'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter, useSearchParams } from 'next/navigation';
import { useQuery } from '@tanstack/react-query';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { api, chaletsApi } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { useSettingsStore } from '@/stores/settingsStore';
import { useContentTranslation } from '@/lib/translate';
import { useSiteSettings } from '@/lib/settings-context';
import { useAuth } from '@/lib/auth-context';
import { toast } from 'sonner';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  Loader2,
  Home,
  Users,
  Bed,
  Bath,
  Wifi,
  Wind,
  UtensilsCrossed,
  Car,
  AlertCircle,
  Calendar,
  ChevronLeft,
  ChevronRight,
  Check,
  Plus,
  Minus,
  ArrowLeft,
} from 'lucide-react';
import Link from 'next/link';

interface BookingUnit {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  description?: string;
  description_ar?: string;
  description_fr?: string;
  capacity: number;
  bedroom_count?: number;
  bathroom_count?: number;
  amenities?: string[];
  images?: string[];
  base_price?: number;
  weekend_price?: number;
  is_active?: boolean;
}

interface AddOn {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  description?: string;
  price: number;
  price_type: 'per_night' | 'one_time';
  is_active: boolean;
}

const amenityIcons: Record<string, React.ElementType> = {
  WiFi: Wifi, wifi: Wifi, AC: Wind, ac: Wind, 'air conditioning': Wind,
  Kitchen: UtensilsCrossed, kitchen: UtensilsCrossed, Parking: Car, parking: Car,
};

export default function DynamicUnitDetailPage() {
  const params = useParams();
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user } = useAuth();
  const t = useTranslations('chalets');
  const tCommon = useTranslations('common');
  const currency = useSettingsStore((s) => s.currency);
  const { translateContent } = useContentTranslation();
  const { modules } = useSiteSettings();

  const slug = Array.isArray(params?.slug) ? params.slug[0] : params?.slug || '';
  const unitId = Array.isArray(params?.unitId) ? params.unitId[0] : params?.unitId || '';
  const moduleIdParam = searchParams.get('module') || undefined;

  const currentModule = modules.find((m) => m.slug.toLowerCase() === slug.toLowerCase());
  const moduleName = currentModule?.name || 'Booking';
  const moduleId = moduleIdParam || currentModule?.id;

  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [checkInDate, setCheckInDate] = useState('');
  const [checkOutDate, setCheckOutDate] = useState('');
  const [numberOfGuests, setNumberOfGuests] = useState(2);
  const [selectedAddOns, setSelectedAddOns] = useState<{ addOnId: string; quantity: number }[]>([]);
  const [customerName, setCustomerName] = useState(user?.fullName || '');
  const [customerEmail, setCustomerEmail] = useState(user?.email || '');
  const [customerPhone, setCustomerPhone] = useState('');
  const [specialRequests, setSpecialRequests] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [blockedDates, setBlockedDates] = useState<string[]>([]);

  // Fetch unit details (uses same chalets API — shared table)
  const { data: unitData, isLoading, error: unitError } = useQuery({
    queryKey: ['chalet', unitId],
    queryFn: () => chaletsApi.getChalet(unitId),
  });

  // Fetch add-ons
  const { data: addOnsData } = useQuery({
    queryKey: ['chalet-addons', moduleId],
    queryFn: () => chaletsApi.getAddOns(moduleId),
    enabled: !!moduleId,
  });

  const unit: BookingUnit | null = unitData?.data?.data || null;
  const addOns: AddOn[] = addOnsData?.data?.data || [];

  useEffect(() => {
    if (user) {
      setCustomerName(user.fullName || '');
      setCustomerEmail(user.email || '');
    }
  }, [user]);

  useEffect(() => {
    if (unit && checkInDate && checkOutDate) {
      fetchAvailability();
    }
  }, [unit, checkInDate, checkOutDate]);

  const fetchAvailability = async () => {
    try {
      const response = await api.get(`/chalets/${unitId}/availability`, {
        params: { startDate: checkInDate, endDate: checkOutDate },
      });
      setBlockedDates(response.data.data?.blockedDates || []);
    } catch (error) {
      console.error('Failed to fetch availability:', error);
    }
  };

  const calculatePricing = () => {
    if (!unit || !checkInDate || !checkOutDate) return null;
    const checkIn = new Date(checkInDate);
    const checkOut = new Date(checkOutDate);
    const nights = Math.ceil((checkOut.getTime() - checkIn.getTime()) / (1000 * 60 * 60 * 24));
    if (nights <= 0) return null;

    let baseAmount = 0;
    const current = new Date(checkIn);
    while (current < checkOut) {
      const dayOfWeek = current.getDay();
      const isWeekend = dayOfWeek === 5 || dayOfWeek === 6;
      baseAmount += isWeekend
        ? (unit.weekend_price || unit.base_price || 0)
        : (unit.base_price || 0);
      current.setDate(current.getDate() + 1);
    }

    let addOnsAmount = 0;
    selectedAddOns.forEach(({ addOnId, quantity }) => {
      const addOn = addOns.find(a => a.id === addOnId);
      if (addOn) {
        addOnsAmount += addOn.price * quantity * (addOn.price_type === 'per_night' ? nights : 1);
      }
    });

    return { nights, baseAmount, addOnsAmount, depositAmount: baseAmount * 0.3, totalAmount: baseAmount + addOnsAmount };
  };

  const pricing = calculatePricing();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!unit || !pricing) { toast.error('Please select valid dates'); return; }
    if (!customerName || !customerEmail || !customerPhone) { toast.error('Please fill in all required fields'); return; }

    setIsSubmitting(true);
    try {
      const response = await api.post('/chalets/bookings', {
        chaletId: unit.id,
        customerName, customerEmail, customerPhone,
        checkInDate, checkOutDate, numberOfGuests,
        addOns: selectedAddOns, specialRequests,
        paymentMethod: 'cash',
      });
      toast.success('Booking submitted successfully!');
      router.push(`/${slug}/confirmation?type=booking&id=${response.data.data.id}`);
    } catch (error: unknown) {
      const axiosError = error as { response?: { data?: { error?: string } } };
      toast.error(axiosError.response?.data?.error || 'Failed to submit booking');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900">
        <Loader2 className="w-8 h-8 animate-spin text-primary-600" />
      </div>
    );
  }

  if (unitError || !unit) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900">
        <div className="text-center">
          <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h2 className="text-xl font-semibold text-slate-900 dark:text-white">Unit not found</h2>
          <Link href={`/${slug}`}>
            <Button className="mt-4">Back to {moduleName}</Button>
          </Link>
        </div>
      </div>
    );
  }

  const images = unit.images && unit.images.length > 0 ? unit.images : [];

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 to-white dark:from-slate-900 dark:to-slate-800">
      {/* Back Button */}
      <div className="max-w-7xl mx-auto px-4 py-4">
        <Link
          href={`/${slug}`}
          className="inline-flex items-center text-slate-600 dark:text-slate-400 hover:text-primary-600 transition-colors"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to {moduleName}
        </Link>
      </div>

      <main className="max-w-7xl mx-auto px-4 pb-16">
        <div className="grid lg:grid-cols-5 gap-8">
          {/* Left Column - Images & Details */}
          <div className="lg:col-span-3 space-y-6">
            {/* Image Gallery */}
            <motion.div
              className="relative rounded-2xl overflow-hidden bg-slate-200 dark:bg-slate-700 aspect-[4/3]"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
            >
              {images.length > 0 ? (
                <>
                  <img src={images[currentImageIndex]} alt={translateContent(unit, 'name')} className="w-full h-full object-cover" />
                  {images.length > 1 && (
                    <>
                      <button onClick={() => setCurrentImageIndex(i => (i - 1 + images.length) % images.length)} className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/80 dark:bg-slate-800/80 rounded-full flex items-center justify-center">
                        <ChevronLeft className="w-6 h-6" />
                      </button>
                      <button onClick={() => setCurrentImageIndex(i => (i + 1) % images.length)} className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/80 dark:bg-slate-800/80 rounded-full flex items-center justify-center">
                        <ChevronRight className="w-6 h-6" />
                      </button>
                      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2">
                        {images.map((_, i) => (
                          <button key={i} onClick={() => setCurrentImageIndex(i)} className={`w-2 h-2 rounded-full transition-colors ${i === currentImageIndex ? 'bg-white' : 'bg-white/50'}`} />
                        ))}
                      </div>
                    </>
                  )}
                </>
              ) : (
                <div className="h-full flex items-center justify-center">
                  <Home className="w-20 h-20 text-slate-400" />
                </div>
              )}
            </motion.div>

            {/* Unit Info */}
            <Card>
              <CardHeader>
                <CardTitle className="text-2xl">{translateContent(unit, 'name')}</CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                {unit.description && (
                  <p className="text-slate-600 dark:text-slate-400">{translateContent(unit, 'description')}</p>
                )}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                    <Users className="w-5 h-5 text-primary-600" />
                    <span>{unit.capacity} Guests</span>
                  </div>
                  {unit.bedroom_count && (
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                      <Bed className="w-5 h-5 text-primary-600" />
                      <span>{unit.bedroom_count} Bedrooms</span>
                    </div>
                  )}
                  {unit.bathroom_count && (
                    <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                      <Bath className="w-5 h-5 text-primary-600" />
                      <span>{unit.bathroom_count} Bathrooms</span>
                    </div>
                  )}
                </div>
                {unit.amenities && unit.amenities.length > 0 && (
                  <div>
                    <h3 className="font-semibold mb-3">Amenities</h3>
                    <div className="flex flex-wrap gap-2">
                      {unit.amenities.map((amenity) => {
                        const Icon = amenityIcons[amenity] || Check;
                        return (
                          <span key={amenity} className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 rounded-full text-sm">
                            <Icon className="w-4 h-4" />
                            {amenity}
                          </span>
                        );
                      })}
                    </div>
                  </div>
                )}
                <div>
                  <h3 className="font-semibold mb-2">Pricing</h3>
                  <div className="flex gap-6">
                    <div>
                      <p className="text-sm text-slate-500">Weekday</p>
                      <p className="text-xl font-bold text-primary-600">{formatCurrency(unit.base_price, currency)}<span className="text-sm font-normal text-slate-500">/night</span></p>
                    </div>
                    {unit.weekend_price && unit.weekend_price !== unit.base_price && (
                      <div>
                        <p className="text-sm text-slate-500">Weekend</p>
                        <p className="text-xl font-bold text-orange-600">{formatCurrency(unit.weekend_price, currency)}<span className="text-sm font-normal text-slate-500">/night</span></p>
                      </div>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Right Column - Booking Form */}
          <div className="lg:col-span-2">
            <div className="sticky top-24">
              <Card>
                <CardHeader className="bg-gradient-to-r from-primary-600 to-primary-500 text-white rounded-t-xl">
                  <CardTitle className="flex items-center gap-2">
                    <Calendar className="w-5 h-5" />
                    Book {translateContent(unit, 'name')}
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-6">
                  <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">Check-in</label>
                        <input type="date" value={checkInDate} onChange={(e) => setCheckInDate(e.target.value)} min={new Date().toISOString().split('T')[0]} className="w-full mt-1 px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white text-sm" required />
                      </div>
                      <div>
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">Check-out</label>
                        <input type="date" value={checkOutDate} onChange={(e) => setCheckOutDate(e.target.value)} min={checkInDate || new Date().toISOString().split('T')[0]} className="w-full mt-1 px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white text-sm" required />
                      </div>
                    </div>

                    <div>
                      <label className="text-sm font-medium text-slate-700 dark:text-slate-300">Guests</label>
                      <div className="flex items-center gap-3 mt-1">
                        <button type="button" onClick={() => setNumberOfGuests(Math.max(1, numberOfGuests - 1))} className="w-8 h-8 rounded-full border flex items-center justify-center"><Minus className="w-4 h-4" /></button>
                        <span className="font-medium w-8 text-center">{numberOfGuests}</span>
                        <button type="button" onClick={() => setNumberOfGuests(Math.min(unit.capacity, numberOfGuests + 1))} className="w-8 h-8 rounded-full border flex items-center justify-center"><Plus className="w-4 h-4" /></button>
                        <span className="text-sm text-slate-500">/ {unit.capacity} max</span>
                      </div>
                    </div>

                    <div className="border-t pt-4 space-y-3">
                      <input type="text" value={customerName} onChange={(e) => setCustomerName(e.target.value)} placeholder="Full Name *" className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-sm" required />
                      <input type="email" value={customerEmail} onChange={(e) => setCustomerEmail(e.target.value)} placeholder="Email *" className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-sm" required />
                      <input type="tel" value={customerPhone} onChange={(e) => setCustomerPhone(e.target.value)} placeholder="Phone Number *" className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-sm" required />
                      <textarea value={specialRequests} onChange={(e) => setSpecialRequests(e.target.value)} placeholder="Special requests (optional)" rows={2} className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-sm resize-none" />
                    </div>

                    {/* Add-Ons */}
                    {addOns.length > 0 && (
                      <div className="border-t pt-4">
                        <h3 className="font-semibold mb-3">Add-Ons</h3>
                        <div className="space-y-2">
                          {addOns.filter(a => a.is_active).map((addOn) => {
                            const selected = selectedAddOns.find(a => a.addOnId === addOn.id);
                            return (
                              <div key={addOn.id} className={`p-3 rounded-lg border transition-all cursor-pointer ${selected ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20' : 'border-slate-200 dark:border-slate-700'}`} onClick={() => {
                                if (selected) setSelectedAddOns(prev => prev.filter(a => a.addOnId !== addOn.id));
                                else setSelectedAddOns(prev => [...prev, { addOnId: addOn.id, quantity: 1 }]);
                              }}>
                                <div className="flex justify-between items-center">
                                  <div>
                                    <p className="font-medium text-sm">{translateContent(addOn, 'name')}</p>
                                    <p className="text-xs text-slate-500">{formatCurrency(addOn.price, currency)} / {addOn.price_type === 'per_night' ? 'night' : 'total'}</p>
                                  </div>
                                  {selected && (
                                    <div className="flex items-center gap-2" onClick={(e) => e.stopPropagation()}>
                                      <button type="button" onClick={() => setSelectedAddOns(prev => prev.map(a => a.addOnId === addOn.id ? { ...a, quantity: Math.max(1, a.quantity - 1) } : a))} className="w-6 h-6 rounded-full border flex items-center justify-center"><Minus className="w-3 h-3" /></button>
                                      <span className="text-sm font-medium">{selected.quantity}</span>
                                      <button type="button" onClick={() => setSelectedAddOns(prev => prev.map(a => a.addOnId === addOn.id ? { ...a, quantity: a.quantity + 1 } : a))} className="w-6 h-6 rounded-full border flex items-center justify-center"><Plus className="w-3 h-3" /></button>
                                    </div>
                                  )}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}

                    {/* Pricing Summary */}
                    {pricing && (
                      <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-4 space-y-2">
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-500">{pricing.nights} night{pricing.nights > 1 ? 's' : ''}</span>
                          <span>{formatCurrency(pricing.baseAmount, currency)}</span>
                        </div>
                        {pricing.addOnsAmount > 0 && (
                          <div className="flex justify-between text-sm">
                            <span className="text-slate-500">Add-ons</span>
                            <span>{formatCurrency(pricing.addOnsAmount, currency)}</span>
                          </div>
                        )}
                        <div className="flex justify-between font-bold pt-2 border-t">
                          <span>Total</span>
                          <span className="text-primary-600">{formatCurrency(pricing.totalAmount, currency)}</span>
                        </div>
                        <p className="text-xs text-slate-500">Deposit: {formatCurrency(pricing.depositAmount, currency)} (30%)</p>
                      </div>
                    )}

                    <Button type="submit" className="w-full" disabled={isSubmitting || !pricing}>
                      {isSubmitting ? (
                        <><Loader2 className="w-4 h-4 animate-spin mr-2" /> Submitting...</>
                      ) : (
                        <>Book Now{pricing ? ` • ${formatCurrency(pricing.totalAmount, currency)}` : ''}</>
                      )}
                    </Button>
                  </form>
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { toast } from 'sonner';
import {
  Palette,
  Upload,
  Eye,
  Save,
  RotateCcw,
  Globe,
  Mail,
  Phone,
  MapPin,
  Image as ImageIcon,
  Type,
  Sparkles,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Label } from '@/components/ui/Label';
import { Textarea } from '@/components/ui/Textarea';
import { Switch } from '@/components/ui/Switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/Card';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/Form';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/Select';
import { Separator } from '@/components/ui/Separator';
import { cn } from '@/lib/utils';
import { api } from '@/lib/api';

const brandingSchema = z.object({
  // Basic Info
  businessName: z.string().min(1, 'Business name is required').max(100),
  tagline: z.string().max(200).optional(),
  description: z.string().max(1000).optional(),
  
  // Contact Info
  email: z.string().email('Invalid email').optional().or(z.literal('')),
  phone: z.string().max(20).optional(),
  address: z.string().max(300).optional(),
  website: z.string().url('Invalid URL').optional().or(z.literal('')),
  
  // Branding
  primaryColor: z.string().regex(/^#[0-9A-Fa-f]{6}$/, 'Invalid color'),
  secondaryColor: z.string().regex(/^#[0-9A-Fa-f]{6}$/, 'Invalid color'),
  accentColor: z.string().regex(/^#[0-9A-Fa-f]{6}$/, 'Invalid color'),
  
  // Typography
  headingFont: z.string().min(1),
  bodyFont: z.string().min(1),
  
  // Features
  showPoweredBy: z.boolean(),
  customDomain: z.string().optional(),
  
  // Social Media
  facebook: z.string().url().optional().or(z.literal('')),
  instagram: z.string().url().optional().or(z.literal('')),
  twitter: z.string().url().optional().or(z.literal('')),
  linkedin: z.string().url().optional().or(z.literal('')),
});

type BrandingFormData = z.infer<typeof brandingSchema>;

const FONT_OPTIONS = [
  { value: 'inter', label: 'Inter' },
  { value: 'roboto', label: 'Roboto' },
  { value: 'open-sans', label: 'Open Sans' },
  { value: 'lato', label: 'Lato' },
  { value: 'poppins', label: 'Poppins' },
  { value: 'montserrat', label: 'Montserrat' },
  { value: 'playfair-display', label: 'Playfair Display' },
  { value: 'merriweather', label: 'Merriweather' },
];

const DEFAULT_COLORS = {
  primary: '#0891b2',
  secondary: '#64748b',
  accent: '#f59e0b',
};

export default function AdminBrandingPage() {
  const t = useTranslations('admin.branding');
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [previewMode, setPreviewMode] = useState(false);
  const [logoUrl, setLogoUrl] = useState<string | null>(null);
  const [faviconUrl, setFaviconUrl] = useState<string | null>(null);
  const [uploadingLogo, setUploadingLogo] = useState(false);
  const [uploadingFavicon, setUploadingFavicon] = useState(false);

  const form = useForm<BrandingFormData>({
    resolver: zodResolver(brandingSchema),
    defaultValues: {
      businessName: '',
      tagline: '',
      description: '',
      email: '',
      phone: '',
      address: '',
      website: '',
      primaryColor: DEFAULT_COLORS.primary,
      secondaryColor: DEFAULT_COLORS.secondary,
      accentColor: DEFAULT_COLORS.accent,
      headingFont: 'inter',
      bodyFont: 'inter',
      showPoweredBy: true,
      customDomain: '',
      facebook: '',
      instagram: '',
      twitter: '',
      linkedin: '',
    },
  });

  // Fetch current branding settings
  const fetchBranding = useCallback(async () => {
    try {
      const response = await api.get('/admin/branding');
      const data = response.data.data;
      
      form.reset({
        businessName: data.businessName || '',
        tagline: data.tagline || '',
        description: data.description || '',
        email: data.email || '',
        phone: data.phone || '',
        address: data.address || '',
        website: data.website || '',
        primaryColor: data.primaryColor || DEFAULT_COLORS.primary,
        secondaryColor: data.secondaryColor || DEFAULT_COLORS.secondary,
        accentColor: data.accentColor || DEFAULT_COLORS.accent,
        headingFont: data.headingFont || 'inter',
        bodyFont: data.bodyFont || 'inter',
        showPoweredBy: data.showPoweredBy ?? true,
        customDomain: data.customDomain || '',
        facebook: data.facebook || '',
        instagram: data.instagram || '',
        twitter: data.twitter || '',
        linkedin: data.linkedin || '',
      });
      
      setLogoUrl(data.logoUrl || null);
      setFaviconUrl(data.faviconUrl || null);
    } catch (error) {
      console.error('Failed to fetch branding:', error);
      toast.error('Failed to load branding settings');
    } finally {
      setIsLoading(false);
    }
  }, [form]);

  useEffect(() => {
    fetchBranding();
  }, [fetchBranding]);

  // Handle logo upload
  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Please upload an image file');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error('Logo must be less than 5MB');
      return;
    }

    setUploadingLogo(true);
    try {
      const formData = new FormData();
      formData.append('logo', file);
      
      const response = await api.post('/admin/branding/logo', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      
      setLogoUrl(response.data.data.url);
      toast.success('Logo uploaded successfully');
    } catch (error) {
      toast.error('Failed to upload logo');
    } finally {
      setUploadingLogo(false);
    }
  };

  // Handle favicon upload
  const handleFaviconUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Please upload an image file');
      return;
    }

    setUploadingFavicon(true);
    try {
      const formData = new FormData();
      formData.append('favicon', file);
      
      const response = await api.post('/admin/branding/favicon', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      
      setFaviconUrl(response.data.data.url);
      toast.success('Favicon uploaded successfully');
    } catch (error) {
      toast.error('Failed to upload favicon');
    } finally {
      setUploadingFavicon(false);
    }
  };

  // Save branding settings
  const onSubmit = async (data: BrandingFormData) => {
    setIsSaving(true);
    try {
      await api.put('/admin/branding', {
        ...data,
        logoUrl,
        faviconUrl,
      });
      
      toast.success('Branding settings saved successfully');
    } catch (error) {
      toast.error('Failed to save branding settings');
    } finally {
      setIsSaving(false);
    }
  };

  // Reset to defaults
  const handleReset = () => {
    form.reset({
      ...form.getValues(),
      primaryColor: DEFAULT_COLORS.primary,
      secondaryColor: DEFAULT_COLORS.secondary,
      accentColor: DEFAULT_COLORS.accent,
      headingFont: 'inter',
      bodyFont: 'inter',
    });
    toast.info('Colors and fonts reset to defaults');
  };

  const watchedColors = form.watch(['primaryColor', 'secondaryColor', 'accentColor']);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8 max-w-5xl">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold">Branding & White Label</h1>
          <p className="text-muted-foreground mt-1">
            Customize the look and feel of your platform management system
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={() => setPreviewMode(!previewMode)}
          >
            <Eye className="mr-2 h-4 w-4" />
            {previewMode ? 'Exit Preview' : 'Preview'}
          </Button>
          <Button variant="outline" onClick={handleReset}>
            <RotateCcw className="mr-2 h-4 w-4" />
            Reset Colors
          </Button>
        </div>
      </div>

      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8">
          <Tabs defaultValue="identity" className="w-full">
            <TabsList className="grid w-full grid-cols-4">
              <TabsTrigger value="identity">Identity</TabsTrigger>
              <TabsTrigger value="colors">Colors & Fonts</TabsTrigger>
              <TabsTrigger value="contact">Contact Info</TabsTrigger>
              <TabsTrigger value="advanced">Advanced</TabsTrigger>
            </TabsList>

            <TabsContent value="identity" className="space-y-6">
              {/* Logo & Favicon */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <ImageIcon className="h-5 w-5" />
                    Logo & Favicon
                  </CardTitle>
                  <CardDescription>
                    Upload your brand logo and favicon
                  </CardDescription>
                </CardHeader>
                <CardContent className="grid md:grid-cols-2 gap-6">
                  {/* Logo Upload */}
                  <div className="space-y-4">
                    <Label>Logo</Label>
                    <div className="border-2 border-dashed rounded-lg p-6 text-center">
                      {logoUrl ? (
                        <div className="space-y-4">
                          <img
                            src={logoUrl}
                            alt="Logo"
                            className="max-h-24 mx-auto object-contain"
                          />
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={() => document.getElementById('logo-upload')?.click()}
                            disabled={uploadingLogo}
                          >
                            {uploadingLogo ? 'Uploading...' : 'Change Logo'}
                          </Button>
                        </div>
                      ) : (
                        <div
                          className="cursor-pointer"
                          onClick={() => document.getElementById('logo-upload')?.click()}
                        >
                          <Upload className="h-10 w-10 mx-auto text-muted-foreground" />
                          <p className="mt-2 text-sm text-muted-foreground">
                            Click to upload logo
                          </p>
                          <p className="text-xs text-muted-foreground">
                            PNG, JPG up to 5MB
                          </p>
                        </div>
                      )}
                      <input
                        id="logo-upload"
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={handleLogoUpload}
                      />
                    </div>
                  </div>

                  {/* Favicon Upload */}
                  <div className="space-y-4">
                    <Label>Favicon</Label>
                    <div className="border-2 border-dashed rounded-lg p-6 text-center">
                      {faviconUrl ? (
                        <div className="space-y-4">
                          <img
                            src={faviconUrl}
                            alt="Favicon"
                            className="h-16 w-16 mx-auto object-contain"
                          />
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={() => document.getElementById('favicon-upload')?.click()}
                            disabled={uploadingFavicon}
                          >
                            {uploadingFavicon ? 'Uploading...' : 'Change Favicon'}
                          </Button>
                        </div>
                      ) : (
                        <div
                          className="cursor-pointer"
                          onClick={() => document.getElementById('favicon-upload')?.click()}
                        >
                          <Sparkles className="h-10 w-10 mx-auto text-muted-foreground" />
                          <p className="mt-2 text-sm text-muted-foreground">
                            Click to upload favicon
                          </p>
                          <p className="text-xs text-muted-foreground">
                            32x32 or 64x64 PNG
                          </p>
                        </div>
                      )}
                      <input
                        id="favicon-upload"
                        type="file"
                        accept="image/png,image/x-icon"
                        className="hidden"
                        onChange={handleFaviconUpload}
                      />
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Business Info */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Type className="h-5 w-5" />
                    Business Information
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <FormField
                    control={form.control}
                    name="businessName"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Business Name *</FormLabel>
                        <FormControl>
                          <Input placeholder="Your Resort Name" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="tagline"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Tagline</FormLabel>
                        <FormControl>
                          <Input placeholder="Your perfect getaway awaits" {...field} />
                        </FormControl>
                        <FormDescription>
                          A short slogan shown in headers and emails
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="description"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Description</FormLabel>
                        <FormControl>
                          <Textarea
                            placeholder="Brief description of your resort..."
                            rows={3}
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="colors" className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Palette className="h-5 w-5" />
                    Brand Colors
                  </CardTitle>
                  <CardDescription>
                    Choose colors that match your brand identity
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                  <div className="grid md:grid-cols-3 gap-6">
                    <FormField
                      control={form.control}
                      name="primaryColor"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Primary Color</FormLabel>
                          <div className="flex gap-2">
                            <div
                              className="w-10 h-10 rounded-md border cursor-pointer"
                              style={{ backgroundColor: field.value }}
                              onClick={() => document.getElementById('primary-color')?.click()}
                            />
                            <FormControl>
                              <Input {...field} className="font-mono" />
                            </FormControl>
                            <input
                              id="primary-color"
                              type="color"
                              value={field.value}
                              onChange={(e) => field.onChange(e.target.value)}
                              className="sr-only"
                            />
                          </div>
                          <FormDescription>
                            Main brand color for buttons and links
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="secondaryColor"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Secondary Color</FormLabel>
                          <div className="flex gap-2">
                            <div
                              className="w-10 h-10 rounded-md border cursor-pointer"
                              style={{ backgroundColor: field.value }}
                              onClick={() => document.getElementById('secondary-color')?.click()}
                            />
                            <FormControl>
                              <Input {...field} className="font-mono" />
                            </FormControl>
                            <input
                              id="secondary-color"
                              type="color"
                              value={field.value}
                              onChange={(e) => field.onChange(e.target.value)}
                              className="sr-only"
                            />
                          </div>
                          <FormDescription>
                            Used for secondary elements
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="accentColor"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Accent Color</FormLabel>
                          <div className="flex gap-2">
                            <div
                              className="w-10 h-10 rounded-md border cursor-pointer"
                              style={{ backgroundColor: field.value }}
                              onClick={() => document.getElementById('accent-color')?.click()}
                            />
                            <FormControl>
                              <Input {...field} className="font-mono" />
                            </FormControl>
                            <input
                              id="accent-color"
                              type="color"
                              value={field.value}
                              onChange={(e) => field.onChange(e.target.value)}
                              className="sr-only"
                            />
                          </div>
                          <FormDescription>
                            Highlights and notifications
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>

                  {/* Color Preview */}
                  <Separator />
                  <div>
                    <Label className="mb-3 block">Preview</Label>
                    <div className="p-4 border rounded-lg space-y-4">
                      <div className="flex gap-2">
                        <Button
                          type="button"
                          style={{ backgroundColor: watchedColors[0] }}
                        >
                          Primary Button
                        </Button>
                        <Button
                          type="button"
                          variant="outline"
                          style={{
                            borderColor: watchedColors[1],
                            color: watchedColors[1],
                          }}
                        >
                          Secondary Button
                        </Button>
                        <div
                          className="px-3 py-2 rounded text-white text-sm"
                          style={{ backgroundColor: watchedColors[2] }}
                        >
                          Accent Badge
                        </div>
                      </div>
                      <div
                        className="h-2 rounded-full"
                        style={{
                          background: `linear-gradient(to right, ${watchedColors[0]}, ${watchedColors[1]}, ${watchedColors[2]})`,
                        }}
                      />
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Typography */}
              <Card>
                <CardHeader>
                  <CardTitle>Typography</CardTitle>
                  <CardDescription>
                    Choose fonts for headings and body text
                  </CardDescription>
                </CardHeader>
                <CardContent className="grid md:grid-cols-2 gap-6">
                  <FormField
                    control={form.control}
                    name="headingFont"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Heading Font</FormLabel>
                        <Select onValueChange={field.onChange} value={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {FONT_OPTIONS.map((font) => (
                              <SelectItem key={font.value} value={font.value}>
                                {font.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="bodyFont"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Body Font</FormLabel>
                        <Select onValueChange={field.onChange} value={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {FONT_OPTIONS.map((font) => (
                              <SelectItem key={font.value} value={font.value}>
                                {font.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="contact" className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Mail className="h-5 w-5" />
                    Contact Information
                  </CardTitle>
                  <CardDescription>
                    Information displayed in emails and footer
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="grid md:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="email"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Email</FormLabel>
                          <FormControl>
                            <Input
                              type="email"
                              placeholder="contact@resort.com"
                              {...field}
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="phone"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Phone</FormLabel>
                          <FormControl>
                            <Input placeholder="+1 234 567 8900" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>

                  <FormField
                    control={form.control}
                    name="address"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Address</FormLabel>
                        <FormControl>
                          <Textarea
                            placeholder="123 Resort Way, Beach City, BC 12345"
                            rows={2}
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="website"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Website</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="https://www.yourresort.com"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </CardContent>
              </Card>

              {/* Social Media */}
              <Card>
                <CardHeader>
                  <CardTitle>Social Media</CardTitle>
                </CardHeader>
                <CardContent className="grid md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="facebook"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Facebook</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="https://facebook.com/yourresort"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="instagram"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Instagram</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="https://instagram.com/yourresort"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="twitter"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Twitter / X</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="https://twitter.com/yourresort"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="linkedin"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>LinkedIn</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="https://linkedin.com/company/yourresort"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="advanced" className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Globe className="h-5 w-5" />
                    White Label Settings
                  </CardTitle>
                  <CardDescription>
                    Advanced customization options
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                  <FormField
                    control={form.control}
                    name="showPoweredBy"
                    render={({ field }) => (
                      <FormItem className="flex items-center justify-between rounded-lg border p-4">
                        <div className="space-y-0.5">
                          <FormLabel className="text-base">
                            Show "Powered By" Footer
                          </FormLabel>
                          <FormDescription>
                            Display Iron Paradise Gym attribution in the footer
                          </FormDescription>
                        </div>
                        <FormControl>
                          <Switch
                            checked={field.value}
                            onCheckedChange={field.onChange}
                          />
                        </FormControl>
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="customDomain"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Custom Domain</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="booking.yourresort.com"
                            {...field}
                          />
                        </FormControl>
                        <FormDescription>
                          Contact support to configure a custom domain
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </CardContent>
              </Card>
            </TabsContent>
          </Tabs>

          {/* Save Button */}
          <div className="flex justify-end gap-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => form.reset()}
            >
              Discard Changes
            </Button>
            <Button type="submit" disabled={isSaving}>
              {isSaving ? (
                <>
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
                  Saving...
                </>
              ) : (
                <>
                  <Save className="mr-2 h-4 w-4" />
                  Save Changes
                </>
              )}
            </Button>
          </div>
        </form>
      </Form>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { toast } from 'sonner';
import { Mail, Send, CheckCircle, XCircle, Loader2, Eye, EyeOff } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Label } from '@/components/ui/Label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/Select';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/Form';
import { useTranslations } from 'next-intl';
import { api } from '@/lib/api';

// Validation schema
const emailConfigSchema = z.object({
  provider: z.enum(['smtp', 'sendgrid', 'ses', 'mailgun', 'postmark']),
  smtpHost: z.string().optional(),
  smtpPort: z.number().min(1).max(65535).optional(),
  smtpSecure: z.boolean().optional(),
  smtpUser: z.string().optional(),
  smtpPassword: z.string().optional(),
  apiKey: z.string().optional(),
  fromEmail: z.string().email('Valid email required'),
  fromName: z.string().min(1, 'Sender name required'),
  replyToEmail: z.string().email().optional().or(z.literal('')),
}).superRefine((data, ctx) => {
  if (data.provider === 'smtp') {
    if (!data.smtpHost) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'SMTP host is required',
        path: ['smtpHost'],
      });
    }
    if (!data.smtpPort) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'SMTP port is required',
        path: ['smtpPort'],
      });
    }
  } else {
    if (!data.apiKey) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'API key is required for this provider',
        path: ['apiKey'],
      });
    }
  }
});

type EmailConfig = z.infer<typeof emailConfigSchema>;

interface TestResult {
  success: boolean;
  message: string;
  timestamp: Date;
}

export default function EmailConfigurationPage() {
  const t = useTranslations('admin.settings');
  const [isLoading, setIsLoading] = useState(false);
  const [isTesting, setIsTesting] = useState(false);
  const [testResult, setTestResult] = useState<TestResult | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [showApiKey, setShowApiKey] = useState(false);

  const form = useForm<EmailConfig>({
    resolver: zodResolver(emailConfigSchema),
    defaultValues: {
      provider: 'smtp',
      smtpHost: '',
      smtpPort: 587,
      smtpSecure: true,
      smtpUser: '',
      smtpPassword: '',
      apiKey: '',
      fromEmail: '',
      fromName: 'Iron Paradise Gym',
      replyToEmail: '',
    },
  });

  const provider = form.watch('provider');

  const onSubmit = async (data: EmailConfig) => {
    setIsLoading(true);
    try {
      await api.put('/admin/settings/email', data);
      toast.success('Email configuration saved successfully');
    } catch (error: any) {
      toast.error(error.message || 'Failed to save email configuration');
    } finally {
      setIsLoading(false);
    }
  };

  const handleTestEmail = async () => {
    const values = form.getValues();
    const validation = emailConfigSchema.safeParse(values);
    
    if (!validation.success) {
      toast.error('Please fill in all required fields before testing');
      return;
    }

    setIsTesting(true);
    setTestResult(null);

    try {
      const response = await api.post('/admin/settings/email/test', {
        ...values,
        testRecipient: values.fromEmail, // Send test to configured from address
      });

      setTestResult({
        success: true,
        message: 'Test email sent successfully! Check your inbox.',
        timestamp: new Date(),
      });
      toast.success('Test email sent successfully');
    } catch (error: any) {
      setTestResult({
        success: false,
        message: error.message || 'Failed to send test email',
        timestamp: new Date(),
      });
      toast.error('Failed to send test email');
    } finally {
      setIsTesting(false);
    }
  };

  return (
    <div className="container mx-auto py-8 max-w-4xl">
      <div className="mb-8">
        <h1 className="text-3xl font-bold flex items-center gap-3">
          <Mail className="h-8 w-8" />
          Email Configuration
        </h1>
        <p className="text-muted-foreground mt-2">
          Configure your email service provider for sending transactional emails.
        </p>
      </div>

      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
          {/* Provider Selection */}
          <Card>
            <CardHeader>
              <CardTitle>Email Provider</CardTitle>
              <CardDescription>
                Select your email service provider
              </CardDescription>
            </CardHeader>
            <CardContent>
              <FormField
                control={form.control}
                name="provider"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Provider</FormLabel>
                    <Select
                      onValueChange={field.onChange}
                      defaultValue={field.value}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select a provider" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="smtp">SMTP Server</SelectItem>
                        <SelectItem value="sendgrid">SendGrid</SelectItem>
                        <SelectItem value="ses">Amazon SES</SelectItem>
                        <SelectItem value="mailgun">Mailgun</SelectItem>
                        <SelectItem value="postmark">Postmark</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormDescription>
                      Choose how emails will be sent from the system
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </CardContent>
          </Card>

          {/* SMTP Configuration */}
          {provider === 'smtp' && (
            <Card>
              <CardHeader>
                <CardTitle>SMTP Settings</CardTitle>
                <CardDescription>
                  Configure your SMTP server connection
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="smtpHost"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>SMTP Host</FormLabel>
                        <FormControl>
                          <Input placeholder="smtp.example.com" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="smtpPort"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>SMTP Port</FormLabel>
                        <FormControl>
                          <Input
                            type="number"
                            placeholder="587"
                            {...field}
                            onChange={(e) => field.onChange(parseInt(e.target.value))}
                          />
                        </FormControl>
                        <FormDescription>Common: 587 (TLS), 465 (SSL), 25</FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <FormField
                  control={form.control}
                  name="smtpUser"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>SMTP Username</FormLabel>
                      <FormControl>
                        <Input placeholder="your-username" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="smtpPassword"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>SMTP Password</FormLabel>
                      <FormControl>
                        <div className="relative">
                          <Input
                            type={showPassword ? 'text' : 'password'}
                            placeholder="••••••••"
                            {...field}
                          />
                          <Button
                            type="button"
                            variant="ghost"
                            size="sm"
                            className="absolute right-0 top-0 h-full px-3"
                            onClick={() => setShowPassword(!showPassword)}
                          >
                            {showPassword ? (
                              <EyeOff className="h-4 w-4" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </Button>
                        </div>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>
          )}

          {/* API Key Configuration for other providers */}
          {provider !== 'smtp' && (
            <Card>
              <CardHeader>
                <CardTitle>{provider.charAt(0).toUpperCase() + provider.slice(1)} Settings</CardTitle>
                <CardDescription>
                  Enter your {provider} API credentials
                </CardDescription>
              </CardHeader>
              <CardContent>
                <FormField
                  control={form.control}
                  name="apiKey"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>API Key</FormLabel>
                      <FormControl>
                        <div className="relative">
                          <Input
                            type={showApiKey ? 'text' : 'password'}
                            placeholder="Enter your API key"
                            {...field}
                          />
                          <Button
                            type="button"
                            variant="ghost"
                            size="sm"
                            className="absolute right-0 top-0 h-full px-3"
                            onClick={() => setShowApiKey(!showApiKey)}
                          >
                            {showApiKey ? (
                              <EyeOff className="h-4 w-4" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </Button>
                        </div>
                      </FormControl>
                      <FormDescription>
                        Your {provider} API key for authentication
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>
          )}

          {/* Sender Information */}
          <Card>
            <CardHeader>
              <CardTitle>Sender Information</CardTitle>
              <CardDescription>
                Configure how emails appear to recipients
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <FormField
                  control={form.control}
                  name="fromEmail"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>From Email</FormLabel>
                      <FormControl>
                        <Input
                          type="email"
                          placeholder="noreply@resort.com"
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="fromName"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>From Name</FormLabel>
                      <FormControl>
                        <Input placeholder="Iron Paradise Gym" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

              <FormField
                control={form.control}
                name="replyToEmail"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Reply-To Email (Optional)</FormLabel>
                    <FormControl>
                      <Input
                        type="email"
                        placeholder="support@resort.com"
                        {...field}
                      />
                    </FormControl>
                    <FormDescription>
                      Where replies should be sent (if different from From address)
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </CardContent>
          </Card>

          {/* Test Result */}
          {testResult && (
            <Card className={testResult.success ? 'border-green-500' : 'border-red-500'}>
              <CardContent className="pt-6">
                <div className="flex items-center gap-3">
                  {testResult.success ? (
                    <CheckCircle className="h-6 w-6 text-green-500" />
                  ) : (
                    <XCircle className="h-6 w-6 text-red-500" />
                  )}
                  <div>
                    <p className="font-medium">
                      {testResult.success ? 'Test Successful' : 'Test Failed'}
                    </p>
                    <p className="text-sm text-muted-foreground">{testResult.message}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Action Buttons */}
          <div className="flex gap-4 justify-end">
            <Button
              type="button"
              variant="outline"
              onClick={handleTestEmail}
              disabled={isTesting || isLoading}
            >
              {isTesting ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : (
                <Send className="h-4 w-4 mr-2" />
              )}
              Send Test Email
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : null}
              Save Configuration
            </Button>
          </div>
        </form>
      </Form>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { toast } from 'sonner';
import {
  Plus,
  Pencil,
  Trash2,
  Calendar,
  Percent,
  DollarSign,
  TrendingUp,
  TrendingDown,
  Settings,
  HelpCircle,
  Save,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Label } from '@/components/ui/Label';
import { Switch } from '@/components/ui/Switch';
import { Badge } from '@/components/ui/Badge';
import { Slider } from '@/components/ui/Slider';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/Card';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/Dialog';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/Form';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/Select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/Table';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/Tooltip';
import { Checkbox } from '@/components/ui/Checkbox';
import { Separator } from '@/components/ui/Separator';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs';
import { api } from '@/lib/api';
import { cn } from '@/lib/utils';

const seasonalRuleSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100),
  startDate: z.string().regex(/^\d{2}-\d{2}$/, 'Use MM-DD format'),
  endDate: z.string().regex(/^\d{2}-\d{2}$/, 'Use MM-DD format'),
  priceMultiplier: z.number().min(0.1).max(3),
  applicableTo: z.array(z.string()).min(1, 'Select at least one category'),
  priority: z.number().min(0).max(100),
  isActive: z.boolean(),
});

type SeasonalRuleFormData = z.infer<typeof seasonalRuleSchema>;

interface SeasonalRule {
  id: string;
  name: string;
  startDate: string;
  endDate: string;
  priceMultiplier: number;
  applicableTo: string[];
  priority: number;
  isActive: boolean;
}

interface DynamicPricingConfig {
  enabled: boolean;
  minOccupancyThreshold: number;
  maxOccupancyThreshold: number;
  minPriceMultiplier: number;
  maxPriceMultiplier: number;
  advanceBookingDays: number;
  earlyBirdDiscount: number;
  lastMinuteDays: number;
  lastMinutePremium: number;
}

const CATEGORIES = [
  { value: 'chalets', label: 'Chalets' },
  { value: 'pool', label: 'Pool' },
  { value: 'restaurant', label: 'Restaurant' },
];

const MONTHS = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];

export default function SeasonalPricingPage() {
  const t = useTranslations('admin.pricing');
  const [isLoading, setIsLoading] = useState(true);
  const [rules, setRules] = useState<SeasonalRule[]>([]);
  const [dynamicConfig, setDynamicConfig] = useState<DynamicPricingConfig>({
    enabled: false,
    minOccupancyThreshold: 30,
    maxOccupancyThreshold: 80,
    minPriceMultiplier: 0.85,
    maxPriceMultiplier: 1.25,
    advanceBookingDays: 30,
    earlyBirdDiscount: 0.1,
    lastMinuteDays: 3,
    lastMinutePremium: 0,
  });
  const [editingRule, setEditingRule] = useState<SeasonalRule | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isSavingDynamic, setIsSavingDynamic] = useState(false);

  const form = useForm<SeasonalRuleFormData>({
    resolver: zodResolver(seasonalRuleSchema),
    defaultValues: {
      name: '',
      startDate: '',
      endDate: '',
      priceMultiplier: 1,
      applicableTo: ['chalets'],
      priority: 5,
      isActive: true,
    },
  });

  // Fetch data
  const fetchData = useCallback(async () => {
    try {
      const [rulesRes, configRes] = await Promise.all([
        api.get('/admin/pricing/seasonal-rules'),
        api.get('/admin/pricing/dynamic-config'),
      ]);
      setRules(rulesRes.data.data);
      setDynamicConfig(configRes.data.data);
    } catch (error) {
      console.error('Failed to fetch pricing data:', error);
      toast.error('Failed to load pricing settings');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Handle rule submission
  const onSubmitRule = async (data: SeasonalRuleFormData) => {
    try {
      if (editingRule) {
        await api.put(`/admin/pricing/seasonal-rules/${editingRule.id}`, data);
        toast.success('Rule updated successfully');
      } else {
        await api.post('/admin/pricing/seasonal-rules', data);
        toast.success('Rule created successfully');
      }
      setIsDialogOpen(false);
      setEditingRule(null);
      form.reset();
      fetchData();
    } catch (error) {
      toast.error('Failed to save rule');
    }
  };

  // Handle rule deletion
  const handleDeleteRule = async (ruleId: string) => {
    if (!confirm('Are you sure you want to delete this rule?')) return;

    try {
      await api.delete(`/admin/pricing/seasonal-rules/${ruleId}`);
      toast.success('Rule deleted successfully');
      fetchData();
    } catch (error) {
      toast.error('Failed to delete rule');
    }
  };

  // Handle edit
  const handleEditRule = (rule: SeasonalRule) => {
    setEditingRule(rule);
    form.reset({
      name: rule.name,
      startDate: rule.startDate,
      endDate: rule.endDate,
      priceMultiplier: rule.priceMultiplier,
      applicableTo: rule.applicableTo,
      priority: rule.priority,
      isActive: rule.isActive,
    });
    setIsDialogOpen(true);
  };

  // Save dynamic pricing config
  const handleSaveDynamicConfig = async () => {
    setIsSavingDynamic(true);
    try {
      await api.put('/admin/pricing/dynamic-config', dynamicConfig);
      toast.success('Dynamic pricing settings saved');
    } catch (error) {
      toast.error('Failed to save dynamic pricing settings');
    } finally {
      setIsSavingDynamic(false);
    }
  };

  // Get month label from MM-DD
  const getDateLabel = (date: string) => {
    const [month, day] = date.split('-').map(Number);
    return `${MONTHS[month - 1]} ${day}`;
  };

  // Get multiplier badge color
  const getMultiplierColor = (multiplier: number) => {
    if (multiplier > 1) return 'bg-red-100 text-red-700';
    if (multiplier < 1) return 'bg-green-100 text-green-700';
    return 'bg-gray-100 text-gray-700';
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8 max-w-6xl">
      <div className="mb-8">
        <h1 className="text-3xl font-bold">Seasonal & Dynamic Pricing</h1>
        <p className="text-muted-foreground mt-1">
          Configure seasonal rates and dynamic pricing rules
        </p>
      </div>

      <Tabs defaultValue="seasonal" className="space-y-6">
        <TabsList>
          <TabsTrigger value="seasonal" className="flex items-center gap-2">
            <Calendar className="h-4 w-4" />
            Seasonal Rules
          </TabsTrigger>
          <TabsTrigger value="dynamic" className="flex items-center gap-2">
            <TrendingUp className="h-4 w-4" />
            Dynamic Pricing
          </TabsTrigger>
        </TabsList>

        {/* Seasonal Rules Tab */}
        <TabsContent value="seasonal" className="space-y-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>Seasonal Pricing Rules</CardTitle>
                <CardDescription>
                  Define price adjustments for specific date ranges
                </CardDescription>
              </div>
              <Dialog open={isDialogOpen} onOpenChange={(open) => {
                setIsDialogOpen(open);
                if (!open) {
                  setEditingRule(null);
                  form.reset();
                }
              }}>
                <DialogTrigger asChild>
                  <Button>
                    <Plus className="mr-2 h-4 w-4" />
                    Add Rule
                  </Button>
                </DialogTrigger>
                <DialogContent className="max-w-md">
                  <DialogHeader>
                    <DialogTitle>
                      {editingRule ? 'Edit Rule' : 'Add Seasonal Rule'}
                    </DialogTitle>
                    <DialogDescription>
                      Configure a price adjustment for a specific period
                    </DialogDescription>
                  </DialogHeader>
                  <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmitRule)} className="space-y-4">
                      <FormField
                        control={form.control}
                        name="name"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Rule Name</FormLabel>
                            <FormControl>
                              <Input placeholder="Summer Peak Season" {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <div className="grid grid-cols-2 gap-4">
                        <FormField
                          control={form.control}
                          name="startDate"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Start Date (MM-DD)</FormLabel>
                              <FormControl>
                                <Input placeholder="07-01" {...field} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="endDate"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>End Date (MM-DD)</FormLabel>
                              <FormControl>
                                <Input placeholder="08-31" {...field} />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>

                      <FormField
                        control={form.control}
                        name="priceMultiplier"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>
                              Price Multiplier: {field.value}x
                              {field.value > 1 && (
                                <span className="text-red-500 ml-2">
                                  (+{Math.round((field.value - 1) * 100)}%)
                                </span>
                              )}
                              {field.value < 1 && (
                                <span className="text-green-500 ml-2">
                                  ({Math.round((field.value - 1) * 100)}%)
                                </span>
                              )}
                            </FormLabel>
                            <FormControl>
                              <Slider
                                min={0.5}
                                max={2}
                                step={0.05}
                                value={[field.value]}
                                onValueChange={([value]) => field.onChange(value)}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="applicableTo"
                        render={() => (
                          <FormItem>
                            <FormLabel>Apply To</FormLabel>
                            <div className="flex flex-wrap gap-2">
                              {CATEGORIES.map((category) => (
                                <FormField
                                  key={category.value}
                                  control={form.control}
                                  name="applicableTo"
                                  render={({ field }) => (
                                    <FormItem className="flex items-center space-x-2">
                                      <FormControl>
                                        <Checkbox
                                          checked={field.value?.includes(category.value)}
                                          onCheckedChange={(checked) => {
                                            return checked
                                              ? field.onChange([...field.value, category.value])
                                              : field.onChange(
                                                  field.value?.filter(
                                                    (value) => value !== category.value
                                                  )
                                                );
                                          }}
                                        />
                                      </FormControl>
                                      <FormLabel className="font-normal">
                                        {category.label}
                                      </FormLabel>
                                    </FormItem>
                                  )}
                                />
                              ))}
                            </div>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <div className="grid grid-cols-2 gap-4">
                        <FormField
                          control={form.control}
                          name="priority"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Priority</FormLabel>
                              <FormControl>
                                <Input
                                  type="number"
                                  min={0}
                                  max={100}
                                  {...field}
                                  onChange={(e) => field.onChange(parseInt(e.target.value))}
                                />
                              </FormControl>
                              <FormDescription>
                                Higher priority rules override lower
                              </FormDescription>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="isActive"
                          render={({ field }) => (
                            <FormItem className="flex flex-col">
                              <FormLabel>Active</FormLabel>
                              <FormControl>
                                <Switch
                                  checked={field.value}
                                  onCheckedChange={field.onChange}
                                />
                              </FormControl>
                            </FormItem>
                          )}
                        />
                      </div>

                      <DialogFooter>
                        <Button type="submit">
                          {editingRule ? 'Update Rule' : 'Create Rule'}
                        </Button>
                      </DialogFooter>
                    </form>
                  </Form>
                </DialogContent>
              </Dialog>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Period</TableHead>
                    <TableHead>Adjustment</TableHead>
                    <TableHead>Applies To</TableHead>
                    <TableHead>Priority</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="w-[100px]">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {rules.map((rule) => (
                    <TableRow key={rule.id}>
                      <TableCell className="font-medium">{rule.name}</TableCell>
                      <TableCell>
                        {getDateLabel(rule.startDate)} - {getDateLabel(rule.endDate)}
                      </TableCell>
                      <TableCell>
                        <Badge className={getMultiplierColor(rule.priceMultiplier)}>
                          {rule.priceMultiplier > 1 ? (
                            <TrendingUp className="h-3 w-3 mr-1" />
                          ) : rule.priceMultiplier < 1 ? (
                            <TrendingDown className="h-3 w-3 mr-1" />
                          ) : null}
                          {rule.priceMultiplier}x
                          {rule.priceMultiplier !== 1 && (
                            <span className="ml-1">
                              ({rule.priceMultiplier > 1 ? '+' : ''}
                              {Math.round((rule.priceMultiplier - 1) * 100)}%)
                            </span>
                          )}
