export default function ModuleCartPage() {
  const t = useTranslations('common');
  const router = useRouter();
  const params = useParams();
  const rawSlug = params?.slug;
  const slug = Array.isArray(rawSlug) ? rawSlug[0] : rawSlug;

  const { modules, loading: modulesLoading, settings } = useSiteSettings();
  
  const normalizedSlug = slug ? decodeURIComponent(slug).toLowerCase() : '';
  const currentModule = modules.find((m) => m.slug.toLowerCase() === normalizedSlug);
  const moduleId = currentModule?.id;

  const currency = useSettingsStore((s) => s.currency);

  const [isHydrated, setIsHydrated] = useState(false);
  useEffect(() => {
    setIsHydrated(true);
  }, []);

  const items = useCartStore((s) => s.items);
  const moduleItems = moduleId ? items.filter(i => i.moduleId === moduleId) : [];
  
  const addItem = useCartStore((s) => s.addItem);
  const removeItem = useCartStore((s) => s.removeItem);

  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [orderType, setOrderType] = useState<'dine_in' | 'takeaway' | 'delivery'>('dine_in');
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card'>('cash');
  const [notes, setNotes] = useState('');
  const [activeStep, setActiveStep] = useState(1);

  // Discount tracking state
  interface AppliedDiscount {
    type: 'coupon' | 'giftcard' | 'loyalty';
    code?: string;
    amount: number;
    details?: string;
  }
  const [appliedDiscounts, setAppliedDiscounts] = useState<AppliedDiscount[]>([]);
  const [finalTotal, setFinalTotal] = useState(0);

  // Stripe payment state
  const [showStripePayment, setShowStripePayment] = useState(false);
  const [pendingOrderId, setPendingOrderId] = useState<string | null>(null);

  const subtotal = moduleItems.reduce((sum, item) => sum + item.price * item.quantity, 0);
  // FIX: Iteration 4 - Use dynamic tax rate from settings instead of hardcoded 0.11
  const taxRate = settings.taxRate || 0.11;
  const tax = subtotal * taxRate;
  // Phase 2: Add service charge + delivery fee to match restaurant cart parity
  const serviceChargeRate = settings.serviceChargeRate ?? 0.10;
  const serviceCharge = orderType === 'dine_in' ? subtotal * serviceChargeRate : 0;
  const deliveryFee = orderType === 'delivery' ? (settings.deliveryFee ?? 5) : 0;
  const preDiscountTotal = subtotal + tax + serviceCharge + deliveryFee;
  const totalDiscount = appliedDiscounts.reduce((sum, d) => sum + d.amount, 0);
  const total = Math.max(0, preDiscountTotal - totalDiscount);

  // Update final total when discounts change
  useEffect(() => {
    setFinalTotal(total);
  }, [total]);

  interface OrderData {
    customerName: string;
    customerPhone: string;
    tableNumber?: string;
    orderType: 'dine_in' | 'takeaway' | 'delivery';
    paymentMethod: 'cash' | 'card';
    notes?: string;
    items: Array<{ menuItemId: string; quantity: number; specialInstructions?: string }>;
    moduleId?: string;
    // Discount integration fields
    couponCode?: string;
    giftCardRedemptions?: Array<{ code: string; amount: number }>;
    loyaltyPointsToRedeem?: number;
    loyaltyPointsDollarValue?: number;
  }

  interface MutationError {
    response?: { data?: { error?: string } };
    message?: string;
  }

  const orderMutation = useMutation({
    mutationFn: (data: OrderData) => restaurantApi.createOrder(data),
    onSuccess: (response) => {
      const order = response?.data?.data;
      const orderId = order?.id || order?.order_id || '';

      // For card payments, show Stripe checkout instead of redirecting
      if (paymentMethod === 'card' && total > 0) {
        setPendingOrderId(orderId);
        setShowStripePayment(true);
        toast.info('Complete your card payment');
      } else {
        // For cash payments or zero total, redirect directly
        moduleItems.forEach(item => removeItem(item.id));
        toast.success(t('orderPlaced') || 'Order placed successfully!');
        router.push(`/${slug}/confirmation?type=order&id=${orderId}`);
      }
    },
    onError: (err: MutationError) => {
      toast.error(err.response?.data?.error || t('orderFailed') || 'Failed to place order');
    },
  });

  // Stripe payment handlers
  const handleStripePaymentSuccess = () => {
    moduleItems.forEach(item => removeItem(item.id));
    toast.success(t('orderPlaced') || 'Order placed successfully!');
    router.push(`/${slug}/confirmation?type=order&id=${pendingOrderId}`);
  };

  const handleStripePaymentError = (error: string) => {
    toast.error(`Payment failed: ${error}`);
  };

  const handleStripePaymentCancel = () => {
    setShowStripePayment(false);
    toast.info('Payment cancelled. Your order is still saved.');
  };

  const handlePlaceOrder = () => {
    if (!customerName.trim()) {
      toast.error(t('enterName') || 'Please enter your name');
      setActiveStep(2);
      return;
    }
    if (!customerPhone.trim()) {
      toast.error(t('enterPhone') || 'Please enter your phone number');
      setActiveStep(2);
      return;
    }
    if (orderType === 'dine_in' && !tableNumber.trim()) {
      toast.error(t('enterTableNumber') || 'Please enter your table number');
      setActiveStep(2);
      return;
    }
    if (moduleItems.length === 0) {
      toast.error(t('cartEmpty') || 'Your cart is empty');
      return;
    }

    // Build discount data from applied discounts
    const couponDiscount = appliedDiscounts.find(d => d.type === 'coupon');
    const giftCardDiscounts = appliedDiscounts.filter(d => d.type === 'giftcard');
    const loyaltyDiscount = appliedDiscounts.find(d => d.type === 'loyalty');

    orderMutation.mutate({
      customerName: customerName.trim(),
      customerPhone: customerPhone.trim(),
      tableNumber: orderType === 'dine_in' ? tableNumber.trim() : undefined,
      orderType,
      paymentMethod,
      notes: notes.trim(),
      items: moduleItems.map((item) => ({
        menuItemId: item.id,
        quantity: item.quantity,
        specialInstructions: item.specialInstructions,
      })),
      moduleId,
      // Pass discount information to backend
      couponCode: couponDiscount?.code,
      giftCardRedemptions: giftCardDiscounts.length > 0 
        ? giftCardDiscounts.map(gc => ({ code: gc.code!, amount: gc.amount }))
        : undefined,
      loyaltyPointsToRedeem: loyaltyDiscount 
        ? parseInt(loyaltyDiscount.details?.replace(/[^\d]/g, '') || '0')
        : undefined,
      loyaltyPointsDollarValue: loyaltyDiscount?.amount,
    });
  };

  if (!isHydrated) {
    return null;
  }

  if (modulesLoading) {
