    { value: 'takeaway', label: t('takeaway') || 'Takeaway', icon: ShoppingCart, description: 'Pick up when ready' },
    { value: 'delivery', label: t('delivery') || 'Delivery', icon: Truck, description: 'Delivered to your door' },
  ];

