export default function ChannelManagerPage() {
  const queryClient = useQueryClient();
  const [selectedChannel, setSelectedChannel] = useState<Channel | null>(null);
  const [showConnectModal, setShowConnectModal] = useState(false);
  const [connectForm, setConnectForm] = useState({ type: 'booking_com', hotelId: '', apiKey: '' });
  const [fetchError, setFetchError] = useState<string | null>(null);

  // Helper to get property ID - in production this would come from context
  const getPropertyId = () => '00000000-0000-0000-0000-000000000001';

  // Fetch channels (connections)
  const { data: channels = [], isLoading } = useQuery({
    queryKey: ['channels'],
    queryFn: async () => {
      try {
        const propertyId = getPropertyId();
        const res = await api.get(`/channels/properties/${propertyId}/connections`);
        const data = res.data;
        setFetchError(null);
        // Transform backend data to frontend format
        return (data.connections || []).map((conn: any) => ({
          id: conn.id,
          name: channelNames[conn.channel_code?.toLowerCase()] || conn.channel_name,
          type: conn.channel_code?.toLowerCase() || 'custom',
          status: conn.status === 'active' ? 'connected' : conn.status,
          last_sync: conn.last_sync_at,
          sync_errors: conn.error_count,
          rooms_mapped: 0, // Would need separate query
          rates_mapped: 0,
          bookings_today: 0,
          revenue_mtd: 0,
          commission_rate: 15,
          config: {
            hotel_id: conn.hotel_code,
            api_key: conn.api_key
          }
        }));
      } catch (error) {
        setFetchError('Could not connect to server');
        return [];
      }
    }
  });

  // Fetch sync logs
  const { data: syncLogs = [] } = useQuery({
    queryKey: ['channel-sync-logs'],
    queryFn: async () => {
      try {
        // Get logs for each connection
        const propertyId = getPropertyId();
        const res = await api.get(`/channels/properties/${propertyId}/connections`);
        const connections = res.data?.connections || [];
        
        // For now, return empty - full implementation would aggregate from all connections
        return [];
      } catch {
        return [];
      }
    }
  });

  // Sync channel
  const syncMutation = useMutation({
    mutationFn: async (channelId: string) => {
      const res = await api.post(`/channels/connections/${channelId}/sync/availability`);
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['channels'] });
      toast.success('Sync started');
    },
    onError: () => {
      toast.error('Failed to start sync');
    }
  });

  // Connect channel
  const connectMutation = useMutation({
    mutationFn: async (data: { type: string; hotelId: string; apiKey: string }) => {
      const propertyId = getPropertyId();
      const res = await api.post(`/channels/properties/${propertyId}/connections`, {
        channel_code: data.type.toUpperCase(),
        channel_name: channelNames[data.type] || data.type,
        hotel_code: data.hotelId,
        api_key: data.apiKey,
        status: 'pending'
      });
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['channels'] });
      setShowConnectModal(false);
      toast.success('Channel connected');
    },
    onError: () => {
      toast.error('Failed to connect channel');
    }
  });

  // Disconnect channel
  const disconnectMutation = useMutation({
    mutationFn: async (channelId: string) => {
      const res = await api.delete(`/channels/connections/${channelId}`);
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['channels'] });
      toast.success('Channel disconnected');
    }
  });

  // Stats
  const connectedChannels = channels.filter((c: Channel) => c.status === 'connected').length;
  const totalBookingsToday = channels.reduce((sum: number, c: Channel) => sum + c.bookings_today, 0);
  const totalRevenueMTD = channels.reduce((sum: number, c: Channel) => sum + c.revenue_mtd, 0);
  const channelsWithErrors = channels.filter((c: Channel) => c.status === 'error').length;

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
  };

  const formatTimeAgo = (dateStr: string) => {
    const diff = Date.now() - new Date(dateStr).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    return `${Math.floor(hours / 24)}d ago`;
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Channel Manager</h1>
          <p className="text-slate-600 dark:text-slate-400">Manage OTA connections and sync inventory</p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => channels.forEach((c: Channel) => c.status === 'connected' && syncMutation.mutate(c.id))}
            className="flex items-center gap-2 px-4 py-2 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
          >
            <RefreshCw className="w-4 h-4" />
            Sync All
          </button>
          <button 
            onClick={() => setShowConnectModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 transition-colors"
          >
            <LinkIcon className="w-4 h-4" />
            Connect Channel
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-green-100 dark:bg-green-900/30">
              <Globe className="w-5 h-5 text-green-600 dark:text-green-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{connectedChannels}</p>
              <p className="text-sm text-slate-500">Connected Channels</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-100 dark:bg-blue-900/30">
              <Calendar className="w-5 h-5 text-blue-600 dark:text-blue-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{totalBookingsToday}</p>
              <p className="text-sm text-slate-500">Bookings Today</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-emerald-100 dark:bg-emerald-900/30">
              <TrendingUp className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{formatCurrency(totalRevenueMTD)}</p>
              <p className="text-sm text-slate-500">Revenue MTD</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-lg ${channelsWithErrors > 0 ? 'bg-red-100 dark:bg-red-900/30' : 'bg-slate-100 dark:bg-slate-700'}`}>
              <AlertCircle className={`w-5 h-5 ${channelsWithErrors > 0 ? 'text-red-600 dark:text-red-400' : 'text-slate-500'}`} />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{channelsWithErrors}</p>
              <p className="text-sm text-slate-500">Channels with Errors</p>
            </div>
          </div>
        </div>
      </div>

      {/* Channels Grid */}
      <div className="grid grid-cols-2 gap-4">
        {channels.map((channel: Channel) => (
          <div
            key={channel.id}
            className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 overflow-hidden"
          >
            <div className="p-4 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className="text-2xl">{channelLogos[channel.type]}</span>
                <div>
                  <h3 className="font-semibold text-slate-900 dark:text-white">{channelNames[channel.type]}</h3>
                  <span className={`text-xs px-2 py-0.5 rounded-full ${statusColors[channel.status]}`}>
                    {channel.status === 'syncing' && <Loader2 className="w-3 h-3 inline animate-spin mr-1" />}
                    {channel.status}
                  </span>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {channel.status === 'connected' && (
                  <button
                    onClick={() => syncMutation.mutate(channel.id)}
                    disabled={syncMutation.isPending}
                    className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
                  >
                    <RefreshCw className={`w-4 h-4 ${syncMutation.isPending ? 'animate-spin' : ''}`} />
                  </button>
                )}
                <button className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700">
                  <Settings className="w-4 h-4" />
                </button>
              </div>
            </div>

            <div className="p-4">
              {channel.status === 'disconnected' ? (
                <div className="text-center py-6">
                  <Unlink className="w-8 h-8 mx-auto text-slate-400 mb-2" />
                  <p className="text-slate-600 dark:text-slate-400 mb-4">Not connected</p>
                  <button
                    onClick={() => {
                      setConnectForm({ ...connectForm, type: channel.type });
                      setShowConnectModal(true);
                    }}
                    className="px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90"
                  >
                    Connect
                  </button>
                </div>
              ) : channel.status === 'error' ? (
                <div className="text-center py-4">
                  <div className="bg-red-50 dark:bg-red-900/20 rounded-lg p-4 mb-4">
                    <XCircle className="w-6 h-6 mx-auto text-red-500 mb-2" />
                    <p className="text-sm text-red-700 dark:text-red-300">
                      {channel.sync_errors} sync error(s) detected
                    </p>
                  </div>
                  <div className="flex gap-2 justify-center">
                    <button
                      onClick={() => syncMutation.mutate(channel.id)}
                      className="px-3 py-1.5 text-sm bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 rounded-lg"
                    >
                      Retry Sync
                    </button>
                    <button className="px-3 py-1.5 text-sm border border-slate-200 dark:border-slate-700 rounded-lg">
                      View Errors
                    </button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                      <p className="text-xs text-slate-500">Rooms Mapped</p>
                      <p className="text-lg font-semibold text-slate-900 dark:text-white">{channel.rooms_mapped}</p>
                    </div>
                    <div>
                      <p className="text-xs text-slate-500">Rate Plans</p>
                      <p className="text-lg font-semibold text-slate-900 dark:text-white">{channel.rates_mapped}</p>
                    </div>
                    <div>
                      <p className="text-xs text-slate-500">Today's Bookings</p>
                      <p className="text-lg font-semibold text-slate-900 dark:text-white">{channel.bookings_today}</p>
                    </div>
                    <div>
                      <p className="text-xs text-slate-500">Revenue MTD</p>
                      <p className="text-lg font-semibold text-slate-900 dark:text-white">{formatCurrency(channel.revenue_mtd)}</p>
                    </div>
                  </div>
                  <div className="flex items-center justify-between text-xs text-slate-500 pt-3 border-t border-slate-200 dark:border-slate-700">
                    <span className="flex items-center gap-1">
                      <Clock className="w-3 h-3" />
                      Last sync: {channel.last_sync ? formatTimeAgo(channel.last_sync) : 'Never'}
                    </span>
                    <span>Commission: {channel.commission_rate}%</span>
                  </div>
                </>
              )}
            </div>

            {channel.status === 'connected' && (
              <div className="px-4 py-2 bg-slate-50 dark:bg-slate-700/30 border-t border-slate-200 dark:border-slate-700 flex justify-between items-center">
                <button className="text-sm text-primary hover:underline flex items-center gap-1">
                  View Bookings
                  <ChevronRight className="w-4 h-4" />
                </button>
                <button
                  onClick={() => {
                    if (confirm(`Disconnect from ${channelNames[channel.type]}?`)) {
                      disconnectMutation.mutate(channel.id);
                    }
                  }}
                  className="text-sm text-red-600 hover:underline"
                >
                  Disconnect
                </button>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Sync Activity */}
      <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700">
        <div className="px-4 py-3 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between">
          <h2 className="font-semibold text-slate-900 dark:text-white">Recent Sync Activity</h2>
          <Activity className="w-4 h-4 text-slate-400" />
        </div>
        <div className="p-4">
          {syncLogs.length === 0 ? (
            <p className="text-center text-slate-500 py-4">No recent sync activity</p>
          ) : (
            <div className="space-y-2">
              {syncLogs.slice(0, 5).map((log: SyncLog) => (
                <div key={log.id} className="flex items-center justify-between py-2 border-b border-slate-100 dark:border-slate-700 last:border-0">
                  <div className="flex items-center gap-3">
                    {log.status === 'success' ? (
                      <CheckCircle className="w-4 h-4 text-green-500" />
                    ) : log.status === 'failed' ? (
                      <XCircle className="w-4 h-4 text-red-500" />
                    ) : (
                      <AlertCircle className="w-4 h-4 text-yellow-500" />
                    )}
                    <span className="text-sm text-slate-900 dark:text-white capitalize">{log.type}</span>
                  </div>
                  <div className="flex items-center gap-4 text-sm text-slate-500">
                    <span>{log.records_synced} records</span>
                    <span>{formatTimeAgo(log.created_at)}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Connect Modal */}
      {showConnectModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 max-w-md w-full mx-4">
            <h2 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">
              Connect Channel
            </h2>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                connectMutation.mutate(connectForm);
              }}
              className="space-y-4"
            >
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  Channel
                </label>
                <select
                  value={connectForm.type}
                  onChange={(e) => setConnectForm({ ...connectForm, type: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                >
                  <option value="booking_com">Booking.com</option>
                  <option value="expedia">Expedia</option>
                  <option value="airbnb">Airbnb</option>
                  <option value="agoda">Agoda</option>
                  <option value="trip_com">Trip.com</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  Hotel/Property ID
                </label>
                <input
                  type="text"
                  value={connectForm.hotelId}
                  onChange={(e) => setConnectForm({ ...connectForm, hotelId: e.target.value })}
                  placeholder="e.g., 123456"
                  required
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  API Key / Access Token
                </label>
                <input
                  type="password"
                  value={connectForm.apiKey}
                  onChange={(e) => setConnectForm({ ...connectForm, apiKey: e.target.value })}
                  placeholder="••••••••••••"
                  required
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                />
              </div>
              <p className="text-xs text-slate-500">
                Contact each OTA to obtain your API credentials. Iron Paradise Gym uses SiteMinder for channel management.
              </p>
              <div className="flex gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowConnectModal(false)}
                  className="flex-1 py-2 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={connectMutation.isPending || !connectForm.hotelId || !connectForm.apiKey}
                  className="flex-1 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 disabled:opacity-50"
                >
                  {connectMutation.isPending ? 'Connecting...' : 'Connect'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/Tabs';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  Ticket,
  Percent,
  DollarSign,
  TrendingUp,
  Search,
  Plus,
  Edit,
  Trash2,
  RefreshCw,
  Copy,
  CheckCircle,
  XCircle,
  Clock,
  Calendar,
  Tag,
  Users,
  ShoppingCart,
} from 'lucide-react';

interface Coupon {
  id: string;
  code: string;
  name: string;
  description?: string;
  discount_type: 'percentage' | 'fixed' | 'free_item';
  discount_value: number;
  min_order_amount: number;
  max_discount_amount?: number;
  applies_to: string;
  usage_limit?: number;
  usage_count: number;
  per_user_limit: number;
  valid_from?: string;
  valid_until?: string;
  is_active: boolean;
  created_at: string;
}

interface CouponStats {
  total_coupons: number;
  active_coupons: number;
  total_uses: number;
  totalDiscountGiven: number;
}

export default function CouponsAdminPage() {
  const [activeTab, setActiveTab] = useState('coupons');
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [stats, setStats] = useState<CouponStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [editingCoupon, setEditingCoupon] = useState<Coupon | null>(null);
  
  // Form state
  const [formData, setFormData] = useState({
    code: '',
    name: '',
    description: '',
    discountType: 'percentage' as 'percentage' | 'fixed' | 'free_item',
    discountValue: '',
    minOrderAmount: '0',
    maxDiscountAmount: '',
    appliesTo: 'all',
    usageLimit: '',
    perUserLimit: '1',
    validFrom: '',
    validUntil: '',
    firstOrderOnly: false,
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [couponsRes, statsRes] = await Promise.all([
        api.get('/coupons', { params: { status: statusFilter === 'all' ? undefined : statusFilter } }),
        api.get('/coupons/stats'),
      ]);

      if (couponsRes.data.success) setCoupons(couponsRes.data.data);
      if (statsRes.data.success) setStats(statsRes.data.data.summary);
    } catch (error) {
      toast.error('Failed to load coupon data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [statusFilter]);

  const generateCode = async () => {
    try {
      const res = await api.get('/coupons/generate-code');
      if (res.data.success) {
        setFormData(f => ({ ...f, code: res.data.data.code }));
      }
    } catch (error) {
      toast.error('Failed to generate code');
    }
  };

  const handleSubmit = async () => {
    if (!formData.code || !formData.name || !formData.discountValue) {
      toast.error('Please fill in required fields');
      return;
    }
    
    try {
      const payload = {
        code: formData.code,
        name: formData.name,
        description: formData.description || undefined,
        discountType: formData.discountType,
        discountValue: parseFloat(formData.discountValue),
        minOrderAmount: parseFloat(formData.minOrderAmount) || 0,
        maxDiscountAmount: formData.maxDiscountAmount ? parseFloat(formData.maxDiscountAmount) : undefined,
        appliesTo: formData.appliesTo,
        usageLimit: formData.usageLimit ? parseInt(formData.usageLimit) : undefined,
        perUserLimit: parseInt(formData.perUserLimit) || 1,
        validFrom: formData.validFrom || undefined,
        validUntil: formData.validUntil || undefined,
        firstOrderOnly: formData.firstOrderOnly,
      };
      
      let res;
      if (editingCoupon) {
        res = await api.put(`/coupons/${editingCoupon.id}`, payload);
      } else {
        res = await api.post('/coupons', payload);
      }
      
      if (res.data.success) {
        toast.success(editingCoupon ? 'Coupon updated' : 'Coupon created');
        setShowCreateModal(false);
        setEditingCoupon(null);
        resetForm();
        loadData();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Failed to save coupon');
    }
  };

  const resetForm = () => {
    setFormData({
      code: '',
      name: '',
      description: '',
      discountType: 'percentage',
      discountValue: '',
      minOrderAmount: '0',
      maxDiscountAmount: '',
      appliesTo: 'all',
      usageLimit: '',
      perUserLimit: '1',
      validFrom: '',
      validUntil: '',
      firstOrderOnly: false,
    });
  };

  const handleEdit = (coupon: Coupon) => {
    setEditingCoupon(coupon);
    setFormData({
      code: coupon.code,
      name: coupon.name,
      description: coupon.description || '',
      discountType: coupon.discount_type,
      discountValue: coupon.discount_value.toString(),
      minOrderAmount: coupon.min_order_amount.toString(),
      maxDiscountAmount: coupon.max_discount_amount?.toString() || '',
      appliesTo: coupon.applies_to,
      usageLimit: coupon.usage_limit?.toString() || '',
      perUserLimit: coupon.per_user_limit.toString(),
      validFrom: coupon.valid_from?.split('T')[0] || '',
      validUntil: coupon.valid_until?.split('T')[0] || '',
      firstOrderOnly: false,
    });
    setShowCreateModal(true);
  };

  const handleDelete = async (couponId: string) => {
    if (!confirm('Are you sure you want to delete this coupon?')) return;
    
    try {
      const res = await api.delete(`/coupons/${couponId}`);
      if (res.data.success) {
        toast.success('Coupon deleted');
        loadData();
      }
    } catch (error) {
      toast.error('Failed to delete coupon');
    }
  };

  const handleToggleActive = async (coupon: Coupon) => {
    try {
      const res = await api.put(`/coupons/${coupon.id}`, { isActive: !coupon.is_active });
      if (res.data.success) {
        toast.success(coupon.is_active ? 'Coupon deactivated' : 'Coupon activated');
        loadData();
      }
    } catch (error) {
      toast.error('Failed to update coupon');
    }
  };

  const copyCode = (code: string) => {
    navigator.clipboard.writeText(code);
    toast.success('Code copied to clipboard');
  };

  const getDiscountDisplay = (coupon: Coupon) => {
    if (coupon.discount_type === 'percentage') {
      return `${coupon.discount_value}% off`;
    } else if (coupon.discount_type === 'fixed') {
      return `${formatCurrency(coupon.discount_value)} off`;
    } else {
      return 'Free item';
    }
  };

  const getStatusBadge = (coupon: Coupon) => {
    const now = new Date();
    const validUntil = coupon.valid_until ? new Date(coupon.valid_until) : null;
    
    if (!coupon.is_active) {
      return <Badge className="bg-slate-100 text-slate-500">Inactive</Badge>;
    }
    if (validUntil && validUntil < now) {
      return <Badge className="bg-amber-100 text-amber-700">Expired</Badge>;
    }
    if (coupon.usage_limit && coupon.usage_count >= coupon.usage_limit) {
      return <Badge className="bg-red-100 text-red-700">Limit Reached</Badge>;
    }
    return <Badge className="bg-green-100 text-green-700">Active</Badge>;
  };

  const filteredCoupons = coupons.filter(coupon => {
    const matchesSearch = searchQuery === '' || 
      coupon.code.toLowerCase().includes(searchQuery.toLowerCase()) ||
      coupon.name.toLowerCase().includes(searchQuery.toLowerCase());
    
    return matchesSearch;
  });

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <RefreshCw className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Coupons</h1>
          <p className="text-slate-500 dark:text-slate-400">Manage discount codes and promotions</p>
        </div>
        <div className="flex gap-2">
          <Button onClick={() => loadData()} variant="outline" className="gap-2">
            <RefreshCw className="w-4 h-4" />
            Refresh
          </Button>
          <Button onClick={() => { resetForm(); setEditingCoupon(null); setShowCreateModal(true); }} className="gap-2">
            <Plus className="w-4 h-4" />
            Create Coupon
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-blue-100 text-sm">Total Coupons</p>
                <p className="text-3xl font-bold">{stats?.total_coupons || 0}</p>
              </div>
              <Ticket className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-green-100 text-sm">Active Coupons</p>
                <p className="text-3xl font-bold">{stats?.active_coupons || 0}</p>
              </div>
              <CheckCircle className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-amber-500 to-amber-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-amber-100 text-sm">Total Uses</p>
                <p className="text-3xl font-bold">{stats?.total_uses || 0}</p>
              </div>
              <Users className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-purple-100 text-sm">Discount Given</p>
                <p className="text-3xl font-bold">{formatCurrency(stats?.totalDiscountGiven || 0)}</p>
              </div>
              <DollarSign className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Filters */}
      <div className="flex gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
          <Input
            placeholder="Search by code or name..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="px-4 py-2 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
        >
          <option value="all">All Status</option>
          <option value="active">Active</option>
          <option value="inactive">Inactive</option>
        </select>
      </div>

      {/* Coupons Table */}
      <Card>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b dark:border-slate-700">
                  <th className="text-left p-4 font-medium text-slate-500">Code</th>
                  <th className="text-left p-4 font-medium text-slate-500">Name</th>
                  <th className="text-left p-4 font-medium text-slate-500">Discount</th>
                  <th className="text-left p-4 font-medium text-slate-500">Applies To</th>
                  <th className="text-center p-4 font-medium text-slate-500">Usage</th>
                  <th className="text-left p-4 font-medium text-slate-500">Valid Until</th>
                  <th className="text-left p-4 font-medium text-slate-500">Status</th>
                  <th className="text-right p-4 font-medium text-slate-500">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredCoupons.map((coupon) => (
                  <tr key={coupon.id} className="border-b dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800">
                    <td className="p-4">
                      <div className="flex items-center gap-2">
                        <code className="font-mono font-bold bg-slate-100 dark:bg-slate-700 px-2 py-1 rounded">
                          {coupon.code}
                        </code>
                        <Button 
                          variant="ghost" 
                          size="sm"
                          onClick={() => copyCode(coupon.code)}
                        >
                          <Copy className="w-4 h-4" />
                        </Button>
                      </div>
                    </td>
                    <td className="p-4">
                      <p className="font-medium">{coupon.name}</p>
                      {coupon.description && (
                        <p className="text-sm text-slate-500 truncate max-w-xs">{coupon.description}</p>
                      )}
                    </td>
                    <td className="p-4">
                      <Badge className="bg-blue-100 text-blue-700">
                        {coupon.discount_type === 'percentage' && <Percent className="w-3 h-3 mr-1" />}
                        {getDiscountDisplay(coupon)}
                      </Badge>
                      {coupon.min_order_amount > 0 && (
                        <p className="text-xs text-slate-500 mt-1">Min: {formatCurrency(coupon.min_order_amount)}</p>
                      )}
                    </td>
                    <td className="p-4">
                      <Badge variant="outline" className="capitalize">
                        {coupon.applies_to}
                      </Badge>
                    </td>
                    <td className="p-4 text-center">
                      <span className="font-medium">{coupon.usage_count}</span>
                      {coupon.usage_limit && (
                        <span className="text-slate-400">/{coupon.usage_limit}</span>
                      )}
                    </td>
                    <td className="p-4 text-slate-500">
                      {coupon.valid_until ? (
                        <div className="flex items-center gap-1">
                          <Calendar className="w-4 h-4" />
                          {formatDate(coupon.valid_until)}
                        </div>
                      ) : (
                        <span className="text-slate-400">No expiry</span>
                      )}
                    </td>
                    <td className="p-4">
                      {getStatusBadge(coupon)}
                    </td>
                    <td className="p-4 text-right">
                      <div className="flex justify-end gap-1">
                        <Button 
                          variant="ghost" 
                          size="sm"
                          onClick={() => handleToggleActive(coupon)}
                          title={coupon.is_active ? 'Deactivate' : 'Activate'}
                        >
                          {coupon.is_active ? (
                            <XCircle className="w-4 h-4 text-red-500" />
                          ) : (
                            <CheckCircle className="w-4 h-4 text-green-500" />
                          )}
                        </Button>
                        <Button 
                          variant="ghost" 
                          size="sm"
                          onClick={() => handleEdit(coupon)}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button 
                          variant="ghost" 
                          size="sm"
                          onClick={() => handleDelete(coupon.id)}
                          className="text-red-500 hover:text-red-700"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Create/Edit Modal */}
      <AnimatePresence>
        {showCreateModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
            onClick={() => { setShowCreateModal(false); setEditingCoupon(null); }}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-2xl shadow-2xl max-h-[90vh] overflow-y-auto"
            >
              <h3 className="text-xl font-bold mb-4">
                {editingCoupon ? 'Edit Coupon' : 'Create Coupon'}
              </h3>
              
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2 sm:col-span-1">
                  <label className="block text-sm font-medium mb-2">Code *</label>
                  <div className="flex gap-2">
                    <Input
                      placeholder="SUMMER20"
                      value={formData.code}
                      onChange={(e) => setFormData(f => ({ ...f, code: e.target.value.toUpperCase() }))}
                    />
                    <Button variant="outline" onClick={generateCode} type="button">
                      Generate
                    </Button>
                  </div>
                </div>
                
                <div className="col-span-2 sm:col-span-1">
                  <label className="block text-sm font-medium mb-2">Name *</label>
                  <Input
                    placeholder="Summer Sale 20% Off"
                    value={formData.name}
                    onChange={(e) => setFormData(f => ({ ...f, name: e.target.value }))}
                  />
                </div>
                
                <div className="col-span-2">
                  <label className="block text-sm font-medium mb-2">Description</label>
                  <Input
                    placeholder="Optional description"
                    value={formData.description}
                    onChange={(e) => setFormData(f => ({ ...f, description: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Discount Type *</label>
                  <select
                    value={formData.discountType}
                    onChange={(e) => setFormData(f => ({ ...f, discountType: e.target.value as any }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="percentage">Percentage</option>
                    <option value="fixed">Fixed Amount</option>
                    <option value="free_item">Free Item</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">
                    {formData.discountType === 'percentage' ? 'Percentage *' : 'Amount *'}
                  </label>
                  <Input
                    type="number"
                    placeholder={formData.discountType === 'percentage' ? '20' : '10.00'}
                    value={formData.discountValue}
                    onChange={(e) => setFormData(f => ({ ...f, discountValue: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Minimum Order ($)</label>
                  <Input
                    type="number"
                    placeholder="0"
                    value={formData.minOrderAmount}
                    onChange={(e) => setFormData(f => ({ ...f, minOrderAmount: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Max Discount ($)</label>
                  <Input
                    type="number"
                    placeholder="No limit"
                    value={formData.maxDiscountAmount}
                    onChange={(e) => setFormData(f => ({ ...f, maxDiscountAmount: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Applies To</label>
                  <select
                    value={formData.appliesTo}
                    onChange={(e) => setFormData(f => ({ ...f, appliesTo: e.target.value }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="all">All Orders</option>
                    <option value="restaurant">Restaurant Only</option>
                    <option value="chalets">Chalets Only</option>
                    <option value="pool">Pool Only</option>
                    <option value="snack">Snack Bar Only</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Usage Limit</label>
                  <Input
                    type="number"
                    placeholder="Unlimited"
                    value={formData.usageLimit}
                    onChange={(e) => setFormData(f => ({ ...f, usageLimit: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Per User Limit</label>
                  <Input
                    type="number"
                    placeholder="1"
                    value={formData.perUserLimit}
                    onChange={(e) => setFormData(f => ({ ...f, perUserLimit: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Valid From</label>
                  <Input
                    type="date"
                    value={formData.validFrom}
                    onChange={(e) => setFormData(f => ({ ...f, validFrom: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Valid Until</label>
                  <Input
                    type="date"
                    value={formData.validUntil}
                    onChange={(e) => setFormData(f => ({ ...f, validUntil: e.target.value }))}
                  />
                </div>
                
                <div className="col-span-2">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={formData.firstOrderOnly}
                      onChange={(e) => setFormData(f => ({ ...f, firstOrderOnly: e.target.checked }))}
                      className="rounded"
                    />
                    <span className="text-sm">First order only</span>
                  </label>
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => { setShowCreateModal(false); setEditingCoupon(null); }}>
                  Cancel
                </Button>
                <Button onClick={handleSubmit}>
                  {editingCoupon ? 'Update Coupon' : 'Create Coupon'}
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/Dialog';
import { useDebounce } from '@/utils/performance';
import { useSiteSettings, Module } from '@/lib/settings-context';
import {
  Plus,
  Edit2,
  Trash2,
  Link2,
  RefreshCw,
  Settings2,
  ChevronDown,
  ChevronRight,
  Package,
  DollarSign,
  Activity,
  AlertTriangle,
  CheckCircle2,
  Search,
  Filter,
  Layers,
  BarChart3,
  Clock,
  Eye,
  EyeOff,
} from 'lucide-react';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';

// Types
type CustomizationType = 'add' | 'remove' | 'swap' | 'upgrade' | 'replace';
type SelectionMode = 'single' | 'multiple' | 'quantity';
type PriceType = 'fixed' | 'percentage' | 'per_unit' | 'per_night' | 'per_person';

// Map module template types to entity type keys
const MODULE_TO_ENTITY_TYPE: Record<string, string> = {
  'menu_service': 'menu_item',
  'multi_day_booking': 'chalet',
  'session_access': 'pool_session',
};

interface CustomizationGroup {
  id: string;
  name: string;
  nameAr?: string;
  description?: string;
  selectionMode: SelectionMode;
  minSelections: number;
  maxSelections: number;
  isRequired: boolean;
  applicableEntityTypes: string[];
  isGlobal: boolean;
  isAvailable: boolean;
  sortOrder: number;
  options?: CustomizationOption[];
}

interface CustomizationOption {
  id: string;
  groupId: string;
  name: string;
  nameAr?: string;
  customizationType: CustomizationType;
  priceAdjustment: number;
  priceType: PriceType;
  inventoryItemId?: string;
  quantityPerSelection: number;
  maxQuantity: number;
  isDefault: boolean;
  isPopular: boolean;
  isAvailable: boolean;
  sortOrder: number;
}

interface MetricSummary {
  metricName: string;
  sampleCount: number;
  avgValue: number;
  minValue: number;
  maxValue: number;
  p50: number;
  p95: number;
  p99: number;
  hour: string;
}

interface DualWriteStats {
  total: number;
  matches: number;
  mismatches: number;
  matchRate: number;
}

// Entity type labels - static list, but will be filtered by active modules
const ALL_ENTITY_TYPE_LABELS: Record<string, string> = {
  menu_item: 'Menu Items',
  snack_bar_item: 'Snack Bar Items',
  chalet: 'Chalets',
  pool_session: 'Pool Sessions',
  spa_service: 'Spa Services',
  activity: 'Activities',
  rental_item: 'Rentals',
  event_ticket: 'Event Tickets',
  room: 'Rooms',
  package: 'Packages',
};

// Map module slugs to entity types
const MODULE_SLUG_TO_ENTITY: Record<string, string[]> = {
  'restaurant': ['menu_item'],
  'snack-bar': ['snack_bar_item'],
  'chalets': ['chalet'],
  'pool': ['pool_session'],
  'spa': ['spa_service'],
  'activities': ['activity'],
  'rentals': ['rental_item'],
  'events': ['event_ticket'],
  'rooms': ['room'],
};

const SELECTION_MODE_LABELS: Record<SelectionMode, string> = {
  single: 'Single Selection',
  multiple: 'Multiple Selection',
  quantity: 'Quantity Selector',
};

const CUSTOMIZATION_TYPE_LABELS: Record<CustomizationType, string> = {
  add: 'Add',
  remove: 'Remove',
  swap: 'Swap',
  upgrade: 'Upgrade',
  replace: 'Replace',
};

export default function AdminCustomizationsPage() {
  const queryClient = useQueryClient();
  const { modules } = useSiteSettings();
  const [activeTab, setActiveTab] = useState<'groups' | 'metrics' | 'migration'>('groups');
  const [searchQuery, setSearchQuery] = useState('');
  const debouncedSearch = useDebounce(searchQuery, 300);
  const [selectedGroup, setSelectedGroup] = useState<CustomizationGroup | null>(null);
  const [isGroupDialogOpen, setIsGroupDialogOpen] = useState(false);
  const [isOptionDialogOpen, setIsOptionDialogOpen] = useState(false);
  const [editingOption, setEditingOption] = useState<CustomizationOption | null>(null);
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  // Compute available entity types based on active modules
  const availableEntityTypes = useMemo(() => {
    if (!modules || modules.length === 0) {
      // Fallback: show all entity types if no modules data
      return Object.keys(ALL_ENTITY_TYPE_LABELS);
    }
    
    const activeEntityTypes = new Set<string>();
    
    modules.forEach((mod: Module) => {
      if (mod.is_active) {
        // Check by slug mapping
        const entityTypes = MODULE_SLUG_TO_ENTITY[mod.slug];
        if (entityTypes) {
          entityTypes.forEach(et => activeEntityTypes.add(et));
        }
        // Check by template type mapping
        const entityFromTemplate = MODULE_TO_ENTITY_TYPE[mod.template_type];
        if (entityFromTemplate) {
          activeEntityTypes.add(entityFromTemplate);
        }
      }
    });
    
    // Always include package as it's a cross-module concept
    activeEntityTypes.add('package');
    
    return Array.from(activeEntityTypes);
  }, [modules]);

  // Create filtered entity type labels based on active modules
  const ENTITY_TYPE_LABELS = useMemo(() => {
    const filtered: Record<string, string> = {};
    availableEntityTypes.forEach(key => {
      if (ALL_ENTITY_TYPE_LABELS[key]) {
        filtered[key] = ALL_ENTITY_TYPE_LABELS[key];
      }
    });
    return filtered;
  }, [availableEntityTypes]);

  // Fetch groups with options
  const { data: groups, isLoading: groupsLoading, refetch: refetchGroups } = useQuery({
    queryKey: ['customization-groups'],
    queryFn: async () => {
      const response = await api.get('/customizations/groups', {
        params: { includeOptions: true }
      });
      return response.data as CustomizationGroup[];
    },
  });

  // Client-side search filtering
  const filteredGroups = useMemo(() => {
    if (!groups || !debouncedSearch) return groups;
    const q = debouncedSearch.toLowerCase();
    return groups.filter(g =>
      g.name.toLowerCase().includes(q) ||
      g.description?.toLowerCase().includes(q) ||
      g.options?.some(o => o.name.toLowerCase().includes(q))
    );
  }, [groups, debouncedSearch]);

  // Fetch metrics
  const { data: metrics, isLoading: metricsLoading } = useQuery({
    queryKey: ['customization-metrics'],
    queryFn: async () => {
      const response = await api.get('/customizations/metrics');
      return response.data as MetricSummary[];
    },
    enabled: activeTab === 'metrics',
  });

  // Fetch dual-write stats
  const { data: dualWriteStats } = useQuery({
    queryKey: ['dual-write-stats'],
    queryFn: async () => {
      const response = await api.get('/customizations/dual-write/stats');
      return response.data as DualWriteStats;
    },
    enabled: activeTab === 'migration',
  });

  // Mutations
  const createGroupMutation = useMutation({
    mutationFn: (data: Partial<CustomizationGroup>) =>
      api.post('/customizations/groups', data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customization-groups'] });
      toast.success('Group created successfully');
      setIsGroupDialogOpen(false);
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Failed to create group');
    },
  });

  const updateGroupMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: Partial<CustomizationGroup> }) => 
      api.put(`/customizations/groups/${id}`, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customization-groups'] });
      toast.success('Group updated successfully');
      setIsGroupDialogOpen(false);
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Failed to update group');
    },
  });

  const deleteGroupMutation = useMutation({
    mutationFn: (id: string) => api.delete(`/customizations/groups/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customization-groups'] });
      toast.success('Group deleted successfully');
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Failed to delete group');
    },
  });

  const createOptionMutation = useMutation({
    mutationFn: (data: Partial<CustomizationOption>) => 
      api.post('/customizations/options', data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customization-groups'] });
      toast.success('Option created successfully');
      setIsOptionDialogOpen(false);
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Failed to create option');
    },
  });

  const updateOptionMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: Partial<CustomizationOption> }) => 
      api.put(`/customizations/options/${id}`, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customization-groups'] });
      toast.success('Option updated successfully');
      setIsOptionDialogOpen(false);
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Failed to update option');
    },
  });

  const deleteOptionMutation = useMutation({
    mutationFn: (id: string) => api.delete(`/customizations/options/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customization-groups'] });
      toast.success('Option deleted successfully');
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Failed to delete option');
    },
  });

  const migrateMutation = useMutation({
    mutationFn: () => api.post('/customizations/migrate'),
    onSuccess: (response) => {
      toast.success(`Migration completed: ${response.data.groups} groups, ${response.data.options} options, ${response.data.links} links`);
      queryClient.invalidateQueries({ queryKey: ['customization-groups'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Migration failed');
    },
  });

  // Toggle group expansion
  const toggleGroupExpansion = (groupId: string) => {
    setExpandedGroups(prev => {
      const next = new Set(prev);
      if (next.has(groupId)) {
        next.delete(groupId);
      } else {
        next.add(groupId);
      }
      return next;
    });
  };

  // Group stats
  const groupStats = useMemo(() => {
    if (!groups) return { total: 0, active: 0, inactive: 0, totalOptions: 0 };
    return {
      total: groups.length,
      active: groups.filter(g => g.isAvailable).length,
      inactive: groups.filter(g => !g.isAvailable).length,
      totalOptions: groups.reduce((sum, g) => sum + (g.options?.length || 0), 0),
    };
  }, [groups]);

  return (
    <motion.div
      initial="hidden"
      animate="visible"
      variants={staggerContainer}
      className="space-y-6 p-6"
    >
      {/* Header */}
      <motion.div variants={fadeInUp} className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Customization Manager</h1>
          <p className="text-muted-foreground">
            Manage customization groups, options, and monitor system health
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => refetchGroups()}
            disabled={groupsLoading}
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${groupsLoading ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
          <Button
            onClick={() => {
              setSelectedGroup(null);
              setIsGroupDialogOpen(true);
            }}
          >
            <Plus className="h-4 w-4 mr-2" />
            New Group
          </Button>
        </div>
      </motion.div>

      {/* Stats Cards */}
      <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Total Groups</p>
                <p className="text-2xl font-bold">{groupStats.total}</p>
              </div>
              <Layers className="h-8 w-8 text-primary opacity-50" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Active Groups</p>
                <p className="text-2xl font-bold text-green-600">{groupStats.active}</p>
              </div>
              <CheckCircle2 className="h-8 w-8 text-green-600 opacity-50" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Total Options</p>
                <p className="text-2xl font-bold">{groupStats.totalOptions}</p>
              </div>
              <Settings2 className="h-8 w-8 text-blue-600 opacity-50" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Inactive</p>
                <p className="text-2xl font-bold text-muted-foreground">{groupStats.inactive}</p>
              </div>
              <EyeOff className="h-8 w-8 text-muted-foreground opacity-50" />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Tabs */}
      <motion.div variants={fadeInUp} className="border-b">
        <div className="flex space-x-8">
          {[
            { id: 'groups', label: 'Groups & Options', icon: Layers },
            { id: 'metrics', label: 'Performance Metrics', icon: BarChart3 },
            { id: 'migration', label: 'Migration & Dual-Write', icon: RefreshCw },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as typeof activeTab)}
              className={`flex items-center gap-2 pb-4 px-1 border-b-2 transition-colors ${
                activeTab === tab.id
                  ? 'border-primary text-primary'
                  : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
            >
              <tab.icon className="h-4 w-4" />
              {tab.label}
            </button>
          ))}
        </div>
      </motion.div>

      {/* Tab Content */}
      <AnimatePresence mode="wait">
        {activeTab === 'groups' && (
          <motion.div
            key="groups"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-4"
          >
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search groups and options..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>

            {/* Groups List */}
            <div className="space-y-3">
              {groupsLoading ? (
                <div className="text-center py-8 text-muted-foreground">Loading...</div>
              ) : filteredGroups?.length === 0 ? (
                <Card>
                  <CardContent className="py-8 text-center">
                    <Layers className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                    <p className="text-muted-foreground">No customization groups found</p>
                    <Button
                      className="mt-4"
                      onClick={() => {
                        setSelectedGroup(null);
                        setIsGroupDialogOpen(true);
                      }}
                    >
                      <Plus className="h-4 w-4 mr-2" />
                      Create First Group
                    </Button>
                  </CardContent>
                </Card>
              ) : (
                filteredGroups?.map((group) => (
                  <Card key={group.id} className="overflow-hidden">
                    <div
                      className="flex items-center justify-between p-4 cursor-pointer hover:bg-muted/50 transition-colors"
                      onClick={() => toggleGroupExpansion(group.id)}
                    >
                      <div className="flex items-center gap-3">
                        {expandedGroups.has(group.id) ? (
                          <ChevronDown className="h-5 w-5 text-muted-foreground" />
                        ) : (
                          <ChevronRight className="h-5 w-5 text-muted-foreground" />
                        )}
                        <div>
                          <div className="flex items-center gap-2">
                            <h3 className="font-semibold">{group.name}</h3>
                            {!group.isAvailable && (
                              <span className="px-2 py-0.5 text-xs rounded-full bg-muted text-muted-foreground">
                                Inactive
                              </span>
                            )}
                            {group.isRequired && (
                              <span className="px-2 py-0.5 text-xs rounded-full bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400">
                                Required
                              </span>
                            )}
                            {group.isGlobal && (
                              <span className="px-2 py-0.5 text-xs rounded-full bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400">
                                Global
                              </span>
                            )}
                          </div>
                          <p className="text-sm text-muted-foreground">
                            {SELECTION_MODE_LABELS[group.selectionMode]} • 
                            {group.options?.length || 0} options • 
                            {group.applicableEntityTypes.map(t => ALL_ENTITY_TYPE_LABELS[t] || t).slice(0, 2).join(', ')}
                            {group.applicableEntityTypes.length > 2 && ` +${group.applicableEntityTypes.length - 2}`}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2" onClick={(e) => e.stopPropagation()}>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => {
                            setSelectedGroup(group);
                            setEditingOption(null);
                            setIsOptionDialogOpen(true);
                          }}
                        >
                          <Plus className="h-4 w-4 mr-1" />
                          Option
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => {
                            setSelectedGroup(group);
                            setIsGroupDialogOpen(true);
                          }}
                        >
                          <Edit2 className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => {
                            if (confirm('Are you sure you want to delete this group?')) {
                              deleteGroupMutation.mutate(group.id);
                            }
                          }}
                        >
                          <Trash2 className="h-4 w-4 text-destructive" />
                        </Button>
                      </div>
                    </div>

                    {/* Expanded Options */}
                    <AnimatePresence>
                      {expandedGroups.has(group.id) && group.options && group.options.length > 0 && (
                        <motion.div
                          initial={{ height: 0, opacity: 0 }}
                          animate={{ height: 'auto', opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          className="border-t bg-muted/30"
                        >
                          <div className="p-4 space-y-2">
                            {group.options.map((option) => (
                              <div
                                key={option.id}
                                className="flex items-center justify-between p-3 bg-background rounded-lg border"
                              >
                                <div className="flex items-center gap-3">
                                  <div className={`w-2 h-2 rounded-full ${
                                    option.isAvailable ? 'bg-green-500' : 'bg-muted'
                                  }`} />
                                  <div>
                                    <div className="flex items-center gap-2">
                                      <span className="font-medium">{option.name}</span>
                                      <span className="px-2 py-0.5 text-xs rounded-full bg-muted">
                                        {CUSTOMIZATION_TYPE_LABELS[option.customizationType]}
                                      </span>
                                      {option.isDefault && (
                                        <span className="px-2 py-0.5 text-xs rounded-full bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400">
                                          Default
                                        </span>
                                      )}
                                      {option.isPopular && (
                                        <span className="px-2 py-0.5 text-xs rounded-full bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400">
                                          Popular
                                        </span>
                                      )}
                                    </div>
                                    <p className="text-sm text-muted-foreground">
                                      {option.priceAdjustment > 0 ? '+' : ''}
                                      {option.priceAdjustment.toFixed(2)} ({option.priceType})
                                      {option.inventoryItemId && ' • Inventory linked'}
                                    </p>
                                  </div>
                                </div>
                                <div className="flex items-center gap-1">
                                  <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={() => {
                                      setSelectedGroup(group);
                                      setEditingOption(option);
                                      setIsOptionDialogOpen(true);
                                    }}
                                  >
                                    <Edit2 className="h-4 w-4" />
                                  </Button>
                                  <Button
                                    variant="ghost"
                                    size="sm"
                                    onClick={() => {
                                      if (confirm('Delete this option?')) {
                                        deleteOptionMutation.mutate(option.id);
                                      }
                                    }}
                                  >
                                    <Trash2 className="h-4 w-4 text-destructive" />
                                  </Button>
                                </div>
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </Card>
                ))
              )}
            </div>
          </motion.div>
        )}

        {activeTab === 'metrics' && (
          <motion.div
            key="metrics"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-4"
          >
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <BarChart3 className="h-5 w-5" />
                  Performance Metrics (Last 24h)
                </CardTitle>
              </CardHeader>
              <CardContent>
                {metricsLoading ? (
                  <div className="text-center py-8 text-muted-foreground">Loading metrics...</div>
                ) : !metrics || metrics.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Clock className="h-12 w-12 mx-auto mb-4 opacity-50" />
                    <p>No metrics data available yet</p>
                    <p className="text-sm">Metrics will appear after customization operations</p>
                  </div>
                ) : (
                  <div className="space-y-6">
                    {/* Group by metric name */}
                    {['validation_latency_ms', 'inventory_processing_ms'].map((metricName) => {
                      const metricData = metrics.filter(m => m.metricName === metricName);
                      if (metricData.length === 0) return null;
                      
                      const latest = metricData[0];
                      const isHealthy = latest.p95 < 50; // Under 50ms target
                      
                      return (
                        <div key={metricName} className="p-4 border rounded-lg">
                          <div className="flex items-center justify-between mb-4">
                            <div className="flex items-center gap-2">
                              <div className={`w-3 h-3 rounded-full ${isHealthy ? 'bg-green-500' : 'bg-yellow-500'}`} />
                              <h4 className="font-semibold">
                                {metricName === 'validation_latency_ms' ? 'Validation Latency' : 'Inventory Processing'}
                              </h4>
                            </div>
                            <span className={`text-sm ${isHealthy ? 'text-green-600' : 'text-yellow-600'}`}>
                              {isHealthy ? 'Healthy' : 'Above Target'}
                            </span>
                          </div>
                          
                          <div className="grid grid-cols-5 gap-4 text-center">
                            <div>
                              <p className="text-sm text-muted-foreground">Samples</p>
                              <p className="text-lg font-semibold">{latest.sampleCount}</p>
                            </div>
                            <div>
                              <p className="text-sm text-muted-foreground">Average</p>
                              <p className="text-lg font-semibold">{latest.avgValue.toFixed(1)}ms</p>
                            </div>
                            <div>
                              <p className="text-sm text-muted-foreground">P50</p>
                              <p className="text-lg font-semibold">{latest.p50.toFixed(1)}ms</p>
                            </div>
                            <div>
                              <p className="text-sm text-muted-foreground">P95</p>
                              <p className={`text-lg font-semibold ${latest.p95 > 50 ? 'text-yellow-600' : ''}`}>
                                {latest.p95.toFixed(1)}ms
                              </p>
                            </div>
                            <div>
                              <p className="text-sm text-muted-foreground">P99</p>
                              <p className="text-lg font-semibold">{latest.p99.toFixed(1)}ms</p>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>
          </motion.div>
        )}

        {activeTab === 'migration' && (
          <motion.div
            key="migration"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-4"
          >
            {/* Migration Tool */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <RefreshCw className="h-5 w-5" />
                  Menu Modifiers Migration
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <p className="text-muted-foreground">
                  Migrate existing menu modifier groups and options to the unified customization system.
                  This is a one-time operation that copies data without deleting the original.
                </p>
                <div className="flex items-center gap-4">
                  <Button
                    onClick={() => {
                      if (confirm('This will migrate all menu modifiers to the unified system. Continue?')) {
                        migrateMutation.mutate();
                      }
                    }}
                    disabled={migrateMutation.isPending}
                  >
                    {migrateMutation.isPending ? (
                      <>
                        <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                        Migrating...
                      </>
                    ) : (
                      <>
                        <RefreshCw className="h-4 w-4 mr-2" />
                        Run Migration
                      </>
                    )}
                  </Button>
                </div>
              </CardContent>
            </Card>

            {/* Dual-Write Stats */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Activity className="h-5 w-5" />
                  Dual-Write Monitoring
                </CardTitle>
              </CardHeader>
              <CardContent>
                {!dualWriteStats ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Activity className="h-12 w-12 mx-auto mb-4 opacity-50" />
                    <p>No dual-write data available</p>
                    <p className="text-sm">Data will appear when dual-write is enabled</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <div className="grid grid-cols-4 gap-4">
                      <div className="p-4 border rounded-lg text-center">
                        <p className="text-sm text-muted-foreground">Total Operations</p>
                        <p className="text-2xl font-bold">{dualWriteStats.total}</p>
                      </div>
                      <div className="p-4 border rounded-lg text-center">
                        <p className="text-sm text-muted-foreground">Matches</p>
                        <p className="text-2xl font-bold text-green-600">{dualWriteStats.matches}</p>
                      </div>
                      <div className="p-4 border rounded-lg text-center">
                        <p className="text-sm text-muted-foreground">Mismatches</p>
                        <p className="text-2xl font-bold text-red-600">{dualWriteStats.mismatches}</p>
                      </div>
                      <div className="p-4 border rounded-lg text-center">
                        <p className="text-sm text-muted-foreground">Match Rate</p>
                        <p className={`text-2xl font-bold ${
                          dualWriteStats.matchRate >= 99 ? 'text-green-600' : 
                          dualWriteStats.matchRate >= 95 ? 'text-yellow-600' : 'text-red-600'
                        }`}>
                          {dualWriteStats.matchRate.toFixed(1)}%
                        </p>
                      </div>
                    </div>
                    
                    {dualWriteStats.matchRate < 100 && (
                      <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
                        <div className="flex items-center gap-2">
                          <AlertTriangle className="h-5 w-5 text-yellow-600" />
                          <p className="font-medium text-yellow-800 dark:text-yellow-200">
                            Discrepancies detected
                          </p>
                        </div>
                        <p className="text-sm text-yellow-700 dark:text-yellow-300 mt-1">
                          Review the discrepancies before proceeding with migration cutover.
                        </p>
                      </div>
                    )}
                  </div>
                )}
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Group Dialog */}
      <GroupDialog
        open={isGroupDialogOpen}
        onOpenChange={setIsGroupDialogOpen}
        group={selectedGroup}
        availableEntityTypes={ENTITY_TYPE_LABELS}
        onSubmit={(data) => {
          if (selectedGroup) {
            updateGroupMutation.mutate({ id: selectedGroup.id, data });
          } else {
            createGroupMutation.mutate(data);
          }
        }}
        isLoading={createGroupMutation.isPending || updateGroupMutation.isPending}
      />

      {/* Option Dialog */}
      <OptionDialog
        open={isOptionDialogOpen}
        onOpenChange={setIsOptionDialogOpen}
        groupId={selectedGroup?.id || ''}
        option={editingOption}
        onSubmit={(data) => {
          if (editingOption) {
            updateOptionMutation.mutate({ id: editingOption.id, data });
          } else {
            createOptionMutation.mutate({ ...data, groupId: selectedGroup?.id });
          }
        }}
        isLoading={createOptionMutation.isPending || updateOptionMutation.isPending}
      />
    </motion.div>
  );
}

// Group Dialog Component
function GroupDialog({
  open,
  onOpenChange,
  group,
  availableEntityTypes,
  onSubmit,
  isLoading,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  group: CustomizationGroup | null;
  availableEntityTypes: Record<string, string>;
  onSubmit: (data: Partial<CustomizationGroup>) => void;
  isLoading: boolean;
}) {
  const [formData, setFormData] = useState<Partial<CustomizationGroup>>({
    name: '',
    nameAr: '',
    description: '',
    selectionMode: 'single',
    minSelections: 0,
    maxSelections: 1,
    isRequired: false,
    applicableEntityTypes: [],
    isGlobal: false,
    isAvailable: true,
  });

  useEffect(() => {
    if (group) {
      setFormData(group);
    } else {
      setFormData({
        name: '',
        nameAr: '',
        description: '',
        selectionMode: 'single',
        minSelections: 0,
        maxSelections: 1,
        isRequired: false,
        applicableEntityTypes: [],
        isGlobal: false,
        isAvailable: true,
      });
    }
  }, [group, open]);

  const toggleEntityType = (type: string) => {
    const current = formData.applicableEntityTypes || [];
    if (current.includes(type)) {
      setFormData({ ...formData, applicableEntityTypes: current.filter(t => t !== type) });
    } else {
      setFormData({ ...formData, applicableEntityTypes: [...current, type] });
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>{group ? 'Edit Group' : 'Create Group'}</DialogTitle>
        </DialogHeader>
        
        <div className="space-y-4 py-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Name (English)</label>
              <Input
                value={formData.name || ''}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="e.g., Size"
                className="bg-card text-foreground border-border"
              />
            </div>
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Name (Arabic)</label>
              <Input
                value={formData.nameAr || ''}
                onChange={(e) => setFormData({ ...formData, nameAr: e.target.value })}
                placeholder="e.g., الحجم"
                dir="rtl"
                className="bg-card text-foreground border-border"
              />
            </div>
          </div>

          <div>
            <label className="text-sm font-semibold text-foreground block mb-1">Description</label>
            <Input
              value={formData.description || ''}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Optional description"
              className="bg-card text-foreground border-border"
            />
          </div>

          <div>
            <label className="text-sm font-semibold text-foreground block mb-1">Selection Mode</label>
            <select
              className="w-full px-3 py-2 border border-border rounded-md bg-card text-foreground focus:outline-none focus:ring-2 focus:ring-primary"
              value={formData.selectionMode}
              onChange={(e) => setFormData({ ...formData, selectionMode: e.target.value as SelectionMode })}
            >
              {Object.entries(SELECTION_MODE_LABELS).map(([value, label]) => (
                <option key={value} value={value} className="bg-card text-foreground">{label}</option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Min Selections</label>
              <Input
                type="number"
                min={0}
                value={formData.minSelections || 0}
                onChange={(e) => setFormData({ ...formData, minSelections: parseInt(e.target.value) || 0 })}
                className="bg-card text-foreground border-border"
              />
            </div>
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Max Selections</label>
              <Input
                type="number"
                min={1}
                value={formData.maxSelections || 1}
                onChange={(e) => setFormData({ ...formData, maxSelections: parseInt(e.target.value) || 1 })}
                className="bg-card text-foreground border-border"
              />
            </div>
          </div>

          <div>
            <label className="text-sm font-medium text-foreground mb-2 block">Applicable Entity Types</label>
            <div className="flex flex-wrap gap-2">
              {Object.entries(availableEntityTypes).map(([value, label]) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => toggleEntityType(value)}
                  className={`px-3 py-1.5 text-sm font-medium rounded-full border transition-colors ${
                    formData.applicableEntityTypes?.includes(value)
                      ? 'bg-primary text-primary-foreground border-primary'
                      : 'bg-card text-foreground border-border hover:bg-muted'
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>
            {Object.keys(availableEntityTypes).length === 0 && (
              <p className="text-sm text-muted-foreground mt-2">No active modules found. Please enable modules first.</p>
            )}
          </div>

          <div className="flex items-center gap-6 pt-2">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={formData.isRequired || false}
                onChange={(e) => setFormData({ ...formData, isRequired: e.target.checked })}
                className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
              />
              <span className="text-sm font-medium text-foreground">Required</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={formData.isGlobal || false}
                onChange={(e) => setFormData({ ...formData, isGlobal: e.target.checked })}
                className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
              />
              <span className="text-sm font-medium text-foreground">Global</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={formData.isAvailable !== false}
                onChange={(e) => setFormData({ ...formData, isAvailable: e.target.checked })}
                className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
              />
              <span className="text-sm font-medium text-foreground">Available</span>
            </label>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button 
            onClick={() => onSubmit(formData)} 
            disabled={isLoading || !formData.name || !formData.applicableEntityTypes?.length}
          >
            {isLoading ? 'Saving...' : group ? 'Update' : 'Create'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// Option Dialog Component
function OptionDialog({
  open,
  onOpenChange,
  groupId,
  option,
  onSubmit,
  isLoading,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  groupId: string;
  option: CustomizationOption | null;
  onSubmit: (data: Partial<CustomizationOption>) => void;
  isLoading: boolean;
}) {
  const [formData, setFormData] = useState<Partial<CustomizationOption>>({
    name: '',
    nameAr: '',
    customizationType: 'add',
    priceAdjustment: 0,
    priceType: 'fixed',
    quantityPerSelection: 1,
    maxQuantity: 10,
    isDefault: false,
    isPopular: false,
    isAvailable: true,
  });

  useEffect(() => {
    if (option) {
      setFormData(option);
    } else {
      setFormData({
        name: '',
        nameAr: '',
        customizationType: 'add',
        priceAdjustment: 0,
        priceType: 'fixed',
        quantityPerSelection: 1,
        maxQuantity: 10,
        isDefault: false,
        isPopular: false,
        isAvailable: true,
      });
    }
  }, [option, open]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>{option ? 'Edit Option' : 'Create Option'}</DialogTitle>
        </DialogHeader>
        
        <div className="space-y-4 py-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Name (English)</label>
              <Input
                value={formData.name || ''}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="e.g., Large"
                className="bg-card text-foreground border-border"
              />
            </div>
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Name (Arabic)</label>
              <Input
                value={formData.nameAr || ''}
                onChange={(e) => setFormData({ ...formData, nameAr: e.target.value })}
                placeholder="e.g., كبير"
                dir="rtl"
                className="bg-card text-foreground border-border"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Customization Type</label>
              <select
                className="w-full px-3 py-2 border border-border rounded-md bg-card text-foreground focus:outline-none focus:ring-2 focus:ring-primary"
                value={formData.customizationType}
                onChange={(e) => setFormData({ ...formData, customizationType: e.target.value as CustomizationType })}
              >
                {Object.entries(CUSTOMIZATION_TYPE_LABELS).map(([value, label]) => (
                  <option key={value} value={value} className="bg-card text-foreground">{label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Price Type</label>
              <select
                className="w-full px-3 py-2 border border-border rounded-md bg-card text-foreground focus:outline-none focus:ring-2 focus:ring-primary"
                value={formData.priceType}
                onChange={(e) => setFormData({ ...formData, priceType: e.target.value as PriceType })}
              >
                <option value="fixed" className="bg-card text-foreground">Fixed</option>
                <option value="percentage" className="bg-card text-foreground">Percentage</option>
                <option value="per_unit" className="bg-card text-foreground">Per Unit</option>
                <option value="per_night" className="bg-card text-foreground">Per Night</option>
                <option value="per_person" className="bg-card text-foreground">Per Person</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Price Adjustment</label>
              <Input
                type="number"
                step="0.01"
                value={formData.priceAdjustment || 0}
                onChange={(e) => setFormData({ ...formData, priceAdjustment: parseFloat(e.target.value) || 0 })}
                className="bg-card text-foreground border-border"
              />
            </div>
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Qty Per Selection</label>
              <Input
                type="number"
                min={1}
                value={formData.quantityPerSelection || 1}
                onChange={(e) => setFormData({ ...formData, quantityPerSelection: parseFloat(e.target.value) || 1 })}
                className="bg-card text-foreground border-border"
              />
            </div>
            <div>
              <label className="text-sm font-semibold text-foreground block mb-1">Max Quantity</label>
              <Input
                type="number"
                min={1}
                value={formData.maxQuantity || 10}
                onChange={(e) => setFormData({ ...formData, maxQuantity: parseInt(e.target.value) || 10 })}
                className="bg-card text-foreground border-border"
              />
            </div>
          </div>

          <div>
            <label className="text-sm font-semibold text-foreground block mb-1">Inventory Item ID (optional)</label>
            <Input
              value={formData.inventoryItemId || ''}
              onChange={(e) => setFormData({ ...formData, inventoryItemId: e.target.value || undefined })}
              placeholder="UUID of inventory item"
              className="bg-card text-foreground border-border"
            />
          </div>

          <div className="flex items-center gap-6 pt-2">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={formData.isDefault || false}
                onChange={(e) => setFormData({ ...formData, isDefault: e.target.checked })}
                className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
              />
              <span className="text-sm font-medium text-foreground">Default</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={formData.isPopular || false}
                onChange={(e) => setFormData({ ...formData, isPopular: e.target.checked })}
                className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
              />
              <span className="text-sm font-medium text-foreground">Popular</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={formData.isAvailable !== false}
                onChange={(e) => setFormData({ ...formData, isAvailable: e.target.checked })}
                className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
              />
              <span className="text-sm font-medium text-foreground">Available</span>
            </label>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button 
            onClick={() => onSubmit(formData)} 
            disabled={isLoading || !formData.name}
          >
            {isLoading ? 'Saving...' : option ? 'Update' : 'Create'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/Tabs';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  CreditCard,
  Gift,
  DollarSign,
  TrendingUp,
  Search,
  Plus,
  Edit,
  Eye,
  EyeOff,
  RefreshCw,
  Copy,
  Ban,
  CheckCircle,
  Clock,
  AlertTriangle,
  Package,
} from 'lucide-react';

interface GiftCard {
  id: string;
  code: string;
  initial_value: number;
  current_balance: number;
  status: 'active' | 'redeemed' | 'expired' | 'disabled';
  purchaser_name?: string;
  purchaser_email?: string;
  recipient_name?: string;
  recipient_email?: string;
  expires_at?: string;
  created_at: string;
}

interface GiftCardTemplate {
  id: string;
  name: string;
  amount: number;
  discount_percent: number;
  image_url?: string;
  is_active: boolean;
}

interface GiftCardStats {
  totalCards: number;
  activeCards: number;
  totalValueSold: number;
  totalValueRedeemed: number;
  unredeeemedValue: number;
}

export default function GiftCardsAdminPage() {
  const [activeTab, setActiveTab] = useState('cards');
  const [giftCards, setGiftCards] = useState<GiftCard[]>([]);
  const [templates, setTemplates] = useState<GiftCardTemplate[]>([]);
  const [stats, setStats] = useState<GiftCardStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [selectedCard, setSelectedCard] = useState<GiftCard | null>(null);
  const [visibleCodes, setVisibleCodes] = useState<Set<string>>(new Set());
  
  // Create form state
  const [createForm, setCreateForm] = useState({
    initialValue: '',
    recipientName: '',
    recipientEmail: '',
    message: '',
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [cardsRes, templatesRes, statsRes] = await Promise.all([
        api.get('/giftcards/admin'),
        api.get('/giftcards/templates'),
        api.get('/giftcards/admin/stats'),
      ]);

      if (cardsRes.data.success) setGiftCards(cardsRes.data.data);
      if (templatesRes.data.success) setTemplates(templatesRes.data.data);
      if (statsRes.data.success) {
        const s = statsRes.data.data.summary;
        if (s) {
          setStats({
            totalCards: s.total_cards || 0,
            activeCards: s.active_cards || 0,
            totalValueSold: s.total_sold || 0,
            totalValueRedeemed: s.total_redeemed || 0,
            unredeeemedValue: s.outstanding_balance || 0,
          });
        }
      }
    } catch (error) {
      toast.error('Failed to load gift card data');
    } finally {
      setLoading(false);
    }
  };

  const toggleCodeVisibility = (cardId: string) => {
    const newVisible = new Set(visibleCodes);
    if (newVisible.has(cardId)) {
      newVisible.delete(cardId);
    } else {
      newVisible.add(cardId);
    }
    setVisibleCodes(newVisible);
  };

  const copyCode = (code: string) => {
    navigator.clipboard.writeText(code);
    toast.success('Code copied to clipboard');
  };

  const handleCreateCard = async () => {
    if (!createForm.initialValue) {
      toast.error('Please enter a value');
      return;
    }
    
    try {
      const res = await api.post('/giftcards/admin', {
        initialValue: parseFloat(createForm.initialValue),
        recipientName: createForm.recipientName || undefined,
        recipientEmail: createForm.recipientEmail || undefined,
        personalMessage: createForm.message || undefined,
      });
      
      if (res.data.success) {
        toast.success(`Gift card created: ${res.data.data.code}`);
        setShowCreateModal(false);
        setCreateForm({ initialValue: '', recipientName: '', recipientEmail: '', message: '' });
        loadData();
      }
    } catch (error) {
      toast.error('Failed to create gift card');
    }
  };

  const handleDisableCard = async (cardId: string) => {
    try {
      const res = await api.put(`/giftcards/admin/${cardId}/disable`);
      if (res.data.success) {
        toast.success('Gift card disabled');
        loadData();
      }
    } catch (error) {
      toast.error('Failed to disable gift card');
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'active':
        return <Badge className="bg-green-100 text-green-700">Active</Badge>;
      case 'redeemed':
        return <Badge className="bg-blue-100 text-blue-700">Fully Redeemed</Badge>;
      case 'expired':
        return <Badge className="bg-amber-100 text-amber-700">Expired</Badge>;
      case 'disabled':
        return <Badge className="bg-red-100 text-red-700">Disabled</Badge>;
      default:
        return <Badge>{status}</Badge>;
    }
  };

  const filteredCards = giftCards.filter(card => {
    const matchesSearch = searchQuery === '' || 
      card.code.toLowerCase().includes(searchQuery.toLowerCase()) ||
      card.recipient_email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      card.purchaser_email?.toLowerCase().includes(searchQuery.toLowerCase());
    
    const matchesStatus = statusFilter === 'all' || card.status === statusFilter;
    
    return matchesSearch && matchesStatus;
  });

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <RefreshCw className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Gift Cards</h1>
          <p className="text-slate-500 dark:text-slate-400">Manage gift cards and templates</p>
        </div>
        <div className="flex gap-2">
          <Button onClick={() => loadData()} variant="outline" className="gap-2">
            <RefreshCw className="w-4 h-4" />
            Refresh
          </Button>
          <Button onClick={() => setShowCreateModal(true)} className="gap-2">
            <Plus className="w-4 h-4" />
            Create Gift Card
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-5 gap-4">
        <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-blue-100 text-sm">Total Cards</p>
                <p className="text-3xl font-bold">{stats?.totalCards || 0}</p>
              </div>
              <CreditCard className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-green-100 text-sm">Active Cards</p>
                <p className="text-3xl font-bold">{stats?.activeCards || 0}</p>
              </div>
              <CheckCircle className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-amber-500 to-amber-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-amber-100 text-sm">Value Sold</p>
                <p className="text-3xl font-bold">{formatCurrency(stats?.totalValueSold || 0)}</p>
              </div>
              <DollarSign className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-purple-100 text-sm">Redeemed</p>
                <p className="text-3xl font-bold">{formatCurrency(stats?.totalValueRedeemed || 0)}</p>
              </div>
              <Gift className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-rose-500 to-rose-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-rose-100 text-sm">Outstanding</p>
                <p className="text-3xl font-bold">{formatCurrency(stats?.unredeeemedValue || 0)}</p>
              </div>
              <TrendingUp className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid grid-cols-2 w-full max-w-xs">
          <TabsTrigger value="cards">Gift Cards</TabsTrigger>
          <TabsTrigger value="templates">Templates</TabsTrigger>
        </TabsList>

        {/* Gift Cards Tab */}
        <TabsContent value="cards" className="space-y-4">
          <div className="flex gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
              <Input
                placeholder="Search by code or email..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
            >
              <option value="all">All Status</option>
              <option value="active">Active</option>
              <option value="redeemed">Redeemed</option>
              <option value="expired">Expired</option>
              <option value="disabled">Disabled</option>
            </select>
          </div>

          <Card>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b dark:border-slate-700">
                      <th className="text-left p-4 font-medium text-slate-500">Code</th>
                      <th className="text-left p-4 font-medium text-slate-500">Value</th>
                      <th className="text-left p-4 font-medium text-slate-500">Balance</th>
                      <th className="text-left p-4 font-medium text-slate-500">Status</th>
                      <th className="text-left p-4 font-medium text-slate-500">Recipient</th>
                      <th className="text-left p-4 font-medium text-slate-500">Created</th>
                      <th className="text-right p-4 font-medium text-slate-500">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredCards.map((card) => (
                      <tr key={card.id} className="border-b dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800">
                        <td className="p-4">
                          <div className="flex items-center gap-2">
                            <code className="font-mono text-sm bg-slate-100 dark:bg-slate-700 px-2 py-1 rounded">
                              {visibleCodes.has(card.id) ? card.code : '••••-••••-••••-••••'}
                            </code>
                            <Button 
                              variant="ghost" 
                              size="sm"
                              onClick={() => toggleCodeVisibility(card.id)}
                            >
                              {visibleCodes.has(card.id) ? (
                                <EyeOff className="w-4 h-4" />
                              ) : (
                                <Eye className="w-4 h-4" />
                              )}
                            </Button>
                            {visibleCodes.has(card.id) && (
                              <Button 
                                variant="ghost" 
                                size="sm"
                                onClick={() => copyCode(card.code)}
                              >
                                <Copy className="w-4 h-4" />
                              </Button>
                            )}
                          </div>
                        </td>
                        <td className="p-4 font-medium">
                          {formatCurrency(card.initial_value)}
                        </td>
                        <td className="p-4">
                          <span className={card.current_balance > 0 ? 'text-green-600 font-semibold' : 'text-slate-400'}>
                            {formatCurrency(card.current_balance)}
                          </span>
                        </td>
                        <td className="p-4">
                          {getStatusBadge(card.status)}
                        </td>
                        <td className="p-4">
                          {card.recipient_email ? (
                            <div className="text-sm">
                              <p>{card.recipient_name || '-'}</p>
                              <p className="text-slate-500">{card.recipient_email}</p>
                            </div>
                          ) : (
                            <span className="text-slate-400">-</span>
                          )}
                        </td>
                        <td className="p-4 text-slate-500">
                          {formatDate(card.created_at)}
                        </td>
                        <td className="p-4 text-right">
                          <div className="flex justify-end gap-1">
                            <Button 
                              variant="ghost" 
                              size="sm"
                              onClick={() => { setSelectedCard(card); setShowDetailsModal(true); }}
                            >
                              <Eye className="w-4 h-4" />
                            </Button>
                            {card.status === 'active' && (
                              <Button 
                                variant="ghost" 
                                size="sm"
                                onClick={() => handleDisableCard(card.id)}
                                className="text-red-500 hover:text-red-700"
                              >
                                <Ban className="w-4 h-4" />
                              </Button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Templates Tab */}
        <TabsContent value="templates" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {templates.map((template) => (
              <Card key={template.id} className={`relative overflow-hidden ${!template.is_active ? 'opacity-50' : ''}`}>
                <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-blue-500 to-purple-500" />
                <CardContent className="p-6">
                  <div className="flex items-start justify-between mb-4">
                    <div className="w-12 h-12 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center">
                      <Gift className="w-6 h-6 text-blue-600 dark:text-blue-400" />
                    </div>
                    <Badge className={template.is_active ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-500'}>
                      {template.is_active ? 'Active' : 'Inactive'}
                    </Badge>
                  </div>
                  <h3 className="text-xl font-bold mb-1">{template.name}</h3>
                  <p className="text-3xl font-bold text-blue-600 mb-2">
                    {formatCurrency(template.amount)}
                  </p>
                  {template.discount_percent > 0 && (
                    <Badge className="bg-amber-100 text-amber-700">
                      {template.discount_percent}% off
                    </Badge>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>
      </Tabs>

      {/* Create Gift Card Modal */}
      <AnimatePresence>
        {showCreateModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]"
            onClick={() => setShowCreateModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
            >
              <h3 className="text-xl font-bold mb-4">Create Gift Card</h3>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-2">Value ($)</label>
                  <Input
                    type="number"
                    placeholder="Enter gift card value"
                    value={createForm.initialValue}
                    onChange={(e) => setCreateForm(f => ({ ...f, initialValue: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Recipient Name (optional)</label>
                  <Input
                    placeholder="Recipient name"
                    value={createForm.recipientName}
                    onChange={(e) => setCreateForm(f => ({ ...f, recipientName: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Recipient Email (optional)</label>
                  <Input
                    type="email"
                    placeholder="Recipient email"
                    value={createForm.recipientEmail}
                    onChange={(e) => setCreateForm(f => ({ ...f, recipientEmail: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Message (optional)</label>
                  <textarea
                    className="w-full p-3 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                    rows={3}
                    placeholder="Personal message"
                    value={createForm.message}
                    onChange={(e) => setCreateForm(f => ({ ...f, message: e.target.value }))}
                  />
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => setShowCreateModal(false)}>
                  Cancel
                </Button>
                <Button onClick={handleCreateCard}>
                  Create Gift Card
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Card Details Modal */}
      <AnimatePresence>
        {showDetailsModal && selectedCard && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]"
            onClick={() => setShowDetailsModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
            >
              <h3 className="text-xl font-bold mb-4">Gift Card Details</h3>
              
              <div className="space-y-4">
                <div className="p-4 bg-slate-100 dark:bg-slate-700 rounded-lg">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm text-slate-500">Code</span>
                    <Button variant="ghost" size="sm" onClick={() => copyCode(selectedCard.code)}>
                      <Copy className="w-4 h-4" />
                    </Button>
                  </div>
                  <code className="font-mono text-lg font-bold">{selectedCard.code}</code>
                </div>
                
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <span className="text-sm text-slate-500">Original Value</span>
                    <p className="font-bold">{formatCurrency(selectedCard.initial_value)}</p>
                  </div>
                  <div>
                    <span className="text-sm text-slate-500">Current Balance</span>
                    <p className="font-bold text-green-600">{formatCurrency(selectedCard.current_balance)}</p>
                  </div>
                  <div>
                    <span className="text-sm text-slate-500">Status</span>
                    <div className="mt-1">{getStatusBadge(selectedCard.status)}</div>
                  </div>
                  <div>
                    <span className="text-sm text-slate-500">Created</span>
                    <p>{formatDate(selectedCard.created_at)}</p>
                  </div>
                </div>
                
                {selectedCard.recipient_email && (
                  <div>
                    <span className="text-sm text-slate-500">Recipient</span>
                    <p>{selectedCard.recipient_name}</p>
                    <p className="text-sm text-slate-500">{selectedCard.recipient_email}</p>
                  </div>
                )}
                
                {selectedCard.purchaser_email && (
                  <div>
                    <span className="text-sm text-slate-500">Purchaser</span>
                    <p>{selectedCard.purchaser_name}</p>
                    <p className="text-sm text-slate-500">{selectedCard.purchaser_email}</p>
                  </div>
                )}
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => setShowDetailsModal(false)}>
                  Close
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/Tabs';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  ClipboardList,
  Clock,
  CheckCircle,
  AlertTriangle,
  Users,
  Calendar,
  Plus,
  RefreshCw,
  Play,
  Pause,
  Check,
  Flag,
  Filter,
  Home,
  User,
  Timer,
  TrendingUp,
  BarChart3,
} from 'lucide-react';

interface Task {
  id: string;
  chalet_id?: string;
  chalet_name?: string;
  room_number?: string;
  task_type_id: string;
  task_type_name: string;
  priority: 'low' | 'normal' | 'high' | 'urgent';
  status: 'pending' | 'in_progress' | 'completed' | 'cancelled' | 'on_hold';
  notes?: string;
  assigned_to?: string;
  assigned_to_name?: string;
  scheduled_for?: string;
  started_at?: string;
  completed_at?: string;
  estimated_duration?: number;
  created_at: string;
}

interface TaskType {
  id: string;
  name: string;
  estimated_duration: number;
  checklist?: any;
  is_active: boolean;
}

interface Staff {
  id: string;
  name: string;
  email: string;
  active_tasks: number;
}

interface Stats {
  pending: number;
  in_progress: number;
  completed_today: number;
  total_completed: number;
  on_hold: number;
  urgent: number;
}

interface StaffPerformance {
  id: string;
  name: string;
  tasks_completed: number;
  avg_time_minutes: number;
}

export default function HousekeepingAdminPage() {
  const [activeTab, setActiveTab] = useState('tasks');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [taskTypes, setTaskTypes] = useState<TaskType[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [staffPerformance, setStaffPerformance] = useState<StaffPerformance[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('active');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [assignedFilter, setAssignedFilter] = useState('all');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  
  // Create form state
  const [createForm, setCreateForm] = useState({
    chaletId: '',
    taskTypeId: '',
    priority: 'normal',
    notes: '',
    assignedTo: '',
    scheduledFor: '',
  });

  useEffect(() => {
    loadData();
  }, [statusFilter, priorityFilter, assignedFilter]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [tasksRes, typesRes, staffRes, statsRes] = await Promise.all([
        api.get('/housekeeping/tasks', {
          params: {
            status: statusFilter === 'all' ? undefined : statusFilter,
            priority: priorityFilter === 'all' ? undefined : priorityFilter,
            assignedTo: assignedFilter === 'all' ? undefined : assignedFilter,
          }
        }),
        api.get('/housekeeping/task-types'),
        api.get('/housekeeping/staff'),
        api.get('/housekeeping/stats'),
      ]);

      if (tasksRes.data.success) setTasks(tasksRes.data.data);
      if (typesRes.data.success) setTaskTypes(typesRes.data.data);
      if (staffRes.data.success) setStaff(staffRes.data.data);
      if (statsRes.data.success) {
        setStats(statsRes.data.data.summary);
        setStaffPerformance(statsRes.data.data.staffPerformance || []);
      }
    } catch (error) {
      toast.error('Failed to load housekeeping data');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTask = async () => {
    if (!createForm.taskTypeId) {
      toast.error('Please select a task type');
      return;
    }
    
    try {
      const res = await api.post('/housekeeping/tasks', {
        chaletId: createForm.chaletId || undefined,
        taskTypeId: createForm.taskTypeId,
        priority: createForm.priority,
        notes: createForm.notes || undefined,
        assignedTo: createForm.assignedTo || undefined,
        scheduledFor: createForm.scheduledFor || new Date().toISOString(),
      });
      
      if (res.data.success) {
        toast.success('Task created');
        setShowCreateModal(false);
        setCreateForm({
          chaletId: '',
          taskTypeId: '',
          priority: 'normal',
          notes: '',
          assignedTo: '',
          scheduledFor: '',
        });
        loadData();
      }
    } catch (error) {
      toast.error('Failed to create task');
    }
  };

  const handleAssignTask = async (taskId: string, staffId: string) => {
    try {
      const res = await api.post(`/housekeeping/tasks/${taskId}/assign`, { staffId });
      if (res.data.success) {
        toast.success('Task assigned');
        setShowAssignModal(false);
        setSelectedTask(null);
        loadData();
      }
    } catch (error) {
      toast.error('Failed to assign task');
    }
  };

  const handleUpdateStatus = async (taskId: string, newStatus: string) => {
    try {
      let endpoint = `/housekeeping/tasks/${taskId}`;
      let method = 'put';
      let payload: any = { status: newStatus };
      
      if (newStatus === 'in_progress') {
        endpoint = `/housekeeping/tasks/${taskId}/start`;
        method = 'post';
        payload = {};
      } else if (newStatus === 'completed') {
        endpoint = `/housekeeping/tasks/${taskId}/complete`;
        method = 'post';
        payload = {};
      }
      
      const res = method === 'post' 
        ? await api.post(endpoint, payload)
        : await api.put(endpoint, payload);
      
      if (res.data.success) {
        toast.success('Task updated');
        loadData();
      }
    } catch (error) {
      toast.error('Failed to update task');
    }
  };

  const getPriorityBadge = (priority: string) => {
    const styles: Record<string, string> = {
      urgent: 'bg-red-100 text-red-700 border-red-200',
      high: 'bg-orange-100 text-orange-700 border-orange-200',
      normal: 'bg-blue-100 text-blue-700 border-blue-200',
      low: 'bg-slate-100 text-slate-600 border-slate-200',
    };
    return <Badge className={styles[priority] || styles.normal}>{priority}</Badge>;
  };

  const getStatusBadge = (status: string) => {
    const styles: Record<string, { bg: string; icon: React.ReactNode }> = {
      pending: { bg: 'bg-amber-100 text-amber-700', icon: <Clock className="w-3 h-3" /> },
      in_progress: { bg: 'bg-blue-100 text-blue-700', icon: <Play className="w-3 h-3" /> },
      completed: { bg: 'bg-green-100 text-green-700', icon: <Check className="w-3 h-3" /> },
      cancelled: { bg: 'bg-slate-100 text-slate-500', icon: <Pause className="w-3 h-3" /> },
      on_hold: { bg: 'bg-red-100 text-red-700', icon: <AlertTriangle className="w-3 h-3" /> },
    };
    const style = styles[status] || styles.pending;
    return (
      <Badge className={`flex items-center gap-1 ${style.bg}`}>
        {style.icon}
        {status.replace('_', ' ')}
      </Badge>
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <RefreshCw className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Housekeeping</h1>
          <p className="text-slate-500 dark:text-slate-400">Task management and scheduling</p>
        </div>
        <div className="flex gap-2">
          <Button onClick={() => loadData()} variant="outline" className="gap-2">
            <RefreshCw className="w-4 h-4" />
            Refresh
          </Button>
          <Button onClick={() => setShowCreateModal(true)} className="gap-2">
            <Plus className="w-4 h-4" />
            New Task
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <motion.div variants={fadeInUp} className="grid grid-cols-2 md:grid-cols-6 gap-4">
        <Card className="bg-gradient-to-br from-amber-500 to-amber-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-amber-100 text-xs">Pending</p>
                <p className="text-2xl font-bold">{stats?.pending || 0}</p>
              </div>
              <Clock className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-blue-100 text-xs">In Progress</p>
                <p className="text-2xl font-bold">{stats?.in_progress || 0}</p>
              </div>
              <Play className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-green-100 text-xs">Done Today</p>
                <p className="text-2xl font-bold">{stats?.completed_today || 0}</p>
              </div>
              <CheckCircle className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-purple-100 text-xs">Total Done</p>
                <p className="text-2xl font-bold">{stats?.total_completed || 0}</p>
              </div>
              <TrendingUp className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-red-500 to-red-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-red-100 text-xs">On Hold</p>
                <p className="text-2xl font-bold">{stats?.on_hold || 0}</p>
              </div>
              <AlertTriangle className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-rose-500 to-rose-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-rose-100 text-xs">Urgent</p>
                <p className="text-2xl font-bold">{stats?.urgent || 0}</p>
              </div>
              <Flag className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid grid-cols-3 w-full max-w-md">
          <TabsTrigger value="tasks">Tasks</TabsTrigger>
          <TabsTrigger value="staff">Staff</TabsTrigger>
          <TabsTrigger value="stats">Statistics</TabsTrigger>
        </TabsList>

        {/* Tasks Tab */}
        <TabsContent value="tasks" className="space-y-4">
          <div className="flex flex-wrap gap-4">
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
            >
              <option value="all">All Status</option>
              <option value="active">Active</option>
              <option value="pending">Pending</option>
              <option value="in_progress">In Progress</option>
              <option value="completed">Completed</option>
              <option value="on_hold">On Hold</option>
            </select>
            
            <select
              value={priorityFilter}
              onChange={(e) => setPriorityFilter(e.target.value)}
              className="px-4 py-2 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
            >
              <option value="all">All Priorities</option>
              <option value="urgent">Urgent</option>
              <option value="high">High</option>
              <option value="normal">Normal</option>
              <option value="low">Low</option>
            </select>
            
            <select
              value={assignedFilter}
              onChange={(e) => setAssignedFilter(e.target.value)}
              className="px-4 py-2 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
            >
              <option value="all">All Staff</option>
              <option value="unassigned">Unassigned</option>
              {staff.map(s => (
                <option key={s.id} value={s.id}>{s.name}</option>
              ))}
            </select>
          </div>

          <div className="grid gap-4">
            {tasks.map((task) => (
              <Card key={task.id} className="hover:shadow-md transition-shadow">
                <CardContent className="p-4">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        {getPriorityBadge(task.priority)}
                        {getStatusBadge(task.status)}
                        {task.chalet_name && (
                          <Badge variant="outline" className="flex items-center gap-1">
                            <Home className="w-3 h-3" />
                            {task.chalet_name}
                          </Badge>
                        )}
                      </div>
                      
                      <h3 className="font-semibold text-lg">{task.task_type_name}</h3>
                      
                      {task.notes && (
                        <p className="text-sm text-slate-500 mt-1">{task.notes}</p>
                      )}
                      
                      <div className="flex items-center gap-4 mt-3 text-sm text-slate-500">
                        {task.assigned_to_name ? (
                          <span className="flex items-center gap-1">
                            <User className="w-4 h-4" />
                            {task.assigned_to_name}
                          </span>
                        ) : (
                          <span className="flex items-center gap-1 text-amber-500">
                            <AlertTriangle className="w-4 h-4" />
                            Unassigned
                          </span>
                        )}
                        
                        {task.scheduled_for && (
                          <span className="flex items-center gap-1">
                            <Calendar className="w-4 h-4" />
                            {formatDate(task.scheduled_for)}
                          </span>
                        )}
                        
                        {task.estimated_duration && (
                          <span className="flex items-center gap-1">
                            <Timer className="w-4 h-4" />
                            ~{task.estimated_duration} min
                          </span>
                        )}
                      </div>
                    </div>
                    
                    <div className="flex gap-2">
                      {!task.assigned_to && (
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => { setSelectedTask(task); setShowAssignModal(true); }}
                        >
                          Assign
                        </Button>
                      )}
                      
                      {task.status === 'pending' && task.assigned_to && (
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => handleUpdateStatus(task.id, 'in_progress')}
                          className="text-blue-600"
                        >
                          <Play className="w-4 h-4 mr-1" />
                          Start
                        </Button>
                      )}
                      
                      {task.status === 'in_progress' && (
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => handleUpdateStatus(task.id, 'completed')}
                          className="text-green-600"
                        >
                          <Check className="w-4 h-4 mr-1" />
                          Complete
                        </Button>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
            
            {tasks.length === 0 && (
              <Card>
                <CardContent className="p-8 text-center text-slate-500">
                  <ClipboardList className="w-12 h-12 mx-auto mb-4 opacity-50" />
                  <p>No tasks found</p>
                </CardContent>
              </Card>
            )}
          </div>
        </TabsContent>

        {/* Staff Tab */}
        <TabsContent value="staff" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {staff.map((member) => (
              <Card key={member.id}>
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center">
                      <User className="w-6 h-6 text-blue-600 dark:text-blue-400" />
                    </div>
                    <div className="flex-1">
                      <h3 className="font-semibold">{member.name}</h3>
                      <p className="text-sm text-slate-500">{member.email}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-2xl font-bold text-blue-600">{member.active_tasks}</p>
                      <p className="text-xs text-slate-500">active tasks</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Stats Tab */}
        <TabsContent value="stats" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <BarChart3 className="w-5 h-5" />
                Staff Performance (Last 7 Days)
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {staffPerformance.map((perf) => (
                  <div key={perf.id} className="flex items-center gap-4">
                    <div className="w-40 truncate font-medium">{perf.name}</div>
                    <div className="flex-1">
                      <div className="w-full bg-slate-200 dark:bg-slate-700 rounded-full h-3">
                        <div 
                          className="bg-blue-500 h-3 rounded-full" 
                          style={{ width: `${Math.min(100, (perf.tasks_completed / 20) * 100)}%` }}
                        />
                      </div>
                    </div>
                    <div className="w-24 text-right">
                      <span className="font-bold">{perf.tasks_completed}</span>
                      <span className="text-slate-500 text-sm"> tasks</span>
                    </div>
                    <div className="w-24 text-right text-sm text-slate-500">
                      ~{Math.round(perf.avg_time_minutes)} min/task
                    </div>
                  </div>
                ))}
                
                {staffPerformance.length === 0 && (
                  <p className="text-center text-slate-500 py-4">No performance data yet</p>
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Create Task Modal */}
      <AnimatePresence>
        {showCreateModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
            onClick={() => setShowCreateModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
            >
              <h3 className="text-xl font-bold mb-4">Create Task</h3>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-2">Task Type *</label>
                  <select
                    value={createForm.taskTypeId}
                    onChange={(e) => setCreateForm(f => ({ ...f, taskTypeId: e.target.value }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="">Select task type</option>
                    {taskTypes.map(type => (
                      <option key={type.id} value={type.id}>
                        {type.name} (~{type.estimated_duration} min)
                      </option>
                    ))}
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Priority</label>
                  <select
                    value={createForm.priority}
                    onChange={(e) => setCreateForm(f => ({ ...f, priority: e.target.value }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="low">Low</option>
                    <option value="normal">Normal</option>
                    <option value="high">High</option>
                    <option value="urgent">Urgent</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Assign To</label>
                  <select
                    value={createForm.assignedTo}
                    onChange={(e) => setCreateForm(f => ({ ...f, assignedTo: e.target.value }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="">Unassigned</option>
                    {staff.map(s => (
                      <option key={s.id} value={s.id}>
                        {s.name} ({s.active_tasks} active)
                      </option>
                    ))}
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Notes</label>
                  <textarea
                    className="w-full p-3 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                    rows={3}
                    placeholder="Additional notes..."
                    value={createForm.notes}
                    onChange={(e) => setCreateForm(f => ({ ...f, notes: e.target.value }))}
                  />
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => setShowCreateModal(false)}>
                  Cancel
                </Button>
                <Button onClick={handleCreateTask}>
                  Create Task
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Assign Modal */}
      <AnimatePresence>
        {showAssignModal && selectedTask && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
            onClick={() => { setShowAssignModal(false); setSelectedTask(null); }}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
            >
              <h3 className="text-xl font-bold mb-4">Assign Task</h3>
              <p className="text-slate-500 mb-4">
                Select a staff member to assign: <strong>{selectedTask.task_type_name}</strong>
              </p>
              
              <div className="space-y-2">
                {staff.map((member) => (
                  <button
                    key={member.id}
                    onClick={() => handleAssignTask(selectedTask.id, member.id)}
                    className="w-full p-4 flex items-center gap-4 rounded-lg border hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
                  >
                    <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center">
                      <User className="w-5 h-5 text-blue-600" />
                    </div>
                    <div className="flex-1 text-left">
                      <p className="font-medium">{member.name}</p>
                      <p className="text-sm text-slate-500">{member.active_tasks} active tasks</p>
                    </div>
                  </button>
                ))}
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => { setShowAssignModal(false); setSelectedTask(null); }}>
                  Cancel
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/Tabs';
import { Switch } from '@/components/ui/Switch';
import { Label } from '@/components/ui/Label';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/Alert';
import { 
  RefreshCw, 
  Link2, 
  Link2Off, 
  CheckCircle2, 
  XCircle, 
  AlertTriangle,
  History,
  Settings,
  FileText,
  ArrowRight
} from 'lucide-react';
import { toast } from 'sonner';
import api from '@/lib/api';

interface ConnectionStatus {
  connected: boolean;
  connectionId?: string;
  companyId?: string;
  companyName?: string;
  syncEnabled?: boolean;
  lastSync?: string;
  lastSyncStatus?: string;
  lastSyncError?: string;
  connectedAt?: string;
}

interface SyncHistoryItem {
  id: string;
  syncType: string;
  status: string;
  recordsProcessed: number;
  recordsSynced: number;
  recordsFailed: number;
  startedAt: string;
  completedAt: string | null;
}

interface AccountMapping {
  key: string;
  name: string;
  defaultType: string;
  mapped: {
    qb_account_id: string;
    qb_account_name: string;
  } | null;
}

interface QBAccount {
  id: string;
  name: string;
  accountType: string;
  classification: string;
}

export default function QuickBooksIntegrationPage() {
  const [status, setStatus] = useState<ConnectionStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [history, setHistory] = useState<SyncHistoryItem[]>([]);
  const [mappings, setMappings] = useState<AccountMapping[]>([]);
  const [accounts, setAccounts] = useState<QBAccount[]>([]);
  const [activeTab, setActiveTab] = useState('overview');

  const apiBase = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

  useEffect(() => {
    fetchConnectionStatus();
    
    // Check URL params for connection result
    const params = new URLSearchParams(window.location.search);
    if (params.get('connected') === 'true') {
      toast.success('QuickBooks Connected', {
        description: 'Your QuickBooks account has been successfully connected.',
      });
      // Clear URL params
      window.history.replaceState({}, '', window.location.pathname);
    } else if (params.get('error')) {
      toast.error('Connection Failed', {
        description: 'Failed to connect to QuickBooks. Please try again.',
      });
      window.history.replaceState({}, '', window.location.pathname);
    }
  }, []);

  useEffect(() => {
    if (status?.connected && status.connectionId) {
      fetchSyncHistory();
      fetchMappings();
      fetchAccounts();
    }
  }, [status?.connected, status?.connectionId]);

  async function fetchConnectionStatus() {
    try {
      const res = await api.get('/integrations/quickbooks/status');
      setStatus(res.data);
    } catch (error) {
      console.error('Failed to fetch connection status:', error);
    } finally {
      setLoading(false);
    }
  }

  async function fetchSyncHistory() {
    if (!status?.connectionId) return;
    try {
      const res = await api.get(`/integrations/quickbooks/${status.connectionId}/sync/history`);
      setHistory(res.data.history || []);
    } catch (error) {
      console.error('Failed to fetch sync history:', error);
    }
  }

  async function fetchMappings() {
    if (!status?.connectionId) return;
    try {
      const res = await api.get(`/integrations/quickbooks/${status.connectionId}/mappings`);
      setMappings(res.data.categories || []);
    } catch (error) {
      console.error('Failed to fetch mappings:', error);
    }
  }

  async function fetchAccounts() {
    if (!status?.connectionId) return;
    try {
      const res = await api.get(`/integrations/quickbooks/${status.connectionId}/accounts`);
      setAccounts(res.data.accounts || []);
    } catch (error) {
      console.error('Failed to fetch accounts:', error);
    }
  }

  async function handleConnect() {
    try {
      const res = await api.post('/integrations/quickbooks/connect', { propertyId: 'default' });
      
      if (res.data.authorizationUrl) {
        window.location.href = res.data.authorizationUrl;
      }
    } catch (error) {
      toast.error('Connection Error', {
        description: 'Failed to initiate QuickBooks connection.',
      });
    }
  }

  async function handleDisconnect() {
    if (!status?.connectionId) return;
    
    if (!confirm('Are you sure you want to disconnect QuickBooks? This will stop all syncing.')) {
      return;
    }

    try {
      await api.post(`/integrations/quickbooks/${status.connectionId}/disconnect`);
      
      toast.success('Disconnected', {
        description: 'QuickBooks has been disconnected.',
      });
      
      fetchConnectionStatus();
    } catch (error) {
      toast.error('Error', {
        description: 'Failed to disconnect QuickBooks.',
      });
    }
  }

  async function handleSync() {
    if (!status?.connectionId) return;
    
    setSyncing(true);
    try {
      const res = await api.post(`/integrations/quickbooks/${status.connectionId}/sync`, { syncType: 'sales' });
      
      if (res.data.success) {
        toast.success('Sync Complete', {
          description: `Synced ${res.data.recordsSynced} records. ${res.data.recordsFailed} failed.`,
        });
        fetchSyncHistory();
        fetchConnectionStatus();
      } else {
        throw new Error(res.data.error);
      }
    } catch (error) {
      toast.error('Sync Failed', {
        description: error instanceof Error ? error.message : 'Unknown error',
      });
    } finally {
      setSyncing(false);
    }
  }

  async function handleSaveMapping(category: string, accountId: string) {
    if (!status?.connectionId) return;
    
    const account = accounts.find(a => a.id === accountId);
    
    try {
      await api.post(`/integrations/quickbooks/${status.connectionId}/mappings`, {
        v2Category: category,
        qbAccountId: accountId,
        qbAccountName: account?.name,
        qbAccountType: account?.accountType,
      });
      
      toast.success('Mapping Saved', {
        description: 'Account mapping has been updated.',
      });
      
      fetchMappings();
    } catch (error) {
      toast.error('Error', {
        description: 'Failed to save mapping.',
      });
    }
  }

  async function handleToggleSync(enabled: boolean) {
    if (!status?.connectionId) return;
    
    try {
      await api.patch(`/integrations/quickbooks/${status.connectionId}/settings`, { syncEnabled: enabled });
      
      setStatus(prev => prev ? { ...prev, syncEnabled: enabled } : null);
      
      toast.success(enabled ? 'Sync Enabled' : 'Sync Disabled', {
        description: enabled 
          ? 'Automatic syncing has been enabled.' 
          : 'Automatic syncing has been disabled.',
      });
    } catch (error) {
      toast.error('Error', {
        description: 'Failed to update settings.',
      });
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <RefreshCw className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 max-w-6xl">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold">QuickBooks Integration</h1>
          <p className="text-muted-foreground mt-1">
            Sync your sales, customers, and invoices with QuickBooks Online
          </p>
        </div>
        {status?.connected && (
          <Badge variant={status.syncEnabled ? 'default' : 'secondary'} className="text-sm">
            {status.syncEnabled ? 'Sync Active' : 'Sync Paused'}
          </Badge>
        )}
      </div>

      {/* Connection Card */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            {status?.connected ? (
              <CheckCircle2 className="h-5 w-5 text-green-500" />
            ) : (
              <Link2Off className="h-5 w-5 text-muted-foreground" />
            )}
            Connection Status
          </CardTitle>
          <CardDescription>
            {status?.connected 
              ? `Connected to ${status.companyName || 'QuickBooks'}` 
              : 'Connect your QuickBooks Online account to sync data'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {status?.connected ? (
            <div className="space-y-4">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div>
                  <p className="text-sm text-muted-foreground">Company</p>
                  <p className="font-medium">{status.companyName}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Company ID</p>
                  <p className="font-medium font-mono text-sm">{status.companyId}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Last Sync</p>
                  <p className="font-medium">
                    {status.lastSync 
                      ? new Date(status.lastSync).toLocaleString() 
                      : 'Never'}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Last Status</p>
                  <Badge variant={
                    status.lastSyncStatus === 'completed' ? 'default' :
                    status.lastSyncStatus === 'completed_with_errors' ? 'secondary' :
                    status.lastSyncStatus === 'failed' ? 'destructive' : 'outline'
                  }>
                    {status.lastSyncStatus || 'N/A'}
                  </Badge>
                </div>
              </div>
              
              <div className="flex items-center justify-between pt-4 border-t">
                <div className="flex items-center space-x-2">
                  <Switch
                    id="auto-sync"
                    checked={status.syncEnabled}
                    onCheckedChange={handleToggleSync}
                  />
                  <Label htmlFor="auto-sync">Automatic Daily Sync</Label>
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    onClick={handleSync}
                    disabled={syncing}
                  >
                    {syncing ? (
                      <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                    ) : (
                      <RefreshCw className="h-4 w-4 mr-2" />
                    )}
                    Sync Now
                  </Button>
                  <Button
                    variant="destructive"
                    onClick={handleDisconnect}
                  >
                    <Link2Off className="h-4 w-4 mr-2" />
                    Disconnect
                  </Button>
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center py-8">
              <Link2 className="h-12 w-12 mx-auto mb-4 text-muted-foreground" />
              <p className="text-muted-foreground mb-4">
                Connect your QuickBooks Online account to automatically sync sales, customers, and invoices.
              </p>
              <Button onClick={handleConnect}>
                <Link2 className="h-4 w-4 mr-2" />
                Connect QuickBooks
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Detailed sections - only show when connected */}
      {status?.connected && (
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="overview">
              <FileText className="h-4 w-4 mr-2" />
              Overview
            </TabsTrigger>
            <TabsTrigger value="mappings">
              <Settings className="h-4 w-4 mr-2" />
              Account Mappings
            </TabsTrigger>
            <TabsTrigger value="history">
              <History className="h-4 w-4 mr-2" />
              Sync History
            </TabsTrigger>
          </TabsList>

          <TabsContent value="overview" className="mt-6">
            <div className="grid md:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>What Gets Synced</CardTitle>
                </CardHeader>
                <CardContent>
                  <ul className="space-y-3">
                    <li className="flex items-center gap-2">
                      <CheckCircle2 className="h-4 w-4 text-green-500" />
                      <span>Daily sales as Sales Receipts</span>
                    </li>
                    <li className="flex items-center gap-2">
                      <CheckCircle2 className="h-4 w-4 text-green-500" />
                      <span>Customer profiles</span>
                    </li>
                    <li className="flex items-center gap-2">
                      <CheckCircle2 className="h-4 w-4 text-green-500" />
                      <span>Revenue by category</span>
                    </li>
                    <li className="flex items-center gap-2">
                      <CheckCircle2 className="h-4 w-4 text-green-500" />
                      <span>Tax collected</span>
                    </li>
                    <li className="flex items-center gap-2">
                      <CheckCircle2 className="h-4 w-4 text-green-500" />
                      <span>Refunds and adjustments</span>
                    </li>
                  </ul>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Sync Schedule</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div className="flex items-center justify-between">
                      <span className="text-sm">Automatic Sync</span>
                      <Badge variant={status.syncEnabled ? 'default' : 'secondary'}>
                        {status.syncEnabled ? 'Daily at 2:00 AM' : 'Disabled'}
                      </Badge>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm">Manual Sync</span>
                      <Badge variant="outline">Available</Badge>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm">Real-time Sync</span>
                      <Badge variant="secondary">Coming Soon</Badge>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          <TabsContent value="mappings" className="mt-6">
            <Card>
              <CardHeader>
                <CardTitle>Account Mappings</CardTitle>
                <CardDescription>
                  Map V2 revenue categories to your QuickBooks accounts
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {mappings.map((mapping) => (
                    <div 
                      key={mapping.key} 
                      className="flex items-center justify-between p-4 rounded-lg border"
                    >
                      <div>
                        <p className="font-medium">{mapping.name}</p>
                        <p className="text-sm text-muted-foreground">
                          Default type: {mapping.defaultType}
                        </p>
                      </div>
                      <div className="flex items-center gap-4">
                        {mapping.mapped ? (
                          <div className="text-right">
                            <p className="text-sm font-medium">{mapping.mapped.qb_account_name}</p>
                            <p className="text-xs text-muted-foreground">
                              ID: {mapping.mapped.qb_account_id}
                            </p>
                          </div>
                        ) : (
                          <span className="text-sm text-muted-foreground">Not mapped</span>
                        )}
                        <ArrowRight className="h-4 w-4 text-muted-foreground" />
                        <select
                          className="border rounded-md px-3 py-2 text-sm min-w-[200px]"
                          value={mapping.mapped?.qb_account_id || ''}
                          onChange={(e) => handleSaveMapping(mapping.key, e.target.value)}
                        >
                          <option value="">Select account...</option>
                          {accounts
                            .filter(a => a.classification === mapping.defaultType || mapping.defaultType === 'Other Current Liability')
                            .map((account) => (
                              <option key={account.id} value={account.id}>
                                {account.name} ({account.accountType})
                              </option>
                            ))}
                        </select>
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="history" className="mt-6">
            <Card>
              <CardHeader>
                <CardTitle>Sync History</CardTitle>
                <CardDescription>
                  View past sync operations and their results
                </CardDescription>
              </CardHeader>
              <CardContent>
                {history.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    No sync history yet. Run a sync to see results here.
                  </div>
                ) : (
                  <div className="space-y-2">
                    {history.map((item) => (
                      <div 
                        key={item.id}
                        className="flex items-center justify-between p-4 rounded-lg border"
                      >
                        <div className="flex items-center gap-4">
                          {item.status === 'completed' ? (
                            <CheckCircle2 className="h-5 w-5 text-green-500" />
                          ) : item.status === 'completed_with_errors' ? (
                            <AlertTriangle className="h-5 w-5 text-yellow-500" />
                          ) : item.status === 'failed' ? (
                            <XCircle className="h-5 w-5 text-red-500" />
                          ) : (
                            <RefreshCw className="h-5 w-5 animate-spin" />
                          )}
                          <div>
                            <p className="font-medium capitalize">{item.syncType} Sync</p>
                            <p className="text-sm text-muted-foreground">
                              {new Date(item.startedAt).toLocaleString()}
                            </p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="text-sm">
                            <span className="text-green-600">{item.recordsSynced} synced</span>
                            {item.recordsFailed > 0 && (
                              <span className="text-red-600 ml-2">{item.recordsFailed} failed</span>
                            )}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {item.recordsProcessed} processed
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      )}

      {/* Error Alert */}
      {status?.lastSyncError && (
        <Alert variant="destructive" className="mt-6">
          <AlertTriangle className="h-4 w-4" />
          <AlertTitle>Last Sync Error</AlertTitle>
          <AlertDescription>{status.lastSyncError}</AlertDescription>
        </Alert>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/Tabs';
import { Portal } from '@/components/ui/Portal';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  Package,
  AlertTriangle,
  TrendingDown,
  TrendingUp,
  Search,
  Plus,
  Edit,
  RefreshCw,
  ArrowUpDown,
  Download,
  Upload,
  Bell,
  CheckCircle,
  XCircle,
  Clock,
  BarChart3,
  Box,
  Calendar,
  Filter,
  Minus,
  Trash2,
} from 'lucide-react';

interface InventoryItem {
  id: string;
  name: string;
  sku: string;
  description?: string;
  category_id: string;
  category_name: string;
  category_color?: string;
  unit: string;
  current_stock: number;
  min_stock_level: number;
  max_stock_level?: number;
  reorder_point: number;
  cost_per_unit?: number;
  supplier?: string;
  location?: string;
  expiry_date?: string;
  stock_status: 'normal' | 'low_stock' | 'out_of_stock' | 'overstock';
  is_active: boolean;
}

interface Category {
  id: string;
  name: string;
  color?: string;
  item_count: number;
  total_stock: number;
}

interface Alert {
  id: string;
  item_id: string;
  item_name: string;
  sku: string;
  alert_type: string;
  message: string;
  priority: 'low' | 'medium' | 'high' | 'critical';
  current_stock: number;
  is_resolved: boolean;
  created_at: string;
}

interface Stats {
  total_items: number;
  out_of_stock: number;
  low_stock: number;
  overstock: number;
  total_value: number;
  unresolvedAlerts: number;
}

interface Transaction {
  id: string;
  item_id: string;
  item_name: string;
  sku: string;
  type: 'in' | 'out' | 'adjustment' | 'waste' | 'return';
  quantity: number;
  previous_stock: number;
  new_stock: number;
  reference_type: string;
  notes?: string;
  performed_by_name?: string;
  created_at: string;
}

export default function InventoryAdminPage() {
  const [activeTab, setActiveTab] = useState('items');
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [stockFilter, setStockFilter] = useState('all');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showTransactionModal, setShowTransactionModal] = useState(false);
  const [showCategoryModal, setShowCategoryModal] = useState(false);
  const [showDeleteItemModal, setShowDeleteItemModal] = useState(false);
  const [showDeleteCategoryModal, setShowDeleteCategoryModal] = useState(false);
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [deletingItem, setDeletingItem] = useState<InventoryItem | null>(null);
  const [deletingCategory, setDeletingCategory] = useState<Category | null>(null);
  
  // Form states
  const [itemForm, setItemForm] = useState({
    name: '',
    sku: '',
    description: '',
    categoryId: '',
    unit: 'piece',
    currentStock: '0',
    minStockLevel: '10',
    maxStockLevel: '',
    reorderPoint: '5',
    costPerUnit: '',
    supplier: '',
    location: '',
    expiryDate: '',
  });

  const [transactionForm, setTransactionForm] = useState({
    type: 'in' as 'in' | 'out' | 'adjustment' | 'waste' | 'return',
    quantity: '',
    notes: '',
  });

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    if (activeTab === 'transactions') {
      loadTransactions();
    } else if (activeTab === 'alerts') {
      loadAlerts();
    }
  }, [activeTab]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [itemsRes, categoriesRes, statsRes, alertsRes] = await Promise.all([
        api.get('/inventory/items', {
          params: {
            search: searchQuery || undefined,
            categoryId: categoryFilter === 'all' ? undefined : categoryFilter,
            lowStock: stockFilter === 'low' ? 'true' : undefined,
            outOfStock: stockFilter === 'out' ? 'true' : undefined,
          }
        }),
        api.get('/inventory/categories'),
        api.get('/inventory/stats'),
        api.get('/inventory/alerts'),
      ]);

      if (itemsRes.data.success) setItems(itemsRes.data.data);
      if (categoriesRes.data.success) setCategories(categoriesRes.data.data);
      if (statsRes.data.success) setStats(statsRes.data.data.summary);
      if (alertsRes.data.success) setAlerts(alertsRes.data.data);
    } catch (error) {
      toast.error('Failed to load inventory data');
    } finally {
      setLoading(false);
    }
  };

  const loadTransactions = async () => {
    try {
      const res = await api.get('/inventory/transactions', { params: { limit: 100 } });
      if (res.data.success) setTransactions(res.data.data);
    } catch (error) {
      toast.error('Failed to load transactions');
    }
  };

  const loadAlerts = async () => {
    try {
      const res = await api.get('/inventory/alerts');
      if (res.data.success) setAlerts(res.data.data);
    } catch (error) {
      toast.error('Failed to load alerts');
    }
  };

  useEffect(() => {
    loadData();
  }, [searchQuery, categoryFilter, stockFilter]);

  const handleCreateItem = async () => {
    if (!itemForm.name || !itemForm.categoryId) {
      toast.error('Please fill in required fields');
      return;
    }
    
    try {
      const payload = {
        name: itemForm.name,
        sku: itemForm.sku || undefined,
        description: itemForm.description || undefined,
        categoryId: itemForm.categoryId,
        unit: itemForm.unit,
        currentStock: parseFloat(itemForm.currentStock) || 0,
        minStockLevel: parseFloat(itemForm.minStockLevel) || 10,
        maxStockLevel: itemForm.maxStockLevel ? parseFloat(itemForm.maxStockLevel) : undefined,
        reorderPoint: parseFloat(itemForm.reorderPoint) || 5,
        costPerUnit: itemForm.costPerUnit ? parseFloat(itemForm.costPerUnit) : undefined,
        supplier: itemForm.supplier || undefined,
        location: itemForm.location || undefined,
        expiryDate: itemForm.expiryDate || undefined,
      };
      
      let res;
      if (editingItem) {
        res = await api.put(`/inventory/items/${editingItem.id}`, payload);
      } else {
        res = await api.post('/inventory/items', payload);
      }
      
      if (res.data.success) {
        toast.success(editingItem ? 'Item updated' : 'Item created');
        setShowCreateModal(false);
        setEditingItem(null);
        resetItemForm();
        loadData();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Failed to save item');
    }
  };

  const resetItemForm = () => {
    setItemForm({
      name: '',
      sku: '',
      description: '',
      categoryId: '',
      unit: 'piece',
      currentStock: '0',
      minStockLevel: '10',
      maxStockLevel: '',
      reorderPoint: '5',
      costPerUnit: '',
      supplier: '',
      location: '',
      expiryDate: '',
    });
  };

  const handleEdit = (item: InventoryItem) => {
    setEditingItem(item);
    setItemForm({
      name: item.name,
      sku: item.sku || '',
      description: item.description || '',
      categoryId: item.category_id,
      unit: item.unit,
      currentStock: item.current_stock.toString(),
      minStockLevel: item.min_stock_level.toString(),
      maxStockLevel: item.max_stock_level?.toString() || '',
      reorderPoint: item.reorder_point.toString(),
      costPerUnit: item.cost_per_unit?.toString() || '',
      supplier: item.supplier || '',
      location: item.location || '',
      expiryDate: item.expiry_date?.split('T')[0] || '',
    });
    setShowCreateModal(true);
  };

  const handleRecordTransaction = async () => {
    if (!selectedItem || !transactionForm.quantity) {
      toast.error('Please enter a quantity');
      return;
    }
    
    try {
      const res = await api.post('/inventory/transactions', {
        itemId: selectedItem.id,
        type: transactionForm.type,
        quantity: parseFloat(transactionForm.quantity),
        notes: transactionForm.notes || undefined,
        referenceType: 'manual',
      });
      
      if (res.data.success) {
        toast.success('Transaction recorded');
        setShowTransactionModal(false);
        setSelectedItem(null);
        setTransactionForm({ type: 'in', quantity: '', notes: '' });
        loadData();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Failed to record transaction');
    }
  };

  const handleResolveAlert = async (alertId: string) => {
    try {
      const res = await api.post(`/inventory/alerts/${alertId}/resolve`);
      if (res.data.success) {
        toast.success('Alert resolved');
        loadAlerts();
        loadData();
      }
    } catch (error) {
      toast.error('Failed to resolve alert');
    }
  };

  const handleDeleteItem = async () => {
    if (!deletingItem) return;
    
    try {
      const res = await api.delete(`/inventory/items/${deletingItem.id}`);
      if (res.data.success) {
        toast.success('Item deleted successfully');
        setShowDeleteItemModal(false);
        setDeletingItem(null);
        loadData();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Failed to delete item');
    }
  };

  const handleDeleteCategory = async () => {
    if (!deletingCategory) return;
    
    try {
      const res = await api.delete(`/inventory/categories/${deletingCategory.id}`);
      if (res.data.success) {
        toast.success('Category deleted successfully');
        setShowDeleteCategoryModal(false);
        setDeletingCategory(null);
        loadData();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Failed to delete category');
    }
  };
  const handleExportReport = async () => {
    try {
      window.open(`${api.defaults.baseURL}/inventory/report?format=csv`, '_blank');
    } catch (error) {
      toast.error('Failed to export report');
    }
  };

  const getStockStatusBadge = (status: string) => {
    const styles: Record<string, string> = {
      normal: 'bg-green-100 text-green-700',
      low_stock: 'bg-amber-100 text-amber-700',
      out_of_stock: 'bg-red-100 text-red-700',
      overstock: 'bg-blue-100 text-blue-700',
    };
    return (
      <Badge className={styles[status] || styles.normal}>
        {status.replace('_', ' ')}
      </Badge>
    );
  };

  const getTransactionTypeBadge = (type: string) => {
    const styles: Record<string, { bg: string; icon: React.ReactNode }> = {
      in: { bg: 'bg-green-100 text-green-700', icon: <TrendingUp className="w-3 h-3" /> },
      out: { bg: 'bg-red-100 text-red-700', icon: <TrendingDown className="w-3 h-3" /> },
      adjustment: { bg: 'bg-blue-100 text-blue-700', icon: <ArrowUpDown className="w-3 h-3" /> },
      waste: { bg: 'bg-amber-100 text-amber-700', icon: <AlertTriangle className="w-3 h-3" /> },
      return: { bg: 'bg-purple-100 text-purple-700', icon: <Upload className="w-3 h-3" /> },
    };
    const style = styles[type] || styles.adjustment;
    return (
      <Badge className={`flex items-center gap-1 ${style.bg}`}>
        {style.icon}
        {type}
      </Badge>
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <RefreshCw className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Inventory</h1>
          <p className="text-slate-500 dark:text-slate-400">Stock management and tracking</p>
        </div>
        <div className="flex gap-2">
          <Button onClick={handleExportReport} variant="outline" className="gap-2">
            <Download className="w-4 h-4" />
            Export
          </Button>
          <Button onClick={() => loadData()} variant="outline" className="gap-2">
            <RefreshCw className="w-4 h-4" />
            Refresh
          </Button>
          <Button onClick={() => { resetItemForm(); setEditingItem(null); setShowCreateModal(true); }} className="gap-2">
            <Plus className="w-4 h-4" />
            Add Item
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <motion.div variants={fadeInUp} className="grid grid-cols-2 md:grid-cols-6 gap-4">
        <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-blue-100 text-xs">Total Items</p>
                <p className="text-2xl font-bold">{stats?.total_items || 0}</p>
              </div>
              <Package className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-red-500 to-red-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-red-100 text-xs">Out of Stock</p>
                <p className="text-2xl font-bold">{stats?.out_of_stock || 0}</p>
              </div>
              <XCircle className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-amber-500 to-amber-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-amber-100 text-xs">Low Stock</p>
                <p className="text-2xl font-bold">{stats?.low_stock || 0}</p>
              </div>
              <AlertTriangle className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-purple-100 text-xs">Overstock</p>
                <p className="text-2xl font-bold">{stats?.overstock || 0}</p>
              </div>
              <Box className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-green-100 text-xs">Total Value</p>
                <p className="text-2xl font-bold">{formatCurrency(stats?.total_value || 0)}</p>
              </div>
              <TrendingUp className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-rose-500 to-rose-600 text-white">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-rose-100 text-xs">Active Alerts</p>
                <p className="text-2xl font-bold">{stats?.unresolvedAlerts || 0}</p>
              </div>
              <Bell className="w-8 h-8 opacity-80" />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid grid-cols-4 w-full max-w-lg">
          <TabsTrigger value="items">Items</TabsTrigger>
          <TabsTrigger value="categories">Categories</TabsTrigger>
          <TabsTrigger value="transactions">Transactions</TabsTrigger>
          <TabsTrigger value="alerts">
            Alerts
            {(stats?.unresolvedAlerts || 0) > 0 && (
              <span className="ml-1 bg-red-500 text-white text-xs rounded-full px-1.5">
                {stats?.unresolvedAlerts}
              </span>
            )}
          </TabsTrigger>
        </TabsList>

        {/* Items Tab */}
        <TabsContent value="items" className="space-y-4">
          <div className="flex flex-wrap gap-4">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
              <Input
                placeholder="Search items..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <select
              value={categoryFilter}
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="px-4 py-2 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
            >
              <option value="all">All Categories</option>
              {categories.map(cat => (
                <option key={cat.id} value={cat.id}>{cat.name}</option>
              ))}
            </select>
            <select
              value={stockFilter}
              onChange={(e) => setStockFilter(e.target.value)}
              className="px-4 py-2 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
            >
              <option value="all">All Stock Levels</option>
              <option value="low">Low Stock</option>
              <option value="out">Out of Stock</option>
            </select>
          </div>

          <Card>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b dark:border-slate-700">
                      <th className="text-left p-4 font-medium text-slate-500">Item</th>
                      <th className="text-left p-4 font-medium text-slate-500">SKU</th>
                      <th className="text-left p-4 font-medium text-slate-500">Category</th>
                      <th className="text-center p-4 font-medium text-slate-500">Stock</th>
                      <th className="text-left p-4 font-medium text-slate-500">Status</th>
                      <th className="text-right p-4 font-medium text-slate-500">Cost</th>
                      <th className="text-right p-4 font-medium text-slate-500">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {items.map((item) => (
                      <tr key={item.id} className="border-b dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800">
                        <td className="p-4">
                          <div>
                            <p className="font-medium">{item.name}</p>
                            {item.location && (
                              <p className="text-xs text-slate-500">{item.location}</p>
                            )}
                          </div>
                        </td>
                        <td className="p-4">
                          <code className="text-sm bg-slate-100 dark:bg-slate-700 px-2 py-1 rounded">
                            {item.sku}
                          </code>
                        </td>
                        <td className="p-4">
                          <Badge 
                            style={{ 
                              backgroundColor: (item.category_color || '#6b7280') + '20',
                              color: item.category_color || '#6b7280'
                            }}
                          >
                            {item.category_name}
                          </Badge>
                        </td>
                        <td className="p-4 text-center">
                          <span className="font-bold">{item.current_stock}</span>
                          <span className="text-slate-400 text-sm"> {item.unit}</span>
                          <div className="text-xs text-slate-500">
                            Min: {item.min_stock_level} / Reorder: {item.reorder_point}
                          </div>
                        </td>
                        <td className="p-4">
                          {getStockStatusBadge(item.stock_status)}
                        </td>
                        <td className="p-4 text-right">
                          {item.cost_per_unit ? formatCurrency(item.cost_per_unit) : '-'}
                        </td>
                        <td className="p-4 text-right">
                          <div className="flex justify-end gap-1">
                            <Button 
                              variant="outline" 
                              size="sm"
                              onClick={() => { setSelectedItem(item); setShowTransactionModal(true); }}
                              title="Record Transaction"
                            >
                              <ArrowUpDown className="w-4 h-4" />
                            </Button>
                            <Button 
                              variant="ghost" 
                              size="sm"
                              onClick={() => handleEdit(item)}
                              title="Edit Item"
                            >
                              <Edit className="w-4 h-4" />
                            </Button>
                            <Button 
                              variant="ghost" 
                              size="sm"
                              onClick={() => { setDeletingItem(item); setShowDeleteItemModal(true); }}
                              title="Delete Item"
                              className="text-red-500 hover:text-red-700 hover:bg-red-50"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Categories Tab */}
        <TabsContent value="categories" className="space-y-4">
          <div className="flex justify-end">
            <Button onClick={() => { setEditingCategory(null); setShowCategoryModal(true); }}>
              <Plus className="w-4 h-4 mr-2" />
              Add Category
            </Button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {categories.map((cat) => (
              <Card key={cat.id}>
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    <div 
                      className="w-12 h-12 rounded-lg flex items-center justify-center"
                      style={{ backgroundColor: (cat.color || '#6b7280') + '20' }}
                    >
                      <Package className="w-6 h-6" style={{ color: cat.color || '#6b7280' }} />
                    </div>
                    <div className="flex-1">
                      <h3 className="font-semibold">{cat.name}</h3>
                      <p className="text-sm text-slate-500">{cat.item_count} items</p>
                    </div>
                    <div className="text-right">
                      <p className="text-2xl font-bold">{Math.round(cat.total_stock)}</p>
                      <p className="text-xs text-slate-500">units</p>
                    </div>
                    <div className="flex gap-1">
                      <Button 
                        variant="ghost" 
                        size="sm"
                        onClick={() => { setEditingCategory(cat); setShowCategoryModal(true); }}
                        title="Edit Category"
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button 
                        variant="ghost" 
                        size="sm"
                        onClick={() => { setDeletingCategory(cat); setShowDeleteCategoryModal(true); }}
                        title="Delete Category"
                        className="text-red-500 hover:text-red-700 hover:bg-red-50"
                        disabled={cat.item_count > 0}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Transactions Tab */}
        <TabsContent value="transactions" className="space-y-4">
          <Card>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b dark:border-slate-700">
                      <th className="text-left p-4 font-medium text-slate-500">Date</th>
                      <th className="text-left p-4 font-medium text-slate-500">Item</th>
                      <th className="text-left p-4 font-medium text-slate-500">Type</th>
                      <th className="text-center p-4 font-medium text-slate-500">Quantity</th>
                      <th className="text-center p-4 font-medium text-slate-500">Stock Change</th>
                      <th className="text-left p-4 font-medium text-slate-500">By</th>
                      <th className="text-left p-4 font-medium text-slate-500">Notes</th>
                    </tr>
                  </thead>
                  <tbody>
                    {transactions.map((txn) => (
                      <tr key={txn.id} className="border-b dark:border-slate-700">
                        <td className="p-4 text-sm text-slate-500">
                          {formatDate(txn.created_at)}
                        </td>
                        <td className="p-4">
                          <div>
                            <p className="font-medium">{txn.item_name}</p>
                            <p className="text-xs text-slate-500">{txn.sku}</p>
                          </div>
                        </td>
                        <td className="p-4">
                          {getTransactionTypeBadge(txn.type)}
                        </td>
                        <td className="p-4 text-center font-bold">
                          {txn.type === 'in' || txn.type === 'return' ? '+' : txn.type === 'adjustment' ? '=' : '-'}
                          {txn.quantity}
                        </td>
                        <td className="p-4 text-center text-sm text-slate-500">
                          {txn.previous_stock} → {txn.new_stock}
                        </td>
                        <td className="p-4 text-sm">
                          {txn.performed_by_name || '-'}
                        </td>
                        <td className="p-4 text-sm text-slate-500 truncate max-w-xs">
                          {txn.notes || '-'}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Alerts Tab */}
        <TabsContent value="alerts" className="space-y-4">
          {alerts.length === 0 ? (
            <Card>
              <CardContent className="p-8 text-center text-slate-500">
                <CheckCircle className="w-12 h-12 mx-auto mb-4 text-green-500" />
                <p className="text-lg font-medium">No active alerts</p>
                <p className="text-sm">All inventory levels are within normal ranges</p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {alerts.map((alert) => (
                <Card key={alert.id} className={`border-l-4 ${
                  alert.priority === 'critical' ? 'border-l-red-500' :
                  alert.priority === 'high' ? 'border-l-orange-500' :
                  alert.priority === 'medium' ? 'border-l-amber-500' :
                  'border-l-blue-500'
                }`}>
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between">
                      <div className="flex items-start gap-4">
                        <div className={`p-2 rounded-full ${
                          alert.priority === 'critical' ? 'bg-red-100' :
                          alert.priority === 'high' ? 'bg-orange-100' :
                          alert.priority === 'medium' ? 'bg-amber-100' :
                          'bg-blue-100'
                        }`}>
                          <AlertTriangle className={`w-5 h-5 ${
                            alert.priority === 'critical' ? 'text-red-600' :
                            alert.priority === 'high' ? 'text-orange-600' :
                            alert.priority === 'medium' ? 'text-amber-600' :
                            'text-blue-600'
                          }`} />
                        </div>
                        <div>
                          <div className="flex items-center gap-2 mb-1">
                            <Badge className="capitalize">{alert.priority}</Badge>
                            <Badge variant="outline">{alert.alert_type.replace('_', ' ')}</Badge>
                          </div>
                          <h3 className="font-semibold">{alert.item_name}</h3>
                          <p className="text-sm text-slate-500">{alert.message}</p>
                          <p className="text-xs text-slate-400 mt-1">
                            Current stock: {alert.current_stock} • {formatDate(alert.created_at)}
                          </p>
                        </div>
                      </div>
                      <Button 
                        variant="outline" 
                        size="sm"
                        onClick={() => handleResolveAlert(alert.id)}
                      >
                        <CheckCircle className="w-4 h-4 mr-1" />
                        Resolve
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Create/Edit Item Modal */}
      <Portal>
        <AnimatePresence>
          {showCreateModal && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
              onClick={() => { setShowCreateModal(false); setEditingItem(null); }}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.95, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-2xl shadow-2xl max-h-[90vh] overflow-y-auto"
              >
                <h3 className="text-xl font-bold mb-4">
                  {editingItem ? 'Edit Item' : 'Add Inventory Item'}
                </h3>
              
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                  <label className="block text-sm font-medium mb-2">Name *</label>
                  <Input
                    placeholder="Item name"
                    value={itemForm.name}
                    onChange={(e) => setItemForm(f => ({ ...f, name: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">SKU</label>
                  <Input
                    placeholder="Auto-generated if empty"
                    value={itemForm.sku}
                    onChange={(e) => setItemForm(f => ({ ...f, sku: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Category *</label>
                  <select
                    value={itemForm.categoryId}
                    onChange={(e) => setItemForm(f => ({ ...f, categoryId: e.target.value }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="">Select category</option>
                    {categories.map(cat => (
                      <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))}
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Unit</label>
                  <select
                    value={itemForm.unit}
                    onChange={(e) => setItemForm(f => ({ ...f, unit: e.target.value }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="piece">Piece</option>
                    <option value="unit">Unit</option>
                    <option value="kg">Kilogram</option>
                    <option value="gram">Gram</option>
                    <option value="liter">Liter</option>
                    <option value="ml">Milliliter</option>
                    <option value="box">Box</option>
                    <option value="pack">Pack</option>
                    <option value="bottle">Bottle</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Initial Stock</label>
                  <Input
                    type="number"
                    placeholder="0"
                    value={itemForm.currentStock}
                    onChange={(e) => setItemForm(f => ({ ...f, currentStock: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Min Stock Level</label>
                  <Input
                    type="number"
                    placeholder="10"
                    value={itemForm.minStockLevel}
                    onChange={(e) => setItemForm(f => ({ ...f, minStockLevel: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Reorder Point</label>
                  <Input
                    type="number"
                    placeholder="5"
                    value={itemForm.reorderPoint}
                    onChange={(e) => setItemForm(f => ({ ...f, reorderPoint: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Cost per Unit ($)</label>
                  <Input
                    type="number"
                    step="0.01"
                    placeholder="0.00"
                    value={itemForm.costPerUnit}
                    onChange={(e) => setItemForm(f => ({ ...f, costPerUnit: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Supplier</label>
                  <Input
                    placeholder="Supplier name"
                    value={itemForm.supplier}
                    onChange={(e) => setItemForm(f => ({ ...f, supplier: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Location</label>
                  <Input
                    placeholder="Storage location"
                    value={itemForm.location}
                    onChange={(e) => setItemForm(f => ({ ...f, location: e.target.value }))}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Expiry Date</label>
                  <Input
                    type="date"
                    value={itemForm.expiryDate}
                    onChange={(e) => setItemForm(f => ({ ...f, expiryDate: e.target.value }))}
                  />
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => { setShowCreateModal(false); setEditingItem(null); }}>
                  Cancel
                </Button>
                <Button onClick={handleCreateItem}>
                  {editingItem ? 'Update Item' : 'Add Item'}
                </Button>
              </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </Portal>

      {/* Transaction Modal */}
      <Portal>
        <AnimatePresence>
          {showTransactionModal && selectedItem && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
              onClick={() => { setShowTransactionModal(false); setSelectedItem(null); }}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.95, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
              >
                <h3 className="text-xl font-bold mb-4">Record Transaction</h3>
                <p className="text-slate-500 mb-4">
                  <strong>{selectedItem.name}</strong>
                <br />
                Current stock: <strong>{selectedItem.current_stock} {selectedItem.unit}</strong>
              </p>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-2">Transaction Type</label>
                  <select
                    value={transactionForm.type}
                    onChange={(e) => setTransactionForm(f => ({ ...f, type: e.target.value as any }))}
                    className="w-full p-2 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                  >
                    <option value="in">Stock In (Received)</option>
                    <option value="out">Stock Out (Used)</option>
                    <option value="adjustment">Adjustment (Set to)</option>
                    <option value="waste">Waste/Loss</option>
                    <option value="return">Return</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Quantity</label>
                  <Input
                    type="number"
                    placeholder="Enter quantity"
                    value={transactionForm.quantity}
                    onChange={(e) => setTransactionForm(f => ({ ...f, quantity: e.target.value }))}
                  />
                  <p className="text-xs text-slate-500 mt-1">
                    {transactionForm.type === 'adjustment' 
                      ? 'Stock will be set to this value'
                      : transactionForm.type === 'in' || transactionForm.type === 'return'
                        ? 'This will be added to current stock'
                        : 'This will be subtracted from current stock'
                    }
                  </p>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Notes</label>
                  <textarea
                    className="w-full p-3 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
                    rows={2}
                    placeholder="Optional notes..."
                    value={transactionForm.notes}
                    onChange={(e) => setTransactionForm(f => ({ ...f, notes: e.target.value }))}
                  />
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => { setShowTransactionModal(false); setSelectedItem(null); }}>
                  Cancel
                </Button>
                <Button onClick={handleRecordTransaction}>
                  Record Transaction
                </Button>
              </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </Portal>

      {/* Category Create/Edit Modal */}
      <Portal>
        <AnimatePresence>
          {showCategoryModal && (
            <CategoryModal
              category={editingCategory}
              onClose={() => { setShowCategoryModal(false); setEditingCategory(null); }}
              onSave={async (data) => {
                try {
                  if (editingCategory) {
                    const res = await api.put(`/inventory/categories/${editingCategory.id}`, data);
                    if (res.data.success) {
                      toast.success('Category updated');
                    }
                  } else {
                    const res = await api.post('/inventory/categories', data);
                    if (res.data.success) {
                      toast.success('Category created');
                    }
                  }
                  setShowCategoryModal(false);
                  setEditingCategory(null);
                  loadData();
                } catch (error: any) {
                  toast.error(error.response?.data?.error || 'Failed to save category');
                }
              }}
            />
          )}
        </AnimatePresence>
      </Portal>

      {/* Delete Item Confirmation Modal */}
      <Portal>
        <AnimatePresence>
          {showDeleteItemModal && deletingItem && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
              onClick={() => { setShowDeleteItemModal(false); setDeletingItem(null); }}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.95, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
              >
                <div className="flex items-center gap-4 mb-4">
                  <div className="w-12 h-12 rounded-full bg-red-100 flex items-center justify-center">
                    <Trash2 className="w-6 h-6 text-red-600" />
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-red-600">Delete Item</h3>
                    <p className="text-slate-500">This action cannot be undone</p>
                  </div>
                </div>
                
                <p className="mb-6">
                  Are you sure you want to delete <strong>{deletingItem.name}</strong>?
                  <br />
                  <span className="text-sm text-slate-500">
                    SKU: {deletingItem.sku} | Current stock: {deletingItem.current_stock} {deletingItem.unit}
                  </span>
                </p>
                
                <div className="flex justify-end gap-3">
                  <Button variant="outline" onClick={() => { setShowDeleteItemModal(false); setDeletingItem(null); }}>
                    Cancel
                  </Button>
                  <Button 
                    onClick={handleDeleteItem}
                    className="bg-red-600 hover:bg-red-700 text-white"
                  >
                    Delete Item
                  </Button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </Portal>

      {/* Delete Category Confirmation Modal */}
      <Portal>
        <AnimatePresence>
          {showDeleteCategoryModal && deletingCategory && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
              onClick={() => { setShowDeleteCategoryModal(false); setDeletingCategory(null); }}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.95, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
              >
                <div className="flex items-center gap-4 mb-4">
                  <div className="w-12 h-12 rounded-full bg-red-100 flex items-center justify-center">
                    <Trash2 className="w-6 h-6 text-red-600" />
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-red-600">Delete Category</h3>
                    <p className="text-slate-500">This action cannot be undone</p>
                  </div>
                </div>
                
                <p className="mb-6">
                  Are you sure you want to delete the category <strong>{deletingCategory.name}</strong>?
                  {deletingCategory.item_count > 0 && (
                    <span className="block mt-2 text-amber-600">
                      <AlertTriangle className="w-4 h-4 inline mr-1" />
                      This category has {deletingCategory.item_count} items. 
                      Please move or delete the items first.
                    </span>
                  )}
                </p>
                
                <div className="flex justify-end gap-3">
                  <Button variant="outline" onClick={() => { setShowDeleteCategoryModal(false); setDeletingCategory(null); }}>
                    Cancel
                  </Button>
                  <Button 
                    onClick={handleDeleteCategory}
                    className="bg-red-600 hover:bg-red-700 text-white"
                    disabled={deletingCategory.item_count > 0}
                  >
                    Delete Category
                  </Button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </Portal>
    </motion.div>
  );
}

// Category Modal Component
interface CategoryModalProps {
  category: Category | null;
  onClose: () => void;
  onSave: (data: { name: string; color?: string; description?: string }) => Promise<void>;
}

function CategoryModal({ category, onClose, onSave }: CategoryModalProps) {
  const [form, setForm] = useState({
    name: category?.name || '',
    color: category?.color || '#6b7280',
    description: '',
  });
  const [saving, setSaving] = useState(false);

  const handleSubmit = async () => {
    if (!form.name.trim()) {
      toast.error('Category name is required');
      return;
    }
    setSaving(true);
    await onSave({
      name: form.name.trim(),
      color: form.color,
      description: form.description.trim() || undefined,
    });
    setSaving(false);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.95, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.95, opacity: 0 }}
        onClick={(e) => e.stopPropagation()}
        className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
      >
        <h3 className="text-xl font-bold mb-6">
          {category ? 'Edit Category' : 'Create Category'}
        </h3>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Category Name *</label>
            <Input
              placeholder="e.g., Beverages, Cleaning Supplies"
              value={form.name}
              onChange={(e) => setForm(f => ({ ...f, name: e.target.value }))}
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Color</label>
            <div className="flex gap-3 items-center">
              <input
                type="color"
                value={form.color}
                onChange={(e) => setForm(f => ({ ...f, color: e.target.value }))}
                className="w-12 h-10 rounded cursor-pointer"
              />
              <Input
                value={form.color}
                onChange={(e) => setForm(f => ({ ...f, color: e.target.value }))}
                placeholder="#6b7280"
                className="flex-1"
              />
              <div 
                className="w-10 h-10 rounded-lg flex items-center justify-center"
                style={{ backgroundColor: form.color + '20', color: form.color }}
              >
                <Package className="w-5 h-5" />
              </div>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Description (optional)</label>
            <textarea
              className="w-full p-3 border rounded-lg dark:bg-slate-700 dark:border-slate-600"
              rows={2}
              placeholder="Brief description of this category..."
              value={form.description}
              onChange={(e) => setForm(f => ({ ...f, description: e.target.value }))}
            />
          </div>
        </div>

        <div className="flex justify-end gap-3 mt-6 pt-4 border-t">
          <Button variant="outline" onClick={onClose} disabled={saving}>
            Cancel
          </Button>
          <Button onClick={handleSubmit} disabled={saving}>
            {saving ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : null}
            {category ? 'Update Category' : 'Create Category'}
          </Button>
        </div>
      </motion.div>
    </motion.div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { 
  Monitor, 
  Plus, 
  Settings2, 
  Power, 
  AlertTriangle, 
  CheckCircle2,
  WifiOff,
  Key,
  RefreshCw,
  Wrench
} from 'lucide-react';
import { toast } from 'sonner';
import api from '@/lib/api';

interface KioskDevice {
  id: string;
  property_id: string;
  location: string;
  name: string;
  status: 'online' | 'offline' | 'maintenance' | 'error';
  capabilities: string[];
  last_heartbeat: string;
  key_stock: number;
  is_active: boolean;
  config: {
    timeout_seconds?: number;
    language?: string;
    features_enabled?: string[];
  };
}

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

// Helper to get property ID from context (default to a known ID for now)
function getDefaultPropertyId(): string {
  // In production, this should come from user context or settings
  return '00000000-0000-0000-0000-000000000001';
}

async function fetchKiosks(): Promise<KioskDevice[]> {
  const propertyId = getDefaultPropertyId();
  try {
    const res = await api.get(`/kiosk/devices/property/${propertyId}?includeInactive=true`);
    return res.data?.data || [];
  } catch (err) {
    console.warn('Failed to fetch kiosks:', err);
    return [];
  }
}

export default function KioskAdminPage() {
  const queryClient = useQueryClient();
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedKiosk, setSelectedKiosk] = useState<KioskDevice | null>(null);
  const [newKioskForm, setNewKioskForm] = useState({
    name: '',
    location: '',
    capabilities: [] as string[],
  });

  const { data: kiosks = [], isLoading, error } = useQuery({
    queryKey: ['admin-kiosks'],
    queryFn: fetchKiosks,
  });

  const registerKioskMutation = useMutation({
    mutationFn: async (data: { name: string; location: string; capabilities: string[] }) => {
      const propertyId = getDefaultPropertyId();
      const res = await api.post(`/kiosk/devices/${propertyId}`, {
        deviceName: data.name,
        deviceCode: `KIOSK-${Date.now()}`,
        location: data.location,
        capabilities: {
          hasIdScanner: data.capabilities.includes('id_scanner'),
          hasCardReader: data.capabilities.includes('card_reader'),
          hasKeyEncoder: data.capabilities.includes('key_encoder'),
          hasReceiptPrinter: data.capabilities.includes('receipt_printer'),
          hasCamera: data.capabilities.includes('camera'),
        },
      });
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-kiosks'] });
      toast.success('Kiosk registered successfully');
      setShowAddModal(false);
      setNewKioskForm({ name: '', location: '', capabilities: [] });
    },
    onError: (error: any) => {
      const message = error?.response?.data?.error || 'Failed to register kiosk';
      toast.error(message);
    }
  });

  const toggleMaintenanceMutation = useMutation({
    mutationFn: async ({ deviceId, enable }: { deviceId: string; enable: boolean }) => {
      const res = await api.post(`/kiosk/devices/${deviceId}/maintenance`, { enabled: enable });
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-kiosks'] });
      toast.success('Maintenance mode updated');
    },
    onError: () => toast.error('Failed to update maintenance mode')
  });

  const refillKeysMutation = useMutation({
    mutationFn: async ({ kioskId, quantity }: { kioskId: string; quantity: number }) => {
      const res = await api.post(`/kiosk/key-stock/${kioskId}/refill`, { quantity });
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-kiosks'] });
      toast.success('Key stock refilled');
    },
    onError: () => toast.error('Failed to refill keys')
  });

  const deactivateMutation = useMutation({
    mutationFn: async (deviceId: string) => {
      const res = await api.delete(`/kiosk/devices/${deviceId}`);
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-kiosks'] });
      toast.success('Kiosk deactivated');
    },
    onError: () => toast.error('Failed to deactivate kiosk')
  });

  const handleRegisterSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newKioskForm.name.trim()) {
      toast.error('Device name is required');
      return;
    }
    registerKioskMutation.mutate(newKioskForm);
  };

  const toggleCapability = (cap: string) => {
    setNewKioskForm(prev => ({
      ...prev,
      capabilities: prev.capabilities.includes(cap)
        ? prev.capabilities.filter(c => c !== cap)
        : [...prev.capabilities, cap]
    }));
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'online': return <CheckCircle2 className="h-5 w-5 text-green-500" />;
      case 'offline': return <WifiOff className="h-5 w-5 text-gray-400" />;
      case 'maintenance': return <Wrench className="h-5 w-5 text-yellow-500" />;
      case 'error': return <AlertTriangle className="h-5 w-5 text-red-500" />;
      default: return <Monitor className="h-5 w-5 text-gray-400" />;
    }
  };

  const getStatusBadge = (status: string) => {
    const colors: Record<string, string> = {
      online: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200',
      offline: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200',
      maintenance: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200',
      error: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200'
    };
    return colors[status] || colors.offline;
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
        <p className="text-red-800 dark:text-red-200">Failed to load kiosks. Please try again.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Kiosk Management</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">
            Manage self-service kiosk devices
          </p>
        </div>
        <button
          onClick={() => setShowAddModal(true)}
          className="flex items-center gap-2 bg-primary text-white px-4 py-2 rounded-lg hover:bg-primary/90 transition-colors"
        >
          <Plus className="h-4 w-4" />
          Add Kiosk
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 rounded-lg p-4 border border-gray-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-100 dark:bg-blue-900 rounded-lg">
              <Monitor className="h-5 w-5 text-blue-600 dark:text-blue-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">{kiosks.length}</p>
              <p className="text-sm text-gray-500 dark:text-gray-400">Total Kiosks</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-lg p-4 border border-gray-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-green-100 dark:bg-green-900 rounded-lg">
              <CheckCircle2 className="h-5 w-5 text-green-600 dark:text-green-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {kiosks.filter(k => k.status === 'online').length}
              </p>
              <p className="text-sm text-gray-500 dark:text-gray-400">Online</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-lg p-4 border border-gray-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-yellow-100 dark:bg-yellow-900 rounded-lg">
              <Wrench className="h-5 w-5 text-yellow-600 dark:text-yellow-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {kiosks.filter(k => k.status === 'maintenance').length}
              </p>
              <p className="text-sm text-gray-500 dark:text-gray-400">Maintenance</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-lg p-4 border border-gray-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-red-100 dark:bg-red-900 rounded-lg">
              <AlertTriangle className="h-5 w-5 text-red-600 dark:text-red-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {kiosks.filter(k => k.status === 'error').length}
              </p>
              <p className="text-sm text-gray-500 dark:text-gray-400">Errors</p>
            </div>
          </div>
        </div>
      </div>

      {/* Kiosk List */}
      <div className="bg-white dark:bg-slate-800 rounded-lg border border-gray-200 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 dark:bg-slate-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  Device
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  Status
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  Location
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  Key Stock
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  Last Seen
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 dark:divide-slate-700">
              {kiosks.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center">
                    <Monitor className="h-12 w-12 mx-auto text-gray-300 dark:text-gray-600 mb-4" />
                    <p className="text-gray-500 dark:text-gray-400">No kiosks registered yet</p>
                    <button
                      onClick={() => setShowAddModal(true)}
                      className="mt-4 text-primary hover:underline"
                    >
                      Register your first kiosk
                    </button>
                  </td>
                </tr>
              ) : kiosks.map((kiosk) => (
                <tr key={kiosk.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/50">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-3">
                      {getStatusIcon(kiosk.status)}
                      <div>
                        <p className="font-medium text-gray-900 dark:text-white">{kiosk.name}</p>
                        <p className="text-sm text-gray-500 dark:text-gray-400">{kiosk.id.slice(0, 8)}...</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadge(kiosk.status)}`}>
                      {kiosk.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-gray-700 dark:text-gray-300">
                    {kiosk.location || 'Not set'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-2">
                      <Key className="h-4 w-4 text-gray-400" />
                      <span className={`font-medium ${kiosk.key_stock < 10 ? 'text-red-600' : 'text-gray-700 dark:text-gray-300'}`}>
                        {kiosk.key_stock}
                      </span>
                      {kiosk.key_stock < 10 && (
                        <button
                          onClick={() => refillKeysMutation.mutate({ kioskId: kiosk.id, quantity: 50 })}
                          className="text-xs text-primary hover:underline"
                        >
                          Refill
                        </button>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-gray-500 dark:text-gray-400 text-sm">
                    {kiosk.last_heartbeat 
                      ? new Date(kiosk.last_heartbeat).toLocaleString()
                      : 'Never'
                    }
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        onClick={() => setSelectedKiosk(kiosk)}
                        className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
                        title="Settings"
                      >
                        <Settings2 className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => toggleMaintenanceMutation.mutate({ 
                          deviceId: kiosk.id, 
                          enable: kiosk.status !== 'maintenance' 
                        })}
                        className={`p-2 ${kiosk.status === 'maintenance' ? 'text-yellow-500' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}
                        title={kiosk.status === 'maintenance' ? 'Exit Maintenance' : 'Enter Maintenance'}
                      >
                        <Wrench className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => {
                          if (confirm('Are you sure you want to deactivate this kiosk?')) {
                            deactivateMutation.mutate(kiosk.id);
                          }
                        }}
                        className="p-2 text-gray-400 hover:text-red-600"
                        title="Deactivate"
                      >
                        <Power className="h-4 w-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add/Edit Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md mx-4">
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Register New Kiosk</h2>
            <form onSubmit={handleRegisterSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Device Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  placeholder="Lobby Kiosk 1"
                  value={newKioskForm.name}
                  onChange={(e) => setNewKioskForm(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-gray-900 dark:text-white"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Location
                </label>
                <input
                  type="text"
                  placeholder="Main Lobby"
                  value={newKioskForm.location}
                  onChange={(e) => setNewKioskForm(prev => ({ ...prev, location: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-gray-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Capabilities
                </label>
                <div className="grid grid-cols-2 gap-2">
                  {['id_scanner', 'card_reader', 'key_encoder', 'receipt_printer', 'camera'].map(cap => (
                    <label key={cap} className="flex items-center gap-2">
                      <input 
                        type="checkbox" 
                        className="rounded" 
                        checked={newKioskForm.capabilities.includes(cap)}
                        onChange={() => toggleCapability(cap)}
                      />
                      <span className="text-sm text-gray-700 dark:text-gray-300 capitalize">
                        {cap.replace('_', ' ')}
                      </span>
                    </label>
                  ))}
                </div>
              </div>
              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => {
                    setShowAddModal(false);
                    setNewKioskForm({ name: '', location: '', capabilities: [] });
                  }}
                  className="flex-1 px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-slate-700"
                  disabled={registerKioskMutation.isPending}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="flex-1 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                  disabled={registerKioskMutation.isPending}
                >
                  {registerKioskMutation.isPending ? (
                    <>
                      <RefreshCw className="h-4 w-4 animate-spin" />
                      Registering...
                    </>
                  ) : (
                    'Register'
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { motion, AnimatePresence } from 'framer-motion';
import { ReactNode, useState, useEffect, useMemo, useCallback } from 'react';
import { useAuth } from '@/lib/auth-context';
import { useSiteSettings } from '@/lib/settings-context';
import { cn } from '@/lib/cn';
import { ThemeToggle } from '@/components/ThemeToggle';
import { LanguageSwitcher } from '@/components/LanguageSwitcher';
import { CurrencySwitcher } from '@/components/CurrencySwitcher';
import { api } from '@/lib/api';
import {
  Menu,
  X,
  ChevronDown,
  ChevronRight,
  Bell,
  LogOut,
  Search,
} from 'lucide-react';
import { toast } from 'sonner';
import {
  type NavCategory,
  type NavItem,
  getStaticNavigation,
  getModuleChildren,
  moduleTypeIcons,
  filterNavigationByRole,
  flattenNavigation,
  getInitialExpandedCategories,
  saveExpandedCategories,
  SIDEBAR_EXPANDED_KEY,
} from '@/config/admin-navigation';

interface AdminLayoutProps {
  children: ReactNode;
}

export default function AdminLayout({ children }: AdminLayoutProps) {
  const pathname = usePathname();
  const router = useRouter();
  const t = useTranslations('admin');
  const { modules, settings } = useSiteSettings();
  const { user, logout, isAuthenticated, isLoading } = useAuth();
  
  // Dynamic branding from CMS
  const resortName = settings.resortName || 'Your Business';
  const logoText = resortName.substring(0, 2).toUpperCase();

  // Sidebar state
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [expandedCategories, setExpandedCategories] = useState<string[]>(['modules']);
  const [expandedItems, setExpandedItems] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [authChecked, setAuthChecked] = useState(false);
  
  // Notifications state
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [notifications, setNotifications] = useState<Array<{ id: string; title: string; message: string; time: string; read: boolean }>>([]);
  const [loadingNotifications, setLoadingNotifications] = useState(true);

  // Load persisted sidebar state
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const savedSidebar = localStorage.getItem(SIDEBAR_EXPANDED_KEY);
      if (savedSidebar !== null) {
        setSidebarOpen(savedSidebar === 'true');
      }
      setExpandedCategories(getInitialExpandedCategories());
    }
  }, []);

  // Build navigation with categories
  const navigation = useMemo((): NavCategory[] => {
    const categories = getStaticNavigation(t);
    
    // Populate modules category with actual modules from database
    const modulesCategory = categories.find(c => c.id === 'modules');
    if (modulesCategory && modules && modules.length > 0) {
      const activeModules = modules
        .filter(m => m.is_active)
        .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
      
      modulesCategory.items = activeModules.map(module => {
        const icon = moduleTypeIcons[module.template_type] || moduleTypeIcons.default;
        const children = getModuleChildren(module.slug, module.template_type, t);
        
        return {
          name: module.name,
          href: `/admin/${encodeURIComponent(module.slug)}`,
          icon,
          children: children.length > 0 ? children : undefined,
        };
      });
    }
    
    // Filter by user roles
    const userRoles = user?.roles || [];
    return filterNavigationByRole(categories, userRoles.length > 0 ? userRoles : ['admin']);
  }, [modules, t, user?.roles]);

  // Flatten for search
  const searchableItems = useMemo(() => flattenNavigation(navigation), [navigation]);

  // Filtered items based on search
  const filteredItems = useMemo(() => {
    if (!searchQuery.trim()) return null;
    const query = searchQuery.toLowerCase();
    return searchableItems.filter(item => 
      item.name.toLowerCase().includes(query) || 
      item.category.toLowerCase().includes(query)
    );
  }, [searchQuery, searchableItems]);

  // Toggle category expansion
  const toggleCategory = useCallback((categoryId: string) => {
    setExpandedCategories(prev => {
      const next = prev.includes(categoryId) 
        ? prev.filter(id => id !== categoryId)
        : [...prev, categoryId];
      saveExpandedCategories(next);
      return next;
    });
  }, []);

  // Toggle item expansion (for items with children)
  const toggleItem = useCallback((itemName: string) => {
    setExpandedItems(prev => 
      prev.includes(itemName) 
        ? prev.filter(n => n !== itemName)
        : [...prev, itemName]
    );
  }, []);

  // Persist sidebar state
  const handleSidebarToggle = useCallback(() => {
    setSidebarOpen(prev => {
      const next = !prev;
      if (typeof window !== 'undefined') {
        localStorage.setItem(SIDEBAR_EXPANDED_KEY, String(next));
      }
      return next;
    });
  }, []);

  // Fetch notifications
  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        const response = await api.get('/admin/notifications');
        if (response.data?.success && response.data?.data) {
          setNotifications(response.data.data);
        }
      } catch {
        setNotifications([]);
      } finally {
        setLoadingNotifications(false);
      }
    };

    if (isAuthenticated) {
      fetchNotifications();
      const interval = setInterval(fetchNotifications, 30000);
      return () => clearInterval(interval);
    }
  }, [isAuthenticated]);

  const unreadCount = notifications.filter(n => !n.read).length;

  const markAsRead = (id: string) => {
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, read: true })));
  };

  // Check authentication
  useEffect(() => {
    if (!isLoading) {
      setAuthChecked(true);
      if (!isAuthenticated) {
        router.push('/login?redirect=/admin');
      } else if (user && !user.roles.some(role => ['admin', 'super_admin'].includes(role))) {
        toast.error(t('errors.accessDenied') || 'Access denied. Admin privileges required.');
        router.push('/');
      }
    }
  }, [isAuthenticated, isLoading, router, user, t]);

  const handleLogout = async () => {
    await logout();
    toast.success(t('messages.loggedOutSuccessfully'));
    router.push('/');
  };

  if (isLoading || !authChecked || !isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-900 flex items-center justify-center">
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
          className="w-8 h-8 border-2 border-blue-600 border-t-transparent rounded-full"
        />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900">
      {/* Mobile Header */}
      <header className="lg:hidden fixed top-0 left-0 right-0 z-[200] backdrop-blur-xl bg-white/80 dark:bg-slate-900/80 border-b border-slate-200/50 dark:border-slate-700/50 px-4 h-16 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-3">
          <button
            onClick={() => setMobileMenuOpen(true)}
            className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
          >
            <Menu className="h-5 w-5 text-slate-600 dark:text-slate-400" />
          </button>
          <div className="bg-gradient-to-br from-blue-600 to-purple-600 text-white font-bold text-lg px-2.5 py-1 rounded-lg">
            {logoText}
          </div>
          <span className="font-semibold text-slate-900 dark:text-white">Admin</span>
        </div>
        <div className="flex items-center gap-2">
          <CurrencySwitcher />
          <ThemeToggle />
          <LanguageSwitcher />
        </div>
      </header>

      {/* Mobile Sidebar Overlay */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setMobileMenuOpen(false)}
              className="lg:hidden fixed inset-0 z-[200] bg-black/50"
            />
            <motion.aside
              initial={{ x: '-100%' }}
              animate={{ x: 0 }}
              exit={{ x: '-100%' }}
              transition={{ type: 'spring', damping: 30, stiffness: 300 }}
              className="lg:hidden fixed inset-y-0 left-0 z-[200] w-72 backdrop-blur-xl bg-gradient-to-b from-white/95 via-slate-50/90 to-white/95 dark:from-slate-900/95 dark:via-slate-800/90 dark:to-slate-900/95 shadow-2xl border-r border-slate-200/30 dark:border-slate-700/30"
            >
              <div className="flex items-center justify-between p-4 border-b border-slate-200/50 dark:border-slate-700/50">
                <div className="flex items-center gap-2">
                  <div className="bg-gradient-to-br from-blue-600 to-purple-600 text-white font-bold text-lg px-2.5 py-1 rounded-lg">
                    {logoText}
                  </div>
                  <span className="font-semibold text-slate-900 dark:text-white">Admin Panel</span>
                </div>
                <button
                  onClick={() => setMobileMenuOpen(false)}
                  className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
                >
                  <X className="h-5 w-5 text-slate-600 dark:text-slate-400" />
                </button>
              </div>
              
              {/* Mobile Search */}
              <div className="p-3 border-b border-slate-200/50 dark:border-slate-700/50">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                  <input
                    type="text"
                    placeholder="Search pages..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-9 pr-3 py-2 text-sm bg-slate-100 dark:bg-slate-800 rounded-lg border-0 focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>
              
              <nav className="p-3 space-y-1 overflow-y-auto max-h-[calc(100vh-200px)]">
                {filteredItems ? (
                  // Search results
                  <div className="space-y-1">
                    <p className="px-3 py-1 text-xs font-medium text-slate-500 uppercase">
                      {filteredItems.length} results
                    </p>
                    {filteredItems.map((item) => (
                      <Link
                        key={item.href}
                        href={item.href}
                        onClick={() => {
                          setMobileMenuOpen(false);
                          setSearchQuery('');
                        }}
                        className={cn(
                          'block px-3 py-2 rounded-lg text-sm',
                          pathname === item.href
                            ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600'
                            : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'
                        )}
                      >
                        <span className="font-medium">{item.name}</span>
                        <span className="text-xs text-slate-400 ml-2">in {item.category}</span>
                      </Link>
                    ))}
                  </div>
                ) : (
                  // Normal navigation
                  navigation.map((category) => (
                    <CategorySection
                      key={category.id}
                      category={category}
                      pathname={pathname}
                      expanded={expandedCategories.includes(category.id)}
                      onToggleCategory={() => toggleCategory(category.id)}
                      expandedItems={expandedItems}
                      onToggleItem={toggleItem}
                      onNavigate={() => setMobileMenuOpen(false)}
                      collapsed={false}
                    />
                  ))
                )}
              </nav>
              
              <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-slate-200/50 dark:border-slate-700/50 bg-gradient-to-t from-white dark:from-slate-900 to-transparent">
                <button
                  onClick={handleLogout}
                  className="w-full flex items-center gap-3 px-4 py-3 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-colors"
                >
                  <LogOut className="h-5 w-5" />
                  <span>{t('nav.logout')}</span>
                </button>
              </div>
            </motion.aside>
          </>
        )}
      </AnimatePresence>

      {/* Desktop Sidebar */}
      <aside
        className={cn(
          'hidden lg:flex flex-col fixed inset-y-0 left-0 z-40 transition-all duration-300',
          'bg-gradient-to-b from-slate-50/95 via-white/90 to-slate-50/95',
          'dark:from-slate-900/95 dark:via-slate-800/90 dark:to-slate-900/95',
          'backdrop-blur-xl border-r border-slate-200/50 dark:border-slate-700/50',
          'shadow-[4px_0_24px_-4px_rgba(0,0,0,0.1)] dark:shadow-[4px_0_24px_-4px_rgba(0,0,0,0.3)]',
          sidebarOpen ? 'w-64' : 'w-20'
        )}
      >
        {/* Logo */}
        <div className="h-16 flex items-center justify-between px-4 border-b border-slate-200/50 dark:border-slate-700/50">
          <div className="flex items-center gap-2">
            <div className="bg-gradient-to-br from-blue-600 to-purple-600 text-white font-bold text-lg px-2.5 py-1 rounded-lg shrink-0">
              {logoText}
            </div>
            {sidebarOpen && (
              <motion.span
                initial={{ opacity: 0, width: 0 }}
                animate={{ opacity: 1, width: 'auto' }}
                exit={{ opacity: 0, width: 0 }}
                className="font-semibold text-slate-900 dark:text-white whitespace-nowrap overflow-hidden"
              >
                Admin Panel
              </motion.span>
            )}
          </div>
          <button
            onClick={handleSidebarToggle}
            className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
          >
            <Menu className="h-4 w-4 text-slate-600 dark:text-slate-400" />
          </button>
        </div>

        {/* Search */}
        {sidebarOpen && (
          <div className="p-3 border-b border-slate-200/50 dark:border-slate-700/50">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
              <input
                type="text"
                placeholder="Search pages..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-9 pr-3 py-2 text-sm bg-slate-100 dark:bg-slate-800 rounded-lg border-0 focus:ring-2 focus:ring-blue-500 placeholder:text-slate-400"
              />
            </div>
          </div>
        )}

        {/* Navigation */}
        <nav className="flex-1 p-3 space-y-1 overflow-y-auto scrollbar-thin scrollbar-thumb-slate-300 dark:scrollbar-thumb-slate-600">
          {filteredItems ? (
            // Search results
            <div className="space-y-1">
              {sidebarOpen && (
                <p className="px-3 py-1 text-xs font-medium text-slate-500 uppercase">
                  {filteredItems.length} results
                </p>
              )}
              {filteredItems.map((item) => (
                <Link
                  key={item.href}
