} from 'lucide-react';

interface LoyaltyTier {
  id: string;
  name: string;
  min_points: number;
  points_multiplier: number;
  color: string;
  benefits: Record<string, any>;
  is_active: boolean;
}

interface LoyaltyAccount {
  id: string;
  user_id: string;
  user?: {
    id: string;
    full_name: string;
    email: string;
  };
  tier?: {
    id: string;
    name: string;
    color: string;
  };
  // Legacy direct fields for compatibility
  user_name?: string;
  user_email?: string;
  current_tier?: string;
  tier_name?: string;
  tier_color?: string;
  available_points?: number;
  total_points: number;
  lifetime_points: number;
  redeemed_points?: number;
  created_at: string;
}

interface LoyaltyTransaction {
  id: string;
  type: string;
  points: number;
  description: string;
  order_type: string;
  created_at: string;
  user_name?: string;
}

interface LoyaltyStats {
  totalMembers: number;
  totalPointsIssued: number;
  totalPointsRedeemed: number;
  activeMembers30Days: number;
  tierDistribution: Array<{ tier_name: string; tier_color: string; count: number }>;
}

// Map backend response structure to frontend LoyaltyStats interface
function mapBackendStats(raw: any): LoyaltyStats {
  const summary = raw?.summary || raw || {};
  return {
    totalMembers: summary.total_members ?? summary.totalMembers ?? 0,
    totalPointsIssued: summary.total_lifetime_points ?? summary.totalPointsIssued ?? 0,
    totalPointsRedeemed: summary.total_outstanding_points
      ? (summary.total_lifetime_points || 0) - (summary.total_outstanding_points || 0)
      : summary.totalPointsRedeemed ?? 0,
    activeMembers30Days: summary.active_members_30_days ?? summary.activeMembers30Days ?? 0,
    tierDistribution: (raw?.tierDistribution || []).map((t: any) => ({
      tier_name: t.tier_name || t.name || 'Unknown',
      tier_color: t.tier_color || t.color || '#6b7280',
      count: t.count || 0,
    })),
  };
}

interface LoyaltySettings {
  points_per_dollar: number;
  redemption_value: number;
  min_redemption_points: number;
  points_expiry_days: number;
}

export default function LoyaltyAdminPage() {
  const [activeTab, setActiveTab] = useState('overview');
  const [tiers, setTiers] = useState<LoyaltyTier[]>([]);
  const [accounts, setAccounts] = useState<LoyaltyAccount[]>([]);
  const [transactions, setTransactions] = useState<LoyaltyTransaction[]>([]);
  const [stats, setStats] = useState<LoyaltyStats | null>(null);
  const [settings, setSettings] = useState<LoyaltySettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [editingTier, setEditingTier] = useState<LoyaltyTier | null>(null);
  const [showTierModal, setShowTierModal] = useState(false);
  const [showAdjustModal, setShowAdjustModal] = useState(false);
  const [selectedAccount, setSelectedAccount] = useState<LoyaltyAccount | null>(null);
  const [adjustAmount, setAdjustAmount] = useState('');
  const [adjustReason, setAdjustReason] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [tiersRes, statsRes, settingsRes] = await Promise.all([
        api.get('/loyalty/tiers'),
        api.get('/loyalty/stats'),
        api.get('/loyalty/settings'),
      ]);

      if (tiersRes.data.success) setTiers(tiersRes.data.data);
      if (statsRes.data.success) setStats(mapBackendStats(statsRes.data.data));
      if (settingsRes.data.success) setSettings(settingsRes.data.data);
    } catch (error) {
      toast.error('Failed to load loyalty data');
    } finally {
      setLoading(false);
    }
  };

  const loadAccounts = async () => {
    try {
      const res = await api.get('/loyalty/accounts', { params: { search: searchQuery } });
      if (res.data.success) setAccounts(res.data.data);
    } catch (error) {
      toast.error('Failed to load accounts');
    }
  };

  useEffect(() => {
    if (activeTab === 'members') {
      loadAccounts();
    }
  }, [activeTab, searchQuery]);

  const handleUpdateSettings = async () => {
    if (!settings) return;
    try {
      const res = await api.put('/loyalty/settings', settings);
      if (res.data.success) {
        toast.success('Settings updated');
      }
    } catch (error) {
      toast.error('Failed to update settings');
    }
  };

  const handleAdjustPoints = async () => {
    if (!selectedAccount || !adjustAmount) return;
    try {
      const res = await api.post(`/loyalty/accounts/${selectedAccount.id}/adjust`, {
        points: parseInt(adjustAmount),
        reason: adjustReason || 'Manual adjustment by admin',
      });
      if (res.data.success) {
        toast.success('Points adjusted');
        setShowAdjustModal(false);
        setSelectedAccount(null);
        setAdjustAmount('');
        setAdjustReason('');
        loadAccounts();
      }
    } catch (error) {
      toast.error('Failed to adjust points');
    }
  };

  const getTierIcon = (tierName: string) => {
    switch (tierName.toLowerCase()) {
      case 'platinum': return <Crown className="w-5 h-5" />;
      case 'gold': return <Medal className="w-5 h-5" />;
      case 'silver': return <Award className="w-5 h-5" />;
      default: return <Star className="w-5 h-5" />;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <RefreshCw className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Loyalty Program</h1>
          <p className="text-slate-500 dark:text-slate-400">Manage rewards, tiers, and member points</p>
        </div>
        <Button onClick={() => loadData()} variant="outline" className="gap-2">
          <RefreshCw className="w-4 h-4" />
          Refresh
        </Button>
      </div>

      {/* Stats Cards */}
      <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-blue-100 text-sm">Total Members</p>
                <p className="text-3xl font-bold">{stats?.totalMembers?.toLocaleString() || 0}</p>
              </div>
              <Users className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-amber-500 to-amber-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-amber-100 text-sm">Points Issued</p>
                <p className="text-3xl font-bold">{stats?.totalPointsIssued?.toLocaleString() || 0}</p>
              </div>
              <Coins className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-green-100 text-sm">Points Redeemed</p>
                <p className="text-3xl font-bold">{stats?.totalPointsRedeemed?.toLocaleString() || 0}</p>
              </div>
              <Gift className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
        
        <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-purple-100 text-sm">Active (30 days)</p>
                <p className="text-3xl font-bold">{stats?.activeMembers30Days?.toLocaleString() || 0}</p>
              </div>
              <TrendingUp className="w-10 h-10 opacity-80" />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid grid-cols-4 w-full max-w-lg">
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="members">Members</TabsTrigger>
          <TabsTrigger value="tiers">Tiers</TabsTrigger>
          <TabsTrigger value="settings">Settings</TabsTrigger>
        </TabsList>

        {/* Overview Tab */}
        <TabsContent value="overview" className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Tier Distribution */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Trophy className="w-5 h-5 text-amber-500" />
                  Tier Distribution
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {stats?.tierDistribution?.map((tier) => (
                    <div key={tier.tier_name} className="flex items-center gap-4">
                      <div 
                        className="w-4 h-4 rounded-full" 
                        style={{ backgroundColor: tier.tier_color }}
                      />
                      <span className="flex-1 font-medium">{tier.tier_name}</span>
                      <span className="text-slate-500">{tier.count} members</span>
                      <div className="w-24 bg-slate-200 dark:bg-slate-700 rounded-full h-2">
                        <div 
                          className="h-2 rounded-full" 
                          style={{ 
                            backgroundColor: tier.tier_color,
                            width: `${(tier.count / (stats?.totalMembers || 1)) * 100}%` 
                          }}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            {/* Tiers Preview */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Star className="w-5 h-5 text-amber-500" />
                  Tier Levels
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {tiers.filter(t => t.is_active).map((tier) => (
                    <div 
                      key={tier.id} 
                      className="p-4 rounded-lg border-2 flex items-center gap-4"
                      style={{ borderColor: tier.color }}
                    >
                      <div 
                        className="w-12 h-12 rounded-full flex items-center justify-center"
                        style={{ backgroundColor: tier.color + '20', color: tier.color }}
                      >
                        {getTierIcon(tier.name)}
                      </div>
                      <div className="flex-1">
                        <h3 className="font-semibold">{tier.name}</h3>
                        <p className="text-sm text-slate-500">
                          {tier.min_points.toLocaleString()}+ points • {tier.points_multiplier}x multiplier
                        </p>
                      </div>
                      <ChevronRight className="w-5 h-5 text-slate-400" />
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        {/* Members Tab */}
        <TabsContent value="members" className="space-y-4">
          <div className="flex gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
              <Input
                placeholder="Search members by name or email..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <Button variant="outline" onClick={loadAccounts}>
              <RefreshCw className="w-4 h-4" />
            </Button>
          </div>

          <Card>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b dark:border-slate-700">
                      <th className="text-left p-4 font-medium text-slate-500">Member</th>
                      <th className="text-left p-4 font-medium text-slate-500">Tier</th>
                      <th className="text-right p-4 font-medium text-slate-500">Current Points</th>
                      <th className="text-right p-4 font-medium text-slate-500">Lifetime Points</th>
                      <th className="text-left p-4 font-medium text-slate-500">Joined</th>
                      <th className="text-right p-4 font-medium text-slate-500">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {accounts.map((account) => {
                      // Handle both nested and flat structures
                      const userName = account.user?.full_name || account.user_name || 'Unknown';
                      const userEmail = account.user?.email || account.user_email || '';
                      const tierName = account.tier?.name || account.tier_name || 'Bronze';
                      const tierColor = account.tier?.color || account.tier_color || '#CD7F32';
                      const currentPoints = account.available_points ?? account.total_points ?? 0;
                      const lifetimePoints = account.lifetime_points ?? 0;
                      
                      return (
                        <tr key={account.id} className="border-b dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800">
                          <td className="p-4">
                            <div>
                              <p className="font-medium">{userName}</p>
                              <p className="text-sm text-slate-500">{userEmail}</p>
                            </div>
                          </td>
                          <td className="p-4">
                            <Badge 
                              style={{ backgroundColor: tierColor + '20', color: tierColor }}
                            >
                              {tierName}
                            </Badge>
                          </td>
                          <td className="p-4 text-right font-semibold">
                            {currentPoints.toLocaleString()}
                          </td>
                          <td className="p-4 text-right text-slate-500">
                            {lifetimePoints.toLocaleString()}
                          </td>
                          <td className="p-4 text-slate-500">
                            {formatDate(account.created_at)}
                          </td>
                          <td className="p-4 text-right">
                            <Button 
                              variant="outline" 
                              size="sm"
                              onClick={() => {
                                setSelectedAccount(account);
                                setShowAdjustModal(true);
                            }}
                          >
                            <ArrowUpDown className="w-4 h-4 mr-1" />
                            Adjust
                          </Button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Tiers Tab */}
        <TabsContent value="tiers" className="space-y-4">
          <div className="flex justify-end">
            <Button onClick={() => { setEditingTier(null); setShowTierModal(true); }}>
              <Plus className="w-4 h-4 mr-2" />
              Add Tier
            </Button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {tiers.map((tier) => (
              <Card 
                key={tier.id} 
                className={`relative overflow-hidden ${!tier.is_active ? 'opacity-50' : ''}`}
              >
                <div 
                  className="absolute top-0 left-0 right-0 h-1" 
                  style={{ backgroundColor: tier.color }}
                />
                <CardContent className="p-6">
                  <div className="flex items-start justify-between mb-4">
                    <div 
                      className="w-12 h-12 rounded-full flex items-center justify-center"
                      style={{ backgroundColor: tier.color + '20', color: tier.color }}
                    >
                      {getTierIcon(tier.name)}
                    </div>
                    <div className="flex gap-1">
                      <Button 
                        variant="ghost" 
                        size="sm"
                        onClick={() => { setEditingTier(tier); setShowTierModal(true); }}
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button 
                        variant="ghost" 
                        size="sm"
                        className="text-red-500 hover:text-red-700 hover:bg-red-50"
                        onClick={async () => {
                          if (!confirm(`Are you sure you want to delete the "${tier.name}" tier? Members will be migrated to another tier.`)) return;
                          try {
                            // Ensure CSRF token is present
                            const csrfCookie = document.cookie.match(/(^| )csrf-token=([^;]+)/);
                            let csrfToken = csrfCookie ? csrfCookie[2] : undefined;
                            if (!csrfToken) {
                              // Fetch new CSRF token
                              const res = await api.get('/csrf-token');
                              csrfToken = res.data.csrfToken;
                            }
                            await api.delete(`/loyalty/tiers/${tier.id}`, {
                              headers: { 'X-CSRF-Token': csrfToken },
                              withCredentials: true,
                            });
                            toast.success('Tier deleted successfully');
                            loadData();
                          } catch (error: any) {
                            toast.error(error.response?.data?.error || 'Failed to delete tier');
                          }
                        }}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                  <h3 className="text-xl font-bold mb-2">{tier.name}</h3>
                  <div className="space-y-2 text-sm text-slate-500">
                    <p>Min Points: {tier.min_points.toLocaleString()}</p>
                    <p>Multiplier: {tier.points_multiplier}x</p>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Settings Tab */}
        <TabsContent value="settings" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Settings className="w-5 h-5" />
                Program Settings
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium mb-2">Points per Dollar Spent</label>
                  <Input
                    type="number"
                    value={settings?.points_per_dollar || 1}
                    onChange={(e) => setSettings(s => s ? { ...s, points_per_dollar: parseFloat(e.target.value) } : null)}
                  />
                  <p className="text-xs text-slate-500 mt-1">How many points customers earn per $1 spent</p>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Point Redemption Value ($)</label>
                  <Input
                    type="number"
                    step="0.01"
                    value={settings?.redemption_value || 0.01}
                    onChange={(e) => setSettings(s => s ? { ...s, redemption_value: parseFloat(e.target.value) } : null)}
                  />
                  <p className="text-xs text-slate-500 mt-1">Dollar value of each point when redeemed</p>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Minimum Redemption Points</label>
                  <Input
                    type="number"
                    value={settings?.min_redemption_points || 100}
                    onChange={(e) => setSettings(s => s ? { ...s, min_redemption_points: parseInt(e.target.value) } : null)}
                  />
                  <p className="text-xs text-slate-500 mt-1">Minimum points required to redeem</p>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Points Expiry (Days)</label>
                  <Input
                    type="number"
                    value={settings?.points_expiry_days || 365}
                    onChange={(e) => setSettings(s => s ? { ...s, points_expiry_days: parseInt(e.target.value) } : null)}
                  />
                  <p className="text-xs text-slate-500 mt-1">Days until points expire (0 = never)</p>
                </div>
              </div>
              
              <div className="flex justify-end">
                <Button onClick={handleUpdateSettings}>
                  Save Settings
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Adjust Points Modal */}
      <AnimatePresence>
        {showAdjustModal && selectedAccount && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]"
            onClick={() => setShowAdjustModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-md shadow-2xl"
            >
              <h3 className="text-xl font-bold mb-4">Adjust Points</h3>
              <p className="text-slate-500 mb-4">
                Adjusting points for <strong>{selectedAccount.user_name}</strong>
                <br />
                Current balance: <strong>{selectedAccount.total_points.toLocaleString()}</strong> points
              </p>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-2">Point Adjustment</label>
                  <Input
                    type="number"
                    placeholder="Enter positive or negative amount"
                    value={adjustAmount}
                    onChange={(e) => setAdjustAmount(e.target.value)}
                  />
                  <p className="text-xs text-slate-500 mt-1">Use negative values to deduct points</p>
                </div>
                
                <div>
                  <label className="block text-sm font-medium mb-2">Reason</label>
                  <Input
                    placeholder="Reason for adjustment"
                    value={adjustReason}
                    onChange={(e) => setAdjustReason(e.target.value)}
                  />
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <Button variant="outline" onClick={() => setShowAdjustModal(false)}>
                  Cancel
                </Button>
                <Button onClick={handleAdjustPoints}>
                  Adjust Points
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Tier Create/Edit Modal */}
      <AnimatePresence>
        {showTierModal && (
          <TierModal
            tier={editingTier}
            onClose={() => { setShowTierModal(false); setEditingTier(null); }}
            onSave={async (tierData) => {
              try {
                if (editingTier) {
                  const res = await api.put(`/loyalty/tiers/${editingTier.id}`, tierData);
                  if (res.data.success) {
                    toast.success('Tier updated');
                  }
                } else {
                  const res = await api.post('/loyalty/tiers', tierData);
                  if (res.data.success) {
                    toast.success('Tier created');
                  }
                }
                setShowTierModal(false);
                setEditingTier(null);
                loadData();
              } catch (error) {
                toast.error('Failed to save tier');
              }
            }}
          />
        )}
      </AnimatePresence>
    </motion.div>
  );
}

// Tier Modal Component
interface TierModalProps {
  tier: LoyaltyTier | null;
  onClose: () => void;
  onSave: (data: Partial<LoyaltyTier>) => Promise<void>;
}

function TierModal({ tier, onClose, onSave }: TierModalProps) {
  const [form, setForm] = useState({
    name: tier?.name || '',
    min_points: tier?.min_points?.toString() || '0',
    points_multiplier: tier?.points_multiplier?.toString() || '1',
    color: tier?.color || '#3b82f6',
    benefits: tier?.benefits || {},
    is_active: tier?.is_active ?? true,
  });
  const [saving, setSaving] = useState(false);
  const [benefitKey, setBenefitKey] = useState('');
  const [benefitValue, setBenefitValue] = useState('');

  const handleSubmit = async () => {
    if (!form.name) {
      toast.error('Name is required');
      return;
    }
    setSaving(true);
    await onSave({
      name: form.name,
      min_points: parseInt(form.min_points) || 0,
      points_multiplier: parseFloat(form.points_multiplier) || 1,
      color: form.color,
      benefits: form.benefits,
      is_active: form.is_active,
    });
    setSaving(false);
  };

  const addBenefit = () => {
    if (benefitKey && benefitValue) {
      setForm(f => ({
        ...f,
        benefits: { ...f.benefits, [benefitKey]: benefitValue }
      }));
      setBenefitKey('');
      setBenefitValue('');
    }
  };

  const removeBenefit = (key: string) => {
    setForm(f => {
      const newBenefits = { ...f.benefits };
      delete newBenefits[key];
      return { ...f, benefits: newBenefits };
    });
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.95, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.95, opacity: 0 }}
        onClick={(e) => e.stopPropagation()}
        className="bg-white dark:bg-slate-800 rounded-xl p-6 w-full max-w-lg shadow-2xl max-h-[90vh] overflow-y-auto"
      >
        <h3 className="text-xl font-bold mb-6">{tier ? 'Edit Tier' : 'Create Tier'}</h3>
        
        <div className="space-y-4">
          {/* Name */}
          <div>
            <label className="block text-sm font-medium mb-2">Tier Name *</label>
            <Input
              placeholder="e.g., Gold, Platinum, Diamond"
              value={form.name}
              onChange={(e) => setForm(f => ({ ...f, name: e.target.value }))}
            />
          </div>

          {/* Min Points & Multiplier */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">Minimum Points</label>
              <Input
                type="number"
                min="0"
                value={form.min_points}
                onChange={(e) => setForm(f => ({ ...f, min_points: e.target.value }))}
              />
              <p className="text-xs text-slate-500 mt-1">Points needed to reach this tier</p>
            </div>
            <div>
              <label className="block text-sm font-medium mb-2">Points Multiplier</label>
              <Input
                type="number"
                min="1"
                step="0.1"
                value={form.points_multiplier}
                onChange={(e) => setForm(f => ({ ...f, points_multiplier: e.target.value }))}
              />
              <p className="text-xs text-slate-500 mt-1">Earning multiplier (e.g., 1.5x)</p>
            </div>
          </div>

          {/* Color */}
          <div>
            <label className="block text-sm font-medium mb-2">Tier Color</label>
            <div className="flex gap-3 items-center">
              <input
                type="color"
                value={form.color}
                onChange={(e) => setForm(f => ({ ...f, color: e.target.value }))}
                className="w-12 h-10 rounded cursor-pointer"
              />
              <Input
                value={form.color}
                onChange={(e) => setForm(f => ({ ...f, color: e.target.value }))}
                placeholder="#3b82f6"
                className="flex-1"
              />
              <div 
                className="w-10 h-10 rounded-full flex items-center justify-center"
                style={{ backgroundColor: form.color + '20', color: form.color }}
              >
                <Star className="w-5 h-5" />
              </div>
            </div>
          </div>

          {/* Benefits */}
          <div>
            <label className="block text-sm font-medium mb-2">Benefits</label>
            <div className="space-y-2 mb-3">
              {Object.entries(form.benefits).map(([key, value]) => (
                <div key={key} className="flex items-center gap-2 bg-slate-100 dark:bg-slate-700 p-2 rounded">
                  <span className="font-medium">{key}:</span>
                  <span className="flex-1">{String(value)}</span>
                  <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={() => removeBenefit(key)}
                    className="text-red-500 hover:text-red-700"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              ))}
            </div>
            <div className="flex gap-2">
              <Input
                placeholder="Benefit name"
                value={benefitKey}
                onChange={(e) => setBenefitKey(e.target.value)}
                className="flex-1"
              />
              <Input
                placeholder="Value"
                value={benefitValue}
                onChange={(e) => setBenefitValue(e.target.value)}
                className="flex-1"
              />
              <Button variant="outline" onClick={addBenefit}>
                <Plus className="w-4 h-4" />
              </Button>
            </div>
            <p className="text-xs text-slate-500 mt-1">
              e.g., "Free Pool Entry" → "2 per month", "Discount" → "10%"
            </p>
          </div>

          {/* Active Status */}
          <div className="flex items-center gap-3">
            <input
              type="checkbox"
              id="tier-active"
              checked={form.is_active}
              onChange={(e) => setForm(f => ({ ...f, is_active: e.target.checked }))}
              className="w-4 h-4 rounded"
            />
            <label htmlFor="tier-active" className="text-sm font-medium">
              Active (visible to customers)
            </label>
          </div>
        </div>

        <div className="flex justify-end gap-3 mt-6 pt-4 border-t">
          <Button variant="outline" onClick={onClose} disabled={saving}>
            Cancel
          </Button>
          <Button onClick={handleSubmit} disabled={saving}>
            {saving ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : null}
            {tier ? 'Update Tier' : 'Create Tier'}
          </Button>
        </div>
      </motion.div>
    </motion.div>
  );
}

'use client';

import { useEffect } from 'react';
import { useParams } from 'next/navigation';
import { DndContext, DragOverlay, closestCenter } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { useModuleBuilderStore } from '@/stores/module-builder-store';
import { BuilderCanvas } from '@/components/module-builder/BuilderCanvas';
import { ComponentToolbar } from '@/components/module-builder/ComponentToolbar';
import { PropertyPanel } from '@/components/module-builder/PropertyPanel';
import { DynamicModuleRenderer } from '@/components/module-builder/DynamicModuleRenderer';
import { Loader2, ArrowLeft, Save, Eye, EyeOff, Undo2, Redo2, ZoomIn, ZoomOut } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import { modulesApi } from '@/lib/api';
import { useQuery, useMutation } from '@tanstack/react-query';
import { UIBlock } from '@/types/module-builder';

export default function ModuleBuilderPage() {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;
  
  const { 
    setLayout, 
    layout, 
    setActiveModuleId, 
    selectedBlockId,
    isPreview,
    togglePreview,
    undo,
    redo,
    canUndo,
    canRedo,
    zoom,
    setZoom,
  } = useModuleBuilderStore();

  const { data, isLoading, refetch } = useQuery({
    queryKey: ['module', id],
    queryFn: () => modulesApi.getById(id),
    staleTime: 0, // Always fetch fresh data when navigating to builder
  });

  const saveMutation = useMutation({
    mutationFn: (newLayout: UIBlock[]) => {
        // We save the layout inside the 'settings' JSONb column
        // Merging with existing settings to prevent data loss
        const currentSettings = data?.data?.settings || {};
        return modulesApi.update(id, {
            settings: {
                ...currentSettings,
                layout: newLayout
            },
            settings_version: data?.data?.settings_version
        });
    },
    onSuccess: () => {
      toast.success('Layout saved successfully');
      refetch(); // Refresh data after save to ensure consistency
    },
    onError: () => toast.error('Failed to save layout')
  });

  useEffect(() => {
    if (data?.data) {
      setActiveModuleId(id);
      // Load layout from settings if it exists, otherwise empty
      // Use skipHistory=true to not add initial load to undo stack
      const savedLayout = data.data.settings?.layout || [];
      console.log('[ModuleBuilder] Loading layout from API:', savedLayout);
      setLayout(savedLayout, true); // Skip history for initial load
    }
  }, [data, id, setActiveModuleId, setLayout]);

  if (isLoading) {
    return <div className="flex h-screen items-center justify-center"><Loader2 className="animate-spin" /></div>;
  }

  return (
    <div className="flex h-screen flex-col bg-slate-50 dark:bg-slate-900">
      {/* Header */}
      <header className="flex items-center justify-between border-b bg-white px-6 py-3 shadow-sm dark:bg-slate-800 dark:border-slate-700">
        <div className="flex items-center gap-4">
          <button onClick={() => router.back()} className="rounded-full p-2 hover:bg-slate-100 dark:hover:bg-slate-700">
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <h1 className="text-lg font-bold text-slate-900 dark:text-white">{data?.data?.name || 'Module Builder'}</h1>
            <p className="text-xs text-slate-500">Visual Editor</p>
          </div>
        </div>
        <div className="flex gap-2">
            {/* Undo/Redo */}
            <div className="flex items-center border border-slate-300 rounded-lg dark:border-slate-600 overflow-hidden">
                <button
                    onClick={undo}
                    disabled={!canUndo()}
                    className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed"
                    title="Undo (Ctrl+Z)"
                >
                    <Undo2 className="h-4 w-4" />
                </button>
                <div className="w-px h-6 bg-slate-300 dark:bg-slate-600" />
                <button
                    onClick={redo}
                    disabled={!canRedo()}
                    className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed"
                    title="Redo (Ctrl+Y)"
                >
                    <Redo2 className="h-4 w-4" />
                </button>
            </div>

            {/* Zoom */}
            <div className="flex items-center border border-slate-300 rounded-lg dark:border-slate-600 overflow-hidden">
                <button
                    onClick={() => setZoom(zoom - 10)}
                    disabled={zoom <= 50}
                    className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 disabled:opacity-30"
                    title="Zoom Out"
                >
                    <ZoomOut className="h-4 w-4" />
                </button>
                <span className="px-2 text-sm font-medium min-w-[50px] text-center">{zoom}%</span>
                <button
                    onClick={() => setZoom(zoom + 10)}
                    disabled={zoom >= 150}
                    className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 disabled:opacity-30"
                    title="Zoom In"
                >
                    <ZoomIn className="h-4 w-4" />
                </button>
            </div>

            <button
                onClick={togglePreview}
                className="flex items-center gap-2 rounded-lg border border-slate-300 px-4 py-2 text-sm font-medium hover:bg-slate-50 dark:border-slate-600 dark:hover:bg-slate-700"
            >
                {isPreview ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                {isPreview ? 'Back to Edit' : 'Preview'}
            </button>
            <button 
                onClick={() => saveMutation.mutate(layout)}
                disabled={saveMutation.isPending}
                className="flex items-center gap-2 rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-700 disabled:opacity-50"
            >
                <Save className="h-4 w-4" />
                {saveMutation.isPending ? 'Saving...' : 'Save Layout'}
            </button>
        </div>
      </header>

      {/* Main Workspace */}
      <div className="flex flex-1 overflow-hidden">
        {/* Render Canvas */}
         <main className={`flex-1 overflow-y-auto bg-slate-100 dark:bg-slate-950/50 ${isPreview ? 'p-0' : 'p-8'}`}>
            {isPreview ? (
                 <div className="bg-white dark:bg-slate-900 min-h-full">
                    {/* Pass current layout state to renderer for live preview */}
                    <DynamicModuleRenderer layout={layout} module={data?.data} />
                 </div>
            ) : (
                <div className="mx-auto max-w-5xl rounded-xl bg-white min-h-[600px] shadow-lg dark:bg-slate-900 border border-slate-200 dark:border-slate-800">
                    <BuilderCanvas />
                </div>
            )}
        </main>

        {/* Right Sidebar: Properties */}
        {!isPreview && (
            <aside className="w-80 border-l bg-white dark:bg-slate-800 dark:border-slate-700">
                <PropertyPanel />
            </aside>
        )}
      </div>

      {/* Bottom Bar: Components */}
      {!isPreview && (
          <div className="h-20 border-t bg-white px-6 shadow-up dark:bg-slate-800 dark:border-slate-700">
            <ComponentToolbar />
          </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { modulesApi } from '@/lib/api';
import { Loader2, Plus, Edit, Trash2, Check, X, AlertCircle, LayoutTemplate } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { toast } from 'sonner';
import { Module, ModuleSettings } from '@/lib/settings-context';

import { isSameDay } from 'date-fns';
import { useRouter } from 'next/navigation';

interface ModuleFormData {
  name: string;
  slug: string;
  description: string;
  template_type: string;
  is_active: boolean;
  show_in_main: boolean;
  settings: ModuleSettings;
}

interface ApiError {
  response?: { data?: { message?: string } };
}

export default function ModulesPage() {
  const router = useRouter();
  const t = useTranslations('admin');
  const queryClient = useQueryClient();
  const [isCreating, setIsCreating] = useState(false);
  const [editingModule, setEditingModule] = useState<Module | null>(null);

  const { data, isLoading, error } = useQuery({
    queryKey: ['admin-modules'],
    queryFn: () => modulesApi.getAll(false),
  });

  const modules = data?.data?.data || [];

  const createMutation = useMutation({
    mutationFn: (data: ModuleFormData) => modulesApi.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-modules'] });
      setIsCreating(false);
      toast.success('Module created successfully');
    },
    onError: (err: ApiError) => {
      toast.error(err.response?.data?.message || 'Failed to create module');
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: ModuleFormData }) => modulesApi.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-modules'] });
      setEditingModule(null);
      toast.success('Module updated successfully');
    },
    onError: (err: ApiError) => {
      toast.error(err.response?.data?.message || 'Failed to update module');
    },
  });

  const deleteMutation = useMutation({
    mutationFn: ({ id, force }: { id: string; force?: boolean }) => modulesApi.delete(id, force),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-modules'] });
      toast.success('Module deleted successfully');
    },
    onError: (err: ApiError) => {
      toast.error(err.response?.data?.message || 'Failed to delete module');
    },
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="w-8 h-8 animate-spin text-primary-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
          Module Management
        </h1>
        <button
          onClick={() => setIsCreating(true)}
          className="flex items-center px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors"
        >
          <Plus className="w-4 h-4 mr-2" />
          Add Module
        </button>
      </div>

      {isCreating && (
        <ModuleForm
          onSubmit={(data: ModuleFormData) => createMutation.mutate(data)}
          onCancel={() => setIsCreating(false)}
          isLoading={createMutation.isPending}
        />
      )}

      {editingModule && (
        <ModuleForm
          initialData={editingModule}
          onSubmit={(data: ModuleFormData) => updateMutation.mutate({ id: editingModule.id, data })}
          onCancel={() => setEditingModule(null)}
          isLoading={updateMutation.isPending}
        />
      )}

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm overflow-hidden border border-slate-200 dark:border-slate-700">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200 dark:divide-slate-700">
          <thead className="bg-slate-50 dark:bg-slate-900/50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                Name
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                Slug
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                Type
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                Status
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="bg-white dark:bg-slate-800 divide-y divide-slate-200 dark:divide-slate-700">
            {modules.map((module: Module) => (
              <tr key={module.id}>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="text-sm font-medium text-slate-900 dark:text-white">
                    {module.name}
                  </div>
                  <div className="text-sm text-slate-500 dark:text-slate-400">
                    {module.description}
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500 dark:text-slate-400">
                  {module.slug}
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300">
                    {module.template_type}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                    module.is_active
                      ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300'
                      : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300'
                  }`}>
                    {module.is_active ? 'Active' : 'Inactive'}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                  <div className="flex items-center justify-end gap-3">
                    <button
                      onClick={() => router.push(`/admin/modules/builder/${module.id}`)}
                      className="flex items-center px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg transition-colors text-xs font-medium"
                      title="Customize Module Interface"
                    >
                      <LayoutTemplate className="w-4 h-4 mr-1.5" />
                      Builder
                    </button>
                    <button
                      onClick={() => setEditingModule(module)}
                      className="p-1.5 text-primary-600 hover:bg-primary-100 dark:hover:bg-primary-900/30 rounded transition-colors"
                      title="Edit Module Settings"
                    >
                      <Edit className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => {
                        const input = prompt('Type "Delete" to confirm hard deletion of this module. This action is irreversible.');
                        if (input === 'Delete') {
                          deleteMutation.mutate({ id: module.id, force: true });
                        } else if (input !== null) {
                          toast.error('You must type "Delete" exactly to confirm.');
                        }
                      }}
                      className="p-1.5 text-red-600 hover:bg-red-100 dark:hover:bg-red-900/30 rounded transition-colors"
                      title="Delete Module"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        </div>
      </div>
    </div>
  );
}

interface ModuleFormProps {
  initialData?: Module | null;
  onSubmit: (data: ModuleFormData) => void;
  onCancel: () => void;
  isLoading: boolean;
}

function ModuleForm({ initialData, onSubmit, onCancel, isLoading }: ModuleFormProps) {
  const [formData, setFormData] = useState({
    name: initialData?.name || '',
    slug: initialData?.slug || '',
    description: initialData?.description || '',
    template_type: initialData?.template_type || 'menu_service',
    is_active: initialData?.is_active ?? true,
    show_in_main: initialData?.show_in_main ?? true,
    settings: initialData?.settings || {
      header_color: '#0ea5e9',
      accent_color: '#6366f1',
      show_in_nav: true,
      icon: 'default',
    },
  });

  // Helper to normalize slug: lowercase, replace spaces with hyphens, remove special chars
  const normalizeSlug = (value: string) => {
    return value
      .toLowerCase()
      .trim()
      .replace(/\s+/g, '-')           // Replace spaces with hyphens
      .replace(/[^a-z0-9-]/g, '')     // Remove non-alphanumeric except hyphens
      .replace(/-+/g, '-')            // Replace multiple hyphens with single
      .replace(/^-|-$/g, '');         // Remove leading/trailing hyphens
  };

  // Auto-generate slug from name if slug is empty
  const handleNameChange = (value: string) => {
    const newData = { ...formData, name: value };
    // Auto-generate slug if it's empty or was auto-generated before
    if (!formData.slug || formData.slug === normalizeSlug(formData.name)) {
      newData.slug = normalizeSlug(value);
    }
    setFormData(newData);
  };

  const handleSlugChange = (value: string) => {
    // Normalize the slug on every change
    setFormData({ ...formData, slug: normalizeSlug(value) });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(formData);
  };

  const updateSettings = (key: string, value: string | boolean) => {
    setFormData({
      ...formData,
      settings: { ...formData.settings, [key]: value },
    });
  };

  return (
    <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 mb-6">
      <h2 className="text-lg font-semibold mb-4 text-slate-900 dark:text-white">
        {initialData ? 'Edit Module' : 'Create New Module'}
      </h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
              Name
            </label>
            <input
              type="text"
              required
              value={formData.name}
              onChange={(e) => handleNameChange(e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
              Slug (URL Path)
            </label>
            <input
              type="text"
              required
              value={formData.slug}
              onChange={(e) => handleSlugChange(e.target.value)}
              placeholder="e.g., chocolate-box"
              className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500"
            />
            <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
              URL-friendly identifier (lowercase, hyphens only)
            </p>
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
            Description
          </label>
          <textarea
            value={formData.description}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500"
            rows={3}
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
              Template Type
            </label>
            <select
              value={formData.template_type}
              onChange={(e) => setFormData({ ...formData, template_type: e.target.value as 'menu_service' | 'multi_day_booking' | 'session_access' })}
              className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500"
              disabled={!!initialData} // Prevent changing type after creation for now
            >
              <option value="menu_service">Menu Service (Restaurant/Bar)</option>
              <option value="multi_day_booking">Multi-Day Booking (Chalets/Hotel)</option>
              <option value="session_access">Session Access (Pool/Gym/Spa)</option>
            </select>
          </div>
          <div className="flex flex-col gap-2 pt-6">
            <label className="flex items-center cursor-pointer">
              <input
                type="checkbox"
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                className="w-4 h-4 text-primary-600 border-slate-300 rounded focus:ring-primary-500"
              />
              <span className="ml-2 text-sm text-slate-700 dark:text-slate-300">
                Active (Module enabled)
              </span>
            </label>
            <label className="flex items-center cursor-pointer">
              <input
                type="checkbox"
                checked={formData.show_in_main}
                onChange={(e) => setFormData({ ...formData, show_in_main: e.target.checked })}
                className="w-4 h-4 text-primary-600 border-slate-300 rounded focus:ring-primary-500"
              />
              <span className="ml-2 text-sm text-slate-700 dark:text-slate-300">
                Show on Homepage (Visible to customers)
              </span>
            </label>
          </div>
        </div>

        {/* Module Appearance Settings */}
        <div className="border-t border-slate-200 dark:border-slate-700 pt-4 mt-4">
          <h3 className="text-sm font-semibold text-slate-900 dark:text-white mb-3">
            Appearance Settings
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                Header Color
              </label>
              <div className="flex gap-2">
                <input
                  type="color"
                  value={formData.settings.header_color || '#0ea5e9'}
                  onChange={(e) => updateSettings('header_color', e.target.value)}
                  className="w-12 h-10 rounded cursor-pointer border border-slate-300"
                />
                <input
                  type="text"
                  value={formData.settings.header_color || '#0ea5e9'}
                  onChange={(e) => updateSettings('header_color', e.target.value)}
                  className="flex-1 px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white text-sm"
                  placeholder="#0ea5e9"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                Accent Color
              </label>
              <div className="flex gap-2">
                <input
                  type="color"
                  value={formData.settings.accent_color || '#6366f1'}
                  onChange={(e) => updateSettings('accent_color', e.target.value)}
                  className="w-12 h-10 rounded cursor-pointer border border-slate-300"
                />
                <input
                  type="text"
                  value={formData.settings.accent_color || '#6366f1'}
                  onChange={(e) => updateSettings('accent_color', e.target.value)}
                  className="flex-1 px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white text-sm"
                  placeholder="#6366f1"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                Icon Style
              </label>
              <select
                value={formData.settings.icon || 'default'}
                onChange={(e) => updateSettings('icon', e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500"
              >
                <option value="default">Default</option>
                <option value="utensils">Utensils (Restaurant)</option>
                <option value="home">Home (Accommodation)</option>
                <option value="waves">Waves (Pool/Beach)</option>
                <option value="dumbbell">Dumbbell (Gym)</option>
                <option value="spa">Spa</option>
                <option value="coffee">Coffee</option>
                <option value="shopping">Shopping</option>
              </select>
            </div>
          </div>
          <div className="mt-3">
            <label className="flex items-center cursor-pointer">
              <input
                type="checkbox"
                checked={formData.settings.show_in_nav ?? true}
                onChange={(e) => updateSettings('show_in_nav', e.target.checked)}
                className="w-4 h-4 text-primary-600 border-slate-300 rounded focus:ring-primary-500"
              />
              <span className="ml-2 text-sm text-slate-700 dark:text-slate-300">
                Show in main navigation
              </span>
            </label>
          </div>
        </div>

        <div className="flex justify-end gap-3 pt-4">
          <button
            type="button"
            onClick={onCancel}
            className="px-4 py-2 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg transition-colors"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={isLoading}
            className="px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors disabled:opacity-50 flex items-center"
          >
            {isLoading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
            {initialData ? 'Update Module' : 'Create Module'}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { CardSkeleton } from '@/components/ui/Skeleton';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import { useSocket } from '@/lib/socket';
import {
  UtensilsCrossed,
  Cookie,
  Search,
  Filter,
  RefreshCw,
  CheckCircle2,
  Clock,
  XCircle,
  ChefHat,
  Truck,
  Package,
  AlertCircle,
  Play,
  Eye,
} from 'lucide-react';

interface OrderItem {
  id: string;
  name: string;
  quantity: number;
  unit_price: number;
  notes?: string;
}

interface Order {
  id: string;
  order_number: string;
  source: 'restaurant' | 'snack_bar';
  status: 'pending' | 'confirmed' | 'preparing' | 'ready' | 'delivered' | 'completed' | 'cancelled';
  total_amount: number;
  items: OrderItem[];
  table_number?: string;
  customer_name?: string;
  customer_notes?: string;
  created_at: string;
  updated_at: string;
}

const statusConfig: Record<string, { color: string; icon: React.ElementType; label: string }> = {
  pending: { color: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400', icon: Clock, label: 'Pending' },
  confirmed: { color: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400', icon: CheckCircle2, label: 'Confirmed' },
  preparing: { color: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400', icon: ChefHat, label: 'Preparing' },
  ready: { color: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400', icon: Package, label: 'Ready' },
  delivered: { color: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400', icon: Truck, label: 'Delivered' },
  completed: { color: 'bg-slate-100 text-slate-800 dark:bg-slate-700 dark:text-slate-300', icon: CheckCircle2, label: 'Completed' },
  cancelled: { color: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400', icon: XCircle, label: 'Cancelled' },
};

export default function AdminOrdersPage() {
  const t = useTranslations('admin');
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [sourceFilter, setSourceFilter] = useState<string>('all');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const { socket } = useSocket();

  const fetchOrders = useCallback(async () => {
    try {
      setLoading(true);
      // Fetch both restaurant and snack bar orders
      const [restaurantRes, snackRes] = await Promise.all([
        api.get('/restaurant/admin/orders').catch(() => ({ data: { data: [] } })),
        api.get('/snack/staff/orders').catch(() => ({ data: { data: [] } })),
      ]);

      const restaurantOrders = (restaurantRes.data.data || []).map((o: Omit<Order, 'source'>) => ({
        ...o,
        source: 'restaurant' as const,
      }));
      const snackOrders = (snackRes.data.data || []).map((o: Omit<Order, 'source'>) => ({
        ...o,
        source: 'snack_bar' as const,
      }));

      // Combine and sort by date
      const allOrders = [...restaurantOrders, ...snackOrders].sort(
        (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      );

      setOrders(allOrders);
    } catch (error) {
      toast.error('Failed to fetch orders');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOrders();
  }, [fetchOrders]);

  // Real-time order updates
  useEffect(() => {
    if (socket) {
      socket.on('order:new', (order: Order) => {
        setOrders((prev) => [order, ...prev]);
        toast.success(`New order received: #${order.order_number || order.id.slice(0, 8)}`);
      });

      socket.on('order:updated', (order: Partial<Order> & { id: string }) => {
        setOrders((prev) =>
          prev.map((o) => (o.id === order.id ? { ...o, ...order } : o))
        );
      });

      socket.on('order:statusChanged', ({ orderId, status }: { orderId: string; status: string }) => {
        setOrders((prev) =>
          prev.map((o) => (o.id === orderId ? { ...o, status: status as Order['status'] } : o))
        );
      });

      return () => {
        socket.off('order:new');
        socket.off('order:updated');
        socket.off('order:statusChanged');
      };
    }
  }, [socket]);

  const updateOrderStatus = async (orderId: string, source: string, newStatus: string) => {
    try {
      const endpoint = source === 'restaurant' 
        ? `/restaurant/admin/orders/${orderId}/status`
        : `/snack/staff/orders/${orderId}/status`;
      
      await api.put(endpoint, { status: newStatus });
      
      setOrders((prev) =>
        prev.map((o) => (o.id === orderId ? { ...o, status: newStatus as Order['status'] } : o))
      );
      
      toast.success('Order status updated');
    } catch (error) {
      toast.error('Failed to update order status');
    }
  };

  const filteredOrders = orders.filter((o) => {
    if (statusFilter !== 'all' && o.status !== statusFilter) return false;
    if (sourceFilter !== 'all' && o.source !== sourceFilter) return false;
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      return (
        o.id.toLowerCase().includes(query) ||
        o.order_number?.toLowerCase().includes(query) ||
        o.customer_name?.toLowerCase().includes(query) ||
        o.table_number?.toLowerCase().includes(query)
      );
    }
    return true;
  });

  const activeOrders = orders.filter((o) => !['completed', 'cancelled'].includes(o.status));
  const pendingCount = orders.filter((o) => o.status === 'pending').length;
  const preparingCount = orders.filter((o) => o.status === 'preparing').length;
  const readyCount = orders.filter((o) => o.status === 'ready').length;

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <CardSkeleton key={i} />
          ))}
        </div>
        <CardSkeleton />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
            Orders
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            Manage restaurant and snack bar orders in real-time
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={() => fetchOrders()}>
            <RefreshCw className="w-4 h-4 mr-2" />
            Refresh
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-blue-100 text-sm">Active Orders</p>
                  <p className="text-2xl font-bold mt-1">{activeOrders.length}</p>
                </div>
                <UtensilsCrossed className="w-10 h-10 text-blue-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-yellow-500 to-yellow-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-yellow-100 text-sm">Pending</p>
                  <p className="text-2xl font-bold mt-1">{pendingCount}</p>
                </div>
                <Clock className="w-10 h-10 text-yellow-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-orange-500 to-orange-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-orange-100 text-sm">Preparing</p>
                  <p className="text-2xl font-bold mt-1">{preparingCount}</p>
                </div>
                <ChefHat className="w-10 h-10 text-orange-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-green-100 text-sm">Ready</p>
                  <p className="text-2xl font-bold mt-1">{readyCount}</p>
                </div>
                <Package className="w-10 h-10 text-green-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="p-4">
          <div className="flex flex-col md:flex-row gap-4">
            {/* Search */}
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Search by order ID, customer, or table..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>

            {/* Source Filter */}
            <select
              value={sourceFilter}
              onChange={(e) => setSourceFilter(e.target.value)}
              className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
            >
              <option value="all">All Sources</option>
              <option value="restaurant">Restaurant</option>
              <option value="snack_bar">Snack Bar</option>
            </select>

            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
            >
              <option value="all">All Status</option>
              <option value="pending">Pending</option>
              <option value="confirmed">Confirmed</option>
              <option value="preparing">Preparing</option>
              <option value="ready">Ready</option>
              <option value="delivered">Delivered</option>
              <option value="completed">Completed</option>
              <option value="cancelled">Cancelled</option>
            </select>
          </div>
        </CardContent>
      </Card>

      {/* Orders Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-4">
        <AnimatePresence mode="popLayout">
          {filteredOrders.length === 0 ? (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="col-span-full text-center py-12"
            >
              <p className="text-slate-500 dark:text-slate-400">No orders found</p>
            </motion.div>
          ) : (
            filteredOrders.map((order, index) => {
              const StatusIcon = statusConfig[order.status]?.icon || Clock;
              return (
                <motion.div
                  key={order.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.9 }}
                  transition={{ delay: index * 0.05 }}
                  layout
                >
                  <Card className="hover:shadow-lg transition-shadow">
                    <CardHeader className="pb-2">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          {order.source === 'restaurant' ? (
                            <UtensilsCrossed className="w-5 h-5 text-blue-500" />
                          ) : (
                            <Cookie className="w-5 h-5 text-orange-500" />
                          )}
                          <CardTitle className="text-lg">
                            #{order.order_number || order.id.slice(0, 8)}
                          </CardTitle>
                        </div>
                        <span
                          className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium ${
                            statusConfig[order.status]?.color
                          }`}
                        >
                          <StatusIcon className="w-3 h-3" />
                          {statusConfig[order.status]?.label || order.status}
                        </span>
                      </div>
                    </CardHeader>
                    <CardContent className="space-y-3">
                      {/* Customer Info */}
                      {(order.customer_name || order.table_number) && (
                        <div className="text-sm text-slate-600 dark:text-slate-300">
                          {order.customer_name && <p>Customer: {order.customer_name}</p>}
                          {order.table_number && <p>Table: {order.table_number}</p>}
                        </div>
                      )}

                      {/* Items */}
                      <div className="space-y-1">
                        {(order.items || []).slice(0, 3).map((item, i) => (
                          <div key={i} className="flex justify-between text-sm">
                            <span className="text-slate-600 dark:text-slate-300">
                              {item.quantity}x {item.name}
                            </span>
                            <span className="text-slate-500 dark:text-slate-400">
                              {formatCurrency(item.unit_price * item.quantity)}
                            </span>
                          </div>
                        ))}
                        {(order.items || []).length > 3 && (
                          <p className="text-xs text-slate-400">
                            +{order.items.length - 3} more items
                          </p>
                        )}
                      </div>

                      {/* Total */}
                      <div className="flex justify-between items-center pt-2 border-t border-slate-200 dark:border-slate-700">
                        <span className="font-medium text-slate-700 dark:text-slate-300">
                          Total
                        </span>
                        <span className="font-bold text-lg text-slate-900 dark:text-white">
                          {formatCurrency(order.total_amount)}
                        </span>
                      </div>

                      {/* Actions */}
                      <div className="flex gap-2 pt-2">
                        {order.status === 'pending' && (
                          <Button
                            size="sm"
                            className="flex-1"
                            onClick={() => updateOrderStatus(order.id, order.source, 'confirmed')}
                          >
                            <CheckCircle2 className="w-4 h-4 mr-1" />
                            Confirm
                          </Button>
                        )}
                        {order.status === 'confirmed' && (
                          <Button
                            size="sm"
                            className="flex-1"
                            onClick={() => updateOrderStatus(order.id, order.source, 'preparing')}
                          >
                            <ChefHat className="w-4 h-4 mr-1" />
                            Start
                          </Button>
                        )}
                        {order.status === 'preparing' && (
                          <Button
                            size="sm"
                            className="flex-1"
                            onClick={() => updateOrderStatus(order.id, order.source, 'ready')}
                          >
                            <Package className="w-4 h-4 mr-1" />
                            Ready
                          </Button>
                        )}
                        {order.status === 'ready' && (
                          <Button
                            size="sm"
                            className="flex-1"
                            onClick={() => updateOrderStatus(order.id, order.source, 'delivered')}
                          >
                            <Truck className="w-4 h-4 mr-1" />
                            Deliver
                          </Button>
                        )}
                        {order.status === 'delivered' && (
                          <Button
                            size="sm"
                            className="flex-1"
                            onClick={() => updateOrderStatus(order.id, order.source, 'completed')}
                          >
                            <CheckCircle2 className="w-4 h-4 mr-1" />
                            Complete
                          </Button>
                        )}
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setSelectedOrder(order)}
                        >
                          <Eye className="w-4 h-4" />
                        </Button>
                      </div>

                      {/* Timestamp */}
                      <p className="text-xs text-slate-400 text-right">
                        {formatDate(order.created_at)}
                      </p>
                    </CardContent>
                  </Card>
                </motion.div>
              );
            })
          )}
        </AnimatePresence>
      </div>

      {/* Order Detail Modal */}
      <AnimatePresence>
        {selectedOrder && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4"
            onClick={() => setSelectedOrder(null)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white dark:bg-slate-800 rounded-xl max-w-lg w-full p-6 max-h-[80vh] overflow-y-auto"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                  Order #{selectedOrder.order_number || selectedOrder.id.slice(0, 8)}
                </h2>
                <Button variant="ghost" size="sm" onClick={() => setSelectedOrder(null)}>
                  ×
                </Button>
              </div>

              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <span className="text-slate-500 dark:text-slate-400">Source</span>
                    <p className="font-medium text-slate-900 dark:text-white capitalize">
                      {selectedOrder.source.replace('_', ' ')}
                    </p>
                  </div>
                  <div>
                    <span className="text-slate-500 dark:text-slate-400">Status</span>
                    <p className="font-medium text-slate-900 dark:text-white capitalize">
                      {selectedOrder.status}
                    </p>
                  </div>
                  {selectedOrder.customer_name && (
                    <div>
                      <span className="text-slate-500 dark:text-slate-400">Customer</span>
                      <p className="font-medium text-slate-900 dark:text-white">
                        {selectedOrder.customer_name}
                      </p>
                    </div>
                  )}
                  {selectedOrder.table_number && (
                    <div>
                      <span className="text-slate-500 dark:text-slate-400">Table</span>
                      <p className="font-medium text-slate-900 dark:text-white">
                        {selectedOrder.table_number}
                      </p>
                    </div>
                  )}
                </div>

                <div className="border-t border-slate-200 dark:border-slate-700 pt-4">
                  <h3 className="font-medium text-slate-900 dark:text-white mb-2">Items</h3>
                  <div className="space-y-2">
                    {(selectedOrder.items || []).map((item, i) => (
                      <div key={i} className="flex justify-between">
                        <span className="text-slate-600 dark:text-slate-300">
                          {item.quantity}x {item.name}
                          {item.notes && (
                            <span className="text-xs text-slate-400 block">
                              Note: {item.notes}
                            </span>
                          )}
                        </span>
                        <span className="font-medium text-slate-900 dark:text-white">
                          {formatCurrency(item.unit_price * item.quantity)}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>

                {selectedOrder.customer_notes && (
                  <div className="bg-yellow-50 dark:bg-yellow-900/20 p-3 rounded-lg">
                    <p className="text-sm text-yellow-800 dark:text-yellow-200">
                      <strong>Notes:</strong> {selectedOrder.customer_notes}
                    </p>
                  </div>
                )}

                <div className="border-t border-slate-200 dark:border-slate-700 pt-4 flex justify-between items-center">
                  <span className="text-lg font-medium text-slate-900 dark:text-white">
                    Total
                  </span>
                  <span className="text-2xl font-bold text-slate-900 dark:text-white">
                    {formatCurrency(selectedOrder.total_amount)}
                  </span>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

'use client';

import { useEffect, useState, useMemo } from 'react';
import Link from 'next/link';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '@/lib/auth-context';
import { useSiteSettings } from '@/lib/settings-context';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { StatCardSkeleton, CardSkeleton } from '@/components/ui/Skeleton';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import { useSocket } from '@/lib/socket';
import { getModuleIcon } from '@/lib/module-utils';
import {
  Users,
  UtensilsCrossed,
  Home,
  Waves,
  DollarSign,
  TrendingUp,
  ArrowUpRight,
  ArrowDownRight,
  RefreshCw,
  Clock,
  CheckCircle2,
  AlertTriangle,
  Timer,
  Sparkles,
} from 'lucide-react';

interface RecentOrder {
  id: string;
  orderNumber?: string;
  customerName?: string;
  itemCount?: number;
  totalAmount?: number;
  status?: string;
}

interface DashboardStats {
  todayOrders: number;
  todayRevenue: number;
  todayBookings: number;
  todayTickets: number;
  recentOrders: RecentOrder[];
  // Dynamic revenue by module - keyed by module slug
  revenueByUnit: Record<string, number>;
  trends?: {
    orders: number;
    revenue: number;
    bookings: number;
    tickets: number;
  };
}

// Animated stat card with gradient background
function StatCard({
  title,
  value,
  icon: Icon,
  trend,
  trendValue,
  gradient,
  delay = 0,
}: {
  title: string;
  value: string | number;
  icon: React.ElementType;
  trend: 'up' | 'down' | 'neutral';
  trendValue: string;
  gradient: string;
  delay?: number;
}) {
  return (
    <motion.div
      variants={fadeInUp}
      initial="hidden"
      animate="visible"
      transition={{ delay }}
      whileHover={{ scale: 1.02, y: -4 }}
      className="relative overflow-hidden rounded-2xl bg-white dark:bg-slate-800 shadow-lg border border-slate-100 dark:border-slate-700"
    >
      {/* Gradient accent */}
      <div className={`absolute inset-0 opacity-5 ${gradient}`} />
      <div className={`absolute top-0 left-0 right-0 h-1 ${gradient}`} />
      
      <div className="relative p-6">
        <div className="flex items-start justify-between">
          <div className="space-y-2">
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400">{title}</p>
            <motion.p
              initial={{ opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ delay: delay + 0.2, type: 'spring', stiffness: 200 }}
              className="text-3xl font-bold text-slate-900 dark:text-white"
            >
              {value}
            </motion.p>
          </div>
          <motion.div
            initial={{ rotate: -20, opacity: 0 }}
            animate={{ rotate: 0, opacity: 1 }}
            transition={{ delay: delay + 0.1, type: 'spring' }}
            className={`w-14 h-14 rounded-2xl ${gradient} flex items-center justify-center shadow-lg`}
          >
            <Icon className="w-7 h-7 text-white" />
          </motion.div>
        </div>

        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: delay + 0.3 }}
          className={`flex items-center gap-1 mt-4 text-sm font-medium ${
            trend === 'up' ? 'text-emerald-600 dark:text-emerald-400' : trend === 'down' ? 'text-red-500 dark:text-red-400' : 'text-slate-500 dark:text-slate-400'
          }`}
        >
          {trend === 'up' ? (
            <ArrowUpRight className="w-4 h-4" />
          ) : trend === 'down' ? (
            <ArrowDownRight className="w-4 h-4" />
          ) : null}
          <span>{trendValue}</span>
        </motion.div>
      </div>
    </motion.div>
  );
}

// Revenue progress bar with animation
function RevenueBar({
  name,
  value,
  percentage,
  color,
  delay,
}: {
  name: React.ReactNode;
  value: number;
  percentage: number;
  color: string;
  delay: number;
}) {
  return (
    <motion.div
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ delay }}
      className="space-y-2"
    >
      <div className="flex justify-between text-sm">
        <span className="font-medium text-slate-700 dark:text-slate-300">{name}</span>
        <span className="text-slate-500 dark:text-slate-400">{formatCurrency(value)}</span>
      </div>
      <div className="h-3 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
        <motion.div
          initial={{ width: 0 }}
          animate={{ width: `${percentage}%` }}
          transition={{ delay: delay + 0.2, duration: 0.8, ease: 'easeOut' }}
          className={`h-full rounded-full ${color}`}
        />
      </div>
    </motion.div>
  );
}

// Order status badge
function OrderStatus({ status }: { status: string }) {
  const configs: Record<string, { color: string; icon: React.ElementType; label: string }> = {
    pending: { color: 'bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400', icon: Clock, label: 'Pending' },
    preparing: { color: 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400', icon: Timer, label: 'Preparing' },
    ready: { color: 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400', icon: CheckCircle2, label: 'Ready' },
    completed: { color: 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300', icon: CheckCircle2, label: 'Completed' },
    cancelled: { color: 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400', icon: AlertTriangle, label: 'Cancelled' },
  };

  const config = configs[status] || configs.pending;
  const StatusIcon = config.icon;

  return (
    <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium ${config.color}`}>
      <StatusIcon className="w-3 h-3" />
      {config.label}
    </span>
  );
}

export default function AdminDashboard() {
  const { user } = useAuth();
  const { modules, settings } = useSiteSettings();
  const { socket } = useSocket();
  const [onlineUsers, setOnlineUsers] = useState(0);
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  
  // Get business name from settings
  const businessName = settings?.resortName || 'Your Business';

  // Get active modules for dynamic revenue display
  const activeModules = useMemo(() => {
    if (!modules || modules.length === 0) return [];
    return modules
      .filter(m => m.is_active)
      .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
  }, [modules]);

  // Map colors to module indices for variety
  const moduleColors = [
    'bg-gradient-to-r from-orange-400 to-rose-500',
    'bg-gradient-to-r from-amber-400 to-orange-500',
    'bg-gradient-to-r from-emerald-400 to-teal-500',
    'bg-gradient-to-r from-primary-400 to-secondary-500',
    'bg-gradient-to-r from-purple-400 to-indigo-500',
    'bg-gradient-to-r from-pink-400 to-rose-500',
    'bg-gradient-to-r from-cyan-400 to-blue-500',
    'bg-gradient-to-r from-lime-400 to-green-500',
  ];

  useEffect(() => {
    loadStats();
  }, []);

  useEffect(() => {
    if (socket) {
      socket.on('stats:online_users', (data: { count: number }) => {
        setOnlineUsers(data.count);
      });
      
      // Request initial online users count when socket is ready
      if (socket.connected) {
        socket.emit('request:online_users');
      } else {
        socket.once('connect', () => {
          socket.emit('request:online_users');
        });
      }
    }
    return () => {
      socket?.off('stats:online_users');
    };
  }, [socket]);

  const loadStats = async (isRefresh = false) => {
    if (isRefresh) setIsRefreshing(true);
    try {
      const response = await api.get('/admin/dashboard');
      setStats(response.data.data);
      if (isRefresh) toast.success('Dashboard refreshed');
    } catch (error) {
      toast.error('Failed to load dashboard data');
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  // Calculate totals
  const totalRevenue = stats?.revenueByUnit
    ? Object.values(stats.revenueByUnit).reduce((a, b) => a + b, 0)
    : 0;

  const getPercentage = (value: number) => {
    if (totalRevenue === 0) return 0;
    return Math.round((value / totalRevenue) * 100);
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        {/* Header skeleton */}
        <div className="flex justify-between items-center">
          <div className="space-y-2">
            <div className="h-8 w-48 bg-slate-200 dark:bg-slate-700 rounded animate-pulse" />
            <div className="h-5 w-64 bg-slate-100 dark:bg-slate-800 rounded animate-pulse" />
          </div>
        </div>

        {/* Stats skeleton */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {[...Array(4)].map((_, i) => (
            <StatCardSkeleton key={i} />
          ))}
        </div>

        {/* Content skeleton */}
        <div className="grid lg:grid-cols-2 gap-6">
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  return (
    <motion.div
      initial="hidden"
      animate="visible"
      variants={staggerContainer}
      className="space-y-8"
    >
      {/* Welcome Header */}
      <motion.div variants={fadeInUp} className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            Welcome back
            <motion.span
              animate={{ rotate: [0, 14, -8, 14, -4, 10, 0] }}
              transition={{ duration: 2, repeat: Infinity, repeatDelay: 3 }}
              className="inline-block"
            >
              👋
            </motion.span>
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">
            Here&apos;s what&apos;s happening at {businessName} today, <span className="font-medium text-slate-700 dark:text-slate-300">{user?.fullName}</span>
          </p>
        </div>
        <Button
          variant="outline"
          onClick={() => loadStats(true)}
          isLoading={isRefreshing}
          className="gap-2"
        >
          <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
          Refresh
        </Button>
      </motion.div>

      {/* Stats Grid - Always shows core stats, plus dynamic module stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard
          title="Online Users"
          value={onlineUsers}
          icon={Users}
          trend="neutral"
          trendValue="Live Count"
          gradient="bg-gradient-to-br from-blue-400 to-indigo-500"
          delay={0}
        />
        <StatCard
          title="Today's Orders"
          value={stats?.todayOrders || 0}
          icon={UtensilsCrossed}
          trend={stats?.trends?.orders !== undefined ? (stats.trends.orders >= 0 ? 'up' : 'down') : 'neutral'}
          trendValue={stats?.trends?.orders !== undefined ? `${stats.trends.orders >= 0 ? '+' : ''}${stats.trends.orders}% from yesterday` : 'No data'}
          gradient="bg-gradient-to-br from-orange-400 to-rose-500"
          delay={0}
        />
        <StatCard
          title="Today's Revenue"
          value={formatCurrency(stats?.todayRevenue || 0)}
          icon={DollarSign}
          trend={stats?.trends?.revenue !== undefined ? (stats.trends.revenue >= 0 ? 'up' : 'down') : 'neutral'}
          trendValue={stats?.trends?.revenue !== undefined ? `${stats.trends.revenue >= 0 ? '+' : ''}${stats.trends.revenue}% from yesterday` : 'No data'}
          gradient="bg-gradient-to-br from-emerald-400 to-teal-500"
          delay={0.1}
        />
        <StatCard
          title="Active Bookings"
          value={stats?.todayBookings || 0}
          icon={Home}
          trend={stats?.trends?.bookings !== undefined ? (stats.trends.bookings >= 0 ? 'up' : 'down') : 'neutral'}
          trendValue={stats?.trends?.bookings !== undefined ? `${stats.trends.bookings >= 0 ? '+' : ''}${stats.trends.bookings}% from last week` : 'No data'}
          gradient="bg-gradient-to-br from-blue-400 to-indigo-500"
          delay={0.2}
        />
      </div>

      {/* Two Column Layout */}
      <div className="grid lg:grid-cols-2 gap-6">
        {/* Revenue by Unit - Dynamic based on active modules */}
        <motion.div variants={fadeInUp}>
          <Card variant="glass">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-primary-600" />
                Revenue by Business Unit
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-5">
                {activeModules.length > 0 ? (
                  activeModules.map((module, index) => {
                    // Get revenue for this module - support both slug formats
                    const slugKey = module.slug;
                    const camelKey = module.slug.replace(/-([a-z])/g, (_, l) => l.toUpperCase());
                    const revenue = stats?.revenueByUnit?.[slugKey] || stats?.revenueByUnit?.[camelKey] || 0;
                    
                    const ModuleIcon = getModuleIcon(module);

                    return (
                      <RevenueBar
                        key={module.id}
                        name={
                          <div className="flex items-center gap-2">
                            <ModuleIcon className="w-4 h-4" />
                            <span>{module.name}</span>
                          </div>
                        }
                        value={revenue}
                        percentage={getPercentage(revenue)}
                        color={moduleColors[index % moduleColors.length]}
                        delay={0.4 + index * 0.1}
                      />
                    );
                  })
                ) : (
                  // No modules configured - show empty state
                  <div className="text-center py-4 text-slate-500 dark:text-slate-400">
                    <p>No modules configured</p>
                    <p className="text-sm">Add modules in the Modules section to see revenue data</p>
                  </div>
                )}
              </div>

              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.8 }}
                className="mt-6 pt-6 border-t border-slate-100 dark:border-slate-700"
              >
                <div className="flex items-center justify-between">
                  <span className="font-medium text-slate-700 dark:text-slate-300">Total Revenue</span>
                  <span className="text-2xl font-bold text-slate-900 dark:text-white">
                    {formatCurrency(totalRevenue)}
                  </span>
                </div>
              </motion.div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Recent Orders */}
        <motion.div variants={fadeInUp}>
          <Card variant="glass">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Clock className="w-5 h-5 text-primary-600" />
                Recent Orders
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                <AnimatePresence mode="popLayout">
                  {(stats?.recentOrders || []).slice(0, 5).map((order: RecentOrder, index: number) => (
                    <motion.div
                      key={order.id}
                      initial={{ opacity: 0, x: 20 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: -20 }}
                      transition={{ delay: index * 0.1 }}
                      whileHover={{ scale: 1.02 }}
                      className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-700/50 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-xl transition-colors cursor-pointer"
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-gradient-to-br from-primary-400 to-primary-600 rounded-lg flex items-center justify-center text-white font-medium text-sm">
                          #{order.orderNumber?.slice(-3) || '---'}
                        </div>
                        <div>
                          <p className="font-medium text-slate-900 dark:text-white">{order.customerName || 'Guest'}</p>
                          <p className="text-sm text-slate-500 dark:text-slate-400">{order.itemCount || 0} items</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-semibold text-slate-900 dark:text-white">{formatCurrency(order.totalAmount || 0)}</p>
                        <OrderStatus status={order.status || 'pending'} />
                      </div>
                    </motion.div>
                  ))}
                </AnimatePresence>

                {(!stats?.recentOrders || stats.recentOrders.length === 0) && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="text-center py-8 text-slate-500 dark:text-slate-400"
                  >
                    <UtensilsCrossed className="w-12 h-12 mx-auto mb-3 text-slate-300 dark:text-slate-600" />
                    <p>No orders yet today</p>
                    <p className="text-sm">Orders will appear here as they come in</p>
                  </motion.div>
                )}
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Quick Actions - Dynamic based on active modules */}
      <motion.div variants={fadeInUp}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-primary-600" />
              Quick Actions
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {/* Dynamic module-based actions */}
              {activeModules.slice(0, 3).map((module, index) => {
                const ModuleIcon = getModuleIcon(module);
                // Determine the admin link based on template type
                // Routes use dynamic [slug] routes, not /admin/modules/
                let href = `/admin/${module.slug}`;
                let label = `Manage ${module.name}`;
                
                if (module.template_type === 'menu_service') {
                  href = `/admin/${module.slug}/menu`;
                  label = `${module.name} Menu`;
                } else if (module.template_type === 'multi_day_booking') {
                  href = `/admin/${module.slug}/bookings`;
                  label = `${module.name} Bookings`;
                } else if (module.template_type === 'session_access') {
                  href = `/admin/${module.slug}/sessions`;
                  label = `${module.name} Sessions`;
                }
                
                return (
                  <motion.div
                    key={module.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.8 + index * 0.1 }}
                  >
                    <Link href={href}>
                      <motion.div
                        whileHover={{ scale: 1.05, y: -4 }}
                        whileTap={{ scale: 0.98 }}
                        className="flex flex-col items-center gap-3 p-6 bg-slate-50 dark:bg-slate-700/50 hover:bg-white dark:hover:bg-slate-700 rounded-xl border border-slate-100 dark:border-slate-600 hover:border-slate-200 dark:hover:border-slate-500 hover:shadow-lg transition-all cursor-pointer"
                      >
                        <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${moduleColors[index % moduleColors.length]} flex items-center justify-center shadow-lg`}>
                          <ModuleIcon className="w-7 h-7 text-white" />
                        </div>
                        <span className="font-medium text-slate-700 dark:text-slate-200 text-center">{label}</span>
                      </motion.div>
                    </Link>
                  </motion.div>
                );
              })}
              {/* Always show Reports */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.8 + Math.min(activeModules.length, 3) * 0.1 }}
              >
                <Link href="/admin/reports">
                  <motion.div
                    whileHover={{ scale: 1.05, y: -4 }}
                    whileTap={{ scale: 0.98 }}
                    className="flex flex-col items-center gap-3 p-6 bg-slate-50 dark:bg-slate-700/50 hover:bg-white dark:hover:bg-slate-700 rounded-xl border border-slate-100 dark:border-slate-600 hover:border-slate-200 dark:hover:border-slate-500 hover:shadow-lg transition-all cursor-pointer"
                  >
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-purple-400 to-indigo-500 flex items-center justify-center shadow-lg">
                      <TrendingUp className="w-7 h-7 text-white" />
                    </div>
                    <span className="font-medium text-slate-700 dark:text-slate-200">View Reports</span>
                  </motion.div>
                </Link>
              </motion.div>
            </div>
          </CardContent>
        </Card>
      </motion.div>
    </motion.div>
  );
}

