export default function MultiPropertyPage() {
  const queryClient = useQueryClient();
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedProperty, setSelectedProperty] = useState<Property | null>(null);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [newProperty, setNewProperty] = useState({
    name: '',
    code: '',
    type: 'hotel',
    address: '',
    city: '',
    country: '',
    timezone: 'America/New_York',
    currency: 'USD',
    total_rooms: '',
    phone: '',
    email: '',
  });

  // Fetch properties
  const { data: properties = [], isLoading } = useQuery({
    queryKey: ['properties'],
    queryFn: async () => {
      try {
        // Use my-properties endpoint which returns properties accessible to current user
        const res = await api.get('/multi-property/my-properties');
        setFetchError(null);
        const rawProperties = res.data?.properties || [];
        return rawProperties.map((p: any) => ({
          ...p,
          code: p.code ?? p.property_code ?? '',
          type: p.type ?? p.property_type ?? 'hotel',
          status: p.status ?? (p.is_active ? 'active' : 'inactive'),
          address: p.address ?? p.address_line1 ?? '',
          total_rooms: Number(p.total_rooms ?? 0),
          available_rooms: Number(p.available_rooms ?? 0),
          occupancy_rate: Number(p.occupancy_rate ?? 0),
          revenue_today: Number(p.revenue_today ?? 0),
          revenue_mtd: Number(p.revenue_mtd ?? 0),
          reservations_today: Number(p.reservations_today ?? 0),
          staff_count: Number(p.staff_count ?? 0),
        }));
      } catch (error) {
        setFetchError('Could not connect to server');
        return [];
      }
    }
  });

  // Switch property context
  const switchPropertyMutation = useMutation({
    mutationFn: async (propertyId: string) => {
      const res = await api.post('/multi-property/switch-property', { property_id: propertyId });
      return res.data;
    },
    onSuccess: (_, propertyId) => {
      const property = properties.find((p: Property) => p.id === propertyId);
      toast.success(`Switched to ${property?.name}`);
    },
    onError: () => {
      toast.error('Failed to switch property');
    }
  });

  // Create property
  const createPropertyMutation = useMutation({
    mutationFn: async (data: typeof newProperty) => {
      const res = await api.post('/multi-property/properties', {
        name: data.name,
        property_code: data.code,
        property_type: data.type,
        address: data.address,
        city: data.city,
        country: data.country,
        timezone: data.timezone,
        currency: data.currency,
        total_rooms: data.total_rooms ? parseInt(data.total_rooms) : undefined,
        phone: data.phone,
        email: data.email,
      });
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['properties'] });
      setShowAddModal(false);
      setNewProperty({ name: '', code: '', type: 'hotel', address: '', city: '', country: '', timezone: 'America/New_York', currency: 'USD', total_rooms: '', phone: '', email: '' });
      toast.success('Property created');
    },
    onError: () => {
      toast.error('Failed to create property');
    }
  });

  // Filter properties
  const filteredProperties = properties.filter((p: Property) =>
    !searchTerm ||
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.city.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Aggregate stats
  const stats = {
    totalProperties: properties.length,
    activeProperties: properties.filter((p: Property) => p.status === 'active').length,
    totalRooms: properties.reduce((sum: number, p: Property) => sum + p.total_rooms, 0),
    avgOccupancy: Math.round(
      properties.reduce((sum: number, p: Property) => sum + p.occupancy_rate, 0) /
      Math.max(properties.length, 1)
    ),
    totalRevenueToday: properties.reduce((sum: number, p: Property) => sum + p.revenue_today, 0),
    totalRevenueMTD: properties.reduce((sum: number, p: Property) => sum + p.revenue_mtd, 0)
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(amount);
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Multi-Property Management</h1>
          <p className="text-slate-600 dark:text-slate-400">Manage all your properties from one place</p>
        </div>
        <button
          onClick={() => setShowAddModal(true)}
          className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 transition-colors"
        >
          <Plus className="w-4 h-4" />
          Add Property
        </button>
      </div>

      {/* Portfolio Stats */}
      <div className="grid grid-cols-6 gap-4">
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-primary/10">
              <Building2 className="w-5 h-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{stats.totalProperties}</p>
              <p className="text-sm text-slate-500">Properties</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-green-100 dark:bg-green-900/30">
              <CheckCircle className="w-5 h-5 text-green-600 dark:text-green-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{stats.activeProperties}</p>
              <p className="text-sm text-slate-500">Active</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-100 dark:bg-blue-900/30">
              <Bed className="w-5 h-5 text-blue-600 dark:text-blue-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{stats.totalRooms}</p>
              <p className="text-sm text-slate-500">Total Rooms</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-purple-100 dark:bg-purple-900/30">
              <Activity className="w-5 h-5 text-purple-600 dark:text-purple-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{stats.avgOccupancy}%</p>
              <p className="text-sm text-slate-500">Avg Occupancy</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-emerald-100 dark:bg-emerald-900/30">
              <DollarSign className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{formatCurrency(stats.totalRevenueToday)}</p>
              <p className="text-sm text-slate-500">Today</p>
            </div>
          </div>
        </div>
        <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-amber-100 dark:bg-amber-900/30">
              <TrendingUp className="w-5 h-5 text-amber-600 dark:text-amber-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{formatCurrency(stats.totalRevenueMTD)}</p>
              <p className="text-sm text-slate-500">MTD Revenue</p>
            </div>
          </div>
        </div>
      </div>

      {/* Search */}
      <div className="relative max-w-md">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
        <input
          type="text"
          placeholder="Search properties..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full pl-10 pr-4 py-2 border border-slate-200 dark:border-slate-700 rounded-lg bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
        />
      </div>

      {/* Properties Grid */}
      {isLoading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-primary" />
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
          {filteredProperties.map((property: Property) => (
            <div
              key={property.id}
              className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 overflow-hidden hover:shadow-lg transition-shadow"
            >
              {/* Header */}
              <div className="p-4 border-b border-slate-200 dark:border-slate-700">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <span className="text-3xl">{typeIcons[property.type]}</span>
                    <div>
                      <h3 className="font-semibold text-slate-900 dark:text-white">{property.name}</h3>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-xs text-slate-500 font-mono">{property.code}</span>
                        <span className={`text-xs px-2 py-0.5 rounded-full ${statusColors[property.status]}`}>
                          {property.status}
                        </span>
                      </div>
                    </div>
                  </div>
                  <button className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700">
                    <MoreHorizontal className="w-4 h-4" />
                  </button>
                </div>
              </div>

              {/* Stats */}
              <div className="p-4 grid grid-cols-2 gap-4">
                <div>
                  <p className="text-xs text-slate-500">Occupancy</p>
                  <div className="flex items-center gap-2">
                    <div className="flex-1 h-2 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                      <div
                        className={`h-full rounded-full ${
                          property.occupancy_rate >= 80 ? 'bg-green-500' :
                          property.occupancy_rate >= 50 ? 'bg-yellow-500' : 'bg-red-500'
                        }`}
                        style={{ width: `${property.occupancy_rate}%` }}
                      />
                    </div>
                    <span className="text-sm font-semibold text-slate-900 dark:text-white">
                      {property.occupancy_rate}%
                    </span>
                  </div>
                </div>
                <div>
                  <p className="text-xs text-slate-500">Rooms</p>
                  <p className="text-lg font-semibold text-slate-900 dark:text-white">
                    {property.available_rooms} <span className="text-sm font-normal text-slate-500">/ {property.total_rooms}</span>
                  </p>
                </div>
                <div>
                  <p className="text-xs text-slate-500">Today's Revenue</p>
                  <p className="text-lg font-semibold text-slate-900 dark:text-white">
                    {formatCurrency(property.revenue_today)}
                  </p>
                </div>
                <div>
                  <p className="text-xs text-slate-500">Reservations</p>
                  <p className="text-lg font-semibold text-slate-900 dark:text-white">
                    {property.reservations_today} <span className="text-sm font-normal text-slate-500">today</span>
                  </p>
                </div>
              </div>

              {/* Location */}
              <div className="px-4 py-3 bg-slate-50 dark:bg-slate-700/30 border-t border-slate-200 dark:border-slate-700">
                <div className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
                  <MapPin className="w-4 h-4" />
                  <span>{property.city}, {property.country}</span>
                </div>
              </div>

              {/* Actions */}
              <div className="p-4 border-t border-slate-200 dark:border-slate-700 flex justify-between items-center">
                <button
                  onClick={() => switchPropertyMutation.mutate(property.id)}
                  disabled={switchPropertyMutation.isPending || property.status !== 'active'}
                  className="px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                >
                  {switchPropertyMutation.isPending ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <ChevronRight className="w-4 h-4" />
                  )}
                  Switch to Property
                </button>
                <button
                  onClick={() => setSelectedProperty(property)}
                  className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
                >
                  <Settings className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Add Property Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 max-w-lg w-full mx-4 max-h-[90vh] overflow-y-auto">
            <h2 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">
              Add New Property
            </h2>
            <form className="space-y-4" onSubmit={(e) => {
              e.preventDefault();
              if (!newProperty.name) {
                toast.error('Property name is required');
                return;
              }
              createPropertyMutation.mutate(newProperty);
            }}>
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Property Name
                  </label>
                  <input
                    type="text"
                    placeholder="e.g., Iron Paradise Gym Downtown"
                    value={newProperty.name}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, name: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Property Code
                  </label>
                  <input
                    type="text"
                    placeholder="e.g., V2-DTN"
                    value={newProperty.code}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, code: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Property Type
                  </label>
                  <select
                    value={newProperty.type}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, type: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  >
                    <option value="hotel">Hotel</option>
                    <option value="resort">Resort</option>
                    <option value="villa">Villa</option>
                    <option value="apartment">Apartment</option>
                    <option value="hostel">Hostel</option>
                  </select>
                </div>
                <div className="col-span-2">
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Address
                  </label>
                  <input
                    type="text"
                    placeholder="Street address"
                    value={newProperty.address}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, address: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    City
                  </label>
                  <input
                    type="text"
                    value={newProperty.city}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, city: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Country
                  </label>
                  <input
                    type="text"
                    value={newProperty.country}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, country: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Timezone
                  </label>
                  <select
                    value={newProperty.timezone}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, timezone: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  >
                    <option value="America/New_York">Eastern (ET)</option>
                    <option value="America/Chicago">Central (CT)</option>
                    <option value="America/Denver">Mountain (MT)</option>
                    <option value="America/Los_Angeles">Pacific (PT)</option>
                    <option value="UTC">UTC</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Currency
                  </label>
                  <select
                    value={newProperty.currency}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, currency: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  >
                    <option value="USD">USD ($)</option>
                    <option value="EUR">EUR (€)</option>
                    <option value="GBP">GBP (£)</option>
                    <option value="CAD">CAD (C$)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Total Rooms
                  </label>
                  <input
                    type="number"
                    min="1"
                    value={newProperty.total_rooms}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, total_rooms: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Phone
                  </label>
                  <input
                    type="tel"
                    value={newProperty.phone}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, phone: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Email
                  </label>
                  <input
                    type="email"
                    value={newProperty.email}
                    onChange={(e) => setNewProperty(prev => ({ ...prev, email: e.target.value }))}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
              </div>
              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  className="flex-1 py-2 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={createPropertyMutation.isPending}
                  className="flex-1 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {createPropertyMutation.isPending && <Loader2 className="w-4 h-4 animate-spin" />}
                  Add Property
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Property Details Modal */}
      {selectedProperty && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 max-w-lg w-full mx-4">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-slate-900 dark:text-white">
                Property Settings
              </h2>
              <button
                onClick={() => setSelectedProperty(null)}
                className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
              >
                ✕
              </button>
            </div>
            <div className="space-y-4">
              <div className="flex items-center gap-4">
                <span className="text-4xl">{typeIcons[selectedProperty.type]}</span>
                <div>
                  <h3 className="text-xl font-bold text-slate-900 dark:text-white">
                    {selectedProperty.name}
                  </h3>
                  <p className="text-slate-500">{selectedProperty.code}</p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3 text-sm">
                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                  <MapPin className="w-4 h-4" />
                  {selectedProperty.city}, {selectedProperty.country}
                </div>
                {selectedProperty.phone && (
                  <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                    <Phone className="w-4 h-4" />
                    {selectedProperty.phone}
                  </div>
                )}
                {selectedProperty.email && (
                  <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                    <Mail className="w-4 h-4" />
                    {selectedProperty.email}
                  </div>
                )}
                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
                  <Users className="w-4 h-4" />
                  {selectedProperty.staff_count} staff members
                </div>
              </div>
              <div className="pt-4 border-t border-slate-200 dark:border-slate-700">
                <h4 className="font-medium text-slate-900 dark:text-white mb-3">Quick Actions</h4>
                <div className="grid grid-cols-2 gap-2">
                  <button className="px-4 py-2 text-sm bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-600">
                    Edit Details
                  </button>
                  <button className="px-4 py-2 text-sm bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-600">
                    Manage Staff
                  </button>
                  <button className="px-4 py-2 text-sm bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-600">
                    Room Types
                  </button>
                  <button className="px-4 py-2 text-sm bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-600">
                    View Reports
                  </button>
                </div>
              </div>
              {selectedProperty.status === 'active' && (
                <button
                  onClick={() => {
                    switchPropertyMutation.mutate(selectedProperty.id);
                    setSelectedProperty(null);
                  }}
                  className="w-full py-3 bg-primary text-white rounded-lg hover:bg-primary/90 flex items-center justify-center gap-2"
                >
                  <ChevronRight className="w-4 h-4" />
                  Switch to This Property
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { CardSkeleton } from '@/components/ui/Skeleton';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import Link from 'next/link';
import {
  BarChart3,
  TrendingUp,
  TrendingDown,
  DollarSign,
  Users,
  ShoppingCart,
  Briefcase,
  Building2,
  FileSpreadsheet,
  Shield,
  Activity,
  RefreshCw,
  ArrowUpRight,
  ArrowDownRight,
  AlertTriangle,
  CheckCircle,
  XCircle,
  Clock,
  Download,
  Calendar,
  PieChart,
  LineChart,
  BarChart2,
  Target,
} from 'lucide-react';

// 10 Report Categories from Planning.md
const REPORT_CATEGORIES = [
  {
    id: 'executive',
    name: 'Executive Overview',
    description: 'Immediate situational awareness - revenue, orders, growth, health',
    icon: Briefcase,
    color: 'from-indigo-500 to-purple-500',
    bgColor: 'bg-indigo-100 dark:bg-indigo-900/30',
    textColor: 'text-indigo-600 dark:text-indigo-400',
    endpoint: '/reports/executive-overview',
  },
  {
    id: 'sales',
    name: 'Sales & Revenue',
    description: 'Where money comes from - by time, service, location',
    icon: DollarSign,
    color: 'from-green-500 to-emerald-500',
    bgColor: 'bg-green-100 dark:bg-green-900/30',
    textColor: 'text-green-600 dark:text-green-400',
    endpoint: '/reports/daily-sales',
  },
  {
    id: 'orders',
    name: 'Order Flow & Operations',
    description: 'Order funnel, prep times, bottlenecks, cancellations',
    icon: ShoppingCart,
    color: 'from-blue-500 to-cyan-500',
    bgColor: 'bg-blue-100 dark:bg-blue-900/30',
    textColor: 'text-blue-600 dark:text-blue-400',
    endpoint: '/reports/order-flow',
  },
  {
    id: 'customers',
    name: 'Customer Intelligence',
    description: 'New vs returning, retention, CLV, top customers',
    icon: Users,
    color: 'from-purple-500 to-pink-500',
    bgColor: 'bg-purple-100 dark:bg-purple-900/30',
    textColor: 'text-purple-600 dark:text-purple-400',
    endpoint: '/reports/customer-intelligence',
  },
  {
    id: 'products',
    name: 'Product & Menu Performance',
    description: 'Top sellers, time-based popularity, attach rate, margins',
    icon: PieChart,
    color: 'from-orange-500 to-amber-500',
    bgColor: 'bg-orange-100 dark:bg-orange-900/30',
    textColor: 'text-orange-600 dark:text-orange-400',
    endpoint: '/reports/menu-performance',
  },
  {
    id: 'payments',
    name: 'Payments & Finance',
    description: 'Revenue by method, refunds, reconciliation, Stripe',
    icon: FileSpreadsheet,
    color: 'from-teal-500 to-green-500',
    bgColor: 'bg-teal-100 dark:bg-teal-900/30',
    textColor: 'text-teal-600 dark:text-teal-400',
    endpoint: '/reports/payments-finance',
  },
  {
    id: 'capacity',
    name: 'Capacity & Utilization',
    description: 'Occupancy, RevPAR, booking conversion, no-shows',
    icon: Building2,
    color: 'from-rose-500 to-red-500',
    bgColor: 'bg-rose-100 dark:bg-rose-900/30',
    textColor: 'text-rose-600 dark:text-rose-400',
    endpoint: '/reports/capacity-utilization',
  },
  {
    id: 'staff',
    name: 'Staff & System Performance',
    description: 'Orders per staff, handling time, logins, overrides',
    icon: Activity,
    color: 'from-sky-500 to-blue-500',
    bgColor: 'bg-sky-100 dark:bg-sky-900/30',
    textColor: 'text-sky-600 dark:text-sky-400',
    endpoint: '/reports/staff-performance',
  },
  {
    id: 'trends',
    name: 'Comparative & Trends',
    description: 'Period comparisons, forecasting, anomaly detection',
    icon: LineChart,
    color: 'from-violet-500 to-indigo-500',
    bgColor: 'bg-violet-100 dark:bg-violet-900/30',
    textColor: 'text-violet-600 dark:text-violet-400',
    endpoint: '/reports/comparative-analysis',
  },
  {
    id: 'audit',
    name: 'Export & Audit',
    description: 'CSV/Excel exports, audit logs, compliance',
    icon: Shield,
    color: 'from-slate-500 to-gray-500',
    bgColor: 'bg-slate-100 dark:bg-slate-900/30',
    textColor: 'text-slate-600 dark:text-slate-400',
    endpoint: '/reports/audit',
  },
];

interface ExecutiveData {
  today: { revenue: number; orders: number; bookings: number };
  mtd: { revenue: number; netRevenue: number; orders: number; bookings: number; discounts: number; refunds: number };
  ytd: { revenue: number; orders: number; bookings: number };
  growth: { orderGrowthPercent: string; revenueGrowthPercent: string };
  aov: string;
  activeCustomers: number;
  systemHealth: { orderFailures24h: number; paymentFailures24h: number; status: string };
}

export default function AnalyticsReportsPage() {
  const t = useTranslations('adminReports');
  const [executiveData, setExecutiveData] = useState<ExecutiveData | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [categoryData, setCategoryData] = useState<any>(null);
  const [categoryLoading, setCategoryLoading] = useState(false);
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Set default date range (last 30 days)
  useEffect(() => {
    const end = new Date();
    const start = new Date(end.getTime() - 30 * 24 * 60 * 60 * 1000);
    setDateRange({
      start: start.toISOString().split('T')[0],
      end: end.toISOString().split('T')[0],
    });
  }, []);

  const fetchExecutiveOverview = useCallback(async () => {
    try {
      setLoading(true);
      const response = await api.get('/reports/executive-overview');
      setExecutiveData(response.data.data);
    } catch (error) {
      console.error('Failed to fetch executive overview:', error);
      toast.error('Failed to load executive overview');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchExecutiveOverview();
  }, [fetchExecutiveOverview]);

  const fetchCategoryData = async (category: typeof REPORT_CATEGORIES[0]) => {
    try {
      setCategoryLoading(true);
      setSelectedCategory(category.id);
      const response = await api.get(category.endpoint, {
        params: { startDate: dateRange.start, endDate: dateRange.end },
      });
      setCategoryData(response.data.data);
    } catch (error) {
      console.error(`Failed to fetch ${category.name}:`, error);
      toast.error(`Failed to load ${category.name}`);
    } finally {
      setCategoryLoading(false);
    }
  };

  const exportData = async (format: 'csv' | 'json' = 'csv') => {
    try {
      const response = await api.get('/reports/export-comprehensive', {
        params: {
          format,
          reportTypes: 'daily_sales,product_performance,payments,orders,bookings',
          startDate: dateRange.start,
          endDate: dateRange.end,
        },
        responseType: format === 'csv' ? 'blob' : 'json',
      });

      if (format === 'csv') {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `comprehensive_report_${dateRange.start}_${dateRange.end}.csv`);
        document.body.appendChild(link);
        link.click();
        link.remove();
        toast.success('Report exported successfully');
      } else {
        // Handle JSON download
        const dataStr = JSON.stringify(response.data.data, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `comprehensive_report_${dateRange.start}_${dateRange.end}.json`);
        document.body.appendChild(link);
        link.click();
        link.remove();
        toast.success('Report exported successfully');
      }
    } catch (error) {
      toast.error('Failed to export report');
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <CardSkeleton key={i} />
          ))}
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {[...Array(6)].map((_, i) => (
            <CardSkeleton key={i} />
          ))}
        </div>
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
            Analytics Dashboard
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            Comprehensive reporting across 10 categories
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          {/* Date Range */}
          <div className="flex items-center gap-2 bg-slate-100 dark:bg-slate-800 rounded-lg p-2">
            <Calendar className="w-4 h-4 text-slate-500" />
            <input
              type="date"
              value={dateRange.start}
              onChange={(e) => setDateRange(prev => ({ ...prev, start: e.target.value }))}
              className="bg-transparent border-none text-sm focus:outline-none"
            />
            <span className="text-slate-400">to</span>
            <input
              type="date"
              value={dateRange.end}
              onChange={(e) => setDateRange(prev => ({ ...prev, end: e.target.value }))}
              className="bg-transparent border-none text-sm focus:outline-none"
            />
          </div>
          <Button variant="outline" onClick={fetchExecutiveOverview}>
            <RefreshCw className="w-4 h-4 mr-2" />
            Refresh
          </Button>
          <Button onClick={() => exportData('csv')}>
            <Download className="w-4 h-4 mr-2" />
            Export All
          </Button>
        </div>
      </div>

      {/* Executive Overview KPIs */}
      {executiveData && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <motion.div variants={fadeInUp}>
            <Card className="relative overflow-hidden">
              <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-green-500 to-emerald-500" />
              <CardContent className="p-6">
                <div className="flex items-start justify-between">
                  <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400">Today&apos;s Revenue</p>
                    <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                      {formatCurrency(executiveData.today.revenue)}
                    </p>
                    <div className={`flex items-center gap-1 mt-2 text-sm ${
                      parseFloat(executiveData.growth.revenueGrowthPercent) >= 0 ? 'text-green-500' : 'text-red-500'
                    }`}>
                      {parseFloat(executiveData.growth.revenueGrowthPercent) >= 0 ? (
                        <ArrowUpRight className="w-4 h-4" />
                      ) : (
                        <ArrowDownRight className="w-4 h-4" />
                      )}
                      {Math.abs(parseFloat(executiveData.growth.revenueGrowthPercent))}% vs last month
                    </div>
                  </div>
                  <div className="p-3 rounded-xl bg-green-100 dark:bg-green-900/30">
                    <DollarSign className="w-6 h-6 text-green-600 dark:text-green-400" />
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>

          <motion.div variants={fadeInUp}>
            <Card className="relative overflow-hidden">
              <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-blue-500 to-indigo-500" />
              <CardContent className="p-6">
                <div className="flex items-start justify-between">
                  <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400">MTD Revenue</p>
                    <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                      {formatCurrency(executiveData.mtd.revenue)}
                    </p>
                    <p className="text-sm text-slate-400 mt-2">
                      Net: {formatCurrency(executiveData.mtd.netRevenue)}
                    </p>
                  </div>
                  <div className="p-3 rounded-xl bg-blue-100 dark:bg-blue-900/30">
                    <BarChart3 className="w-6 h-6 text-blue-600 dark:text-blue-400" />
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>

          <motion.div variants={fadeInUp}>
            <Card className="relative overflow-hidden">
              <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-purple-500 to-pink-500" />
              <CardContent className="p-6">
                <div className="flex items-start justify-between">
                  <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400">Active Customers</p>
                    <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                      {executiveData.activeCustomers}
                    </p>
                    <p className="text-sm text-slate-400 mt-2">
                      AOV: {formatCurrency(parseFloat(executiveData.aov))}
                    </p>
                  </div>
                  <div className="p-3 rounded-xl bg-purple-100 dark:bg-purple-900/30">
                    <Users className="w-6 h-6 text-purple-600 dark:text-purple-400" />
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>

          <motion.div variants={fadeInUp}>
            <Card className="relative overflow-hidden">
              <div className={`absolute top-0 left-0 right-0 h-1 ${
                executiveData.systemHealth.status === 'healthy' 
                  ? 'bg-gradient-to-r from-green-500 to-emerald-500'
                  : 'bg-gradient-to-r from-yellow-500 to-orange-500'
              }`} />
              <CardContent className="p-6">
                <div className="flex items-start justify-between">
                  <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400">System Health</p>
                    <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1 capitalize">
                      {executiveData.systemHealth.status}
                    </p>
                    <div className="flex items-center gap-2 mt-2 text-sm text-slate-500">
                      {executiveData.systemHealth.orderFailures24h > 0 && (
                        <span className="text-red-500">
                          {executiveData.systemHealth.orderFailures24h} order failures
                        </span>
                      )}
                      {executiveData.systemHealth.paymentFailures24h > 0 && (
                        <span className="text-red-500">
                          {executiveData.systemHealth.paymentFailures24h} payment failures
                        </span>
                      )}
                      {executiveData.systemHealth.status === 'healthy' && (
                        <span className="text-green-500">All systems operational</span>
                      )}
                    </div>
                  </div>
                  <div className={`p-3 rounded-xl ${
                    executiveData.systemHealth.status === 'healthy'
                      ? 'bg-green-100 dark:bg-green-900/30'
                      : 'bg-yellow-100 dark:bg-yellow-900/30'
                  }`}>
                    {executiveData.systemHealth.status === 'healthy' ? (
                      <CheckCircle className="w-6 h-6 text-green-600 dark:text-green-400" />
                    ) : (
                      <AlertTriangle className="w-6 h-6 text-yellow-600 dark:text-yellow-400" />
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        </div>
      )}

      {/* 10 Report Categories */}
      <div>
        <h2 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">
          Report Categories
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4">
          {REPORT_CATEGORIES.map((category, index) => (
            <motion.div
              key={category.id}
              variants={fadeInUp}
              transition={{ delay: index * 0.05 }}
            >
              <Card 
                className={`cursor-pointer hover:shadow-lg transition-all duration-200 ${
                  selectedCategory === category.id ? 'ring-2 ring-primary-500' : ''
                }`}
                onClick={() => fetchCategoryData(category)}
              >
                <CardContent className="p-4">
                  <div className={`w-12 h-12 rounded-xl ${category.bgColor} flex items-center justify-center mb-3`}>
                    <category.icon className={`w-6 h-6 ${category.textColor}`} />
                  </div>
                  <h3 className="font-semibold text-slate-900 dark:text-white text-sm">
                    {category.name}
                  </h3>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 line-clamp-2">
                    {category.description}
                  </p>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>
      </div>

      {/* Selected Category Detail */}
      {selectedCategory && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>
                {REPORT_CATEGORIES.find(c => c.id === selectedCategory)?.name} Report
              </CardTitle>
              <Button 
                variant="ghost" 
                size="sm"
                onClick={() => {
                  setSelectedCategory(null);
                  setCategoryData(null);
                }}
              >
                <XCircle className="w-4 h-4" />
              </Button>
            </CardHeader>
            <CardContent>
              {categoryLoading ? (
                <div className="flex items-center justify-center py-12">
                  <RefreshCw className="w-8 h-8 animate-spin text-primary-500" />
                </div>
              ) : categoryData ? (
                <div className="space-y-4">
                  {/* Render based on category type */}
                  {selectedCategory === 'orders' && categoryData.funnel && (
                    <div className="grid grid-cols-2 md:grid-cols-6 gap-4">
                      {Object.entries(categoryData.funnel).map(([status, count]) => (
                        <div key={status} className="text-center p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                          <p className="text-2xl font-bold text-slate-900 dark:text-white">{count as number}</p>
                          <p className="text-sm text-slate-500 capitalize">{status}</p>
                        </div>
                      ))}
                    </div>
                  )}

                  {selectedCategory === 'customers' && categoryData.overview && (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Total Customers</p>
                        <p className="text-2xl font-bold">{categoryData.overview.totalCustomers}</p>
                      </div>
                      <div className="p-4 bg-green-50 dark:bg-green-900/20 rounded-lg">
                        <p className="text-sm text-green-600">New Customers</p>
                        <p className="text-2xl font-bold text-green-700">{categoryData.overview.newCustomers}</p>
                      </div>
                      <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                        <p className="text-sm text-blue-600">Returning</p>
                        <p className="text-2xl font-bold text-blue-700">{categoryData.overview.returningCustomers}</p>
                      </div>
                    </div>
                  )}

                  {selectedCategory === 'products' && categoryData.topSellers && (
                    <div className="overflow-x-auto">
                      <table className="w-full">
                        <thead>
                          <tr className="border-b">
                            <th className="text-left py-2">Product</th>
                            <th className="text-right py-2">Quantity</th>
                            <th className="text-right py-2">Revenue</th>
                          </tr>
                        </thead>
                        <tbody>
                          {categoryData.topSellers.slice(0, 10).map((item: any) => (
                            <tr key={item.productId} className="border-b">
                              <td className="py-2">{item.productName}</td>
                              <td className="text-right">{item.quantity}</td>
                              <td className="text-right font-semibold">{formatCurrency(item.revenue)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}

                  {selectedCategory === 'payments' && categoryData.summary && (
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Total Revenue</p>
                        <p className="text-2xl font-bold">{formatCurrency(categoryData.summary.totalRevenue)}</p>
                      </div>
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Transactions</p>
                        <p className="text-2xl font-bold">{categoryData.summary.totalPayments}</p>
                      </div>
                      <div className="p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
                        <p className="text-sm text-red-600">Failed</p>
                        <p className="text-2xl font-bold text-red-700">{categoryData.summary.failedPayments}</p>
                      </div>
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Failure Rate</p>
                        <p className="text-2xl font-bold">{categoryData.summary.failureRate}%</p>
                      </div>
                    </div>
                  )}

                  {selectedCategory === 'capacity' && categoryData.overview && (
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Total Units</p>
                        <p className="text-2xl font-bold">{categoryData.overview.totalUnits}</p>
                      </div>
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Occupancy Rate</p>
                        <p className="text-2xl font-bold">{categoryData.overview.occupancyRate}%</p>
                      </div>
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Booked Days</p>
                        <p className="text-2xl font-bold">{categoryData.overview.bookedDays}</p>
                      </div>
                      <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                        <p className="text-sm text-slate-500">Total Capacity</p>
                        <p className="text-2xl font-bold">{categoryData.overview.totalCapacityDays}</p>
                      </div>
                    </div>
                  )}

                  {selectedCategory === 'staff' && categoryData.staffPerformance && (
                    <div className="overflow-x-auto">
                      <table className="w-full">
                        <thead>
                          <tr className="border-b">
                            <th className="text-left py-2">Staff Member</th>
                            <th className="text-right py-2">Orders</th>
                            <th className="text-right py-2">Revenue</th>
                            <th className="text-right py-2">Avg Time</th>
                          </tr>
                        </thead>
                        <tbody>
                          {categoryData.staffPerformance.map((staff: any) => (
                            <tr key={staff.staffId} className="border-b">
                              <td className="py-2">{staff.name}</td>
                              <td className="text-right">{staff.ordersHandled}</td>
                              <td className="text-right font-semibold">{formatCurrency(staff.revenue)}</td>
                              <td className="text-right">{staff.avgHandlingTimeMinutes} min</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}

                  {selectedCategory === 'trends' && categoryData.comparison && (
                    <div className="space-y-4">
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {Object.entries(categoryData.comparison).map(([metric, data]: [string, any]) => (
                          <div key={metric} className="p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
                            <p className="text-sm text-slate-500 capitalize">{metric.replace('_', ' ')}</p>
                            <p className="text-xl font-bold">
                              {typeof data.current === 'number' && metric.includes('revenue') 
                                ? formatCurrency(data.current) 
                                : data.current}
                            </p>
                            <div className={`flex items-center gap-1 text-sm ${
                              parseFloat(data.change) >= 0 ? 'text-green-500' : 'text-red-500'
                            }`}>
                              {parseFloat(data.change) >= 0 ? (
                                <TrendingUp className="w-4 h-4" />
                              ) : (
                                <TrendingDown className="w-4 h-4" />
                              )}
                              {data.change}%
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  {selectedCategory === 'audit' && categoryData.logs && (
                    <div className="space-y-4">
                      <div className="text-sm text-slate-500">
                        Showing {categoryData.logs.length} of {categoryData.summary.total} logs
                      </div>
                      <div className="max-h-96 overflow-y-auto">
                        <table className="w-full text-sm">
                          <thead className="sticky top-0 bg-white dark:bg-slate-900">
                            <tr className="border-b">
                              <th className="text-left py-2">Action</th>
                              <th className="text-left py-2">User</th>
                              <th className="text-right py-2">Time</th>
                            </tr>
                          </thead>
                          <tbody>
                            {categoryData.logs.slice(0, 50).map((log: any, i: number) => (
                              <tr key={i} className="border-b">
                                <td className="py-2 font-mono text-xs">{log.action}</td>
                                <td className="py-2">{log.user_id || 'System'}</td>
                                <td className="text-right text-slate-500">
                                  {formatDate(log.created_at)}
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  )}

                  {/* Generic data display for other categories */}
                  {!['orders', 'customers', 'products', 'payments', 'capacity', 'staff', 'trends', 'audit'].includes(selectedCategory) && (
                    <pre className="bg-slate-50 dark:bg-slate-800 p-4 rounded-lg overflow-auto max-h-96 text-sm">
                      {JSON.stringify(categoryData, null, 2)}
                    </pre>
                  )}
                </div>
              ) : (
                <div className="text-center py-8 text-slate-500">
                  No data available for this report
                </div>
              )}
            </CardContent>
          </Card>
        </motion.div>
      )}

      {/* Quick Links */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Quick Actions</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <Link href="/admin/reports">
              <Button variant="outline" className="w-full justify-start">
                <BarChart2 className="w-4 h-4 mr-2" />
                Legacy Reports Dashboard
              </Button>
            </Link>
            <Link href="/admin/reports/scheduled">
              <Button variant="outline" className="w-full justify-start">
                <Clock className="w-4 h-4 mr-2" />
                Scheduled Reports
              </Button>
            </Link>
            <Button variant="outline" className="w-full justify-start" onClick={() => exportData('json')}>
              <Download className="w-4 h-4 mr-2" />
              Export as JSON
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg">YTD Summary</CardTitle>
          </CardHeader>
          <CardContent>
            {executiveData?.ytd && (
              <div className="space-y-3">
                <div className="flex justify-between">
                  <span className="text-slate-500">Total Revenue</span>
                  <span className="font-semibold">{formatCurrency(executiveData.ytd.revenue)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Total Orders</span>
                  <span className="font-semibold">{executiveData.ytd.orders}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Total Bookings</span>
                  <span className="font-semibold">{executiveData.ytd.bookings}</span>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </motion.div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { CardSkeleton } from '@/components/ui/Skeleton';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import Link from 'next/link';
import {
  BarChart3,
  TrendingUp,
  TrendingDown,
  DollarSign,
  Users,
  Calendar,
  Download,
  RefreshCw,
  UtensilsCrossed,
  Home,
  Waves,
  Cookie,
  ArrowUpRight,
  ArrowDownRight,
  CalendarClock,
} from 'lucide-react';

interface OccupancyData {
  chalets: {
    occupancyRate: number;
    bookedNights: number;
    totalCapacity: number;
    activeUnits: number;
  };
  pool: {
    occupancyRate: number;
    ticketsSold: number;
    totalCapacity: number;
    dailyCapacity: number;
  };
}

interface CustomerData {
  topCustomers: Array<{
    id: string;
    name: string;
    revenue: number;
    count: number;
  }>;
  customerRetention: {
    new: number;
    returning: number;
    total: number;
    newRatio: number;
  };
}

interface ReportData {
  overview: {
    totalRevenue: number;
    totalOrders: number;
    totalBookings: number;
    totalUsers: number;
    revenueChange: number;
    ordersChange: number;
  };
  revenueByService: {
    restaurant: number;
    snackBar: number;
    chalets: number;
    pool: number;
  };
  revenueByMonth: Array<{
    month: string;
    revenue: number;
  }>;
  topItems: Array<{
    name: string;
    quantity: number;
    revenue: number;
  }>;
}

type ExportType = 'restaurant' | 'chalets' | 'pool' | 'snack' | 'users';

const EXPORT_OPTIONS: { value: ExportType; label: string }[] = [
  { value: 'restaurant', label: 'Restaurant Orders' },
  { value: 'chalets', label: 'Chalet Bookings' },
  { value: 'pool', label: 'Pool Tickets' },
  { value: 'snack', label: 'Snack Orders' },
  { value: 'users', label: 'Users' },
];

export default function AdminReportsPage() {
  const t = useTranslations('adminReports');
  const tc = useTranslations('adminCommon');
  
  const [reportData, setReportData] = useState<ReportData | null>(null);
  const [occupancyData, setOccupancyData] = useState<OccupancyData | null>(null);
  const [customerData, setCustomerData] = useState<CustomerData | null>(null);
  const [loading, setLoading] = useState(true);
  const [dateRange, setDateRange] = useState<'week' | 'month' | 'year'>('month');
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [exporting, setExporting] = useState(false);

  const fetchReports = useCallback(async () => {
    try {
      setLoading(true);
      const [overviewRes, occupancyRes, customerRes] = await Promise.all([
        api.get('/admin/reports/overview', { params: { range: dateRange } }),
        api.get('/admin/reports/occupancy', { params: { range: dateRange } }),
        api.get('/admin/reports/customers', { params: { range: dateRange } }),
      ]);

      setReportData(overviewRes.data.data || null);
      setOccupancyData(occupancyRes.data.data || null);
      setCustomerData(customerRes.data.data || null);
    } catch (error) {
      console.error('Failed to fetch reports:', error);
      toast.error(t('errors.failedToLoad'));
      setReportData(null);
    } finally {
      setLoading(false);
    }
  }, [dateRange]);

  useEffect(() => {
    fetchReports();
  }, [fetchReports]);

  const exportReport = async (type: ExportType) => {
    setExporting(true);
    setShowExportMenu(false);
    try {
      const response = await api.get('/admin/reports/export', {
        params: { range: dateRange, format: 'csv', type },
        responseType: 'blob',
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `${type}-report-${dateRange}-${new Date().toISOString().split('T')[0]}.csv`);
      document.body.appendChild(link);
      link.click();
      link.remove();

      toast.success(t('exported'));
    } catch (error) {
      toast.error(t('errors.failedToExport'));
    } finally {
      setExporting(false);
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <CardSkeleton key={i} />
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  // Handle case when no data is available
  if (!reportData) {
    return (
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
              {t('title')}
            </h1>
            <p className="text-slate-500 dark:text-slate-400">
              {t('subtitle')}
            </p>
          </div>
          <Button variant="outline" onClick={fetchReports}>
            <RefreshCw className="w-4 h-4 mr-2" />
            {tc('refresh')}
          </Button>
        </div>
        <Card>
          <CardContent className="p-12 text-center">
            <BarChart3 className="w-12 h-12 text-slate-400 mx-auto mb-4" />
            <p className="text-lg font-medium text-slate-700 dark:text-slate-300">{tc('noData')}</p>
            <p className="text-slate-500 dark:text-slate-400">{t('subtitle')}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const data = reportData;
  const totalServiceRevenue = data.revenueByService ? Object.values(data.revenueByService).reduce((a, b) => a + b, 0) : 0;
  const revenueByMonth = data.revenueByMonth || [];
  const topItems = data.topItems || [];

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
            {t('title')}
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            {t('subtitle')}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {/* Date Range Selector */}
          <div className="flex bg-slate-100 dark:bg-slate-800 rounded-lg p-1">
            {(['week', 'month', 'year'] as const).map((range) => (
              <button
                key={range}
                onClick={() => setDateRange(range)}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${dateRange === range
                  ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow'
                  : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
                  }`}
              >
                {range.charAt(0).toUpperCase() + range.slice(1)}
              </button>
            ))}
          </div>
          <Link href="/admin/reports/scheduled">
            <Button variant="outline">
              <CalendarClock className="w-4 h-4 mr-2" />
              Scheduled
            </Button>
          </Link>
          <Button variant="outline" onClick={fetchReports}>
            <RefreshCw className="w-4 h-4 mr-2" />
            {tc('refresh')}
          </Button>
          <div className="relative">
            <Button onClick={() => setShowExportMenu(!showExportMenu)} disabled={exporting}>
              <Download className="w-4 h-4 mr-2" />
              {exporting ? tc('loading') : tc('export')}
            </Button>
            {showExportMenu && (
              <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-slate-800 rounded-lg shadow-lg border border-slate-200 dark:border-slate-700 z-10">
                {EXPORT_OPTIONS.map((opt) => (
                  <button
                    key={opt.value}
                    onClick={() => exportReport(opt.value)}
                    className="w-full text-left px-4 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 first:rounded-t-lg last:rounded-b-lg text-sm"
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div variants={fadeInUp}>
          <Card className="relative overflow-hidden">
            <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-green-500 to-emerald-500" />
            <CardContent className="p-6">
              <div className="flex items-start justify-between">
                <div>
                  <p className="text-sm text-slate-500 dark:text-slate-400">{t('totalRevenue')}</p>
                  <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                    {formatCurrency(data.overview.totalRevenue)}
                  </p>
                  <div className={`flex items-center gap-1 mt-2 text-sm ${data.overview.revenueChange >= 0 ? 'text-green-500' : 'text-red-500'
                    }`}>
                    {data.overview.revenueChange >= 0 ? (
                      <ArrowUpRight className="w-4 h-4" />
                    ) : (
                      <ArrowDownRight className="w-4 h-4" />
                    )}
                    {Math.abs(data.overview.revenueChange)}% vs last period
                  </div>
                </div>
                <div className="p-3 rounded-xl bg-green-100 dark:bg-green-900/30">
                  <DollarSign className="w-6 h-6 text-green-600 dark:text-green-400" />
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="relative overflow-hidden">
            <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-blue-500 to-indigo-500" />
            <CardContent className="p-6">
              <div className="flex items-start justify-between">
                <div>
                  <p className="text-sm text-slate-500 dark:text-slate-400">{t('totalOrders')}</p>
                  <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                    {data.overview.totalOrders}
                  </p>
                  <div className={`flex items-center gap-1 mt-2 text-sm ${data.overview.ordersChange >= 0 ? 'text-green-500' : 'text-red-500'
                    }`}>
                    {data.overview.ordersChange >= 0 ? (
                      <ArrowUpRight className="w-4 h-4" />
                    ) : (
                      <ArrowDownRight className="w-4 h-4" />
                    )}
                    {Math.abs(data.overview.ordersChange)}% vs last period
                  </div>
                </div>
                <div className="p-3 rounded-xl bg-blue-100 dark:bg-blue-900/30">
                  <BarChart3 className="w-6 h-6 text-blue-600 dark:text-blue-400" />
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="relative overflow-hidden">
            <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-purple-500 to-pink-500" />
            <CardContent className="p-6">
              <div className="flex items-start justify-between">
                <div>
                  <p className="text-sm text-slate-500 dark:text-slate-400">{t('totalBookings')}</p>
                  <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                    {data.overview.totalBookings}
                  </p>
                  <p className="text-sm text-slate-400 mt-2">{t('chaletBookings')} & {t('poolSessions')}</p>
                </div>
                <div className="p-3 rounded-xl bg-purple-100 dark:bg-purple-900/30">
                  <Calendar className="w-6 h-6 text-purple-600 dark:text-purple-400" />
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="relative overflow-hidden">
            <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-orange-500 to-red-500" />
            <CardContent className="p-6">
              <div className="flex items-start justify-between">
                <div>
                  <p className="text-sm text-slate-500 dark:text-slate-400">{t('totalUsers')}</p>
                  <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                    {data.overview.totalUsers}
                  </p>
                  <p className="text-sm text-slate-400 mt-2">{t('registeredAccounts')}</p>
                </div>
                <div className="p-3 rounded-xl bg-orange-100 dark:bg-orange-900/30">
                  <Users className="w-6 h-6 text-orange-600 dark:text-orange-400" />
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Occupancy & Retention */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Occupancy Card */}
        <motion.div variants={fadeInUp}>
          <Card>
            <CardHeader>
              <CardTitle>Unit Occupancy Rate</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-6">
                {occupancyData && (
                  <>
                    <div className="space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{t('chaletBookings')}</span>
                        <span className="text-sm font-semibold text-slate-900 dark:text-white">{occupancyData.chalets.occupancyRate}%</span>
                      </div>
                      <div className="h-4 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${occupancyData.chalets.occupancyRate}%` }}
                          className="h-full bg-gradient-to-r from-purple-500 to-indigo-500 rounded-full"
                        />
                      </div>
                      <p className="text-xs text-slate-500">{occupancyData.chalets.bookedNights} nights / {occupancyData.chalets.totalCapacity} total</p>
                    </div>

                    <div className="space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{t('poolSessions')}</span>
                        <span className="text-sm font-semibold text-slate-900 dark:text-white">{occupancyData.pool.occupancyRate}%</span>
                      </div>
                      <div className="h-4 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${occupancyData.pool.occupancyRate}%` }}
                          className="h-full bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full"
                        />
                      </div>
                      <p className="text-xs text-slate-500">{occupancyData.pool.ticketsSold} guests / {occupancyData.pool.totalCapacity} capacity</p>
                    </div>
                  </>
                )}
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Retention Card */}
        <motion.div variants={fadeInUp}>
          <Card>
            <CardHeader>
              <CardTitle>Customer Retention</CardTitle>
            </CardHeader>
            <CardContent>
              {customerData && (
                <div className="flex items-center gap-8 py-4">
                  <div className="relative w-32 h-32">
                    {/* Simplified donut chart using CSS */}
                    <div className="absolute inset-0 rounded-full border-[12px] border-slate-100 dark:border-slate-800" />
                    <div
                      className="absolute inset-0 rounded-full border-[12px] border-indigo-500 border-t-transparent border-l-transparent"
                      style={{ transform: `rotate(${45 + (customerData.customerRetention.newRatio * 3.6)}deg)` }}
                    />
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                      <span className="text-2xl font-bold">{customerData.customerRetention.newRatio}%</span>
                      <span className="text-[10px] text-slate-500 uppercase">New</span>
                    </div>
                  </div>
                  <div className="flex-1 space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-sm bg-indigo-500" />
                        <span className="text-sm text-slate-600 dark:text-slate-400">{t('newCustomers')}</span>
                      </div>
                      <span className="font-semibold">{customerData.customerRetention.new}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-sm bg-slate-200 dark:bg-slate-700" />
                        <span className="text-sm text-slate-600 dark:text-slate-400">Returning</span>
                      </div>
                      <span className="font-semibold">{customerData.customerRetention.returning}</span>
                    </div>
                    <div className="pt-2 border-t border-slate-100 dark:border-slate-800 flex justify-between items-center text-sm">
                      <span className="text-slate-500 font-medium">Total Active Users</span>
                      <span className="font-bold">{customerData.customerRetention.total}</span>
                    </div>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Revenue by Service */}
        <motion.div variants={fadeInUp}>
          <Card>
            <CardHeader>
              <CardTitle>Revenue by Service</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {[
                  { key: 'restaurant', label: 'Restaurant', icon: UtensilsCrossed, color: 'bg-blue-500' },
                  { key: 'snackBar', label: 'Snack Bar', icon: Cookie, color: 'bg-orange-500' },
                  { key: 'chalets', label: 'Chalets', icon: Home, color: 'bg-green-500' },
                  { key: 'pool', label: 'Pool', icon: Waves, color: 'bg-primary-500' },
                ].map((service) => {
                  const value = data.revenueByService[service.key as keyof typeof data.revenueByService];
                  const percentage = totalServiceRevenue > 0 ? (value / totalServiceRevenue) * 100 : 0;
                  const Icon = service.icon;

                  return (
                    <div key={service.key} className="space-y-2">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <Icon className="w-4 h-4 text-slate-500" />
                          <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                            {service.label}
                          </span>
                        </div>
                        <span className="text-sm font-semibold text-slate-900 dark:text-white">
                          {formatCurrency(value)}
                        </span>
                      </div>
                      <div className="h-2 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${percentage}%` }}
                          transition={{ duration: 0.8, ease: 'easeOut' }}
                          className={`h-full ${service.color} rounded-full`}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Monthly Revenue Chart */}
        <motion.div variants={fadeInUp}>
          <Card>
            <CardHeader>
              <CardTitle>Revenue Trend</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="h-64 flex items-end justify-between gap-2">
                {revenueByMonth.map((item, index) => {
                  const maxRevenue = revenueByMonth.length > 0 ? Math.max(...revenueByMonth.map((r) => r.revenue)) : 0;
                  const heightPercent = maxRevenue > 0 ? (item.revenue / maxRevenue) * 100 : 0;

                  return (
                    <div key={item.month} className="flex-1 flex flex-col items-center gap-2">
                      <motion.div
                        initial={{ height: 0 }}
                        animate={{ height: `${heightPercent}%` }}
                        transition={{ duration: 0.5, delay: index * 0.1 }}
                        className="w-full bg-gradient-to-t from-blue-500 to-blue-400 rounded-t-lg min-h-[4px] relative group"
                      >
                        <div className="absolute -top-8 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity bg-slate-900 text-white text-xs px-2 py-1 rounded whitespace-nowrap">
                          {formatCurrency(item.revenue)}
                        </div>
                      </motion.div>
                      <span className="text-xs text-slate-500 dark:text-slate-400">
                        {item.month}
                      </span>
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Top Items */}
      <motion.div variants={fadeInUp}>
        <Card>
          <CardHeader>
            <CardTitle>Top Selling Items</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-slate-200 dark:border-slate-700">
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-500 dark:text-slate-400">
                      Rank
                    </th>
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-500 dark:text-slate-400">
                      Item Name
                    </th>
                    <th className="text-right py-3 px-4 text-sm font-semibold text-slate-500 dark:text-slate-400">
                      Quantity Sold
                    </th>
                    <th className="text-right py-3 px-4 text-sm font-semibold text-slate-500 dark:text-slate-400">
                      Revenue
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {topItems.map((item, index) => (
                    <motion.tr
                      key={item.name}
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: index * 0.1 }}
                      className="border-b border-slate-100 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800/50"
                    >
                      <td className="py-3 px-4">
                        <span className={`inline-flex items-center justify-center w-6 h-6 rounded-full text-sm font-bold ${index === 0 ? 'bg-yellow-100 text-yellow-700' :
                          index === 1 ? 'bg-slate-100 text-slate-700' :
                            index === 2 ? 'bg-orange-100 text-orange-700' :
                              'bg-slate-50 text-slate-500'
                          }`}>
                          {index + 1}
                        </span>
                      </td>
                      <td className="py-3 px-4 font-medium text-slate-900 dark:text-white">
                        {item.name}
                      </td>
                      <td className="py-3 px-4 text-right text-slate-600 dark:text-slate-300">
                        {item.quantity}
                      </td>
                      <td className="py-3 px-4 text-right font-semibold text-slate-900 dark:text-white">
                        {formatCurrency(item.revenue)}
                      </td>
                    </motion.tr>
                  ))}
                </tbody>
              </table>
              {topItems.length === 0 && (
                <div className="text-center py-8 text-slate-500 dark:text-slate-400">
                  No sales data available yet
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>
      {/* Top Customers */}
      <motion.div variants={fadeInUp}>
        <Card>
          <CardHeader>
            <CardTitle>Top Customers</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-slate-200 dark:border-slate-700">
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-500 dark:text-slate-400">
                      Customer
                    </th>
                    <th className="text-right py-3 px-4 text-sm font-semibold text-slate-500 dark:text-slate-400">
                      Orders
                    </th>
                    <th className="text-right py-3 px-4 text-sm font-semibold text-slate-500 dark:text-slate-400">
                      Total Revenue
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {customerData?.topCustomers.map((customer, index) => (
                    <motion.tr
                      key={customer.id}
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: index * 0.1 }}
                      className="border-b border-slate-100 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800/50"
                    >
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-xs font-bold text-slate-500">
                            {customer.name.split(' ').map(n => n[0]).join('')}
                          </div>
                          <span className="font-medium text-slate-900 dark:text-white">{customer.name}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4 text-right text-slate-600 dark:text-slate-300">
                        {customer.count}
                      </td>
                      <td className="py-3 px-4 text-right font-semibold text-slate-900 dark:text-white">
                        {formatCurrency(customer.revenue)}
                      </td>
                    </motion.tr>
                  ))}
                </tbody>
              </table>
              {(!customerData || customerData.topCustomers.length === 0) && (
                <div className="text-center py-8 text-slate-500 dark:text-slate-400">
                  No customer data available yet
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>
    </motion.div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  Clock,
  Plus,
  Trash2,
  Edit2,
  Send,
  Mail,
  CalendarClock,
  FileText,
  CheckCircle,
  XCircle,
  X,
  Save,
  ArrowLeft,
  Loader2,
} from 'lucide-react';
import Link from 'next/link';

interface ScheduledReport {
  id: string;
  name: string;
  type: 'daily' | 'weekly' | 'monthly';
  report_type: string;
  recipients: string[];
  enabled: boolean;
  last_sent_at: string | null;
  next_run_at: string | null;
  created_at: string;
}

type ReportType = 'revenue' | 'occupancy' | 'orders' | 'customers' | 'overview';
type ScheduleType = 'daily' | 'weekly' | 'monthly';

const REPORT_TYPES: { value: ReportType; label: string; description: string }[] = [
  { value: 'overview', label: 'Overview', description: 'Complete business overview' },
  { value: 'revenue', label: 'Revenue', description: 'Revenue breakdown by service' },
  { value: 'occupancy', label: 'Occupancy', description: 'Chalet & pool utilization' },
  { value: 'orders', label: 'Orders', description: 'Order statistics and trends' },
  { value: 'customers', label: 'Customers', description: 'Customer analytics' },
];

const SCHEDULE_TYPES: { value: ScheduleType; label: string; icon: string }[] = [
  { value: 'daily', label: 'Daily', icon: '📅' },
  { value: 'weekly', label: 'Weekly', icon: '📆' },
  { value: 'monthly', label: 'Monthly', icon: '🗓️' },
];

export default function ScheduledReportsPage() {
  const t = useTranslations('adminReports');
  const tc = useTranslations('adminCommon');
  
  const [reports, setReports] = useState<ScheduledReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingReport, setEditingReport] = useState<ScheduledReport | null>(null);
  const [saving, setSaving] = useState(false);
  const [sendingId, setSendingId] = useState<string | null>(null);
  
  // Form state
  const [formData, setFormData] = useState({
    name: '',
    type: 'daily' as ScheduleType,
    reportType: 'overview' as ReportType,
    recipients: '',
    enabled: true,
  });

  const fetchReports = useCallback(async () => {
    try {
      const response = await api.get('/admin/reports/scheduled');
      const data = response.data?.data ?? response.data ?? [];
      setReports(Array.isArray(data) ? data : []);
    } catch (error) {
      toast.error('Failed to load scheduled reports');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchReports();
  }, [fetchReports]);

  const openCreateModal = () => {
    setEditingReport(null);
    setFormData({
      name: '',
      type: 'daily',
      reportType: 'overview',
      recipients: '',
      enabled: true,
    });
    setShowModal(true);
  };

  const openEditModal = (report: ScheduledReport) => {
    setEditingReport(report);
    setFormData({
      name: report.name,
      type: report.type,
      reportType: report.report_type as ReportType,
      recipients: report.recipients.join(', '),
      enabled: report.enabled,
    });
    setShowModal(true);
  };

  const handleSubmit = async () => {
    if (!formData.name.trim()) {
      toast.error('Please enter a report name');
      return;
    }
    
    const recipientsList = formData.recipients
      .split(',')
      .map(email => email.trim())
      .filter(email => email.includes('@'));
    
    if (recipientsList.length === 0) {
      toast.error('Please enter at least one valid email recipient');
      return;
    }
    
    setSaving(true);
    try {
      if (editingReport) {
        await api.put(`/admin/reports/scheduled/${editingReport.id}`, {
          name: formData.name,
          type: formData.type,
          reportType: formData.reportType,
          recipients: recipientsList,
          enabled: formData.enabled,
        });
        toast.success('Report updated successfully');
      } else {
        await api.post('/admin/reports/scheduled', {
          name: formData.name,
          type: formData.type,
          reportType: formData.reportType,
          recipients: recipientsList,
          enabled: formData.enabled,
        });
        toast.success('Report created successfully');
      }
      setShowModal(false);
      fetchReports();
    } catch (error) {
      toast.error(editingReport ? 'Failed to update report' : 'Failed to create report');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this scheduled report?')) {
      return;
    }
    
    try {
      await api.delete(`/admin/reports/scheduled/${id}`);
      toast.success('Report deleted');
      fetchReports();
    } catch (error) {
      toast.error('Failed to delete report');
    }
  };

  const handleToggleEnabled = async (report: ScheduledReport) => {
    try {
      await api.put(`/admin/reports/scheduled/${report.id}`, {
        enabled: !report.enabled,
      });
      toast.success(report.enabled ? 'Report disabled' : 'Report enabled');
      fetchReports();
    } catch (error) {
      toast.error('Failed to update report');
    }
  };

  const handleSendNow = async (id: string) => {
    setSendingId(id);
    try {
      await api.post(`/admin/reports/scheduled/${id}/send`);
      toast.success('Report sent successfully');
      fetchReports();
    } catch (error) {
      toast.error('Failed to send report');
    } finally {
      setSendingId(null);
    }
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'Never';
    return new Date(dateString).toLocaleString();
  };

  const getReportTypeInfo = (type: string) => {
    return REPORT_TYPES.find(rt => rt.value === type) || { label: type, description: '' };
  };

  if (loading) {
    return (
      <div className="p-8">
        <div className="animate-pulse space-y-4">
          <div className="h-8 bg-muted rounded w-1/4"></div>
          <div className="h-4 bg-muted rounded w-1/3"></div>
          <div className="h-48 bg-muted rounded"></div>
        </div>
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6 p-6 max-w-6xl mx-auto"
    >
      {/* Header */}
      <motion.div variants={fadeInUp} className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href="/admin/reports">
            <Button variant="ghost" size="icon">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <CalendarClock className="h-6 w-6 text-primary" />
              Scheduled Reports
            </h1>
            <p className="text-muted-foreground">
              Configure automated email reports sent on a schedule
            </p>
          </div>
        </div>
        <Button onClick={openCreateModal}>
          <Plus className="h-4 w-4 mr-2" />
          New Report
        </Button>
      </motion.div>

      {/* Reports List */}
      {reports.length === 0 ? (
        <motion.div variants={fadeInUp}>
          <Card className="p-12 text-center">
            <FileText className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">No Scheduled Reports</h3>
            <p className="text-muted-foreground mb-6">
              Create your first scheduled report to automatically receive business insights via email.
            </p>
            <Button onClick={openCreateModal}>
              <Plus className="h-4 w-4 mr-2" />
              Create Your First Report
            </Button>
          </Card>
        </motion.div>
      ) : (
        <motion.div variants={fadeInUp} className="grid gap-4">
          {reports.map((report) => {
            const typeInfo = getReportTypeInfo(report.report_type);
            
            return (
              <Card key={report.id} className={`transition-opacity ${!report.enabled ? 'opacity-60' : ''}`}>
                <CardContent className="p-6">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <h3 className="text-lg font-semibold">{report.name}</h3>
                        {report.enabled ? (
                          <span className="inline-flex items-center gap-1 text-xs font-medium text-green-600 bg-green-100 px-2 py-0.5 rounded-full">
                            <CheckCircle className="h-3 w-3" /> Active
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 text-xs font-medium text-muted-foreground bg-muted px-2 py-0.5 rounded-full">
                            <XCircle className="h-3 w-3" /> Disabled
                          </span>
                        )}
                      </div>
                      
                      <div className="flex flex-wrap gap-4 text-sm text-muted-foreground mb-4">
                        <span className="inline-flex items-center gap-1">
                          <Clock className="h-4 w-4" />
                          {SCHEDULE_TYPES.find(st => st.value === report.type)?.icon} {report.type}
                        </span>
                        <span className="inline-flex items-center gap-1">
                          <FileText className="h-4 w-4" />
                          {typeInfo.label}
                        </span>
                        <span className="inline-flex items-center gap-1">
                          <Mail className="h-4 w-4" />
                          {report.recipients.length} recipient{report.recipients.length !== 1 ? 's' : ''}
                        </span>
                      </div>
                      
                      <div className="flex gap-6 text-xs text-muted-foreground">
                        <span>
                          <strong>Last sent:</strong> {formatDate(report.last_sent_at)}
                        </span>
                        <span>
                          <strong>Next run:</strong> {formatDate(report.next_run_at)}
                        </span>
                      </div>
                    </div>
                    
                    <div className="flex items-center gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleSendNow(report.id)}
                        disabled={sendingId === report.id}
                      >
                        {sendingId === report.id ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          <>
                            <Send className="h-4 w-4 mr-1" />
                            Send Now
                          </>
                        )}
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleToggleEnabled(report)}
                      >
                        {report.enabled ? (
                          <XCircle className="h-4 w-4 text-muted-foreground" />
                        ) : (
                          <CheckCircle className="h-4 w-4 text-green-600" />
                        )}
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => openEditModal(report)}
                      >
                        <Edit2 className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleDelete(report.id)}
                      >
                        <Trash2 className="h-4 w-4 text-destructive" />
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </motion.div>
      )}

      {/* Create/Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]">
          <Card className="w-full max-w-lg mx-4">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="flex items-center gap-2">
                  <CalendarClock className="h-5 w-5" />
                  {editingReport ? 'Edit Report' : 'New Scheduled Report'}
                </CardTitle>
                <Button variant="ghost" size="icon" onClick={() => setShowModal(false)}>
                  <X className="h-4 w-4" />
                </Button>
              </div>
              <CardDescription>
                Configure when and what report to send automatically.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {/* Report Name */}
              <div>
                <label className="text-sm font-medium mb-1 block">Report Name</label>
                <input
                  type="text"
                  className="w-full border rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                  placeholder="e.g., Weekly Revenue Summary"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>
              
              {/* Schedule Type */}
              <div>
                <label className="text-sm font-medium mb-2 block">Schedule</label>
                <div className="grid grid-cols-3 gap-2">
                  {SCHEDULE_TYPES.map((st) => (
                    <button
                      key={st.value}
                      type="button"
                      onClick={() => setFormData({ ...formData, type: st.value })}
                      className={`p-3 rounded-lg border text-center transition-colors ${
                        formData.type === st.value
                          ? 'border-primary bg-primary/5 text-primary'
                          : 'hover:bg-muted/50'
                      }`}
                    >
                      <div className="text-xl mb-1">{st.icon}</div>
                      <div className="text-sm font-medium">{st.label}</div>
                    </button>
                  ))}
                </div>
              </div>
              
              {/* Report Type */}
              <div>
                <label className="text-sm font-medium mb-2 block">Report Type</label>
                <div className="space-y-2">
                  {REPORT_TYPES.map((rt) => (
                    <label
                      key={rt.value}
                      className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                        formData.reportType === rt.value
                          ? 'border-primary bg-primary/5'
                          : 'hover:bg-muted/50'
                      }`}
                    >
                      <input
                        type="radio"
                        name="reportType"
                        checked={formData.reportType === rt.value}
                        onChange={() => setFormData({ ...formData, reportType: rt.value })}
                        className="w-4 h-4"
                      />
                      <div>
                        <div className="font-medium text-sm">{rt.label}</div>
                        <div className="text-xs text-muted-foreground">{rt.description}</div>
                      </div>
                    </label>
                  ))}
                </div>
              </div>
              
              {/* Recipients */}
              <div>
                <label className="text-sm font-medium mb-1 block">Recipients</label>
                <textarea
                  className="w-full border rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary resize-none"
                  placeholder="email@example.com, another@example.com"
                  rows={2}
                  value={formData.recipients}
                  onChange={(e) => setFormData({ ...formData, recipients: e.target.value })}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Separate multiple email addresses with commas
                </p>
              </div>
              
              {/* Enabled Toggle */}
              <div className="flex items-center justify-between py-2">
                <label className="text-sm font-medium">Enabled</label>
                <button
                  type="button"
                  onClick={() => setFormData({ ...formData, enabled: !formData.enabled })}
                  className={`relative w-12 h-6 rounded-full transition-colors ${
                    formData.enabled ? 'bg-green-500' : 'bg-gray-300'
                  }`}
                >
                  <span
                    className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${
                      formData.enabled ? 'translate-x-7' : 'translate-x-1'
                    }`}
                  />
                </button>
              </div>
              
              {/* Actions */}
              <div className="flex gap-2 pt-4">
                <Button variant="outline" onClick={() => setShowModal(false)} className="flex-1">
                  Cancel
                </Button>
                <Button onClick={handleSubmit} disabled={saving} className="flex-1">
                  {saving ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <>
                      <Save className="h-4 w-4 mr-2" />
                      {editingReport ? 'Save Changes' : 'Create Report'}
                    </>
                  )}
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}
    </motion.div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { api } from '@/lib/api';
import { formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { CardSkeleton } from '@/components/ui/Skeleton';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  Star,
  Search,
  RefreshCw,
  CheckCircle2,
  XCircle,
  Trash2,
  MessageSquare,
  UtensilsCrossed,
  Home,
  Waves,
  Cookie,
  HelpCircle,
  Filter,
  ThumbsUp,
  ThumbsDown,
} from 'lucide-react';

interface Review {
  id: string;
  rating: number;
  text: string;
  service_type: 'general' | 'restaurant' | 'chalets' | 'pool' | 'snack_bar';
  is_approved: boolean;
  created_at: string;
  users?: {
    id: string;
    full_name: string;
    email: string;
    profile_image_url?: string;
  };
}

const serviceConfig: Record<string, { icon: React.ElementType; color: string }> = {
  general: { icon: HelpCircle, color: 'text-slate-500' },
  restaurant: { icon: UtensilsCrossed, color: 'text-blue-500' },
  chalets: { icon: Home, color: 'text-green-500' },
  pool: { icon: Waves, color: 'text-primary-500' },
  snack_bar: { icon: Cookie, color: 'text-orange-500' },
};

export default function AdminReviewsPage() {
  const t = useTranslations('admin');
  const [reviews, setReviews] = useState<Review[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'pending' | 'approved'>('all');
  const [serviceFilter, setServiceFilter] = useState<string>('all');
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const fetchReviews = useCallback(async () => {
    try {
      setLoading(true);
      const response = await api.get('/reviews/admin');
      setReviews(response.data.data || []);
    } catch (error) {
      toast.error('Failed to fetch reviews');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchReviews();
  }, [fetchReviews]);

  const approveReview = async (id: string) => {
    try {
      setActionLoading(id);
      await api.put(`/reviews/${id}/approve`);
      setReviews((prev) =>
        prev.map((r) => (r.id === id ? { ...r, is_approved: true } : r))
      );
      toast.success('Review approved');
    } catch (error) {
      toast.error('Failed to approve review');
    } finally {
      setActionLoading(null);
    }
  };

  const rejectReview = async (id: string) => {
    try {
      setActionLoading(id);
      await api.put(`/reviews/${id}/reject`);
      setReviews((prev) =>
        prev.map((r) => (r.id === id ? { ...r, is_approved: false } : r))
      );
      toast.success('Review rejected');
    } catch (error) {
      toast.error('Failed to reject review');
    } finally {
      setActionLoading(null);
    }
  };

  const deleteReview = async (id: string) => {
    if (!confirm('Are you sure you want to delete this review?')) return;
    
    try {
      setActionLoading(id);
      await api.delete(`/reviews/${id}`);
      setReviews((prev) => prev.filter((r) => r.id !== id));
      toast.success('Review deleted');
    } catch (error) {
      toast.error('Failed to delete review');
    } finally {
      setActionLoading(null);
    }
  };

  const filteredReviews = reviews.filter((r) => {
    if (statusFilter === 'pending' && r.is_approved) return false;
    if (statusFilter === 'approved' && !r.is_approved) return false;
    if (serviceFilter !== 'all' && r.service_type !== serviceFilter) return false;
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      return (
        (r.text || '').toLowerCase().includes(query) ||
        r.users?.full_name?.toLowerCase().includes(query) ||
        r.users?.email?.toLowerCase().includes(query)
      );
    }
    return true;
  });

  const pendingCount = reviews.filter((r) => !r.is_approved).length;
  const approvedCount = reviews.filter((r) => r.is_approved).length;
  const averageRating = reviews.length > 0
    ? (reviews.reduce((sum, r) => sum + r.rating, 0) / reviews.length).toFixed(1)
    : '0.0';

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {[...Array(3)].map((_, i) => (
            <CardSkeleton key={i} />
          ))}
        </div>
        <CardSkeleton />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
            Reviews
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            Manage customer reviews and feedback
          </p>
        </div>
        <Button variant="outline" onClick={fetchReviews}>
          <RefreshCw className="w-4 h-4 mr-2" />
          Refresh
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-yellow-500 to-amber-500 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-yellow-100 text-sm">Average Rating</p>
                  <div className="flex items-center gap-2 mt-1">
                    <p className="text-3xl font-bold">{averageRating}</p>
                    <Star className="w-6 h-6 fill-current" />
                  </div>
                </div>
                <div className="flex">
                  {[1, 2, 3, 4, 5].map((star) => (
                    <Star
                      key={star}
                      className={`w-5 h-5 ${
                        star <= Math.round(parseFloat(averageRating))
                          ? 'fill-white text-white'
                          : 'text-yellow-200'
                      }`}
                    />
                  ))}
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-orange-500 to-orange-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-orange-100 text-sm">Pending Reviews</p>
                  <p className="text-3xl font-bold mt-1">{pendingCount}</p>
                </div>
                <MessageSquare className="w-10 h-10 text-orange-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-green-100 text-sm">Approved Reviews</p>
                  <p className="text-3xl font-bold mt-1">{approvedCount}</p>
                </div>
                <CheckCircle2 className="w-10 h-10 text-green-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="p-4">
          <div className="flex flex-col md:flex-row gap-4">
            {/* Search */}
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Search reviews..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>

            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as typeof statusFilter)}
              className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
            >
              <option value="all">All Status</option>
              <option value="pending">Pending</option>
              <option value="approved">Approved</option>
            </select>

            {/* Service Filter */}
            <select
              value={serviceFilter}
              onChange={(e) => setServiceFilter(e.target.value)}
              className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
            >
              <option value="all">All Services</option>
              <option value="general">General</option>
              <option value="restaurant">Restaurant</option>
              <option value="chalets">Chalets</option>
              <option value="pool">Pool</option>
              <option value="snack_bar">Snack Bar</option>
            </select>
          </div>
        </CardContent>
      </Card>

      {/* Reviews List */}
      <div className="space-y-4">
        <AnimatePresence mode="popLayout">
          {filteredReviews.length === 0 ? (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="text-center py-12"
            >
              <MessageSquare className="w-12 h-12 mx-auto text-slate-300 dark:text-slate-600 mb-4" />
              <p className="text-slate-500 dark:text-slate-400">No reviews found</p>
            </motion.div>
          ) : (
            filteredReviews.map((review, index) => {
              const ServiceIcon = serviceConfig[review.service_type]?.icon || HelpCircle;
              const serviceColor = serviceConfig[review.service_type]?.color || 'text-slate-500';

              return (
                <motion.div
                  key={review.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, x: -100 }}
                  transition={{ delay: index * 0.05 }}
                  layout
                >
                  <Card className={`${!review.is_approved ? 'border-l-4 border-l-orange-500' : ''}`}>
                    <CardContent className="p-6">
                      <div className="flex flex-col md:flex-row md:items-start gap-4">
                        {/* User Avatar */}
                        <div className="flex-shrink-0">
                          {review.users?.profile_image_url ? (
                            <img
                              src={review.users.profile_image_url}
                              alt={review.users.full_name}
                              className="w-12 h-12 rounded-full object-cover"
                            />
                          ) : (
                            <div className="w-12 h-12 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center">
                              <span className="text-lg font-semibold text-slate-600 dark:text-slate-300">
                                {review.users?.full_name?.charAt(0) || 'G'}
                              </span>
                            </div>
                          )}
                        </div>

                        {/* Review Content */}
                        <div className="flex-1 min-w-0">
                          <div className="flex flex-wrap items-center gap-2 mb-2">
                            <span className="font-semibold text-slate-900 dark:text-white">
                              {review.users?.full_name || 'Anonymous'}
                            </span>
                            <span className="text-sm text-slate-500 dark:text-slate-400">
                              {review.users?.email}
                            </span>
                            <span className={`flex items-center gap-1 text-sm ${serviceColor}`}>
                              <ServiceIcon className="w-4 h-4" />
                              {(review.service_type || 'general').replace('_', ' ')}
                            </span>
                          </div>

                          {/* Rating */}
                          <div className="flex items-center gap-1 mb-2">
                            {[1, 2, 3, 4, 5].map((star) => (
                              <Star
                                key={star}
                                className={`w-4 h-4 ${
                                  star <= review.rating
                                    ? 'fill-yellow-400 text-yellow-400'
                                    : 'text-slate-300 dark:text-slate-600'
                                }`}
                              />
                            ))}
                            <span className="ml-2 text-sm text-slate-500 dark:text-slate-400">
                              {formatDate(review.created_at)}
                            </span>
                          </div>

                          {/* Review Text */}
                          <p className="text-slate-700 dark:text-slate-300">
                            {review.text}
                          </p>

                          {/* Status Badge */}
                          <div className="mt-3">
                            <span
                              className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                review.is_approved
                                  ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400'
                                  : 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400'
                              }`}
                            >
                              {review.is_approved ? (
                                <>
                                  <CheckCircle2 className="w-3 h-3" />
                                  Approved
                                </>
                              ) : (
                                <>
                                  <MessageSquare className="w-3 h-3" />
                                  Pending Approval
                                </>
                              )}
                            </span>
                          </div>
                        </div>

                        {/* Actions */}
                        <div className="flex items-center gap-2">
                          {!review.is_approved && (
                            <Button
                              size="sm"
                              onClick={() => approveReview(review.id)}
                              disabled={actionLoading === review.id}
                            >
                              <ThumbsUp className="w-4 h-4 mr-1" />
                              Approve
                            </Button>
                          )}
                          {review.is_approved && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => rejectReview(review.id)}
                              disabled={actionLoading === review.id}
                            >
                              <ThumbsDown className="w-4 h-4 mr-1" />
                              Revoke
                            </Button>
                          )}
                          <Button
                            variant="danger"
                            size="sm"
                            onClick={() => deleteReview(review.id)}
                            disabled={actionLoading === review.id}
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </motion.div>
              );
            })
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { useSiteSettings } from '@/lib/settings-context';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import { resortThemes, ResortTheme } from '@/lib/theme-config';
import {
  Palette,
  Volume2,
  VolumeX,
  Monitor,
  Smartphone,
  Save,
  RotateCcw,
  Zap,
  Sun,
  Cloud,
  CloudRain,
  Snowflake,
  Check,
  CloudSun,
} from 'lucide-react';

// Weather effect selector
function WeatherOption({
  effect,
  icon: Icon,
  label,
  isSelected,
  onSelect,
}: {
  effect: string;
  icon: React.ElementType;
  label: string;
  isSelected: boolean;
  onSelect: () => void;
}) {
  return (
    <motion.button
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.95 }}
      onClick={onSelect}
      className={`flex flex-col items-center gap-2 p-4 rounded-xl border-2 transition-all ${
        isSelected
          ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300'
          : 'border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600 text-slate-600 dark:text-slate-400'
      }`}
    >
      <Icon className={`w-8 h-8 ${isSelected ? 'text-primary-500' : 'text-slate-400'}`} />
      <span className="text-sm font-medium">{label}</span>
    </motion.button>
  );
}

// Toggle switch component
function ToggleSwitch({
  enabled,
  onChange,
  label,
  description,
}: {
  enabled: boolean;
  onChange: (value: boolean) => void;
  label: string;
  description?: string;
}) {
  return (
    <div className="flex items-center justify-between py-4">
      <div>
        <p className="font-medium text-slate-900 dark:text-white">{label}</p>
        {description && <p className="text-sm text-slate-500 dark:text-slate-400">{description}</p>}
      </div>
      <button
        onClick={() => onChange(!enabled)}
        className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
          enabled ? 'bg-primary-600' : 'bg-slate-200 dark:bg-slate-700'
        }`}
      >
        <span
          className={`inline-block h-4 w-4 transform rounded-full bg-white shadow-lg transition-transform ${
            enabled ? 'translate-x-6' : 'translate-x-1'
          }`}
        />
      </button>
    </div>
  );
}

// Color picker component
function ColorPicker({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <div className="flex items-center justify-between py-3">
      <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{label}</span>
      <div className="flex items-center gap-2">
        <input
          type="color"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-10 h-10 rounded-lg cursor-pointer border-2 border-slate-200 dark:border-slate-700"
        />
        <input
          type="text"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-24 px-2 py-1 text-sm rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
        />
      </div>
    </div>
  );
}

export default function AppearanceSettingsPage() {
  const t = useTranslations('adminSettings');
  const tc = useTranslations('adminCommon');
  const { settings, refetch, loading } = useSiteSettings();
  
  // Theme state
  const [selectedTheme, setSelectedTheme] = useState<ResortTheme>(settings.theme || 'beach');
  const [useCustomColors, setUseCustomColors] = useState(!!settings.themeColors);
  const [customColors, setCustomColors] = useState({
    primary: settings.themeColors?.primary || '#0891b2',
    secondary: settings.themeColors?.secondary || '#06b6d4',
    accent: settings.themeColors?.accent || '#f59e0b',
    background: settings.themeColors?.background || '#f0fdfa',
    surface: settings.themeColors?.surface || '#ffffff',
    text: settings.themeColors?.text || '#164e63',
    textMuted: settings.themeColors?.textMuted || '#0e7490',
  });
  
  // Weather widget state
  const [showWeatherWidget, setShowWeatherWidget] = useState(settings.showWeatherWidget ?? true);
  const [weatherLocation, setWeatherLocation] = useState(settings.weatherLocation || 'New York, USA');
  const [weatherEffect, setWeatherEffect] = useState<string>(settings.weatherEffect || 'auto');
  
  // Animation state
  const [animationsEnabled, setAnimationsEnabled] = useState(settings.animationsEnabled ?? true);
  const [reducedMotion, setReducedMotion] = useState(settings.reducedMotion ?? false);
  const [soundEnabled, setSoundEnabled] = useState(settings.soundEnabled ?? true);
  
  const [hasChanges, setHasChanges] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [initialized, setInitialized] = useState(false);

  // Sync state when settings load from API (fixes settings not showing after page load)
  useEffect(() => {
    if (!loading && !initialized) {
      setSelectedTheme(settings.theme || 'beach');
      setUseCustomColors(!!settings.themeColors);
      if (settings.themeColors) {
        setCustomColors({
          primary: settings.themeColors.primary || '#0891b2',
          secondary: settings.themeColors.secondary || '#06b6d4',
          accent: settings.themeColors.accent || '#f59e0b',
          background: settings.themeColors.background || '#f0fdfa',
          surface: settings.themeColors.surface || '#ffffff',
          text: settings.themeColors.text || '#164e63',
          textMuted: settings.themeColors.textMuted || '#0e7490',
        });
      }
      setShowWeatherWidget(settings.showWeatherWidget ?? true);
      setWeatherLocation(settings.weatherLocation || 'New York, USA');
      setWeatherEffect(settings.weatherEffect || 'auto');
      setAnimationsEnabled(settings.animationsEnabled ?? true);
      setReducedMotion(settings.reducedMotion ?? false);
      setSoundEnabled(settings.soundEnabled ?? true);
      setInitialized(true);
    }
  }, [loading, settings, initialized]);

  // Update custom colors when theme changes
  useEffect(() => {
    if (!useCustomColors && selectedTheme) {
      const theme = resortThemes[selectedTheme];
      if (theme) {
        setCustomColors(theme.colors);
      }
    }
  }, [selectedTheme, useCustomColors]);

  const handleSave = async () => {
    try {
      setIsSaving(true);
      const newSettings = {
        ...settings,
        theme: selectedTheme,
        themeColors: useCustomColors ? customColors : null,
        showWeatherWidget,
        weatherLocation,
        weatherEffect,
        animationsEnabled,
        reducedMotion,
        soundEnabled
      };
      await api.put('/admin/settings', newSettings);
      await refetch();
      setHasChanges(false);
      toast.success(t('appearance.saved'));
    } catch (error) {
      console.error('Failed to save settings:', error);
      toast.error(tc('errors.failedToSave'));
    } finally {
      setIsSaving(false);
    }
  };

  const handleReset = () => {
    setSelectedTheme('beach');
    setUseCustomColors(false);
    setCustomColors(resortThemes.beach.colors);
    setShowWeatherWidget(true);
    setWeatherLocation('New York, USA');
    setWeatherEffect('auto');
    setAnimationsEnabled(true);
    setReducedMotion(false);
    setSoundEnabled(true);
    setHasChanges(true);
    toast.info('Settings reset to defaults');
  };

  const markChanged = () => setHasChanges(true);

  return (
    <motion.div
      initial="hidden"
      animate="visible"
      variants={staggerContainer}
      className="space-y-8"
    >
      <motion.div variants={fadeInUp} className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            <Palette className="w-8 h-8 text-primary-600" />
            {t('appearance.title')}
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">
            {t('appearance.subtitle')}
          </p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={handleReset}>
            <RotateCcw className="w-4 h-4 mr-2" />
            Reset
          </Button>
          <Button onClick={handleSave} isLoading={isSaving} disabled={!hasChanges}>
            <Save className="w-4 h-4 mr-2" />
            {tc('saveChanges')}
          </Button>
        </div>
      </motion.div>

      {/* Theme Selection */}
      <motion.div variants={fadeInUp}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Palette className="w-5 h-5 text-primary-600" />
              Resort Theme
            </CardTitle>
            <CardDescription>
              Choose a preset theme or customize colors for your resort
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4 mb-6">
              {Object.values(resortThemes).map((theme) => (
                <motion.button
                  key={theme.id}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => {
                    setSelectedTheme(theme.id);
                    markChanged();
                  }}
                  className={`relative p-4 rounded-xl border-2 transition-all ${
                    selectedTheme === theme.id
                      ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                      : 'border-slate-200 dark:border-slate-700 hover:border-slate-300'
                  }`}
                >
                  {selectedTheme === theme.id && (
                    <div className="absolute top-2 right-2 w-5 h-5 bg-primary-500 rounded-full flex items-center justify-center">
                      <Check className="w-3 h-3 text-white" />
                    </div>
                  )}
                  <div className={`w-full h-12 rounded-lg mb-3 ${theme.gradient}`} />
                  <span className="text-2xl mb-1 block">{theme.icon}</span>
                  <p className="font-medium text-sm text-slate-900 dark:text-white">{theme.name}</p>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{theme.description}</p>
                </motion.button>
              ))}
            </div>
            
            {/* Custom Colors Toggle */}
            <div className="border-t border-slate-200 dark:border-slate-700 pt-4">
              <ToggleSwitch
                enabled={useCustomColors}
                onChange={(value) => {
                  setUseCustomColors(value);
                  markChanged();
                }}
                label="Use Custom Colors"
                description="Override theme colors with your own custom palette"
              />
              
              {useCustomColors && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-lg"
                >
                  <ColorPicker
                    label="Primary Color"
                    value={customColors.primary}
                    onChange={(v) => { setCustomColors({...customColors, primary: v}); markChanged(); }}
                  />
                  <ColorPicker
                    label="Secondary Color"
                    value={customColors.secondary}
                    onChange={(v) => { setCustomColors({...customColors, secondary: v}); markChanged(); }}
                  />
                  <ColorPicker
                    label="Accent Color"
                    value={customColors.accent}
                    onChange={(v) => { setCustomColors({...customColors, accent: v}); markChanged(); }}
                  />
                  <ColorPicker
                    label="Background"
                    value={customColors.background}
                    onChange={(v) => { setCustomColors({...customColors, background: v}); markChanged(); }}
                  />
                  <ColorPicker
                    label="Surface Color"
                    value={customColors.surface}
                    onChange={(v) => { setCustomColors({...customColors, surface: v}); markChanged(); }}
                  />
                  <ColorPicker
                    label="Text Color"
                    value={customColors.text}
                    onChange={(v) => { setCustomColors({...customColors, text: v}); markChanged(); }}
                  />
                  <ColorPicker
                    label="Muted Text"
                    value={customColors.textMuted}
                    onChange={(v) => { setCustomColors({...customColors, textMuted: v}); markChanged(); }}
                  />
                </motion.div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Weather Widget Settings */}
      <motion.div variants={fadeInUp}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Sun className="w-5 h-5 text-primary-600" />
              Weather Widget
            </CardTitle>
            <CardDescription>
              Display real-time weather information for guests
            </CardDescription>
          </CardHeader>
          <CardContent>
            <ToggleSwitch
              enabled={showWeatherWidget}
              onChange={(value) => {
                setShowWeatherWidget(value);
                markChanged();
              }}
              label="Show Weather Widget"
              description="Display current weather conditions on the homepage"
            />
            
            {showWeatherWidget && (
              <div className="mt-4 space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                    Weather Location
                  </label>
                  <input
                    type="text"
                    value={weatherLocation}
                    onChange={(e) => { setWeatherLocation(e.target.value); markChanged(); }}
                    placeholder="e.g., New York, USA"
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                  />
                  <p className="text-xs text-slate-500 mt-1">
                    Enter the city and country for weather data
                  </p>
                </div>
                
                {/* Weather Animation Effect Selector - Visual Grid */}
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                    Weather Animation Effect
                  </label>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-2">
                    <WeatherOption
                      effect="sunny"
                      icon={Sun}
                      label="Sunny"
                      isSelected={weatherEffect === 'sunny'}
                      onSelect={() => { setWeatherEffect('sunny'); markChanged(); }}
                    />
                    <WeatherOption
                      effect="clouds"
                      icon={CloudSun}
                      label="Cloudy"
                      isSelected={weatherEffect === 'clouds'}
                      onSelect={() => { setWeatherEffect('clouds'); markChanged(); }}
                    />
                    <WeatherOption
                      effect="rain"
                      icon={CloudRain}
                      label="Rainy"
                      isSelected={weatherEffect === 'rain'}
                      onSelect={() => { setWeatherEffect('rain'); markChanged(); }}
                    />
                    <WeatherOption
                      effect="snow"
                      icon={Snowflake}
                      label="Snowy"
                      isSelected={weatherEffect === 'snow'}
                      onSelect={() => { setWeatherEffect('snow'); markChanged(); }}
                    />
                    {/* Add more options as needed or keep simple */}
                  </div>
                  
                  {/* Additional detailed selector for more obscure effects if needed */}
                  <div className="mt-2">
                     <label className="text-xs text-slate-500 mb-1 block">More Effects:</label>
                     <select
                        value={weatherEffect}
                        onChange={(e) => { setWeatherEffect(e.target.value); markChanged(); }}
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                      >
                        <option value="auto">🎨 Auto (Based on theme)</option>
                        <option value="sunny">☀️ Sunny (Clear)</option>
                        <option value="clouds">☁️ Cloudy</option>
                        <option value="waves">🌊 Waves (Animated ocean waves)</option>
                        <option value="snow">❄️ Snow (Falling snowflakes)</option>
                        <option value="rain">🌧️ Rain (Rain drops)</option>
                        <option value="leaves">🍂 Leaves (Falling autumn leaves)</option>
                        <option value="stars">✨ Stars (Twinkling night sky)</option>
                        <option value="fireflies">🌟 Fireflies (Glowing particles)</option>
                        <option value="none">🚫 None (Disable animations)</option>
                      </select>
                  </div>

                  <p className="text-xs text-slate-500 mt-2">
                    Choose the ambient animation effect displayed on the site.
                  </p>
                </div>
              </div>
            )}
            
            {/* Weather Preview */}
            <div className="mt-6 p-4 bg-gradient-to-br from-blue-500 to-cyan-500 rounded-xl text-white">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm opacity-80">{weatherLocation}</p>
                  <p className="text-4xl font-bold">24°C</p>
                  <p className="text-sm opacity-80">Partly Cloudy</p>
                </div>
                <div className="text-6xl">
                  <Cloud className="w-16 h-16" />
                </div>
              </div>
              <p className="text-xs mt-2 opacity-60">Preview - Actual weather will be fetched from API</p>
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Animation & Performance */}
      <motion.div variants={fadeInUp}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Zap className="w-5 h-5 text-primary-600" />
              Animations & Performance
            </CardTitle>
            <CardDescription>
              Control animation behavior and performance settings
            </CardDescription>
          </CardHeader>
          <CardContent className="divide-y divide-slate-100">
            <ToggleSwitch
              enabled={animationsEnabled}
              onChange={(value) => {
                setAnimationsEnabled(value);
                setHasChanges(true);
              }}
              label="Enable Animations"
              description="Show smooth transitions and micro-interactions throughout the site"
            />
            <ToggleSwitch
              enabled={reducedMotion}
              onChange={(value) => {
                setReducedMotion(value);
                setHasChanges(true);
              }}
              label="Reduced Motion"
              description="Minimize animations for users who prefer less motion"
            />
            <ToggleSwitch
              enabled={soundEnabled}
              onChange={(value) => {
                setSoundEnabled(value);
                setHasChanges(true);
              }}
              label="Sound Effects"
              description="Play notification sounds for new orders and events"
            />
          </CardContent>
        </Card>
      </motion.div>

      {/* Device Preview (static, not theme-dependent) */}
      <motion.div variants={fadeInUp}>
        <Card variant="glass">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Monitor className="w-5 h-5 text-primary-600" />
              Device Preview
            </CardTitle>
            <CardDescription>
              See how your site looks across different devices
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex justify-center gap-8">
              {/* Desktop Preview */}
              <div className="text-center">
                <div className="w-64 h-40 rounded-lg bg-gradient-to-br from-green-400 via-blue-400 to-purple-500 border-4 border-slate-800 shadow-xl relative overflow-hidden">
                  <div className="absolute top-0 left-0 right-0 h-6 bg-slate-800 flex items-center px-2 gap-1">
                    <div className="w-2 h-2 rounded-full bg-red-500" />
                    <div className="w-2 h-2 rounded-full bg-yellow-500" />
                    <div className="w-2 h-2 rounded-full bg-green-500" />
                  </div>
                  <div className="absolute top-8 left-2 right-2 bottom-2 bg-white/80 rounded flex items-center justify-center">
                    <span className="text-4xl">🏝️</span>
                  </div>
                </div>
                <div className="flex items-center justify-center gap-2 mt-3 text-slate-600">
                  <Monitor className="w-4 h-4" />
                  <span className="text-sm">Desktop</span>
                </div>
              </div>

              {/* Mobile Preview */}
              <div className="text-center">
                <div className="w-24 h-44 rounded-2xl bg-gradient-to-br from-green-400 via-blue-400 to-purple-500 border-4 border-slate-800 shadow-xl relative overflow-hidden">
                  <div className="absolute top-2 left-1/2 -translate-x-1/2 w-12 h-1 bg-slate-800 rounded-full" />
                  <div className="absolute top-5 left-2 right-2 bottom-4 bg-white/80 rounded flex items-center justify-center">
                    <span className="text-2xl">🏝️</span>
                  </div>
                </div>
                <div className="flex items-center justify-center gap-2 mt-3 text-slate-600">
                  <Smartphone className="w-4 h-4" />
                  <span className="text-sm">Mobile</span>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </motion.div>
    </motion.div>
  );
}

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useTranslations } from 'next-intl';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Database,
    Download,
    Trash2,
    Plus,
    FileJson,
    Clock,
    User,
    AlertTriangle,
    RefreshCcw,
    CheckCircle2,
    XCircle,
    Loader2,
    HardDrive,
    Upload,
    RotateCcw,
    Shield
} from 'lucide-react';
import { api } from '@/lib/api';
import { Button } from '@/components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/Card';
import { toast } from 'sonner';

interface Backup {
    id: string;
    filename: string;
    size_bytes: number;
    status: 'pending' | 'completed' | 'failed';
    type: 'manual' | 'scheduled';
    created_at: string;
    users?: {
        full_name: string;
    };
}

const fadeInUp = {
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0 },
    transition: { duration: 0.4 }
};

export default function BackupsPage() {
    const t = useTranslations('adminSettings');
    const tc = useTranslations('adminCommon');
    const [backups, setBackups] = useState<Backup[]>([]);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);
    const [downloading, setDownloading] = useState<string | null>(null);
    const [restoring, setRestoring] = useState(false);
    const [showRestoreConfirm, setShowRestoreConfirm] = useState(false);
    const [pendingRestoreData, setPendingRestoreData] = useState<Record<string, unknown> | null>(null);
    const [pendingRestoreFilename, setPendingRestoreFilename] = useState<string>('');
    const fileInputRef = useRef<HTMLInputElement>(null);

    const fetchBackups = useCallback(async () => {
        try {
            setLoading(true);
            const response = await api.get('/admin/backups');
            if (response.data.success) {
                setBackups(response.data.data);
            }
        } catch (error) {
            console.error('Failed to fetch backups:', error);
            toast.error(tc('errors.failedToLoad'));
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchBackups();
    }, [fetchBackups]);

    const handleCreateBackup = async () => {
        try {
            setCreating(true);
            toast.loading('Initializing database snapshot...', { id: 'backup-create' });

            const response = await api.post('/admin/backups');

            if (response.data.success) {
                toast.success(`Backup created: ${response.data.data.filename}`, { id: 'backup-create' });
                fetchBackups();
            }
        } catch (error) {
            console.error('Backup failed:', error);
            toast.error(tc('errors.failedToSave'), { id: 'backup-create' });
        } finally {
            setCreating(false);
        }
    };

    const handleDeleteBackup = async (id: string) => {
        if (!window.confirm('Are you sure you want to delete this backup? This action cannot be undone.')) return;

        try {
            await api.delete(`/admin/backups/${id}`);
            toast.success(t('backups.backupDeleted'));
            setBackups(prev => prev.filter(b => b.id !== id));
        } catch (error) {
            toast.error(tc('errors.failedToDelete'));
        }
    };

    const handleDownloadBackup = async (id: string, filename: string) => {
        try {
            setDownloading(id);
            const response = await api.get(`/admin/backups/${id}/download`);

            if (response.data.success && response.data.data.downloadUrl) {
                // Fetch the file content and create a blob for proper download
                // This is needed because the download attribute doesn't work for cross-origin URLs
                const fileResponse = await fetch(response.data.data.downloadUrl);
                if (!fileResponse.ok) {
                    throw new Error('Failed to fetch backup file');
                }
                
                const blob = await fileResponse.blob();
                const blobUrl = window.URL.createObjectURL(blob);
                
                const link = document.createElement('a');
                link.href = blobUrl;
                link.download = filename;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                
                // Clean up the blob URL
                window.URL.revokeObjectURL(blobUrl);
                toast.success(t('backups.downloadStarted'));
            }
        } catch (error) {
            console.error('Download failed:', error);
            toast.error(tc('errors.failedToLoad'));
        } finally {
            setDownloading(null);
        }
    };

    // Handle file upload for restore
    const handleFileSelect = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        // Reset input for re-selection of same file
        event.target.value = '';

        // Validate file type
        if (!file.name.endsWith('.json')) {
            toast.error('Invalid file type. Please upload a JSON backup file.');
            return;
        }

        // Validate file size (max 100MB)
        if (file.size > 100 * 1024 * 1024) {
            toast.error('File too large. Maximum size is 100MB.');
            return;
        }

        try {
            const text = await file.text();
            const backupData = JSON.parse(text);

            // Validate backup structure
            if (!backupData.tables || typeof backupData.tables !== 'object') {
                toast.error('Invalid backup format. File does not contain valid backup data.');
                return;
            }

            // Store for confirmation
            setPendingRestoreData(backupData);
            setPendingRestoreFilename(file.name);
            setShowRestoreConfirm(true);
        } catch (error) {
            console.error('Failed to parse backup file:', error);
            toast.error('Failed to parse backup file. Ensure it is a valid JSON file.');
        }
    };

    // Execute restore after confirmation
    const handleConfirmRestore = async () => {
        if (!pendingRestoreData) return;

        try {
            setRestoring(true);
            setShowRestoreConfirm(false);
            toast.loading('Restoring database from backup...', { id: 'restore-backup' });

            const response = await api.post('/admin/backups/restore', pendingRestoreData);

            if (response.data.success) {
                toast.success('Backup restored successfully! The page will refresh.', { id: 'restore-backup' });
                // Refresh page after restore to reload all data
                setTimeout(() => {
                    window.location.reload();
                }, 2000);
            } else {
                throw new Error(response.data.error || 'Restore failed');
            }
        } catch (error: unknown) {
            const err = error as { response?: { data?: { error?: string } }; message?: string };
            console.error('Restore failed:', error);
            toast.error(err.response?.data?.error || err.message || 'Restore failed', { id: 'restore-backup' });
        } finally {
            setRestoring(false);
            setPendingRestoreData(null);
            setPendingRestoreFilename('');
        }
    };

    const handleCancelRestore = () => {
        setShowRestoreConfirm(false);
        setPendingRestoreData(null);
        setPendingRestoreFilename('');
    };

    const formatSize = (bytes: number) => {
        if (!bytes || bytes <= 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    };

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'completed': return <CheckCircle2 className="w-4 h-4 text-green-500" />;
            case 'failed': return <XCircle className="w-4 h-4 text-red-500" />;
            case 'pending': return <Loader2 className="w-4 h-4 animate-spin text-blue-500" />;
            default: return <Clock className="w-4 h-4 text-slate-400" />;
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        <Database className="w-7 h-7 text-blue-600" />
                        {t('backups.title')}
                    </h1>
                    <p className="text-slate-500 dark:text-slate-400">
                        {t('backups.subtitle')}
                    </p>
                </div>
                <div className="flex items-center gap-3">
                    <input
                        type="file"
                        ref={fileInputRef}
                        className="hidden"
                        accept=".json"
                        onChange={handleFileSelect}
                    />
                    <Button
                        onClick={() => fileInputRef.current?.click()}
                        disabled={restoring}
                        variant="outline"
                        className="border-amber-300 text-amber-700 hover:bg-amber-50 dark:border-amber-700 dark:text-amber-400 dark:hover:bg-amber-900/20"
                    >
                        {restoring ? (
                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        ) : (
                            <Upload className="w-4 h-4 mr-2" />
                        )}
                        Restore from File
                    </Button>
                    <Button
                        onClick={handleCreateBackup}
                        disabled={creating}
                        className="bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-500/20"
                    >
                        {creating ? (
                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        ) : (
                            <Plus className="w-4 h-4 mr-2" />
                        )}
                        {t('backups.createBackup')}
                    </Button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Retention Info */}
                <motion.div variants={fadeInUp} className="lg:col-span-1">
                    <Card className="h-full">
                        <CardHeader>
                            <CardTitle className="text-lg">{t('backups.systemHealth')}</CardTitle>
                            <CardDescription>{t('backups.subtitle')}</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="p-4 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700">
                                <div className="flex items-center justify-between mb-2">
                                    <span className="text-sm font-medium text-slate-600 dark:text-slate-400">{t('backups.totalBackups')}</span>
                                    <span className="text-lg font-bold text-slate-900 dark:text-white">{backups.length}</span>
                                </div>
                                <div className="w-full bg-slate-200 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                                    <div className="bg-blue-600 h-full" style={{ width: `${Math.min(backups.length * 10, 100)}%` }} />
                                </div>
                                <p className="text-xs text-slate-500 mt-2">Storage usage: {formatSize(backups.reduce((acc, curr) => acc + (curr.size_bytes || 0), 0))}</p>
                            </div>

                            <div className="flex items-start gap-3 p-3 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-100 dark:border-yellow-800 rounded-lg">
                                <AlertTriangle className="w-5 h-5 text-yellow-600 shrink-0 mt-0.5" />
                                <p className="text-xs text-yellow-700 dark:text-yellow-400">
                                    <strong>Important:</strong> Backups contain sensitive database information. Ensure download links are only shared with authorized administrators.
                                </p>
                            </div>

                            <div className="space-y-3">
                                <h4 className="text-sm font-semibold text-slate-900 dark:text-white uppercase tracking-wider">Storage Policy</h4>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-slate-500">Auto-Retention</span>
                                    <span className="font-medium text-green-600">Enabled</span>
                                </div>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-slate-500">Max Backups</span>
                                    <span className="font-medium">10 Files</span>
                                </div>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-slate-500">Last Cleanup</span>
                                    <span className="font-medium text-slate-400">Never</span>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </motion.div>

                {/* Backup List */}
                <div className="lg:col-span-2">
                    <Card>
                        <CardHeader className="flex flex-row items-center justify-between">
                            <div>
                                <CardTitle>History</CardTitle>
                                <CardDescription>Last 30 days of data snapshots</CardDescription>
                            </div>
                            <Button variant="ghost" size="sm" onClick={fetchBackups} disabled={loading}>
                                <RefreshCcw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
                            </Button>
                        </CardHeader>
                        <CardContent className="p-0">
                            <div className="overflow-x-auto">
                                <table className="w-full text-left">
                                    <thead className="bg-slate-50 dark:bg-slate-800 text-xs text-slate-500 uppercase font-semibold">
                                        <tr>
                                            <th className="px-6 py-4">Filename</th>
                                            <th className="px-6 py-4">Metadata</th>
                                            <th className="px-6 py-4">Status</th>
                                            <th className="px-6 py-4 text-right">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                        <AnimatePresence mode="popLayout">
                                            {loading && backups.length === 0 ? (
                                                Array.from({ length: 3 }).map((_, i) => (
                                                    <tr key={i} className="animate-pulse">
                                                        <td colSpan={4} className="px-6 py-8">
                                                            <div className="h-4 bg-slate-100 dark:bg-slate-700 rounded w-full" />
                                                        </td>
                                                    </tr>
                                                ))
                                            ) : backups.length === 0 ? (
                                                <tr>
                                                    <td colSpan={4} className="px-6 py-12 text-center text-slate-500">
                                                        <Database className="w-12 h-12 mx-auto mb-3 opacity-20" />
                                                        <p>No backups found</p>
                                                    </td>
                                                </tr>
                                            ) : (
                                                backups.map((backup) => (
                                                    <motion.tr
                                                        key={backup.id}
                                                        initial={{ opacity: 0 }}
                                                        animate={{ opacity: 1 }}
                                                        exit={{ opacity: 0 }}
                                                        className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group"
                                                    >
                                                        <td className="px-6 py-4">
                                                            <div className="flex items-center gap-3">
                                                                <FileJson className="w-8 h-8 text-blue-500/50" />
                                                                <div>
                                                                    <p className="font-medium text-slate-900 dark:text-white truncate max-w-[200px]" title={backup.filename}>
                                                                        {backup.filename}
                                                                    </p>
                                                                    <p className="text-xs text-slate-500 flex items-center gap-1">
                                                                        <Clock className="w-3 h-3" />
                                                                        {new Date(backup.created_at).toLocaleString()}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                        </td>
                                                        <td className="px-6 py-4">
                                                            <div className="space-y-1">
                                                                <div className="flex items-center gap-2 text-xs text-slate-600 dark:text-slate-400">
                                                                    <HardDrive className="w-3 h-3" />
                                                                    {formatSize(backup.size_bytes)}
                                                                </div>
                                                                <div className="flex items-center gap-2 text-xs text-slate-600 dark:text-slate-400">
                                                                    <User className="w-3 h-3" />
                                                                    {backup.users?.full_name || 'System'}
                                                                </div>
                                                            </div>
                                                        </td>
                                                        <td className="px-6 py-4">
                                                            <div className="flex items-center gap-2 text-xs font-medium capitalize">
                                                                {getStatusIcon(backup.status)}
                                                                {backup.status}
                                                            </div>
                                                        </td>
                                                        <td className="px-6 py-4 text-right">
                                                            <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                                {backup.status === 'completed' && (
                                                                    <Button
                                                                        variant="outline"
                                                                        size="sm"
                                                                        onClick={() => handleDownloadBackup(backup.id, backup.filename)}
                                                                        disabled={downloading === backup.id}
                                                                        title="Download snapshot"
                                                                    >
                                                                        {downloading === backup.id ? (
                                                                            <Loader2 className="w-4 h-4 animate-spin" />
                                                                        ) : (
                                                                            <Download className="w-4 h-4" />
                                                                        )}
                                                                    </Button>
                                                                )}
                                                                <Button
                                                                    variant="outline"
                                                                    size="sm"
                                                                    className="text-red-600 hover:text-red-700 hover:bg-red-50"
                                                                    onClick={() => handleDeleteBackup(backup.id)}
                                                                    title="Delete backup"
                                                                >
                                                                    <Trash2 className="w-4 h-4" />
                                                                </Button>
                                                            </div>
                                                        </td>
                                                    </motion.tr>
                                                ))
                                            )}
                                        </AnimatePresence>
                                    </tbody>
                                </table>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>

            {/* Restore Confirmation Modal */}
            <AnimatePresence>
                {showRestoreConfirm && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm"
                        onClick={handleCancelRestore}
                    >
                        <motion.div
                            initial={{ scale: 0.95, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.95, opacity: 0 }}
                            className="bg-white dark:bg-slate-900 rounded-xl shadow-2xl p-6 max-w-md w-full mx-4"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="flex items-center gap-4 mb-4">
                                <div className="p-3 bg-amber-100 dark:bg-amber-900/30 rounded-full">
                                    <Shield className="w-6 h-6 text-amber-600" />
                                </div>
                                <div>
                                    <h3 className="text-lg font-semibold text-slate-900 dark:text-white">
                                        Confirm Database Restore
                                    </h3>
                                    <p className="text-sm text-slate-500">
                                        This action cannot be undone
                                    </p>
                                </div>
                            </div>

                            <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg mb-4">
                                <div className="flex items-start gap-3">
                                    <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                                    <div className="text-sm text-amber-800 dark:text-amber-200">
                                        <p className="font-medium mb-1">Warning: This will replace all current data!</p>
                                        <p>All existing settings, modules, menus, bookings, and other data will be overwritten with the backup contents.</p>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-3 p-3 bg-slate-100 dark:bg-slate-800 rounded-lg mb-6">
                                <FileJson className="w-8 h-8 text-blue-500" />
                                <div>
                                    <p className="font-medium text-slate-900 dark:text-white text-sm truncate max-w-[250px]">
                                        {pendingRestoreFilename}
                                    </p>
                                    <p className="text-xs text-slate-500">
                                        {pendingRestoreData && Object.keys(pendingRestoreData.tables || {}).length} tables to restore
                                    </p>
                                </div>
                            </div>

                            <div className="flex justify-end gap-3">
                                <Button
                                    variant="outline"
                                    onClick={handleCancelRestore}
                                >
                                    Cancel
                                </Button>
                                <Button
                                    onClick={handleConfirmRestore}
                                    className="bg-amber-600 hover:bg-amber-700 text-white"
                                >
                                    <RotateCcw className="w-4 h-4 mr-2" />
                                    Restore Backup
                                </Button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  Link as LinkIcon,
  Plus,
  Trash2,
  Save,
  GripVertical,
  Facebook,
  Instagram,
  Twitter,
  Youtube,
  Globe,
  Layout,
  Info,
  Layers,
  CheckCircle2,
  Type
} from 'lucide-react';

interface FooterLink {
  label: string;
  href: string;
}

interface FooterColumn {
  title: string;
  links: FooterLink[];
}

interface FooterSocial {
  platform: string;
  url: string;
}

interface FooterConfig {
  logo: {
    text: string;
    showIcon: boolean;
  };
  description: string;
  columns: FooterColumn[];
  socials: FooterSocial[];
  contact: {
    showAddress: boolean;
    showPhone: boolean;
    showEmail: boolean;
  };
  copyright: string;
}

const DEFAULT_CONFIG: FooterConfig = {
  logo: { text: 'Iron Paradise Gym', showIcon: true },
  description: 'Premium resort experience in the heart of Lebanon.',
  columns: [
    {
      title: 'Quick Links',
      links: [
        { label: 'Restaurant', href: '/restaurant' },
        { label: 'Chalets', href: '/chalets' },
        { label: 'Pool', href: '/pool' },
        { label: 'Gift Cards', href: '/giftcards' }
      ]
    },
    {
      title: 'Legal',
      links: [
        { label: 'Privacy Policy', href: '/privacy' },
        { label: 'Terms of Service', href: '/terms' },
        { label: 'Cancellation Policy', href: '/cancellation' }
      ]
    }
  ],
  socials: [
    { platform: 'facebook', url: '' },
    { platform: 'instagram', url: '' }
  ],
  contact: {
    showAddress: true,
    showPhone: true,
    showEmail: true
  },
  copyright: '© {year} Iron Paradise Gym. All rights reserved.'
};

export default function FooterSettingsPage() {
  const [config, setConfig] = useState<FooterConfig>(DEFAULT_CONFIG);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    try {
      const { data } = await api.get('/admin/settings');
      if (data?.data?.footer) {
        // deeply merge with default config to ensure all properties exist
        setConfig(prev => ({
          ...DEFAULT_CONFIG,
          ...data.data.footer,
          logo: {
            ...DEFAULT_CONFIG.logo,
            ...(data.data.footer.logo || {})
          },
          contact: {
            ...DEFAULT_CONFIG.contact,
            ...(data.data.footer.contact || {})
          },
          // Ensure arrays are arrays
          columns: data.data.footer.columns || DEFAULT_CONFIG.columns,
          socials: data.data.footer.socials || DEFAULT_CONFIG.socials,
        }));
      }
    } catch (error) {
      console.error('Failed to fetch footer settings:', error);
      toast.error('Failed to load settings');
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await api.put('/admin/settings', { footer: config });
      toast.success('Footer configuration saved successfully');
    } catch (error: unknown) {
      const axiosError = error as { response?: { data?: { error?: string } } };
      toast.error(axiosError.response?.data?.error || 'Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  // --- Column Management ---
  const addColumn = () => {
    setConfig({
      ...config,
      columns: [...config.columns, { title: 'New Column', links: [] }]
    });
  };

  const removeColumn = (index: number) => {
    const newColumns = [...config.columns];
    newColumns.splice(index, 1);
    setConfig({ ...config, columns: newColumns });
  };

  const updateColumnTitle = (index: number, title: string) => {
    const newColumns = [...config.columns];
    newColumns[index].title = title;
    setConfig({ ...config, columns: newColumns });
  };

  const addLink = (columnIndex: number) => {
    const newColumns = [...config.columns];
    newColumns[columnIndex].links.push({ label: 'New Link', href: '#' });
    setConfig({ ...config, columns: newColumns });
  };

  const removeLink = (columnIndex: number, linkIndex: number) => {
    const newColumns = [...config.columns];
    newColumns[columnIndex].links.splice(linkIndex, 1);
    setConfig({ ...config, columns: newColumns });
  };

  const updateLink = (columnIndex: number, linkIndex: number, field: keyof FooterLink, value: string) => {
    const newColumns = [...config.columns];
    newColumns[columnIndex].links[linkIndex][field] = value;
    setConfig({ ...config, columns: newColumns });
  };

  // --- Socials Management ---
  const addSocial = () => {
    setConfig({
      ...config,
      socials: [...config.socials, { platform: 'facebook', url: '' }]
    });
  };

  const removeSocial = (index: number) => {
    const newSocials = [...config.socials];
    newSocials.splice(index, 1);
    setConfig({ ...config, socials: newSocials });
  };

  const updateSocial = (index: number, field: keyof FooterSocial, value: string) => {
    const newSocials = [...config.socials];
    newSocials[index][field] = value;
    setConfig({ ...config, socials: newSocials });
  };

  if (loading) return (
    <div className="flex items-center justify-center min-h-[400px]">
      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-600" />
    </div>
  );

  return (
    <motion.div
      initial="hidden"
      animate="visible"
      variants={staggerContainer}
      className="space-y-8 pb-20"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            <Layout className="w-8 h-8 text-primary-600" />
            Footer CMS
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            Customize your website''s footer layout, links, and information.
          </p>
        </div>
        <Button onClick={handleSave} disabled={saving} className="shadow-lg shadow-primary-500/20">
          <Save className="w-4 h-4 mr-2" />
          {saving ? 'Saving...' : 'Save Changes'}
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column - General & Brand */}
        <div className="lg:col-span-1 space-y-8">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Info className="w-5 h-5 text-blue-500" />
                Branding & Info
              </CardTitle>
              <CardDescription>Resort name and description</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Resort Name (Logo Text)</label>
                <div className="flex gap-2">
                  <Input
                    value={config.logo.text}
                    onChange={(e) => setConfig({ ...config, logo: { ...config.logo, text: e.target.value } })}
                    placeholder="Iron Paradise Gym"
                  />
                  <Button
                    variant={config.logo.showIcon ? 'primary' : 'outline'}
                    size="icon"
                    onClick={() => setConfig({ ...config, logo: { ...config.logo, showIcon: !config.logo.showIcon } })}
                    title="Toggle Icon"
                  >
                    <CheckCircle2 className={`w-4 h-4 ${config.logo.showIcon ? 'text-white' : 'text-slate-400'}`} />
                  </Button>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Footer Description</label>
                <textarea
                  className="w-full min-h-[100px] p-3 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                  value={config.description}
                  onChange={(e) => setConfig({ ...config, description: e.target.value })}
                  placeholder="A short description of your resort..."
                />
              </div>
              <div className="space-y-3 pt-2">
                <p className="text-xs font-semibold text-slate-500 uppercase">Contact Display</p>
                {[
                  { key: 'showAddress', label: 'Show Address' },
                  { key: 'showPhone', label: 'Show Phone' },
                  { key: 'showEmail', label: 'Show Email' }
                ].map((item) => (
                  <label key={item.key} className="flex items-center gap-3 cursor-pointer group">
                    <div
                      className={`w-10 h-6 rounded-full p-1 transition-colors duration-200 ${config.contact[item.key as keyof typeof config.contact] ? 'bg-primary-600' : 'bg-slate-200 dark:bg-slate-700'}`}
                      onClick={() => setConfig({
                        ...config,
                        contact: { ...config.contact, [item.key]: !config.contact[item.key as keyof typeof config.contact] }
                      })}
                    >
                      <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform duration-200 ${config.contact[item.key as keyof typeof config.contact] ? 'translate-x-4' : 'translate-x-0'}`} />
                    </div>
                    <span className="text-sm text-slate-600 dark:text-slate-400 group-hover:text-slate-900 transition-colors">{item.label}</span>
                  </label>
                ))}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Facebook className="w-5 h-5 text-blue-600" />
                Social Media
              </CardTitle>
              <CardDescription>Links to your social profiles</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <AnimatePresence>
                {config.socials.map((social, idx) => (
                  <motion.div
                    key={idx}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    className="flex gap-2"
                  >
                    <select
                      className="w-1/3 p-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                      value={social.platform}
                      onChange={(e) => updateSocial(idx, 'platform', e.target.value)}
                    >
                      <option value="facebook">Facebook</option>
                      <option value="instagram">Instagram</option>
                      <option value="twitter">Twitter</option>
                      <option value="youtube">Youtube</option>
                      <option value="tiktok">TikTok</option>
                    </select>
                    <Input
                      className="flex-1"
                      placeholder="URL"
                      value={social.url}
                      onChange={(e) => updateSocial(idx, 'url', e.target.value)}
                    />
                    <Button variant="ghost" size="icon" onClick={() => removeSocial(idx)} className="text-red-500">
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </motion.div>
                ))}
              </AnimatePresence>
              <Button variant="outline" className="w-full text-xs" onClick={addSocial}>
                <Plus className="w-3 h-3 mr-1" /> Add Social Profile
              </Button>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Type className="w-5 h-5 text-slate-600" />
                Copyright
              </CardTitle>
            </CardHeader>
            <CardContent>
              <Input
                value={config.copyright}
                onChange={(e) => setConfig({ ...config, copyright: e.target.value })}
                placeholder="© {year} Iron Paradise Gym. All rights reserved."
              />
              <p className="text-xs text-slate-500 mt-2">Use {'{year}'} to insert the current year.</p>
            </CardContent>
          </Card>
        </div>

        {/* Right Column - Links Columns Builder */}
        <div className="lg:col-span-2 space-y-8">
          <Card className="min-h-full">
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle className="flex items-center gap-2">
                  <Layers className="w-5 h-5 text-purple-500" />
                  Footer Navigation
                </CardTitle>
                <CardDescription>Manage your footer columns and links</CardDescription>
              </div>
              <Button onClick={addColumn} size="sm" variant="outline" className="text-primary-600 border-primary-100 bg-primary-50">
                <Plus className="w-4 h-4 mr-2" />
                Add Column
              </Button>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {config.columns.map((column, colIdx) => (
                  <motion.div
                    key={colIdx}
                    variants={fadeInUp}
                    className="p-4 rounded-xl border border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/20 relative group"
                  >
                    <div className="flex items-center gap-2 mb-4">
                      <GripVertical className="w-4 h-4 text-slate-300 cursor-grab" />
                      <Input
                        value={column.title}
                        onChange={(e) => updateColumnTitle(colIdx, e.target.value)}
                        className="font-bold border-none bg-transparent focus:ring-0 px-0 h-auto text-lg"
                        placeholder="Column Title"
                      />
                      <Button
                        variant="ghost"
                        size="icon"
                        className="opacity-0 group-hover:opacity-100 transition-opacity"
                        onClick={() => removeColumn(colIdx)}
                      >
                        <Trash2 className="w-4 h-4 text-red-400" />
                      </Button>
                    </div>

                    <div className="space-y-2">
                      <AnimatePresence>
                        {column.links.map((link, linkIdx) => (
                          <motion.div
                            key={linkIdx}
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            className="flex items-center gap-2 p-2 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-lg shadow-sm"
                          >
                            <Input
                              value={link.label}
                              onChange={(e) => updateLink(colIdx, linkIdx, 'label', e.target.value)}
                              placeholder="Label"
                              className="text-xs h-8 flex-1"
                            />
                            <Input
                              value={link.href}
                              onChange={(e) => updateLink(colIdx, linkIdx, 'href', e.target.value)}
                              placeholder="URL"
                              className="text-xs h-8 flex-1"
                            />
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 text-slate-400 hover:text-red-500"
                              onClick={() => removeLink(colIdx, linkIdx)}
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </Button>
                          </motion.div>
                        ))}
                      </AnimatePresence>
                      <Button
                        variant="ghost"
                        className="w-full text-xs h-8 border border-dashed border-slate-300 dark:border-slate-700 hover:border-primary-300 hover:text-primary-600"
                        onClick={() => addLink(colIdx)}
                      >
                        <Plus className="w-3 h-3 mr-1" /> Add Link
                      </Button>
                    </div>
                  </motion.div>
                ))}

                {config.columns.length === 0 && (
                  <div className="col-span-full py-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
                    <Layers className="w-12 h-12 mx-auto text-slate-300 mb-3" />
                    <p className="text-slate-500">No columns added yet. Use the button above to start.</p>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </motion.div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  Layout,
  Image as ImageIcon,
  Type,
  Sparkles,
  Save,
  Plus,
  Trash2,
  GripVertical,
  Eye,
  EyeOff,
  ArrowUp,
  ArrowDown,
  Upload,
  X,
  Loader2,
} from 'lucide-react';

interface HeroSlide {
  id: string;
  title: string;
  subtitle: string;
  buttonText: string;
  buttonLink: string;
  imageUrl: string;
  enabled: boolean;
}

interface HomepageSection {
  id: string;
  type: 'services' | 'features' | 'stats' | 'testimonials' | 'map' | 'cta';
  title: string;
  enabled: boolean;
  order: number;
}

interface HomepageSettings {
  heroSlides: HeroSlide[];
  sections: HomepageSection[];
  ctaTitle: string;
  ctaSubtitle: string;
  ctaButtonText: string;
  ctaButtonLink: string;
}

const defaultSettings: HomepageSettings = {
  heroSlides: [
    {
      id: '1',
      title: 'Welcome to Azure Bay Resort',
      subtitle: 'Where the Ocean Meets Paradise',
      buttonText: 'Explore Our Services',
      buttonLink: '#services',
      imageUrl: '',
      enabled: true,
    },
  ],
  sections: [
    { id: '1', type: 'services', title: 'Our Services', enabled: true, order: 1 },
    { id: '2', type: 'features', title: 'Why Choose Us', enabled: true, order: 2 },
    { id: '3', type: 'stats', title: 'Our Numbers', enabled: true, order: 3 },
    { id: '4', type: 'testimonials', title: 'What Our Guests Say', enabled: true, order: 4 },
    { id: '5', type: 'map', title: 'Find Us', enabled: true, order: 5 },
    { id: '6', type: 'cta', title: 'Call to Action', enabled: true, order: 6 },
  ],
  ctaTitle: 'Ready to Experience Azure Bay Resort?',
  ctaSubtitle: 'Book your stay today and discover why we are the preferred destination.',
  ctaButtonText: 'Book Now',
  ctaButtonLink: '/chalets',
};

export default function HomepageSettingsPage() {
  const t = useTranslations('adminSettings');
  const tc = useTranslations('adminCommon');
  const [settings, setSettings] = useState<HomepageSettings>(defaultSettings);
  const [isSaving, setIsSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [activeTab, setActiveTab] = useState<'hero' | 'sections' | 'cta'>('hero');
  const [uploadingSlideId, setUploadingSlideId] = useState<string | null>(null);
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  useEffect(() => {
    loadSettings();
  }, []);

  const normalizeSections = (raw: unknown): HomepageSection[] => {
    if (!Array.isArray(raw)) return defaultSettings.sections;
    if (raw.length === 0) return defaultSettings.sections;
    // If sections are strings like ["hero","features",...], convert to objects
    if (typeof raw[0] === 'string') {
      const sectionTitles: Record<string, string> = {
        hero: 'Hero', services: 'Our Services', features: 'Why Choose Us',
        programs: 'Programs', stats: 'Our Numbers', testimonials: 'What Our Guests Say',
        map: 'Find Us', cta: 'Call to Action',
      };
      return (raw as string[]).map((type, i) => ({
        id: String(i + 1),
        type: type as HomepageSection['type'],
        title: sectionTitles[type] || type,
        enabled: true,
        order: i + 1,
      }));
    }
    // Already objects — ensure all fields exist
    return raw.map((s: any, i: number) => ({
      id: s.id ?? String(i + 1),
      type: s.type ?? 'services',
      title: s.title ?? s.type ?? 'Section',
      enabled: s.enabled ?? true,
      order: s.order ?? i + 1,
    }));
  };

  const normalizeSlides = (raw: unknown): HeroSlide[] => {
    if (!Array.isArray(raw) || raw.length === 0) return defaultSettings.heroSlides;
    return raw.map((s: any, i: number) => ({
      id: s.id ?? String(i + 1),
      title: s.title ?? '',
      subtitle: s.subtitle ?? '',
      buttonText: s.buttonText ?? s.ctaText ?? '',
      buttonLink: s.buttonLink ?? s.ctaLink ?? '',
      imageUrl: s.imageUrl ?? '',
      enabled: s.enabled ?? true,
    }));
  };

  const applyData = (d: any) => {
    setSettings({
      ...defaultSettings,
      heroSlides: normalizeSlides(d.heroSlides),
      sections: normalizeSections(d.sections),
      ctaTitle: d.ctaTitle ?? defaultSettings.ctaTitle,
      ctaSubtitle: d.ctaSubtitle ?? defaultSettings.ctaSubtitle,
      ctaButtonText: d.ctaButtonText ?? defaultSettings.ctaButtonText,
      ctaButtonLink: d.ctaButtonLink ?? defaultSettings.ctaButtonLink,
    });
  };

  const loadSettings = async () => {
    try {
      const response = await api.get('/admin/settings/homepage');
      if (response.data?.success && response.data?.data) {
        applyData(response.data.data);
      }
    } catch {
      try {
        const fallbackResponse = await api.get('/admin/settings');
        if (fallbackResponse.data?.data?.homepage) {
          applyData(fallbackResponse.data.data.homepage);
        }
      } catch { /* fallback also failed, use defaults */ }
    }
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await api.put('/admin/settings/homepage', settings);
      toast.success(t('homepage.saved'));
      setHasChanges(false);
    } catch {
      toast.error(tc('errors.failedToSave'));
    } finally {
      setIsSaving(false);
    }
  };

  const addHeroSlide = () => {
    const slides = settings.heroSlides || [];
    setSettings({
      ...settings,
      heroSlides: [
        ...slides,
        {
          id: Date.now().toString(),
          title: 'New Slide',
          subtitle: 'Subtitle text',
          buttonText: 'Learn More',
          buttonLink: '#',
          imageUrl: '',
          enabled: true,
        },
      ],
    });
    setHasChanges(true);
  };

  const removeHeroSlide = (id: string) => {
    setSettings({
      ...settings,
      heroSlides: (settings.heroSlides || []).filter((slide) => slide.id !== id),
    });
    setHasChanges(true);
  };

  const updateHeroSlide = (id: string, field: keyof HeroSlide, value: string | boolean) => {
    setSettings({
      ...settings,
      heroSlides: (settings.heroSlides || []).map((slide) =>
        slide.id === id ? { ...slide, [field]: value } : slide
      ),
    });
    setHasChanges(true);
  };

  const toggleSection = (id: string) => {
    setSettings({
      ...settings,
      sections: (settings.sections || []).map((section) =>
        section.id === id ? { ...section, enabled: !section.enabled } : section
      ),
    });
    setHasChanges(true);
  };

  const moveSection = (id: string, direction: 'up' | 'down') => {
    const secs = settings.sections || [];
    const idx = secs.findIndex((s) => s.id === id);
    if (idx < 0) return;
    if ((direction === 'up' && idx === 0) || (direction === 'down' && idx === secs.length - 1)) return;
    const newSections = [...secs];
    const swapIdx = direction === 'up' ? idx - 1 : idx + 1;
    [newSections[idx], newSections[swapIdx]] = [newSections[swapIdx], newSections[idx]];
    newSections.forEach((s, i) => (s.order = i + 1));
    setSettings({ ...settings, sections: newSections });
    setHasChanges(true);
  };

  const handleImageUpload = async (slideId: string, file: File) => {
    if (!file.type.startsWith('image/')) { toast.error('Please upload an image file'); return; }
    if (file.size > 10 * 1024 * 1024) { toast.error('Image must be less than 10MB'); return; }
    setUploadingSlideId(slideId);
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const response = await api.post('/admin/uploads', { file: reader.result, type: 'image', filename: file.name });
        if (response.data?.success && response.data?.data?.url) {
          updateHeroSlide(slideId, 'imageUrl', response.data.data.url);
          toast.success('Image uploaded successfully');
        } else { toast.error('Failed to upload image'); }
      } catch { toast.error('Failed to upload image'); }
      finally { setUploadingSlideId(null); }
    };
    reader.onerror = () => { toast.error('Failed to read file'); setUploadingSlideId(null); };
    reader.readAsDataURL(file);
  };

  const heroSlides = settings.heroSlides || [];
  const sections = settings.sections || [];

  const tabs = [
    { id: 'hero' as const, label: 'Hero Slides', icon: Sparkles },
    { id: 'sections' as const, label: 'Sections', icon: Layout },
    { id: 'cta' as const, label: 'Call to Action', icon: Type },
  ];

  return (
    <motion.div initial="hidden" animate="visible" variants={staggerContainer} className="space-y-8">
      {/* Header */}
      <motion.div variants={fadeInUp} className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            <Layout className="w-8 h-8 text-primary-600" />
            {t('homepage.title')}
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">{t('homepage.subtitle')}</p>
        </div>
        <Button onClick={handleSave} isLoading={isSaving} disabled={!hasChanges}>
          <Save className="w-4 h-4 mr-2" />
          {tc('saveChanges')}
        </Button>
      </motion.div>

      {/* Tabs */}
      <motion.div variants={fadeInUp}>
        <div className="flex gap-2 p-1 bg-slate-100 dark:bg-slate-800 rounded-lg w-fit">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                  activeTab === tab.id
                    ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow'
                    : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
                }`}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
              </button>
            );
          })}
        </div>
      </motion.div>

      {/* Hero Slides Tab */}
      {activeTab === 'hero' && (
        <motion.div variants={fadeInUp}>
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle>Hero Slides</CardTitle>
                  <CardDescription>Manage the rotating hero banner on the homepage</CardDescription>
                </div>
                <Button variant="outline" size="sm" onClick={addHeroSlide}>
                  <Plus className="w-4 h-4 mr-2" />
                  Add Slide
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-6">
                {heroSlides.map((slide, index) => (
                  <div
                    key={slide.id}
                    className={`p-4 rounded-lg border-2 ${
                      slide.enabled
                        ? 'border-primary-200 bg-primary-50/50 dark:border-primary-800 dark:bg-primary-900/20'
                        : 'border-slate-200 dark:border-slate-700 opacity-60'
                    }`}
                  >
                    <div className="flex items-center gap-4 mb-4">
                      <GripVertical className="w-4 h-4 text-slate-400 cursor-grab" />
                      <span className="text-sm font-medium text-slate-500">Slide {index + 1}</span>
                      <div className="flex-1" />
                      <Button variant="ghost" size="sm" onClick={() => updateHeroSlide(slide.id, 'enabled', !slide.enabled)}>
                        {slide.enabled ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                      </Button>
                      {heroSlides.length > 1 && (
                        <Button variant="ghost" size="sm" onClick={() => removeHeroSlide(slide.id)}>
                          <Trash2 className="w-4 h-4 text-red-500" />
                        </Button>
                      )}
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Title</label>
                        <Input value={slide.title} onChange={(e) => updateHeroSlide(slide.id, 'title', e.target.value)} />
                      </div>
                      <div>
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Subtitle</label>
                        <Input value={slide.subtitle} onChange={(e) => updateHeroSlide(slide.id, 'subtitle', e.target.value)} />
                      </div>
                      <div>
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Button Text</label>
                        <Input value={slide.buttonText} onChange={(e) => updateHeroSlide(slide.id, 'buttonText', e.target.value)} />
                      </div>
                      <div>
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Button Link</label>
                        <Input value={slide.buttonLink} onChange={(e) => updateHeroSlide(slide.id, 'buttonLink', e.target.value)} />
                      </div>
                      <div className="md:col-span-2">
                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-2 block">
                          <ImageIcon className="w-4 h-4 inline mr-2" />
                          Background Image
                        </label>
                        <div className="space-y-3">
                          {slide.imageUrl && (
                            <div className="relative rounded-lg overflow-hidden h-40 bg-slate-100 dark:bg-slate-800">
                              <img src={slide.imageUrl} alt={`Slide ${index + 1} background`} className="w-full h-full object-cover" />
                              <button
                                type="button"
                                onClick={() => updateHeroSlide(slide.id, 'imageUrl', '')}
                                className="absolute top-2 right-2 p-1 bg-red-500 text-white rounded-full hover:bg-red-600 transition-colors"
                              >
                                <X className="w-4 h-4" />
                              </button>
                            </div>
                          )}
                          <div className="flex gap-3">
                            <input
                              type="file"
                              accept="image/*"
                              ref={(el) => { fileInputRefs.current[slide.id] = el; }}
                              onChange={(e) => { const f = e.target.files?.[0]; if (f) handleImageUpload(slide.id, f); }}
                              className="hidden"
                            />
                            <Button
                              type="button"
                              variant="outline"
                              size="sm"
                              onClick={() => fileInputRefs.current[slide.id]?.click()}
                              disabled={uploadingSlideId === slide.id}
                              className="flex-1"
                            >
                              {uploadingSlideId === slide.id
                                ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Uploading...</>
                                : <><Upload className="w-4 h-4 mr-2" />{slide.imageUrl ? 'Change Image' : 'Upload Image'}</>
                              }
                            </Button>
                          </div>
                          <div className="flex items-center gap-2">
                            <span className="text-xs text-slate-400">or enter URL:</span>
                            <Input
                              value={slide.imageUrl}
                              onChange={(e) => updateHeroSlide(slide.id, 'imageUrl', e.target.value)}
                              placeholder="https://example.com/image.jpg"
                              className="flex-1 text-sm"
                            />
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </motion.div>
      )}

      {/* Sections Tab */}
      {activeTab === 'sections' && (
        <motion.div variants={fadeInUp}>
          <Card>
            <CardHeader>
              <CardTitle>Homepage Sections</CardTitle>
              <CardDescription>Toggle and reorder the sections that appear on the homepage</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {[...sections].sort((a, b) => a.order - b.order).map((section, index, arr) => (
                  <div
                    key={section.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border ${
                      section.enabled
                        ? 'border-primary-200 bg-primary-50/50 dark:border-primary-800 dark:bg-primary-900/20'
                        : 'border-slate-200 dark:border-slate-700 opacity-60'
                    }`}
                  >
                    <GripVertical className="w-4 h-4 text-slate-400 cursor-grab" />
                    <div className="flex-1">
                      <span className="text-sm font-medium">{section.title}</span>
                      <span className="text-xs text-slate-400 ml-2">({section.type})</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <Button variant="ghost" size="sm" onClick={() => moveSection(section.id, 'up')} disabled={index === 0}>
                        <ArrowUp className="w-4 h-4" />
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => moveSection(section.id, 'down')} disabled={index === arr.length - 1}>
                        <ArrowDown className="w-4 h-4" />
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => toggleSection(section.id)}>
                        {section.enabled ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </motion.div>
      )}

      {/* CTA Tab */}
      {activeTab === 'cta' && (
        <motion.div variants={fadeInUp}>
          <Card>
            <CardHeader>
              <CardTitle>Call to Action Section</CardTitle>
              <CardDescription>Configure the CTA section at the bottom of the homepage</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Title</label>
                  <Input
                    value={settings.ctaTitle ?? ''}
                    onChange={(e) => { setSettings({ ...settings, ctaTitle: e.target.value }); setHasChanges(true); }}
                  />
                </div>
                <div>
                  <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Subtitle</label>
                  <Input
                    value={settings.ctaSubtitle ?? ''}
                    onChange={(e) => { setSettings({ ...settings, ctaSubtitle: e.target.value }); setHasChanges(true); }}
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Button Text</label>
                    <Input
                      value={settings.ctaButtonText ?? ''}
                      onChange={(e) => { setSettings({ ...settings, ctaButtonText: e.target.value }); setHasChanges(true); }}
                    />
                  </div>
                  <div>
                    <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Button Link</label>
                    <Input
                      value={settings.ctaButtonLink ?? ''}
                      onChange={(e) => { setSettings({ ...settings, ctaButtonLink: e.target.value }); setHasChanges(true); }}
                    />
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>
      )}
    </motion.div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
    Link as LinkIcon,
    Plus,
    Trash2,
    Save,
    GripVertical,
    Home,
    UtensilsCrossed,
    Waves,
    Cookie,
    Layout,
    Info,
    Layers,
    Settings,
    Globe,
    Sun,
    Coins,
    ShoppingCart as CartIcon,
    MousePointer2,
    ExternalLink
} from 'lucide-react';
import { useSiteSettings } from '@/lib/settings-context';

interface NavLink {
    type: 'internal' | 'external' | 'module';
    label: string;
    href: string;
    moduleSlug?: string;
    icon: string;
}

interface NavbarConfig {
    links: NavLink[];
    config: {
        showLanguageSwitcher: boolean;
        showThemeToggle: boolean;
        showCurrencySwitcher: boolean;
        showUserPreferences: boolean;
        showCart: boolean;
        sticky: boolean;
    };
}

const ICONS: Record<string, React.ElementType> = {
    Home,
    UtensilsCrossed,
    Waves,
    Cookie,
    Link: LinkIcon,
    Layout,
    Info,
    Layers,
    Globe,
    ExternalLink
};

const DEFAULT_CONFIG: NavbarConfig = {
    links: [
        { type: 'internal', label: 'Home', href: '/', icon: 'Home' }
    ],
    config: {
        showLanguageSwitcher: true,
        showThemeToggle: true,
        showCurrencySwitcher: true,
        showUserPreferences: true,
        showCart: true,
        sticky: true
    }
};

export default function NavbarSettingsPage() {
    const [navbar, setNavbar] = useState<NavbarConfig>(DEFAULT_CONFIG);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const { modules, refetch: refetchSettings } = useSiteSettings();

    useEffect(() => {
        fetchSettings();
    }, []);

    const fetchSettings = async () => {
        try {
            const { data } = await api.get('/admin/settings');
            if (data?.data?.navbar) {
                setNavbar(data.data.navbar);
            }
        } catch (error) {
            console.error('Failed to fetch navbar settings:', error);
            toast.error('Failed to load settings');
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        setSaving(true);
        try {
            // Send navbar directly in the body (backend expects settings.navbar)
            await api.put('/admin/settings', { navbar });
            toast.success('Navbar configuration saved successfully');
            // Refetch settings to update the header immediately
            await refetchSettings();
        } catch (error: unknown) {
            const axiosError = error as { response?: { data?: { error?: string } } };
            toast.error(axiosError.response?.data?.error || 'Failed to save settings');
        } finally {
            setSaving(false);
        }
    };

    const addLink = () => {
        setNavbar({
            ...navbar,
            links: [...navbar.links, { type: 'internal', label: 'New Link', href: '#', icon: 'Link' }]
        });
    };

    const removeLink = (index: number) => {
        const newLinks = [...navbar.links];
        newLinks.splice(index, 1);
        setNavbar({ ...navbar, links: newLinks });
    };

    const updateLink = (index: number, field: keyof NavLink, value: string | boolean) => {
        const newLinks = [...navbar.links];
        newLinks[index] = { ...newLinks[index], [field]: value };

        // If setting to module type, try to find the module and set label/href
        if (field === 'moduleSlug' && value) {
            const module = modules.find(m => m.slug === value);
            if (module) {
                newLinks[index].label = module.name;
                newLinks[index].href = `/${module.slug}`;
            }
        }

        setNavbar({ ...navbar, links: newLinks });
    };

    const toggleConfig = (field: keyof NavbarConfig['config']) => {
        setNavbar({
            ...navbar,
            config: {
                ...navbar.config,
                [field]: !navbar.config[field]
            }
        });
    };

    if (loading) return (
        <div className="flex items-center justify-center min-h-[400px]">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-600" />
        </div>
    );

    return (
        <motion.div
            initial="hidden"
            animate="visible"
            variants={staggerContainer}
            className="space-y-8 pb-20"
        >
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
                        <MousePointer2 className="w-8 h-8 text-primary-600" />
                        Navigation Bar CMS
                    </h1>
                    <p className="text-slate-500 dark:text-slate-400">
                        Customize your website''s top navigation bar, links, and action buttons.
                    </p>
                </div>
                <Button onClick={handleSave} disabled={saving} className="shadow-lg shadow-primary-500/20">
                    <Save className="w-4 h-4 mr-2" />
                    {saving ? 'Saving...' : 'Save Changes'}
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column - Configuration Toggles */}
                <div className="lg:col-span-1 space-y-8">
                    <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <Settings className="w-5 h-5 text-blue-500" />
                                Bar Configuration
                            </CardTitle>
                            <CardDescription>Global navbar behavior and components</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            {[
                                { key: 'sticky', label: 'Sticky Header', icon: Layout },
                                { key: 'showCart', label: 'Cart Button', icon: CartIcon },
                                { key: 'showLanguageSwitcher', label: 'Language Switcher', icon: Globe },
                                { key: 'showThemeToggle', label: 'Theme Toggle', icon: Sun },
                                { key: 'showCurrencySwitcher', label: 'Currency Switcher', icon: Coins },
                                { key: 'showUserPreferences', label: 'User Preferences', icon: Settings }
                            ].map((item) => (
                                <div key={item.key} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 group-hover:bg-primary-50 group-hover:text-primary-600 transition-colors">
                                            <item.icon className="w-4 h-4" />
                                        </div>
                                        <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{item.label}</span>
                                    </div>
                                    <button
                                        onClick={() => toggleConfig(item.key as keyof NavbarConfig['config'])}
                                        className={`w-12 h-6 rounded-full p-1 transition-colors duration-200 ${navbar.config[item.key as keyof NavbarConfig['config']] ? 'bg-primary-600' : 'bg-slate-200 dark:bg-slate-700'}`}
                                    >
                                        <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform duration-200 ${navbar.config[item.key as keyof NavbarConfig['config']] ? 'translate-x-6' : 'translate-x-0'}`} />
                                    </button>
                                </div>
                            ))}
                        </CardContent>
                    </Card>
                </div>

                {/* Right Column - Navigation Links Builder */}
                <div className="lg:col-span-2 space-y-8">
                    <Card className="min-h-full">
                        <CardHeader className="flex flex-row items-center justify-between">
                            <div>
                                <CardTitle className="flex items-center gap-2">
                                    <LinkIcon className="w-5 h-5 text-purple-500" />
                                    Navigation Links
                                </CardTitle>
                                <CardDescription>Manage the links displayed in the main navigation</CardDescription>
                            </div>
                            <Button onClick={addLink} size="sm" variant="outline" className="text-primary-600 border-primary-100 bg-primary-50">
                                <Plus className="w-4 h-4 mr-2" />
                                Add Link
                            </Button>
                        </CardHeader>
                        <CardContent>
                            <div className="space-y-4">
                                <AnimatePresence>
                                    {navbar.links.map((link, idx) => (
                                        <motion.div
                                            key={idx}
                                            initial={{ opacity: 0, scale: 0.95 }}
                                            animate={{ opacity: 1, scale: 1 }}
                                            exit={{ opacity: 0, scale: 0.95 }}
                                            className="p-4 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800/50 shadow-sm relative group"
                                        >
                                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
                                                <div className="space-y-1">
                                                    <label className="text-[10px] font-bold text-slate-400 uppercase">Link Type</label>
                                                    <select
                                                        className="w-full p-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                                        value={link.type}
                                                        onChange={(e) => updateLink(idx, 'type', e.target.value)}
                                                    >
                                                        <option value="internal">Internal Page</option>
                                                        <option value="external">External Link</option>
                                                        <option value="module">Site Module</option>
                                                    </select>
                                                </div>

                                                {link.type === 'module' ? (
                                                    <div className="space-y-1">
                                                        <label className="text-[10px] font-bold text-slate-400 uppercase">Module</label>
                                                        <select
                                                            className="w-full p-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                                            value={link.moduleSlug}
                                                            onChange={(e) => updateLink(idx, 'moduleSlug', e.target.value)}
                                                        >
                                                            <option value="">Select Module</option>
                                                            {modules.map(m => (
                                                                <option key={m.id} value={m.slug}>{m.name}</option>
                                                            ))}
                                                        </select>
                                                    </div>
                                                ) : (
                                                    <div className="space-y-1">
                                                        <label className="text-[10px] font-bold text-slate-400 uppercase">Label</label>
                                                        <Input
                                                            value={link.label}
                                                            onChange={(e) => updateLink(idx, 'label', e.target.value)}
                                                            placeholder="e.g. Home"
                                                        />
                                                    </div>
                                                )}

                                                <div className="space-y-1">
                                                    <label className="text-[10px] font-bold text-slate-400 uppercase">{link.type === 'module' ? 'Path (Auto)' : 'URL / Path'}</label>
                                                    <Input
                                                        value={link.href}
                                                        onChange={(e) => updateLink(idx, 'href', e.target.value)}
                                                        placeholder={link.type === 'external' ? 'https://...' : '/...'}
                                                        disabled={link.type === 'module'}
                                                    />
                                                </div>

                                                <div className="flex gap-2">
                                                    <div className="space-y-1 flex-1">
                                                        <label className="text-[10px] font-bold text-slate-400 uppercase">Icon</label>
                                                        <select
                                                            className="w-full p-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"
                                                            value={link.icon}
                                                            onChange={(e) => updateLink(idx, 'icon', e.target.value)}
                                                        >
                                                            {Object.keys(ICONS).map(iconName => (
                                                                <option key={iconName} value={iconName}>{iconName}</option>
                                                            ))}
                                                        </select>
                                                    </div>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => removeLink(idx)}
                                                        className="text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </Button>
                                                </div>
                                            </div>

                                            <div className="absolute -left-2 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <GripVertical className="w-4 h-4 text-slate-300 cursor-grab" />
                                            </div>
                                        </motion.div>
                                    ))}
                                </AnimatePresence>

                                {navbar.links.length === 0 && (
                                    <div className="py-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl">
                                        <LinkIcon className="w-12 h-12 mx-auto text-slate-300 mb-3" />
                                        <p className="text-slate-500">No navigation links added yet.</p>
                                    </div>
                                )}
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </motion.div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { CardSkeleton } from '@/components/ui/Skeleton';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import { useSocket } from '@/lib/socket';
import {
  Bell,
  Send,
  RefreshCw,
  CheckCircle2,
  Clock,
  Users,
  MessageSquare,
  AlertCircle,
  Info,
  CheckCheck,
  Megaphone,
  Plus,
  Trash2,
  Filter,
  Calendar,
  Zap,
  FileText,
  Settings,
  ExternalLink,
  Edit,
  Copy,
  X,
} from 'lucide-react';

// Types
interface NotificationAction {
  label: string;
  url: string;
  style?: 'primary' | 'secondary' | 'danger';
}

interface Notification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'success' | 'warning' | 'error';
  priority: 'low' | 'normal' | 'high' | 'urgent';
  target_type: 'all' | 'customer' | 'staff' | 'admin';
  target_id?: string;
  is_read: boolean;
  actions?: NotificationAction[];
  scheduled_for?: string;
  sent_at?: string;
  created_at: string;
  read_at?: string;
}

interface NotificationTemplate {
  id: string;
  name: string;
  title: string;
  message: string;
  type: 'info' | 'success' | 'warning' | 'error';
  target_type: 'all' | 'customer' | 'staff' | 'admin';
  priority: 'low' | 'normal' | 'high' | 'urgent';
  actions?: NotificationAction[];
  variables: string[];
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

type TabType = 'notifications' | 'templates' | 'broadcasts';

const typeConfig: Record<string, { icon: React.ElementType; color: string; bgColor: string }> = {
  info: { icon: Info, color: 'text-blue-500', bgColor: 'bg-blue-100 dark:bg-blue-900/30' },
  success: { icon: CheckCircle2, color: 'text-green-500', bgColor: 'bg-green-100 dark:bg-green-900/30' },
  warning: { icon: AlertCircle, color: 'text-yellow-500', bgColor: 'bg-yellow-100 dark:bg-yellow-900/30' },
  error: { icon: AlertCircle, color: 'text-red-500', bgColor: 'bg-red-100 dark:bg-red-900/30' },
};

const priorityConfig: Record<string, { label: string; color: string; bgColor: string }> = {
  low: { label: 'Low', color: 'text-slate-500', bgColor: 'bg-slate-100 dark:bg-slate-700' },
  normal: { label: 'Normal', color: 'text-blue-500', bgColor: 'bg-blue-100 dark:bg-blue-900/30' },
  high: { label: 'High', color: 'text-orange-500', bgColor: 'bg-orange-100 dark:bg-orange-900/30' },
  urgent: { label: 'Urgent', color: 'text-red-500', bgColor: 'bg-red-100 dark:bg-red-900/30' },
};

export default function AdminNotificationsPage() {
  const t = useTranslations('adminSettings');
  const tc = useTranslations('adminCommon');
  
  // Tab state
  const [activeTab, setActiveTab] = useState<TabType>('notifications');
  
  // Notification states
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [broadcasts, setBroadcasts] = useState<Notification[]>([]);
  const [templates, setTemplates] = useState<NotificationTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  
  // Modal states
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showTemplateModal, setShowTemplateModal] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<NotificationTemplate | null>(null);
  
  // Filters
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  
  const { socket } = useSocket();

  // Form states for new notification
  const [newNotification, setNewNotification] = useState<{
    title: string;
    message: string;
    type: 'info' | 'success' | 'warning' | 'error';
    target_type: 'all' | 'customer' | 'staff' | 'admin';
    priority: 'low' | 'normal' | 'high' | 'urgent';
    scheduled_for: string;
    actions: NotificationAction[];
  }>({
    title: '',
    message: '',
    type: 'info',
    target_type: 'all',
    priority: 'normal',
    scheduled_for: '',
    actions: [],
  });
  
  // Form states for template
  const [templateForm, setTemplateForm] = useState<{
    name: string;
    title: string;
    message: string;
    type: 'info' | 'success' | 'warning' | 'error';
    target_type: 'all' | 'customer' | 'staff' | 'admin';
    priority: 'low' | 'normal' | 'high' | 'urgent';
    variables: string[];
    actions: NotificationAction[];
    is_active: boolean;
  }>({
    name: '',
    title: '',
    message: '',
    type: 'info',
    target_type: 'all',
    priority: 'normal',
    variables: [],
    actions: [],
    is_active: true,
  });
  
  const [sending, setSending] = useState(false);

  // Fetch data
  const fetchNotifications = useCallback(async () => {
    try {
      setLoading(true);
      const [notifRes, broadcastRes, templateRes] = await Promise.all([
        api.get('/admin/notifications'),
        api.get('/admin/notifications/broadcasts').catch(() => ({ data: { data: [] } })),
        api.get('/admin/notifications/templates').catch(() => ({ data: { data: [] } })),
      ]);
      setNotifications(notifRes.data.data || []);
      setBroadcasts(broadcastRes.data.data || []);
      setTemplates(templateRes.data.data || []);
    } catch {
      setNotifications([]);
      setBroadcasts([]);
      setTemplates([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchNotifications();
  }, [fetchNotifications]);

  // Real-time updates
  useEffect(() => {
    if (socket) {
      socket.on('notification:new', (notification: Notification) => {
        setNotifications((prev) => [notification, ...prev]);
      });
      return () => {
        socket.off('notification:new');
      };
    }
  }, [socket]);

  // Actions
  const sendNotification = async () => {
    if (!newNotification.title || !newNotification.message) {
      toast.error(tc('errors.required'));
      return;
    }

    try {
      setSending(true);
      await api.post('/admin/notifications/broadcast', {
        ...newNotification,
        scheduled_for: newNotification.scheduled_for || undefined,
      });
      toast.success(t('notifications.sent'));
      setShowCreateModal(false);
      resetNotificationForm();
      fetchNotifications();
    } catch {
      toast.error(tc('errors.failedToSave'));
    } finally {
      setSending(false);
    }
  };

  const deleteNotification = async (id: string) => {
    try {
      await api.delete(`/admin/notifications/${id}`);
      setNotifications((prev) => prev.filter((n) => n.id !== id));
      setBroadcasts((prev) => prev.filter((b) => b.id !== id));
      toast.success(tc('success.deleted'));
    } catch {
      toast.error('Failed to delete notification');
    }
  };

  const deleteSelected = async () => {
    if (selectedIds.length === 0) return;
    
    try {
      await api.post('/admin/notifications/delete-multiple', { ids: selectedIds });
      setNotifications((prev) => prev.filter((n) => !selectedIds.includes(n.id)));
      setBroadcasts((prev) => prev.filter((b) => !selectedIds.includes(b.id)));
      setSelectedIds([]);
      toast.success(`${selectedIds.length} notifications deleted`);
    } catch {
      toast.error('Failed to delete notifications');
    }
  };

  // Template actions
  const saveTemplate = async () => {
    if (!templateForm.name || !templateForm.title || !templateForm.message) {
      toast.error('Name, title and message are required');
      return;
    }

    try {
      setSending(true);
      if (editingTemplate) {
        await api.put(`/admin/notifications/templates/${editingTemplate.id}`, templateForm);
        toast.success('Template updated');
      } else {
        await api.post('/admin/notifications/templates', templateForm);
        toast.success('Template created');
      }
      setShowTemplateModal(false);
      resetTemplateForm();
      fetchNotifications();
    } catch {
      toast.error('Failed to save template');
    } finally {
      setSending(false);
    }
  };

  const deleteTemplate = async (id: string) => {
    try {
      await api.delete(`/admin/notifications/templates/${id}`);
      setTemplates((prev) => prev.filter((t) => t.id !== id));
      toast.success('Template deleted');
    } catch {
      toast.error('Failed to delete template');
    }
  };

  const sendFromTemplate = async (template: NotificationTemplate) => {
    try {
      await api.post(`/admin/notifications/templates/${template.id}/send`, {});
      toast.success('Notification sent from template');
      fetchNotifications();
    } catch {
      toast.error('Failed to send from template');
    }
  };

  const useTemplateForNotification = (template: NotificationTemplate) => {
    setNewNotification({
      title: template.title,
      message: template.message,
      type: template.type as 'info' | 'success' | 'warning' | 'error',
      target_type: template.target_type as 'all' | 'customer' | 'staff' | 'admin',
      priority: template.priority as 'low' | 'normal' | 'high' | 'urgent',
      scheduled_for: '',
      actions: template.actions || [],
    });
    setShowCreateModal(true);
  };

  // Form helpers
  const resetNotificationForm = () => {
    setNewNotification({
      title: '',
      message: '',
      type: 'info',
      target_type: 'all',
      priority: 'normal',
      scheduled_for: '',
      actions: [],
    });
  };

  const resetTemplateForm = () => {
    setTemplateForm({
      name: '',
      title: '',
      message: '',
      type: 'info',
      target_type: 'all',
      priority: 'normal',
      variables: [],
      actions: [],
      is_active: true,
    });
    setEditingTemplate(null);
  };

  const openEditTemplate = (template: NotificationTemplate) => {
    setEditingTemplate(template);
    setTemplateForm({
      name: template.name,
      title: template.title,
      message: template.message,
      type: template.type as 'info' | 'success' | 'warning' | 'error',
      target_type: template.target_type as 'all' | 'customer' | 'staff' | 'admin',
      priority: template.priority as 'low' | 'normal' | 'high' | 'urgent',
      variables: template.variables,
      actions: template.actions || [],
      is_active: template.is_active,
    });
    setShowTemplateModal(true);
  };

  const addAction = (form: 'notification' | 'template') => {
    const newAction: NotificationAction = { label: '', url: '', style: 'primary' };
    if (form === 'notification') {
      setNewNotification((prev) => ({ ...prev, actions: [...prev.actions, newAction] }));
    } else {
      setTemplateForm((prev) => ({ ...prev, actions: [...prev.actions, newAction] }));
    }
  };

  const updateAction = (form: 'notification' | 'template', index: number, field: keyof NotificationAction, value: string) => {
    if (form === 'notification') {
      setNewNotification((prev) => ({
        ...prev,
        actions: prev.actions.map((a, i) => i === index ? { ...a, [field]: value } : a),
      }));
    } else {
      setTemplateForm((prev) => ({
        ...prev,
        actions: prev.actions.map((a, i) => i === index ? { ...a, [field]: value } : a),
      }));
    }
  };

  const removeAction = (form: 'notification' | 'template', index: number) => {
    if (form === 'notification') {
      setNewNotification((prev) => ({ ...prev, actions: prev.actions.filter((_, i) => i !== index) }));
    } else {
      setTemplateForm((prev) => ({ ...prev, actions: prev.actions.filter((_, i) => i !== index) }));
    }
  };

  // Filtering
  const filteredNotifications = notifications.filter((n) => {
    if (typeFilter !== 'all' && n.type !== typeFilter) return false;
    if (priorityFilter !== 'all' && n.priority !== priorityFilter) return false;
    return true;
  });

  const filteredBroadcasts = broadcasts.filter((b) => {
    if (typeFilter !== 'all' && b.type !== typeFilter) return false;
    if (priorityFilter !== 'all' && b.priority !== priorityFilter) return false;
    return true;
  });

  // Stats
  const unreadCount = notifications.filter((n) => !n.is_read).length;
  const todayCount = notifications.filter(
    (n) => n.created_at?.startsWith(new Date().toISOString().split('T')[0])
  ).length;
  const scheduledCount = broadcasts.filter((b) => b.scheduled_for && !b.sent_at).length;

  // Selection
  const toggleSelect = (id: string) => {
    setSelectedIds((prev) => 
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
    );
  };

  const toggleSelectAll = () => {
    const currentList = activeTab === 'broadcasts' ? filteredBroadcasts : filteredNotifications;
    if (selectedIds.length === currentList.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(currentList.map((n) => n.id));
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <CardSkeleton key={i} />
          ))}
        </div>
        <CardSkeleton />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
            {t('notifications.title')}
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            Manage notifications, templates, and broadcasts
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={fetchNotifications}>
            <RefreshCw className="w-4 h-4 mr-2" />
            {tc('refresh')}
          </Button>
          <Button variant="outline" onClick={() => { resetTemplateForm(); setShowTemplateModal(true); }}>
            <FileText className="w-4 h-4 mr-2" />
            New Template
          </Button>
          <Button onClick={() => { resetNotificationForm(); setShowCreateModal(true); }}>
            <Plus className="w-4 h-4 mr-2" />
            {t('notifications.sendNotification')}
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-blue-100 text-sm">{t('notifications.totalSent')}</p>
                  <p className="text-3xl font-bold mt-1">{notifications.length}</p>
                </div>
                <Bell className="w-10 h-10 text-blue-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-green-500 to-green-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-green-100 text-sm">{t('notifications.sentToday')}</p>
                  <p className="text-3xl font-bold mt-1">{todayCount}</p>
                </div>
                <Megaphone className="w-10 h-10 text-green-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-orange-500 to-orange-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-orange-100 text-sm">Unread</p>
                  <p className="text-3xl font-bold mt-1">{unreadCount}</p>
                </div>
                <MessageSquare className="w-10 h-10 text-orange-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>

        <motion.div variants={fadeInUp}>
          <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-purple-100 text-sm">Scheduled</p>
                  <p className="text-3xl font-bold mt-1">{scheduledCount}</p>
                </div>
                <Calendar className="w-10 h-10 text-purple-200" />
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-slate-200 dark:border-slate-700">
        {(['notifications', 'broadcasts', 'templates'] as TabType[]).map((tab) => (
          <button
            key={tab}
            onClick={() => { setActiveTab(tab); setSelectedIds([]); }}
            className={`px-4 py-2 font-medium capitalize transition-colors ${
              activeTab === tab
                ? 'text-blue-600 border-b-2 border-blue-600'
                : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
            }`}
          >
            {tab === 'notifications' && <Bell className="w-4 h-4 inline mr-2" />}
            {tab === 'broadcasts' && <Megaphone className="w-4 h-4 inline mr-2" />}
            {tab === 'templates' && <FileText className="w-4 h-4 inline mr-2" />}
            {tab}
            {tab === 'templates' && ` (${templates.length})`}
            {tab === 'broadcasts' && ` (${broadcasts.length})`}
          </button>
        ))}
      </div>

      {/* Filters & Bulk Actions */}
      {activeTab !== 'templates' && (
        <Card>
          <CardContent className="p-4">
            <div className="flex flex-wrap items-center gap-4">
              <Filter className="w-4 h-4 text-slate-400" />
              <select
                value={typeFilter}
                onChange={(e) => setTypeFilter(e.target.value)}
                className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
              >
                <option value="all">All Types</option>
                <option value="info">Info</option>
                <option value="success">Success</option>
                <option value="warning">Warning</option>
                <option value="error">Error</option>
              </select>
              <select
                value={priorityFilter}
                onChange={(e) => setPriorityFilter(e.target.value)}
                className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
              >
                <option value="all">All Priorities</option>
                <option value="low">Low</option>
                <option value="normal">Normal</option>
                <option value="high">High</option>
                <option value="urgent">Urgent</option>
              </select>
              
              {selectedIds.length > 0 && (
                <div className="ml-auto flex items-center gap-2">
                  <span className="text-sm text-slate-500">{selectedIds.length} selected</span>
                  <Button variant="outline" size="sm" onClick={() => setSelectedIds([])}>
                    Clear
                  </Button>
                  <Button variant="danger" size="sm" onClick={deleteSelected}>
                    <Trash2 className="w-4 h-4 mr-1" />
                    Delete Selected
                  </Button>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Templates Tab */}
      {activeTab === 'templates' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <AnimatePresence mode="popLayout">
            {templates.length === 0 ? (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="col-span-full text-center py-12"
              >
                <FileText className="w-12 h-12 mx-auto text-slate-300 dark:text-slate-600 mb-4" />
                <p className="text-slate-500 dark:text-slate-400">No templates yet</p>
                <Button className="mt-4" onClick={() => { resetTemplateForm(); setShowTemplateModal(true); }}>
                  <Plus className="w-4 h-4 mr-2" />
                  Create Template
                </Button>
              </motion.div>
            ) : (
              templates.map((template) => (
                <motion.div
                  key={template.id}
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  layout
                >
                  <Card className={`h-full ${!template.is_active ? 'opacity-60' : ''}`}>
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between mb-3">
                        <div className="flex items-center gap-2">
                          <div className={`p-2 rounded-lg ${typeConfig[template.type]?.bgColor || 'bg-blue-100'}`}>
                            {(() => {
                              const TypeIcon = typeConfig[template.type]?.icon || Info;
                              return <TypeIcon className={`w-4 h-4 ${typeConfig[template.type]?.color || 'text-blue-500'}`} />;
                            })()}
                          </div>
                          <div>
                            <h3 className="font-semibold text-slate-900 dark:text-white">{template.name}</h3>
                            <span className={`text-xs px-2 py-0.5 rounded ${priorityConfig[template.priority]?.bgColor} ${priorityConfig[template.priority]?.color}`}>
                              {priorityConfig[template.priority]?.label}
                            </span>
                          </div>
                        </div>
                        {!template.is_active && (
                          <span className="text-xs px-2 py-1 bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400 rounded">
                            Inactive
                          </span>
                        )}
                      </div>
                      
                      <p className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">{template.title}</p>
                      <p className="text-sm text-slate-500 dark:text-slate-400 line-clamp-2 mb-3">{template.message}</p>
                      
                      {template.variables.length > 0 && (
                        <div className="flex flex-wrap gap-1 mb-3">
                          {template.variables.map((v) => (
                            <span key={v} className="text-xs px-2 py-0.5 bg-slate-100 dark:bg-slate-700 rounded">
                              {`{{${v}}}`}
                            </span>
                          ))}
                        </div>
                      )}
                      
                      <div className="flex items-center gap-2 pt-3 border-t border-slate-200 dark:border-slate-700">
                        <Button size="sm" onClick={() => sendFromTemplate(template)}>
                          <Send className="w-3 h-3 mr-1" />
                          Send
                        </Button>
                        <Button size="sm" variant="outline" onClick={() => useTemplateForNotification(template)}>
                          <Copy className="w-3 h-3 mr-1" />
                          Use
                        </Button>
                        <Button size="sm" variant="ghost" onClick={() => openEditTemplate(template)}>
                          <Edit className="w-3 h-3" />
                        </Button>
                        <Button size="sm" variant="ghost" onClick={() => deleteTemplate(template.id)}>
                          <Trash2 className="w-3 h-3 text-red-500" />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                </motion.div>
              ))
            )}
          </AnimatePresence>
        </div>
      )}

      {/* Notifications/Broadcasts List */}
      {activeTab !== 'templates' && (
        <div className="space-y-3">
          <div className="flex items-center gap-2 px-2">
            <input
              type="checkbox"
              checked={selectedIds.length === (activeTab === 'broadcasts' ? filteredBroadcasts : filteredNotifications).length && selectedIds.length > 0}
              onChange={toggleSelectAll}
              className="w-4 h-4 rounded border-slate-300"
            />
            <span className="text-sm text-slate-500">Select all</span>
          </div>
          
          <AnimatePresence mode="popLayout">
            {(activeTab === 'broadcasts' ? filteredBroadcasts : filteredNotifications).length === 0 ? (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="text-center py-12"
              >
                <Bell className="w-12 h-12 mx-auto text-slate-300 dark:text-slate-600 mb-4" />
                <p className="text-slate-500 dark:text-slate-400">No {activeTab} yet</p>
                <p className="text-sm text-slate-400 dark:text-slate-500 mt-1">
                  Click "Send Notification" to broadcast a message
                </p>
              </motion.div>
            ) : (
              (activeTab === 'broadcasts' ? filteredBroadcasts : filteredNotifications).map((notification, index) => {
                const TypeIcon = typeConfig[notification.type]?.icon || Info;
                const typeColor = typeConfig[notification.type]?.color || 'text-blue-500';
                const typeBg = typeConfig[notification.type]?.bgColor || 'bg-blue-100';

                return (
                  <motion.div
                    key={notification.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, x: -100 }}
                    transition={{ delay: index * 0.03 }}
                    layout
                  >
                    <Card className={selectedIds.includes(notification.id) ? 'ring-2 ring-blue-500' : ''}>
                      <CardContent className="p-4">
                        <div className="flex items-start gap-4">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(notification.id)}
                            onChange={() => toggleSelect(notification.id)}
                            className="mt-2 w-4 h-4 rounded border-slate-300"
                          />
                          <div className={`p-2 rounded-lg ${typeBg}`}>
                            <TypeIcon className={`w-5 h-5 ${typeColor}`} />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex flex-wrap items-center gap-2 mb-1">
                              <h3 className="font-semibold text-slate-900 dark:text-white">
                                {notification.title}
                              </h3>
                              <span className={`px-2 py-0.5 rounded text-xs ${typeBg} ${typeColor}`}>
                                {notification.type}
                              </span>
                              <span className={`px-2 py-0.5 rounded text-xs ${priorityConfig[notification.priority || 'normal']?.bgColor} ${priorityConfig[notification.priority || 'normal']?.color}`}>
                                {priorityConfig[notification.priority || 'normal']?.label}
                              </span>
                              <span className="px-2 py-0.5 rounded text-xs bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">
                                <Users className="w-3 h-3 inline mr-1" />
                                {notification.target_type === 'all' ? 'All Users' : notification.target_type}
                              </span>
                            </div>
                            <p className="text-slate-600 dark:text-slate-300 text-sm">
                              {notification.message}
                            </p>
                            
                            {/* Action buttons */}
                            {notification.actions && notification.actions.length > 0 && (
                              <div className="flex gap-2 mt-2">
                                {notification.actions.map((action, i) => (
                                  <a
                                    key={i}
                                    href={action.url}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className={`inline-flex items-center gap-1 px-3 py-1 text-xs rounded ${
                                      action.style === 'danger' 
                                        ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
                                        : action.style === 'secondary'
                                        ? 'bg-slate-100 text-slate-700 dark:bg-slate-700 dark:text-slate-300'
                                        : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                                    }`}
                                  >
                                    {action.label}
                                    <ExternalLink className="w-3 h-3" />
                                  </a>
                                ))}
                              </div>
                            )}
                            
                            <div className="flex flex-wrap items-center gap-4 mt-2 text-xs text-slate-400">
                              <span className="flex items-center gap-1">
                                <Clock className="w-3 h-3" />
                                {notification.created_at ? formatDate(notification.created_at) : 'Just now'}
                              </span>
                              {notification.scheduled_for && !notification.sent_at && (
                                <span className="flex items-center gap-1 text-purple-500">
                                  <Calendar className="w-3 h-3" />
                                  Scheduled: {formatDate(notification.scheduled_for)}
                                </span>
                              )}
                              {notification.is_read && (
                                <span className="flex items-center gap-1 text-green-500">
                                  <CheckCheck className="w-3 h-3" />
                                  Read
                                </span>
                              )}
                            </div>
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => deleteNotification(notification.id)}
                          >
                            <Trash2 className="w-4 h-4 text-slate-400 hover:text-red-500" />
                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  </motion.div>
                );
              })
            )}
          </AnimatePresence>
        </div>
      )}

      {/* Create Notification Modal */}
      <AnimatePresence>
        {showCreateModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4 overflow-y-auto"
            onClick={() => setShowCreateModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white dark:bg-slate-800 rounded-xl max-w-2xl w-full p-6 my-8"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                  {t('notifications.sendNotification')}
                </h2>
                <button onClick={() => setShowCreateModal(false)} className="text-slate-400 hover:text-slate-600">
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Title *
                  </label>
                  <input
                    type="text"
                    value={newNotification.title}
                    onChange={(e) => setNewNotification((prev) => ({ ...prev, title: e.target.value }))}
                    placeholder="Notification title..."
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Message *
                  </label>
                  <textarea
                    value={newNotification.message}
                    onChange={(e) => setNewNotification((prev) => ({ ...prev, message: e.target.value }))}
                    placeholder="Enter your message..."
                    rows={3}
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                  />
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Type</label>
                    <select
                      value={newNotification.type}
                      onChange={(e) => setNewNotification((prev) => ({ ...prev, type: e.target.value as typeof newNotification.type }))}
                      className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                    >
                      <option value="info">Info</option>
                      <option value="success">Success</option>
                      <option value="warning">Warning</option>
                      <option value="error">Error</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Priority</label>
                    <select
                      value={newNotification.priority}
                      onChange={(e) => setNewNotification((prev) => ({ ...prev, priority: e.target.value as typeof newNotification.priority }))}
                      className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                    >
                      <option value="low">Low</option>
                      <option value="normal">Normal</option>
                      <option value="high">High</option>
                      <option value="urgent">Urgent</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Target</label>
                    <select
                      value={newNotification.target_type}
                      onChange={(e) => setNewNotification((prev) => ({ ...prev, target_type: e.target.value as typeof newNotification.target_type }))}
                      className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                    >
                      <option value="all">All Users</option>
                      <option value="customer">Customers</option>
                      <option value="staff">Staff</option>
                      <option value="admin">Admins</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Schedule</label>
                    <input
                      type="datetime-local"
                      value={newNotification.scheduled_for}
                      onChange={(e) => setNewNotification((prev) => ({ ...prev, scheduled_for: e.target.value }))}
                      className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                    />
                  </div>
                </div>

                {/* Action Buttons Section */}
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300">
                      Action Buttons
                    </label>
                    <Button size="sm" variant="outline" onClick={() => addAction('notification')}>
                      <Plus className="w-3 h-3 mr-1" /> Add Action
                    </Button>
                  </div>
                  {newNotification.actions.map((action, index) => (
                    <div key={index} className="flex gap-2 mb-2">
                      <input
                        type="text"
                        placeholder="Label"
                        value={action.label}
                        onChange={(e) => updateAction('notification', index, 'label', e.target.value)}
                        className="flex-1 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                      />
                      <input
                        type="text"
                        placeholder="URL"
                        value={action.url}
                        onChange={(e) => updateAction('notification', index, 'url', e.target.value)}
                        className="flex-1 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                      />
                      <select
                        value={action.style || 'primary'}
                        onChange={(e) => updateAction('notification', index, 'style', e.target.value)}
                        className="px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                      >
                        <option value="primary">Primary</option>
                        <option value="secondary">Secondary</option>
                        <option value="danger">Danger</option>
                      </select>
                      <Button size="sm" variant="ghost" onClick={() => removeAction('notification', index)}>
                        <Trash2 className="w-4 h-4 text-red-500" />
                      </Button>
                    </div>
                  ))}
                </div>

                <div className="flex justify-end gap-2 pt-4 border-t border-slate-200 dark:border-slate-700">
                  <Button variant="outline" onClick={() => setShowCreateModal(false)}>
                    {tc('cancel')}
                  </Button>
                  <Button onClick={sendNotification} disabled={sending}>
                    {sending ? 'Sending...' : (
                      <>
                        <Send className="w-4 h-4 mr-2" />
                        {newNotification.scheduled_for ? 'Schedule' : 'Send Now'}
                      </>
                    )}
                  </Button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Template Modal */}
      <AnimatePresence>
        {showTemplateModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200] p-4 overflow-y-auto"
            onClick={() => { setShowTemplateModal(false); resetTemplateForm(); }}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white dark:bg-slate-800 rounded-xl max-w-2xl w-full p-6 my-8"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                  {editingTemplate ? 'Edit Template' : 'Create Template'}
                </h2>
                <button onClick={() => { setShowTemplateModal(false); resetTemplateForm(); }} className="text-slate-400 hover:text-slate-600">
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Template Name *
                  </label>
                  <input
                    type="text"
                    value={templateForm.name}
                    onChange={(e) => setTemplateForm((prev) => ({ ...prev, name: e.target.value }))}
                    placeholder="e.g., Welcome Message, Payment Reminder..."
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Title * <span className="text-slate-400 text-xs">(use {`{{variable}}`} for placeholders)</span>
                  </label>
                  <input
                    type="text"
                    value={templateForm.title}
                    onChange={(e) => setTemplateForm((prev) => ({ ...prev, title: e.target.value }))}
                    placeholder="Welcome {{name}}!"
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Message *
                  </label>
                  <textarea
                    value={templateForm.message}
                    onChange={(e) => setTemplateForm((prev) => ({ ...prev, message: e.target.value }))}
                    placeholder="Hello {{name}}, your booking #{{bookingId}} has been confirmed..."
                    rows={4}
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Variables <span className="text-slate-400 text-xs">(comma separated)</span>
                  </label>
                  <input
                    type="text"
                    value={templateForm.variables.join(', ')}
                    onChange={(e) => setTemplateForm((prev) => ({ ...prev, variables: e.target.value.split(',').map(v => v.trim()).filter(Boolean) }))}
                    placeholder="name, bookingId, amount"
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                  />
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Type</label>
                    <select
                      value={templateForm.type}
                      onChange={(e) => setTemplateForm((prev) => ({ ...prev, type: e.target.value as typeof templateForm.type }))}
                      className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                    >
                      <option value="info">Info</option>
                      <option value="success">Success</option>
                      <option value="warning">Warning</option>
                      <option value="error">Error</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Priority</label>
                    <select
                      value={templateForm.priority}
                      onChange={(e) => setTemplateForm((prev) => ({ ...prev, priority: e.target.value as typeof templateForm.priority }))}
                      className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                    >
                      <option value="low">Low</option>
                      <option value="normal">Normal</option>
                      <option value="high">High</option>
                      <option value="urgent">Urgent</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Target</label>
                    <select
                      value={templateForm.target_type}
                      onChange={(e) => setTemplateForm((prev) => ({ ...prev, target_type: e.target.value as typeof templateForm.target_type }))}
                      className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white"
                    >
                      <option value="all">All Users</option>
                      <option value="customer">Customers</option>
                      <option value="staff">Staff</option>
                      <option value="admin">Admins</option>
                    </select>
                  </div>

                  <div className="flex items-center">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={templateForm.is_active}
                        onChange={(e) => setTemplateForm((prev) => ({ ...prev, is_active: e.target.checked }))}
                        className="w-4 h-4 rounded border-slate-300"
                      />
                      <span className="text-sm font-medium text-slate-700 dark:text-slate-300">Active</span>
                    </label>
                  </div>
                </div>

                {/* Template Actions */}
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300">
                      Action Buttons
                    </label>
                    <Button size="sm" variant="outline" onClick={() => addAction('template')}>
                      <Plus className="w-3 h-3 mr-1" /> Add Action
                    </Button>
                  </div>
                  {templateForm.actions.map((action, index) => (
                    <div key={index} className="flex gap-2 mb-2">
                      <input
                        type="text"
                        placeholder="Label"
                        value={action.label}
                        onChange={(e) => updateAction('template', index, 'label', e.target.value)}
                        className="flex-1 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                      />
                      <input
                        type="text"
                        placeholder="URL"
                        value={action.url}
                        onChange={(e) => updateAction('template', index, 'url', e.target.value)}
                        className="flex-1 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                      />
                      <select
                        value={action.style || 'primary'}
                        onChange={(e) => updateAction('template', index, 'style', e.target.value)}
                        className="px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                      >
                        <option value="primary">Primary</option>
                        <option value="secondary">Secondary</option>
                        <option value="danger">Danger</option>
                      </select>
                      <Button size="sm" variant="ghost" onClick={() => removeAction('template', index)}>
                        <Trash2 className="w-4 h-4 text-red-500" />
                      </Button>
                    </div>
                  ))}
                </div>

                <div className="flex justify-end gap-2 pt-4 border-t border-slate-200 dark:border-slate-700">
                  <Button variant="outline" onClick={() => { setShowTemplateModal(false); resetTemplateForm(); }}>
                    {tc('cancel')}
                  </Button>
                  <Button onClick={saveTemplate} disabled={sending}>
                    {sending ? 'Saving...' : (editingTemplate ? 'Update Template' : 'Create Template')}
                  </Button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { useSiteSettings } from '@/lib/settings-context';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import api from '@/lib/api';
import { toast } from 'sonner';
import {
  Settings,
  Save,
  Building2,
  Phone,
  Mail,
  MapPin,
  Clock,
  FileText,
  CreditCard,
  Globe,
  Package,
} from 'lucide-react';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';

export default function AdminSettingsPage() {
  const t = useTranslations('admin');
  const tCommon = useTranslations('common');

  const { settings, modules, refetch, loading } = useSiteSettings();
  const [formSettings, setFormSettings] = useState(settings);
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<string>('general');

  // Get active modules for the modules tab
  const activeModules = useMemo(() => {
    if (!modules || modules.length === 0) return [];
    return modules
      .filter(m => m.is_active)
      .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
  }, [modules]);

  useEffect(() => {
    setFormSettings(settings);
  }, [settings]);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await api.put('/admin/settings', formSettings);
      toast.success('Settings saved successfully!');
      await refetch();
    } catch (error) {
      toast.error('Failed to save settings. Please try again.');
    } finally {
      setIsSaving(false);
    }
  };

  // Helper to update module-specific settings
  const updateModuleSetting = (moduleSlug: string, field: string, value: string) => {
    setFormSettings({
      ...formSettings,
      moduleSettings: {
        ...(formSettings.moduleSettings || {}),
        [moduleSlug]: {
          ...((formSettings.moduleSettings as Record<string, Record<string, string>> || {})[moduleSlug] || {}),
          [field]: value,
        },
      },
    });
  };

  // Dynamically generate module-specific tabs based on active modules
  const moduleSpecificTabs = useMemo(() => {
    const tabs: { id: string; label: string; icon: typeof Building2; moduleSlug: string; templateType: string }[] = [];
    
    activeModules.forEach(module => {
      // Add settings tab for modules that have configurable settings
      if (module.template_type === 'multi_day_booking') {
        tabs.push({
          id: `module-${module.slug}` as const,
          label: module.name,
          icon: Building2,
          moduleSlug: module.slug,
          templateType: module.template_type
        });
      } else if (module.template_type === 'session_access') {
        tabs.push({
          id: `module-${module.slug}` as const,
          label: module.name,
          icon: Globe,
          moduleSlug: module.slug,
          templateType: module.template_type
        });
      }
    });
    
    return tabs;
  }, [activeModules]);

  const tabs = [
    { id: 'general' as const, label: 'General', icon: Building2 },
    ...(activeModules.length > 0 ? [{ id: 'modules' as const, label: 'Modules', icon: Package }] : []),
    { id: 'contact' as const, label: 'Contact', icon: Phone },
    { id: 'hours' as const, label: 'Business Hours', icon: Clock },
    ...moduleSpecificTabs,
    { id: 'legal' as const, label: 'Legal Pages', icon: FileText },
  ];

  const renderTabContent = () => {
    switch (activeTab) {
      case 'general':
        return (
          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Resort Name
              </label>
              <Input
                value={formSettings.resortName || ''}
                onChange={(e) => setFormSettings({ ...formSettings, resortName: e.target.value })}
                placeholder="Enter your resort name"
              />
              {!formSettings.resortName && (
                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                  Using default: Iron Paradise Gym
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Tagline
              </label>
              <Input
                value={formSettings.tagline || ''}
                onChange={(e) => setFormSettings({ ...formSettings, tagline: e.target.value })}
                placeholder="Enter a catchy tagline for your resort"
              />
              {!formSettings.tagline && (
                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                  Using default: Premier Resort Experience
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Description
              </label>
              <textarea
                rows={3}
                value={formSettings.description || ''}
                onChange={(e) => setFormSettings({ ...formSettings, description: e.target.value })}
                placeholder="Describe your resort in a few sentences"
                className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>
          </div>
        );

      case 'modules':
        return (
          <div className="space-y-6">
            <div className="bg-gradient-to-r from-primary-50 to-secondary-50 dark:from-primary-900/20 dark:to-secondary-900/20 rounded-2xl p-4 border border-primary-100 dark:border-primary-800 mb-6">
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Configure display names and settings for each of your active modules.
                These names will appear throughout the site.
              </p>
            </div>
            
            {activeModules.length === 0 ? (
              <div className="text-center py-8 text-slate-500">
                <Package className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p>No active modules found.</p>
                <p className="text-sm">Go to Module Builder to create and activate modules.</p>
              </div>
            ) : (
              <div className="space-y-6">
                {activeModules.map((module) => {
                  const moduleSettings = (formSettings.moduleSettings as Record<string, Record<string, string>> || {})[module.slug] || {};
                  return (
                    <div key={module.id} className="p-4 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-200 dark:border-slate-700">
                      <div className="flex items-center gap-2 mb-4">
                        <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-400 to-secondary-500 flex items-center justify-center">
                          <Package className="w-4 h-4 text-white" />
                        </div>
                        <div>
                          <h4 className="font-medium text-slate-900 dark:text-white">{module.name}</h4>
                          <p className="text-xs text-slate-500">Slug: {module.slug} • Type: {module.template_type}</p>
                        </div>
                      </div>
                      
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Display Name
                          </label>
                          <Input
                            value={moduleSettings.displayName || ''}
                            onChange={(e) => updateModuleSetting(module.slug, 'displayName', e.target.value)}
                            placeholder={module.name}
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Business Hours
                          </label>
                          <Input
                            value={moduleSettings.hours || ''}
                            onChange={(e) => updateModuleSetting(module.slug, 'hours', e.target.value)}
                            placeholder="e.g., 9:00 AM - 10:00 PM"
                          />
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        );

      case 'contact':
        return (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  <Phone className="w-4 h-4 inline mr-2" />
                  Phone Number
                </label>
                <input
                  type="text"
                  value={formSettings.phone || ''}
                  onChange={(e) => setFormSettings({ ...formSettings, phone: e.target.value })}
                  placeholder="+1 (555) 123-4567"
                  className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                />
                {!formSettings.phone && (
                  <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                    No phone number set - visitors won't see a contact number
                  </p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  <Mail className="w-4 h-4 inline mr-2" />
                  Email
                </label>
                <input
                  type="email"
                  value={formSettings.email || ''}
                  onChange={(e) => setFormSettings({ ...formSettings, email: e.target.value })}
                  placeholder="contact@yourresort.com"
                  className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                />
                {!formSettings.email && (
                  <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                    Using default: support@ironparadisegym.com
                  </p>
                )}
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                <MapPin className="w-4 h-4 inline mr-2" />
                Address
              </label>
              <input
                type="text"
                value={formSettings.address || ''}
                onChange={(e) => setFormSettings({ ...formSettings, address: e.target.value })}
                placeholder="123 Resort Boulevard, Beach City, State 12345"
                className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
              {!formSettings.address && (
                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                  No address set - consider adding your location
                </p>
              )}
            </div>
          </div>
        );

      case 'hours':
        return (
          <div className="space-y-6">
            <div className="bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 rounded-2xl p-4 border border-blue-100 dark:border-blue-800 mb-4">
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Set your standard business hours. Individual module hours can be configured in the Modules tab.
              </p>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  Pool Hours
                </label>
                <input
                  type="text"
                  value={formSettings.poolHours || ''}
                  onChange={(e) => setFormSettings({ ...formSettings, poolHours: e.target.value })}
                  placeholder="e.g., 8:00 AM - 8:00 PM"
                  className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  Restaurant Hours
                </label>
                <input
                  type="text"
                  value={formSettings.restaurantHours || ''}
                  onChange={(e) => setFormSettings({ ...formSettings, restaurantHours: e.target.value })}
                  placeholder="e.g., 7:00 AM - 11:00 PM"
                  className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  Reception Hours
                </label>
                <input
                  type="text"
                  value={formSettings.receptionHours || ''}
                  onChange={(e) => setFormSettings({ ...formSettings, receptionHours: e.target.value })}
                  placeholder="e.g., 24 Hours"
                  className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                />
              </div>
            </div>
          </div>
        );

      case 'legal':
        return (
          <div className="space-y-6">
            <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 rounded-2xl p-4 border border-purple-100 dark:border-purple-800 mb-4">
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Enter the legal content for your business. These pages are accessible via the footer links.
              </p>
            </div>
            
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Privacy Policy
              </label>
              <textarea
                rows={6}
                value={formSettings.privacyPolicy || ''}
                onChange={(e) => setFormSettings({ ...formSettings, privacyPolicy: e.target.value })}
                placeholder="Enter your privacy policy content. Explain how you collect, use, and protect customer data..."
                className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
              {!formSettings.privacyPolicy && (
                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                  No privacy policy set - recommended for legal compliance
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Terms of Service
              </label>
              <textarea
                rows={6}
                value={formSettings.termsOfService || ''}
                onChange={(e) => setFormSettings({ ...formSettings, termsOfService: e.target.value })}
                placeholder="Enter your terms of service. Include booking conditions, responsibilities, liability limitations..."
                className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
              {!formSettings.termsOfService && (
                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                  No terms of service set - recommended for legal compliance
                </p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Refund Policy
              </label>
              <textarea
                rows={6}
                value={formSettings.refundPolicy || ''}
                onChange={(e) => setFormSettings({ ...formSettings, refundPolicy: e.target.value })}
                placeholder="Enter your refund policy. Explain refund conditions, timeframes, and procedures..."
                className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
              {!formSettings.refundPolicy && (
                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">
                  No refund policy set - recommended for booking services
                </p>
              )}
            </div>
          </div>
        );

      default:
        // Handle dynamic module tabs
        if (activeTab.startsWith('module-')) {
          const moduleSlug = activeTab.replace('module-', '');
          const module = activeModules.find(m => m.slug === moduleSlug);
          
          if (!module) return null;
          
          const moduleSettings = (formSettings.moduleSettings as Record<string, Record<string, string | number>> || {})[moduleSlug] || {};
          
          if (module.template_type === 'multi_day_booking') {
            // Multi-day booking settings (like chalets/rooms)
            return (
              <div className="space-y-8">
                <div className="bg-gradient-to-r from-emerald-50 to-teal-50 dark:from-emerald-900/20 dark:to-teal-900/20 rounded-2xl p-4 border border-emerald-100 dark:border-emerald-800 mb-4">
                  <h3 className="font-medium text-slate-900 dark:text-white mb-2">{module.name} Settings</h3>
                  <p className="text-sm text-slate-600 dark:text-slate-400">
                    Configure check-in/out times, deposit requirements, and policies for {module.name.toLowerCase()}.
                  </p>
                </div>
                
                <div>
                  <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Check-in & Check-out</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                        Check-in Time
                      </label>
                      <input
                        type="text"
                        value={moduleSettings.checkIn as string || ''}
                        onChange={(e) => updateModuleSetting(moduleSlug, 'checkIn', e.target.value)}
                        placeholder="e.g., 3:00 PM"
                        className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                        Check-out Time
                      </label>
                      <input
                        type="text"
                        value={moduleSettings.checkOut as string || ''}
                        onChange={(e) => updateModuleSetting(moduleSlug, 'checkOut', e.target.value)}
                        placeholder="e.g., 12:00 PM"
                        className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                      />
                    </div>
                  </div>
                </div>

                <div className="bg-gradient-to-r from-emerald-50 to-teal-50 dark:from-emerald-900/20 dark:to-teal-900/20 rounded-2xl p-6 border border-emerald-100 dark:border-emerald-800">
                  <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4 flex items-center gap-2">
                    <CreditCard className="w-5 h-5 text-emerald-600" />
                    Deposit Configuration
                  </h3>
                  <div className="mb-6">
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">
                      Deposit Percentage
                    </label>
                    <div className="relative">
                      <input
                        type="number"
                        min="0"
                        max="100"
                        value={moduleSettings.depositPercent as number || 0}
                        onChange={(e) => updateModuleSetting(moduleSlug, 'depositPercent', Math.max(0, Math.min(100, parseInt(e.target.value) || 0)).toString())}
                        placeholder="30"
                        className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400">%</span>
                    </div>
                  </div>
                </div>

                <div>
                  <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Cancellation Policy</h3>
                  <textarea
                    rows={4}
                    value={moduleSettings.cancellationPolicy as string || ''}
                    onChange={(e) => updateModuleSetting(moduleSlug, 'cancellationPolicy', e.target.value)}
                    placeholder="Describe your cancellation policy..."
                    className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                  />
                </div>
              </div>
            );
          } else if (module.template_type === 'session_access') {
            // Session-based access settings (like pool, gym, spa)
            return (
              <div className="space-y-6">
                <div className="bg-gradient-to-r from-blue-50 to-cyan-50 dark:from-blue-900/20 dark:to-cyan-900/20 rounded-2xl p-4 border border-blue-100 dark:border-blue-800 mb-4">
                  <h3 className="font-medium text-slate-900 dark:text-white mb-2">{module.name} Settings</h3>
                  <p className="text-sm text-slate-600 dark:text-slate-400">
                    Configure pricing and capacity for {module.name.toLowerCase()} sessions.
                  </p>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                      Adult Price ($)
                    </label>
                    <input
                      type="number"
                      value={moduleSettings.adultPrice as number || ''}
                      onChange={(e) => updateModuleSetting(moduleSlug, 'adultPrice', e.target.value)}
                      placeholder="25.00"
                      className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                      Child Price ($)
                    </label>
                    <input
                      type="number"
                      value={moduleSettings.childPrice as number || ''}
                      onChange={(e) => updateModuleSetting(moduleSlug, 'childPrice', e.target.value)}
                      placeholder="15.00"
                      className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                      Infant Price ($)
                    </label>
                    <input
                      type="number"
                      value={moduleSettings.infantPrice as number || ''}
                      onChange={(e) => updateModuleSetting(moduleSlug, 'infantPrice', e.target.value)}
                      placeholder="0.00"
                      className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                      Max Capacity
                    </label>
                    <input
                      type="number"
                      value={moduleSettings.capacity as number || ''}
                      onChange={(e) => updateModuleSetting(moduleSlug, 'capacity', e.target.value)}
                      placeholder="100"
                      className="w-full px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                    />
                  </div>
                </div>
              </div>
            );
          }
        }
        return null;
    }
  };

  if (!formSettings) return null;
  if (loading) return <div className="p-8 text-center text-muted-foreground">Loading settings...</div>;

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="mb-8"
      >
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
              <Settings className="w-8 h-8 text-primary-600" />
              {t('settings')}
            </h1>
            <p className="text-slate-600 dark:text-slate-400 mt-2">
              Manage your resort settings, contact information, pricing, and policies
            </p>
          </div>

          <Button
            onClick={handleSave}
            disabled={isSaving}
            className="flex items-center gap-2"
          >
            <Save className="w-4 h-4" />
            {isSaving ? 'Saving...' : tCommon('save')}
          </Button>
        </div>
      </motion.div>

      <div className="flex flex-wrap gap-2 mb-6">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl transition-all ${
              activeTab === tab.id
                ? 'bg-primary-100 dark:bg-primary-900/40 text-primary-700 dark:text-primary-300 font-medium'
                : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700 border border-slate-200 dark:border-slate-700'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <Card className="border border-slate-200 dark:border-slate-700">
        <CardContent className="p-6">
          {renderTabContent()}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { toast } from 'sonner';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { CardSkeleton } from '@/components/ui/Skeleton';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import { useSocket } from '@/lib/socket';
import {
  CreditCard,
  Banknote,
  Search,
  Filter,
  RefreshCw,
  CheckCircle2,
  Clock,
  XCircle,
  ArrowUpDown,
  Download,
  DollarSign,
  TrendingUp,
  Settings as SettingsIcon,
  Save,
} from 'lucide-react';

interface Payment {
  id: string;
  amount: number;
  payment_method: 'cash' | 'card' | 'stripe';
  status: 'pending' | 'completed' | 'failed' | 'refunded';
  reference_type: string;
  reference_id: string;
  created_at: string;
  users?: {
    full_name: string;
    email: string;
  };
}

interface PaymentStats {
  totalToday: number;
  totalPending: number;
  totalCompleted: number;
  transactionCount: number;
}

export default function AdminPaymentsPage() {
  const t = useTranslations('admin');
  const [payments, setPayments] = useState<Payment[]>([]);
  const [stats, setStats] = useState<PaymentStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [methodFilter, setMethodFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [exporting, setExporting] = useState(false);
  const [activeTab, setActiveTab] = useState<'transactions' | 'settings'>('transactions');
  const [savingSettings, setSavingSettings] = useState(false);
  const [paymentSettings, setPaymentSettings] = useState({
    stripePublicKey: '',
    stripeSecretKey: '',
    stripeWebhookSecret: '',
    stripeMode: 'test' as 'test' | 'live',
    currency: 'USD',
  });
  const { socket } = useSocket();

  const exportPayments = async () => {
    try {
      setExporting(true);
      // Filter payments based on current filters
      const dataToExport = filteredPayments;

      // Create CSV content
      const headers = ['Date', 'Amount', 'Method', 'Status', 'Reference Type', 'Customer'];
      const rows = dataToExport.map(p => [
        new Date(p.created_at).toLocaleDateString(),
        p.amount.toFixed(2),
        p.payment_method,
        p.status,
        p.reference_type,
        p.users?.full_name || 'Guest'
      ]);

      const csvContent = [
        headers.join(','),
        ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
      ].join('\n');

      // Download file
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `payments_export_${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast.success('Payments exported successfully');
    } catch (error) {
      toast.error('Failed to export payments');
    } finally {
      setExporting(false);
    }
  };

  const fetchPayments = useCallback(async () => {
    try {
      const response = await api.get('/payments/transactions');
      setPayments(response.data.data || []);

      // Calculate stats
      const today = new Date().toISOString().split('T')[0];
      const todayPayments = (response.data.data || []).filter(
        (p: Payment) => p.created_at.startsWith(today)
      );

      setStats({
        totalToday: todayPayments.reduce((sum: number, p: Payment) => sum + p.amount, 0),
        totalPending: (response.data.data || []).filter((p: Payment) => p.status === 'pending').length,
        totalCompleted: (response.data.data || []).filter((p: Payment) => p.status === 'completed').length,
        transactionCount: (response.data.data || []).length,
      });
    } catch (error) {
      toast.error('Failed to fetch payments');
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchSettings = useCallback(async () => {
    try {
      const response = await api.get('/admin/settings');
      if (response.data.success && response.data.data.payments) {
        setPaymentSettings(response.data.data.payments);
      }
    } catch (error) {
      console.error('Failed to fetch payment settings:', error);
    }
  }, []);

  useEffect(() => {
    fetchPayments();
    fetchSettings();
  }, [fetchPayments, fetchSettings]);

  const saveSettings = async () => {
    try {
      setSavingSettings(true);
      await api.put('/admin/settings', {
        key: 'payments',
        value: paymentSettings
      });
      toast.success('Payment settings saved successfully');
    } catch (error) {
      toast.error('Failed to save payment settings');
    } finally {
      setSavingSettings(false);
    }
  };

  const handleRefund = async (paymentId: string) => {
    const reason = prompt('Please enter the reason for the refund:');
    if (reason === null) return;

    try {
      await api.post(`/payments/transactions/${paymentId}/refund`, { reason });
      toast.success('Refund processed successfully');
      fetchPayments();
    } catch (error: unknown) {
      const axiosError = error as { response?: { data?: { error?: string } } };
      toast.error(axiosError.response?.data?.error || 'Failed to process refund');
    }
  };

  // Real-time payment updates
  useEffect(() => {
    if (socket) {
      socket.on('payment:new', (payment: Payment) => {
        setPayments((prev) => [payment, ...prev]);
        toast.success(`New payment received: ${formatCurrency(payment.amount)}`);
      });

      socket.on('payment:updated', (payment: Payment) => {
        setPayments((prev) =>
          prev.map((p) => (p.id === payment.id ? payment : p))
        );
      });

      return () => {
        socket.off('payment:new');
        socket.off('payment:updated');
      };
    }
  }, [socket]);

  const filteredPayments = payments
    .filter((p) => {
      if (statusFilter !== 'all' && p.status !== statusFilter) return false;
      if (methodFilter !== 'all' && p.payment_method !== methodFilter) return false;
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        return (
          p.id.toLowerCase().includes(query) ||
          p.reference_type.toLowerCase().includes(query) ||
          p.users?.full_name?.toLowerCase().includes(query) ||
          p.users?.email?.toLowerCase().includes(query)
        );
      }
      return true;
    })
    .sort((a, b) => {
      const dateA = new Date(a.created_at).getTime();
      const dateB = new Date(b.created_at).getTime();
      return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
    });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed':
        return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400';
      case 'pending':
        return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400';
      case 'failed':
        return 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400';
      case 'refunded':
        return 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400';
    }
  };

  const getMethodIcon = (method: string) => {
    switch (method) {
      case 'card':
      case 'stripe':
        return <CreditCard className="w-4 h-4" />;
      case 'cash':
        return <Banknote className="w-4 h-4" />;
      default:
        return <DollarSign className="w-4 h-4" />;
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <CardSkeleton key={i} />
          ))}
        </div>
        <CardSkeleton />
      </div>
    );
  }

  return (
    <motion.div
      variants={staggerContainer}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
            Payments
          </h1>
          <p className="text-slate-500 dark:text-slate-400">
            Manage and track all payment transactions
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={fetchPayments}>
            <RefreshCw className="w-4 h-4 mr-2" />
            Refresh
          </Button>
          <Button variant="outline" onClick={exportPayments} disabled={exporting}>
            <Download className={`w-4 h-4 mr-2 ${exporting ? 'animate-pulse' : ''}`} />
            {exporting ? 'Exporting...' : 'Export'}
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 dark:border-slate-700">
        <button
          onClick={() => setActiveTab('transactions')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'transactions'
            ? 'border-blue-600 text-blue-600'
            : 'border-transparent text-slate-500 hover:text-slate-700'
            }`}
        >
          Transactions
        </button>
        <button
          onClick={() => setActiveTab('settings')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'settings'
            ? 'border-blue-600 text-blue-600'
            : 'border-transparent text-slate-500 hover:text-slate-700'
            }`}
        >
          Provider Config
        </button>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'transactions' ? (
          <motion.div
            key="transactions"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="space-y-6"
          >
            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <motion.div variants={fadeInUp}>
                <Card>
                  <CardContent className="p-4">
                    <div className="flex items-center gap-3">
                      <div className="p-2 rounded-lg bg-green-100 dark:bg-green-900/30">
                        <DollarSign className="w-5 h-5 text-green-600" />
                      </div>
                      <div>
                        <p className="text-sm text-slate-500 dark:text-slate-400">Total Today</p>
                        <p className="text-2xl font-bold text-slate-900 dark:text-white">
                          {formatCurrency(stats?.totalToday || 0)}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
              <motion.div variants={fadeInUp}>
                <Card>
                  <CardContent className="p-4">
                    <div className="flex items-center gap-3">
                      <div className="p-2 rounded-lg bg-blue-100 dark:bg-blue-900/30">
                        <TrendingUp className="w-5 h-5 text-blue-600" />
                      </div>
                      <div>
                        <p className="text-sm text-slate-500 dark:text-slate-400">Total Completed</p>
                        <p className="text-2xl font-bold text-slate-900 dark:text-white">
                          {stats?.totalCompleted || 0}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
              <motion.div variants={fadeInUp}>
                <Card>
                  <CardContent className="p-4">
                    <div className="flex items-center gap-3">
                      <div className="p-2 rounded-lg bg-yellow-100 dark:bg-yellow-900/30">
                        <Clock className="w-5 h-5 text-yellow-600" />
                      </div>
                      <div>
                        <p className="text-sm text-slate-500 dark:text-slate-400">Pending</p>
                        <p className="text-2xl font-bold text-slate-900 dark:text-white">
                          {stats?.totalPending || 0}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
              <motion.div variants={fadeInUp}>
                <Card>
                  <CardContent className="p-4">
                    <div className="flex items-center gap-3">
                      <div className="p-2 rounded-lg bg-slate-100 dark:bg-slate-800">
                        <Search className="w-5 h-5 text-slate-600" />
                      </div>
                      <div>
                        <p className="text-sm text-slate-500 dark:text-slate-400">Total Transactions</p>
                        <p className="text-2xl font-bold text-slate-900 dark:text-white">
                          {stats?.transactionCount || 0}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            </div>

            {/* Filters */}
            <Card>
              <CardContent className="p-4">
                <div className="flex flex-col md:flex-row gap-4">
                  <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input
                      type="text"
                      placeholder="Search transactions..."
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                  </div>
                  <div className="flex gap-2">
                    <select
                      value={statusFilter}
                      onChange={(e) => setStatusFilter(e.target.value)}
                      className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white outline-none"
                    >
                      <option value="all">All Status</option>
                      <option value="pending">Pending</option>
                      <option value="completed">Completed</option>
                      <option value="failed">Failed</option>
                      <option value="refunded">Refunded</option>
                    </select>
                    <select
                      value={methodFilter}
                      onChange={(e) => setMethodFilter(e.target.value)}
                      className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white outline-none"
                    >
                      <option value="all">All Methods</option>
                      <option value="cash">Cash</option>
                      <option value="card">Card</option>
                      <option value="stripe">Stripe</option>
                    </select>
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => setSortOrder(sortOrder === 'desc' ? 'asc' : 'desc')}
                    >
                      <ArrowUpDown className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Table */}
            <Card className="overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-200 dark:border-slate-700">
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Date</th>
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">ID</th>
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Customer</th>
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Reference</th>
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Amount</th>
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Method</th>
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Status</th>
                      <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
                    {filteredPayments.length === 0 ? (
                      <tr>
                        <td colSpan={8} className="px-6 py-12 text-center text-slate-500">
                          No transactions found
                        </td>
                      </tr>
                    ) : (
                      filteredPayments.map((payment) => (
                        <tr key={payment.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                          <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-400 whitespace-nowrap">
                            {formatDate(payment.created_at)}
                          </td>
                          <td className="px-6 py-4 text-sm font-mono text-slate-500 whitespace-nowrap">
                            {payment.id.slice(0, 8)}...
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="text-sm font-medium text-slate-900 dark:text-white">
                              {payment.users?.full_name || 'Guest'}
                            </div>
                            <div className="text-xs text-slate-500">
                              {payment.users?.email || 'No email'}
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className="text-xs font-medium px-2 py-1 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">
                              {payment.reference_type}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-sm font-bold text-slate-900 dark:text-white whitespace-nowrap">
                            {formatCurrency(payment.amount)}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <div className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400 capitalize">
                              {getMethodIcon(payment.payment_method)}
                              {payment.payment_method}
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(payment.status)}`}>
                              {payment.status}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            {payment.status === 'completed' && (
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleRefund(payment.id)}
                              >
                                Refund
                              </Button>
                            )}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </Card>
          </motion.div>
        ) : (
          <motion.div
            key="settings"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="grid grid-cols-1 lg:grid-cols-2 gap-6"
          >
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <CreditCard className="w-5 h-5 text-blue-600" />
                  Stripe Configuration
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Stripe Mode
                  </label>
                  <select
                    value={paymentSettings.stripeMode}
                    onChange={(e) => setPaymentSettings({ ...paymentSettings, stripeMode: e.target.value as any })}
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                  >
                    <option value="test">Test Mode</option>
                    <option value="live">Live Mode</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Public Key
                  </label>
                  <input
                    type="password"
                    value={paymentSettings.stripePublicKey}
                    onChange={(e) => setPaymentSettings({ ...paymentSettings, stripePublicKey: e.target.value })}
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                    placeholder="pk_test_..."
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Secret Key
                  </label>
                  <input
                    type="password"
                    value={paymentSettings.stripeSecretKey}
                    onChange={(e) => setPaymentSettings({ ...paymentSettings, stripeSecretKey: e.target.value })}
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                    placeholder="sk_test_..."
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Webhook Secret
                  </label>
                  <input
                    type="password"
                    value={paymentSettings.stripeWebhookSecret}
                    onChange={(e) => setPaymentSettings({ ...paymentSettings, stripeWebhookSecret: e.target.value })}
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                    placeholder="whsec_..."
                  />
                </div>
                <div className="pt-4">
                  <Button
                    className="w-full"
                    onClick={saveSettings}
                    disabled={savingSettings}
                  >
                    <Save className="w-4 h-4 mr-2" />
                    {savingSettings ? 'Saving...' : 'Save Configuration'}
                  </Button>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <DollarSign className="w-5 h-5 text-green-600" />
                  General Payment Settings
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Default Currency
                  </label>
                  <select
                    value={paymentSettings.currency}
                    onChange={(e) => setPaymentSettings({ ...paymentSettings, currency: e.target.value })}
                    className="w-full px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800"
                  >
                    <option value="USD">USD ($)</option>
                    <option value="EUR">EUR (€)</option>
                    <option value="GBP">GBP (£)</option>
                    <option value="LBP">LBP (ل.ل)</option>
                  </select>
                </div>
                <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-100 dark:border-blue-800">
                  <p className="text-sm text-blue-700 dark:text-blue-300">
                    <strong>Note:</strong> Stripe settings will override environment variables if configured here. Ensure keys match the selected mode.
                  </p>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  Percent,
  Plus,
  Trash2,
  Settings,
  Save,
  AlertCircle,
  CheckCircle,
  Info,
  Globe,
  Building2,
  Loader2,
  Edit2,
  X
} from 'lucide-react';
import { toast } from 'sonner';
import api from '@/lib/api';

interface TaxRate {
  id: string;
  name: string;
  rate: number;
  type: 'vat' | 'sales' | 'service' | 'tourism' | 'custom';
  applies_to: string[];
  is_default: boolean;
  is_compound: boolean;
  jurisdiction?: string;
  description?: string;
  created_at: string;
}

interface TaxConfiguration {
  default_rate: number;
  tax_included_in_price: boolean;
  show_tax_breakdown: boolean;
  rounding_method: 'round' | 'floor' | 'ceil';
  decimal_places: number;
  tax_number?: string;
  tax_name_display?: string;
  rates: TaxRate[];
}

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

const taxTypes = [
  { value: 'vat', label: 'VAT (Value Added Tax)', description: 'Standard consumption tax' },
  { value: 'sales', label: 'Sales Tax', description: 'Point-of-sale tax' },
  { value: 'service', label: 'Service Charge', description: 'Hospitality service fee' },
  { value: 'tourism', label: 'Tourism Tax', description: 'Destination/bed tax' },
  { value: 'custom', label: 'Custom', description: 'Other tax type' }
];

const categoryOptions = [
  { value: 'accommodation', label: 'Accommodation' },
  { value: 'food_beverage', label: 'Food & Beverage' },
  { value: 'spa', label: 'Spa & Wellness' },
  { value: 'pool', label: 'Pool Access' },
  { value: 'activities', label: 'Activities' },
  { value: 'retail', label: 'Retail/Shop' },
  { value: 'transportation', label: 'Transportation' },
  { value: 'events', label: 'Events' },
  { value: 'all', label: 'All Categories' }
];

// Demo default configuration
// FIX: Iteration 4 - Align default tax rate to 11% (Lebanon VAT)
const defaultConfig: TaxConfiguration = {
  default_rate: 11,
  tax_included_in_price: false,
  show_tax_breakdown: true,
  rounding_method: 'round',
  decimal_places: 2,
  tax_number: '',
  tax_name_display: 'Tax',
  rates: [
    {
      id: '1',
      name: 'Standard VAT',
      rate: 11,
      type: 'vat',
      applies_to: ['all'],
      is_default: true,
      is_compound: false,
      description: 'Standard VAT rate',
      created_at: new Date().toISOString()
    },
    {
      id: '2',
      name: 'Service Charge',
      rate: 12,
      type: 'service',
      applies_to: ['food_beverage'],
      is_default: false,
      is_compound: false,
      description: 'Restaurant service charge',
      created_at: new Date().toISOString()
    }
  ]
};

export default function TaxConfigurationPage() {
  const queryClient = useQueryClient();
  const [config, setConfig] = useState<TaxConfiguration>(defaultConfig);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingRate, setEditingRate] = useState<TaxRate | null>(null);
  const [newRate, setNewRate] = useState<Partial<TaxRate>>({
    name: '',
    rate: 0,
    type: 'vat',
    applies_to: ['all'],
    is_default: false,
    is_compound: false,
    description: ''
  });

  // Fetch configuration
  const { data: fetchedConfig, isLoading } = useQuery({
    queryKey: ['tax-configuration'],
    queryFn: async () => {
      try {
        const res = await api.get('/admin/settings/tax');
        return res.data?.data || defaultConfig;
      } catch {
        return defaultConfig;
      }
    }
  });

  useEffect(() => {
    if (fetchedConfig) {
      setConfig({
        ...defaultConfig,
        ...fetchedConfig,
        rates: fetchedConfig.rates || defaultConfig.rates
      });
    }
  }, [fetchedConfig]);

  // Save configuration
  const saveMutation = useMutation({
    mutationFn: async (data: TaxConfiguration) => {
      const res = await api.put('/admin/settings/tax', data);
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tax-configuration'] });
      toast.success('Tax configuration saved');
    },
    onError: () => {
      toast.error('Failed to save configuration');
    }
  });

  const handleSave = () => {
    saveMutation.mutate(config);
  };

  const handleAddRate = () => {
    if (!newRate.name || newRate.rate === undefined) {
      toast.error('Please fill in required fields');
      return;
    }
    const rate: TaxRate = {
      id: Date.now().toString(),
      name: newRate.name,
      rate: newRate.rate,
      type: newRate.type as TaxRate['type'],
      applies_to: newRate.applies_to || ['all'],
      is_default: newRate.is_default || false,
      is_compound: newRate.is_compound || false,
      description: newRate.description,
      created_at: new Date().toISOString()
    };
    
    // If new rate is default, remove default from others
    let updatedRates = config.rates;
    if (rate.is_default) {
      updatedRates = config.rates.map(r => ({ ...r, is_default: false }));
    }
    
    setConfig({ ...config, rates: [...updatedRates, rate] });
    setShowAddModal(false);
    setNewRate({
      name: '',
      rate: 0,
      type: 'vat',
      applies_to: ['all'],
      is_default: false,
      is_compound: false,
      description: ''
    });
    toast.success('Tax rate added');
  };

  const handleUpdateRate = () => {
    if (!editingRate) return;
    
    let updatedRates = config.rates.map(r => 
      r.id === editingRate.id ? editingRate : r
    );
    
    // If editing rate is now default, remove default from others
    if (editingRate.is_default) {
      updatedRates = updatedRates.map(r => 
        r.id === editingRate.id ? r : { ...r, is_default: false }
      );
    }
    
    setConfig({ ...config, rates: updatedRates });
    setEditingRate(null);
    toast.success('Tax rate updated');
  };

  const handleDeleteRate = (id: string) => {
    const rate = config.rates.find(r => r.id === id);
    if (rate?.is_default) {
      toast.error('Cannot delete the default tax rate');
      return;
    }
    if (confirm('Delete this tax rate?')) {
      setConfig({ ...config, rates: config.rates.filter(r => r.id !== id) });
      toast.success('Tax rate deleted');
    }
  };

  const handleSetDefault = (id: string) => {
    const updatedRates = config.rates.map(r => ({
      ...r,
      is_default: r.id === id
    }));
    setConfig({ ...config, rates: updatedRates });
    toast.success('Default tax rate updated');
  };

  const getTypeLabel = (type: string) => {
    return taxTypes.find(t => t.value === type)?.label || type;
  };

  const getCategoryLabels = (categories: string[]) => {
    if (categories.includes('all')) return 'All Categories';
    return categories
      .map(c => categoryOptions.find(o => o.value === c)?.label || c)
      .join(', ');
  };

  if (isLoading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 max-w-5xl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Tax Configuration</h1>
          <p className="text-slate-600 dark:text-slate-400">Configure tax rates for your resort</p>
        </div>
        <button
          onClick={handleSave}
          disabled={saveMutation.isPending}
          className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 disabled:opacity-50"
        >
          {saveMutation.isPending ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Save className="w-4 h-4" />
          )}
          Save Changes
        </button>
      </div>

      {/* General Settings */}
      <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 overflow-hidden">
        <div className="px-4 py-3 bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 flex items-center gap-2">
          <Settings className="w-4 h-4 text-slate-500" />
          <h2 className="font-semibold text-slate-900 dark:text-white">General Settings</h2>
        </div>
        <div className="p-6 space-y-6">
          <div className="grid grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Tax Display Name
              </label>
              <input
                type="text"
                value={config.tax_name_display || ''}
                onChange={(e) => setConfig({ ...config, tax_name_display: e.target.value })}
                placeholder="e.g., VAT, Sales Tax, GST"
                className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              />
              <p className="text-xs text-slate-500 mt-1">How tax appears on receipts</p>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Tax Registration Number
              </label>
              <input
                type="text"
                value={config.tax_number || ''}
                onChange={(e) => setConfig({ ...config, tax_number: e.target.value })}
                placeholder="e.g., VAT123456789"
                className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              />
              <p className="text-xs text-slate-500 mt-1">Displayed on invoices (optional)</p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-6">
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Default Tax Rate (%)
              </label>
              <input
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={config.default_rate}
                onChange={(e) => setConfig({ ...config, default_rate: parseFloat(e.target.value) || 0 })}
                className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Rounding Method
              </label>
              <select
                value={config.rounding_method}
                onChange={(e) => setConfig({ ...config, rounding_method: e.target.value as TaxConfiguration['rounding_method'] })}
                className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              >
                <option value="round">Standard Rounding</option>
                <option value="floor">Round Down</option>
                <option value="ceil">Round Up</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                Decimal Places
              </label>
              <select
                value={config.decimal_places}
                onChange={(e) => setConfig({ ...config, decimal_places: parseInt(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              >
                <option value={0}>0 (No decimals)</option>
                <option value={2}>2 (Standard)</option>
                <option value={3}>3 (High precision)</option>
              </select>
            </div>
          </div>

          <div className="flex flex-col gap-4">
            <label className="flex items-center gap-3">
              <input
                type="checkbox"
                checked={config.tax_included_in_price}
                onChange={(e) => setConfig({ ...config, tax_included_in_price: e.target.checked })}
                className="w-4 h-4 rounded border-slate-300 text-primary focus:ring-primary"
              />
              <div>
                <span className="text-sm font-medium text-slate-900 dark:text-white">Tax Included in Prices</span>
                <p className="text-xs text-slate-500">Prices shown already include tax (common in Europe)</p>
              </div>
            </label>
            <label className="flex items-center gap-3">
              <input
                type="checkbox"
                checked={config.show_tax_breakdown}
                onChange={(e) => setConfig({ ...config, show_tax_breakdown: e.target.checked })}
                className="w-4 h-4 rounded border-slate-300 text-primary focus:ring-primary"
              />
              <div>
                <span className="text-sm font-medium text-slate-900 dark:text-white">Show Tax Breakdown</span>
                <p className="text-xs text-slate-500">Display individual tax rates on receipts and invoices</p>
              </div>
            </label>
          </div>
        </div>
      </div>

      {/* Tax Rates */}
      <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 overflow-hidden">
        <div className="px-4 py-3 bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Percent className="w-4 h-4 text-slate-500" />
            <h2 className="font-semibold text-slate-900 dark:text-white">Tax Rates</h2>
          </div>
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 px-3 py-1.5 text-sm bg-primary text-white rounded-lg hover:bg-primary/90"
          >
            <Plus className="w-4 h-4" />
            Add Rate
          </button>
        </div>
        
        {config.rates.length === 0 ? (
          <div className="p-8 text-center">
            <Percent className="w-12 h-12 mx-auto text-slate-400 mb-3" />
            <p className="text-slate-600 dark:text-slate-400">No tax rates configured</p>
            <button
              onClick={() => setShowAddModal(true)}
              className="mt-4 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90"
            >
              Add Your First Tax Rate
            </button>
          </div>
        ) : (
          <div className="divide-y divide-slate-200 dark:divide-slate-700">
            {config.rates.map((rate) => (
              <div key={rate.id} className="p-4 hover:bg-slate-50 dark:hover:bg-slate-700/30">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 rounded-xl bg-primary/10 flex items-center justify-center">
                      <span className="text-xl font-bold text-primary">{rate.rate}%</span>
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-semibold text-slate-900 dark:text-white">{rate.name}</span>
                        {rate.is_default && (
                          <span className="px-2 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 text-xs rounded-full">
                            Default
                          </span>
                        )}
                        {rate.is_compound && (
                          <span className="px-2 py-0.5 bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300 text-xs rounded-full">
                            Compound
                          </span>
                        )}
                      </div>
                      <div className="text-sm text-slate-600 dark:text-slate-400 mt-1">
                        {getTypeLabel(rate.type)} • {getCategoryLabels(rate.applies_to)}
                      </div>
                      {rate.description && (
                        <p className="text-xs text-slate-500 mt-1">{rate.description}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {!rate.is_default && (
                      <button
                        onClick={() => handleSetDefault(rate.id)}
                        className="px-3 py-1.5 text-sm text-primary hover:bg-primary/10 rounded-lg"
                      >
                        Set Default
                      </button>
                    )}
                    <button
                      onClick={() => setEditingRate(rate)}
                      className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDeleteRate(rate.id)}
                      disabled={rate.is_default}
                      className="p-2 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-red-600 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Info Box */}
      <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl p-4">
        <div className="flex items-start gap-3">
          <Info className="w-5 h-5 text-blue-600 dark:text-blue-400 flex-shrink-0 mt-0.5" />
          <div>
            <h3 className="font-medium text-blue-800 dark:text-blue-200">Tax Configuration Tips</h3>
            <ul className="text-sm text-blue-700 dark:text-blue-300 mt-2 space-y-1">
              <li>• <strong>Compound taxes</strong> are calculated on top of other taxes (e.g., PST on GST+subtotal)</li>
              <li>• Use category-specific rates for different tax rules (e.g., lower VAT on accommodation)</li>
              <li>• The <strong>default rate</strong> applies when no specific category rate is configured</li>
              <li>• Consult with a tax professional for jurisdiction-specific requirements</li>
            </ul>
          </div>
        </div>
      </div>

      {/* Add Rate Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 max-w-md w-full mx-4">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-slate-900 dark:text-white">Add Tax Rate</h2>
              <button onClick={() => setShowAddModal(false)} className="p-1">
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  Name *
                </label>
                <input
                  type="text"
                  value={newRate.name}
                  onChange={(e) => setNewRate({ ...newRate, name: e.target.value })}
                  placeholder="e.g., Standard VAT"
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Rate (%) *
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    max="100"
                    value={newRate.rate}
                    onChange={(e) => setNewRate({ ...newRate, rate: parseFloat(e.target.value) || 0 })}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Type
                  </label>
                  <select
                    value={newRate.type}
                    onChange={(e) => setNewRate({ ...newRate, type: e.target.value as TaxRate['type'] })}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  >
                    {taxTypes.map(t => (
                      <option key={t.value} value={t.value}>{t.label}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  Applies To
                </label>
                <select
                  multiple
                  value={newRate.applies_to}
                  onChange={(e) => {
                    const values = Array.from(e.target.selectedOptions, opt => opt.value);
                    setNewRate({ ...newRate, applies_to: values });
                  }}
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white h-32"
                >
                  {categoryOptions.map(c => (
                    <option key={c.value} value={c.value}>{c.label}</option>
                  ))}
                </select>
                <p className="text-xs text-slate-500 mt-1">Hold Ctrl/Cmd to select multiple</p>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  Description
                </label>
                <input
                  type="text"
                  value={newRate.description || ''}
                  onChange={(e) => setNewRate({ ...newRate, description: e.target.value })}
                  placeholder="Optional description"
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                />
              </div>
              <div className="flex flex-col gap-2">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={newRate.is_default}
                    onChange={(e) => setNewRate({ ...newRate, is_default: e.target.checked })}
                    className="w-4 h-4 rounded"
                  />
                  <span className="text-sm text-slate-700 dark:text-slate-300">Set as default rate</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={newRate.is_compound}
                    onChange={(e) => setNewRate({ ...newRate, is_compound: e.target.checked })}
                    className="w-4 h-4 rounded"
                  />
                  <span className="text-sm text-slate-700 dark:text-slate-300">Compound tax (calculated on subtotal + other taxes)</span>
                </label>
              </div>
              <div className="flex gap-3 pt-2">
                <button
                  onClick={() => setShowAddModal(false)}
                  className="flex-1 py-2 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 rounded-lg"
                >
                  Cancel
                </button>
                <button
                  onClick={handleAddRate}
                  className="flex-1 py-2 bg-primary text-white rounded-lg hover:bg-primary/90"
                >
                  Add Rate
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Edit Rate Modal */}
      {editingRate && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 max-w-md w-full mx-4">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-slate-900 dark:text-white">Edit Tax Rate</h2>
              <button onClick={() => setEditingRate(null)} className="p-1">
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Name</label>
                <input
                  type="text"
                  value={editingRate.name}
                  onChange={(e) => setEditingRate({ ...editingRate, name: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Rate (%)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={editingRate.rate}
                    onChange={(e) => setEditingRate({ ...editingRate, rate: parseFloat(e.target.value) || 0 })}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Type</label>
                  <select
                    value={editingRate.type}
                    onChange={(e) => setEditingRate({ ...editingRate, type: e.target.value as TaxRate['type'] })}
                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  >
                    {taxTypes.map(t => (
                      <option key={t.value} value={t.value}>{t.label}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Description</label>
                <input
                  type="text"
                  value={editingRate.description || ''}
                  onChange={(e) => setEditingRate({ ...editingRate, description: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                />
              </div>
              <div className="flex flex-col gap-2">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={editingRate.is_default}
                    onChange={(e) => setEditingRate({ ...editingRate, is_default: e.target.checked })}
                    className="w-4 h-4 rounded"
                  />
                  <span className="text-sm text-slate-700 dark:text-slate-300">Set as default rate</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={editingRate.is_compound}
                    onChange={(e) => setEditingRate({ ...editingRate, is_compound: e.target.checked })}
                    className="w-4 h-4 rounded"
                  />
                  <span className="text-sm text-slate-700 dark:text-slate-300">Compound tax</span>
                </label>
              </div>
              <div className="flex gap-3 pt-2">
                <button
                  onClick={() => setEditingRate(null)}
                  className="flex-1 py-2 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 rounded-lg"
                >
                  Cancel
                </button>
                <button
                  onClick={handleUpdateRate}
                  className="flex-1 py-2 bg-primary text-white rounded-lg hover:bg-primary/90"
                >
                  Save Changes
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { toast } from 'sonner';
import api from '@/lib/api';
import {
  Languages,
  AlertTriangle,
  AlertCircle,
  Check,
  ChevronDown,
  ChevronRight,
  RefreshCw,
  Wand2,
  Edit3,
  Save,
  X,
  FileText,
  Utensils,
  Home,
  Waves,
  Cookie,
  Package,
  Plus,
  Trash2,
  Globe,
  Code,
  FileJson,
  Settings,
} from 'lucide-react';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';

interface MissingTranslation {
  table: string;
  tableDisplayName: string;
  id: string;
  itemLabel: string;
  field: string;
  originalValue: string;
  missingLanguages: string[];
}

interface TranslationStats {
  overall: { total: number; translated: number; missing: number };
  byTable: Record<string, { total: number; translated: number; missing: number }>;
  percentage: number;
}

interface GroupedMissing {
  displayName: string;
  items: MissingTranslation[];
}

interface SupportedLanguage {
  id?: string;
  code: string;
  name: string;
  native_name: string;
  direction: 'ltr' | 'rtl';
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
}

interface FrontendComparison {
  totalKeys: number;
  allKeys: string[];
  languages: Record<string, {
    file: string;
    keyCount: number;
    missingKeys: string[];
    missingCount: number;
  }>;
}

const getTableIcon = (table: string) => {
  const icons: Record<string, typeof Package> = {
    modules: Package,
    menu_categories: Utensils,
    menu_items: Utensils,
    chalets: Home,
    snack_items: Cookie,
    chalet_add_ons: Home,
    pool_sessions: Waves,
  };
  return icons[table] || FileText;
};

export default function TranslationsPage() {
  // Translations
  const t = useTranslations('adminTranslations');
  const tc = useTranslations('adminCommon');
  
  // Tabs
  const [activeTab, setActiveTab] = useState<'database' | 'frontend' | 'languages'>('database');
  
  // Translation service status
  const [serviceStatus, setServiceStatus] = useState<{
    provider: string;
    configured: boolean;
    apiKeySet: boolean;
    message: string;
  } | null>(null);
  
  // Database translations state
  const [stats, setStats] = useState<TranslationStats | null>(null);
  const [missing, setMissing] = useState<Record<string, GroupedMissing>>({});
  const [loading, setLoading] = useState(true);
  const [expandedTables, setExpandedTables] = useState<Set<string>>(new Set());
  const [editingItem, setEditingItem] = useState<{ table: string; id: string; field: string; lang: string } | null>(null);
  const [editValue, setEditValue] = useState('');
  
  // Language management state
  const [languages, setLanguages] = useState<SupportedLanguage[]>([]);
  const [showAddLanguage, setShowAddLanguage] = useState(false);
  const [newLanguage, setNewLanguage] = useState<Partial<SupportedLanguage>>({
    code: '',
    name: '',
    native_name: '',
    direction: 'ltr',
    is_active: true,
  });
  
  // Frontend translations state
  const [frontendComparison, setFrontendComparison] = useState<FrontendComparison | null>(null);
  const [expandedLanguages, setExpandedLanguages] = useState<Set<string>>(new Set());
  const [editingFrontendKey, setEditingFrontendKey] = useState<{ lang: string; key: string } | null>(null);
  const [frontendEditValue, setFrontendEditValue] = useState('');
  const [autoTranslating, setAutoTranslating] = useState<string | null>(null);
  const [batchTranslating, setBatchTranslating] = useState<string | null>(null);

  // Fetch database translations
  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [statsRes, missingRes, statusRes] = await Promise.all([
        api.get('/admin/translations/stats'),
        api.get('/admin/translations/missing'),
        api.get('/admin/translations/status'),
      ]);

      if (statsRes.data?.success) {
        setStats(statsRes.data.data);
      }
      if (missingRes.data?.success) {
        setMissing(missingRes.data.data.byTable || {});
      }
      if (statusRes.data?.success) {
        setServiceStatus({
          provider: statusRes.data.provider,
          configured: statusRes.data.configured,
          apiKeySet: statusRes.data.apiKeySet,
          message: statusRes.data.message,
        });
      }
    } catch {
      toast.error(t('errors.failedToLoad'));
    } finally {
      setLoading(false);
    }
  }, [t]);

  // Fetch supported languages
  const fetchLanguages = useCallback(async () => {
    try {
      const res = await api.get('/admin/translations/languages');
      if (res.data?.success) {
        setLanguages(res.data.data || []);
      }
    } catch {
      toast.error(t('errors.failedToLoad'));
    }
  }, [t]);

  // Fetch frontend translation comparison
  const fetchFrontendComparison = useCallback(async () => {
    try {
      const res = await api.get('/admin/translations/frontend/compare');
      if (res.data?.success) {
        setFrontendComparison(res.data.data);
      }
    } catch {
      toast.error(t('errors.failedToLoad'));
    }
  }, [t]);

  useEffect(() => {
    fetchData();
    fetchLanguages();
    fetchFrontendComparison();
  }, [fetchData, fetchLanguages, fetchFrontendComparison]);

  const toggleTable = (table: string) => {
    setExpandedTables(prev => {
      const next = new Set(prev);
      if (next.has(table)) {
        next.delete(table);
      } else {
        next.add(table);
      }
      return next;
    });
  };

  const startEdit = (table: string, id: string, field: string, lang: string) => {
    setEditingItem({ table, id, field, lang });
    setEditValue('');
  };

  const saveTranslation = async () => {
    if (!editingItem) return;

    try {
      await api.put(`/admin/translations/${editingItem.table}/${editingItem.id}`, {
        field: editingItem.field,
        language: editingItem.lang,
        value: editValue,
      });

      toast.success(t('translationSaved'));
      setEditingItem(null);
      setEditValue('');
      fetchData();
    } catch {
      toast.error(t('errors.failedToSave'));
    }
  };

  const autoTranslateItem = async (table: string, id: string) => {
    setAutoTranslating(`${table}-${id}`);
    try {
      const res = await api.post('/admin/translations/auto-translate', { table, id });
      if (res.data?.success) {
        toast.success(t('autoTranslated'));
        fetchData();
      }
    } catch {
      toast.error(t('errors.failedToTranslate'));
    } finally {
      setAutoTranslating(null);
    }
  };

  const batchAutoTranslate = async (table: string) => {
    setBatchTranslating(table);
    try {
      const res = await api.post('/admin/translations/batch-translate', { table });
      if (res.data?.success) {
        const { translated, errors } = res.data;
        toast.success(`Translated ${translated} items${errors?.length ? ` (${errors.length} errors)` : ''}`);
        fetchData();
      }
    } catch {
      toast.error(t('errors.failedToTranslate'));
    } finally {
      setBatchTranslating(null);
    }
  };

  // Language management functions
  const addLanguage = async () => {
    if (!newLanguage.code || !newLanguage.name || !newLanguage.native_name) {
      toast.error(t('errors.fillRequired'));
      return;
    }
    try {
      const res = await api.post('/admin/translations/languages', newLanguage);
      if (res.data?.success) {
        toast.success(t('languageAdded'));
        setShowAddLanguage(false);
        setNewLanguage({ code: '', name: '', native_name: '', direction: 'ltr', is_active: true });
        fetchLanguages();
      }
    } catch {
      toast.error(t('errors.failedToAddLanguage'));
    }
  };

  const deleteLanguage = async (code: string) => {
    if (code === 'en') {
      toast.error(t('languagesTab.cannotDeleteDefault'));
      return;
    }
    if (!confirm(`Are you sure you want to delete the ${code} language?`)) return;
    try {
      const res = await api.delete(`/admin/translations/languages/${code}`);
      if (res.data?.success) {
        toast.success(t('languageDeleted'));
        fetchLanguages();
      }
    } catch {
      toast.error(tc('errors.failedToDelete'));
    }
  };

  const toggleLanguageActive = async (code: string, isActive: boolean) => {
    try {
      const res = await api.put(`/admin/translations/languages/${code}`, { is_active: !isActive });
      if (res.data?.success) {
        toast.success(tc('success.updated'));
        fetchLanguages();
      }
    } catch {
      toast.error(tc('errors.failedToUpdate'));
    }
  };

  // Frontend translation functions
  const toggleLanguageExpand = (lang: string) => {
    setExpandedLanguages(prev => {
      const next = new Set(prev);
      if (next.has(lang)) {
        next.delete(lang);
      } else {
        next.add(lang);
      }
      return next;
    });
  };

  const saveFrontendTranslation = async () => {
    if (!editingFrontendKey) return;
    try {
      const res = await api.post('/admin/translations/frontend/update', {
        language: editingFrontendKey.lang,
        key: editingFrontendKey.key,
        value: frontendEditValue,
      });
      if (res.data?.success) {
        toast.success(t('translationSaved'));
        setEditingFrontendKey(null);
        setFrontendEditValue('');
        fetchFrontendComparison();
      }
    } catch {
      toast.error(t('errors.failedToSave'));
    }
  };

  if (loading && !stats) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <RefreshCw className="w-8 h-8 animate-spin text-primary-500" />
      </div>
    );
  }

  // Calculate combined stats
  const frontendPercentage = frontendComparison 
    ? Math.round(Object.entries(frontendComparison.languages).reduce((sum, [, data]) => {
        const langPercentage = frontendComparison.totalKeys > 0 
          ? ((frontendComparison.totalKeys - data.missingCount) / frontendComparison.totalKeys) * 100 
          : 100;
        return sum + langPercentage;
      }, 0) / Math.max(Object.keys(frontendComparison.languages).length, 1))
    : 0;
  
  const frontendMissingCount = frontendComparison 
    ? Object.values(frontendComparison.languages).reduce((sum, l) => sum + l.missingCount, 0)
    : 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            <Languages className="w-8 h-8 text-primary-500" />
            {t('title')}
          </h1>
          <p className="text-slate-600 dark:text-slate-400 mt-1">
            {t('subtitle')}
          </p>
        </div>
        <Button onClick={() => { fetchData(); fetchLanguages(); fetchFrontendComparison(); }} variant="outline" disabled={loading}>
          <RefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
          {t('frontendTab.refreshAll')}
        </Button>
      </div>

      {/* Combined Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Frontend UI Translations */}
        <Card className="border-2 border-blue-200 dark:border-blue-800">
          <CardContent className="p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2">
                <FileJson className="w-5 h-5 text-blue-500" />
                <h3 className="font-semibold text-slate-900 dark:text-white">Frontend UI Translations</h3>
              </div>
              <div className={`px-3 py-1 rounded-full text-sm font-medium ${
                frontendPercentage === 100 ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                frontendPercentage > 80 ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400' :
                'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
              }`}>
                {frontendPercentage}% Complete
              </div>
            </div>
            <p className="text-sm text-slate-500 dark:text-slate-400 mb-3">
              User interface text in JSON files (buttons, labels, messages)
            </p>
            <div className="flex items-center gap-4">
              <div className="flex-1 bg-slate-200 dark:bg-slate-700 rounded-full h-3">
                <div 
                  className={`h-3 rounded-full transition-all ${
                    frontendPercentage === 100 ? 'bg-green-500' : frontendPercentage > 80 ? 'bg-yellow-500' : 'bg-red-500'
                  }`}
                  style={{ width: `${frontendPercentage}%` }}
                />
              </div>
              <span className="text-sm font-medium text-slate-600 dark:text-slate-400">
                {frontendMissingCount} missing
              </span>
            </div>
          </CardContent>
        </Card>

        {/* Database Content Translations */}
        <Card className="border-2 border-purple-200 dark:border-purple-800">
          <CardContent className="p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2">
                <Settings className="w-5 h-5 text-purple-500" />
                <h3 className="font-semibold text-slate-900 dark:text-white">Database Content Translations</h3>
              </div>
              <div className={`px-3 py-1 rounded-full text-sm font-medium ${
                (stats?.percentage || 0) === 100 ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                (stats?.percentage || 0) > 50 ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400' :
                'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
              }`}>
                {stats?.percentage || 0}% Complete
              </div>
            </div>
            <p className="text-sm text-slate-500 dark:text-slate-400 mb-3">
              Menu items, chalets, pool sessions stored in database
            </p>
            <div className="flex items-center gap-4">
              <div className="flex-1 bg-slate-200 dark:bg-slate-700 rounded-full h-3">
                <div 
                  className={`h-3 rounded-full transition-all ${
                    (stats?.percentage || 0) === 100 ? 'bg-green-500' : (stats?.percentage || 0) > 50 ? 'bg-yellow-500' : 'bg-red-500'
                  }`}
                  style={{ width: `${stats?.percentage || 0}%` }}
                />
              </div>
              <span className="text-sm font-medium text-slate-600 dark:text-slate-400">
                {stats?.overall.missing || 0} missing
              </span>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-slate-200 dark:border-slate-700">
        <button
          onClick={() => setActiveTab('database')}
          className={`px-4 py-2 font-medium text-sm border-b-2 transition-colors ${
            activeTab === 'database'
              ? 'border-primary-500 text-primary-600 dark:text-primary-400'
              : 'border-transparent text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
          }`}
        >
          <Settings className="w-4 h-4 inline mr-2" />
          {t('tabs.database')}
        </button>
        <button
          onClick={() => setActiveTab('frontend')}
          className={`px-4 py-2 font-medium text-sm border-b-2 transition-colors ${
            activeTab === 'frontend'
              ? 'border-primary-500 text-primary-600 dark:text-primary-400'
              : 'border-transparent text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
          }`}
        >
          <FileJson className="w-4 h-4 inline mr-2" />
          {t('tabs.frontend')}
        </button>
        <button
          onClick={() => setActiveTab('languages')}
          className={`px-4 py-2 font-medium text-sm border-b-2 transition-colors ${
            activeTab === 'languages'
              ? 'border-primary-500 text-primary-600 dark:text-primary-400'
              : 'border-transparent text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
          }`}
        >
          <Globe className="w-4 h-4 inline mr-2" />
          {t('tabs.languages')} ({languages.length})
        </button>
      </div>

      {/* Languages Tab */}
      {activeTab === 'languages' && (
        <div className="space-y-4">
          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-lg font-semibold text-slate-900 dark:text-white">{t('languagesTab.title')}</h2>
                <Button onClick={() => setShowAddLanguage(true)} size="sm">
                  <Plus className="w-4 h-4 mr-2" />
                  {t('languagesTab.addLanguage')}
                </Button>
              </div>

              {/* Add Language Form */}
              <AnimatePresence>
                {showAddLanguage && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    exit={{ opacity: 0, height: 0 }}
                    className="mb-6 p-4 bg-slate-50 dark:bg-slate-800 rounded-lg"
                  >
                    <h3 className="font-medium mb-4 text-slate-900 dark:text-white">Add New Language</h3>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                          Code *
                        </label>
                        <Input
                          placeholder="e.g., de"
                          value={newLanguage.code}
                          onChange={(e) => setNewLanguage({ ...newLanguage, code: e.target.value.toLowerCase() })}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                          Name *
                        </label>
                        <Input
                          placeholder="e.g., German"
                          value={newLanguage.name}
                          onChange={(e) => setNewLanguage({ ...newLanguage, name: e.target.value })}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                          Native Name *
                        </label>
                        <Input
                          placeholder="e.g., Deutsch"
                          value={newLanguage.native_name}
                          onChange={(e) => setNewLanguage({ ...newLanguage, native_name: e.target.value })}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                          Direction
                        </label>
                        <select
                          className="w-full px-3 py-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                          value={newLanguage.direction}
                          onChange={(e) => setNewLanguage({ ...newLanguage, direction: e.target.value as 'ltr' | 'rtl' })}
                        >
                          <option value="ltr">Left to Right</option>
                          <option value="rtl">Right to Left</option>
                        </select>
                      </div>
                    </div>
                    <div className="flex gap-2 mt-4">
                      <Button onClick={addLanguage} size="sm">
                        <Save className="w-4 h-4 mr-2" />
                        Save
                      </Button>
                      <Button onClick={() => setShowAddLanguage(false)} variant="outline" size="sm">
                        <X className="w-4 h-4 mr-2" />
                        Cancel
                      </Button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Languages List */}
              <div className="space-y-2">
                {languages.map((lang) => (
                  <div
                    key={lang.code}
                    className="flex items-center justify-between p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg"
                  >
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 flex items-center justify-center bg-primary-100 dark:bg-primary-900/30 text-primary-600 rounded-lg font-bold text-sm">
                        {lang.code.toUpperCase()}
                      </div>
                      <div>
                        <p className="font-medium text-slate-900 dark:text-white">
                          {lang.name} 
                          <span className="ml-2 text-slate-500">({lang.native_name})</span>
                          {lang.is_default && (
                            <span className="ml-2 px-2 py-0.5 bg-primary-100 dark:bg-primary-900/30 text-primary-600 text-xs rounded">
                              Default
                            </span>
                          )}
                        </p>
                        <p className="text-sm text-slate-500">
                          Direction: {lang.direction.toUpperCase()} | 
                          Status: {lang.is_active ? 'Active' : 'Inactive'}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button
                        size="sm"
                        variant={lang.is_active ? 'outline' : 'primary'}
                        onClick={() => toggleLanguageActive(lang.code, lang.is_active)}
                      >
                        {lang.is_active ? 'Disable' : 'Enable'}
                      </Button>
                      {lang.code !== 'en' && (
                        <Button
                          size="sm"
                          variant="ghost"
                          className="text-red-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
                          onClick={() => deleteLanguage(lang.code)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Frontend JSON Files Tab */}
      {activeTab === 'frontend' && (
        <div className="space-y-4">
          {frontendComparison && (
            <>
              {/* Frontend Stats */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <Card>
                  <CardContent className="p-6">
                    <p className="text-sm text-slate-500 dark:text-slate-400">Total Translation Keys</p>
                    <p className="text-3xl font-bold text-slate-900 dark:text-white">{frontendComparison.totalKeys}</p>
                  </CardContent>
                </Card>
                <Card>
                  <CardContent className="p-6">
                    <p className="text-sm text-slate-500 dark:text-slate-400">Languages</p>
                    <p className="text-3xl font-bold text-primary-600">{Object.keys(frontendComparison.languages).length}</p>
                  </CardContent>
                </Card>
                <Card>
                  <CardContent className="p-6">
                    <p className="text-sm text-slate-500 dark:text-slate-400">Total Missing</p>
                    <p className="text-3xl font-bold text-red-600">
                      {Object.values(frontendComparison.languages).reduce((sum, l) => sum + l.missingCount, 0)}
                    </p>
                  </CardContent>
                </Card>
              </div>

              {/* Per-Language Status */}
              <Card>
                <CardContent className="p-6">
                  <h2 className="text-lg font-semibold mb-4 text-slate-900 dark:text-white">
                    <FileJson className="w-5 h-5 inline mr-2" />
                    Frontend Translation Files
                  </h2>
                  <p className="text-sm text-slate-500 mb-4">
                    These are the JSON translation files in <code className="bg-slate-100 dark:bg-slate-700 px-2 py-1 rounded">frontend/messages/</code>
                  </p>

                  <div className="space-y-4">
                    {Object.entries(frontendComparison.languages).map(([lang, data]) => {
                      const isExpanded = expandedLanguages.has(lang);
                      const percentage = frontendComparison.totalKeys > 0 
                        ? Math.round(((frontendComparison.totalKeys - data.missingCount) / frontendComparison.totalKeys) * 100)
                        : 100;

                      return (
                        <div key={lang} className="border border-slate-200 dark:border-slate-700 rounded-lg overflow-hidden">
                          <div 
                            className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/50 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800"
                            onClick={() => toggleLanguageExpand(lang)}
                          >
                            <div className="flex items-center gap-3">
                              {isExpanded ? <ChevronDown className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />}
                              <Code className="w-5 h-5 text-primary-500" />
                              <span className="font-medium text-slate-900 dark:text-white">{lang}.json</span>
                              <span className="text-sm text-slate-500">({data.keyCount} keys)</span>
                              {data.missingCount > 0 && (
                                <span className="px-2 py-0.5 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 text-xs rounded-full">
                                  {data.missingCount} missing
                                </span>
                              )}
                              {data.missingCount === 0 && (
                                <span className="px-2 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 text-xs rounded-full">
                                  <Check className="w-3 h-3 inline mr-1" />
                                  Complete
                                </span>
                              )}
                            </div>
                            <div className="flex items-center gap-4">
                              <div className="w-32 bg-slate-200 dark:bg-slate-700 rounded-full h-2">
                                <div 
                                  className={`h-2 rounded-full ${percentage === 100 ? 'bg-green-500' : percentage > 50 ? 'bg-yellow-500' : 'bg-red-500'}`}
                                  style={{ width: `${percentage}%` }}
                                />
                              </div>
                              <span className="text-sm text-slate-600 dark:text-slate-400 w-12 text-right">{percentage}%</span>
                            </div>
                          </div>

                          {/* Missing Keys List */}
                          <AnimatePresence>
                            {isExpanded && data.missingCount > 0 && (
                              <motion.div
                                initial={{ height: 0 }}
                                animate={{ height: 'auto' }}
                                exit={{ height: 0 }}
                                className="overflow-hidden"
                              >
                                <div className="p-4 border-t border-slate-200 dark:border-slate-700">
                                  <p className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">
                                    Missing Keys ({data.missingCount})
                                  </p>
                                  <div className="max-h-64 overflow-y-auto space-y-2">
                                    {data.missingKeys.map((key) => (
                                      <div 
                                        key={key}
                                        className="flex items-center justify-between p-2 bg-slate-50 dark:bg-slate-800 rounded"
                                      >
