'use client';

import React, { useEffect, useState } from 'react';
import { useTerminology, Terminology } from '@/hooks/useTerminology';
import { toast } from 'sonner';
import api from '@/lib/api';

interface TerminologyItem {
    key: string;
    label: string;
    description: string;
}

const KNOWN_TERMS: TerminologyItem[] = [
    { key: 'unit_singular', label: 'Unit (Singular)', description: 'e.g. Chalet, Room, Suite' },
    { key: 'unit_plural', label: 'Unit (Plural)', description: 'e.g. Chalets, Rooms, Suites' },
    { key: 'facility_singular', label: 'Facility (Singular)', description: 'e.g. Pool, Gym, Spa' },
    { key: 'facility_plural', label: 'Facility (Plural)', description: 'e.g. Pools, Gyms, Spas' },
    { key: 'dining_singular', label: 'Dining (Singular)', description: 'e.g. Restaurant, Bar' },
    { key: 'dining_plural', label: 'Dining (Plural)', description: 'e.g. Restaurants, Bars' },
];

export default function TerminologyPage() {
    const [businessType, setBusinessType] = useState('resort');
    const [loading, setLoading] = useState(false);
    const [values, setValues] = useState<Record<string, string>>({});

    useEffect(() => {
        fetchData();
    }, [businessType]);

    // FIX: Iteration 26 - Use api instance instead of raw fetch (fixes CSRF 403 on terminology save)
    const fetchData = async () => {
        setLoading(true);
        try {
            const response = await api.get(`/terminology?business_type=${businessType}`);
            setValues(response.data?.data || {});
        } catch (error) {
            toast.error('Failed to fetch terminology');
        } finally {
            setLoading(false);
        }
    };

    const handleChange = (key: string, value: string) => {
        setValues(prev => ({ ...prev, [key]: value }));
    };

    // FIX: Iteration 26 - Use api instance instead of raw fetch (fixes CSRF 403)
    const handleSave = async () => {
        setLoading(true);
        try {
            const response = await api.post('/terminology/bulk', {
                business_type: businessType,
                language: 'en',
                updates: values
            });

            if (!response.data?.success) throw new Error('Failed to save');

            toast.success('Terminology updated successfully');
        } catch (error) {
            toast.error('Failed to save changes');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-6 max-w-4xl mx-auto">
            <h1 className="text-2xl font-bold mb-6">Terminology Configuration</h1>

            <div className="mb-8 p-4 bg-white rounded-lg border shadow-sm">
                <label className="block text-sm font-medium text-gray-700 mb-2">Business Type Context</label>
                <select
                    value={businessType}
                    onChange={(e) => setBusinessType(e.target.value)}
                    className="w-full max-w-xs p-2 border rounded-md"
                >
                    <option value="resort">Resort</option>
                    <option value="hotel">Hotel</option>
                    <option value="restaurant">Restaurant</option>
                    <option value="villa">Villa / Vacation Rental</option>
                </select>
                <p className="text-sm text-gray-500 mt-2">
                    Select which business type you are configuring terms for.
                </p>
            </div>

            <div className="bg-white rounded-lg border shadow-sm overflow-hidden">
                <div className="p-4 bg-gray-50 border-b">
                    <h2 className="font-semibold">Term Overrides</h2>
                </div>

                <div className="p-6 grid gap-6">
                    {KNOWN_TERMS.map((term) => (
                        <div key={term.key} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center border-b pb-4 last:border-0 last:pb-0">
                            <div>
                                <label className="block font-medium text-gray-900">{term.label}</label>
                                <p className="text-sm text-gray-500">{term.description}</p>
                                <div className="mt-1 text-xs text-gray-400 font-mono">{term.key}</div>
                            </div>
                            <div className="md:col-span-2">
                                <input
                                    type="text"
                                    value={values[term.key] || ''}
                                    onChange={(e) => handleChange(term.key, e.target.value)}
                                    placeholder={`Default for ${businessType}...`}
                                    className="w-full p-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none"
                                />
                            </div>
                        </div>
                    ))}

                    {/* Dynamic Field Adder could go here */}
                </div>

                <div className="p-4 bg-gray-50 border-t flex justify-end">
                    <button
                        onClick={() => fetchData()}
                        disabled={loading}
                        className="px-4 py-2 text-gray-700 hover:text-gray-900 mr-2"
                    >
                        Reset
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={loading}
                        className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50"
                    >
                        {loading ? 'Saving...' : 'Save Changes'}
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';
import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { useParams, useRouter } from 'next/navigation';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { ArrowLeft, Save, Shield, Check, User, Mail, Phone, Edit2, X } from 'lucide-react';
import { toast } from 'sonner';

interface Permission {
    slug: string;
    description: string;
    module_slug: string;
}

interface PermissionOverride {
    permission_slug: string;
    is_granted: boolean;
}

interface Role {
    id: string;
    name: string;
    display_name: string;
}

export default function UserDetailsPage() {
  const { id } = useParams();
  const router = useRouter();
  const [user, setUser] = useState<any>(null);
  const [allPermissions, setAllPermissions] = useState<Permission[]>([]);
  const [allRoles, setAllRoles] = useState<Role[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [savingProfile, setSavingProfile] = useState(false);
  const [editingProfile, setEditingProfile] = useState(false);
  const [showRoleModal, setShowRoleModal] = useState(false);
  
  // Profile edit state
  const [profileForm, setProfileForm] = useState({
    full_name: '',
    email: '',
    phone: '',
    is_active: true,
  });

  // Role selection state
  const [selectedRoles, setSelectedRoles] = useState<string[]>([]);
  
  // State for overrides
  const [overrides, setOverrides] = useState<Record<string, boolean>>({}); // permissionSlug -> is_granted

  useEffect(() => {
    if (id) {
        Promise.all([
            api.get(`/admin/users/${id}`),
            api.get('/admin/permissions'),
            api.get('/admin/roles')
        ]).then(([userRes, permRes, rolesRes]) => {
            const userPayload = userRes.data?.data ?? userRes.data ?? null;
            if (userPayload) {
                setUser(userPayload);
                // Initialize profile form
                setProfileForm({
                    full_name: userPayload.full_name || '',
                    email: userPayload.email || '',
                    phone: userPayload.phone || '',
                    is_active: userPayload.is_active ?? true,
                });
                // Initialize selected roles
                setSelectedRoles(userPayload.roles || []);
                // Initialize overrides from user data
                const initialOverrides: Record<string, boolean> = {};
                (userPayload.user_permissions_overrides || []).forEach((p: { permission_slug: string; is_granted: boolean }) => {
                    initialOverrides[p.permission_slug] = p.is_granted;
                });
                setOverrides(initialOverrides);
            }
            const permsPayload = permRes.data?.data ?? permRes.data ?? [];
            setAllPermissions(Array.isArray(permsPayload) ? permsPayload : []);
            const rolesPayload = rolesRes.data?.data ?? rolesRes.data ?? [];
            setAllRoles(Array.isArray(rolesPayload) ? rolesPayload : []);
            setLoading(false);
        }).catch(err => {
            toast.error('Failed to load user data');
            console.error(err);
            setLoading(false);
        });
    }
  }, [id]);

  const handleSaveProfile = async () => {
    setSavingProfile(true);
    try {
      await api.put(`/admin/users/${id}`, profileForm);
      setUser({ ...user, ...profileForm });
      setEditingProfile(false);
      toast.success('Profile updated successfully');
    } catch (error) {
      toast.error('Failed to update profile');
    } finally {
      setSavingProfile(false);
    }
  };

  const handleSaveRoles = async () => {
    setSaving(true);
    try {
      await api.put(`/admin/users/${id}/roles`, { roles: selectedRoles });
      setUser({ ...user, roles: selectedRoles });
      setShowRoleModal(false);
      toast.success('Roles updated successfully');
    } catch (error) {
      toast.error('Failed to update roles');
    } finally {
      setSaving(false);
    }
  };

  const handleSaveOverrides = async () => {
      setSaving(true);
      try {
          // Convert map to array
          const permissionsPayload = Object.entries(overrides).map(([pSlug, granted]) => ({
              permission_slug: pSlug,
              is_granted: granted
          }));

          await api.put(`/admin/users/${id}/permissions`, { permissions: permissionsPayload });
          toast.success('Permissions updated successfully');
          router.refresh(); // Refresh to ensure data consistency
      } catch (error) {
          toast.error('Failed to save permissions');
      } finally {
          setSaving(false);
      }
  };

  const toggleOverride = (permissionSlug: string, value: boolean | undefined) => {
      const newOverrides = { ...overrides };
      if (value === undefined) {
          delete newOverrides[permissionSlug]; // Remove override (reset to role default)
      } else {
          newOverrides[permissionSlug] = value;
      }
      setOverrides(newOverrides);
  };

  if (loading) return <div className="p-8">Loading...</div>;
  if (!user) return <div className="p-8">User not found</div>;

  // Group permissions by module
  const permissionsByModule = allPermissions.reduce((acc, perm) => {
      if (!acc[perm.module_slug]) acc[perm.module_slug] = [];
      acc[perm.module_slug].push(perm);
      return acc;
  }, {} as Record<string, Permission[]>);

  return (
    <div className="space-y-6 max-w-5xl mx-auto pb-20">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div>
           <h1 className="text-2xl font-bold">{user.full_name}</h1>
           <p className="text-muted-foreground">{user.email}</p>
        </div>
        <div className="ml-auto flex gap-2">
             <Button variant="outline" onClick={() => setEditingProfile(true)}>
               <Edit2 className="h-4 w-4 mr-2" />
               Edit Profile
             </Button> 
        </div>
      </div>

      {/* Profile Edit Modal */}
      {editingProfile && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <Card className="w-full max-w-md mx-4">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="flex items-center gap-2">
                  <User className="h-5 w-5" />
                  Edit Profile
                </CardTitle>
                <Button variant="ghost" size="icon" onClick={() => setEditingProfile(false)}>
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <label className="text-sm font-medium mb-1 block">Full Name</label>
                <input
                  type="text"
                  className="w-full border rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                  value={profileForm.full_name}
                  onChange={(e) => setProfileForm({ ...profileForm, full_name: e.target.value })}
                />
              </div>
              <div>
                <label className="text-sm font-medium mb-1 block">Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <input
                    type="email"
                    className="w-full border rounded-md pl-10 pr-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                    value={profileForm.email}
                    onChange={(e) => setProfileForm({ ...profileForm, email: e.target.value })}
                  />
                </div>
              </div>
              <div>
                <label className="text-sm font-medium mb-1 block">Phone</label>
                <div className="relative">
                  <Phone className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <input
                    type="tel"
                    className="w-full border rounded-md pl-10 pr-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                    value={profileForm.phone}
                    onChange={(e) => setProfileForm({ ...profileForm, phone: e.target.value })}
                  />
                </div>
              </div>
              <div className="flex items-center justify-between py-2">
                <label className="text-sm font-medium">Account Active</label>
                <button
                  type="button"
                  onClick={() => setProfileForm({ ...profileForm, is_active: !profileForm.is_active })}
                  className={`relative w-11 h-6 rounded-full transition-colors ${
                    profileForm.is_active ? 'bg-green-500' : 'bg-gray-300'
                  }`}
                >
                  <span
                    className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${
                      profileForm.is_active ? 'translate-x-5' : 'translate-x-0'
                    }`}
                  />
                </button>
              </div>
              <div className="flex gap-2 pt-4">
                <Button variant="outline" onClick={() => setEditingProfile(false)} className="flex-1">
                  Cancel
                </Button>
                <Button onClick={handleSaveProfile} disabled={savingProfile} className="flex-1">
                  {savingProfile ? 'Saving...' : <><Save className="h-4 w-4 mr-2" /> Save</>}
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Role Management Modal */}
      {showRoleModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <Card className="w-full max-w-md mx-4">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="flex items-center gap-2">
                  <Shield className="h-5 w-5" />
                  Manage Roles
                </CardTitle>
                <Button variant="ghost" size="icon" onClick={() => setShowRoleModal(false)}>
                  <X className="h-4 w-4" />
                </Button>
              </div>
              <CardDescription>
                Select the roles to assign to this user.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2 max-h-64 overflow-y-auto">
                {allRoles.map((role) => (
                  <label
                    key={role.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                      selectedRoles.includes(role.name)
                        ? 'border-primary bg-primary/5'
                        : 'hover:bg-muted/50'
                    }`}
                  >
                    <input
                      type="checkbox"
                      checked={selectedRoles.includes(role.name)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedRoles([...selectedRoles, role.name]);
                        } else {
                          setSelectedRoles(selectedRoles.filter((r) => r !== role.name));
                        }
                      }}
                      className="w-4 h-4 rounded border-gray-300"
                    />
                    <div>
                      <div className="font-medium">{role.display_name || role.name}</div>
                      <div className="text-xs text-muted-foreground capitalize">{role.name}</div>
                    </div>
                  </label>
                ))}
              </div>
              <div className="flex gap-2 pt-4">
                <Button variant="outline" onClick={() => setShowRoleModal(false)} className="flex-1">
                  Cancel
                </Button>
                <Button onClick={handleSaveRoles} disabled={saving} className="flex-1">
                  {saving ? 'Saving...' : <><Save className="h-4 w-4 mr-2" /> Save</>}
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-1 space-y-6">
              <Card>
                  <CardHeader>
                      <CardTitle>Roles</CardTitle>
                      <CardDescription>
                          Assigned roles determine default permissions.
                      </CardDescription>
                  </CardHeader>
                  <CardContent>
                      <div className="flex flex-wrap gap-2">
                          {user.roles && user.roles.map((r: string) => (
                              <div key={r} className="bg-secondary text-secondary-foreground px-3 py-1 rounded-full text-sm font-medium">
                                  {r}
                              </div>
                          ))}
                      </div>
                      <Button variant="ghost" className="px-0 mt-4 text-primary hover:bg-transparent hover:underline" onClick={() => setShowRoleModal(true)}>
                          Manage Roles
                      </Button>
                  </CardContent>
              </Card>

               <Card>
                  <CardHeader>
                      <CardTitle>Account Status</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                      <div className="flex justify-between items-center text-sm">
                          <span className="text-muted-foreground">Active</span>
                          <span className={user.is_active ? "text-green-600 font-medium" : "text-destructive"}>
                              {user.is_active ? "Yes" : "No"}
                          </span>
                      </div>
                      <div className="flex justify-between items-center text-sm">
                          <span className="text-muted-foreground">Online</span>
                          <span className={user.is_online ? "text-green-600 font-medium" : "text-muted-foreground"}>
                              {user.is_online ? "Yes" : "No"}
                          </span>
                      </div>
                  </CardContent>
              </Card>
          </div>

          <div className="md:col-span-2">
              <Card>
                  <CardHeader className="flex flex-row items-center justify-between">
                      <div>
                        <CardTitle className="flex items-center gap-2">
                            <Shield className="h-5 w-5 text-primary" />
                            Permissions Overrides
                        </CardTitle>
                        <CardDescription>
                            Fine-tune access by granting specific permissions. 
                            Green = Granted (Override).
                        </CardDescription>
                      </div>
                      <Button onClick={handleSaveOverrides} disabled={saving}>
                          {saving ? 'Saving...' : 'Save Changes'}
                      </Button>
                  </CardHeader>
                  <CardContent>
                      <div className="space-y-6">
                          {Object.entries(permissionsByModule).map(([module, perms]) => (
                              <div key={module} className="border rounded-lg p-4">
                                  <h3 className="font-semibold capitalize mb-3 text-lg flex items-center gap-2">
                                      {module} <span className="text-xs font-normal text-muted-foreground bg-muted px-2 py-0.5 rounded">Module</span>
                                  </h3>
                                  <div className="space-y-2">
                                      {perms.map(perm => {
                                          const roleHasIt = user.role_permissions?.includes(perm.slug);
                                          const override = overrides[perm.slug];
                                          const isEffective = override === true || (roleHasIt && override !== false);
                                          
                                          return (
                                              <div key={perm.slug} className="flex items-center justify-between py-2 border-b last:border-0 pl-2 hover:bg-muted/30 rounded transition-colors">
                                                  <div>
                                                      <div className="font-medium text-sm">{perm.slug}</div>
                                                      <div className="text-xs text-muted-foreground">{perm.description}</div>
                                                  </div>
                                                  <div className="flex items-center gap-3">
                                                      {roleHasIt && (
                                                          <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider mr-2">
                                                              Inherited
                                                          </span>
                                                      )}
                                                      
                                                      {/* Simple Toggle - For now just "Grant" override vs "Default" */}
                                                      <div className="flex items-center border rounded overflow-hidden">
                                                          <button 
                                                            onClick={() => toggleOverride(perm.slug, undefined)}
                                                            className={`px-3 py-1 text-xs ${override === undefined ? 'bg-muted text-muted-foreground font-medium' : 'hover:bg-muted/50'}`}
                                                          >
                                                              Default
                                                          </button>
                                                          <button 
                                                            onClick={() => toggleOverride(perm.slug, true)}
                                                            className={`px-3 py-1 text-xs ${override === true ? 'bg-green-100 text-green-700 font-bold border-l border-green-200' : 'hover:bg-green-50 border-l'}`}
                                                          >
                                                              Grant
                                                          </button>
                                                          {/* Deny option hidden for now unless strictly needed, but logic supports it */}
                                                      </div>
                                                  </div>
                                              </div>
                                          );
                                      })}
                                  </div>
                              </div>
                          ))}
                      </div>
                  </CardContent>
              </Card>
          </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { api } from '@/lib/api';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { ArrowLeft, UserPlus, Mail, Phone, Lock, User, Shield } from 'lucide-react';
import { toast } from 'sonner';

// Valid roles matching backend schema
type ValidRole = 
  | 'customer' 
  | 'admin' 
  | 'super_admin'
  | 'restaurant_staff' 
  | 'restaurant_admin'
  | 'chalet_staff' 
  | 'chalet_admin'
  | 'pool_staff' 
  | 'pool_admin'
  | 'snack_bar_staff' 
  | 'snack_bar_admin';

interface FormData {
  email: string;
  password: string;
  confirmPassword: string;
  fullName: string;
  phone: string;
  role: ValidRole;
}

const ROLE_OPTIONS: { value: ValidRole; label: string; description: string; category: string }[] = [
  { value: 'customer', label: 'Customer', description: 'Regular customer with booking and ordering access.', category: 'General' },
  { value: 'admin', label: 'Admin', description: 'Administrator with full access to the admin dashboard.', category: 'General' },
  { value: 'super_admin', label: 'Super Admin', description: 'Super administrator with system-wide access.', category: 'General' },
  { value: 'restaurant_staff', label: 'Restaurant Staff', description: 'Staff member for restaurant operations.', category: 'Restaurant' },
  { value: 'restaurant_admin', label: 'Restaurant Admin', description: 'Administrator for restaurant management.', category: 'Restaurant' },
  { value: 'chalet_staff', label: 'Chalet Staff', description: 'Staff member for chalet operations.', category: 'Chalet' },
  { value: 'chalet_admin', label: 'Chalet Admin', description: 'Administrator for chalet management.', category: 'Chalet' },
  { value: 'pool_staff', label: 'Pool Staff', description: 'Staff member for pool operations.', category: 'Pool' },
  { value: 'pool_admin', label: 'Pool Admin', description: 'Administrator for pool management.', category: 'Pool' },
  { value: 'snack_bar_staff', label: 'Snack Bar Staff', description: 'Staff member for snack bar operations.', category: 'Snack Bar' },
  { value: 'snack_bar_admin', label: 'Snack Bar Admin', description: 'Administrator for snack bar management.', category: 'Snack Bar' },
];

export default function CreateUserPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<FormData>({
    email: '',
    password: '',
    confirmPassword: '',
    fullName: '',
    phone: '',
    role: 'customer',
  });
  const [errors, setErrors] = useState<Partial<FormData>>({});

  const validateForm = (): boolean => {
    const newErrors: Partial<FormData> = {};

    if (!formData.email) {
      newErrors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Invalid email format';
    }

    if (!formData.password) {
      newErrors.password = 'Password is required';
    } else if (formData.password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters';
    } else if (!/[A-Z]/.test(formData.password)) {
      newErrors.password = 'Password must contain at least one uppercase letter';
    } else if (!/[a-z]/.test(formData.password)) {
      newErrors.password = 'Password must contain at least one lowercase letter';
    } else if (!/[0-9]/.test(formData.password)) {
      newErrors.password = 'Password must contain at least one number';
    } else if (!/[!@#$%^&*(),.?":{}|<>]/.test(formData.password)) {
      newErrors.password = 'Password must contain at least one special character';
    }

    if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match';
    }

    if (!formData.fullName) {
      newErrors.fullName = 'Full name is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    setLoading(true);
    try {
      await api.post('/admin/users', {
        email: formData.email,
        password: formData.password,
        full_name: formData.fullName,
        phone: formData.phone || null,
        roles: [formData.role], // Backend expects roles as an array
      });
      
      toast.success('User created successfully');
      // Navigate to appropriate list based on role
      const isStaffRole = formData.role.includes('staff');
      const isAdminRole = formData.role.includes('admin') && formData.role !== 'customer';
      router.push(`/admin/users/${formData.role === 'customer' ? 'customers' : isStaffRole ? 'staff' : isAdminRole ? 'admins' : 'customers'}`);
    } catch (error: unknown) {
      const axiosError = error as { response?: { data?: { message?: string; error?: string } } };
      const message = axiosError.response?.data?.message || axiosError.response?.data?.error || 'Failed to create user';
      toast.error(message);
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (field: keyof FormData) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>
  ) => {
    setFormData(prev => ({ ...prev, [field]: e.target.value }));
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: undefined }));
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6 pb-20">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.back()}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div>
          <h1 className="text-2xl font-bold">Create New User</h1>
          <p className="text-muted-foreground">Add a new user to the system</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <UserPlus className="h-5 w-5 text-primary" />
            User Details
          </CardTitle>
          <CardDescription>
            Fill in the information below to create a new user account.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Email */}
            <div className="space-y-2">
              <label className="text-sm font-medium flex items-center gap-2">
                <Mail className="h-4 w-4" />
                Email Address *
              </label>
              <Input
                type="email"
                placeholder="user@example.com"
                value={formData.email}
                onChange={handleChange('email')}
                className={errors.email ? 'border-destructive' : ''}
              />
              {errors.email && (
                <p className="text-sm text-destructive">{errors.email}</p>
              )}
            </div>

            {/* Full Name */}
            <div className="space-y-2">
              <label className="text-sm font-medium flex items-center gap-2">
                <User className="h-4 w-4" />
                Full Name *
              </label>
              <Input
                type="text"
                placeholder="John Doe"
                value={formData.fullName}
                onChange={handleChange('fullName')}
                className={errors.fullName ? 'border-destructive' : ''}
              />
              {errors.fullName && (
                <p className="text-sm text-destructive">{errors.fullName}</p>
              )}
            </div>

            {/* Phone */}
            <div className="space-y-2">
              <label className="text-sm font-medium flex items-center gap-2">
                <Phone className="h-4 w-4" />
                Phone Number
              </label>
              <Input
                type="tel"
                placeholder="+1 234 567 8900"
                value={formData.phone}
                onChange={handleChange('phone')}
              />
            </div>

            {/* Role */}
            <div className="space-y-2">
              <label className="text-sm font-medium flex items-center gap-2">
                <Shield className="h-4 w-4" />
                Role *
              </label>
              <select
                value={formData.role}
                onChange={handleChange('role')}
                className="w-full px-3 py-2 border rounded-lg bg-background focus:ring-2 focus:ring-primary focus:border-primary"
              >
                {['General', 'Restaurant', 'Chalet', 'Pool', 'Snack Bar'].map(category => (
                  <optgroup key={category} label={category}>
                    {ROLE_OPTIONS
                      .filter(role => role.category === category)
                      .map(role => (
                        <option key={role.value} value={role.value}>
                          {role.label}
                        </option>
                      ))}
                  </optgroup>
                ))}
              </select>
              <p className="text-xs text-muted-foreground">
                {ROLE_OPTIONS.find(r => r.value === formData.role)?.description}
              </p>
            </div>

            {/* Password */}
            <div className="space-y-2">
              <label className="text-sm font-medium flex items-center gap-2">
                <Lock className="h-4 w-4" />
                Password *
              </label>
              <Input
                type="password"
                placeholder="••••••••"
                value={formData.password}
                onChange={handleChange('password')}
                className={errors.password ? 'border-destructive' : ''}
              />
              {errors.password && (
                <p className="text-sm text-destructive">{errors.password}</p>
              )}
            </div>

            {/* Confirm Password */}
            <div className="space-y-2">
              <label className="text-sm font-medium flex items-center gap-2">
                <Lock className="h-4 w-4" />
                Confirm Password *
              </label>
              <Input
                type="password"
                placeholder="••••••••"
                value={formData.confirmPassword}
                onChange={handleChange('confirmPassword')}
                className={errors.confirmPassword ? 'border-destructive' : ''}
              />
              {errors.confirmPassword && (
                <p className="text-sm text-destructive">{errors.confirmPassword}</p>
              )}
            </div>

            {/* Actions */}
            <div className="flex gap-4 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => router.back()}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={loading}
                className="flex-1"
              >
                {loading ? 'Creating...' : 'Create User'}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';
import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { toast } from 'sonner';
import { Shield, Users, Plus, X, Check, Edit2 } from 'lucide-react';

interface Role {
  id: string;
  name: string;
  description?: string;
  users_count?: number;
  permissions_count?: number;
}

interface Permission {
  slug: string;
  name?: string;
  description?: string;
  module_slug?: string;
}

export default function RolesPage() {
  const [roles, setRoles] = useState<Role[]>([]);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [loading, setLoading] = useState(true);
  
  // Modal states
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showPermissionsModal, setShowPermissionsModal] = useState(false);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  const [rolePermissions, setRolePermissions] = useState<string[]>([]); // permission IDs
  const [authError, setAuthError] = useState<string | null>(null);
  
  // Create role form
  const [newRoleName, setNewRoleName] = useState('');
  const [newRoleDescription, setNewRoleDescription] = useState('');
  const [saving, setSaving] = useState(false);
  
  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [rolesRes, permsRes] = await Promise.all([
        api.get('/admin/roles'),
        api.get('/admin/permissions')
      ]);
      const rolesPayload = rolesRes.data?.data ?? rolesRes.data ?? [];
      setRoles(Array.isArray(rolesPayload) ? rolesPayload : []);
      const permsPayload = permsRes.data?.data ?? permsRes.data ?? [];
      setPermissions(Array.isArray(permsPayload) ? permsPayload : []);
      // Clear any previous auth error on success
      setAuthError(null);
    } catch (error: unknown) {
      console.error(error);
      const axiosError = error as { response?: { status?: number; data?: { error?: string } } };

      // Give clearer feedback for auth/permission issues
      if (axiosError.response?.status === 401) {
        setAuthError('You must be logged in to view roles. Please login.');
      } else if (axiosError.response?.status === 403) {
        setAuthError('Access denied. You need the super_admin role to view and manage roles.');
      } else {
        toast.error('Failed to load roles');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRole = async () => {
    if (!newRoleName.trim()) {
      toast.error('Role name is required');
      return;
    }
    
    setSaving(true);
    try {
      const res = await api.post('/admin/roles', {
        name: newRoleName.toLowerCase().replace(/\s+/g, '_'),
        description: newRoleDescription
      });
      
      if (res.data?.data) {
        setRoles([...roles, res.data.data]);
      }
      toast.success('Role created successfully');
      setShowCreateModal(false);
      setNewRoleName('');
      setNewRoleDescription('');
      fetchData(); // Refresh
    } catch (error: unknown) {
      const errorMessage = (error as { response?: { data?: { error?: string } } })?.response?.data?.error;
      toast.error(errorMessage || 'Failed to create role');
    } finally {
      setSaving(false);
    }
  };

  const openPermissionsModal = async (role: Role) => {
    setSelectedRole(role);
    setShowPermissionsModal(true);
    
    // Fetch current role permissions
    try {
      const res = await api.get(`/admin/roles/${role.id}/permissions`);
      setRolePermissions(res.data?.data || []);
    } catch (e) {
      console.error(e);
      setRolePermissions([]);
    }
  };

  const togglePermission = (permissionSlug: string) => {
    setRolePermissions(prev => 
      prev.includes(permissionSlug)
        ? prev.filter(slug => slug !== permissionSlug)
        : [...prev, permissionSlug]
    );
  };

  const saveRolePermissions = async () => {
    if (!selectedRole) return;
    
    setSaving(true);
    try {
      await api.put(`/admin/roles/${selectedRole.id}/permissions`, {
        permission_slugs: rolePermissions
      });
      toast.success('Permissions updated successfully');
      setShowPermissionsModal(false);
    } catch (error: unknown) {
      const errorMessage = (error as { response?: { data?: { error?: string } } })?.response?.data?.error;
      toast.error(errorMessage || 'Failed to update permissions');
    } finally {
      setSaving(false);
    }
  };

  // Group permissions by module
  const permissionsByModule = permissions.reduce((acc, perm) => {
    const module = perm.module_slug || 'other';
    if (!acc[module]) acc[module] = [];
    acc[module].push(perm);
    return acc;
  }, {} as Record<string, Permission[]>);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Roles & Permissions</h1>
          <p className="text-muted-foreground">
            Manage system roles and their default permission sets.
          </p>
        </div>
        <Button onClick={() => setShowCreateModal(true)}>
          <Plus className="h-4 w-4 mr-2" />
          Create Role
        </Button>
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {loading ? (
          <p className="col-span-full text-center py-8 text-muted-foreground">Loading...</p>
        ) : authError ? (
          <div className="col-span-full text-center py-8 text-muted-foreground">
            <p className="mb-2 text-sm">{authError}</p>
            <div className="flex items-center justify-center gap-2">
              <Button variant="outline" onClick={() => (window.location.href = '/login')}>Login</Button>
              <Button variant="ghost" onClick={() => window.location.reload()}>Retry</Button>
            </div>
          </div>
        ) : roles.length === 0 ? (
          <div className="col-span-full text-center py-8 text-muted-foreground space-y-2">
            <p>No roles found</p>
            <p className="text-xs">If this is a fresh install, run the seed script to create default roles and an admin user.</p>
          </div>
        ) : (
          roles.map(role => (
            <Card key={role.id} className="hover:border-primary/50 transition-colors">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="flex items-center gap-2">
                    <Shield className="h-5 w-5 text-primary" />
                    {role.name}
                  </CardTitle>
                </div>
                {role.description && (
                  <CardDescription>{role.description}</CardDescription>
                )}
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center gap-4 text-sm text-muted-foreground">
                  <div className="flex items-center gap-2">
                    <Users className="h-4 w-4" />
                    <span>{role.users_count || 0} users</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Shield className="h-4 w-4" />
                    <span>{role.permissions_count || 0} perms</span>
                  </div>
                </div>
                <Button 
                  variant="outline" 
                  className="w-full"
                  onClick={() => openPermissionsModal(role)}
                >
                  <Edit2 className="h-4 w-4 mr-2" />
                  Edit Permissions
                </Button>
              </CardContent>
            </Card>
          ))
        )}
      </div>

      {/* Create Role Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]">
          <div className="bg-background rounded-lg shadow-xl max-w-md w-full mx-4 p-6">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold">Create New Role</h2>
              <Button variant="ghost" size="icon" onClick={() => setShowCreateModal(false)}>
                <X className="h-4 w-4" />
              </Button>
            </div>
            
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium mb-1 block">Role Name *</label>
                <Input
                  placeholder="e.g., pool_manager"
                  value={newRoleName}
                  onChange={(e) => setNewRoleName(e.target.value)}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Use lowercase with underscores (e.g., restaurant_staff)
                </p>
              </div>
              
              <div>
                <label className="text-sm font-medium mb-1 block">Description</label>
                <Input
                  placeholder="Describe this role..."
                  value={newRoleDescription}
                  onChange={(e) => setNewRoleDescription(e.target.value)}
                />
              </div>
              
              <div className="flex gap-2 pt-4">
                <Button variant="outline" className="flex-1" onClick={() => setShowCreateModal(false)}>
                  Cancel
                </Button>
                <Button className="flex-1" onClick={handleCreateRole} disabled={saving}>
                  {saving ? 'Creating...' : 'Create Role'}
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Permissions Editor Modal */}
      {showPermissionsModal && selectedRole && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[200]">
          <div className="bg-background rounded-lg shadow-xl max-w-2xl w-full mx-4 max-h-[80vh] overflow-hidden flex flex-col">
            <div className="flex justify-between items-center p-6 border-b">
              <div>
                <h2 className="text-xl font-bold">Edit Permissions</h2>
                <p className="text-muted-foreground text-sm">
