                          </div>
                          <div className={`w-6 h-6 rounded border-2 flex items-center justify-center transition-colors ${
                            isSelected 
                              ? 'bg-primary border-primary text-primary-foreground' 
                              : 'border-muted-foreground/30'
                          }`}>
                            {isSelected && <Check className="h-4 w-4" />}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
            
            <div className="p-6 border-t flex gap-2">
              <Button variant="outline" className="flex-1" onClick={() => setShowPermissionsModal(false)}>
                Cancel
              </Button>
              <Button className="flex-1" onClick={saveRolePermissions} disabled={saving}>
                {saving ? 'Saving...' : 'Save Permissions'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { NextResponse } from 'next/server';

export async function GET() {
  const defaultTheme = {
    theme: 'beach',
    colors: {
      primary: '#0ea5e9',
      accent: '#6366f1',
      background: '#f8fafc',
      text: '#1e293b',
    },
  };

  try {
    const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';
    const res = await fetch(`${apiUrl.replace(/\/api\/?$/, '')}/api/settings`, {
      // Forward cookies if needed for SSR auth, but for public settings usually not needed
      next: { revalidate: 60 }, // ISR: cache for 60s
    });
    if (!res.ok) {
      return NextResponse.json(defaultTheme);
    }
    const data = await res.json();
    if (data.success && data.data) {
      // Prefer appearance object if present, else fallback to root
      const appearance = data.data.appearance || data.data;
      return NextResponse.json({
        theme: appearance.theme || 'beach',
        colors: appearance.themeColors || defaultTheme.colors,
      });
    }
    return NextResponse.json(defaultTheme);
  } catch (err) {
    // Fallback to static if backend is down
    return NextResponse.json({
      ...defaultTheme,
      error: 'Backend unavailable',
    });
  }
}

'use client';

import { useCartStore } from '@/stores/cartStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { useSiteSettings } from '@/lib/settings-context';
import { formatCurrency } from '@/lib/utils';
import { useTranslations } from 'next-intl';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import { Trash2, Plus, Minus, ArrowRight, ShoppingCart, Store, ExternalLink } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { toast } from 'sonner';

export default function CartPage() {
  const t = useTranslations('common');
  const tErrors = useTranslations('errors');
  const router = useRouter();
  const currency = useSettingsStore((s) => s.currency);

  const items = useCartStore((s) => s.items);
  const removeItem = useCartStore((s) => s.removeItem);
  const updateQuantity = useCartStore((s) => s.updateQuantity);
  const getTotal = useCartStore((s) => s.getTotal);
  const clearCart = useCartStore((s) => s.clearCart);

  const total = getTotal();
  const isEmpty = items.length === 0;

  // Group items by moduleId
  const groupedItems = items.reduce((acc, item) => {
    const key = item.moduleName || 'Other Items';
    if (!acc[key]) {
      acc[key] = [];
    }
    acc[key].push(item);
    return acc;
  }, {} as Record<string, typeof items>);

  const hasMultipleModules = Object.keys(groupedItems).length > 1;

  // Map module IDs to their slug before routing to avoid landing on 404s when the ID is used
  const { modules } = useSiteSettings();

  const handleCheckout = (moduleId?: string) => {
    let targetModuleId = moduleId;

    // If no specific module ID passed, try to detect single module context
    if (!targetModuleId) {
      const uniqueModules = Array.from(new Set(items.map(i => i.moduleId).filter(Boolean)));
      
      if (uniqueModules.length === 1) {
        targetModuleId = uniqueModules[0];
      } else if (uniqueModules.length > 1) {
        toast.info(tErrors('checkoutModulesSeparately'));
        return;
      } else {
        targetModuleId = items[0]?.moduleId;
        if (!targetModuleId) {
            toast.error(tErrors('unableToDetermineCheckout'));
            return;
        }
      }
    }

    if (targetModuleId) {
      // Prefer routing by slug when we can find the module
      const mod = modules.find((m) => m.id === targetModuleId) || modules.find((m) => m.slug === targetModuleId);
      const slug = mod ? mod.slug : targetModuleId;
      router.push(`/${slug}/cart`);
    }
  };

  if (isEmpty) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 dark:bg-slate-900 p-4">
        <div className="w-24 h-24 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6">
          <ShoppingCart className="w-12 h-12 text-slate-400" />
        </div>
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
          {t('cartEmpty')}
        </h1>
        <p className="text-slate-600 dark:text-slate-400 mb-8 text-center max-w-md">
          {t('browseModules')}
        </p>
        <Link href="/">
          <Button variant="outline" className="gap-2">
            {t('returnHome')}
          </Button>
        </Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white">
            {t('yourCart')}
          </h1>
          <Button variant="ghost" className="text-red-500 hover:text-red-600 hover:bg-red-50" onClick={clearCart}>
            <Trash2 className="w-4 h-4 mr-2" />
            {t('clearCart')}
          </Button>
        </div>

        <div className="grid gap-8">
          {Object.entries(groupedItems).map(([moduleName, moduleItems]) => {
             const sectionModuleId = moduleItems[0]?.moduleId;
             return (
                <section key={moduleName}>
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2">
                      <Store className="w-5 h-5 text-primary-600" />
                      <h2 className="text-xl font-semibold text-slate-900 dark:text-white">
                        {moduleName}
                      </h2>
                    </div>
                    {hasMultipleModules && sectionModuleId && (
                        <Button 
                          size="sm" 
                          variant="outline"
                          onClick={() => handleCheckout(sectionModuleId)}
                          className="gap-2"
                        >
                          {t('checkout')} {moduleName}
                          <ExternalLink className="w-4 h-4" />
                        </Button>
                    )}
                  </div>
                  <Card>
                    <CardContent className="p-0 divide-y divide-slate-100 dark:divide-slate-800">
                      {moduleItems.map((item) => (
                        <div key={item.id} className="p-4 flex items-center gap-4">
                          {item.imageUrl && (
                            <img
                              src={item.imageUrl}
                              alt={item.name}
                              className="w-16 h-16 object-cover rounded-lg"
                            />
                          )}
                          <div className="flex-1">
                            <h3 className="font-medium text-slate-900 dark:text-white">
                              {item.name}
                            </h3>
                            <p className="text-sm text-slate-500 dark:text-slate-400">
                              {formatCurrency(item.price, currency)}
                            </p>
                            {item.specialInstructions && (
                              <p className="text-xs text-slate-500 mt-1 italic">
                                "{item.specialInstructions}"
                              </p>
                            )}
                          </div>
                          
                          <div className="flex items-center gap-3">
                             <div className="flex items-center border rounded-lg dark:border-slate-700">
                              <button
                                onClick={() => updateQuantity(item.id, item.quantity - 1)}
                                className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                              >
                                <Minus className="w-4 h-4" />
                              </button>
                              <span className="w-8 text-center text-sm font-medium">
                                {item.quantity}
                              </span>
                              <button
                                onClick={() => updateQuantity(item.id, item.quantity + 1)}
                                className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                              >
                                <Plus className="w-4 h-4" />
                              </button>
                            </div>
                            <button
                              onClick={() => removeItem(item.id)}
                              className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </div>
                      ))}
                    </CardContent>
                  </Card>
                </section>
             );
          })}

          {/* Checkout Section */}
          <div className="mt-8 flex justify-end">
            <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 w-full max-w-md">
              <div className="flex justify-between items-center mb-4">
                <span className="text-slate-600 dark:text-slate-400">{t('total')}</span>
                <span className="text-2xl font-bold text-slate-900 dark:text-white">
                  {formatCurrency(total, currency)}
                </span>
              </div>
              <Button 
                className="w-full h-12 text-lg gap-2"
                onClick={() => handleCheckout()}
              >
                {t('checkout')}
                <ArrowRight className="w-5 h-5" />
              </Button>
              {hasMultipleModules && (
                <p className="text-xs text-center mt-2 text-slate-500">
                  {t('checkoutModulesSeparately')}
                </p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState, useMemo, useCallback } from 'react';
import { useParams, useRouter, useSearchParams } from 'next/navigation';
import { useQuery } from '@tanstack/react-query';
import { useTranslations } from 'next-intl';
import { motion, AnimatePresence } from 'framer-motion';
import { api, chaletsApi } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { useSettingsStore } from '@/stores/settingsStore';
import { useContentTranslation } from '@/lib/translate';
import { useAuth } from '@/lib/auth-context';
import { toast } from 'sonner';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import AvailabilityCalendar from '@/components/chalets/AvailabilityCalendar';
import {
  Loader2,
  Home,
  Users,
  Bed,
  Bath,
  Wifi,
  Wind,
  UtensilsCrossed,
  Car,
  AlertCircle,
  Star,
  MapPin,
  Calendar,
  ChevronLeft,
  ChevronRight,
  Check,
  Plus,
  Minus,
  ArrowLeft,
} from 'lucide-react';
import Link from 'next/link';

interface Chalet {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  description?: string;
  description_ar?: string;
  description_fr?: string;
  capacity: number;
  bedroom_count?: number;
  bathroom_count?: number;
  amenities?: string[];
  images?: string[];
  base_price?: number;
  weekend_price?: number;
  is_active?: boolean;
}

interface AddOn {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  description?: string;
  price: number;
  price_type: 'per_night' | 'one_time';
  is_active: boolean;
}

const amenityIcons: Record<string, React.ElementType> = {
  WiFi: Wifi,
  wifi: Wifi,
  AC: Wind,
  ac: Wind,
  'air conditioning': Wind,
  Kitchen: UtensilsCrossed,
  kitchen: UtensilsCrossed,
  Parking: Car,
  parking: Car,
};

export default function ChaletDetailPage() {
  const params = useParams();
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user } = useAuth();
  const t = useTranslations('chalets');
  const tCommon = useTranslations('common');
  const currency = useSettingsStore((s) => s.currency);
  const { translateContent, isRTL } = useContentTranslation();
  
  // Get moduleId from query params for add-ons filtering
  const moduleId = searchParams.get('module') || undefined;

  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [checkInDate, setCheckInDate] = useState('');
  const [checkOutDate, setCheckOutDate] = useState('');
  const [numberOfGuests, setNumberOfGuests] = useState(2);
  const [selectedAddOns, setSelectedAddOns] = useState<{ addOnId: string; quantity: number }[]>([]);
  const [customerName, setCustomerName] = useState(user?.fullName || '');
  const [customerEmail, setCustomerEmail] = useState(user?.email || '');
  const [customerPhone, setCustomerPhone] = useState('');
  const [specialRequests, setSpecialRequests] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [blockedDates, setBlockedDates] = useState<string[]>([]);
  const [dailyPricesMap, setDailyPricesMap] = useState<Record<string, { price: number; type: string; ruleName?: string; isBlocked: boolean }>>({});

  // Fetch chalet details
  const { data: chaletData, isLoading: chaletLoading, error: chaletError } = useQuery({
    queryKey: ['chalet', params.id],
    queryFn: () => chaletsApi.getChalet(params.id as string),
  });

  // Fetch add-ons (filtered by module if moduleId is provided)
  const { data: addOnsData } = useQuery({
    queryKey: ['chalet-addons', moduleId],
    queryFn: () => chaletsApi.getAddOns(moduleId),
  });

  const chalet: Chalet | null = chaletData?.data?.data || null;
  const addOns: AddOn[] = addOnsData?.data?.data || [];

  // Update form when user changes
  useEffect(() => {
    if (user) {
      setCustomerName(user.fullName || '');
      setCustomerEmail(user.email || '');
    }
  }, [user]);

  // Fetch daily prices for the calendar (next 3 months)
  useEffect(() => {
    if (!chalet) return;
    const fetchDailyPrices = async () => {
      try {
        const startDate = new Date().toISOString().split('T')[0];
        const endDate = new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        const response = await api.get(`/chalets/${chalet.id}/daily-prices`, { params: { startDate, endDate } });
        const prices = response.data?.data?.dailyPrices || [];
        const priceMap: Record<string, { price: number; type: string; ruleName?: string; isBlocked: boolean }> = {};
        prices.forEach((dp: { date: string; price: number; type: string; ruleName?: string; isBlocked: boolean }) => {
          priceMap[dp.date] = { price: dp.price, type: dp.type, ruleName: dp.ruleName, isBlocked: dp.isBlocked };
        });
        setDailyPricesMap(priceMap);
        // Extract blocked dates from the daily prices response
        const blocked = prices.filter((dp: { isBlocked: boolean }) => dp.isBlocked).map((dp: { date: string }) => dp.date);
        setBlockedDates(blocked);
      } catch (error) {
        console.error('Failed to fetch daily prices:', error);
      }
    };
    fetchDailyPrices();
  }, [chalet]);

  // Fetch availability when dates change
  useEffect(() => {
    if (chalet && checkInDate && checkOutDate) {
      fetchAvailability();
    }
  }, [chalet, checkInDate, checkOutDate]);

  const fetchAvailability = async () => {
    try {
      const response = await api.get(`/chalets/${params.id}/availability`, {
        params: { startDate: checkInDate, endDate: checkOutDate },
      });
      setBlockedDates(response.data.data?.blockedDates || []);
    } catch (error) {
      console.error('Failed to fetch availability:', error);
    }
  };

  const calculatePricing = () => {
    if (!chalet || !checkInDate || !checkOutDate) return null;

    const checkIn = new Date(checkInDate);
    const checkOut = new Date(checkOutDate);
    const nights = Math.ceil((checkOut.getTime() - checkIn.getTime()) / (1000 * 60 * 60 * 24));

    if (nights <= 0) return null;

    let baseAmount = 0;
    const current = new Date(checkIn);
    const nightBreakdown: Array<{ date: string; price: number; type: string }> = [];
    
    while (current < checkOut) {
      const dateStr = current.toISOString().split('T')[0];
      const dailyPrice = dailyPricesMap[dateStr];
      
      let nightPrice: number;
      let nightType: string;
      
      if (dailyPrice) {
        // Use engine-calculated price (includes price rules, seasonal adjustments)
        nightPrice = dailyPrice.price;
        nightType = dailyPrice.type;
      } else {
        // Fallback to chalet base prices if daily prices not loaded
        const dayOfWeek = current.getDay();
        const isWeekend = dayOfWeek === 5 || dayOfWeek === 6;
        nightPrice = isWeekend 
          ? (chalet.weekend_price || chalet.base_price || 0) 
          : (chalet.base_price || 0);
        nightType = isWeekend ? 'weekend' : 'weekday';
      }
      
      baseAmount += nightPrice;
      nightBreakdown.push({ date: dateStr, price: nightPrice, type: nightType });
      current.setDate(current.getDate() + 1);
    }

    let addOnsAmount = 0;
    selectedAddOns.forEach(({ addOnId, quantity }) => {
      const addOn = addOns.find(a => a.id === addOnId);
      if (addOn) {
        const multiplier = addOn.price_type === 'per_night' ? nights : 1;
        addOnsAmount += addOn.price * quantity * multiplier;
      }
    });

    const depositAmount = baseAmount * 0.3;
    const totalAmount = baseAmount + addOnsAmount;

    return { nights, baseAmount, addOnsAmount, depositAmount, totalAmount, nightBreakdown };
  };

  const pricing = calculatePricing();

  const handleAddOnToggle = (addOnId: string) => {
    const existing = selectedAddOns.find(a => a.addOnId === addOnId);
    if (existing) {
      setSelectedAddOns(prev => prev.filter(a => a.addOnId !== addOnId));
    } else {
      setSelectedAddOns(prev => [...prev, { addOnId, quantity: 1 }]);
    }
  };

  const updateAddOnQuantity = (addOnId: string, delta: number) => {
    setSelectedAddOns(prev =>
      prev.map(a =>
        a.addOnId === addOnId
          ? { ...a, quantity: Math.max(1, a.quantity + delta) }
          : a
      )
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!chalet || !pricing) {
      toast.error('Please select valid dates');
      return;
    }

    if (!customerName || !customerEmail || !customerPhone) {
      toast.error('Please fill in all required fields');
      return;
    }

    // Check for blocked dates
    const checkIn = new Date(checkInDate);
    const checkOut = new Date(checkOutDate);
    const current = new Date(checkIn);
    while (current < checkOut) {
      const dateStr = current.toISOString().split('T')[0];
      if (blockedDates.includes(dateStr)) {
        toast.error('Selected dates are not available');
        return;
      }
      current.setDate(current.getDate() + 1);
    }

    setIsSubmitting(true);
    try {
      const response = await api.post('/chalets/bookings', {
        chaletId: chalet.id,
        customerName,
        customerEmail,
        customerPhone,
        checkInDate,
        checkOutDate,
        numberOfGuests,
        addOns: selectedAddOns,
        specialRequests,
        paymentMethod: 'cash',
      });

      toast.success('Booking submitted successfully!');
      router.push(`/chalets/booking-confirmation?id=${response.data.data.id}`);
    } catch (error: unknown) {
      const axiosError = error as { response?: { data?: { error?: string } } };
      toast.error(axiosError.response?.data?.error || 'Failed to submit booking');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (chaletLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-resort-sand dark:bg-slate-900">
        <Loader2 className="w-8 h-8 animate-spin text-primary-600" />
      </div>
    );
  }

  if (chaletError || !chalet) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-resort-sand dark:bg-slate-900">
        <div className="text-center">
          <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h2 className="text-xl font-semibold text-slate-900 dark:text-white">Chalet not found</h2>
          <Link href="/chalets" className="btn btn-primary mt-4">
            Back to Chalets
          </Link>
        </div>
      </div>
    );
  }

  const images = chalet.images && chalet.images.length > 0 ? chalet.images : [];

  return (
    <div className="min-h-screen bg-gradient-to-b from-resort-sand to-white dark:from-slate-900 dark:to-slate-800">
      {/* Back Button */}
      <div className="max-w-7xl mx-auto px-4 py-4">
        <Link
          href="/chalets"
          className="inline-flex items-center text-slate-600 dark:text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          {tCommon('back')}
        </Link>
      </div>

      <main className="max-w-7xl mx-auto px-4 pb-16">
        <div className="grid lg:grid-cols-5 gap-8">
          {/* Left Column - Images & Details */}
          <div className="lg:col-span-3 space-y-6">
            {/* Image Gallery */}
            <motion.div
              className="relative rounded-2xl overflow-hidden bg-slate-200 dark:bg-slate-700 aspect-[4/3]"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
            >
              {images.length > 0 ? (
                <>
                  <img
                    src={images[currentImageIndex]}
                    alt={translateContent(chalet, 'name')}
                    className="w-full h-full object-cover"
                  />
                  {images.length > 1 && (
                    <>
                      <button
                        onClick={() => setCurrentImageIndex(i => (i - 1 + images.length) % images.length)}
                        className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/80 dark:bg-slate-800/80 rounded-full flex items-center justify-center hover:bg-white dark:hover:bg-slate-800 transition-colors"
                      >
                        <ChevronLeft className="w-6 h-6" />
                      </button>
                      <button
                        onClick={() => setCurrentImageIndex(i => (i + 1) % images.length)}
                        className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/80 dark:bg-slate-800/80 rounded-full flex items-center justify-center hover:bg-white dark:hover:bg-slate-800 transition-colors"
                      >
                        <ChevronRight className="w-6 h-6" />
                      </button>
                      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2">
                        {images.map((_, i) => (
                          <button
                            key={i}
                            onClick={() => setCurrentImageIndex(i)}
                            className={`w-2 h-2 rounded-full transition-colors ${
                              i === currentImageIndex ? 'bg-white' : 'bg-white/50'
                            }`}
                          />
                        ))}
                      </div>
                    </>
                  )}
                </>
              ) : (
                <div className="h-full flex items-center justify-center">
                  <Home className="w-20 h-20 text-slate-400" />
                </div>
              )}
            </motion.div>

            {/* Chalet Info */}
            <Card>
              <CardHeader>
                <CardTitle className="text-2xl">{translateContent(chalet, 'name')}</CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Description */}
                {translateContent(chalet, 'description') && (
                  <p className="text-slate-600 dark:text-slate-400">
                    {translateContent(chalet, 'description')}
                  </p>
                )}

                {/* Specs */}
                <div className="grid grid-cols-3 gap-4 p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">
                  <div className="flex flex-col items-center text-center">
                    <Users className="w-6 h-6 text-green-500 mb-1" />
                    <span className="text-lg font-bold">{chalet.capacity}</span>
                    <span className="text-xs text-slate-500">{tCommon('guests')}</span>
                  </div>
                  <div className="flex flex-col items-center text-center">
                    <Bed className="w-6 h-6 text-green-500 mb-1" />
                    <span className="text-lg font-bold">{chalet.bedroom_count || 0}</span>
                    <span className="text-xs text-slate-500">{tCommon('bedrooms')}</span>
                  </div>
                  <div className="flex flex-col items-center text-center">
                    <Bath className="w-6 h-6 text-green-500 mb-1" />
                    <span className="text-lg font-bold">{chalet.bathroom_count || 0}</span>
                    <span className="text-xs text-slate-500">{tCommon('bathrooms')}</span>
                  </div>
                </div>

                {/* Amenities */}
                {chalet.amenities && chalet.amenities.length > 0 && (
                  <div>
                    <h4 className="font-semibold mb-3">{t('amenities')}</h4>
                    <div className="flex flex-wrap gap-2">
                      {chalet.amenities.map((amenity) => {
                        const Icon = amenityIcons[amenity] || amenityIcons[amenity.toLowerCase()] || Home;
                        return (
                          <span
                            key={amenity}
                            className="inline-flex items-center px-3 py-1.5 bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-300 rounded-full text-sm"
                          >
                            <Icon className="w-4 h-4 mr-1.5" />
                            {amenity}
                          </span>
                        );
                      })}
                    </div>
                  </div>
                )}

                {/* Pricing */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-green-50 dark:bg-green-900/20 rounded-lg">
                    <p className="text-sm text-slate-500">{t('weekdayRate')}</p>
                    <p className="text-2xl font-bold text-green-600">
                      {formatCurrency(chalet.base_price || 0, currency)}
                    </p>
                    <p className="text-xs text-slate-500">{tCommon('perNight')}</p>
                  </div>
                  <div className="p-4 bg-amber-50 dark:bg-amber-900/20 rounded-lg">
                    <p className="text-sm text-slate-500">{t('weekendRate')}</p>
                    <p className="text-2xl font-bold text-amber-600">
                      {formatCurrency(chalet.weekend_price || chalet.base_price || 0, currency)}
                    </p>
                    <p className="text-xs text-slate-500">{tCommon('perNight')} (Fri-Sat)</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Right Column - Booking Form */}
          <div className="lg:col-span-2">
            <Card className="sticky top-4">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Calendar className="w-5 h-5" />
                  {t('bookNow')}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <form onSubmit={handleSubmit} className="space-y-4">
                  {/* Availability Calendar with Daily Prices */}
                  <AvailabilityCalendar
                    blockedDates={blockedDates}
                    selectedCheckIn={checkInDate || undefined}
                    selectedCheckOut={checkOutDate || undefined}
                    onDateSelect={(checkIn, checkOut) => {
                      setCheckInDate(checkIn);
                      setCheckOutDate(checkOut || '');
                    }}
                    dailyPrices={dailyPricesMap as Record<string, { price: number; type: 'weekday' | 'weekend' | 'holiday' | 'seasonal'; ruleName?: string; isBlocked: boolean }>}
                    formatPrice={(amount) => formatCurrency(amount, currency)}
                    maxMonthsAhead={3}
                  />

                  {/* Guests */}
                  <div>
                    <label className="block text-sm font-medium mb-1">{tCommon('guests')}</label>
                    <div className="flex items-center gap-4">
                      <button
                        type="button"
                        onClick={() => setNumberOfGuests(g => Math.max(1, g - 1))}
                        className="w-10 h-10 rounded-full border flex items-center justify-center hover:bg-slate-100 dark:hover:bg-slate-700"
                      >
                        <Minus className="w-4 h-4" />
                      </button>
                      <span className="text-lg font-semibold">{numberOfGuests}</span>
                      <button
                        type="button"
                        onClick={() => setNumberOfGuests(g => Math.min(chalet.capacity, g + 1))}
                        className="w-10 h-10 rounded-full border flex items-center justify-center hover:bg-slate-100 dark:hover:bg-slate-700"
                      >
                        <Plus className="w-4 h-4" />
                      </button>
                      <span className="text-sm text-slate-500">
                        (max {chalet.capacity})
                      </span>
                    </div>
                  </div>

                  {/* Add-ons */}
                  {addOns.length > 0 && (
                    <div>
                      <label className="block text-sm font-medium mb-2">{t('addOns')}</label>
                      <div className="space-y-2">
                        {addOns.filter(a => a.is_active).map((addOn) => {
                          const selected = selectedAddOns.find(a => a.addOnId === addOn.id);
                          return (
                            <div
                              key={addOn.id}
                              className={`p-3 border rounded-lg cursor-pointer transition-colors ${
                                selected
                                  ? 'border-green-500 bg-green-50 dark:bg-green-900/20'
                                  : 'border-slate-200 dark:border-slate-700 hover:border-green-300'
                              }`}
                              onClick={() => handleAddOnToggle(addOn.id)}
                            >
                              <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                                    selected ? 'border-green-500 bg-green-500' : 'border-slate-300'
                                  }`}>
                                    {selected && <Check className="w-3 h-3 text-white" />}
                                  </div>
                                  <span className="font-medium">{translateContent(addOn, 'name')}</span>
                                </div>
                                <span className="text-sm text-slate-600 dark:text-slate-400">
                                  {formatCurrency(addOn.price, currency)}
                                  {addOn.price_type === 'per_night' && '/night'}
                                </span>
                              </div>
                              {selected && (
                                <div className="flex items-center gap-2 mt-2 ml-7" onClick={e => e.stopPropagation()}>
                                  <button
                                    type="button"
                                    onClick={() => updateAddOnQuantity(addOn.id, -1)}
                                    className="w-6 h-6 rounded border flex items-center justify-center"
                                  >
                                    <Minus className="w-3 h-3" />
                                  </button>
                                  <span>{selected.quantity}</span>
                                  <button
                                    type="button"
                                    onClick={() => updateAddOnQuantity(addOn.id, 1)}
                                    className="w-6 h-6 rounded border flex items-center justify-center"
                                  >
                                    <Plus className="w-3 h-3" />
                                  </button>
                                </div>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}

                  {/* Contact Info */}
                  <div className="space-y-3 pt-4 border-t">
                    <h4 className="font-semibold">{t('contactInfo')}</h4>
                    <div>
                      <label className="block text-sm font-medium mb-1">{tCommon('fullName')}</label>
                      <Input
                        value={customerName}
                        onChange={(e) => setCustomerName(e.target.value)}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium mb-1">{tCommon('email')}</label>
                      <Input
                        type="email"
                        value={customerEmail}
                        onChange={(e) => setCustomerEmail(e.target.value)}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium mb-1">{tCommon('phone')}</label>
                      <Input
                        type="tel"
                        value={customerPhone}
                        onChange={(e) => setCustomerPhone(e.target.value)}
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium mb-1">{t('specialRequests')}</label>
                      <textarea
                        value={specialRequests}
                        onChange={(e) => setSpecialRequests(e.target.value)}
                        className="input w-full h-20"
                        placeholder={t('specialRequestsPlaceholder')}
                      />
                    </div>
                  </div>

                  {/* Pricing Summary */}
                  {pricing && (
                    <div className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg space-y-2">
                      <div className="flex justify-between text-sm">
                        <span>{pricing.nights} {pricing.nights === 1 ? 'night' : 'nights'}</span>
                        <span>{formatCurrency(pricing.baseAmount, currency)}</span>
                      </div>
                      {/* Nightly breakdown */}
                      {pricing.nightBreakdown && pricing.nightBreakdown.length > 0 && pricing.nightBreakdown.length <= 14 && (
                        <div className="space-y-1 pl-2 border-l-2 border-slate-200 dark:border-slate-600 ml-1">
                          {pricing.nightBreakdown.map((night) => {
                            const typeLabel = { weekday: '', weekend: '(weekend)', holiday: '(holiday)', seasonal: '(seasonal)' }[night.type] || '';
                            return (
                              <div key={night.date} className="flex justify-between text-xs text-slate-500 dark:text-slate-400">
                                <span>{new Date(night.date + 'T12:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} {typeLabel}</span>
                                <span>{formatCurrency(night.price, currency)}</span>
                              </div>
                            );
                          })}
                        </div>
                      )}
                      {pricing.addOnsAmount > 0 && (
                        <div className="flex justify-between text-sm">
                          <span>{t('addOns')}</span>
                          <span>{formatCurrency(pricing.addOnsAmount, currency)}</span>
                        </div>
                      )}
                      <div className="flex justify-between font-semibold pt-2 border-t">
                        <span>{tCommon('total')}</span>
                        <span className="text-lg text-green-600">{formatCurrency(pricing.totalAmount, currency)}</span>
                      </div>
                      <div className="flex justify-between text-sm text-amber-600">
                        <span>{t('depositRequired')} (30%)</span>
                        <span>{formatCurrency(pricing.depositAmount, currency)}</span>
                      </div>
                    </div>
                  )}

                  <Button
                    type="submit"
                    className="w-full"
                    size="lg"
                    isLoading={isSubmitting}
                    disabled={!pricing || isSubmitting}
                  >
                    {t('submitBooking')}
                  </Button>
                </form>
              </CardContent>
            </Card>
          </div>
        </div>
      </main>
    </div>
  );
}

'use client';

import { useEffect, useState, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency, formatDate } from '@/lib/utils';
import { useSettingsStore } from '@/stores/settingsStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  CheckCircle2,
  Calendar,
  Users,
  Home,
  Mail,
  Phone,
  ArrowRight,
  Loader2,
  AlertCircle,
} from 'lucide-react';

interface Booking {
  id: string;
  booking_number: string;
  chalet_id: string;
  customer_name: string;
  customer_email: string;
  customer_phone: string;
  check_in_date: string;
  check_out_date: string;
  number_of_guests: number;
  number_of_nights: number;
  base_amount: number;
  add_ons_amount: number;
  deposit_amount: number;
  total_amount: number;
  status: string;
  payment_status: string;
  special_requests?: string;
  chalet?: {
    name: string;
    images?: string[];
  };
}

function BookingConfirmationContent() {
  const searchParams = useSearchParams();
  const t = useTranslations('chalets');
  const tCommon = useTranslations('common');
  const tErrors = useTranslations('errors');
  const currency = useSettingsStore((s) => s.currency);
  const [booking, setBooking] = useState<Booking | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const bookingId = searchParams.get('id');

  useEffect(() => {
    if (bookingId) {
      fetchBooking();
    } else {
      setError(tErrors('noBookingId'));
      setLoading(false);
    }
  }, [bookingId]);

  const fetchBooking = async () => {
    try {
      const response = await api.get(`/chalets/bookings/${bookingId}`);
      setBooking(response.data.data);
    } catch (err) {
      setError(tErrors('failedToLoad'));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-resort-sand dark:bg-slate-900">
        <Loader2 className="w-8 h-8 animate-spin text-primary-600" />
      </div>
    );
  }

  if (error || !booking) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-resort-sand dark:bg-slate-900">
        <Card className="max-w-md mx-auto">
          <CardContent className="text-center py-8">
            <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">{error || tErrors('bookingNotFound')}</h2>
            <Link href="/chalets">
              <Button className="mt-4">{t('backToChalets')}</Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-green-50 to-white dark:from-slate-900 dark:to-slate-800 py-12">
      <div className="max-w-2xl mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: 'spring' }}
            className="w-20 h-20 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-4"
          >
            <CheckCircle2 className="w-10 h-10 text-green-600 dark:text-green-400" />
          </motion.div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white mb-2">
            {t('bookingConfirmed')}
          </h1>
          <p className="text-slate-600 dark:text-slate-400">
            {t('bookingConfirmationMessage')}
          </p>
        </motion.div>

        <Card>
          <CardHeader className="bg-green-50 dark:bg-green-900/20 border-b">
            <CardTitle className="flex items-center justify-between">
              <span>{t('bookingDetails')}</span>
              <span className="text-sm font-mono bg-white dark:bg-slate-800 px-3 py-1 rounded-full">
                #{booking.booking_number}
              </span>
            </CardTitle>
          </CardHeader>
          <CardContent className="divide-y divide-slate-200 dark:divide-slate-700">
            {/* Chalet */}
            <div className="py-4 flex items-center gap-4">
              <div className="w-12 h-12 bg-green-100 dark:bg-green-900/30 rounded-lg flex items-center justify-center">
                <Home className="w-6 h-6 text-green-600" />
              </div>
              <div>
                <p className="text-sm text-slate-500">{t('chalet')}</p>
                <p className="font-semibold">{booking.chalet?.name || 'Chalet'}</p>
              </div>
            </div>

            {/* Dates */}
            <div className="py-4 flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-100 dark:bg-blue-900/30 rounded-lg flex items-center justify-center">
                <Calendar className="w-6 h-6 text-blue-600" />
              </div>
              <div className="flex-1 grid grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-slate-500">{t('checkIn')}</p>
                  <p className="font-semibold">{formatDate(booking.check_in_date)}</p>
                </div>
                <div>
                  <p className="text-sm text-slate-500">{t('checkOut')}</p>
                  <p className="font-semibold">{formatDate(booking.check_out_date)}</p>
                </div>
              </div>
            </div>

            {/* Guests */}
            <div className="py-4 flex items-center gap-4">
              <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900/30 rounded-lg flex items-center justify-center">
                <Users className="w-6 h-6 text-purple-600" />
              </div>
              <div>
                <p className="text-sm text-slate-500">{tCommon('guests')}</p>
                <p className="font-semibold">{booking.number_of_guests} guests • {booking.number_of_nights} nights</p>
              </div>
            </div>

            {/* Contact */}
            <div className="py-4 space-y-2">
              <div className="flex items-center gap-2 text-sm">
                <Mail className="w-4 h-4 text-slate-400" />
                <span>{booking.customer_email}</span>
              </div>
              <div className="flex items-center gap-2 text-sm">
                <Phone className="w-4 h-4 text-slate-400" />
                <span>{booking.customer_phone}</span>
              </div>
            </div>

            {/* Pricing */}
            <div className="py-4 space-y-2">
              <div className="flex justify-between text-sm">
                <span>{booking.number_of_nights} nights accommodation</span>
                <span>{formatCurrency(booking.base_amount, currency)}</span>
              </div>
              {booking.add_ons_amount > 0 && (
                <div className="flex justify-between text-sm">
                  <span>{t('addOns')}</span>
                  <span>{formatCurrency(booking.add_ons_amount, currency)}</span>
                </div>
              )}
              <div className="flex justify-between font-semibold pt-2 border-t">
                <span>{tCommon('total')}</span>
                <span className="text-lg text-green-600">{formatCurrency(booking.total_amount, currency)}</span>
              </div>
              <div className="flex justify-between text-sm text-amber-600 bg-amber-50 dark:bg-amber-900/20 p-2 rounded">
                <span>{t('depositRequired')}</span>
                <span>{formatCurrency(booking.deposit_amount, currency)}</span>
              </div>
            </div>

            {/* Special Requests */}
            {booking.special_requests && (
              <div className="py-4">
                <p className="text-sm text-slate-500 mb-1">{t('specialRequests')}</p>
                <p className="text-sm">{booking.special_requests}</p>
              </div>
            )}
          </CardContent>
        </Card>

        <div className="mt-6 flex flex-col sm:flex-row gap-4 justify-center">
          <Link href="/chalets">
            <Button variant="outline">{t('browseMoreChalets')}</Button>
          </Link>
          <Link href="/profile">
            <Button className="gap-2">
              {t('viewMyBookings')}
              <ArrowRight className="w-4 h-4" />
            </Button>
          </Link>
        </div>

        <p className="text-center text-sm text-slate-500 mt-6">
          {t('confirmationEmailSent')}
        </p>
      </div>
    </div>
  );
}

export default function BookingConfirmationPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center bg-resort-sand dark:bg-slate-900">
        <Loader2 className="w-8 h-8 animate-spin text-primary-600" />
      </div>
    }>
      <BookingConfirmationContent />
    </Suspense>
  );
}

'use client';

import { useQuery } from '@tanstack/react-query';
import Link from 'next/link';
import { useTranslations } from 'next-intl';
import { chaletsApi } from '@/lib/api';
import { formatCurrency } from '@/lib/utils';
import { useSettingsStore } from '@/stores/settingsStore';
import { useSiteSettings } from '@/lib/settings-context';
import { useContentTranslation } from '@/lib/translate';
import { Loader2, Home, Users, Bed, Bath, Wifi, Wind, UtensilsCrossed, Car, AlertCircle, Star, MapPin, ChevronRight, Sparkles } from 'lucide-react';
import { motion } from 'framer-motion';
import { AuroraSection } from '@/components/effects/AuroraBackground';
import { Card3D, TiltCard, FloatingCard } from '@/components/effects/Card3D';
import { SpotlightCard } from '@/components/effects/GlowingBorder';
import { GradientText, RevealHeading } from '@/components/effects/TextEffects';
import { AnimatedCounter } from '@/components/effects/AnimatedCounter';

interface Chalet {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  description?: string;
  description_ar?: string;
  description_fr?: string;
  capacity: number;
  // Support both camelCase and snake_case from API
  bedroomCount?: number;
  bedroom_count?: number;
  bathroomCount?: number;
  bathroom_count?: number;
  amenities?: string[] | null;
  images?: string[] | null;
  basePrice?: number;
  base_price?: number;
  weekendPrice?: number;
  weekend_price?: number;
  isActive?: boolean;
  is_active?: boolean;
  isFeatured?: boolean;
  is_featured?: boolean;
}

const amenityIcons: Record<string, React.ElementType> = {
  WiFi: Wifi,
  AC: Wind,
  Kitchen: UtensilsCrossed,
  Parking: Car,
};

// Animation variants
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1
    }
  }
};

const cardVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.5,
      ease: "easeOut" as const
    }
  }
};

export default function ChaletsPage() {
  const t = useTranslations('chalets');
  const tCommon = useTranslations('common');
  const currency = useSettingsStore((s) => s.currency);
  const { settings, modules } = useSiteSettings();
  const chaletsModule = modules.find(m => m.slug === 'chalets');
  const { translateContent, isRTL } = useContentTranslation();

  const depositPercent = settings.depositPercent || 30;

  // FIX Iter-2: Removed enabled guard — fires immediately, refetches when module loads
  const { data, isLoading, error } = useQuery({
    queryKey: ['chalets', chaletsModule?.id],
    queryFn: () => chaletsApi.getChalets(chaletsModule?.id),
