import { toast } from 'sonner';
import { api } from '@/lib/api';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import { useSiteSettings } from '@/lib/settings-context';
import {
  MessageCircle,
  Send,
  Phone,
  Mail,
  MapPin,
  Clock,
  CheckCircle2,
  AlertCircle,
} from 'lucide-react';

interface ContactForm {
  name: string;
  email: string;
  phone: string;
  subject: string;
  message: string;
}

const initialForm: ContactForm = {
  name: '',
  email: '',
  phone: '',
  subject: '',
  message: '',
};

export default function ContactPage() {
  const { settings } = useSiteSettings();
  const [form, setForm] = useState<ContactForm>(initialForm);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');

    try {
      await api.post('/support/contact', form);
      setSubmitted(true);
      setForm(initialForm);
      toast.success('Message sent successfully! We\'ll get back to you soon.');
    } catch (err: unknown) {
      const axiosError = err as { response?: { data?: { error?: string } } };
      setError(axiosError.response?.data?.error || 'Failed to send message. Please try again.');
      toast.error('Failed to send message');
    } finally {
      setIsSubmitting(false);
    }
  };

  const contactInfo = [
    {
      icon: Phone,
      label: 'Phone',
      value: settings.phone || '+961 XX XXX XXX',
      href: `tel:${settings.phone || '+961000000000'}`,
    },
    {
      icon: Mail,
      label: 'Email',
      value: settings.email || 'info@ironparadisegym.com',
      href: `mailto:${settings.email || 'info@ironparadisegym.com'}`,
    },
    {
      icon: MapPin,
      label: 'Address',
      value: settings.address || 'Iron Paradise Gym, Lebanon',
      href: '#',
    },
    {
      icon: Clock,
      label: 'Reception Hours',
      value: settings.receptionHours || '24/7',
      href: '#',
    },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <motion.div
          initial="hidden"
          animate="visible"
          variants={staggerContainer}
          className="space-y-12"
        >
          {/* Header */}
          <motion.div variants={fadeInUp} className="text-center">
            <h1 className="text-4xl font-bold text-slate-900 dark:text-white mb-4">
              Contact Us
            </h1>
            <p className="text-lg text-slate-600 dark:text-slate-400 max-w-2xl mx-auto">
              Have a question or need assistance? We're here to help. Reach out to us and we'll respond as soon as possible.
            </p>
          </motion.div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Contact Form */}
            <motion.div variants={fadeInUp} className="lg:col-span-2">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <MessageCircle className="w-5 h-5 text-primary-600" />
                    Send us a Message
                  </CardTitle>
                  <CardDescription>
                    Fill out the form below and we'll get back to you within 24 hours.
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  {submitted ? (
                    <div className="text-center py-8">
                      <CheckCircle2 className="w-16 h-16 text-green-500 mx-auto mb-4" />
                      <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-2">
                        Message Sent!
                      </h3>
                      <p className="text-slate-600 dark:text-slate-400 mb-4">
                        Thank you for contacting us. We'll respond to your inquiry shortly.
                      </p>
                      <Button onClick={() => setSubmitted(false)}>
                        Send Another Message
                      </Button>
                    </div>
                  ) : (
                    <form onSubmit={handleSubmit} className="space-y-6">
                      {error && (
                        <div className="flex items-center gap-2 p-4 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-400 rounded-lg">
                          <AlertCircle className="w-5 h-5" />
                          {error}
                        </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Your Name *
                          </label>
                          <Input
                            required
                            value={form.name}
                            onChange={(e) => setForm({ ...form, name: e.target.value })}
                            placeholder="John Doe"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Email Address *
                          </label>
                          <Input
                            required
                            type="email"
                            value={form.email}
                            onChange={(e) => setForm({ ...form, email: e.target.value })}
                            placeholder="john@example.com"
                          />
                        </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Phone Number
                          </label>
                          <Input
                            value={form.phone}
                            onChange={(e) => setForm({ ...form, phone: e.target.value })}
                            placeholder="+961 XX XXX XXX"
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Subject *
                          </label>
                          <Input
                            required
                            value={form.subject}
                            onChange={(e) => setForm({ ...form, subject: e.target.value })}
                            placeholder="How can we help?"
                          />
                        </div>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                          Message *
                        </label>
                        <textarea
                          required
                          rows={5}
                          value={form.message}
                          onChange={(e) => setForm({ ...form, message: e.target.value })}
                          placeholder="Tell us more about your inquiry..."
                          className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent resize-none"
                        />
                      </div>

                      <Button type="submit" isLoading={isSubmitting} className="w-full">
                        <Send className="w-4 h-4 mr-2" />
                        Send Message
                      </Button>
                    </form>
                  )}
                </CardContent>
              </Card>
            </motion.div>

            {/* Contact Info */}
            <motion.div variants={fadeInUp} className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>Contact Information</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {contactInfo.map((info) => {
                      const Icon = info.icon;
                      return (
                        <a
                          key={info.label}
                          href={info.href}
                          className="flex items-start gap-4 p-3 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                        >
                          <div className="p-2 rounded-lg bg-primary-100 dark:bg-primary-900/30">
                            <Icon className="w-5 h-5 text-primary-600" />
                          </div>
                          <div>
                            <p className="text-sm text-slate-500 dark:text-slate-400">{info.label}</p>
                            <p className="font-medium text-slate-900 dark:text-white">{info.value}</p>
                          </div>
                        </a>
                      );
                    })}
                  </div>
                </CardContent>
              </Card>

              {/* Business Hours */}
              <Card>
                <CardHeader>
                  <CardTitle>Business Hours</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    <div className="flex justify-between">
                      <span className="text-slate-600 dark:text-slate-400">Restaurant</span>
                      <span className="font-medium text-slate-900 dark:text-white">
                        {settings.restaurantHours || '8:00 AM - 11:00 PM'}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-600 dark:text-slate-400">Pool</span>
                      <span className="font-medium text-slate-900 dark:text-white">
                        {settings.poolHours || '9:00 AM - 7:00 PM'}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-slate-600 dark:text-slate-400">Reception</span>
                      <span className="font-medium text-slate-900 dark:text-white">
                        {settings.receptionHours || '24/7'}
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { motion } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { Mail, Loader2, AlertCircle, CheckCircle, ArrowLeft } from 'lucide-react';
import { authApi } from '@/lib/api'; // FIX Iter-12: use api client instead of raw fetch

export default function ForgotPasswordPage() {
  const t = useTranslations('auth');
  const tCommon = useTranslations('common');

  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      // FIX Iter-12: use authApi instead of raw fetch (correct URL, retry, CSRF)
      const response = await authApi.forgotPassword(email);
      const data = response.data;

      if (data.success) {
        setSuccess(true);
      } else {
        setError(data.error || 'Failed to send reset email');
      }
    } catch (err) {
      setError('Network error. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-600 via-primary-700 to-primary-900 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md"
      >
        {/* Logo */}
        <div className="text-center mb-8">
          <Link href="/" className="inline-flex items-center gap-2">
            <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center shadow-lg">
              <span className="text-primary-600 font-bold text-xl">V2</span>
            </div>
            <span className="text-2xl font-bold text-white">Resort</span>
          </Link>
        </div>

        {/* Card */}
        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl p-8">
          {success ? (
            /* Success State */
            <div className="text-center">
              <div className="w-16 h-16 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-4">
                <CheckCircle className="w-8 h-8 text-green-600" />
              </div>
              <h1 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
                Check Your Email
              </h1>
              <p className="text-slate-600 dark:text-slate-400 mb-6">
                If an account exists for <strong>{email}</strong>, we've sent a password reset link.
                Please check your inbox and spam folder.
              </p>
              <Link
                href="/login"
                className="inline-flex items-center gap-2 text-primary-600 hover:text-primary-700 font-medium"
              >
                <ArrowLeft className="w-4 h-4" />
                Back to Login
              </Link>
            </div>
          ) : (
            /* Form State */
            <>
              <div className="text-center mb-6">
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
                  Forgot Password?
                </h1>
                <p className="text-slate-600 dark:text-slate-400 mt-1">
                  Enter your email and we'll send you a reset link
                </p>
              </div>

              {error && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="mb-4 p-4 bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg flex items-center gap-3"
                >
                  <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0" />
                  <span className="text-red-700 dark:text-red-300 text-sm">{error}</span>
                </motion.div>
              )}

              <form onSubmit={handleSubmit} className="space-y-5">
                <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                    Email Address
                  </label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="w-full pl-10 pr-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all"
                      placeholder="your@email.com"
                      required
                    />
                  </div>
                </div>

                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full py-3 bg-primary-600 hover:bg-primary-700 text-white font-semibold rounded-lg shadow-lg shadow-primary-600/30 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin" />
                      Sending...
                    </>
                  ) : (
                    'Send Reset Link'
                  )}
                </button>
              </form>

              <div className="mt-6 text-center">
                <Link
                  href="/login"
                  className="inline-flex items-center gap-2 text-slate-600 dark:text-slate-400 hover:text-primary-600 text-sm"
                >
                  <ArrowLeft className="w-4 h-4" />
                  Back to Login
                </Link>
              </div>
            </>
          )}
        </div>
      </motion.div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { useAuth } from '@/lib/auth-context';
import { formatCurrency } from '@/lib/utils';
import { currencySymbols } from '@/stores/settingsStore'; // FIX Iter-15: Import for currency-aware symbol
import { toast } from 'sonner';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/Tabs';
import { fadeInUp, staggerContainer } from '@/lib/animations/presets';
import {
  Gift,
  CreditCard,
  ChevronRight,
  Loader2,
  Mail,
  User,
  Check,
  ArrowRight,
  Sparkles,
  Heart,
  PartyPopper,
  Search,
  RefreshCw,
} from 'lucide-react';
import Link from 'next/link';

interface GiftCardTemplate {
  id: string;
  name: string;
  amount: number;
  design: {
    background: string;
    pattern?: string;
    textColor?: string;
  };
  isActive: boolean;
}

export default function PublicGiftCardsPage() {
  const { isAuthenticated } = useAuth();
  const [templates, setTemplates] = useState<GiftCardTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedTemplate, setSelectedTemplate] = useState<GiftCardTemplate | null>(null);
  const [customAmount, setCustomAmount] = useState('');
  const [step, setStep] = useState<'select' | 'details' | 'payment' | 'success'>('select');
  const [purchasing, setPurchasing] = useState(false);
  const [purchasedCard, setPurchasedCard] = useState<any>(null);
  
  // Balance check
  const [balanceCode, setBalanceCode] = useState('');
  const [balanceResult, setBalanceResult] = useState<{ balance: number; status: string } | null>(null);
  const [checkingBalance, setCheckingBalance] = useState(false);
  
  const [giftDetails, setGiftDetails] = useState({
    recipientName: '',
    recipientEmail: '',
    message: '',
    senderName: '',
    senderEmail: '', // For guests
  });

  // FIX Iter-16: AbortController to prevent state updates on unmounted component
  useEffect(() => {
    const controller = new AbortController();
    const load = async () => {
      try {
        const res = await api.get('/giftcards/templates', { signal: controller.signal });
        if (controller.signal.aborted) return;
        if (res.data.success) {
          setTemplates(res.data.data.filter((t: GiftCardTemplate) => t.isActive));
        }
      } catch (err: any) {
        if (err?.name === 'CanceledError' || controller.signal.aborted) return;
        // Use defaults if API fails
        setTemplates([
          { id: '1', name: 'Classic', amount: 25, design: { background: 'linear-gradient(135deg, #3b82f6, #6366f1)' }, isActive: true },
          { id: '2', name: 'Premium', amount: 50, design: { background: 'linear-gradient(135deg, #8b5cf6, #a855f7)' }, isActive: true },
          { id: '3', name: 'Deluxe', amount: 100, design: { background: 'linear-gradient(135deg, #f59e0b, #ef4444)' }, isActive: true },
          { id: '4', name: 'Ultimate', amount: 200, design: { background: 'linear-gradient(135deg, #10b981, #14b8a6)' }, isActive: true },
        ]);
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    };
    load();
    return () => controller.abort();
  }, []);

  const handleSelectAmount = (template: GiftCardTemplate | null, amount?: number) => {
    if (template) {
      setSelectedTemplate(template);
      setCustomAmount('');
    } else if (amount) {
      setSelectedTemplate(null);
      setCustomAmount(amount.toString());
    }
    setStep('details');
  };

  const handlePurchase = async () => {
    if (!giftDetails.recipientEmail || !giftDetails.senderName || (!isAuthenticated && !giftDetails.senderEmail)) {
      toast.error('Please fill in all required fields');
      return;
    }

    const amount = selectedTemplate?.amount || parseFloat(customAmount);
    if (!amount || amount < 10) {
      toast.error(`Minimum gift card amount is ${formatCurrency(10)}`);
      return;
    }

    setPurchasing(true);
    try {
      const res = await api.post('/giftcards/purchase', {
        templateId: selectedTemplate?.id,
        customAmount: selectedTemplate ? undefined : amount,
        recipientName: giftDetails.recipientName || undefined,
        recipientEmail: giftDetails.recipientEmail,
        personalMessage: giftDetails.message || undefined,
        senderName: giftDetails.senderName,
        senderEmail: giftDetails.senderEmail || undefined,
        isGuestPurchase: !isAuthenticated,
      });

      if (res.data.success) {
        setPurchasedCard(res.data.data);
        setStep('success');
        toast.success('Gift card purchased successfully!');
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Failed to purchase gift card');
    } finally {
      setPurchasing(false);
    }
  };

  const handleCheckBalance = async () => {
    if (!balanceCode.trim()) {
      toast.error('Please enter a gift card code');
      return;
    }
    
    setCheckingBalance(true);
    setBalanceResult(null);
    try {
      const res = await api.get(`/giftcards/balance/${balanceCode.trim()}`);
      if (res.data.success) {
        setBalanceResult({
          balance: res.data.data.currentBalance,
          status: res.data.data.status,
        });
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Gift card not found');
    } finally {
      setCheckingBalance(false);
    }
  };

  const resetForm = () => {
    setStep('select');
    setSelectedTemplate(null);
    setCustomAmount('');
    setPurchasedCard(null);
    setGiftDetails({
      recipientName: '',
      recipientEmail: '',
      message: '',
      senderName: '',
      senderEmail: '',
    });
  };

  const currentAmount = selectedTemplate?.amount || parseFloat(customAmount) || 0;

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 via-pink-50 to-orange-50 dark:from-slate-900 dark:via-purple-900/20 dark:to-slate-900">
      {/* Hero Section */}
      <div className="relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-r from-purple-600/10 to-pink-600/10" />
        <div className="absolute -top-40 -right-40 w-80 h-80 bg-purple-400/20 rounded-full blur-3xl" />
        <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-pink-400/20 rounded-full blur-3xl" />
        
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="relative max-w-6xl mx-auto px-4 py-16 text-center"
        >
          <motion.div 
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: 'spring', delay: 0.2 }}
            className="w-24 h-24 mx-auto rounded-2xl bg-gradient-to-br from-purple-500 to-pink-600 flex items-center justify-center mb-6 shadow-2xl shadow-purple-500/30"
          >
            <Gift className="w-12 h-12 text-white" />
          </motion.div>
          <h1 className="text-4xl md:text-5xl font-bold text-slate-900 dark:text-white mb-4">
            Give the Gift of Experience
          </h1>
          <p className="text-xl text-slate-600 dark:text-slate-300 max-w-2xl mx-auto">
            Iron Paradise Gym gift cards are the perfect present for any occasion. 
            Redeemable for pool access, chalets, dining, and more.
          </p>
          
          {/* Feature badges */}
          <div className="flex flex-wrap justify-center gap-4 mt-8">
            <Badge className="bg-white/80 dark:bg-slate-800/80 text-slate-700 dark:text-slate-300 px-4 py-2 text-sm">
              <Sparkles className="w-4 h-4 mr-2 text-purple-500" />
              Instant Digital Delivery
            </Badge>
            <Badge className="bg-white/80 dark:bg-slate-800/80 text-slate-700 dark:text-slate-300 px-4 py-2 text-sm">
              <Heart className="w-4 h-4 mr-2 text-pink-500" />
              Personalized Message
            </Badge>
            <Badge className="bg-white/80 dark:bg-slate-800/80 text-slate-700 dark:text-slate-300 px-4 py-2 text-sm">
              <PartyPopper className="w-4 h-4 mr-2 text-orange-500" />
              Never Expires
            </Badge>
          </div>
        </motion.div>
      </div>

      {/* Main Content */}
      <div className="max-w-4xl mx-auto px-4 pb-16 -mt-8">
        <Tabs defaultValue="buy" className="w-full">
          <TabsList className="grid grid-cols-2 w-full max-w-md mx-auto mb-8 bg-white/80 dark:bg-slate-800/80 backdrop-blur-sm">
            <TabsTrigger value="buy">Buy Gift Card</TabsTrigger>
            <TabsTrigger value="balance">Check Balance</TabsTrigger>
          </TabsList>

          {/* Buy Gift Card Tab */}
          <TabsContent value="buy">
            <Card className="shadow-xl border-0 bg-white/90 dark:bg-slate-800/90 backdrop-blur-sm">
              <CardContent className="p-6 md:p-8">
                <AnimatePresence mode="wait">
                  {/* Step 1: Select Amount */}
                  {step === 'select' && (
                    <motion.div
                      key="select"
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: 20 }}
                      className="space-y-6"
                    >
                      <div className="text-center mb-8">
                        <h2 className="text-2xl font-bold text-slate-900 dark:text-white">
                          Choose Your Gift Amount
                        </h2>
                        <p className="text-slate-500 mt-1">
                          Select a preset amount or enter a custom value
                        </p>
                      </div>

                      {loading ? (
                        <div className="flex justify-center py-12">
                          <Loader2 className="w-8 h-8 animate-spin text-purple-500" />
                        </div>
                      ) : (
                        <>
                          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {templates.map((template) => (
                              <motion.button
                                key={template.id}
                                onClick={() => handleSelectAmount(template)}
                                className="relative rounded-xl overflow-hidden shadow-md hover:shadow-lg transition-all group"
                                whileHover={{ scale: 1.03 }}
                                whileTap={{ scale: 0.98 }}
                              >
                                <div 
                                  className="aspect-[3/2] p-4 flex flex-col items-center justify-center"
                                  style={{ 
                                    background: template.design.background,
                                    color: template.design.textColor || 'white'
                                  }}
                                >
                                  <Gift className="w-8 h-8 mb-2 opacity-80" />
                                  <p className="text-2xl font-bold">{formatCurrency(template.amount)}</p>
                                  <p className="text-sm opacity-80">{template.name}</p>
                                </div>
                              </motion.button>
                            ))}
                          </div>

                          <div className="border-t dark:border-slate-700 pt-6">
                            <p className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">
                              Or enter a custom amount ({formatCurrency(10)} - {formatCurrency(1000)})
                            </p>
                            <div className="flex gap-3">
                              <div className="relative flex-1">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">{currencySymbols.USD}</span>
