                  <h4 className="font-semibold text-slate-900 dark:text-white mb-2">{step.title}</h4>
                  <p className="text-sm text-slate-500">{step.desc}</p>
                </CardContent>
              </Card>
            ))}
          </div>
        </motion.div>
      </div>
    </div>
  );
}

