'use client';

import { useState, useEffect, useCallback } from 'react';
import { KioskMode, KioskStep, GuestInfo } from './types';
import api from '@/lib/api';

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

export function useKioskFlow(deviceId: string) {
  const [mode, setMode] = useState<KioskMode>('idle');
  const [step, setStep] = useState<KioskStep>('welcome');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [guestInfo, setGuestInfo] = useState<GuestInfo | null>(null);
  const [confirmationCode, setConfirmationCode] = useState('');
  const [sessionId, setSessionId] = useState<string | null>(null);

  // Auto-reset to idle after timeout
  useEffect(() => {
    let timeout: NodeJS.Timeout;
    if (mode !== 'idle') {
      timeout = setTimeout(() => {
        resetToIdle();
      }, 120000); // 2 minute timeout
    }
    return () => clearTimeout(timeout);
  }, [mode, step]);

  const resetToIdle = useCallback(() => {
    setMode('idle');
    setStep('welcome');
    setError(null);
    setGuestInfo(null);
    setConfirmationCode('');
    setSessionId(null);
  }, []);

  const startSession = useCallback(async (type: 'checkin' | 'checkout') => {
    setLoading(true);
    setError(null);
    try {
      const res = await api.post(`/kiosk/sessions/${deviceId}`, { sessionType: type });
      const data = res.data;
      
      if (!data.success) {
        setError(data.error || 'Failed to start session. Please try again.');
        return;
      }
      setSessionId(data.data?.id || data.data?.sessionId);
      setMode(type);
      setStep('identify');
    } catch (err) {
      console.error('Kiosk session creation failed:', err);
      setError('Kiosk service unavailable. Please contact reception.');
      return;
    } finally {
      setLoading(false);
    }
  }, [deviceId]);

  const lookupReservation = useCallback(async () => {
    if (!confirmationCode.trim()) {
      setError('Please enter your confirmation code');
      return;
    }
    
    setLoading(true);
    setError(null);
    try {
      const kioskEndpoint = mode === 'checkin' 
        ? `/kiosk/checkin/${deviceId}`
        : `/kiosk/checkout/${deviceId}`;
      
      const body = mode === 'checkin' 
        ? { confirmationNumber: confirmationCode.trim() }
        : { roomNumber: confirmationCode.trim() };
      
      const res = await api.post(kioskEndpoint, body);
      const data = res.data;
      
      if (data.success && data.data) {
        const booking = data.data;
        setGuestInfo({
          name: booking.guestName || booking.guest_name || 'Guest',
          room: booking.roomNumber || booking.room_number || 'TBD',
          checkInDate: booking.checkInDate || booking.check_in_date || new Date().toLocaleDateString(),
          checkOutDate: booking.checkOutDate || booking.check_out_date || new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toLocaleDateString(),
          balance: booking.balance || (mode === 'checkout' ? 0 : 0)
        });
        setSessionId(booking.sessionId || booking.id || sessionId);
        setStep('confirm');
      } else {
        setError(data.error || 'Reservation not found. Please check your details and try again.');
        return;
      }
    } catch (err) {
      console.error('Reservation lookup failed:', err);
      setError('Unable to look up reservation. Please contact reception.');
      return;
    } finally {
      setLoading(false);
    }
  }, [confirmationCode, mode, deviceId, sessionId]);

  const confirmGuest = useCallback(async () => {
    setLoading(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      if (mode === 'checkout' && guestInfo?.balance && guestInfo.balance > 0) {
        setStep('payment');
      } else if (mode === 'checkin') {
        setStep('key');
      } else {
        setStep('complete');
      }
    } finally {
      setLoading(false);
    }
  }, [mode, guestInfo]);

  const processPayment = useCallback(async () => {
    if (!sessionId || !deviceId) return;
    setLoading(true);
    setError(null);
    try {
      const res = await api.post(`/kiosk/transactions/${sessionId}/${deviceId}/payment`, {
        amount: guestInfo?.balance || 0,
        method: 'card'
      });
      if (!res.data.success) {
        setError(res.data.error || 'Payment failed. Please try again or contact reception.');
        return;
      }
      setStep('complete');
    } catch (err) {
      console.error('Payment processing failed:', err);
      setError('Payment processing failed. Please contact reception.');
    } finally {
      setLoading(false);
    }
  }, [sessionId, deviceId, guestInfo]);

  const encodeKey = useCallback(async () => {
    if (!sessionId || !deviceId) return;
    setLoading(true);
    setError(null);
    try {
      const res = await api.post(`/kiosk/transactions/${sessionId}/${deviceId}/key-encode`, {
        roomNumber: guestInfo?.room
      });
      if (!res.data.success) {
        setError(res.data.error || 'Key encoding failed. Please contact reception.');
        return;
      }
      setStep('complete');
    } catch (err) {
      console.error('Key encoding failed:', err);
      setError('Key encoding failed. Please contact reception.');
    } finally {
      setLoading(false);
    }
  }, [sessionId, deviceId, guestInfo]);

  return {
    mode,
    step,
    setStep,
    loading,
    error,
    guestInfo,
    confirmationCode,
    setConfirmationCode,
    resetToIdle,
    startSession,
    lookupReservation,
    confirmGuest,
    processPayment,
    encodeKey,
  };
}

import type { Metadata } from 'next';
import { Inter, Noto_Sans_Arabic } from 'next/font/google';
import '../styles/globals.css';
import { Providers } from './providers';
import { Toaster } from 'sonner';
import { defaultLocale, type Locale } from '@/i18n';

import Header from '@/components/layout/Header';
import Footer from '@/components/Footer';
import { PageTransition } from '@/components/effects/PageTransition';
import { JsonLd, generateResortSchema } from '@/lib/structured-data';

const inter = Inter({
  subsets: ['latin'],
  variable: '--font-inter',
});

const notoArabic = Noto_Sans_Arabic({
  subsets: ['arabic'],
  variable: '--font-arabic',
});

const getBaseUrl = () => {
  if (process.env.NEXT_PUBLIC_API_URL) return process.env.NEXT_PUBLIC_API_URL;
  return 'http://localhost:3005';
};

async function getSiteSettings() {
  try {
    const res = await fetch(`${getBaseUrl()}/api/settings`, { next: { revalidate: 60 } });
    if (!res.ok) throw new Error('Failed to fetch settings');
    const data = await res.json();
    return data.data || data;
  } catch (error) {
    console.error('Metadata fetch error:', error);
    return {
      resortName: 'Iron Paradise Gym',
      description: 'Premier resort platform.'
    };
  }
}

export async function generateMetadata(): Promise<Metadata> {
  const settings = await getSiteSettings();
  const title = settings.resortName || 'Iron Paradise Gym';
  const description = settings.description || 'Experience the perfect blend of relaxation and entertainment.';

  return {
    title: `${title} | Luxury Experience`,
    description,
    keywords: 'resort, luxury, dining, experience, vacation',
    manifest: '/manifest.json',
    icons: {
      icon: '/favicon.svg',
      shortcut: '/favicon.svg',
      apple: '/icons/icon-192x192.png',
    },
    appleWebApp: {
      capable: true,
      statusBarStyle: 'black-translucent',
      title: title,
    },
    openGraph: {
      title: `${title} | Luxury Experience`,
      description,
      type: 'website',
    },
    other: {
      'mobile-web-app-capable': 'yes',
    },
  };
}

export default async function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  // Use default locale on server
  const locale = defaultLocale;
  const isRtl = locale === 'ar';

  const settings = await getSiteSettings();

  const resortSchema = generateResortSchema({
    name: settings.resortName || 'Iron Paradise Gym',
    description: settings.description || 'Premier resort experience.',
    url: 'https://v2-ecosystem.vercel.app',
    telephone: '+1 234 567 8900',
    email: 'bookings@ironparadisegym.com',
    address: {
      street: '123 Resort Boulevard',
      city: 'Global City',
      region: 'State',
      country: 'Country',
    },
    images: ['https://v2-ecosystem.vercel.app/images/resort-cover.jpg'],
    priceRange: '$$',
    openingHours: ['10:00-23:00'],
  });

  // Theme detection script that runs BEFORE React hydrates
  // This prevents the "flash of wrong theme" on initial load
  const themeScript = `
(function() {
  try {
    // Get theme and mode from localStorage (set by previous visits)
    var theme = localStorage.getItem('v2-ecosystem-theme') || 'beach';
    var mode = localStorage.getItem('theme') || 'light';
    
    // Theme color mappings (must match theme-config.ts)
    var themes = {
      beach: { bg: '#f0fdfa', bgDark: '#042f2e', primary: '#0891b2' },
      mountain: { bg: '#fafaf9', bgDark: '#1c1917', primary: '#78716c' },
      sunset: { bg: '#fff7ed', bgDark: '#431407', primary: '#ea580c' },
      forest: { bg: '#f0fdf4', bgDark: '#052e16', primary: '#15803d' },
      midnight: { bg: '#faf5ff', bgDark: '#2e1065', primary: '#7c3aed' },
      luxury: { bg: '#fffbeb', bgDark: '#0f172a', primary: '#d97706' }
    };
    
    var t = themes[theme] || themes.beach;
    var isDark = mode === 'dark';
    var bgColor = isDark ? t.bgDark : t.bg;
    
    // Apply initial background color to prevent flash
    document.documentElement.style.setProperty('--initial-bg', bgColor);
    document.documentElement.style.setProperty('--color-primary', t.primary);
    document.documentElement.setAttribute('data-theme', theme);
    document.documentElement.setAttribute('data-color-mode', mode);
    document.documentElement.classList.add(mode);
    
    // Set body background immediately
    document.documentElement.style.backgroundColor = bgColor;
  } catch (e) {}
})();
`;

  return (
    <html
      lang={locale}
      dir={isRtl ? 'rtl' : 'ltr'}
      suppressHydrationWarning
    >
      <head>
        {/* Critical: Theme detection script runs BEFORE React hydrates */}
        <script dangerouslySetInnerHTML={{ __html: themeScript }} />
        <JsonLd data={resortSchema} />
        <meta name="theme-color" content="#3b82f6" />
        <meta name="apple-mobile-web-app-capable" content="yes" />
        <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
        <link rel="apple-touch-icon" href="/icons/icon-192x192.png" />
      </head>
      <body className={`${inter.variable} ${notoArabic.variable} ${isRtl ? 'font-arabic' : 'font-sans'} bg-cms-background transition-colors duration-300`}>
        <Providers>
          <Header />
          <main>
            <PageTransition>
              {children}
            </PageTransition>
          </main>
          <Footer />
          <Toaster position={isRtl ? 'top-left' : 'top-right'} richColors />
        </Providers>
      </body>
    </html>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { motion } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { Mail, Lock, Loader2, Eye, EyeOff, AlertCircle, Shield, KeyRound } from 'lucide-react';
import { useAuth } from '@/lib/auth-context';

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

export default function LoginPage() {
  const t = useTranslations('auth.login');
  const tAuth = useTranslations('auth');
  const tCommon = useTranslations('common');
  const router = useRouter();
  const { user, isAuthenticated, login, verify2FA } = useAuth();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  
  // 2FA state
  const [show2FA, setShow2FA] = useState(false);
  const [pending2FAUserId, setPending2FAUserId] = useState<string | null>(null);
  const [twoFactorCode, setTwoFactorCode] = useState('');
  const [useBackupCode, setUseBackupCode] = useState(false);

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated && user) {
      const roles = user.roles || [];
      if (roles.includes('super_admin') || roles.includes('admin')) {
        router.replace('/admin');
      } else if (roles.some((r: string) => r.includes('staff') || r.includes('manager'))) {
        router.replace('/staff');
      } else {
        router.replace('/');
      }
    }
  }, [isAuthenticated, user, router]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      // Use auth context login which updates state immediately
      const result = await login(email, password);

      // Check if 2FA is required
      if ('requiresTwoFactor' in result && result.requiresTwoFactor) {
        setPending2FAUserId(result.userId);
        setShow2FA(true);
        setIsLoading(false);
        return;
      }

      // Normal login success - result is a User at this point
      const userData = result as { id: string; email: string; fullName: string; roles: string[] };

      // Determine redirect based on roles
      const roles = userData.roles || [];

      // Use replace instead of push for cleaner navigation
      if (roles.includes('super_admin') || roles.includes('admin')) {
        window.location.href = '/admin'; // Force full page navigation
      } else if (roles.some((r: string) => r.includes('staff') || r.includes('manager'))) {
        window.location.href = '/staff';
      } else {
        window.location.href = '/';
      }
    } catch (err: unknown) {
      const error = err as Error;
      setError(error.message || 'Login failed. Please try again.');
      setIsLoading(false);
    }
  };

  const handle2FASubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!pending2FAUserId) return;
    
    setError('');
    setIsLoading(true);

    try {
      const userData = await verify2FA(pending2FAUserId, twoFactorCode);

      // Determine redirect based on roles
      const roles = userData.roles || [];

      if (roles.includes('super_admin') || roles.includes('admin')) {
        window.location.href = '/admin';
      } else if (roles.some((r: string) => r.includes('staff') || r.includes('manager'))) {
        window.location.href = '/staff';
      } else {
        window.location.href = '/';
      }
    } catch (err: unknown) {
      const error = err as Error;
      setError(error.message || '2FA verification failed. Please try again.');
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-600 via-primary-700 to-primary-900 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md"
      >
        {/* Logo */}
        <div className="text-center mb-8">
          <Link href="/" className="inline-flex items-center gap-2">
            <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center shadow-lg">
              <span className="text-primary-600 font-bold text-xl">V2</span>
            </div>
            <span className="text-2xl font-bold text-white">Resort</span>
          </Link>
        </div>

        {/* Login Card */}
        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl p-8">
          <div className="text-center mb-6">
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">
              {tAuth('welcomeBack')}
            </h1>
            <p className="text-slate-600 dark:text-slate-400 mt-1">
              {tAuth('signInToAccount')}
            </p>
          </div>

          {error && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              className="mb-4 p-4 bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800 rounded-lg flex items-center gap-3"
            >
              <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0" />
              <span className="text-red-700 dark:text-red-300 text-sm">{error}</span>
            </motion.div>
          )}

          {show2FA ? (
            /* 2FA Verification Form */
            <form onSubmit={handle2FASubmit} className="space-y-5">
              <div className="text-center mb-4">
                {useBackupCode ? (
                  <KeyRound className="w-12 h-12 text-primary-600 mx-auto mb-2" />
                ) : (
                  <Shield className="w-12 h-12 text-primary-600 mx-auto mb-2" />
                )}
                <h2 className="text-lg font-semibold text-slate-900 dark:text-white">
                  Two-Factor Authentication
                </h2>
                <p className="text-sm text-slate-600 dark:text-slate-400">
                  {useBackupCode 
                    ? 'Enter one of your backup codes (format: XXXX-XXXX)'
                    : 'Enter the 6-digit code from your authenticator app'}
                </p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  {useBackupCode ? 'Backup Code' : 'Verification Code'}
                </label>
                {useBackupCode ? (
                  <input
                    type="text"
                    value={twoFactorCode}
                    onChange={(e) => {
                      // Format as XXXX-XXXX (alphanumeric)
                      const val = e.target.value.toUpperCase().replace(/[^A-Z0-9-]/g, '');
                      if (val.length <= 9) {
                        // Auto-insert hyphen after 4 chars
                        if (val.length === 4 && !val.includes('-')) {
                          setTwoFactorCode(val + '-');
                        } else {
                          setTwoFactorCode(val);
                        }
                      }
                    }}
                    className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all text-center text-xl tracking-widest font-mono"
                    placeholder="XXXX-XXXX"
                    maxLength={9}
                    required
                    autoFocus
                    autoComplete="off" // FIX Iter-5: Add autocomplete attribute for backup code
                  />
                ) : (
                  <input
                    type="text"
                    value={twoFactorCode}
                    onChange={(e) => setTwoFactorCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                    className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all text-center text-2xl tracking-widest font-mono"
                    placeholder="000000"
                    maxLength={6}
                    required
                    autoFocus
                    autoComplete="one-time-code" // FIX Iter-5: Add autocomplete attribute for 2FA code
                  />
                )}
              </div>

              <button
                type="submit"
                disabled={isLoading || (useBackupCode ? twoFactorCode.length !== 9 : twoFactorCode.length !== 6)}
                className="w-full py-3 bg-primary-600 hover:bg-primary-700 text-white font-semibold rounded-lg shadow-lg shadow-primary-600/30 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {isLoading ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    Verifying...
                  </>
                ) : (
                  'Verify & Sign In'
                )}
              </button>

              <button
                type="button"
                onClick={() => { setUseBackupCode(!useBackupCode); setTwoFactorCode(''); setError(''); }}
                className="w-full py-2 text-primary-600 hover:text-primary-700 text-sm font-medium"
              >
                {useBackupCode ? '← Use authenticator code instead' : 'Use backup code instead →'}
              </button>

              <button
                type="button"
                onClick={() => { setShow2FA(false); setPending2FAUserId(null); setTwoFactorCode(''); setError(''); setUseBackupCode(false); }}
                className="w-full py-2 text-slate-600 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200 text-sm"
              >
                ← Back to login
              </button>
            </form>
          ) : (
            /* Normal Login Form */
            <form onSubmit={handleSubmit} className="space-y-5">
              {/* Email */}
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  {t('email')}
                </label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input
                    id="email"
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all"
                    placeholder="admin@v2ecosystem.com"
                    required
                    autoComplete="email" // FIX Iter-5: Add autocomplete attribute for email
                  />
                </div>
              </div>

              {/* Password */}
              <div>
                <div className="flex justify-between items-center mb-2">
                  <label htmlFor="password" className="block text-sm font-medium text-slate-700 dark:text-slate-300">
                    {t('password')}
                  </label>
                  <Link href="/forgot-password" className="text-xs text-primary-600 hover:text-primary-700">
                    {t('forgotPassword')}
                  </Link>
                </div>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full pl-10 pr-12 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all"
                    placeholder="••••••••"
                    required
                    autoComplete="current-password" // FIX Iter-5: Add autocomplete attribute for password
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                  >
                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
              </div>

              {/* Submit Button */}
              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3 bg-primary-600 hover:bg-primary-700 text-white font-semibold rounded-lg shadow-lg shadow-primary-600/30 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {isLoading ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    {t('signingIn')}
                  </>
                ) : (
                  t('title')
                )}
              </button>

              {/* Divider */}
              <div className="relative my-6">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-slate-300 dark:border-slate-600"></div>
                </div>
                <div className="relative flex justify-center text-sm">
                  <span className="px-2 bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400">
                    {t('orContinueWith')}
                  </span>
                </div>
              </div>

              {/* OAuth Buttons */}
              <div className="space-y-3">
                <a
                  href={`${API_URL}/api/auth/google`}
                  className="w-full py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 hover:bg-slate-50 dark:hover:bg-slate-600 transition-all flex items-center justify-center gap-3"
                >
                  <svg className="w-5 h-5" viewBox="0 0 24 24">
                    <path
                      fill="#4285F4"
                      d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                    />
                    <path
                      fill="#34A853"
                      d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                    />
                    <path
                      fill="#FBBC05"
                      d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                    />
                    <path
                      fill="#EA4335"
                      d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                    />
                  </svg>
                  <span className="text-slate-700 dark:text-slate-200 font-medium">{t('continueWithGoogle')}</span>
