          </div>

          {/* Quantity Controls */}
          <div className="mt-auto">
            {quantity > 0 ? (
              <motion.div
                initial={{ scale: 0.8 }}
                animate={{ scale: 1 }}
                className="flex items-center justify-center gap-4 bg-orange-50/80 dark:bg-slate-700/80 backdrop-blur-sm rounded-xl px-4 py-3"
              >
                <motion.button
                  whileHover={{ scale: 1.15 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => onRemove(item.id)}
                  className="w-10 h-10 rounded-full bg-white dark:bg-slate-600 shadow-md flex items-center justify-center text-orange-600 dark:text-orange-400 hover:bg-orange-100 dark:hover:bg-slate-500 transition-colors"
                >
                  <Minus className="w-5 h-5" />
                </motion.button>
                <span className="font-bold text-xl text-slate-900 dark:text-white min-w-[32px] text-center">
                  {quantity}
                </span>
                <motion.button
                  whileHover={{ scale: 1.15 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => onAdd(item)}
                  disabled={!item.isAvailable}
                  className="w-10 h-10 rounded-full bg-gradient-to-r from-orange-500 to-red-500 shadow-md shadow-orange-500/30 flex items-center justify-center text-white disabled:opacity-50"
                >
                  <Plus className="w-5 h-5" />
                </motion.button>
              </motion.div>
            ) : (
              <motion.button
                whileHover={{ scale: 1.02, y: -2 }}
                whileTap={{ scale: 0.98 }}
                onClick={() => onAdd(item)}
                disabled={!item.isAvailable}
                className="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-orange-500 via-red-500 to-amber-500 text-white font-semibold transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed shadow-md hover:shadow-lg hover:shadow-orange-500/30 flex items-center justify-center gap-2 group/btn"
              >
                <Plus className="w-5 h-5 group-hover/btn:rotate-90 transition-transform duration-300" />
                {item.isAvailable ? t('addToCart') : t('unavailable')}
              </motion.button>
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

'use client';

import { ModifierSelectionModal } from '@/components/restaurant/ModifierSelectionModal';
import { CustomizationSelector } from '@/components/customization/CustomizationSelector';
import type { MenuItem } from './types';

interface SelectedModifier {
  optionId: string;
  optionName: string;
  groupId: string;
  groupName: string;
  modifierType: 'add' | 'remove' | 'swap';
  priceAdjustment: number;
  quantity: number;
}

export interface RestaurantModalsProps {
  selectedItemForModifiers: MenuItem | null;
  setSelectedItemForModifiers: (item: MenuItem | null) => void;
  selectedItemForCustomization: MenuItem | null;
  setSelectedItemForCustomization: (item: MenuItem | null) => void;
  handleCustomizationConfirm: (data: {
    selections: any[];
    totalPriceAdjustment: number;
    lineTotal: number;
    quantity: number;
  }) => void;
  addToCart: (item: {
    id: string;
    name: string;
    price: number;
    category?: string;
    imageUrl?: string;
    selectedModifiers?: SelectedModifier[];
    modifierTotal?: number;
    specialInstructions?: string;
  }) => void;
  translateContent: (item: any, field: string) => string;
}

export function RestaurantModals({
  selectedItemForModifiers,
  setSelectedItemForModifiers,
  selectedItemForCustomization,
  setSelectedItemForCustomization,
  handleCustomizationConfirm,
  addToCart,
  translateContent,
}: RestaurantModalsProps) {
  return (
    <>
      {/* Modifier Selection Modal (Legacy) */}
      {selectedItemForModifiers && (
        <ModifierSelectionModal
          isOpen={!!selectedItemForModifiers}
          onClose={() => setSelectedItemForModifiers(null)}
          menuItem={{
            id: selectedItemForModifiers.id,
            name: selectedItemForModifiers.name,
            name_ar: selectedItemForModifiers.name_ar,
            description: selectedItemForModifiers.description,
            description_ar: selectedItemForModifiers.description_ar,
            price: Number(selectedItemForModifiers.discountPrice || selectedItemForModifiers.price),
            image_url: selectedItemForModifiers.imageUrl,
            category: selectedItemForModifiers.category,
          }}
          onAddToCart={addToCart}
        />
      )}

      {/* Unified Customization Selector (New System) */}
      {selectedItemForCustomization && (
        <CustomizationSelector
          entityType="menu_item"
          entityId={selectedItemForCustomization.id}
          entity={{
            name: selectedItemForCustomization.name,
            nameAr: selectedItemForCustomization.name_ar,
            description: selectedItemForCustomization.description,
            descriptionAr: selectedItemForCustomization.description_ar,
            basePrice: Number(
              selectedItemForCustomization.discountPrice || selectedItemForCustomization.price
            ),
            imageUrl: selectedItemForCustomization.imageUrl,
          }}
          isOpen={!!selectedItemForCustomization}
          onClose={() => setSelectedItemForCustomization(null)}
          onConfirm={handleCustomizationConfirm}
          title={translateContent(selectedItemForCustomization, 'name')}
        />
      )}
    </>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { useCartStore } from '@/stores/cartStore';
import { MenuItem } from './types';
import { type SelectedModifier } from '@/components/restaurant/ModifierSelectionModal';

export function useMenuActions(
  translateContent: (item: any, field: string) => string,
  t: (key: string, params?: Record<string, any>) => string,
) {
  const addToRestaurant = useCartStore((s) => s.addToRestaurant);
  const removeFromRestaurant = useCartStore((s) => s.removeFromRestaurant);
  const restaurantItems = useCartStore((s) => s.items.filter(i => i.moduleId === 'restaurant'));
  const getRestaurantTotal = useCartStore((s) => s.getRestaurantTotal);
  const getRestaurantCount = useCartStore((s) => s.getRestaurantCount);

  const [selectedItemForModifiers, setSelectedItemForModifiers] = useState<MenuItem | null>(null);
  const [selectedItemForCustomization, setSelectedItemForCustomization] = useState<MenuItem | null>(null);
  const [checkingCustomizations, setCheckingCustomizations] = useState(false);

  const cartTotal = getRestaurantTotal();
  const cartCount = getRestaurantCount();

  const handleItemClick = useCallback(async (item: MenuItem) => {
    setCheckingCustomizations(true);
    try {
      const response = await api.get(`/customizations/for-entity/menu_item/${item.id}`);
      const customizationGroups = response.data || [];
      if (customizationGroups.length > 0) {
        setSelectedItemForCustomization(item);
      } else {
        setSelectedItemForModifiers(item);
      }
    } catch (error) {
      console.error('Failed to check for customizations, falling back to legacy:', error);
      setSelectedItemForModifiers(item);
    } finally {
      setCheckingCustomizations(false);
    }
  }, []);

  const handleCustomizationConfirm = useCallback((data: {
    selections: any[];
    totalPriceAdjustment: number;
    lineTotal: number;
    quantity: number;
  }) => {
    if (!selectedItemForCustomization) return;
    
    const translatedName = translateContent(selectedItemForCustomization, 'name');
    const basePrice = Number(selectedItemForCustomization.discountPrice || selectedItemForCustomization.price);
    
    const mapCustomizationType = (type: string): 'add' | 'remove' | 'swap' => {
      switch (type) {
        case 'remove': return 'remove';
        case 'swap':
        case 'replace':
        case 'upgrade': return 'swap';
        default: return 'add';
      }
    };
    
    const customizationDetails = data.selections.map(s => ({
      optionId: s.optionId,
      optionName: s.optionName,
      groupId: s.groupId,
      groupName: s.groupName,
      modifierType: mapCustomizationType(s.customizationType),
      priceAdjustment: s.priceAdjustment || s.totalPrice || 0,
      quantity: s.quantity,
    }));
    
    for (let i = 0; i < data.quantity; i++) {
      addToRestaurant({
        id: selectedItemForCustomization.id,
        name: translatedName,
        price: basePrice,
        category: translateContent(selectedItemForCustomization.category, 'name'),
        imageUrl: selectedItemForCustomization.imageUrl,
        selectedModifiers: customizationDetails,
        modifierTotal: data.totalPriceAdjustment,
      });
    }
    
    toast.success(t('addedToCart', { item: translatedName }));
    setSelectedItemForCustomization(null);
  }, [selectedItemForCustomization, translateContent, addToRestaurant, t]);

  const addToCart = useCallback((item: {
    id: string;
    name: string;
    price: number;
    category?: string;
    imageUrl?: string;
    selectedModifiers?: SelectedModifier[];
    modifierTotal?: number;
    specialInstructions?: string;
  }) => {
    addToRestaurant({
      id: item.id,
      name: item.name,
      price: item.price,
      category: item.category,
      imageUrl: item.imageUrl,
      selectedModifiers: item.selectedModifiers,
      modifierTotal: item.modifierTotal,
      specialInstructions: item.specialInstructions,
    });
    toast.success(t('addedToCart', { item: item.name }));
  }, [addToRestaurant, t]);

  const quickAddToCart = useCallback((item: MenuItem) => {
    const translatedName = translateContent(item, 'name');
    addToRestaurant({
      id: item.id,
      name: translatedName,
      price: Number(item.discountPrice || item.price),
      category: translateContent(item.category, 'name'),
      imageUrl: item.imageUrl,
    });
    toast.success(t('addedToCart', { item: translatedName }));
  }, [addToRestaurant, translateContent, t]);

  const getItemQuantity = useCallback((itemId: string) => {
    return restaurantItems
      .filter((i) => i.id === itemId)
      .reduce((sum, i) => sum + i.quantity, 0);
  }, [restaurantItems]);

  return {
    cartTotal,
    cartCount,
    restaurantItems,
    removeFromRestaurant,
    selectedItemForModifiers,
    setSelectedItemForModifiers,
    selectedItemForCustomization,
    setSelectedItemForCustomization,
    checkingCustomizations,
    handleItemClick,
    handleCustomizationConfirm,
    addToCart,
    quickAddToCart,
    getItemQuantity,
  };
}

'use client';

import { useEffect, useState, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { restaurantApi } from '@/lib/api';
import { formatCurrency } from '@/lib/utils';
import { useSettingsStore } from '@/stores/settingsStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  CheckCircle2,
  Clock,
  Phone,
  MapPin,
  ArrowRight,
  Loader2,
  AlertCircle,
  UtensilsCrossed,
  Hash,
  User,
  Tag,
} from 'lucide-react';
import { QRCode } from '@/components/ui/QRCode';

interface RestaurantOrder {
  id: string;
  order_number: string;
  customer_name: string;
  customer_phone: string;
  table_number?: string;
  order_type: 'dine_in' | 'takeaway';
  subtotal: number;
  tax_amount: number;
  service_charge?: number;
  delivery_fee?: number;
  total_amount: number;
  discount_amount?: number;
  coupon_discount?: number;
  coupon_code?: string;
  status: string;
  payment_method: string;
  payment_status: string;
  special_requests?: string;
  created_at: string;
  items?: {
    menu_item: {
      name: string;
    };
    quantity: number;
    unit_price: number;
    total_price: number;
    special_instructions?: string;
  }[];
}

function RestaurantConfirmationContent() {
  const searchParams = useSearchParams();
  const t = useTranslations('restaurant');
  const tCommon = useTranslations('common');
  const currency = useSettingsStore((s) => s.currency);
  const [order, setOrder] = useState<RestaurantOrder | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const orderId = searchParams.get('id');

  useEffect(() => {
    if (orderId) {
      fetchOrder();
    } else {
      setError('No order ID provided');
      setLoading(false);
    }
  }, [orderId]);

  const fetchOrder = async () => {
    try {
      const response = await restaurantApi.getOrderStatus(orderId!);
      setOrder(response.data.data);
    } catch (err) {
      setError('Failed to load order details');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-orange-50 via-amber-50 to-red-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900">
        <Loader2 className="w-8 h-8 animate-spin text-orange-600" />
      </div>
    );
  }

  if (error || !order) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-orange-50 via-amber-50 to-red-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900">
        <Card className="max-w-md mx-auto">
          <CardContent className="text-center py-8">
            <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">{error || 'Order not found'}</h2>
            <Link href="/restaurant">
              <Button className="mt-4">{t('backToMenu')}</Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    );
  }

  const statusColors: Record<string, string> = {
    pending: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400',
    confirmed: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
    preparing: 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400',
    ready: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
    served: 'bg-slate-100 text-slate-700 dark:bg-slate-700 dark:text-slate-300',
    completed: 'bg-slate-100 text-slate-700 dark:bg-slate-700 dark:text-slate-300',
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 via-amber-50 to-red-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900 py-12">
      <div className="max-w-2xl mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: 'spring' }}
            className="w-20 h-20 bg-orange-100 dark:bg-orange-900/30 rounded-full flex items-center justify-center mx-auto mb-4"
          >
            <CheckCircle2 className="w-10 h-10 text-orange-600 dark:text-orange-400" />
          </motion.div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white mb-2">
            {t('orderConfirmed')}
          </h1>
          <p className="text-slate-600 dark:text-slate-400">
            {t('orderConfirmationMessage')}
          </p>
        </motion.div>

        <Card className="overflow-hidden">
          <CardHeader className="bg-gradient-to-r from-orange-500 to-red-500 text-white border-b-0">
            <CardTitle className="flex items-center justify-between">
              <span className="flex items-center gap-2">
                <UtensilsCrossed className="w-5 h-5" />
                {t('orderDetails')}
              </span>
              <span className="text-sm font-mono bg-white/20 px-3 py-1 rounded-full">
                #{order.order_number}
              </span>
            </CardTitle>
          </CardHeader>
          <CardContent className="divide-y divide-slate-200 dark:divide-slate-700">
            {/* QR Code */}
            <div className="py-6 flex flex-col items-center justify-center bg-slate-50 dark:bg-slate-800/50">
              <QRCode value={order.id} size={160} />
              <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">
                {t('qrCode') || 'Show this QR code to staff'}
              </p>
            </div>

            {/* Status */}
            <div className="py-4 flex items-center justify-between">
              <span className="text-slate-600 dark:text-slate-400">{tCommon('status')}</span>
              <span className={`px-3 py-1 rounded-full text-sm font-medium ${statusColors[order.status] || statusColors.pending}`}>
                {order.status.toUpperCase()}
              </span>
            </div>

            {/* Order Type & Table */}
            <div className="py-4 flex items-center gap-4">
              <div className="w-12 h-12 bg-orange-100 dark:bg-orange-900/30 rounded-lg flex items-center justify-center">
                <MapPin className="w-6 h-6 text-orange-600" />
              </div>
              <div>
                <p className="text-sm text-slate-500">{t('orderType')}</p>
                <p className="font-semibold">
                  {order.order_type === 'dine_in' ? t('dineIn') : t('takeaway')}
                  {order.table_number && ` - ${t('table')} ${order.table_number}`}
                </p>
              </div>
            </div>

            {/* Estimated Time */}
            <div className="py-4 flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-100 dark:bg-blue-900/30 rounded-lg flex items-center justify-center">
                <Clock className="w-6 h-6 text-blue-600" />
              </div>
              <div>
                <p className="text-sm text-slate-500">{t('estimatedTime')}</p>
                <p className="font-semibold">20-30 {t('minutes')}</p>
              </div>
            </div>

            {/* Customer Info */}
            <div className="py-4 space-y-2">
              <div className="flex items-center gap-2">
                <User className="w-4 h-4 text-slate-400" />
                <span className="font-medium">{order.customer_name}</span>
              </div>
              <div className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
                <Phone className="w-4 h-4" />
                <span>{order.customer_phone}</span>
              </div>
            </div>

            {/* Order Items */}
            <div className="py-4">
              <p className="text-sm text-slate-500 mb-3">{t('orderItems')}</p>
              <div className="space-y-3">
                {order.items?.map((item, index) => (
                  <div key={index} className="flex justify-between items-start">
                    <div className="flex items-start gap-2">
                      <span className="w-6 h-6 bg-orange-100 dark:bg-orange-900/30 rounded-full flex items-center justify-center text-xs font-medium flex-shrink-0 mt-0.5">
                        {item.quantity}
                      </span>
                      <div>
                        <span className="font-medium">{item.menu_item?.name}</span>
                        {item.special_instructions && (
                          <p className="text-xs text-slate-500 mt-0.5">{item.special_instructions}</p>
                        )}
                      </div>
                    </div>
                    <span className="font-medium">{formatCurrency(item.total_price, currency)}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Totals */}
            <div className="py-4 space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-slate-600 dark:text-slate-400">{t('subtotal')}</span>
                <span>{formatCurrency(order.subtotal, currency)}</span>
              </div>
              
              <div className="flex justify-between text-sm">
                <span className="text-slate-600 dark:text-slate-400">{t('tax')}</span>
                <span>{formatCurrency(order.tax_amount, currency)}</span>
              </div>

              {/* Service Charge Display */}
              {(order.service_charge ?? 0) > 0 && (
                <div className="flex justify-between text-sm">
                  <span className="text-slate-600 dark:text-slate-400">Service Charge (10%)</span>
                  <span>{formatCurrency(order.service_charge ?? 0, currency)}</span>
                </div>
              )}

              {/* Delivery Fee Display */}
              {(order.delivery_fee ?? 0) > 0 && (
                <div className="flex justify-between text-sm">
                  <span className="text-slate-600 dark:text-slate-400">Delivery Fee</span>
                  <span>{formatCurrency(order.delivery_fee ?? 0, currency)}</span>
                </div>
              )}
              
              {/* Discount Display */}
              {((order.discount_amount ?? 0) > 0 || (order.coupon_discount ?? 0) > 0) && (
                <div className="flex justify-between text-sm text-green-600 dark:text-green-400">
                  <span className="flex items-center gap-1">
                    <Tag className="w-3 h-3" />
                    {tCommon('discount')}
                    {order.coupon_code && <span className="text-xs ml-1 bg-green-100 dark:bg-green-900 px-1 rounded">({order.coupon_code})</span>}
                  </span>
                  <span>-{formatCurrency((order.discount_amount ?? 0) || (order.coupon_discount ?? 0), currency)}</span>
                </div>
              )}

              <div className="flex justify-between items-center pt-2 border-t dark:border-slate-700">
                <span className="font-semibold">{tCommon('total')}</span>
                <span className="text-2xl font-bold text-orange-600">
                  {formatCurrency(order.total_amount, currency)}
                </span>
              </div>
              <div className="mt-2">
                <span className={`text-xs px-2 py-1 rounded-full ${
                  order.payment_status === 'paid'
                    ? 'bg-green-100 text-green-700'
                    : 'bg-amber-100 text-amber-700'
                }`}>
                  {order.payment_status === 'paid' ? 'PAID' : `PAY ON ${order.order_type === 'dine_in' ? 'TABLE' : 'PICKUP'} (${order.payment_method?.toUpperCase() || 'CASH'})`}
                </span>
              </div>
            </div>

            {/* Special Requests */}
            {order.special_requests && (
              <div className="py-4">
                <p className="text-sm text-slate-500 mb-1">{t('specialRequests')}</p>
                <p className="text-sm">{order.special_requests}</p>
              </div>
            )}
          </CardContent>
        </Card>

        <div className="mt-6 bg-orange-50 dark:bg-orange-900/20 border border-orange-200 dark:border-orange-800 rounded-lg p-4">
          <p className="text-sm text-orange-800 dark:text-orange-300">
            <strong>{t('tip')}:</strong> {order.order_type === 'dine_in' ? t('foodWillBeServed') : t('weWillCallWhenReady')}
          </p>
        </div>

        <div className="mt-6 flex flex-col sm:flex-row gap-4 justify-center">
          <Link href="/restaurant">
            <Button variant="outline">{t('orderMore')}</Button>
          </Link>
          <Link href="/profile">
            <Button className="gap-2">
              {t('viewMyOrders')}
              <ArrowRight className="w-4 h-4" />
            </Button>
          </Link>
        </div>
      </div>
    </div>
  );
}

export default function RestaurantConfirmationPage() {
