}

'use client';

import { useQuery } from '@tanstack/react-query';
import { restaurantApi } from '@/lib/api';
import { useState } from 'react';
import { useTranslations } from 'next-intl';
import { useSettingsStore } from '@/stores/settingsStore';
import { useSiteSettings } from '@/lib/settings-context';
import { useContentTranslation } from '@/lib/translate';
import { motion, AnimatePresence } from 'framer-motion';

import { normalizeMenuItem, containerVariants, type MenuItem } from './components/types';
import { RestaurantHero } from './components/RestaurantHero';
import { FeaturedDishes } from './components/FeaturedDishes';
import { CategoryFilters } from './components/CategoryFilters';
import { MenuItemCard } from './components/MenuItemCard';
import { FloatingCartBar } from './components/FloatingCartBar';
import { RestaurantLoading, RestaurantError, RestaurantEmptyState } from './components/RestaurantStates';
import { RestaurantModals } from './components/RestaurantModals';
import { useMenuActions } from './components/useMenuActions';

export default function RestaurantMenuPage() {
  const t = useTranslations('restaurant');
  const tCommon = useTranslations('common');
  const { settings, modules } = useSiteSettings();
  const restaurantModule = modules.find(m => m.slug === 'restaurant');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [showFeaturedOnly, setShowFeaturedOnly] = useState(false);
  const [dietaryFilters, setDietaryFilters] = useState<{
    vegetarian: boolean;
    vegan: boolean;
    glutenFree: boolean;
  }>({ vegetarian: false, vegan: false, glutenFree: false });
  const currency = useSettingsStore((s) => s.currency);
  const { translateContent, isRTL } = useContentTranslation();

  const {
    cartTotal, cartCount, removeFromRestaurant,
    selectedItemForModifiers, setSelectedItemForModifiers,
    selectedItemForCustomization, setSelectedItemForCustomization,
    handleItemClick, handleCustomizationConfirm, addToCart,
    getItemQuantity,
  } = useMenuActions(translateContent, t);

  // FIX Iter-2: Removed enabled guard — query fires immediately without moduleId,
  // then refetches when modules load (queryKey includes moduleId so React Query handles it)
  const { data, isLoading, error } = useQuery({
    queryKey: ['restaurant-menu', restaurantModule?.id],
    queryFn: () => restaurantApi.getMenu(restaurantModule?.id),
  });

  // Normalize menu items from API (snake_case → camelCase)
  const rawItems = data?.data?.data?.items || [];
  const menuItems: MenuItem[] = rawItems.map(normalizeMenuItem);
  const categories = data?.data?.data?.categories || [];

  // Filter items by category
  let filteredItems = selectedCategory
    ? menuItems.filter((item) => item.category.id === selectedCategory)
    : menuItems;

  // Apply dietary filters
  if (dietaryFilters.vegetarian) {
    filteredItems = filteredItems.filter((item) => item.isVegetarian);
  }
  if (dietaryFilters.vegan) {
    filteredItems = filteredItems.filter((item) => item.isVegan);
  }
  if (dietaryFilters.glutenFree) {
    filteredItems = filteredItems.filter((item) => item.isGlutenFree);
  }

  if (showFeaturedOnly) {
    filteredItems = filteredItems.filter((item) => item.isFeatured);
  }

  const featuredItems = menuItems.filter((item) => item.isFeatured).slice(0, 3);
  const hasDietaryItems = menuItems.some((item) => item.isVegetarian || item.isVegan || item.isGlutenFree);

  const toggleDietaryFilter = (filter: 'vegetarian' | 'vegan' | 'glutenFree') => {
    setDietaryFilters((prev) => ({ ...prev, [filter]: !prev[filter] }));
  };

  if (isLoading) return <RestaurantLoading t={t} />;

  if (error) return <RestaurantError tCommon={tCommon} />;

  return (
    <div className="min-h-screen bg-gradient-to-b from-white via-slate-50 to-white dark:from-slate-950 dark:via-slate-900 dark:to-slate-950">
      <RestaurantHero
        restaurantName={settings.restaurantName}
        menuItemCount={menuItems.length}
        categoryCount={categories.length}
        t={t}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 -mt-6 relative z-10">
        {/* Featured Dishes Section */}
        {featuredItems.length > 0 && !selectedCategory && (
          <FeaturedDishes
            items={featuredItems}
            currency={currency}
            showFeaturedOnly={showFeaturedOnly}
            onToggleFeatured={() => setShowFeaturedOnly(!showFeaturedOnly)}
            onItemClick={handleItemClick}
            translateContent={translateContent}
            t={t}
          />
        )}

        <CategoryFilters
          categories={categories}
          selectedCategory={selectedCategory}
          onSelectCategory={setSelectedCategory}
          dietaryFilters={dietaryFilters}
          onToggleDietary={toggleDietaryFilter}
          hasDietaryItems={hasDietaryItems}
          translateContent={translateContent}
          t={t}
          tCommon={tCommon}
        />

        {/* Menu Grid */}
        <AnimatePresence mode="wait">
          <motion.div
            key={selectedCategory || 'all'}
            variants={containerVariants}
            initial="hidden"
            animate="visible"
            exit={{ opacity: 0, y: -20 }}
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
          >
            {filteredItems.map((item) => (
              <MenuItemCard
                key={item.id}
                item={item}
                currency={currency}
                quantity={getItemQuantity(item.id)}
                onAdd={handleItemClick}
                onRemove={(id) => removeFromRestaurant(id)}
                translateContent={translateContent}
                t={t}
              />
            ))}
          </motion.div>
        </AnimatePresence>

        {filteredItems.length === 0 && <RestaurantEmptyState t={t} tCommon={tCommon} />}
      </main>

      <FloatingCartBar
        cartCount={cartCount}
        cartTotal={cartTotal}
        currency={currency}
        t={t}
      />

      <RestaurantModals
        selectedItemForModifiers={selectedItemForModifiers}
        setSelectedItemForModifiers={setSelectedItemForModifiers}
        selectedItemForCustomization={selectedItemForCustomization}
        setSelectedItemForCustomization={setSelectedItemForCustomization}
        handleCustomizationConfirm={handleCustomizationConfirm}
        addToCart={addToCart}
        translateContent={translateContent}
      />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { 
  Calendar, 
  Clock, 
  Users, 
  ChevronLeft, 
  ChevronRight,
  CheckCircle,
  AlertCircle,
  Loader2,
  Phone,
  Mail,
  User
} from 'lucide-react';
import { toast } from 'sonner';
import api from '@/lib/api';

interface TimeSlot {
  time: string;
  available: boolean;
}

interface ReservationForm {
  date: string;
  time: string;
  partySize: number;
  name: string;
  email: string;
  phone: string;
  specialRequests: string;
}

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

// Generate time slots from 11:00 to 22:00
const generateTimeSlots = (): TimeSlot[] => {
  const slots: TimeSlot[] = [];
  for (let hour = 11; hour <= 21; hour++) {
    for (let min of [0, 30]) {
      const time = `${hour.toString().padStart(2, '0')}:${min.toString().padStart(2, '0')}`;
      slots.push({ time, available: Math.random() > 0.3 }); // Demo: random availability
    }
  }
  return slots;
};

export default function RestaurantReservePage() {
  const [step, setStep] = useState<'select' | 'details' | 'confirm' | 'success'>('select');
  const [form, setForm] = useState<ReservationForm>({
    date: new Date().toISOString().split('T')[0],
    time: '',
    partySize: 2,
    name: '',
    email: '',
    phone: '',
    specialRequests: ''
  });
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>(generateTimeSlots());

  // Fetch available tables for selected date/time
  const { data: availableTables, isLoading: loadingTables, refetch } = useQuery({
    queryKey: ['available-tables', form.date, form.partySize],
    queryFn: async () => {
      try {
        const res = await api.get(`/restaurant/tables/available?date=${form.date}&partySize=${form.partySize}`);
        return res.data?.data || [];
      } catch {
        return [];
      }
    },
    enabled: !!form.date
  });

  // Submit reservation
  const submitMutation = useMutation({
    mutationFn: async (data: ReservationForm) => {
      const res = await api.post('/restaurant/reservations', {
        date: data.date,
        time: data.time,
        party_size: data.partySize,
        guest_name: data.name,
        guest_email: data.email,
        guest_phone: data.phone,
        special_requests: data.specialRequests
      });
      return res.data;
    },
    onSuccess: () => {
      setStep('success');
    },
    onError: () => {
      toast.error('Failed to create reservation. Please try again.');
    }
  });

  const handleDateChange = (days: number) => {
    const currentDate = new Date(form.date);
    currentDate.setDate(currentDate.getDate() + days);
    const newDate = currentDate.toISOString().split('T')[0];
    setForm({ ...form, date: newDate, time: '' });
    setTimeSlots(generateTimeSlots()); // Regenerate slots for new date
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return date.toLocaleDateString('en-US', { 
      weekday: 'long', 
      month: 'long', 
      day: 'numeric' 
    });
  };

  const canProceedToDetails = form.date && form.time && form.partySize > 0;
  const canSubmit = form.name && form.email && form.phone;

  // Select Date/Time Step
  if (step === 'select') {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-900">
        {/* Header */}
        <div className="bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700">
          <div className="max-w-4xl mx-auto px-4 py-8">
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">
              Reserve a Table
            </h1>
            <p className="text-slate-600 dark:text-slate-400 mt-2">
              Book your dining experience at Iron Paradise Gym Restaurant
            </p>
          </div>
        </div>

        <div className="max-w-4xl mx-auto px-4 py-8">
          {/* Party Size */}
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 mb-6 border border-slate-200 dark:border-slate-700">
            <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-4">
              <Users className="w-4 h-4" />
              Party Size
            </label>
            <div className="flex gap-2 flex-wrap">
              {[1, 2, 3, 4, 5, 6, 7, 8].map((size) => (
                <button
                  key={size}
                  onClick={() => setForm({ ...form, partySize: size })}
                  className={`px-5 py-3 rounded-lg font-medium transition-colors ${
                    form.partySize === size
                      ? 'bg-primary text-white'
                      : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                  }`}
                >
                  {size} {size === 1 ? 'Guest' : 'Guests'}
                </button>
              ))}
              <button
                onClick={() => setForm({ ...form, partySize: 10 })}
                className={`px-5 py-3 rounded-lg font-medium transition-colors ${
                  form.partySize > 8
                    ? 'bg-primary text-white'
                    : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                }`}
              >
                9+ (Large Party)
              </button>
            </div>
          </div>

          {/* Date Selection */}
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 mb-6 border border-slate-200 dark:border-slate-700">
            <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-4">
              <Calendar className="w-4 h-4" />
              Select Date
            </label>
            <div className="flex items-center justify-between">
              <button
                onClick={() => handleDateChange(-1)}
                disabled={form.date <= new Date().toISOString().split('T')[0]}
                className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <div className="text-center">
                <p className="text-xl font-semibold text-slate-900 dark:text-white">
                  {formatDate(form.date)}
                </p>
                <input
                  type="date"
                  value={form.date}
                  min={new Date().toISOString().split('T')[0]}
                  onChange={(e) => setForm({ ...form, date: e.target.value, time: '' })}
                  className="mt-2 px-3 py-1 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white text-sm"
                />
              </div>
              <button
                onClick={() => handleDateChange(1)}
                className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* Time Selection */}
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 mb-6 border border-slate-200 dark:border-slate-700">
            <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-4">
              <Clock className="w-4 h-4" />
              Select Time
            </label>
            
            {loadingTables ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-primary" />
              </div>
            ) : (
              <div className="grid grid-cols-4 md:grid-cols-6 gap-2">
                {timeSlots.map((slot) => (
                  <button
                    key={slot.time}
                    onClick={() => slot.available && setForm({ ...form, time: slot.time })}
                    disabled={!slot.available}
                    className={`py-3 px-2 rounded-lg text-sm font-medium transition-colors ${
                      form.time === slot.time
                        ? 'bg-primary text-white'
                        : slot.available
                          ? 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                          : 'bg-slate-50 dark:bg-slate-800 text-slate-400 dark:text-slate-500 cursor-not-allowed line-through'
                    }`}
                  >
                    {slot.time}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Continue Button */}
          <button
            onClick={() => setStep('details')}
            disabled={!canProceedToDetails}
            className="w-full py-4 bg-primary text-white font-semibold rounded-xl hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            Continue
          </button>
        </div>
      </div>
    );
  }

  // Guest Details Step
  if (step === 'details') {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-900">
        <div className="bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700">
          <div className="max-w-4xl mx-auto px-4 py-8">
            <button
              onClick={() => setStep('select')}
              className="flex items-center gap-2 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white mb-4"
            >
              <ChevronLeft className="w-4 h-4" />
              Back
            </button>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">
              Your Details
            </h1>
            <p className="text-slate-600 dark:text-slate-400 mt-2">
              {formatDate(form.date)} at {form.time} for {form.partySize} {form.partySize === 1 ? 'guest' : 'guests'}
            </p>
          </div>
        </div>

        <div className="max-w-4xl mx-auto px-4 py-8">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700 space-y-6">
            <div>
              <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                <User className="w-4 h-4" />
                Full Name *
              </label>
              <input
                type="text"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                placeholder="John Smith"
                className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                <Mail className="w-4 h-4" />
                Email Address *
              </label>
              <input
                type="email"
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                placeholder="john@example.com"
                className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                <Phone className="w-4 h-4" />
                Phone Number *
              </label>
              <input
                type="tel"
                value={form.phone}
                onChange={(e) => setForm({ ...form, phone: e.target.value })}
                placeholder="+1 (555) 000-0000"
                className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-2 block">
                Special Requests (optional)
              </label>
              <textarea
                value={form.specialRequests}
                onChange={(e) => setForm({ ...form, specialRequests: e.target.value })}
                placeholder="Allergies, dietary requirements, special occasions..."
                rows={3}
                className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white resize-none"
              />
            </div>
          </div>

          <div className="mt-6 flex gap-4">
            <button
              onClick={() => setStep('select')}
              className="flex-1 py-4 border border-slate-300 dark:border-slate-600 text-slate-700 dark:text-slate-300 font-semibold rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors"
            >
              Back
            </button>
            <button
              onClick={() => setStep('confirm')}
              disabled={!canSubmit}
              className="flex-1 py-4 bg-primary text-white font-semibold rounded-xl hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              Review Reservation
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Confirmation Step
  if (step === 'confirm') {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-900">
        <div className="bg-white dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700">
          <div className="max-w-4xl mx-auto px-4 py-8">
            <button
              onClick={() => setStep('details')}
              className="flex items-center gap-2 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white mb-4"
            >
              <ChevronLeft className="w-4 h-4" />
              Back
            </button>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">
              Confirm Reservation
            </h1>
          </div>
        </div>

        <div className="max-w-4xl mx-auto px-4 py-8">
          <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
            <div className="grid grid-cols-2 gap-6">
              <div>
                <p className="text-sm text-slate-500 dark:text-slate-400">Date</p>
                <p className="text-lg font-medium text-slate-900 dark:text-white">{formatDate(form.date)}</p>
              </div>
              <div>
                <p className="text-sm text-slate-500 dark:text-slate-400">Time</p>
                <p className="text-lg font-medium text-slate-900 dark:text-white">{form.time}</p>
              </div>
              <div>
                <p className="text-sm text-slate-500 dark:text-slate-400">Party Size</p>
                <p className="text-lg font-medium text-slate-900 dark:text-white">{form.partySize} guests</p>
              </div>
              <div>
                <p className="text-sm text-slate-500 dark:text-slate-400">Name</p>
                <p className="text-lg font-medium text-slate-900 dark:text-white">{form.name}</p>
              </div>
              <div>
                <p className="text-sm text-slate-500 dark:text-slate-400">Email</p>
                <p className="text-lg font-medium text-slate-900 dark:text-white">{form.email}</p>
              </div>
              <div>
                <p className="text-sm text-slate-500 dark:text-slate-400">Phone</p>
                <p className="text-lg font-medium text-slate-900 dark:text-white">{form.phone}</p>
              </div>
              {form.specialRequests && (
                <div className="col-span-2">
                  <p className="text-sm text-slate-500 dark:text-slate-400">Special Requests</p>
                  <p className="text-slate-900 dark:text-white">{form.specialRequests}</p>
                </div>
              )}
            </div>
          </div>

          <div className="mt-6 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-xl p-4">
            <div className="flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-amber-600 dark:text-amber-400 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-amber-800 dark:text-amber-200">Cancellation Policy</p>
                <p className="text-sm text-amber-700 dark:text-amber-300 mt-1">
                  Please cancel at least 2 hours before your reservation time to avoid a no-show fee.
                </p>
              </div>
            </div>
          </div>

          <div className="mt-6 flex gap-4">
            <button
              onClick={() => setStep('details')}
              className="flex-1 py-4 border border-slate-300 dark:border-slate-600 text-slate-700 dark:text-slate-300 font-semibold rounded-xl hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors"
            >
              Back
            </button>
            <button
              onClick={() => submitMutation.mutate(form)}
              disabled={submitMutation.isPending}
              className="flex-1 py-4 bg-green-600 text-white font-semibold rounded-xl hover:bg-green-500 disabled:opacity-50 transition-colors flex items-center justify-center gap-2"
            >
              {submitMutation.isPending ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Booking...
                </>
              ) : (
                'Confirm Reservation'
              )}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Success Step
  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white dark:bg-slate-800 rounded-2xl p-8 text-center border border-slate-200 dark:border-slate-700">
        <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
          <CheckCircle className="w-10 h-10 text-green-600 dark:text-green-400" />
        </div>
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
          Reservation Confirmed!
        </h1>
        <p className="text-slate-600 dark:text-slate-400 mb-6">
          We've sent a confirmation email to {form.email}
        </p>

        <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-4 mb-6 text-left">
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div>
              <p className="text-slate-500 dark:text-slate-400">Date</p>
              <p className="font-medium text-slate-900 dark:text-white">{formatDate(form.date)}</p>
            </div>
            <div>
              <p className="text-slate-500 dark:text-slate-400">Time</p>
              <p className="font-medium text-slate-900 dark:text-white">{form.time}</p>
            </div>
            <div>
              <p className="text-slate-500 dark:text-slate-400">Party</p>
              <p className="font-medium text-slate-900 dark:text-white">{form.partySize} guests</p>
            </div>
            <div>
              <p className="text-slate-500 dark:text-slate-400">Name</p>
              <p className="font-medium text-slate-900 dark:text-white">{form.name}</p>
            </div>
          </div>
        </div>

        <a
          href="/restaurant"
          className="block w-full py-3 bg-primary text-white font-semibold rounded-xl hover:bg-primary/90 transition-colors"
        >
          Back to Restaurant
        </a>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, Suspense } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { 
  Users, 
  Clock, 
  CheckCircle, 
  Loader2, 
  Phone, 
  User,
  AlertCircle
} from 'lucide-react';
import { useSearchParams } from 'next/navigation';
import { toast } from 'sonner';
import api from '@/lib/api';
import { useWaitlistUpdates } from '@/lib/socket';

interface WaitlistEntry {
  id: string;
  guest_name: string;
  party_size: number;
  phone: string;
  status: 'waiting' | 'notified' | 'seated' | 'cancelled' | 'no_show';
  position: number;
  estimated_wait: number;
  created_at: string;
}

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

function WaitlistContent() {
  const searchParams = useSearchParams();
  const entryId = searchParams.get('id');
  
  const [view, setView] = useState<'join' | 'status'>(entryId ? 'status' : 'join');
  const [form, setForm] = useState({
    name: '',
    phone: '',
    partySize: 2
  });
  const [submittedEntry, setSubmittedEntry] = useState<WaitlistEntry | null>(null);

  // Fetch entry status if ID provided
  const { data: entryStatus, refetch: refetchStatus } = useQuery({
    queryKey: ['waitlist-status', entryId || submittedEntry?.id],
    queryFn: async () => {
      const id = entryId || submittedEntry?.id;
      if (!id) return null;
      const res = await api.get(`/restaurant/waitlist/${id}`);
      return res.data;
    },
    enabled: !!(entryId || submittedEntry?.id),
  });

  // Real-time waitlist updates via Socket.IO
  const handleWaitlistUpdate = useCallback((data: any) => {
    const currentId = entryId || submittedEntry?.id;
    if (currentId && (data.entry?.id === currentId || data.entryId === currentId)) {
      refetchStatus();
    }
  }, [entryId, submittedEntry?.id, refetchStatus]);
  useWaitlistUpdates(handleWaitlistUpdate);

  // Join waitlist mutation
  const joinMutation = useMutation({
    mutationFn: async (data: { name: string; phone: string; partySize: number }) => {
      const res = await api.post('/restaurant/waitlist', {
        guest_name: data.name,
        phone: data.phone,
        party_size: data.partySize
      });
      return res.data;
    },
    onSuccess: (data) => {
      setSubmittedEntry(data.data);
      setView('status');
      toast.success('Added to waitlist!');
    },
    onError: () => {
      toast.error('Failed to join waitlist. Please try again.');
    }
  });

  // Leave waitlist mutation (public - no auth needed)
  const leaveMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await api.delete(`/restaurant/waitlist/${id}/leave`);
      return res.data;
    },
    onSuccess: () => {
      setSubmittedEntry(null);
      setView('join');
      toast.success('Removed from waitlist');
    }
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (form.name && form.phone && form.partySize > 0) {
      joinMutation.mutate(form);
    }
  };

  const currentEntry = entryStatus?.data || submittedEntry;
  const isNotified = currentEntry?.status === 'notified';
  const isSeated = currentEntry?.status === 'seated';
  const isCancelled = currentEntry?.status === 'cancelled' || currentEntry?.status === 'no_show';

  // Join Form View
  if (view === 'join') {
    return (
      <div className="min-h-screen bg-gradient-to-b from-primary/10 to-slate-50 dark:from-primary/5 dark:to-slate-900 flex items-center justify-center p-4">
        <div className="max-w-md w-full">
          <div className="text-center mb-8">
            <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-primary/10 flex items-center justify-center">
              <Users className="w-8 h-8 text-primary" />
            </div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Join the Waitlist</h1>
            <p className="text-slate-600 dark:text-slate-400 mt-2">
              No reservation? No problem! Join our waitlist.
            </p>
          </div>

          <form onSubmit={handleSubmit} className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-xl border border-slate-200 dark:border-slate-700 space-y-5">
            <div>
              <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                <User className="w-4 h-4" />
                Your Name
              </label>
              <input
                type="text"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                placeholder="John Smith"
                required
                className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-xl bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                <Phone className="w-4 h-4" />
                Phone Number
              </label>
              <input
                type="tel"
                value={form.phone}
                onChange={(e) => setForm({ ...form, phone: e.target.value })}
                placeholder="+1 (555) 000-0000"
                required
                className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-xl bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent"
              />
              <p className="text-xs text-slate-500 mt-1">We'll text you when your table is ready</p>
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                <Users className="w-4 h-4" />
                Party Size
              </label>
              <div className="flex gap-2 flex-wrap">
                {[1, 2, 3, 4, 5, 6, 7, 8].map((size) => (
                  <button
                    key={size}
                    type="button"
                    onClick={() => setForm({ ...form, partySize: size })}
                    className={`w-12 h-12 rounded-xl font-semibold transition-colors ${
                      form.partySize === size
                        ? 'bg-primary text-white'
                        : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                    }`}
                  >
                    {size}
                  </button>
                ))}
              </div>
            </div>

            <button
              type="submit"
              disabled={joinMutation.isPending || !form.name || !form.phone}
              className="w-full py-4 bg-primary text-white font-semibold rounded-xl hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2"
            >
              {joinMutation.isPending ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Joining...
                </>
              ) : (
                <>
                  <Users className="w-5 h-5" />
                  Join Waitlist
                </>
              )}
            </button>
          </form>

          <p className="text-center text-sm text-slate-500 mt-4">
            Already on the list?{' '}
            <button 
              onClick={() => {
                const id = prompt('Enter your waitlist ID:');
                if (id) window.location.href = `?id=${id}`;
              }}
              className="text-primary hover:underline"
            >
              Check your status
            </button>
          </p>
        </div>
      </div>
    );
  }

  // Status View
  return (
    <div className="min-h-screen bg-gradient-to-b from-primary/10 to-slate-50 dark:from-primary/5 dark:to-slate-900 flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        {/* Notified Alert */}
        {isNotified && (
          <div className="mb-6 bg-green-100 dark:bg-green-900/30 border-2 border-green-500 rounded-2xl p-6 text-center animate-pulse">
            <CheckCircle className="w-12 h-12 mx-auto text-green-600 dark:text-green-400 mb-3" />
            <h2 className="text-xl font-bold text-green-800 dark:text-green-200">Your Table is Ready!</h2>
            <p className="text-green-700 dark:text-green-300 mt-1">
              Please proceed to the host stand
            </p>
          </div>
        )}

        <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-xl border border-slate-200 dark:border-slate-700">
          {isCancelled ? (
            <div className="text-center py-8">
              <AlertCircle className="w-16 h-16 mx-auto text-slate-400 mb-4" />
              <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2">
                No Longer on Waitlist
              </h2>
              <p className="text-slate-600 dark:text-slate-400 mb-6">
                Your waitlist entry has been removed.
              </p>
              <button
                onClick={() => setView('join')}
                className="px-6 py-3 bg-primary text-white rounded-xl hover:bg-primary/90"
              >
                Join Again
              </button>
            </div>
          ) : isSeated ? (
            <div className="text-center py-8">
              <CheckCircle className="w-16 h-16 mx-auto text-green-500 mb-4" />
              <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2">
                You've Been Seated!
              </h2>
              <p className="text-slate-600 dark:text-slate-400">
                Enjoy your meal!
              </p>
            </div>
          ) : (
            <>
              <div className="text-center mb-6">
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                  {currentEntry?.guest_name || 'Guest'}
                </h2>
                <p className="text-slate-600 dark:text-slate-400">
                  Party of {currentEntry?.party_size || form.partySize}
                </p>
              </div>

              {/* Position Display */}
              <div className="bg-primary/5 rounded-2xl p-8 text-center mb-6">
                <p className="text-sm uppercase tracking-wide text-primary font-semibold mb-2">
                  Your Position
                </p>
                <div className="text-6xl font-bold text-primary mb-2">
                  #{currentEntry?.position || '?'}
                </div>
                <p className="text-slate-600 dark:text-slate-400">
                  in line
                </p>
              </div>

              {/* Estimated Wait */}
              <div className="flex items-center justify-center gap-2 text-slate-600 dark:text-slate-400 mb-6">
                <Clock className="w-5 h-5" />
                <span>
                  Estimated wait: <strong className="text-slate-900 dark:text-white">
                    {currentEntry?.estimated_wait || 15}-{(currentEntry?.estimated_wait || 15) + 10} minutes
                  </strong>
                </span>
              </div>

              {/* Info Box */}
              <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl p-4 mb-6">
                <p className="text-sm text-blue-800 dark:text-blue-200">
                  <strong>Tip:</strong> We'll send you a text when your table is ready. 
                  Feel free to explore the resort - just stay within 5 minutes of the restaurant.
                </p>
              </div>

              {/* Leave Button */}
              <button
                onClick={() => {
                  if (confirm('Are you sure you want to leave the waitlist?')) {
                    leaveMutation.mutate(currentEntry?.id);
                  }
                }}
                disabled={leaveMutation.isPending}
                className="w-full py-3 border border-red-300 dark:border-red-800 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
              >
                {leaveMutation.isPending ? 'Leaving...' : 'Leave Waitlist'}
              </button>
            </>
          )}
        </div>

        {/* Auto-refresh notice */}
        {!isCancelled && !isSeated && (
          <p className="text-center text-xs text-slate-500 mt-4">
            This page updates automatically every 30 seconds
          </p>
        )}
      </div>
    </div>
  );
}

export default function WaitlistPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-gradient-to-b from-slate-900 to-slate-800 flex items-center justify-center">
        <Loader2 className="w-12 h-12 animate-spin text-amber-500" />
      </div>
    }>
      <WaitlistContent />
    </Suspense>
  );
}

'use client';

import { useEffect, useState, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { useTranslations } from 'next-intl';
import { motion } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency } from '@/lib/utils';
import { useSettingsStore } from '@/stores/settingsStore';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  CheckCircle2,
  Clock,
  Phone,
  MapPin,
  ArrowRight,
  Loader2,
  AlertCircle,
  Cookie,
  Hash,
} from 'lucide-react';
import { QRCode } from '@/components/ui/QRCode';

interface SnackOrder {
  id: string;
  order_number: string;
  customer_name: string;
  customer_phone: string;
  pickup_location: string;
  total_amount: number;
  status: string;
  payment_method: string;
  payment_status: string;
  notes?: string;
  created_at: string;
  items?: {
    snack_items: {
      name: string;
    };
    quantity: number;
    unit_price: number;
    subtotal: number;
  }[];
}

function SnackConfirmationContent() {
  const searchParams = useSearchParams();
  const t = useTranslations('snackBar');
  const tCommon = useTranslations('common');
  const currency = useSettingsStore((s) => s.currency);
  const [order, setOrder] = useState<SnackOrder | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const orderId = searchParams.get('id');

  useEffect(() => {
    if (orderId) {
      fetchOrder();
    } else {
      setError('No order ID provided');
      setLoading(false);
    }
  }, [orderId]);

  const fetchOrder = async () => {
    try {
      const response = await api.get(`/snack/orders/${orderId}`);
      setOrder(response.data.data);
    } catch (err) {
      setError('Failed to load order details');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900">
        <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
      </div>
    );
  }

  if (error || !order) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900">
        <Card className="max-w-md mx-auto">
          <CardContent className="text-center py-8">
            <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">{error || 'Order not found'}</h2>
            <Link href="/snack-bar">
              <Button className="mt-4">{t('backToSnackBar')}</Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    );
  }

  const statusColors: Record<string, string> = {
    pending: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400',
    preparing: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
    ready: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
    completed: 'bg-slate-100 text-slate-700 dark:bg-slate-700 dark:text-slate-300',
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900 py-12">
      <div className="max-w-2xl mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.2, type: 'spring' }}
            className="w-20 h-20 bg-amber-100 dark:bg-amber-900/30 rounded-full flex items-center justify-center mx-auto mb-4"
          >
            <CheckCircle2 className="w-10 h-10 text-amber-600 dark:text-amber-400" />
          </motion.div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-white mb-2">
            {t('orderConfirmed')}
          </h1>
          <p className="text-slate-600 dark:text-slate-400">
            {t('orderConfirmationMessage')}
          </p>
        </motion.div>

        <Card className="overflow-hidden">
          <CardHeader className="bg-gradient-to-r from-amber-500 to-orange-500 text-white border-b-0">
            <CardTitle className="flex items-center justify-between">
              <span className="flex items-center gap-2">
                <Cookie className="w-5 h-5" />
                {t('orderDetails')}
              </span>
              <span className="text-sm font-mono bg-white/20 px-3 py-1 rounded-full">
                #{order.order_number}
              </span>
            </CardTitle>
          </CardHeader>
          <CardContent className="divide-y divide-slate-200 dark:divide-slate-700">
            {/* QR Code */}
            <div className="py-6 flex flex-col items-center justify-center bg-slate-50 dark:bg-slate-800/50">
              <QRCode value={order.id} size={160} />
              <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">
                {t('qrCode')}
              </p>
            </div>

            {/* Status */}
            <div className="py-4 flex items-center justify-between">
              <span className="text-slate-600 dark:text-slate-400">{tCommon('status')}</span>
              <span className={`px-3 py-1 rounded-full text-sm font-medium ${statusColors[order.status] || statusColors.pending}`}>
                {order.status.toUpperCase()}
              </span>
            </div>

            {/* Pickup Location */}
            <div className="py-4 flex items-center gap-4">
              <div className="w-12 h-12 bg-amber-100 dark:bg-amber-900/30 rounded-lg flex items-center justify-center">
                <MapPin className="w-6 h-6 text-amber-600" />
              </div>
              <div>
                <p className="text-sm text-slate-500">{t('pickupLocation')}</p>
                <p className="font-semibold">{order.pickup_location || 'Snack Bar Counter'}</p>
              </div>
            </div>

            {/* Estimated Time */}
            <div className="py-4 flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-100 dark:bg-blue-900/30 rounded-lg flex items-center justify-center">
                <Clock className="w-6 h-6 text-blue-600" />
              </div>
              <div>
                <p className="text-sm text-slate-500">{t('estimatedTime')}</p>
                <p className="font-semibold">10-15 {t('minutes')}</p>
              </div>
            </div>

            {/* Contact */}
            <div className="py-4 space-y-2">
              <p className="font-medium">{order.customer_name}</p>
              <div className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
                <Phone className="w-4 h-4" />
                <span>{order.customer_phone}</span>
              </div>
            </div>

            {/* Order Items */}
            <div className="py-4">
              <p className="text-sm text-slate-500 mb-3">{t('orderItems')}</p>
              <div className="space-y-2">
                {order.items?.map((item, index) => (
                  <div key={index} className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <span className="w-6 h-6 bg-amber-100 dark:bg-amber-900/30 rounded-full flex items-center justify-center text-xs font-medium">
                        {item.quantity}
                      </span>
                      <span>{item.snack_items?.name}</span>
                    </div>
                    <span className="font-medium">{formatCurrency(item.subtotal, currency)}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Total */}
            <div className="py-4">
              <div className="flex justify-between items-center">
                <span className="font-semibold">{tCommon('total')}</span>
                <span className="text-2xl font-bold text-amber-600">{formatCurrency(order.total_amount, currency)}</span>
              </div>
              <div className="mt-2">
                <span className={`text-xs px-2 py-1 rounded-full ${
                  order.payment_status === 'paid'
                    ? 'bg-green-100 text-green-700'
                    : 'bg-amber-100 text-amber-700'
                }`}>
                  {order.payment_status === 'paid' ? 'PAID' : `PAY ON PICKUP (${order.payment_method?.toUpperCase() || 'CASH'})`}
                </span>
              </div>
            </div>

            {/* Notes */}
            {order.notes && (
              <div className="py-4">
                <p className="text-sm text-slate-500 mb-1">{t('specialNotes')}</p>
                <p className="text-sm">{order.notes}</p>
              </div>
            )}
          </CardContent>
        </Card>

        <div className="mt-6 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg p-4">
          <p className="text-sm text-amber-800 dark:text-amber-300">
            <strong>{t('tip')}:</strong> {t('weWillCallWhenReady')}
          </p>
        </div>

        <div className="mt-6 flex flex-col sm:flex-row gap-4 justify-center">
          <Link href="/snack-bar">
            <Button variant="outline">{t('orderMore')}</Button>
          </Link>
          <Link href="/profile">
            <Button className="gap-2">
              {t('viewMyOrders')}
              <ArrowRight className="w-4 h-4" />
            </Button>
          </Link>
        </div>
      </div>
    </div>
  );
}

export default function SnackConfirmationPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900">
        <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
      </div>
    }>
      <SnackConfirmationContent />
    </Suspense>
  );
}

