                                            {settings.email || tFooter('email')}
                                        </a>
                                    </li>
                                )}
                            </ul>
                        </address>
                    </motion.div>
                </div>

                {/* Bottom Bar with glass effect */}
                <div className="mt-12 pt-8 border-t border-white/10 flex flex-col md:flex-row justify-between items-center gap-4">
