                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

'use client';

import { useState, useMemo, useCallback } from 'react';
import { z } from 'zod';
import { Check, X, Eye, EyeOff } from 'lucide-react';
import { Input } from '@/components/ui/Input';
import { Progress } from '@/components/ui/Progress';
import { cn } from '@/lib/utils';

interface PasswordStrengthMeterProps {
  value: string;
  onChange: (value: string) => void;
  onStrengthChange?: (strength: PasswordStrength) => void;
  showRequirements?: boolean;
  minStrength?: 'weak' | 'fair' | 'good' | 'strong';
  className?: string;
  placeholder?: string;
  disabled?: boolean;
}

export interface PasswordStrength {
  score: number; // 0-100
  level: 'very-weak' | 'weak' | 'fair' | 'good' | 'strong';
  label: string;
  color: string;
  requirements: PasswordRequirement[];
}

interface PasswordRequirement {
  id: string;
  label: string;
  met: boolean;
}

// Password validation rules
const REQUIREMENTS = [
  {
    id: 'length',
    label: 'At least 8 characters',
    test: (password: string) => password.length >= 8
  },
  {
    id: 'uppercase',
    label: 'One uppercase letter',
    test: (password: string) => /[A-Z]/.test(password)
  },
  {
    id: 'lowercase',
    label: 'One lowercase letter',
    test: (password: string) => /[a-z]/.test(password)
  },
  {
    id: 'number',
    label: 'One number',
    test: (password: string) => /\d/.test(password)
  },
  {
    id: 'special',
    label: 'One special character (!@#$%^&*)',
    test: (password: string) => /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)
  },
  {
    id: 'noCommon',
    label: 'Not a common password',
    test: (password: string) => !isCommonPassword(password)
  }
];

// Common passwords to reject
const COMMON_PASSWORDS = new Set([
  'password', 'password123', '12345678', 'qwerty123', 'abc12345',
  'letmein', 'welcome', 'monkey123', 'dragon123', 'master123',
  'login123', 'admin123', 'passw0rd', 'p@ssword', 'p@ssw0rd'
]);

function isCommonPassword(password: string): boolean {
  return COMMON_PASSWORDS.has(password.toLowerCase());
}

function calculateStrength(password: string): PasswordStrength {
  const requirements = REQUIREMENTS.map(req => ({
    id: req.id,
    label: req.label,
    met: req.test(password)
  }));

  const metCount = requirements.filter(r => r.met).length;
  const totalCount = requirements.length;
  
  // Base score from requirements
  let score = (metCount / totalCount) * 60;
  
  // Bonus for length
  if (password.length >= 12) score += 15;
  else if (password.length >= 10) score += 10;
  
  // Bonus for variety
  const hasUpperAndLower = /[a-z]/.test(password) && /[A-Z]/.test(password);
  const hasNumberAndSpecial = /\d/.test(password) && /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password);
  if (hasUpperAndLower && hasNumberAndSpecial) score += 15;
  else if (hasUpperAndLower || hasNumberAndSpecial) score += 10;

  // Penalty for repeated characters
  if (/(.)\1{2,}/.test(password)) score -= 10;
  
  // Penalty for sequential characters
  if (/(?:abc|bcd|cde|def|efg|fgh|ghi|hij|ijk|jkl|klm|lmn|mno|nop|opq|pqr|qrs|rst|stu|tuv|uvw|vwx|wxy|xyz|012|123|234|345|456|567|678|789)/i.test(password)) {
    score -= 10;
  }

  score = Math.max(0, Math.min(100, score));

  let level: PasswordStrength['level'];
  let label: string;
  let color: string;

  if (score < 20) {
    level = 'very-weak';
    label = 'Very Weak';
    color = 'bg-red-600';
  } else if (score < 40) {
    level = 'weak';
    label = 'Weak';
    color = 'bg-orange-500';
  } else if (score < 60) {
    level = 'fair';
    label = 'Fair';
    color = 'bg-yellow-500';
  } else if (score < 80) {
    level = 'good';
    label = 'Good';
    color = 'bg-lime-500';
  } else {
    level = 'strong';
    label = 'Strong';
    color = 'bg-green-500';
  }

  return {
    score,
    level,
    label,
    color,
    requirements
  };
}

export function PasswordStrengthMeter({
  value,
  onChange,
  onStrengthChange,
  showRequirements = true,
  minStrength = 'fair',
  className,
  placeholder = 'Enter password',
  disabled = false
}: PasswordStrengthMeterProps) {
  const [showPassword, setShowPassword] = useState(false);

  const strength = useMemo(() => {
    const result = calculateStrength(value);
    onStrengthChange?.(result);
    return result;
  }, [value, onStrengthChange]);

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      onChange(e.target.value);
    },
    [onChange]
  );

  const toggleVisibility = useCallback(() => {
    setShowPassword(prev => !prev);
  }, []);

  return (
    <div className={cn('space-y-3', className)}>
      {/* Password Input */}
      <div className="relative">
        <Input
          type={showPassword ? 'text' : 'password'}
          value={value}
          onChange={handleChange}
          placeholder={placeholder}
          disabled={disabled}
          className="pr-10"
        />
        <button
          type="button"
          onClick={toggleVisibility}
          className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
          tabIndex={-1}
        >
          {showPassword ? (
            <EyeOff className="h-4 w-4" />
          ) : (
            <Eye className="h-4 w-4" />
          )}
        </button>
      </div>

      {/* Strength Bar */}
      {value && (
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground">Password strength:</span>
            <span
              className={cn('font-medium', {
                'text-red-600': strength.level === 'very-weak',
                'text-orange-500': strength.level === 'weak',
                'text-yellow-600': strength.level === 'fair',
                'text-lime-600': strength.level === 'good',
                'text-green-600': strength.level === 'strong',
              })}
            >
              {strength.label}
            </span>
          </div>
          <div className="h-2 w-full bg-muted rounded-full overflow-hidden">
            <div
              className={cn('h-full transition-all duration-300', strength.color)}
              style={{ width: `${strength.score}%` }}
            />
          </div>
        </div>
      )}

      {/* Requirements List */}
      {showRequirements && value && (
        <div className="grid grid-cols-2 gap-2">
          {strength.requirements.map(req => (
            <div
              key={req.id}
              className={cn(
                'flex items-center gap-2 text-sm transition-colors',
                req.met ? 'text-green-600' : 'text-muted-foreground'
              )}
            >
              {req.met ? (
                <Check className="h-4 w-4 flex-shrink-0" />
              ) : (
                <X className="h-4 w-4 flex-shrink-0" />
              )}
              <span>{req.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Zod schema for password validation
export const passwordSchema = z.string()
  .min(8, 'Password must be at least 8 characters')
  .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
  .regex(/[a-z]/, 'Password must contain at least one lowercase letter')
  .regex(/\d/, 'Password must contain at least one number')
  .regex(
    /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/,
    'Password must contain at least one special character'
  )
  .refine(
    (password) => !isCommonPassword(password),
    'Password is too common. Please choose a stronger password.'
  );

// Hook for password validation
export function usePasswordValidation(password: string) {
  const strength = useMemo(() => calculateStrength(password), [password]);
  
  const isValid = useMemo(() => {
    const result = passwordSchema.safeParse(password);
    return result.success;
  }, [password]);

  const errors = useMemo(() => {
    const result = passwordSchema.safeParse(password);
    if (result.success) return [];
    return result.error.errors.map(e => e.message);
  }, [password]);

  return {
    strength,
    isValid,
    errors,
    meetsMinimum: (minLevel: PasswordStrength['level']) => {
      const levels = ['very-weak', 'weak', 'fair', 'good', 'strong'];
      return levels.indexOf(strength.level) >= levels.indexOf(minLevel);
    }
  };
}

export default PasswordStrengthMeter;

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { toast } from 'sonner';
import {
  Users,
  Clock,
  Check,
  X,
  Utensils,
  Sparkles,
  AlertCircle,
  RefreshCw,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/Tooltip';
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from '@/components/ui/ContextMenu';
import { cn } from '@/lib/utils';
import { api } from '@/lib/api';
import { useSocket } from '@/hooks/useSocket';

interface TablePosition {
  x: number;
  y: number;
  rotation: number;
  width: number;
  height: number;
  shape: 'rectangle' | 'circle' | 'square';
}

interface Table {
  id: string;
  number: number;
  name: string;
  capacity: number;
  status: 'AVAILABLE' | 'OCCUPIED' | 'RESERVED' | 'CLEANING' | 'OUT_OF_SERVICE';
  position: TablePosition;
  section: string;
  features: string[];
  currentReservation?: {
    guestName: string;
    partySize: number;
    time: string;
  };
}

interface FloorPlanProps {
  onTableSelect?: (table: Table) => void;
  selectedTableId?: string;
  isEditable?: boolean;
}

const STATUS_COLORS = {
  AVAILABLE: 'bg-green-500 hover:bg-green-600',
  OCCUPIED: 'bg-red-500 hover:bg-red-600',
  RESERVED: 'bg-yellow-500 hover:bg-yellow-600',
  CLEANING: 'bg-blue-500 hover:bg-blue-600',
  OUT_OF_SERVICE: 'bg-gray-500',
};

const STATUS_LABELS = {
  AVAILABLE: 'Available',
  OCCUPIED: 'Occupied',
  RESERVED: 'Reserved',
  CLEANING: 'Cleaning',
  OUT_OF_SERVICE: 'Out of Service',
};

export function RestaurantFloorPlan({
  onTableSelect,
  selectedTableId,
  isEditable = false,
}: FloorPlanProps) {
  const t = useTranslations('restaurant');
  const { socket } = useSocket();
  const containerRef = useRef<HTMLDivElement>(null);
  
  const [tables, setTables] = useState<Table[]>([]);
  const [dimensions, setDimensions] = useState({ width: 800, height: 600 });
  const [sections, setSections] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeSection, setActiveSection] = useState<string | 'all'>('all');
  
  // Dragging state for editable mode
  const [draggingTable, setDraggingTable] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });

  // Fetch floor plan data
  const fetchFloorPlan = useCallback(async (signal?: AbortSignal) => { // FIX Iter-23: AbortController support
    try {
      const response = await api.get('/restaurant/floor-plan', { signal }); // FIX Iter-23: pass signal
      const { tables: fetchedTables, sections: fetchedSections, dimensions: dims } = response.data.data;
      if (!signal?.aborted) { // FIX Iter-23: guard setState
        setTables(fetchedTables);
        setSections(fetchedSections);
        setDimensions(dims);
      }
    } catch (error: any) {
      if (error?.name === 'CanceledError') return; // FIX Iter-23: ignore abort
      console.error('Failed to fetch floor plan:', error);
      toast.error('Failed to load floor plan');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    const controller = new AbortController(); // FIX Iter-23: cleanup on unmount
    fetchFloorPlan(controller.signal);
    return () => controller.abort();
  }, [fetchFloorPlan]);

  // Socket listeners for real-time updates
  useEffect(() => {
    if (!socket) return;

    const handleTableStatusChanged = (data: { tableId: string; status: string }) => {
      setTables(prev =>
        prev.map(table =>
          table.id === data.tableId
            ? { ...table, status: data.status as Table['status'] }
            : table
        )
      );
    };

    const handleTablePositionUpdated = (data: { tableId: string; position: TablePosition }) => {
      setTables(prev =>
        prev.map(table =>
          table.id === data.tableId
            ? { ...table, position: data.position }
            : table
        )
      );
    };

    socket.on('table-status-changed', handleTableStatusChanged);
    socket.on('table-position-updated', handleTablePositionUpdated);

    return () => {
      socket.off('table-status-changed', handleTableStatusChanged);
      socket.off('table-position-updated', handleTablePositionUpdated);
    };
  }, [socket]);

  // Handle table status change
  const handleStatusChange = async (tableId: string, newStatus: string) => {
    try {
      await api.put(`/restaurant/tables/${tableId}/status`, { status: newStatus });
      toast.success('Table status updated');
    } catch (error) {
      toast.error('Failed to update table status');
    }
  };

  // Handle dragging in edit mode
  const handleMouseDown = (e: React.MouseEvent, table: Table) => {
    if (!isEditable) return;
    
    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;

    setDraggingTable(table.id);
    setDragOffset({
      x: e.clientX - rect.left - table.position.x,
      y: e.clientY - rect.top - table.position.y,
    });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!draggingTable || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const newX = Math.max(0, Math.min(dimensions.width - 50, e.clientX - rect.left - dragOffset.x));
    const newY = Math.max(0, Math.min(dimensions.height - 50, e.clientY - rect.top - dragOffset.y));

    setTables(prev =>
      prev.map(table =>
        table.id === draggingTable
          ? { ...table, position: { ...table.position, x: newX, y: newY } }
          : table
      )
    );
  };

  const handleMouseUp = async () => {
    if (!draggingTable) return;

    const table = tables.find(t => t.id === draggingTable);
    if (table) {
      try {
        await api.put(`/restaurant/tables/${draggingTable}/position`, {
          position: table.position,
        });
      } catch (error) {
        toast.error('Failed to save table position');
        fetchFloorPlan(); // Revert
      }
    }

    setDraggingTable(null);
  };

  // Filter tables by section
  const filteredTables = activeSection === 'all'
    ? tables
    : tables.filter(t => t.section === activeSection);

  // Render table shape
  const renderTableShape = (table: Table) => {
    const { position, status } = table;
    const isSelected = selectedTableId === table.id;
    const baseClasses = cn(
      'absolute cursor-pointer transition-all duration-200',
      STATUS_COLORS[status],
      isSelected && 'ring-4 ring-primary ring-offset-2',
      isEditable && 'cursor-move'
    );

    const style: React.CSSProperties = {
      left: position.x,
      top: position.y,
      width: position.width,
      height: position.height,
      transform: `rotate(${position.rotation}deg)`,
    };

    if (position.shape === 'circle') {
      return (
        <div
          className={cn(baseClasses, 'rounded-full')}
          style={style}
        />
      );
    }

    return (
      <div
        className={cn(
          baseClasses,
          position.shape === 'square' ? 'rounded-lg' : 'rounded-lg'
        )}
        style={style}
      />
    );
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-[600px]">
        <RefreshCw className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Section filters */}
      <div className="flex items-center gap-2">
        <Button
          variant={activeSection === 'all' ? 'default' : 'outline'}
          size="sm"
          onClick={() => setActiveSection('all')}
        >
          All
        </Button>
        {sections.map(section => (
          <Button
            key={section}
            variant={activeSection === section ? 'default' : 'outline'}
            size="sm"
            onClick={() => setActiveSection(section)}
          >
            {section}
          </Button>
        ))}
        <div className="ml-auto flex items-center gap-4 text-sm">
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-green-500" />
            <span>Available</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-red-500" />
            <span>Occupied</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-yellow-500" />
            <span>Reserved</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-blue-500" />
            <span>Cleaning</span>
          </div>
        </div>
      </div>

      {/* Floor plan */}
      <div
        ref={containerRef}
        className="relative bg-muted/50 rounded-lg border overflow-hidden"
        style={{ width: dimensions.width, height: dimensions.height }}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        <TooltipProvider>
          {filteredTables.map(table => (
            <ContextMenu key={table.id}>
              <ContextMenuTrigger>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <div
                      onMouseDown={(e) => handleMouseDown(e, table)}
                      onClick={() => !isEditable && onTableSelect?.(table)}
                    >
                      {renderTableShape(table)}
                      {/* Table label */}
                      <div
                        className="absolute flex flex-col items-center justify-center text-white text-xs font-medium pointer-events-none"
                        style={{
                          left: table.position.x,
                          top: table.position.y,
                          width: table.position.width,
                          height: table.position.height,
                        }}
                      >
                        <span>{table.number}</span>
                        <span className="flex items-center gap-0.5">
                          <Users className="h-3 w-3" />
                          {table.capacity}
                        </span>
                      </div>
                    </div>
                  </TooltipTrigger>
                  <TooltipContent>
                    <div className="space-y-1">
                      <p className="font-medium">{table.name}</p>
                      <p className="text-xs">Capacity: {table.capacity}</p>
                      <p className="text-xs">Status: {STATUS_LABELS[table.status]}</p>
                      {table.currentReservation && (
                        <div className="text-xs border-t pt-1 mt-1">
                          <p>{table.currentReservation.guestName}</p>
                          <p>{table.currentReservation.time} - {table.currentReservation.partySize} guests</p>
                        </div>
                      )}
                    </div>
                  </TooltipContent>
                </Tooltip>
              </ContextMenuTrigger>
              <ContextMenuContent>
                <ContextMenuItem
                  onClick={() => handleStatusChange(table.id, 'AVAILABLE')}
                  disabled={table.status === 'AVAILABLE'}
                >
                  <Check className="mr-2 h-4 w-4 text-green-500" />
                  Mark Available
                </ContextMenuItem>
                <ContextMenuItem
                  onClick={() => handleStatusChange(table.id, 'OCCUPIED')}
                  disabled={table.status === 'OCCUPIED'}
                >
                  <Utensils className="mr-2 h-4 w-4 text-red-500" />
                  Mark Occupied
                </ContextMenuItem>
                <ContextMenuItem
                  onClick={() => handleStatusChange(table.id, 'CLEANING')}
                  disabled={table.status === 'CLEANING'}
                >
                  <Sparkles className="mr-2 h-4 w-4 text-blue-500" />
                  Mark Cleaning
                </ContextMenuItem>
                <ContextMenuSeparator />
                <ContextMenuItem
                  onClick={() => handleStatusChange(table.id, 'OUT_OF_SERVICE')}
                  disabled={table.status === 'OUT_OF_SERVICE'}
                >
                  <AlertCircle className="mr-2 h-4 w-4 text-gray-500" />
                  Mark Out of Service
                </ContextMenuItem>
              </ContextMenuContent>
            </ContextMenu>
          ))}
        </TooltipProvider>
      </div>
    </div>
  );
}

export default RestaurantFloorPlan;

'use client';

import { useEffect } from 'react';
import { useIdleTimer } from '@/hooks/useIdleTimer';
import { useAuthStore } from '@/stores/authStore';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/AlertDialog';
import { Timer, LogOut } from 'lucide-react';

interface SessionTimeoutMonitorProps {
  /** Warning timeout in minutes (default: 25) */
  warningTimeoutMinutes?: number;
  /** Logout timeout in minutes (default: 30) */
  logoutTimeoutMinutes?: number;
  /** Whether to show the component (useful for admin-only) */
  enabled?: boolean;
}

export function SessionTimeoutMonitor({
  warningTimeoutMinutes = 25,
  logoutTimeoutMinutes = 30,
  enabled = true
}: SessionTimeoutMonitorProps) {
  const { isAuthenticated } = useAuthStore();
  
  const {
    isWarningActive,
    remainingSeconds,
    extendSession,
    logout
  } = useIdleTimer({
    warningTimeoutMinutes,
    logoutTimeoutMinutes
  });

  // Don't render if not authenticated or not enabled
  if (!isAuthenticated || !enabled) {
    return null;
  }

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <AlertDialog open={isWarningActive}>
      <AlertDialogContent className="sm:max-w-md">
        <AlertDialogHeader>
          <div className="flex items-center gap-3">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-orange-100">
              <Timer className="h-6 w-6 text-orange-600" />
            </div>
            <AlertDialogTitle className="text-xl">
              Session Timeout Warning
            </AlertDialogTitle>
          </div>
          <AlertDialogDescription className="pt-4 text-base">
            Your session is about to expire due to inactivity.
          </AlertDialogDescription>
        </AlertDialogHeader>
        
        <div className="flex flex-col items-center gap-4 py-6">
          <div className="text-5xl font-bold text-orange-600 tabular-nums">
            {formatTime(remainingSeconds)}
          </div>
          <p className="text-sm text-muted-foreground">
            You will be logged out automatically
          </p>
        </div>

        <AlertDialogFooter className="flex gap-2 sm:gap-2">
          <AlertDialogCancel
            onClick={logout}
            className="flex items-center gap-2"
          >
            <LogOut className="h-4 w-4" />
            Log Out Now
          </AlertDialogCancel>
          <AlertDialogAction
            onClick={extendSession}
            className="bg-primary"
          >
            Stay Logged In
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

export default SessionTimeoutMonitor;

'use client';

import { motion, AnimatePresence } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { Star, Quote, ChevronLeft, ChevronRight, User, Loader2, X, Send } from 'lucide-react';
import { useState, useEffect } from 'react';
import { API_BASE_URL, api } from '@/lib/api';
import { useAuth } from '@/lib/auth-context';
import { toast } from 'sonner';
import Link from 'next/link';

interface Testimonial {
  id: string;
  name: string;
  role: string;
  avatar?: string;
  rating: number;
  text: string;
  date: string;
}

interface ReviewsResponse {
  success?: boolean;
  data?: {
    reviews: Array<{
      id: string;
      rating: number;
      text: string;
      service_type: string;
      created_at: string;
      users: {
        full_name: string;
        profile_image_url?: string;
      };
    }>;
    stats: {
      totalReviews: number;
      averageRating: number;
    };
  };
  reviews?: Array<{
    id: string;
    rating: number;
    text: string;
    service_type: string;
    created_at: string;
    user: {
      first_name: string;
      last_name: string;
    };
  }>;
  stats?: {
    average_rating: number;
    total_reviews: number;
  };
}

// Empty placeholder - no fake testimonials
const emptyTestimonials: Testimonial[] = [];

const serviceTypeLabels: Record<string, string> = {
  general: 'Resort Guest',
  restaurant: 'Restaurant Guest',
  pool: 'Pool Guest',
  chalets: 'Chalet Guest',
  snack_bar: 'Snack Bar Guest',
};

export default function TestimonialsCarousel() {
  const t = useTranslations('testimonials');
  const { isAuthenticated, user } = useAuth();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [direction, setDirection] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const [testimonials, setTestimonials] = useState<Testimonial[]>(emptyTestimonials);
  const [stats, setStats] = useState({ average_rating: 0, total_reviews: 0 });
  const [showReviewForm, setShowReviewForm] = useState(false);
  const [reviewData, setReviewData] = useState({ rating: 5, text: '', service_type: 'general' });
  const [submitting, setSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Fetch reviews from API
  useEffect(() => {
    const fetchReviews = async () => {
      try {
        const response = await api.get('/reviews');
        if (response.status === 200) {
          const data: ReviewsResponse = response.data;
          
          // Handle new API format (success/data wrapper)
          const reviewsData = data.data?.reviews || data.reviews || [];
          const statsData = data.data?.stats || data.stats;
          
          if (reviewsData.length > 0) {
            interface ReviewRecord {
              id: string;
              rating: number;
              text: string;
              service_type: string;
              created_at?: string;
              users?: { full_name?: string; profile_image_url?: string };
              user?: { first_name: string; last_name: string };
            }
            const mappedTestimonials: Testimonial[] = reviewsData.map((review: ReviewRecord) => {
              // Handle both formats: users.full_name or user.first_name/last_name
              const name = review.users?.full_name || 
                (review.user ? `${review.user.first_name} ${review.user.last_name}` : 'Guest');
              
              return {
                id: review.id,
                name,
                avatar: review.users?.profile_image_url,
                role: serviceTypeLabels[review.service_type] || 'Guest',
                rating: review.rating,
                text: review.text,
                date: review.created_at?.split('T')[0] || '',
              };
            });
            setTestimonials(mappedTestimonials);
          }
          
          if (statsData) {
            // Use type-safe access with fallback
            const avgRating = 'averageRating' in statsData ? statsData.averageRating : 
                              'average_rating' in statsData ? statsData.average_rating : 4.9;
            const totalRevs = 'totalReviews' in statsData ? statsData.totalReviews :
                              'total_reviews' in statsData ? statsData.total_reviews : 0;
            setStats({
              average_rating: avgRating,
              total_reviews: totalRevs,
            });
          }
        }
      } catch (error) {
        // Using fallback testimonials if API fails
      } finally {
        setIsLoading(false);
      }
    };
    fetchReviews();
  }, []);

  useEffect(() => {
    if (!isAutoPlaying || testimonials.length === 0) return;
    
    const interval = setInterval(() => {
      setDirection(1);
      setCurrentIndex((prev) => (prev + 1) % testimonials.length);
    }, 5000);
    
    return () => clearInterval(interval);
  }, [isAutoPlaying, testimonials.length]);

  const slideVariants = {
    enter: (direction: number) => ({
      x: direction > 0 ? 300 : -300,
      opacity: 0,
      scale: 0.9,
    }),
    center: {
      x: 0,
      opacity: 1,
      scale: 1,
      transition: {
        x: { type: 'spring' as const, stiffness: 300, damping: 30 },
        opacity: { duration: 0.3 },
        scale: { duration: 0.3 },
      },
    },
    exit: (direction: number) => ({
      x: direction < 0 ? 300 : -300,
      opacity: 0,
      scale: 0.9,
      transition: {
        x: { type: 'spring' as const, stiffness: 300, damping: 30 },
        opacity: { duration: 0.3 },
        scale: { duration: 0.3 },
      },
    }),
  };

  const goTo = (index: number) => {
    if (testimonials.length === 0) return;
    setDirection(index > currentIndex ? 1 : -1);
    setCurrentIndex(index);
    setIsAutoPlaying(false);
    setTimeout(() => setIsAutoPlaying(true), 10000);
  };

  const goNext = () => {
    if (testimonials.length === 0) return;
    setDirection(1);
    setCurrentIndex((prev) => (prev + 1) % testimonials.length);
    setIsAutoPlaying(false);
    setTimeout(() => setIsAutoPlaying(true), 10000);
  };

  const goPrev = () => {
    if (testimonials.length === 0) return;
    setDirection(-1);
    setCurrentIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);
    setIsAutoPlaying(false);
    setTimeout(() => setIsAutoPlaying(true), 10000);
  };

  const handleSubmitReview = async () => {
    if (!reviewData.text.trim()) {
      toast.error(t('pleaseWriteReview') || 'Please write a review');
      return;
    }
    
    setSubmitting(true);
    try {
      const response = await api.post('/reviews', {
        rating: reviewData.rating,
        text: reviewData.text,
        service_type: reviewData.service_type
      });
      
      if (response.data?.success || response.status === 200 || response.status === 201) {
        toast.success(t('reviewSubmitted') || 'Thank you for your review!');
        setShowReviewForm(false);
        setReviewData({ rating: 5, text: '', service_type: 'general' });
        // Refresh reviews
        const fetchResponse = await api.get('/reviews');
        if (fetchResponse.status === 200) {
          const data: ReviewsResponse = fetchResponse.data;
          // FIX Iter-11: use same format handling as initial fetch (data.data?.reviews || data.reviews)
          const reviewsData = data.data?.reviews || data.reviews || [];
          if (reviewsData.length > 0) {
            const mappedTestimonials: Testimonial[] = reviewsData.map((review) => ({
              id: review.id,
              name: (review as any).users?.full_name || 
                ((review as any).user ? `${(review as any).user.first_name} ${(review as any).user.last_name}` : 'Guest'),
              role: serviceTypeLabels[review.service_type] || 'Guest',
              rating: review.rating,
              text: review.text,
              date: review.created_at.split('T')[0],
            }));
            setTestimonials(mappedTestimonials);
            if (data.data?.stats || data.stats) { // FIX Iter-11: handle both API formats for stats
              setStats((data.data?.stats || data.stats) as any);
            }
          }
        }
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Failed to submit review';
      toast.error(message);
    } finally {
      setSubmitting(false);
    }
  };

  const currentTestimonial = testimonials.length > 0 ? testimonials[currentIndex] : null;

  // Review form modal component (inline)
  const renderReviewModal = () => (
    <AnimatePresence>
      {showReviewForm && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
          role="dialog" // FIX Iter-12: a11y — modal semantics
          aria-modal="true" // FIX Iter-12: a11y
          aria-label="Write a review" // FIX Iter-12: a11y
          onClick={() => setShowReviewForm(false)}
          onKeyDown={(e) => { if (e.key === 'Escape') setShowReviewForm(false); }} // FIX Iter-12: a11y — Escape to close
        >
          <motion.div
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.9, opacity: 0 }}
            className="bg-white dark:bg-slate-800 rounded-2xl p-6 max-w-md w-full shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-slate-900 dark:text-white">
                {t('writeReview') || 'Write a Review'}
              </h3>
              <button
                onClick={() => setShowReviewForm(false)}
                aria-label="Close review form" // FIX Iter-12: a11y
                className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors"
              >
                <X className="w-5 h-5 text-slate-500" />
              </button>
            </div>
            <div className="mb-6">
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                {t('yourRating') || 'Your Rating'}
              </label>
              <div className="flex gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    onClick={() => setReviewData({ ...reviewData, rating: star })}
                    className="p-1 hover:scale-110 transition-transform"
                  >
                    <Star
                      className={`w-8 h-8 ${
                        star <= reviewData.rating
                          ? 'text-yellow-400 fill-yellow-400'
                          : 'text-slate-300 dark:text-slate-600'
                      }`}
                    />
                  </button>
                ))}
              </div>
            </div>
            <div className="mb-6">
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                {t('serviceType') || 'Service Type'}
              </label>
              <select
                value={reviewData.service_type}
                onChange={(e) => setReviewData({ ...reviewData, service_type: e.target.value })}
                className="w-full px-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-amber-500"
              >
                <option value="general">{t('serviceGeneral') || 'General Experience'}</option>
                <option value="chalets">{t('serviceChalets') || 'Chalets'}</option>
                <option value="restaurant">{t('serviceRestaurant') || 'Restaurant'}</option>
                <option value="pool">{t('servicePool') || 'Pool'}</option>
              </select>
            </div>
            <div className="mb-6">
              <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                {t('yourReview') || 'Your Review'}
              </label>
              <textarea
                value={reviewData.text}
                onChange={(e) => setReviewData({ ...reviewData, text: e.target.value })}
                placeholder={t('reviewPlaceholder') || 'Share your experience (minimum 10 characters)...'}
                rows={4}
                className="w-full px-4 py-3 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white placeholder-slate-400 focus:ring-2 focus:ring-amber-500 resize-none"
              />
            </div>
            <button
              onClick={handleSubmitReview}
              disabled={submitting}
              className="w-full py-3 bg-amber-500 hover:bg-amber-600 disabled:bg-amber-400 text-white rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
            >
              {submitting ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  {t('submitting') || 'Submitting...'}
                </>
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  {t('submitReview') || 'Submit Review'}
                </>
              )}
            </button>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );

  // If still loading, show a loading state
  if (isLoading) {
    return (
      <div className="relative">
        <div className="absolute inset-0 bg-gradient-to-br from-amber-50 via-orange-50 to-rose-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900 rounded-3xl" />
        <div className="relative px-8 py-12 md:px-16 text-center">
          <Loader2 className="w-8 h-8 animate-spin text-amber-500 mx-auto" />
          <p className="text-slate-500 dark:text-slate-400 mt-4">{t('loading') || 'Loading reviews...'}</p>
        </div>
      </div>
    );
  }

  // If no testimonials, show a message encouraging reviews
  if (testimonials.length === 0 || !currentTestimonial) {
    return (
      <div className="relative">
        <div className="absolute inset-0 bg-gradient-to-br from-amber-50 via-orange-50 to-rose-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900 rounded-3xl" />
        <div className="relative px-8 py-12 md:px-16 text-center">
          <span className="inline-flex items-center gap-2 px-4 py-2 bg-amber-100 dark:bg-amber-900/30 rounded-full text-amber-700 dark:text-amber-400 text-sm font-medium mb-4">
            <Star className="w-4 h-4 fill-current" />
            {t('badge')}
          </span>
          <h2 className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white mb-4">
            {t('title')}
          </h2>
          <p className="text-slate-600 dark:text-slate-400 mb-8">
            {t('noReviewsYet') || 'Be the first to share your experience!'}
          </p>
          {isAuthenticated ? (
            <button
              onClick={() => setShowReviewForm(true)}
              className="inline-flex items-center gap-2 px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-full font-medium transition-colors shadow-lg shadow-amber-500/25"
            >
              <Star className="w-5 h-5" />
              {t('leaveReview') || 'Leave a Review'}
            </button>
          ) : (
            <Link
              href="/login"
              className="inline-flex items-center gap-2 px-6 py-3 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 rounded-full font-medium transition-colors"
            >
              <User className="w-5 h-5" />
              {t('loginToReview') || 'Login to Leave a Review'}
            </Link>
          )}
          {renderReviewModal()}
        </div>
      </div>
    );
  }

  return (
    <div className="relative">
      {/* Background decoration */}
      <div className="absolute inset-0 bg-gradient-to-br from-amber-50 via-orange-50 to-rose-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900 rounded-3xl" />
      
      {/* Quote decoration */}
      <div className="absolute top-8 left-8 opacity-10">
        <Quote className="w-24 h-24 text-amber-600" />
      </div>
      
      <div className="relative px-8 py-12 md:px-16">
        {/* Header */}
        <div className="text-center mb-10">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
          >
            <span className="inline-flex items-center gap-2 px-4 py-2 bg-amber-100 dark:bg-amber-900/30 rounded-full text-amber-700 dark:text-amber-400 text-sm font-medium mb-4">
              <Star className="w-4 h-4 fill-current" />
              {t('badge')}
            </span>
            <h2 className="text-3xl md:text-4xl font-bold text-slate-900 dark:text-white mb-2">
              {t('title')}
            </h2>
            <p className="text-slate-600 dark:text-slate-400 max-w-2xl mx-auto">
              {t('subtitle')}
            </p>
          </motion.div>
        </div>

        {/* Carousel */}
        <div className="relative max-w-3xl mx-auto">
          {/* Navigation buttons */}
          <button
            onClick={goPrev}
            className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-4 md:-translate-x-12 z-10 w-12 h-12 rounded-full bg-white dark:bg-slate-700 shadow-lg flex items-center justify-center text-slate-600 dark:text-slate-300 hover:bg-amber-50 dark:hover:bg-slate-600 transition-colors"
          >
            <ChevronLeft className="w-6 h-6" />
          </button>
          <button
            onClick={goNext}
            className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-4 md:translate-x-12 z-10 w-12 h-12 rounded-full bg-white dark:bg-slate-700 shadow-lg flex items-center justify-center text-slate-600 dark:text-slate-300 hover:bg-amber-50 dark:hover:bg-slate-600 transition-colors"
          >
            <ChevronRight className="w-6 h-6" />
          </button>

          {/* Testimonial Card */}
          <div className="overflow-hidden">
            <AnimatePresence mode="wait" custom={direction}>
              <motion.div
                key={currentIndex}
                custom={direction}
                variants={slideVariants}
                initial="enter"
                animate="center"
                exit="exit"
                className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl p-8 md:p-10"
              >
                {/* Stars */}
                <div className="flex gap-1 mb-6 justify-center">
                  {[...Array(5)].map((_, i) => (
                    <motion.div
                      key={i}
                      initial={{ opacity: 0, scale: 0 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ delay: i * 0.1 }}
                    >
                      <Star
                        className={`w-6 h-6 ${
                          i < currentTestimonial.rating
                            ? 'text-yellow-400 fill-yellow-400'
                            : 'text-slate-300 dark:text-slate-600'
                        }`}
                      />
                    </motion.div>
                  ))}
                </div>

                {/* Quote text */}
                <blockquote className="text-lg md:text-xl text-slate-700 dark:text-slate-300 text-center mb-8 leading-relaxed">
                  "{currentTestimonial.text}"
                </blockquote>

                {/* Author */}
                <div className="flex items-center justify-center gap-4">
                  <div className="w-14 h-14 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center text-white text-xl font-bold shadow-lg">
                    {currentTestimonial.avatar ? (
                      <img
                        src={currentTestimonial.avatar}
                        alt={currentTestimonial.name}
                        className="w-full h-full rounded-full object-cover"
                      />
                    ) : (
                      currentTestimonial.name.charAt(0)
                    )}
                  </div>
                  <div className="text-left">
