            </AnimatePresence>
          </div>

          {/* Dots navigation */}
          <div className="flex justify-center gap-2 mt-6">
            {testimonials.map((_, index) => (
              <button
                key={index}
                onClick={() => goTo(index)}
                className={`w-2.5 h-2.5 rounded-full transition-all ${
                  index === currentIndex
                    ? 'bg-amber-500 w-8'
                    : 'bg-slate-300 dark:bg-slate-600 hover:bg-amber-300'
                }`}
              />
            ))}
          </div>
        </div>

        {/* Stats */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ delay: 0.3 }}
          className="grid grid-cols-3 gap-4 mt-12 max-w-2xl mx-auto"
        >
          <div className="text-center">
            <div className="text-3xl font-bold text-amber-600 dark:text-amber-400">{stats.average_rating.toFixed(1)}</div>
            <div className="text-sm text-slate-600 dark:text-slate-400">{t('averageRating')}</div>
          </div>
          <div className="text-center">
            <div className="text-3xl font-bold text-amber-600 dark:text-amber-400">{stats.total_reviews}+</div>
            <div className="text-sm text-slate-600 dark:text-slate-400">{t('happyGuests')}</div>
          </div>
          <div className="text-center">
            <div className="text-3xl font-bold text-amber-600 dark:text-amber-400">98%</div>
            <div className="text-sm text-slate-600 dark:text-slate-400">{t('recommend')}</div>
          </div>
        </motion.div>

        {/* Leave a Review Button */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ delay: 0.4 }}
          className="text-center mt-8"
        >
          {isAuthenticated ? (
            <button
              onClick={() => setShowReviewForm(true)}
              className="inline-flex items-center gap-2 px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-full font-medium transition-colors shadow-lg shadow-amber-500/25"
            >
              <Star className="w-5 h-5" />
              {t('leaveReview') || 'Leave a Review'}
            </button>
          ) : (
            <Link
              href="/login"
              className="inline-flex items-center gap-2 px-6 py-3 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 rounded-full font-medium transition-colors"
            >
              <User className="w-5 h-5" />
              {t('loginToReview') || 'Login to Leave a Review'}
            </Link>
          )}
        </motion.div>
      </div>

      {/* Review Form Modal */}
      {renderReviewModal()}
    </div>
  );
}

'use client';

import React, { useEffect } from 'react';
import { useTheme } from 'next-themes';
import { useSiteSettings } from '@/lib/settings-context';
import { resortThemes } from '@/lib/theme-config';

// Color manipulation utilities
function hexToRgb(hex: string): { r: number; g: number; b: number } | null {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result
    ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16),
      }
    : null;
}

function rgbToHsl(r: number, g: number, b: number): { h: number; s: number; l: number } {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0;
  let s = 0;
  const l = (max + min) / 2;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r:
        h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
        break;
      case g:
        h = ((b - r) / d + 2) / 6;
        break;
      case b:
        h = ((r - g) / d + 4) / 6;
        break;
    }
  }
  return { h: h * 360, s: s * 100, l: l * 100 };
}

function hslToHex(h: number, s: number, l: number): string {
  s /= 100;
  l /= 100;
  const a = s * Math.min(l, 1 - l);
  const f = (n: number) => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

// Generate color shades from base color
function generateColorShades(baseHex: string): Record<string, string> {
  const rgb = hexToRgb(baseHex);
  if (!rgb) return {};
  
  const hsl = rgbToHsl(rgb.r, rgb.g, rgb.b);
  
  return {
    '50': hslToHex(hsl.h, Math.min(hsl.s * 0.3, 100), 97),
    '100': hslToHex(hsl.h, Math.min(hsl.s * 0.4, 100), 94),
    '200': hslToHex(hsl.h, Math.min(hsl.s * 0.5, 100), 86),
    '300': hslToHex(hsl.h, Math.min(hsl.s * 0.7, 100), 74),
    '400': hslToHex(hsl.h, Math.min(hsl.s * 0.9, 100), 60),
    '500': baseHex,
    '600': hslToHex(hsl.h, Math.min(hsl.s * 1.1, 100), Math.max(hsl.l * 0.85, 20)),
    '700': hslToHex(hsl.h, Math.min(hsl.s * 1.2, 100), Math.max(hsl.l * 0.7, 15)),
    '800': hslToHex(hsl.h, Math.min(hsl.s * 1.3, 100), Math.max(hsl.l * 0.55, 12)),
    '900': hslToHex(hsl.h, Math.min(hsl.s * 1.4, 100), Math.max(hsl.l * 0.4, 10)),
    '950': hslToHex(hsl.h, Math.min(hsl.s * 1.5, 100), Math.max(hsl.l * 0.25, 5)),
  };
}

export function ThemeInjector() {
  const { settings } = useSiteSettings();
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';

  useEffect(() => {
    // Get the resort theme
    const theme = settings.theme && resortThemes[settings.theme as keyof typeof resortThemes] 
      ? resortThemes[settings.theme as keyof typeof resortThemes] 
      : resortThemes.beach;

    // Get colors - use custom colors if available, otherwise use theme preset
    const baseColors = settings.themeColors || theme.colors;
    const themeColors = theme.colors;

    // Apply CSS custom properties to :root
    const root = document.documentElement;
    
    // Primary colors (same in both modes)
    root.style.setProperty('--color-primary', baseColors.primary);
    root.style.setProperty('--color-secondary', baseColors.secondary);
    root.style.setProperty('--color-accent', baseColors.accent);
    
    // Mode-specific colors - background, surface, text
    // When custom colors are set, use them in both light and dark modes (with dark fallbacks)
    const hasCustomColors = !!settings.themeColors;
    
    if (isDark) {
      // In dark mode: use custom colors if set, otherwise use theme dark preset
      root.style.setProperty('--color-background', hasCustomColors && baseColors.backgroundDark ? baseColors.backgroundDark : themeColors.backgroundDark);
      root.style.setProperty('--color-surface', hasCustomColors && baseColors.surfaceDark ? baseColors.surfaceDark : themeColors.surfaceDark);
      root.style.setProperty('--color-surface-secondary', hasCustomColors && baseColors.surfaceSecondaryDark ? baseColors.surfaceSecondaryDark : (themeColors.surfaceSecondaryDark || themeColors.surfaceDark));
      root.style.setProperty('--color-surface-elevated', hasCustomColors && baseColors.surfaceElevatedDark ? baseColors.surfaceElevatedDark : (themeColors.surfaceElevatedDark || themeColors.surfaceDark));
      root.style.setProperty('--color-text', hasCustomColors && baseColors.textDark ? baseColors.textDark : themeColors.textDark);
      root.style.setProperty('--color-text-muted', hasCustomColors && baseColors.textMutedDark ? baseColors.textMutedDark : themeColors.textMutedDark);
      root.style.setProperty('--color-border', hasCustomColors && baseColors.borderDark ? baseColors.borderDark : (themeColors.borderDark || themeColors.textMutedDark));
      root.style.setProperty('--color-border-muted', hasCustomColors && baseColors.borderMutedDark ? baseColors.borderMutedDark : (themeColors.borderMutedDark || themeColors.surfaceDark));
    } else {
      root.style.setProperty('--color-background', baseColors.background);
      root.style.setProperty('--color-surface', baseColors.surface);
      root.style.setProperty('--color-surface-secondary', baseColors.surfaceSecondary || baseColors.background);
      root.style.setProperty('--color-surface-elevated', baseColors.surfaceElevated || baseColors.surface);
      root.style.setProperty('--color-text', baseColors.text);
      root.style.setProperty('--color-text-muted', baseColors.textMuted);
      root.style.setProperty('--color-border', baseColors.border || baseColors.textMuted);
      root.style.setProperty('--color-border-muted', baseColors.borderMuted || baseColors.background);
    }

    // Text on colored backgrounds (guaranteed readability)
    root.style.setProperty('--color-text-on-primary', themeColors.textOnPrimary || '#ffffff');
    root.style.setProperty('--color-text-on-secondary', themeColors.textOnSecondary || '#ffffff');
    root.style.setProperty('--color-text-on-accent', themeColors.textOnAccent || '#ffffff');
    
    // Focus ring color
    root.style.setProperty('--color-focus-ring', themeColors.focusRing || baseColors.primary);
    
    // Status colors
    root.style.setProperty('--color-success', themeColors.success || '#22c55e');
    root.style.setProperty('--color-warning', themeColors.warning || '#f59e0b');
    root.style.setProperty('--color-error', themeColors.error || '#ef4444');

    // Convert hex to RGB for Tailwind opacity support
    const toRgbString = (hex: string) => {
      const rgb = hexToRgb(hex);
      return rgb ? `${rgb.r} ${rgb.g} ${rgb.b}` : '0 0 0';
    };

    root.style.setProperty('--color-primary-rgb', toRgbString(baseColors.primary));
    root.style.setProperty('--color-secondary-rgb', toRgbString(baseColors.secondary));
    root.style.setProperty('--color-accent-rgb', toRgbString(baseColors.accent));
    
    const bgColor = isDark ? themeColors.backgroundDark : baseColors.background;
    const surfaceColor = isDark ? themeColors.surfaceDark : baseColors.surface;
    const textColor = isDark ? themeColors.textDark : baseColors.text;
    root.style.setProperty('--color-background-rgb', toRgbString(bgColor));
    root.style.setProperty('--color-surface-rgb', toRgbString(surfaceColor));
    root.style.setProperty('--color-text-rgb', toRgbString(textColor));

    // Generate and apply color shades
    const primaryShades = generateColorShades(baseColors.primary);
    const secondaryShades = generateColorShades(baseColors.secondary);
    const accentShades = generateColorShades(baseColors.accent);

    Object.entries(primaryShades).forEach(([shade, color]) => {
      root.style.setProperty(`--color-primary-${shade}`, color);
    });
    Object.entries(secondaryShades).forEach(([shade, color]) => {
      root.style.setProperty(`--color-secondary-${shade}`, color);
    });
    Object.entries(accentShades).forEach(([shade, color]) => {
      root.style.setProperty(`--color-accent-${shade}`, color);
    });

    // Theme gradients - use dark variants when in dark mode
    if (theme.gradients) {
      if (isDark && theme.gradients.heroDark) {
        root.style.setProperty('--gradient-hero', theme.gradients.heroDark);
        root.style.setProperty('--gradient-card', theme.gradients.cardDark);
      } else {
        root.style.setProperty('--gradient-hero', theme.gradients.hero);
        root.style.setProperty('--gradient-card', theme.gradients.card);
      }
      root.style.setProperty('--gradient-button', theme.gradients.button);
    }

    // Aurora/mesh gradient based on theme colors and mode
    const auroraOpacity = isDark ? '30' : '40';
    root.style.setProperty('--gradient-aurora', 
      `radial-gradient(ellipse 80% 80% at 50% -20%, ${baseColors.primary}${auroraOpacity}, transparent),
       radial-gradient(ellipse 60% 60% at 80% 50%, ${baseColors.secondary}${isDark ? '25' : '30'}, transparent),
       radial-gradient(ellipse 50% 50% at 20% 80%, ${baseColors.accent}${isDark ? '15' : '20'}, transparent)`
    );
    
    const meshOpacity = isDark ? '10' : '15';
    root.style.setProperty('--gradient-mesh',
      `radial-gradient(at 40% 20%, ${baseColors.primary}${meshOpacity} 0px, transparent 50%),
       radial-gradient(at 80% 0%, ${baseColors.secondary}${meshOpacity} 0px, transparent 50%),
       radial-gradient(at 0% 50%, ${baseColors.accent}${isDark ? '08' : '10'} 0px, transparent 50%),
       radial-gradient(at 80% 80%, ${baseColors.primary}${isDark ? '08' : '10'} 0px, transparent 50%)`
    );

    // Glass colors derived from theme - adjust for dark mode
    const glassOpacity = isDark ? '20' : '15';
    root.style.setProperty('--glass-primary', `${baseColors.primary}${glassOpacity}`);
    root.style.setProperty('--glass-secondary', `${baseColors.secondary}${glassOpacity}`);
    root.style.setProperty('--glass-accent', `${baseColors.accent}${glassOpacity}`);

    // Theme pattern
    if (theme.pattern) {
      root.style.setProperty('--theme-pattern', `url("${theme.pattern}")`);
    }

    // Weather effect for this theme
    if (theme.weatherEffect) {
      root.style.setProperty('--weather-effect', theme.weatherEffect);
    }

    // Set theme identifier for conditional styling
    root.setAttribute('data-theme', settings.theme || 'beach');
    root.setAttribute('data-color-mode', isDark ? 'dark' : 'light');
    
    // Persist theme to localStorage for the inline script on next page load
    // This prevents theme flash on subsequent visits
    try {
      localStorage.setItem('v2-ecosystem-theme', settings.theme || 'beach');
    } catch (e) {
      // localStorage not available (e.g., private browsing)
    }

  }, [settings.theme, settings.themeColors, isDark]);

  return null;
}

'use client';

import { useTheme } from 'next-themes';
import { useEffect, useState } from 'react';
import { Moon, Sun, Monitor } from 'lucide-react';

export function ThemeToggle() {
  const { theme, setTheme, resolvedTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <button className="p-2 rounded-lg bg-gray-100 dark:bg-gray-800" aria-label="Toggle theme">
        <Sun className="h-5 w-5" />
      </button>
    );
  }

  const cycleTheme = () => {
    if (theme === 'light') {
      setTheme('dark');
    } else if (theme === 'dark') {
      setTheme('system');
    } else {
      setTheme('light');
    }
  };

  return (
    <button
      onClick={cycleTheme}
      className="p-2 rounded-lg bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
      aria-label={`Current theme: ${theme}. Click to change.`}
      title={`Theme: ${theme}`}
    >
      {resolvedTheme === 'dark' ? (
        <Moon className="h-5 w-5 text-blue-400" />
      ) : resolvedTheme === 'light' ? (
        <Sun className="h-5 w-5 text-yellow-500" />
      ) : (
        <Monitor className="h-5 w-5 text-gray-500" />
      )}
    </button>
  );
}

export function ThemeDropdown() {
  const { theme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return null;
  }

  const themes = [
    { value: 'light', label: 'Light', icon: Sun },
    { value: 'dark', label: 'Dark', icon: Moon },
    { value: 'system', label: 'System', icon: Monitor },
  ];

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-2 px-3 py-2 rounded-lg bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
      >
        {theme === 'dark' ? (
          <Moon className="h-4 w-4" />
        ) : theme === 'light' ? (
          <Sun className="h-4 w-4" />
        ) : (
          <Monitor className="h-4 w-4" />
        )}
        <span className="text-sm capitalize">{theme}</span>
      </button>

      {isOpen && (
        <>
          <div 
            className="fixed inset-0 z-10" 
            onClick={() => setIsOpen(false)} 
          />
          <div className="absolute right-0 mt-2 w-36 rounded-lg bg-white dark:bg-gray-800 shadow-lg ring-1 ring-black ring-opacity-5 z-20">
            <div className="py-1">
              {themes.map(({ value, label, icon: Icon }) => (
                <button
                  key={value}
                  onClick={() => {
                    setTheme(value);
                    setIsOpen(false);
                  }}
                  className={`flex items-center gap-2 w-full px-4 py-2 text-sm hover:bg-gray-100 dark:hover:bg-gray-700 ${
                    theme === value ? 'text-blue-600 dark:text-blue-400' : 'text-gray-700 dark:text-gray-300'
                  }`}
                >
                  <Icon className="h-4 w-4" />
                  {label}
                </button>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  Sun,
  Cloud,
  CloudRain,
  CloudSnow,
  CloudLightning,
  Wind,
  Droplets,
  Thermometer,
  Eye,
  Loader2
} from 'lucide-react';
import { useSiteSettings } from '@/lib/settings-context';

interface WeatherData {
  temperature: number;
  feels_like: number;
  humidity: number;
  wind_speed: number;
  visibility: number;
  condition: string;
  description: string;
  icon: string;
  location: string;
  isDemo?: boolean; // FIX Iter-12: flag for demo/fallback data
}

interface WeatherWidgetProps {
  variant?: 'compact' | 'full' | 'header';
  className?: string;
}

// Weather condition to icon mapping
function getWeatherIcon(condition: string, size = 'w-8 h-8') {
  const conditionLower = condition.toLowerCase();

  if (conditionLower.includes('thunder') || conditionLower.includes('storm')) {
    return <CloudLightning className={`${size} text-yellow-500`} />;
  }
  if (conditionLower.includes('rain') || conditionLower.includes('drizzle')) {
    return <CloudRain className={`${size} text-blue-400`} />;
  }
  if (conditionLower.includes('snow') || conditionLower.includes('sleet')) {
    return <CloudSnow className={`${size} text-blue-200`} />;
  }
  if (conditionLower.includes('cloud') || conditionLower.includes('overcast')) {
    return <Cloud className={`${size} text-gray-400`} />;
  }
  if (conditionLower.includes('clear') || conditionLower.includes('sunny')) {
    return <Sun className={`${size} text-yellow-400`} />;
  }
  return <Sun className={`${size} text-yellow-400`} />;
}

export default function WeatherWidget({ variant = 'compact', className = '' }: WeatherWidgetProps) {
  const { settings } = useSiteSettings();
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Only fetch if weather widget is enabled
    if (settings.showWeatherWidget === false) {
      setLoading(false);
      return;
    }

    // FIX Iter-18: AbortController to prevent state updates on unmounted component
    const controller = new AbortController();

    const fetchWeather = async () => {
      try {
        if (!controller.signal.aborted) setLoading(true);
        if (!controller.signal.aborted) setError(null);

        // Try to fetch from our backend which should have API key configured
        const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';
        const apiUrl = baseUrl.replace(/\/api\/?$/, '');
        const location = encodeURIComponent(settings.weatherLocation || 'New York, USA');

        const response = await fetch(`${apiUrl}/api/weather?location=${location}`, { signal: controller.signal });

        if (!response.ok) {
          if (controller.signal.aborted) return;
          // FIX Iter-12: mark fallback data so UI can indicate it's demo data
          setWeather({
            temperature: 24,
            feels_like: 26,
            humidity: 65,
            wind_speed: 12,
            visibility: 10,
            condition: 'Partly Cloudy',
            description: 'Demo data — weather service unavailable',
            icon: 'cloud-sun',
            location: settings.weatherLocation || 'Resort Location',
            isDemo: true, // FIX Iter-12: flag for UI indicator
          });
          return;
        }

        if (controller.signal.aborted) return;
        const data = await response.json();
        if (data.success && data.data) {
          setWeather(data.data);
        }
      } catch (err: any) {
        if (err?.name === 'AbortError' || controller.signal.aborted) return;
        console.error('Weather fetch error:', err);
        // FIX Iter-12: mark fallback data so UI can indicate it's demo data
        setWeather({
          temperature: 24,
          feels_like: 26,
          humidity: 65,
          wind_speed: 12,
          visibility: 10,
          condition: 'Partly Cloudy',
          description: 'Demo data — weather service unavailable',
          icon: 'cloud-sun',
          location: settings.weatherLocation || 'Resort Location',
          isDemo: true, // FIX Iter-12: flag for UI indicator
        });
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    };

    fetchWeather();

    // Refresh weather every 30 minutes
    const interval = setInterval(fetchWeather, 30 * 60 * 1000);
    return () => { controller.abort(); clearInterval(interval); };
  }, [settings.showWeatherWidget, settings.weatherLocation]);

  // Don't render if weather widget is disabled
  if (settings.showWeatherWidget === false) {
    return null;
  }

  if (loading) {
    return (
      <div className={`flex items-center justify-center p-4 ${className}`}>
        <Loader2 className="w-6 h-6 animate-spin text-primary-500" />
      </div>
    );
  }

  if (error || !weather) {
    return null; // Silently fail - don't show error to users
  }

  // Compact variant - for header/navbar
  if (variant === 'header') {
    return (
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className={`flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/10 backdrop-blur-sm ${className}`}
      >
        {getWeatherIcon(weather.condition, 'w-5 h-5')}
        <span className="text-sm font-medium">{Math.round(weather.temperature)}°C</span>
      </motion.div>
    );
  }

  // Compact variant - small card
  if (variant === 'compact') {
    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className={`bg-white/80 dark:bg-slate-800/80 backdrop-blur-lg rounded-2xl p-4 shadow-lg border border-white/20 ${className}`}
      >
        <div className="flex items-center gap-4">
          <div className="flex-shrink-0">
            {getWeatherIcon(weather.condition, 'w-12 h-12')}
          </div>
          <div>
            <div className="text-3xl font-bold text-slate-900 dark:text-white">
              {Math.round(weather.temperature)}°C
            </div>
            <div className="text-sm text-slate-600 dark:text-slate-400">
              {weather.condition}
            </div>
            <div className="text-xs text-slate-500 dark:text-slate-500 mt-1">
              {weather.location}
            </div>
          </div>
        </div>
      </motion.div>
    );
  }

  // Full variant - detailed weather card
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
