'use client';

import { useState, useEffect } from 'react';
import { inventoryApi } from '@/lib/api';
import { toast } from 'sonner';
import { Search, Plus, Trash2, Save, RefreshCw, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Card, CardContent } from '@/components/ui/Card';

interface Ingredient {
    inventory_item_id: string;
    quantity_required: number;
    unit: string;
    is_optional: boolean;
    inventory_item?: {
        name: string;
        sku: string;
        unit: string;
        current_stock: number;
    };
}

interface InventoryItem {
    id: string;
    name: string;
    sku: string;
    unit: string;
    current_stock: number;
}

interface RecipeEditorProps {
    menuItemId: string;
    onSave?: () => void;
    isSession?: boolean;
}

export function RecipeEditor({ menuItemId, onSave, isSession = false }: RecipeEditorProps) {
    const [ingredients, setIngredients] = useState<Ingredient[]>([]);
    const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [showItemSelector, setShowItemSelector] = useState(false);

    useEffect(() => {
        fetchData();
    }, [menuItemId]);

    const fetchData = async () => {
        try {
            setLoading(true);
            const [recipeRes, invRes] = await Promise.all([
                isSession ? inventoryApi.getSessionRecipe(menuItemId) : inventoryApi.getRecipe(menuItemId),
                inventoryApi.getItems()
            ]);
            setIngredients(recipeRes.data.data || []);
            setInventoryItems(invRes.data.data || []);
        } catch (error) {
            toast.error('Failed to fetch recipe data');
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleAddIngredient = (item: InventoryItem) => {
        if (ingredients.some(ing => ing.inventory_item_id === item.id)) {
            toast.error('Item already in recipe');
            return;
        }

        const newIngredient: Ingredient = {
            inventory_item_id: item.id,
            quantity_required: 1,
            unit: item.unit || 'unit',
            is_optional: false,
            inventory_item: {
                name: item.name,
                sku: item.sku,
                unit: item.unit,
                current_stock: item.current_stock
            }
        };

        setIngredients([...ingredients, newIngredient]);
        setShowItemSelector(false);
    };

    const handleRemoveIngredient = (index: number) => {
        const newIngredients = [...ingredients];
        newIngredients.splice(index, 1);
        setIngredients(newIngredients);
    };

    const handleUpdateIngredient = (index: number, updates: Partial<Ingredient>) => {
        const newIngredients = [...ingredients];
        newIngredients[index] = { ...newIngredients[index], ...updates };
        setIngredients(newIngredients);
    };

    const handleSave = async () => {
        try {
            setSaving(true);
            const payload = ingredients.map(ing => ({
                inventoryItemId: ing.inventory_item_id,
                quantityRequired: Number(ing.quantity_required),
                unit: ing.unit,
                isOptional: ing.is_optional
            }));

            if (isSession) {
                await inventoryApi.updateSessionRecipe(menuItemId, payload);
            } else {
                await inventoryApi.updateRecipe(menuItemId, payload);
            }
            toast.success(isSession ? 'Consumables updated successfully' : 'Recipe updated successfully');
            if (onSave) onSave();
        } catch (error) {
            toast.error('Failed to save recipe');
            console.error(error);
        } finally {
            setSaving(false);
        }
    };

    const filteredInventory = inventoryItems.filter(item =>
        item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.sku.toLowerCase().includes(searchQuery.toLowerCase())
    );

    if (loading) {
        return (
            <div className="flex items-center justify-center p-8">
                <RefreshCw className="w-8 h-8 animate-spin text-orange-600" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h4 className="font-semibold text-slate-900 dark:text-white">
                        {isSession ? 'Consumables & Ingredients' : 'Ingredients & Recipe'}
                    </h4>
                    <p className="text-sm text-slate-500">
                        {isSession
                            ? 'Define what items are consumed per guest when booking this session'
                            : 'Define what ingredients are consumed when this item is ordered'}
                    </p>
                </div>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setShowItemSelector(!showItemSelector)}
                    className="gap-2"
                >
                    <Plus className="w-4 h-4" />
                    Add Ingredient
                </Button>
            </div>

            {showItemSelector && (
                <Card className="border-orange-200 bg-orange-50/30 dark:bg-orange-900/10 mb-4">
                    <CardContent className="p-4 space-y-4">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            <Input
                                placeholder="Search inventory items..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="pl-9"
                                autoFocus
                            />
                        </div>
                        <div className="max-h-60 overflow-y-auto space-y-1">
                            {filteredInventory.length === 0 ? (
                                <p className="text-center py-4 text-sm text-slate-500">No items found</p>
                            ) : (
                                filteredInventory.map(item => (
                                    <button
                                        key={item.id}
                                        onClick={() => handleAddIngredient(item)}
                                        className="w-full flex items-center justify-between p-2 hover:bg-white dark:hover:bg-slate-800 rounded-lg text-sm transition-colors text-left"
                                    >
                                        <div>
                                            <span className="font-medium">{item.name}</span>
                                            <span className="ml-2 text-xs text-slate-500">({item.sku})</span>
                                        </div>
                                        <div className="text-xs text-slate-400">
                                            Stock: {item.current_stock} {item.unit}
                                        </div>
                                    </button>
                                ))
                            )}
                        </div>
                    </CardContent>
                </Card>
            )}

            <div className="space-y-3">
                {ingredients.length === 0 ? (
                    <div className="text-center py-12 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-800">
                        <AlertCircle className="w-8 h-8 mx-auto mb-3 text-slate-300" />
                        <p className="text-slate-500">No ingredients defined for this item</p>
                        <p className="text-xs text-slate-400 mt-1">Add ingredients to enable automatic stock deduction</p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        <div className="grid grid-cols-12 gap-4 px-2 text-xs font-medium text-slate-500 uppercase tracking-wider">
                            <div className="col-span-6">Ingredient</div>
                            <div className="col-span-3">Quantity</div>
                            <div className="col-span-2">Unit</div>
                            <div className="col-span-1"></div>
                        </div>
                        {ingredients.map((ing, index) => (
                            <div key={ing.inventory_item_id} className="grid grid-cols-12 gap-4 items-center bg-white dark:bg-slate-800 p-2 rounded-xl border border-slate-200 dark:border-slate-700">
                                <div className="col-span-6">
                                    <p className="font-medium text-sm">{ing.inventory_item?.name}</p>
                                    <p className="text-[10px] text-slate-500 uppercase">{ing.inventory_item?.sku}</p>
                                </div>
                                <div className="col-span-3">
                                    <Input
                                        type="number"
                                        step="0.001"
                                        value={ing.quantity_required.toString()}
                                        onChange={(e) => {
                                            const val = e.target.value === '' ? 0 : parseFloat(e.target.value);
                                            handleUpdateIngredient(index, { quantity_required: val });
                                        }}
                                        className="h-8"
                                    />
                                </div>
                                <div className="col-span-2">
                                    <select
                                        value={ing.unit}
                                        onChange={(e) => handleUpdateIngredient(index, { unit: e.target.value })}
                                        className="w-full text-xs h-8 bg-transparent border border-slate-200 dark:border-slate-700 rounded-md"
                                    >
                                        <option value="kg">kg</option>
                                        <option value="g">g</option>
                                        <option value="l">l</option>
                                        <option value="ml">ml</option>
                                        <option value="unit">unit</option>
                                        <option value="box">box</option>
                                    </select>
                                </div>
                                <div className="col-span-1 flex justify-end">
                                    <button
                                        onClick={() => handleRemoveIngredient(index)}
                                        className="p-1.5 text-slate-400 hover:text-red-500 transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="flex justify-end pt-4">
                <Button
                    onClick={handleSave}
                    disabled={saving}
                    className="bg-orange-600 hover:bg-orange-700 text-white gap-2"
                >
                    {saving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Recipe
                </Button>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { useAuth } from '@/lib/auth-context';
import { useTranslations } from 'next-intl';
import { format } from 'date-fns';
import { Search, Filter, MoreVertical, Edit2, Trash2, Shield, Circle, User } from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { toast } from 'sonner';
import { useRouter } from 'next/navigation';

interface User {
  id: string;
  email: string;
  full_name: string;
  created_at: string;
  is_active: boolean;
  is_online?: boolean; // From backend
  roles: string[];
}

interface UserListProps {
  type: 'customer' | 'staff' | 'admin';
  title: string;
}

export default function UserList({ type, title }: UserListProps) {
  const t = useTranslations('adminUsers');
  const tCommon = useTranslations('adminCommon');
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const router = useRouter();
  const { user: currentUser } = useAuth();
  
  // Refresh interval for online status
  useEffect(() => {
    fetchUsers();
    const interval = setInterval(fetchUsers, 10000); // Poll every 10s for presence
    return () => clearInterval(interval);
  }, [type, search]);

  const fetchUsers = async () => {
    try {
      // Assuming GET /admin/users supports ?type=... and ?search=...
      const res = await api.get(`/admin/users?type=${type}&search=${search}`);
      // Backend returns { success: true, data: [...] }
      const payload = res.data?.data ?? res.data ?? [];
      setUsers(Array.isArray(payload) ? payload : []);
    } catch (error) {
      console.error('Failed to fetch users', error);
      // Don't toast on polling error to avoid spam
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (userId: string) => {
    if (!confirm(tCommon('confirmDelete'))) return;
    try {
      await api.delete(`/admin/users/${userId}`);
      toast.success(t('userDeleted'));
      fetchUsers();
    } catch (error) {
      toast.error(t('errors.failedToDelete'));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">{title}</h1>
          <p className="text-muted-foreground">
            {t('subtitle')}
          </p>
        </div>
        {/* Only show 'Create' button for staff/admin if needed, or all types */}
        <Button onClick={() => router.push(`/admin/users/create?type=${type}`)}>
          + {t('addUser')}
        </Button>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4">
            <div className="relative flex-1 max-w-sm">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
              <input
                type="text"
                placeholder={tCommon('searchPlaceholder')}
                className="flex h-9 w-full rounded-md border border-input bg-background px-3 py-1 pl-8 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            {/* Additional filters could go here */}
          </div>
        </CardHeader>
        <CardContent>
          <div className="rounded-md border">
            <table className="w-full text-sm text-left">
              <thead className="bg-muted/50 text-muted-foreground">
                <tr>
                  <th className="h-10 px-4 font-medium align-middle">{tCommon('tables.name')}</th>
                  <th className="h-10 px-4 font-medium align-middle">{tCommon('status')}</th>
                  <th className="h-10 px-4 font-medium align-middle">{t('roles')}</th>
                  <th className="h-10 px-4 font-medium align-middle">{t('joined')}</th>
                  <th className="h-10 px-4 font-medium align-middle text-right">{tCommon('actions')}</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                   <tr><td colSpan={5} className="p-4 text-center">{tCommon('loading')}</td></tr>
                ) : users.length === 0 ? (
                   <tr><td colSpan={5} className="p-4 text-center text-muted-foreground">{tCommon('noResults')}</td></tr>
                ) : (
                  users.map((user) => (
                    <tr 
                      key={user.id} 
                      className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted cursor-pointer"
                      onClick={() => router.push(`/admin/users/${user.id}`)}
                    >
                      <td className="p-4">
                        <div className="flex items-center gap-3">
                            <div className="h-9 w-9 rounded-full bg-primary/10 flex items-center justify-center text-primary font-medium">
                                {user.full_name?.[0] || <User size={16} />}
                            </div>
                            <div>
                                <div className="font-medium">{user.full_name}</div>
                                <div className="text-xs text-muted-foreground">{user.email}</div>
                            </div>
                        </div>
                      </td>
                      <td className="p-4">
                        <div className="flex items-center gap-2">
                           {user.is_online ? (
                               <span className="inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors border-transparent bg-green-500/15 text-green-700">
                                   <Circle className="w-2 h-2 mr-1 fill-current" />
                                   {t('online')}
                               </span>
                           ) : (
                               <span className="text-muted-foreground text-xs pl-2">{t('offline')}</span>
                           )}
                           {!user.is_active && (
                               <span className="inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors border-transparent bg-destructive/15 text-destructive">
                                   {tCommon('inactive')}
                               </span>
                           )}
                        </div>
                      </td>
                      <td className="p-4">
                         <div className="flex flex-wrap gap-1">
                            {user.roles && user.roles.length > 0 ? (
                                user.roles.map(r => (
                                    <span key={r} className="inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-semibold transition-colors border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80">
                                        {r}
                                    </span>
                                ))
                            ) : (
                                <span className="text-muted-foreground text-xs">-</span>
                            )}
                         </div>
                      </td>
                      <td className="p-4 text-muted-foreground">
                        {format(new Date(user.created_at), 'MMM d, yyyy')}
                      </td>
                      <td className="p-4 text-right">
                        <div className="flex justify-end gap-2" onClick={(e) => e.stopPropagation()}>
                          <Button variant="ghost" size="sm" onClick={() => router.push(`/admin/users/${user.id}`)}>
                            <Edit2 className="h-4 w-4" />
                          </Button>
                          <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => handleDelete(user.id)}>
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Calendar } from 'lucide-react';

interface DailyPriceInfo {
  price: number;
  type: 'weekday' | 'weekend' | 'holiday' | 'seasonal';
  ruleName?: string;
  isBlocked: boolean;
}

interface AvailabilityCalendarProps {
  blockedDates?: string[];
  selectedCheckIn?: string;
  selectedCheckOut?: string;
  onDateSelect: (checkIn: string, checkOut: string | null) => void;
  minDate?: Date;
  maxMonthsAhead?: number;
  weekendHighlight?: boolean;
  pricePerNight?: { weekday: number; weekend: number };
  dailyPrices?: Record<string, DailyPriceInfo>;
  currency?: string;
  formatPrice?: (amount: number) => string;
}

interface CalendarDay {
  date: Date;
  dayOfMonth: number;
  isCurrentMonth: boolean;
  isBlocked: boolean;
  isSelected: boolean;
  isInRange: boolean;
  isCheckIn: boolean;
  isCheckOut: boolean;
  isToday: boolean;
  isPast: boolean;
  isWeekend: boolean;
}

function formatDateString(date: Date): string {
  return date.toISOString().split('T')[0];
}

function isSameDay(date1: Date, date2: Date): boolean {
  return formatDateString(date1) === formatDateString(date2);
}

function isDateBetween(date: Date, start: Date, end: Date): boolean {
  const d = date.getTime();
  return d > start.getTime() && d < end.getTime();
}

export default function AvailabilityCalendar({
  blockedDates = [],
  selectedCheckIn,
  selectedCheckOut,
  onDateSelect,
  minDate = new Date(),
  maxMonthsAhead = 12,
  weekendHighlight = true,
  pricePerNight,
  dailyPrices,
  currency = 'USD',
  formatPrice,
}: AvailabilityCalendarProps) {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectingCheckOut, setSelectingCheckOut] = useState(false);
  const [hoverDate, setHoverDate] = useState<Date | null>(null);

  const blockedDateSet = useMemo(() => new Set(blockedDates), [blockedDates]);

  const today = useMemo(() => {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  }, []);

  const checkInDate = useMemo(
    () => (selectedCheckIn ? new Date(selectedCheckIn) : null),
    [selectedCheckIn]
  );

  const checkOutDate = useMemo(
    () => (selectedCheckOut ? new Date(selectedCheckOut) : null),
    [selectedCheckOut]
  );

  // Generate calendar days for current month view
  const calendarDays = useMemo(() => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const daysInMonth = lastDay.getDate();
    const startingDayOfWeek = firstDay.getDay();

    const days: CalendarDay[] = [];

    // Add days from previous month
    const prevMonthLastDay = new Date(year, month, 0).getDate();
    for (let i = startingDayOfWeek - 1; i >= 0; i--) {
      const date = new Date(year, month - 1, prevMonthLastDay - i);
      days.push(createDayObject(date, false));
    }

    // Add days of current month
    for (let i = 1; i <= daysInMonth; i++) {
      const date = new Date(year, month, i);
      days.push(createDayObject(date, true));
    }

    // Add days from next month to complete the grid
    const remainingDays = 42 - days.length; // 6 rows x 7 days
    for (let i = 1; i <= remainingDays; i++) {
      const date = new Date(year, month + 1, i);
      days.push(createDayObject(date, false));
    }

    return days;
  }, [currentMonth, blockedDateSet, checkInDate, checkOutDate, hoverDate, today]);

  function createDayObject(date: Date, isCurrentMonth: boolean): CalendarDay {
    const dateStr = formatDateString(date);
    const dayOfWeek = date.getDay();
    const isWeekend = dayOfWeek === 5 || dayOfWeek === 6;
    const isPast = date < today;
    const isBlocked = blockedDateSet.has(dateStr) || isPast;

    let isSelected = false;
    let isInRange = false;
    let isCheckIn = false;
    let isCheckOut = false;

    if (checkInDate && isSameDay(date, checkInDate)) {
      isCheckIn = true;
      isSelected = true;
    }

    if (checkOutDate && isSameDay(date, checkOutDate)) {
      isCheckOut = true;
      isSelected = true;
    }

    if (checkInDate && checkOutDate && isDateBetween(date, checkInDate, checkOutDate)) {
      isInRange = true;
    }

    // Hover preview when selecting check-out
    if (selectingCheckOut && checkInDate && hoverDate && !checkOutDate) {
      if (isDateBetween(date, checkInDate, hoverDate)) {
        isInRange = true;
      }
      if (isSameDay(date, hoverDate)) {
        isCheckOut = true;
      }
    }

    return {
      date,
      dayOfMonth: date.getDate(),
      isCurrentMonth,
      isBlocked,
      isSelected,
      isInRange,
      isCheckIn,
      isCheckOut,
      isToday: isSameDay(date, today),
      isPast,
      isWeekend,
    };
  }

  const handleDayClick = (day: CalendarDay) => {
    if (day.isBlocked) return;

    const dateStr = formatDateString(day.date);

    if (!selectingCheckOut || !checkInDate) {
      // Selecting check-in date
      onDateSelect(dateStr, null);
      setSelectingCheckOut(true);
    } else {
      // Selecting check-out date
      if (day.date <= checkInDate) {
        // If clicked date is before check-in, make it the new check-in
        onDateSelect(dateStr, null);
      } else {
        // Check if any blocked dates are in between
        const hasBlockedInRange = blockedDates.some(blocked => {
          const blockedDate = new Date(blocked);
          return isDateBetween(blockedDate, checkInDate, day.date);
        });

        if (hasBlockedInRange) {
          // Reset and start over with new check-in
          onDateSelect(dateStr, null);
        } else {
          // Valid check-out selection
          onDateSelect(selectedCheckIn!, dateStr);
          setSelectingCheckOut(false);
        }
      }
    }
  };

  const navigateMonth = (delta: number) => {
    setCurrentMonth(prev => {
      const newDate = new Date(prev);
      newDate.setMonth(newDate.getMonth() + delta);
      return newDate;
    });
  };

  const canGoBack = currentMonth > minDate;
  const maxDate = new Date();
  maxDate.setMonth(maxDate.getMonth() + maxMonthsAhead);
  const canGoForward = currentMonth < maxDate;

  const monthYearString = currentMonth.toLocaleDateString('en-US', {
    month: 'long',
    year: 'numeric',
  });

  const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  return (
    <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <button
          onClick={() => navigateMonth(-1)}
          disabled={!canGoBack}
          className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          aria-label="Previous month"
        >
          <ChevronLeft className="w-5 h-5" />
        </button>
        <h3 className="text-lg font-semibold text-slate-900 dark:text-white">
          {monthYearString}
        </h3>
        <button
          onClick={() => navigateMonth(1)}
          disabled={!canGoForward}
          className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
          aria-label="Next month"
        >
          <ChevronRight className="w-5 h-5" />
        </button>
      </div>

      {/* Selection Status */}
      <div className="flex items-center justify-center gap-4 mb-4 text-sm">
        <div className="flex items-center gap-2">
          <Calendar className="w-4 h-4 text-green-600" />
          <span className="text-slate-600 dark:text-slate-400">
            {selectingCheckOut && checkInDate ? 'Select check-out' : 'Select check-in'}
          </span>
        </div>
      </div>

      {/* Weekday Headers */}
      <div className="grid grid-cols-7 gap-1 mb-2">
        {weekDays.map(day => (
          <div
            key={day}
            className="text-center text-xs font-medium text-slate-500 dark:text-slate-400 py-2"
          >
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid */}
      <div className="grid grid-cols-7 gap-1">
        {calendarDays.map((day, index) => {
          const dateStr = formatDateString(day.date);
          const dayPrice = dailyPrices?.[dateStr];
          const hasDailyPrice = dayPrice && !dayPrice.isBlocked;

          const dayClasses = [
            'relative flex flex-col items-center justify-center rounded-lg text-sm transition-all',
            hasDailyPrice ? 'h-16' : 'h-12',
          ];

          if (!day.isCurrentMonth) {
            dayClasses.push('text-slate-300 dark:text-slate-600');
          } else if (day.isBlocked || dayPrice?.isBlocked) {
            dayClasses.push('text-slate-300 dark:text-slate-600 line-through cursor-not-allowed');
          } else if (day.isCheckIn) {
            dayClasses.push('bg-green-600 text-white rounded-r-none');
          } else if (day.isCheckOut) {
            dayClasses.push('bg-green-600 text-white rounded-l-none');
          } else if (day.isInRange) {
            dayClasses.push('bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-200 rounded-none');
          } else if (day.isToday) {
            dayClasses.push('border-2 border-green-500 font-bold text-green-600 cursor-pointer hover:bg-green-50 dark:hover:bg-green-900/20');
          } else if (hasDailyPrice) {
            // Color-code by price type
            const typeColors: Record<string, string> = {
              weekday: 'text-slate-700 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700',
              weekend: 'text-amber-600 dark:text-amber-400 cursor-pointer hover:bg-amber-50 dark:hover:bg-amber-900/20',
              holiday: 'text-red-600 dark:text-red-400 cursor-pointer hover:bg-red-50 dark:hover:bg-red-900/20',
              seasonal: 'text-purple-600 dark:text-purple-400 cursor-pointer hover:bg-purple-50 dark:hover:bg-purple-900/20',
            };
            dayClasses.push(typeColors[dayPrice.type] || typeColors.weekday);
          } else if (day.isWeekend && weekendHighlight) {
            dayClasses.push('text-amber-600 dark:text-amber-400 cursor-pointer hover:bg-amber-50 dark:hover:bg-amber-900/20');
          } else {
            dayClasses.push('text-slate-700 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700');
          }

          // Price display helper
          const renderPrice = () => {
            if (day.isBlocked || !day.isCurrentMonth) return null;
            
            if (hasDailyPrice) {
              const priceText = formatPrice
                ? formatPrice(dayPrice.price)
                : `$${dayPrice.price}`;
              const priceColorClass = day.isSelected || day.isCheckIn || day.isCheckOut
                ? 'text-white/80'
                : day.isInRange
                ? 'text-green-600 dark:text-green-400'
                : {
                    weekday: 'text-slate-500 dark:text-slate-400',
                    weekend: 'text-amber-500 dark:text-amber-400',
                    holiday: 'text-red-500 dark:text-red-400',
                    seasonal: 'text-purple-500 dark:text-purple-400',
                  }[dayPrice.type] || 'text-slate-500';
              return (
                <span className={`text-[9px] font-medium leading-tight ${priceColorClass}`}>
                  {priceText}
                </span>
              );
            }
            
            if (pricePerNight) {
              return (
                <span className="text-[10px] text-slate-400 dark:text-slate-500">
                  ${day.isWeekend ? pricePerNight.weekend : pricePerNight.weekday}
                </span>
              );
            }
            
            return null;
          };

          return (
            <button
              key={index}
              onClick={() => handleDayClick(day)}
              onMouseEnter={() => setHoverDate(day.date)}
              onMouseLeave={() => setHoverDate(null)}
              disabled={day.isBlocked || dayPrice?.isBlocked || !day.isCurrentMonth}
              className={dayClasses.join(' ')}
              title={dayPrice?.ruleName ? `${dayPrice.ruleName}` : undefined}
            >
              <span>{day.dayOfMonth}</span>
              {renderPrice()}
            </button>
          );
        })}
      </div>

      {/* Legend */}
      <div className="flex flex-wrap items-center justify-center gap-3 mt-6 pt-4 border-t border-slate-200 dark:border-slate-700 text-xs">
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 bg-green-600 rounded"></div>
          <span className="text-slate-600 dark:text-slate-400">Selected</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 bg-green-100 dark:bg-green-900/30 rounded"></div>
          <span className="text-slate-600 dark:text-slate-400">Your stay</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 bg-slate-200 dark:bg-slate-700 rounded line-through"></div>
          <span className="text-slate-600 dark:text-slate-400">Unavailable</span>
        </div>
        {weekendHighlight && (
          <div className="flex items-center gap-1.5">
            <div className="w-3 h-3 border-2 border-amber-400 rounded"></div>
            <span className="text-slate-600 dark:text-slate-400">Weekend</span>
          </div>
        )}
        {dailyPrices && (
          <>
            <div className="flex items-center gap-1.5">
              <div className="w-3 h-3 border-2 border-purple-400 rounded"></div>
              <span className="text-slate-600 dark:text-slate-400">Seasonal</span>
            </div>
            <div className="flex items-center gap-1.5">
              <div className="w-3 h-3 border-2 border-red-400 rounded"></div>
              <span className="text-slate-600 dark:text-slate-400">Holiday</span>
            </div>
          </>
        )}
      </div>

      {/* Date Summary */}
      {(checkInDate || checkOutDate) && (
        <div className="mt-4 p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">
          <div className="grid grid-cols-2 gap-4 text-center">
            <div>
              <p className="text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wide">Check-in</p>
              <p className="font-semibold text-slate-900 dark:text-white">
                {checkInDate ? checkInDate.toLocaleDateString('en-US', { 
                  weekday: 'short', 
                  month: 'short', 
                  day: 'numeric' 
                }) : '—'}
              </p>
            </div>
            <div>
              <p className="text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wide">Check-out</p>
              <p className="font-semibold text-slate-900 dark:text-white">
                {checkOutDate ? checkOutDate.toLocaleDateString('en-US', { 
                  weekday: 'short', 
                  month: 'short', 
                  day: 'numeric' 
                }) : '—'}
              </p>
            </div>
          </div>
          {checkInDate && checkOutDate && (
            <div className="mt-3 pt-3 border-t border-slate-200 dark:border-slate-600 text-center">
              <p className="text-sm text-slate-600 dark:text-slate-400">
                {Math.ceil((checkOutDate.getTime() - checkInDate.getTime()) / (1000 * 60 * 60 * 24))} nights
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

