'use client';

import React from 'react';
import Script from 'next/script';
import { generateLocalBusinessSchema } from '@/lib/structured-data-generator';
import { useTerminology } from '@/hooks/useTerminology';

interface StructuredDataProps {
    businessName: string;
    businessType: string;
    config: any;
}

export function StructuredData({ businessName, businessType, config }: StructuredDataProps) {
    const { terms } = useTerminology();

    const schema = generateLocalBusinessSchema(
        businessName,
        businessType,
        config,
        terms
    );

    return (
        <Script
            id="structured-data"
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }}
        />
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { formatCurrency } from '@/lib/utils';
import { toast } from 'sonner';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { 
  Ticket, 
  Check, 
  X, 
  Loader2, 
  Tag, 
  Percent, 
  DollarSign,
  AlertCircle,
  Trash2 
} from 'lucide-react';
import { debounce } from 'lodash';

interface AppliedCoupon {
  code: string;
  discountType: 'percentage' | 'fixed';
  discountValue: number;
  discountAmount: number;
  minimumOrderAmount?: number;
  maxDiscount?: number;
  description?: string;
}

interface CouponInputProps {
  orderTotal: number;
  orderType?: string;
  moduleId?: string;
  onCouponApply?: (coupon: AppliedCoupon | null) => void;
  onDiscountChange?: (discountAmount: number) => void;
  className?: string;
  appliedCoupon?: AppliedCoupon | null;
}

export function CouponInput({
  orderTotal,
  orderType = 'general',
  moduleId,
  onCouponApply,
  onDiscountChange,
  className = '',
  appliedCoupon: externalAppliedCoupon,
}: CouponInputProps) {
  const [code, setCode] = useState('');
  const [validating, setValidating] = useState(false);
  const [appliedCoupon, setAppliedCoupon] = useState<AppliedCoupon | null>(externalAppliedCoupon || null);
  const [error, setError] = useState('');
  const [suggestion, setSuggestion] = useState('');

  // Sync with external applied coupon if provided
  useEffect(() => {
    if (externalAppliedCoupon !== undefined) {
      setAppliedCoupon(externalAppliedCoupon);
    }
  }, [externalAppliedCoupon]);

  // Recalculate discount when order total changes
  useEffect(() => {
    if (appliedCoupon) {
      const newDiscount = appliedCoupon.discountType === 'percentage'
        ? Math.min(
            (orderTotal * appliedCoupon.discountValue) / 100,
            appliedCoupon.maxDiscount || Infinity
          )
        : appliedCoupon.discountValue;
      
      const updatedCoupon = { ...appliedCoupon, discountAmount: newDiscount };
      setAppliedCoupon(updatedCoupon);
      onDiscountChange?.(newDiscount);
    }
  }, [orderTotal]);

  const validateCoupon = async () => {
    if (!code.trim()) return;
    
    setValidating(true);
    setError('');
    
    try {
      // Map moduleId to the backend's expected orderType values
      // Backend expects: 'restaurant', 'chalets', 'pool', 'snack'
      const backendOrderType = moduleId || orderType || 'restaurant';
      
      const res = await api.post('/coupons/validate', {
        code: code.trim().toUpperCase(),
        orderAmount: orderTotal, // Backend expects orderAmount, not orderTotal
        orderType: backendOrderType,
      });

      if (res.data.success) {
        const couponData = res.data.data;
        const newCoupon: AppliedCoupon = {
          code: couponData.code,
          discountType: couponData.discountType,
          discountValue: couponData.discountValue,
          discountAmount: couponData.discountAmount,
          minimumOrderAmount: couponData.minimumOrderAmount,
          maxDiscount: couponData.maxDiscount,
          description: couponData.description,
        };
        
        setAppliedCoupon(newCoupon);
        onCouponApply?.(newCoupon);
        onDiscountChange?.(newCoupon.discountAmount);
        setCode('');
        toast.success(`Coupon applied! You save ${formatCurrency(newCoupon.discountAmount)}`);
      }
    } catch (err: any) {
      const errorMessage = err.response?.data?.error || 'Invalid coupon code';
      setError(errorMessage);
      
      // Check for suggestions
      if (err.response?.data?.suggestion) {
        setSuggestion(err.response.data.suggestion);
      }
    } finally {
      setValidating(false);
    }
  };

  const removeCoupon = () => {
    setAppliedCoupon(null);
    onCouponApply?.(null);
    onDiscountChange?.(0);
    setError('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      validateCoupon();
    }
  };

  // Applied coupon display
  if (appliedCoupon) {
    return (
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className={`border border-green-200 dark:border-green-800 bg-green-50 dark:bg-green-900/20 rounded-lg p-4 ${className}`}
      >
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-3">
            <div className="w-10 h-10 rounded-full bg-green-100 dark:bg-green-800 flex items-center justify-center">
              <Check className="w-5 h-5 text-green-600 dark:text-green-400" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="font-mono font-bold text-green-700 dark:text-green-300">
                  {appliedCoupon.code}
                </span>
                {appliedCoupon.discountType === 'percentage' ? (
                  <span className="text-xs bg-green-200 dark:bg-green-700 text-green-800 dark:text-green-200 px-2 py-0.5 rounded">
                    {appliedCoupon.discountValue}% OFF
                  </span>
                ) : (
                  <span className="text-xs bg-green-200 dark:bg-green-700 text-green-800 dark:text-green-200 px-2 py-0.5 rounded">
                    {formatCurrency(appliedCoupon.discountValue)} OFF
                  </span>
                )}
              </div>
              {appliedCoupon.description && (
                <p className="text-sm text-green-600 dark:text-green-400 mt-1">
                  {appliedCoupon.description}
                </p>
              )}
              <p className="text-lg font-bold text-green-700 dark:text-green-300 mt-1">
                You save {formatCurrency(appliedCoupon.discountAmount)}
              </p>
            </div>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={removeCoupon}
            className="text-green-600 hover:text-red-600 hover:bg-red-50"
          >
            <Trash2 className="w-4 h-4" />
          </Button>
        </div>
      </motion.div>
    );
  }

  // Input form
  return (
    <div className={className}>
      <div className="flex gap-2">
        <div className="relative flex-1">
          <Ticket className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
          <Input
            placeholder="Enter coupon code"
            value={code}
            onChange={(e) => { 
              setCode(e.target.value.toUpperCase()); 
              setError(''); 
              setSuggestion('');
            }}
            onKeyDown={handleKeyDown}
            className="pl-10 font-mono uppercase"
            disabled={validating}
          />
        </div>
        <Button
          onClick={validateCoupon}
          disabled={validating || !code.trim()}
          variant="outline"
        >
          {validating ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            'Apply'
          )}
        </Button>
      </div>

      <AnimatePresence>
        {error && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="flex items-center gap-2 text-red-500 text-sm mt-2"
          >
            <AlertCircle className="w-4 h-4" />
            <span>{error}</span>
          </motion.div>
        )}

        {suggestion && (
          <motion.button
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            onClick={() => { setCode(suggestion); setSuggestion(''); }}
            className="text-sm text-blue-500 hover:underline mt-1"
          >
            Did you mean: {suggestion}?
          </motion.button>
        )}
      </AnimatePresence>
    </div>
  );
}

// Available Coupons Display (for showing on checkout page)
interface AvailableCoupon {
  code: string;
  description?: string;
  discountType: 'percentage' | 'fixed';
  discountValue: number;
  minimumOrderAmount?: number;
  expiresAt?: string;
}

interface AvailableCouponsProps {
  orderType?: string;
  moduleId?: string;
  onSelect?: (code: string) => void;
  className?: string;
}

export function AvailableCoupons({ 
  orderType, 
  moduleId, 
  onSelect,
  className = '' 
}: AvailableCouponsProps) {
  const [coupons, setCoupons] = useState<AvailableCoupon[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCoupons();
  }, [orderType, moduleId]);

  const loadCoupons = async () => {
    try {
      const params: Record<string, string> = {};
      if (orderType) params.orderType = orderType;
      if (moduleId) params.moduleId = moduleId;
      
      const res = await api.get('/coupons/active', { params });
      if (res.data.success) {
        setCoupons(res.data.data.slice(0, 4)); // Show max 4
      }
    } catch {
      // Silent fail - coupons are optional
    } finally {
      setLoading(false);
    }
  };

  if (loading || coupons.length === 0) return null;

  return (
    <div className={className}>
      <p className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">
        Available Coupons
      </p>
      <div className="grid gap-2">
        {coupons.map((coupon) => (
          <motion.button
            key={coupon.code}
            onClick={() => onSelect?.(coupon.code)}
            className="flex items-center justify-between p-3 border rounded-lg hover:border-purple-300 hover:bg-purple-50 dark:hover:bg-purple-900/20 transition-colors text-left"
            whileHover={{ scale: 1.01 }}
            whileTap={{ scale: 0.99 }}
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-purple-100 dark:bg-purple-800 flex items-center justify-center">
                {coupon.discountType === 'percentage' ? (
                  <Percent className="w-5 h-5 text-purple-600 dark:text-purple-400" />
                ) : (
                  <DollarSign className="w-5 h-5 text-purple-600 dark:text-purple-400" />
                )}
              </div>
              <div>
                <p className="font-mono font-semibold text-slate-900 dark:text-white">
                  {coupon.code}
                </p>
                <p className="text-xs text-slate-500">
                  {coupon.discountType === 'percentage' 
                    ? `${coupon.discountValue}% off`
                    : `${formatCurrency(coupon.discountValue)} off`
                  }
                  {coupon.minimumOrderAmount && ` · Min. ${formatCurrency(coupon.minimumOrderAmount)}`}
                </p>
              </div>
            </div>
            <Tag className="w-4 h-4 text-purple-500" />
          </motion.button>
        ))}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { useAuth } from '@/lib/auth-context';
import { formatCurrency } from '@/lib/utils';
import { currencySymbols } from '@/stores/settingsStore'; // FIX Iter-17: Import for currency-aware symbol
import { toast } from 'sonner';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Card, CardContent } from '@/components/ui/Card';
import { Gift, CreditCard, Check, Loader2, Mail, User, ChevronRight } from 'lucide-react';

interface GiftCardTemplate {
  id: string;
  name: string;
  amount: number;
  design: {
    background: string;
    pattern?: string;
    textColor?: string;
  };
  isActive: boolean;
}

interface GiftCardPurchaseProps {
  onSuccess?: (giftCard: any) => void;
  className?: string;
}

export function GiftCardPurchase({ onSuccess, className = '' }: GiftCardPurchaseProps) {
  const { isAuthenticated } = useAuth();
  const [templates, setTemplates] = useState<GiftCardTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedTemplate, setSelectedTemplate] = useState<GiftCardTemplate | null>(null);
  const [customAmount, setCustomAmount] = useState('');
  const [step, setStep] = useState<'select' | 'details' | 'confirm'>('select');
  const [purchasing, setPurchasing] = useState(false);
  
  const [giftDetails, setGiftDetails] = useState({
    recipientName: '',
    recipientEmail: '',
    message: '',
    senderName: '',
  });

  // FIX Iter-17: AbortController to prevent state updates on unmounted component
  useEffect(() => {
    const controller = new AbortController();
    const load = async () => {
      try {
        const res = await api.get('/giftcards/templates', { signal: controller.signal });
        if (controller.signal.aborted) return;
        if (res.data.success) {
          setTemplates(res.data.data.filter((t: GiftCardTemplate) => t.isActive));
        }
      } catch (err: any) {
        if (err?.name === 'CanceledError' || controller.signal.aborted) return;
        toast.error('Failed to load gift card options');
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    };
    load();
    return () => controller.abort();
  }, []);

  const handleSelectAmount = (template: GiftCardTemplate | null, amount?: number) => {
    if (template) {
      setSelectedTemplate(template);
      setCustomAmount('');
    } else if (amount) {
      setSelectedTemplate(null);
      setCustomAmount(amount.toString());
    }
    setStep('details');
  };

  const handlePurchase = async () => {
    if (!giftDetails.recipientEmail || !giftDetails.senderName) {
      toast.error('Please fill in all required fields');
      return;
    }

    const amount = selectedTemplate?.amount || parseFloat(customAmount);
    if (!amount || amount < 10) {
      toast.error(`Minimum gift card amount is ${formatCurrency(10)}`); // FIX Iter-17: Currency-aware
      return;
    }

    setPurchasing(true);
    try {
      const res = await api.post('/giftcards/purchase', {
        templateId: selectedTemplate?.id,
        customAmount: selectedTemplate ? undefined : amount,
        recipientName: giftDetails.recipientName || undefined,
        recipientEmail: giftDetails.recipientEmail,
        personalMessage: giftDetails.message || undefined,
        senderName: giftDetails.senderName,
      });

      if (res.data.success) {
        toast.success('Gift card purchased successfully!');
        onSuccess?.(res.data.data);
        // Reset form
        setStep('select');
        setSelectedTemplate(null);
        setCustomAmount('');
        setGiftDetails({
          recipientName: '',
          recipientEmail: '',
          message: '',
          senderName: '',
        });
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Failed to purchase gift card');
    } finally {
      setPurchasing(false);
    }
  };

  const currentAmount = selectedTemplate?.amount || parseFloat(customAmount) || 0;

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-purple-500" />
      </div>
    );
  }

  return (
    <div className={className}>
      <AnimatePresence mode="wait">
        {step === 'select' && (
          <motion.div
            key="select"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="space-y-6"
          >
            <div className="text-center">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white">
                Send a Gift Card
              </h2>
              <p className="text-slate-500 mt-1">
                Choose an amount or create a custom gift
              </p>
            </div>

            {/* Template Options */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {templates.map((template) => (
                <motion.button
                  key={template.id}
                  onClick={() => handleSelectAmount(template)}
                  className="relative rounded-xl overflow-hidden shadow-md hover:shadow-lg transition-all group"
                  whileHover={{ scale: 1.03 }}
                  whileTap={{ scale: 0.98 }}
                >
                  <div 
                    className="aspect-[3/2] p-4 flex flex-col items-center justify-center"
                    style={{ 
                      background: template.design.background || 'linear-gradient(135deg, #7c3aed, #a855f7)',
                      color: template.design.textColor || 'white'
                    }}
                  >
                    <Gift className="w-8 h-8 mb-2 opacity-80" />
                    <p className="text-2xl font-bold">{formatCurrency(template.amount)}</p>
                    <p className="text-sm opacity-80">{template.name}</p>
                  </div>
                  <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                </motion.button>
              ))}
            </div>

            {/* Custom Amount */}
            <div className="border-t dark:border-slate-700 pt-6">
              <p className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">
                Or enter a custom amount
              </p>
              <div className="flex gap-3">
                <div className="relative flex-1">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">{currencySymbols.USD}</span>
                  <Input
                    type="number"
                    placeholder="50"
                    min="10"
                    max="1000"
                    value={customAmount}
                    onChange={(e) => setCustomAmount(e.target.value)}
                    className="pl-8"
                  />
                </div>
                <Button
                  onClick={() => handleSelectAmount(null, parseFloat(customAmount))}
                  disabled={!customAmount || parseFloat(customAmount) < 10}
                >
                  Continue
                  <ChevronRight className="w-4 h-4 ml-1" />
                </Button>
              </div>
              <p className="text-xs text-slate-500 mt-2">Minimum {formatCurrency(10)}, Maximum {formatCurrency(1000)}</p>
            </div>
          </motion.div>
        )}

        {step === 'details' && (
          <motion.div
            key="details"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="space-y-6"
          >
            {/* Selected Amount Preview */}
            <div 
              className="rounded-xl p-6 text-center text-white"
              style={{ 
                background: selectedTemplate?.design.background || 'linear-gradient(135deg, #7c3aed, #a855f7)'
              }}
            >
              <Gift className="w-10 h-10 mx-auto mb-2 opacity-80" />
              <p className="text-3xl font-bold">{formatCurrency(currentAmount)}</p>
              <p className="text-sm opacity-80">Gift Card</p>
            </div>

            {/* Gift Details Form */}
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">
                  Your Name *
                </label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <Input
                    placeholder="Your name (will appear on card)"
                    value={giftDetails.senderName}
                    onChange={(e) => setGiftDetails(d => ({ ...d, senderName: e.target.value }))}
                    className="pl-10"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Recipient's Name
                </label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <Input
                    placeholder="Who is this gift for?"
                    value={giftDetails.recipientName}
                    onChange={(e) => setGiftDetails(d => ({ ...d, recipientName: e.target.value }))}
                    className="pl-10"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Recipient's Email *
                </label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <Input
                    type="email"
                    placeholder="Where should we send the gift card?"
                    value={giftDetails.recipientEmail}
                    onChange={(e) => setGiftDetails(d => ({ ...d, recipientEmail: e.target.value }))}
                    className="pl-10"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Personal Message (optional)
                </label>
                <textarea
                  placeholder="Add a personal message..."
                  value={giftDetails.message}
                  onChange={(e) => setGiftDetails(d => ({ ...d, message: e.target.value }))}
                  className="w-full p-3 border rounded-lg dark:bg-slate-800 dark:border-slate-700"
                  rows={3}
                  maxLength={500}
                />
                <p className="text-xs text-slate-500 text-right">{giftDetails.message.length}/500</p>
              </div>
            </div>

            <div className="flex gap-3">
              <Button variant="outline" onClick={() => setStep('select')} className="flex-1">
                Back
              </Button>
              <Button 
                onClick={handlePurchase} 
                disabled={purchasing || !giftDetails.recipientEmail || !giftDetails.senderName}
                className="flex-1"
              >
                {purchasing ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Processing...
                  </>
                ) : (
                  <>
                    <CreditCard className="w-4 h-4 mr-2" />
                    Purchase {formatCurrency(currentAmount)}
                  </>
                )}
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// Balance Check Component
interface GiftCardBalanceProps {
  className?: string;
}

export function GiftCardBalance({ className = '' }: GiftCardBalanceProps) {
  const [code, setCode] = useState('');
  const [checking, setChecking] = useState(false);
  const [balance, setBalance] = useState<{ balance: number; expiresAt?: string } | null>(null);
  const [error, setError] = useState('');

  const handleCheck = async () => {
    if (!code.trim()) return;
    
    setChecking(true);
    setError('');
    setBalance(null);
    
    try {
      const res = await api.get(`/giftcards/check/${code.trim()}`);
      if (res.data.success) {
        setBalance(res.data.data);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || 'Gift card not found');
    } finally {
      setChecking(false);
    }
  };

  return (
    <Card className={className}>
      <CardContent className="p-6">
        <h3 className="text-lg font-semibold mb-4">Check Gift Card Balance</h3>
        
        <div className="flex gap-3">
          <Input
            placeholder="Enter gift card code"
            value={code}
            onChange={(e) => { setCode(e.target.value.toUpperCase()); setBalance(null); setError(''); }}
            className="font-mono uppercase"
          />
          <Button onClick={handleCheck} disabled={checking || !code.trim()}>
            {checking ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Check'}
          </Button>
        </div>

        {error && (
          <p className="text-red-500 text-sm mt-3">{error}</p>
        )}

        {balance && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="mt-4 p-4 bg-green-50 dark:bg-green-900/20 rounded-lg"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-green-100 dark:bg-green-800 flex items-center justify-center">
                <Check className="w-5 h-5 text-green-600 dark:text-green-400" />
              </div>
              <div>
                <p className="text-sm text-slate-600 dark:text-slate-400">Available Balance</p>
                <p className="text-2xl font-bold text-green-600 dark:text-green-400">
                  {formatCurrency(balance.balance)}
                </p>
              </div>
            </div>
            {balance.expiresAt && (
              <p className="text-xs text-slate-500 mt-2">
                Expires: {new Date(balance.expiresAt).toLocaleDateString()}
              </p>
            )}
          </motion.div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { api } from '@/lib/api';
import { useAuth } from '@/lib/auth-context';
import { formatNumber } from '@/lib/utils';
import { Award, Star, Gift, TrendingUp, ChevronRight } from 'lucide-react';
import Link from 'next/link';

interface LoyaltyAccount {
  id: string;
  currentPoints: number;
  totalPointsEarned: number;
  totalPointsRedeemed: number;
  tier: {
    id: string;
    name: string;
    pointsMultiplier: number;
    benefits: string[];
    color: string;
  };
  nextTier?: {
    name: string;
    pointsRequired: number;
    pointsNeeded: number;
  };
}

interface LoyaltyDisplayProps {
  variant?: 'full' | 'compact' | 'mini';
  className?: string;
}

export function LoyaltyDisplay({ variant = 'compact', className = '' }: LoyaltyDisplayProps) {
  const { user, isAuthenticated } = useAuth();
  const [account, setAccount] = useState<LoyaltyAccount | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (isAuthenticated && user) {
      loadAccount();
    } else {
      setLoading(false);
    }
  }, [isAuthenticated, user]);

  const loadAccount = async () => {
    try {
      // FIX: Iteration 3 - Use /loyalty/me (backend route) instead of /loyalty/account (doesn't exist)
      const res = await api.get('/loyalty/me');
      if (res.data.success) {
        setAccount(res.data.data);
      }
    } catch {
      // User may not have loyalty account yet
    } finally {
      setLoading(false);
    }
  };

  if (loading || !account) {
    return null;
  }

  const tierColor = account.tier?.color || '#6366f1';
  // FIX Iter-10: progress formula was using pointsMultiplier instead of actual points
  const progressPercent = account.nextTier
    ? Math.min(100, Math.round(((account.nextTier.pointsRequired - account.nextTier.pointsNeeded) / account.nextTier.pointsRequired) * 100))
    : 100;

  // Mini variant - just points badge
  if (variant === 'mini') {
    return (
      <Link href="/account/loyalty" className={`flex items-center gap-2 ${className}`}>
        <div 
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-white text-sm font-medium"
          style={{ backgroundColor: tierColor }}
        >
          <Award className="w-4 h-4" />
          <span>{formatNumber(account.currentPoints)}</span>
        </div>
      </Link>
    );
  }

  // Compact variant - points + tier
  if (variant === 'compact') {
    return (
      <Link href="/account/loyalty" className={`block ${className}`}>
        <motion.div 
          className="flex items-center gap-4 p-4 rounded-xl bg-gradient-to-r shadow-lg hover:shadow-xl transition-shadow"
          style={{ 
            background: `linear-gradient(135deg, ${tierColor}, ${tierColor}dd)` 
          }}
          whileHover={{ scale: 1.02 }}
        >
          <div className="w-12 h-12 rounded-full bg-white/20 flex items-center justify-center">
            <Award className="w-6 h-6 text-white" />
          </div>
          <div className="flex-1 text-white">
            <p className="text-sm opacity-80">{account.tier?.name || 'Member'}</p>
            <p className="text-2xl font-bold">{formatNumber(account.currentPoints)} pts</p>
          </div>
          <ChevronRight className="w-5 h-5 text-white/60" />
        </motion.div>
      </Link>
    );
  }

  // Full variant - complete loyalty card
  return (
    <motion.div 
      className={`rounded-2xl overflow-hidden shadow-xl ${className}`}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
    >
      <div 
        className="p-6 text-white"
        style={{ 
          background: `linear-gradient(135deg, ${tierColor}, ${tierColor}aa)` 
        }}
      >
        <div className="flex items-start justify-between mb-6">
          <div>
            <p className="text-sm opacity-80">Loyalty Program</p>
            <h3 className="text-xl font-bold">{account.tier?.name || 'Member'}</h3>
          </div>
          <div className="w-16 h-16 rounded-full bg-white/20 flex items-center justify-center">
            <Award className="w-8 h-8" />
          </div>
        </div>
        
        <div className="text-center py-4">
          <p className="text-5xl font-bold">{formatNumber(account.currentPoints)}</p>
          <p className="text-sm opacity-80">Available Points</p>
        </div>
        
        {account.tier?.pointsMultiplier > 1 && (
          <div className="flex items-center justify-center gap-2 mt-2 text-sm">
            <TrendingUp className="w-4 h-4" />
            <span>{account.tier.pointsMultiplier}x points on all purchases</span>
          </div>
        )}
      </div>
      
      <div className="bg-white dark:bg-slate-800 p-6">
        {account.nextTier && (
          <div className="mb-6">
            <div className="flex justify-between text-sm mb-2">
              <span className="text-slate-500">Progress to {account.nextTier.name}</span>
              <span className="font-medium">{formatNumber(account.nextTier.pointsNeeded)} pts needed</span>
            </div>
            <div className="h-2 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
              <motion.div 
                className="h-full rounded-full"
                style={{ backgroundColor: tierColor }}
                initial={{ width: 0 }}
                animate={{ width: `${Math.min(progressPercent, 100)}%` }}
                transition={{ duration: 1, ease: 'easeOut' }}
              />
            </div>
          </div>
        )}
        
        <div className="grid grid-cols-2 gap-4 text-center">
          <div className="p-3 bg-slate-50 dark:bg-slate-700 rounded-lg">
            <p className="text-2xl font-bold text-slate-900 dark:text-white">
              {formatNumber(account.totalPointsEarned)}
            </p>
            <p className="text-xs text-slate-500">Total Earned</p>
          </div>
          <div className="p-3 bg-slate-50 dark:bg-slate-700 rounded-lg">
            <p className="text-2xl font-bold text-slate-900 dark:text-white">
              {formatNumber(account.totalPointsRedeemed)}
            </p>
            <p className="text-xs text-slate-500">Total Redeemed</p>
          </div>
        </div>
        
        {account.tier?.benefits && account.tier.benefits.length > 0 && (
          <div className="mt-6">
            <p className="text-sm font-medium text-slate-900 dark:text-white mb-3">Your Benefits</p>
            <div className="space-y-2">
              {account.tier.benefits.slice(0, 3).map((benefit, i) => (
                <div key={i} className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
                  <Star className="w-4 h-4 text-amber-500" />
                  <span>{benefit}</span>
                </div>
              ))}
            </div>
          </div>
        )}
        
        <Link 
          href="/account/loyalty"
          className="mt-6 block w-full text-center py-3 rounded-lg font-medium transition-colors"
          style={{ 
            backgroundColor: `${tierColor}15`,
            color: tierColor
          }}
        >
          View Full Details
        </Link>
      </div>
    </motion.div>
  );
}

// Points calculation helper for product pages
interface PointsPreviewProps {
  amount: number;
  className?: string;
}

export function PointsPreview({ amount, className = '' }: PointsPreviewProps) {
  const { isAuthenticated } = useAuth();
  const [pointsRate, setPointsRate] = useState(1);

  useEffect(() => {
    if (isAuthenticated) {
      // FIX: Iteration 3 - Backend only defines POST /calculate, not GET
      api.post('/loyalty/calculate', { amount })
        .then(res => {
          if (res.data.success) {
            setPointsRate(res.data.data.points / amount || 1);
          }
        })
        .catch(() => {});
    }
  }, [isAuthenticated, amount]);

  const pointsToEarn = Math.floor(amount * pointsRate);

  if (!isAuthenticated || pointsToEarn <= 0) return null;

  return (
    <div className={`flex items-center gap-1.5 text-sm ${className}`}>
      <Award className="w-4 h-4 text-amber-500" />
      <span className="text-slate-600 dark:text-slate-400">
        Earn <span className="font-semibold text-amber-600">{formatNumber(pointsToEarn)}</span> loyalty points
      </span>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { api } from '@/lib/api';
import { useAuth } from '@/lib/auth-context';
import { formatCurrency, formatNumber } from '@/lib/utils';
import { toast } from 'sonner';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Card, CardContent } from '@/components/ui/Card';
import { CouponInput, AvailableCoupons } from './CouponInput';
import { PointsPreview } from './LoyaltyDisplay';
import {
  ChevronDown,
  ChevronUp,
  Gift,
  Ticket,
  Award,
  CreditCard,
  Check,
  Loader2,
  X,
  Sparkles,
} from 'lucide-react';

export interface AppliedDiscount {
  type: 'coupon' | 'giftcard' | 'loyalty';
  code?: string;
  amount: number;
  details?: string;
  pointsUsed?: number;
}

interface PaymentDiscountsProps {
  orderTotal: number;
  orderType?: string;
  moduleId?: string;
  onTotalChange?: (finalTotal: number, discounts: AppliedDiscount[]) => void;
  className?: string;
}

export function PaymentDiscounts({
  orderTotal,
  orderType = 'general',
  moduleId,
  onTotalChange,
  className = '',
}: PaymentDiscountsProps) {
  const { user, isAuthenticated } = useAuth();
  const [expanded, setExpanded] = useState(true);
  const [appliedDiscounts, setAppliedDiscounts] = useState<AppliedDiscount[]>([]);
  
  // Gift Card State
  const [giftCardCode, setGiftCardCode] = useState('');
  const [giftCardLoading, setGiftCardLoading] = useState(false);
  const [giftCardBalance, setGiftCardBalance] = useState<number | null>(null);
  const [giftCardApplied, setGiftCardApplied] = useState<{ code: string; amount: number } | null>(null);
  
  // Loyalty Points State
  const [loyaltyAccount, setLoyaltyAccount] = useState<{
    currentPoints: number;
    dollarValue: number;
    pointsRate: number;
  } | null>(null);
  const [pointsToRedeem, setPointsToRedeem] = useState('');
  const [pointsRedeemed, setPointsRedeemed] = useState(0);
  
  // Coupon State
  const [couponDiscount, setCouponDiscount] = useState(0);

  // Load loyalty account info
  useEffect(() => {
    if (isAuthenticated && user) {
      loadLoyaltyInfo();
    }
  }, [isAuthenticated, user]);

  // Calculate total discounts and notify parent
  useEffect(() => {
    const totalDiscount = appliedDiscounts.reduce((sum, d) => sum + d.amount, 0);
    const finalTotal = Math.max(0, orderTotal - totalDiscount);
    onTotalChange?.(finalTotal, appliedDiscounts);
  }, [appliedDiscounts, orderTotal]);

  const loadLoyaltyInfo = async () => {
    try {
      // Check if token exists before making the call
      const token = typeof window !== 'undefined' ? localStorage.getItem('accessToken') : null;
      if (!token) {
        return;
      }
      
      const res = await api.get('/loyalty/me');
      if (res.data.success) {
        const account = res.data.data;
        // Map backend field name (available_points) to frontend field name (currentPoints)
        const currentPoints = account.available_points || account.currentPoints || 0;
        // Assuming 100 points = $1
        const pointsRate = 100; // This should come from settings
        setLoyaltyAccount({
          currentPoints: currentPoints,
          dollarValue: currentPoints / pointsRate,
          pointsRate,
        });
      }
    } catch (error: any) {
      // Only log if it's not a 401 (user not authenticated is expected in some cases)
      if (error.response?.status !== 401) {
        console.error('[PaymentDiscounts] Error loading loyalty info:', error.response?.status, error.response?.data || error.message);
      }
      // Clear loyalty account on auth error - user may need to re-login
      if (error.response?.status === 401) {
        setLoyaltyAccount(null);
      }
    }
  };

  const handleCouponApply = (coupon: any) => {
    if (coupon) {
      // Remove any existing coupon discount
      setAppliedDiscounts(prev => prev.filter(d => d.type !== 'coupon'));
      
      // Add new coupon
      setAppliedDiscounts(prev => [...prev, {
        type: 'coupon',
        code: coupon.code,
        amount: coupon.discountAmount,
        details: coupon.description,
      }]);
      setCouponDiscount(coupon.discountAmount);
    } else {
      // Remove coupon
      setAppliedDiscounts(prev => prev.filter(d => d.type !== 'coupon'));
      setCouponDiscount(0);
    }
  };

  const handleGiftCardCheck = async () => {
    if (!giftCardCode.trim()) return;
    
    setGiftCardLoading(true);
    try {
      const res = await api.get(`/giftcards/check/${giftCardCode.trim()}`);
      if (res.data.success) {
        setGiftCardBalance(res.data.data.balance);
      }
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Gift card not found');
      setGiftCardBalance(null);
    } finally {
      setGiftCardLoading(false);
    }
  };

  const handleGiftCardApply = () => {
    if (giftCardBalance === null) return;
    
    const currentTotal = orderTotal - couponDiscount - pointsRedeemed;
    const amountToApply = Math.min(giftCardBalance, currentTotal);
    
    // Remove any existing gift card
    setAppliedDiscounts(prev => prev.filter(d => d.type !== 'giftcard'));
    
    // Add gift card
    setGiftCardApplied({ code: giftCardCode, amount: amountToApply });
    setAppliedDiscounts(prev => [...prev, {
      type: 'giftcard',
      code: giftCardCode,
      amount: amountToApply,
    }]);
    
    setGiftCardCode('');
    setGiftCardBalance(null);
    toast.success(`Gift card applied: ${formatCurrency(amountToApply)}`);
  };

  const handleRemoveGiftCard = () => {
    setGiftCardApplied(null);
    setAppliedDiscounts(prev => prev.filter(d => d.type !== 'giftcard'));
  };

  const handlePointsChange = (value: string) => {
    setPointsToRedeem(value);
    
    const points = parseInt(value) || 0;
    if (!loyaltyAccount) return;
    
    // Validate points
    const maxPoints = Math.min(
      loyaltyAccount.currentPoints,
      Math.ceil((orderTotal - couponDiscount - (giftCardApplied?.amount || 0)) * loyaltyAccount.pointsRate)
    );
    
    const validPoints = Math.min(points, maxPoints);
    const dollarValue = validPoints / loyaltyAccount.pointsRate;
    
    // Update redemption
    setPointsRedeemed(validPoints);
    
    // Update discounts
    setAppliedDiscounts(prev => {
      const filtered = prev.filter(d => d.type !== 'loyalty');
      if (validPoints > 0) {
        return [...filtered, {
          type: 'loyalty',
          amount: dollarValue,
          details: `${formatNumber(validPoints)} points`,
          pointsUsed: validPoints,
        }];
      }
      return filtered;
    });
  };

  const handleRedeemAllPoints = () => {
    if (!loyaltyAccount) return;
    
    const maxDollarValue = orderTotal - couponDiscount - (giftCardApplied?.amount || 0);
    const maxPoints = Math.min(
      loyaltyAccount.currentPoints,
      Math.ceil(maxDollarValue * loyaltyAccount.pointsRate)
    );
    
    setPointsToRedeem(maxPoints.toString());
    handlePointsChange(maxPoints.toString());
  };

  const totalDiscount = appliedDiscounts.reduce((sum, d) => sum + d.amount, 0);
  const finalTotal = Math.max(0, orderTotal - totalDiscount);
  const pointsToEarn = Math.floor(finalTotal); // 1 point per dollar (can be configured)

  return (
    <Card className={className}>
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full p-4 flex items-center justify-between text-left"
      >
        <div className="flex items-center gap-3">
          <Sparkles className="w-5 h-5 text-purple-500" />
          <span className="font-semibold">Discounts & Rewards</span>
          {totalDiscount > 0 && (
            <span className="text-green-600 font-medium">
              -{formatCurrency(totalDiscount)}
            </span>
          )}
        </div>
        {expanded ? (
          <ChevronUp className="w-5 h-5 text-slate-400" />
        ) : (
          <ChevronDown className="w-5 h-5 text-slate-400" />
        )}
      </button>

      <AnimatePresence>
        {expanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden"
          >
            <CardContent className="pt-0 space-y-6">
              {/* Coupon Section */}
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <Ticket className="w-4 h-4 text-purple-500" />
                  <span className="font-medium text-sm">Coupon Code</span>
                </div>
                <CouponInput
                  orderTotal={orderTotal}
                  orderType={orderType}
                  moduleId={moduleId}
                  onCouponApply={handleCouponApply}
                  onDiscountChange={setCouponDiscount}
                />
              </div>

              {/* Gift Card Section */}
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <Gift className="w-4 h-4 text-pink-500" />
                  <span className="font-medium text-sm">Gift Card</span>
                </div>
                
                {giftCardApplied ? (
                  <div className="flex items-center justify-between p-3 bg-green-50 dark:bg-green-900/20 rounded-lg">
                    <div className="flex items-center gap-3">
                      <Check className="w-5 h-5 text-green-600" />
                      <div>
                        <p className="font-mono text-sm font-medium">{giftCardApplied.code}</p>
                        <p className="text-green-600 font-semibold">
                          -{formatCurrency(giftCardApplied.amount)}
                        </p>
                      </div>
                    </div>
                    <Button variant="ghost" size="sm" onClick={handleRemoveGiftCard}>
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <div className="flex gap-2">
                      <Input
                        placeholder="Enter gift card code"
                        value={giftCardCode}
                        onChange={(e) => { setGiftCardCode(e.target.value.toUpperCase()); setGiftCardBalance(null); }}
                        className="font-mono uppercase"
                      />
                      <Button
                        variant="outline"
                        onClick={handleGiftCardCheck}
                        disabled={giftCardLoading || !giftCardCode.trim()}
                      >
                        {giftCardLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Check'}
                      </Button>
                    </div>
                    
                    {giftCardBalance !== null && (
                      <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="flex items-center justify-between p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg"
                      >
                        <div>
                          <p className="text-sm text-slate-600">Available Balance</p>
                          <p className="text-lg font-bold text-blue-600">{formatCurrency(giftCardBalance)}</p>
                        </div>
                        <Button size="sm" onClick={handleGiftCardApply}>
                          Apply
                        </Button>
                      </motion.div>
                    )}
                  </div>
                )}
              </div>

              {/* Loyalty Points Section */}
              {isAuthenticated && loyaltyAccount && loyaltyAccount.currentPoints > 0 && (
                <div>
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <Award className="w-4 h-4 text-amber-500" />
                      <span className="font-medium text-sm">Loyalty Points</span>
                    </div>
                    <span className="text-sm text-slate-500">
                      {formatNumber(loyaltyAccount.currentPoints)} pts available
                      ({formatCurrency(loyaltyAccount.dollarValue)} value)
                    </span>
                  </div>
                  
                  <div className="flex gap-2">
                    <div className="relative flex-1">
                      <Input
                        type="number"
                        placeholder="Points to redeem"
                        value={pointsToRedeem}
                        onChange={(e) => handlePointsChange(e.target.value)}
                        max={loyaltyAccount.currentPoints}
                        min={0}
                      />
                      {parseInt(pointsToRedeem) > 0 && (
                        <span className="absolute right-3 top-1/2 -translate-y-1/2 text-sm text-green-600">
                          = {formatCurrency(pointsRedeemed / loyaltyAccount.pointsRate)}
                        </span>
                      )}
                    </div>
                    <Button variant="outline" size="sm" onClick={handleRedeemAllPoints}>
                      Max
                    </Button>
                  </div>
                  
                  <p className="text-xs text-slate-500 mt-1">
                    {loyaltyAccount.pointsRate} points = $1.00
                  </p>
                </div>
              )}

              {/* Summary */}
              {appliedDiscounts.length > 0 && (
                <div className="border-t dark:border-slate-700 pt-4">
                  <p className="text-sm font-medium mb-2">Applied Discounts</p>
                  <div className="space-y-2">
                    {appliedDiscounts.map((discount, i) => (
                      <div key={i} className="flex items-center justify-between text-sm">
                        <span className="text-slate-600 dark:text-slate-400 flex items-center gap-2">
                          {discount.type === 'coupon' && <Ticket className="w-4 h-4" />}
                          {discount.type === 'giftcard' && <Gift className="w-4 h-4" />}
                          {discount.type === 'loyalty' && <Award className="w-4 h-4" />}
                          {discount.code || discount.details}
                        </span>
                        <span className="font-medium text-green-600">
                          -{formatCurrency(discount.amount)}
                        </span>
                      </div>
                    ))}
                    <div className="flex items-center justify-between font-bold pt-2 border-t dark:border-slate-700">
                      <span>Total Savings</span>
                      <span className="text-green-600">-{formatCurrency(totalDiscount)}</span>
                    </div>
                  </div>
                </div>
              )}

              {/* Points to earn */}
              {isAuthenticated && pointsToEarn > 0 && (
                <div className="flex items-center gap-2 text-sm text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 p-3 rounded-lg">
                  <Award className="w-4 h-4" />
                  <span>
                    You'll earn <strong>{formatNumber(pointsToEarn)}</strong> loyalty points with this order!
                  </span>
                </div>
              )}
            </CardContent>
          </motion.div>
        )}
      </AnimatePresence>
    </Card>
  );
}

// Export individual components for flexible use
export { CouponInput, AvailableCoupons } from './CouponInput';
export { LoyaltyDisplay, PointsPreview } from './LoyaltyDisplay';
export { GiftCardPurchase, GiftCardBalance } from './GiftCardPurchase';

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { api } from '@/lib/api';
import { formatCurrency } from '@/lib/utils';
import { useSettingsStore } from '@/stores/settingsStore';
import { useContentTranslation } from '@/lib/translate';
import { Button } from '@/components/ui/Button';
import {
  X,
  Plus,
  Minus,
  Check,
  AlertCircle,
  ChevronDown,
  Package,
  Loader2,
  Sparkles,
  Ban,
  RefreshCcw,
  ArrowUpCircle,
} from 'lucide-react';

// ==========================================
// TYPES (mirror the shared types)
// ==========================================

export type CustomizationType = 'add' | 'remove' | 'swap' | 'upgrade' | 'replace';
export type CustomizableEntityType = 
  | 'menu_item' 
  | 'snack_bar_item' 
  | 'chalet' 
  | 'pool_session' 
  | 'spa_service' 
  | 'activity' 
  | 'rental_item' 
  | 'event_ticket' 
  | 'room' 
  | 'package';
export type SelectionMode = 'single' | 'multiple' | 'quantity';
export type PriceType = 'fixed' | 'percentage' | 'per_unit' | 'per_night' | 'per_person';

export interface CustomizationOptionDisplay {
  id: string;
  name: string;
  nameAr?: string;
  description?: string;
  customizationType: CustomizationType;
  priceAdjustment: number;
  priceType: PriceType;
  maxQuantity: number;
  isDefault: boolean;
  isPopular: boolean;
  badgeText?: string;
  imageUrl?: string;
  isAvailable: boolean;
  inventoryItemId?: string;
  quantityPerSelection: number;
  sortOrder: number;
}

export interface CustomizationGroupWithOptions {
  groupId: string;
  groupName: string;
  groupNameAr?: string;
  displayName?: string;
  displayNameAr?: string;
  selectionMode: SelectionMode;
  minSelections: number;
  maxSelections: number;
  isRequired: boolean;
  sortOrder: number;
  options: CustomizationOptionDisplay[];
}

export interface CustomizationSelection {
  groupId: string;
  optionId: string;
  quantity: number;
}

export interface ValidatedSelection extends CustomizationSelection {
  groupName: string;
  optionName: string;
  customizationType: CustomizationType;
  unitPrice: number;
  totalPrice: number;
  inventoryItemId?: string;
  quantityPerSelection: number;
  replacesInventoryItemId?: string;
}

export interface CustomizationValidationResult {
  isValid: boolean;
  totalPriceAdjustment: number;
  validatedSelections: ValidatedSelection[];
  validationErrors: string[];
}

// ==========================================
// CUSTOMIZATION SELECTOR COMPONENT
// ==========================================

interface CustomizationSelectorProps {
  /** Type of entity being customized */
  entityType: CustomizableEntityType;
  /** ID of the specific entity */
  entityId: string;
  /** Entity display info */
  entity: {
    name: string;
    nameAr?: string;
    description?: string;
    descriptionAr?: string;
    basePrice: number;
    imageUrl?: string;
  };
  /** Whether modal is open */
  isOpen: boolean;
  /** Close handler */
  onClose: () => void;
  /** Callback when customizations are confirmed */
  onConfirm: (data: {
    selections: ValidatedSelection[];
    totalPriceAdjustment: number;
    lineTotal: number;
    quantity: number;
  }) => void;
  /** Initial quantity (default 1) */
  initialQuantity?: number;
  /** Whether to show quantity selector (default true) */
  showQuantitySelector?: boolean;
  /** Custom title */
  title?: string;
  /** Price display context for accommodations */
  priceContext?: 'per_item' | 'per_night' | 'per_person' | 'total';
  /** Number of nights/persons for context */
  contextMultiplier?: number;
}

export function CustomizationSelector({
  entityType,
  entityId,
  entity,
  isOpen,
  onClose,
  onConfirm,
  initialQuantity = 1,
  showQuantitySelector = true,
  title,
  priceContext = 'per_item',
  contextMultiplier = 1,
}: CustomizationSelectorProps) {
  const t = useTranslations('common');
  const { translateContent } = useContentTranslation();
  const currency = useSettingsStore((s) => s.currency);

  // State
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [groups, setGroups] = useState<CustomizationGroupWithOptions[]>([]);
  const [selections, setSelections] = useState<Map<string, { optionId: string; quantity: number }[]>>(new Map());
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
  const [quantity, setQuantity] = useState(initialQuantity);
  const [validationResult, setValidationResult] = useState<CustomizationValidationResult | null>(null);
  const [validating, setValidating] = useState(false);

  // Helper for translation - converts individual fields to translatable item format
  const getText = useCallback((name: string, nameAr?: string): string => {
    return translateContent({ name, name_ar: nameAr }, 'name');
  }, [translateContent]);

  // Fetch customizations when modal opens
  useEffect(() => {
    if (isOpen && entityId) {
      fetchCustomizations();
    }
  }, [isOpen, entityType, entityId]);

  // Auto-expand required groups and set defaults
  useEffect(() => {
    if (groups.length > 0) {
      const requiredGroupIds = new Set(
        groups.filter(g => g.isRequired).map(g => g.groupId)
      );
      setExpandedGroups(requiredGroupIds);

      // Set default selections
      const defaultSelections = new Map<string, { optionId: string; quantity: number }[]>();
      groups.forEach(group => {
        const defaults = group.options
          .filter(o => o.isDefault && o.isAvailable)
          .map(o => ({ optionId: o.id, quantity: 1 }));
        if (defaults.length > 0) {
          defaultSelections.set(group.groupId, defaults);
        }
      });
      setSelections(defaultSelections);
    }
  }, [groups]);

  // Validate when selections change
  useEffect(() => {
    if (groups.length > 0 && !loading) {
      validateSelections();
    }
  }, [selections, groups, loading]);

  const fetchCustomizations = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await api.get(`/customizations/for-entity/${entityType}/${entityId}`);
      setGroups(response.data || []);
    } catch (err: any) {
      console.error('Failed to fetch customizations:', err);
      setError(err.message || 'Failed to load customization options');
    } finally {
      setLoading(false);
    }
  };

  const validateSelections = async () => {
    setValidating(true);
    try {
      const selectionsArray: CustomizationSelection[] = [];
      selections.forEach((opts, groupId) => {
        opts.forEach(opt => {
          selectionsArray.push({
            groupId,
            optionId: opt.optionId,
            quantity: opt.quantity
          });
        });
      });

      const response = await api.post('/customizations/validate', {
        entityType,
        entityId,
        selections: selectionsArray
      });

      setValidationResult(response.data);
    } catch (err: any) {
      console.error('Validation error:', err);
      setValidationResult({
        isValid: false,
        totalPriceAdjustment: 0,
        validatedSelections: [],
        validationErrors: ['Failed to validate selections']
      });
    } finally {
      setValidating(false);
    }
  };

  // Selection handlers
  const handleSingleSelect = useCallback((groupId: string, optionId: string) => {
    setSelections(prev => {
      const next = new Map(prev);
      const current = next.get(groupId)?.[0];
      
      // Toggle off if same option
      if (current?.optionId === optionId) {
        next.delete(groupId);
      } else {
        next.set(groupId, [{ optionId, quantity: 1 }]);
      }
      return next;
    });
  }, []);

  const handleMultipleSelect = useCallback((groupId: string, optionId: string, maxSelections: number) => {
    setSelections(prev => {
      const next = new Map(prev);
      const current = next.get(groupId) || [];
      const exists = current.find(s => s.optionId === optionId);

      if (exists) {
        // Remove
        const filtered = current.filter(s => s.optionId !== optionId);
        if (filtered.length === 0) {
          next.delete(groupId);
        } else {
          next.set(groupId, filtered);
        }
      } else if (current.length < maxSelections) {
        // Add
        next.set(groupId, [...current, { optionId, quantity: 1 }]);
      }
      return next;
    });
  }, []);

  const handleQuantityChange = useCallback((groupId: string, optionId: string, delta: number, maxQuantity: number) => {
    setSelections(prev => {
      const next = new Map(prev);
      const current = next.get(groupId) || [];
      const existing = current.find(s => s.optionId === optionId);

      if (existing) {
        const newQty = Math.max(0, Math.min(maxQuantity, existing.quantity + delta));
        if (newQty === 0) {
          const filtered = current.filter(s => s.optionId !== optionId);
          if (filtered.length === 0) {
            next.delete(groupId);
          } else {
            next.set(groupId, filtered);
          }
        } else {
          next.set(groupId, current.map(s => 
            s.optionId === optionId ? { ...s, quantity: newQty } : s
          ));
        }
      } else if (delta > 0) {
        next.set(groupId, [...current, { optionId, quantity: 1 }]);
      }
      return next;
    });
  }, []);

  const toggleGroup = useCallback((groupId: string) => {
    setExpandedGroups(prev => {
      const next = new Set(prev);
      if (next.has(groupId)) {
        next.delete(groupId);
      } else {
        next.add(groupId);
      }
      return next;
    });
  }, []);

  // Calculate totals
  const totals = useMemo(() => {
    const customizationTotal = validationResult?.totalPriceAdjustment || 0;
    const baseTotal = entity.basePrice * quantity;
    
    // For accommodations, customization might be per night
    const adjustedCustomizationTotal = priceContext === 'per_night' 
      ? customizationTotal * contextMultiplier 
      : priceContext === 'per_person'
        ? customizationTotal * contextMultiplier
        : customizationTotal;
    
    return {
      base: baseTotal,
      customizations: adjustedCustomizationTotal * quantity,
      total: baseTotal + (adjustedCustomizationTotal * quantity)
    };
  }, [entity.basePrice, quantity, validationResult, priceContext, contextMultiplier]);

  // Check if all required groups have selections
  const hasRequiredSelections = useMemo(() => {
    return groups
      .filter(g => g.isRequired)
      .every(g => {
        const sel = selections.get(g.groupId);
        return sel && sel.length >= g.minSelections;
      });
  }, [groups, selections]);

  const canConfirm = validationResult?.isValid && hasRequiredSelections && !validating;

  const handleConfirm = () => {
    if (!validationResult?.isValid) return;
    
    onConfirm({
      selections: validationResult.validatedSelections,
      totalPriceAdjustment: validationResult.totalPriceAdjustment,
      lineTotal: totals.total,
      quantity
    });
  };

  // Get icon for customization type
  const getTypeIcon = (type: CustomizationType) => {
    switch (type) {
      case 'add': return <Plus className="w-3 h-3" />;
      case 'remove': return <Ban className="w-3 h-3" />;
      case 'swap': return <RefreshCcw className="w-3 h-3" />;
      case 'upgrade': return <ArrowUpCircle className="w-3 h-3" />;
      default: return null;
    }
  };

  // Get badge color for customization type
  const getTypeBadgeColor = (type: CustomizationType) => {
    switch (type) {
      case 'add': return 'bg-green-100 text-green-700 border-green-300';
      case 'remove': return 'bg-red-100 text-red-700 border-red-300';
      case 'swap': return 'bg-blue-100 text-blue-700 border-blue-300';
      case 'upgrade': return 'bg-purple-100 text-purple-700 border-purple-300';
      default: return 'bg-gray-100 text-gray-700 border-gray-300';
    }
  };

  // Format price based on type
  const formatPrice = (amount: number, type: PriceType) => {
    if (amount === 0) return t('free') || 'Free';
    const prefix = amount > 0 ? '+' : '';
    
    switch (type) {
      case 'percentage':
        return `${prefix}${amount}%`;
      case 'per_night':
        return `${prefix}${formatCurrency(amount, currency)}/night`;
      case 'per_person':
        return `${prefix}${formatCurrency(amount, currency)}/person`;
      default:
        return `${prefix}${formatCurrency(amount, currency)}`;
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        onClick={(e) => e.target === e.currentTarget && onClose()}
      >
        <motion.div
          initial={{ scale: 0.95, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.95, opacity: 0 }}
          className="bg-white dark:bg-gray-900 rounded-2xl shadow-2xl max-w-lg w-full max-h-[90vh] flex flex-col overflow-hidden"
        >
          {/* Header */}
          <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex items-start justify-between">
            <div className="flex-1 pr-4">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                {title || getText(entity.name, entity.nameAr)}
              </h2>
              {entity.description && (
                <p className="text-sm text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
                  {getText(entity.description, entity.descriptionAr)}
                </p>
              )}
              <p className="text-lg font-semibold text-primary mt-2">
                {formatCurrency(entity.basePrice, currency)}
              </p>
            </div>
            <button
              onClick={onClose}
              className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {loading ? (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
              </div>
            ) : error ? (
              <div className="text-center py-8">
                <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-3" />
                <p className="text-gray-600 dark:text-gray-400">{error}</p>
                <Button onClick={fetchCustomizations} className="mt-4">
                  {t('retry') || 'Retry'}
                </Button>
              </div>
            ) : groups.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                <Package className="w-12 h-12 mx-auto mb-3 opacity-50" />
                <p>{t('noCustomizationsAvailable') || 'No customization options available'}</p>
              </div>
            ) : (
              groups.map((group) => (
                <div
                  key={group.groupId}
                  className="border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden"
                >
                  {/* Group Header */}
                  <button
                    onClick={() => toggleGroup(group.groupId)}
                    className="w-full p-4 flex items-center justify-between bg-gray-50 dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-750 transition-colors"
                  >
                    <div className="flex items-center gap-3">
                      <span className="font-semibold text-gray-900 dark:text-white">
                        {getText(group.displayName || group.groupName, group.displayNameAr || group.groupNameAr)}
                      </span>
                      {group.isRequired && (
                        <span className="text-xs px-2 py-0.5 bg-red-100 text-red-700 rounded-full">
                          {t('required') || 'Required'}
                        </span>
                      )}
                      {group.selectionMode === 'multiple' && (
                        <span className="text-xs text-gray-500">
                          ({t('selectUpTo') || 'Select up to'} {group.maxSelections})
                        </span>
                      )}
                    </div>
                    <ChevronDown
                      className={`w-5 h-5 transition-transform ${
                        expandedGroups.has(group.groupId) ? 'rotate-180' : ''
                      }`}
                    />
                  </button>

                  {/* Options */}
                  <AnimatePresence>
                    {expandedGroups.has(group.groupId) && (
                      <motion.div
                        initial={{ height: 0 }}
                        animate={{ height: 'auto' }}
                        exit={{ height: 0 }}
                        className="overflow-hidden"
                      >
                        <div className="p-2 space-y-2">
                          {group.options.map((option) => {
                            const selected = selections.get(group.groupId)?.find(s => s.optionId === option.id);
                            const isSelected = !!selected;
                            const currentQty = selected?.quantity || 0;

                            return (
                              <div
                                key={option.id}
                                className={`
                                  relative p-3 rounded-lg border-2 transition-all cursor-pointer
                                  ${!option.isAvailable 
                                    ? 'opacity-50 cursor-not-allowed bg-gray-50 dark:bg-gray-800 border-gray-200' 
                                    : isSelected
                                      ? 'bg-orange-50 dark:bg-orange-900/20 border-orange-500 shadow-md'
                                      : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 hover:border-orange-300'
                                  }
                                `}
                                onClick={() => {
                                  if (!option.isAvailable) return;
                                  
                                  if (group.selectionMode === 'single') {
                                    handleSingleSelect(group.groupId, option.id);
                                  } else if (group.selectionMode === 'multiple') {
                                    handleMultipleSelect(group.groupId, option.id, group.maxSelections);
                                  }
                                  // Quantity mode handled by buttons
                                }}
                              >
                                <div className="flex items-start justify-between gap-3">
                                  <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                      {/* Selection indicator */}
                                      {group.selectionMode !== 'quantity' && (
                                        <div
                                          className={`
                                            w-5 h-5 rounded-full border-2 flex items-center justify-center
                                            ${isSelected
                                              ? 'bg-orange-500 border-orange-500'
                                              : 'border-gray-300 dark:border-gray-600'
                                            }
                                          `}
                                        >
                                          {isSelected && <Check className="w-3 h-3 text-white" />}
                                        </div>
                                      )}

                                      {/* Name */}
                                      <span className="font-medium text-gray-900 dark:text-white">
                                        {getText(option.name, option.nameAr)}
                                      </span>

                                      {/* Type badge */}
                                      <span className={`
                                        inline-flex items-center gap-1 text-xs px-1.5 py-0.5 rounded border
                                        ${getTypeBadgeColor(option.customizationType)}
                                      `}>
                                        {getTypeIcon(option.customizationType)}
                                        {option.customizationType}
                                      </span>

                                      {/* Popular badge */}
                                      {option.isPopular && (
                                        <span className="inline-flex items-center gap-1 text-xs px-1.5 py-0.5 rounded bg-yellow-100 text-yellow-700 border border-yellow-300">
                                          <Sparkles className="w-3 h-3" />
                                          {t('popular') || 'Popular'}
                                        </span>
                                      )}

                                      {/* Custom badge */}
                                      {option.badgeText && (
                                        <span className="text-xs px-1.5 py-0.5 rounded bg-primary/10 text-primary">
                                          {option.badgeText}
                                        </span>
                                      )}
                                    </div>

                                    {option.description && (
                                      <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 ml-7">
                                        {option.description}
                                      </p>
                                    )}

                                    {!option.isAvailable && (
                                      <p className="text-sm text-red-500 mt-1 ml-7">
                                        {t('outOfStock') || 'Out of stock'}
                                      </p>
                                    )}
                                  </div>

                                  {/* Price & Quantity */}
                                  <div className="flex flex-col items-end gap-2">
                                    <span className={`
                                      font-semibold
                                      ${option.priceAdjustment > 0 
                                        ? 'text-orange-600' 
                                        : option.priceAdjustment < 0 
                                          ? 'text-green-600' 
                                          : 'text-gray-500'
                                      }
                                    `}>
                                      {formatPrice(option.priceAdjustment, option.priceType)}
                                    </span>

                                    {/* Quantity controls for quantity mode */}
                                    {group.selectionMode === 'quantity' && option.isAvailable && (
                                      <div
                                        className="flex items-center gap-2 bg-gray-100 dark:bg-gray-700 rounded-full"
                                        onClick={(e) => e.stopPropagation()}
                                      >
                                        <button
                                          onClick={() => handleQuantityChange(group.groupId, option.id, -1, option.maxQuantity)}
                                          className="p-1.5 rounded-full hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                                          disabled={currentQty === 0}
                                        >
                                          <Minus className="w-4 h-4" />
                                        </button>
                                        <span className="w-6 text-center font-medium">
                                          {currentQty}
                                        </span>
                                        <button
                                          onClick={() => handleQuantityChange(group.groupId, option.id, 1, option.maxQuantity)}
                                          className="p-1.5 rounded-full hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                                          disabled={currentQty >= option.maxQuantity}
                                        >
                                          <Plus className="w-4 h-4" />
                                        </button>
                                      </div>
                                    )}
                                  </div>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              ))
            )}

            {/* Validation Errors */}
            {validationResult && validationResult.validationErrors.length > 0 && (
              <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-3">
                <div className="flex items-start gap-2">
                  <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
                  <div>
                    {validationResult.validationErrors.map((err, i) => (
                      <p key={i} className="text-sm text-red-700 dark:text-red-300">
                        {err}
                      </p>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="p-4 border-t border-gray-200 dark:border-gray-700 space-y-4">
            {/* Quantity Selector */}
            {showQuantitySelector && (
              <div className="flex items-center justify-between">
                <span className="font-medium text-gray-700 dark:text-gray-300">
                  {t('quantity') || 'Quantity'}
                </span>
                <div className="flex items-center gap-3 bg-gray-100 dark:bg-gray-800 rounded-full px-2">
                  <button
                    onClick={() => setQuantity(q => Math.max(1, q - 1))}
                    className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
                    disabled={quantity <= 1}
                  >
                    <Minus className="w-4 h-4" />
                  </button>
                  <span className="w-8 text-center font-bold text-lg">{quantity}</span>
                  <button
                    onClick={() => setQuantity(q => q + 1)}
                    className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
                  >
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
              </div>
            )}

            {/* Price Summary */}
            <div className="space-y-1 text-sm">
              <div className="flex justify-between text-gray-600 dark:text-gray-400">
                <span>{t('basePrice') || 'Base price'}</span>
                <span>{formatCurrency(totals.base, currency)}</span>
              </div>
              {totals.customizations !== 0 && (
                <div className="flex justify-between text-gray-600 dark:text-gray-400">
                  <span>{t('customizations') || 'Customizations'}</span>
                  <span className={totals.customizations > 0 ? 'text-orange-600' : 'text-green-600'}>
                    {totals.customizations > 0 ? '+' : ''}{formatCurrency(totals.customizations, currency)}
                  </span>
                </div>
              )}
              <div className="flex justify-between text-lg font-bold pt-2 border-t border-gray-200 dark:border-gray-700">
                <span>{t('total') || 'Total'}</span>
                <span className="text-primary">{formatCurrency(totals.total, currency)}</span>
              </div>
            </div>

            {/* Action Button */}
            <Button
              onClick={handleConfirm}
              disabled={!canConfirm}
              className="w-full py-3 text-lg font-semibold"
            >
              {validating ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <>
                  <Check className="w-5 h-5 mr-2" />
                  {t('confirmSelection') || 'Confirm Selection'} - {formatCurrency(totals.total, currency)}
                </>
              )}
            </Button>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}

export default CustomizationSelector;

'use client';

import React, { useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { cn } from '@/lib/utils';

interface AuroraBackgroundProps {
  children?: React.ReactNode;
  className?: string;
  showRadialGradient?: boolean;
  intensity?: 'subtle' | 'medium' | 'strong';
}

export function AuroraBackground({
  children,
  className,
  showRadialGradient = true,
  intensity = 'medium',
}: AuroraBackgroundProps) {
  const intensityMap = {
    subtle: 'opacity-30',
    medium: 'opacity-50',
    strong: 'opacity-70',
  };

  return (
    <div
      className={cn(
        'relative flex flex-col min-h-screen overflow-hidden bg-gradient-to-b from-white via-slate-50 to-white dark:from-slate-950 dark:via-slate-900 dark:to-slate-950',
        className
      )}
    >
      {/* Aurora blobs */}
      <div className={cn('absolute inset-0', intensityMap[intensity])}>
        {/* Primary blob */}
        <motion.div
          className="absolute -top-40 -left-40 w-[600px] h-[600px] rounded-full"
          style={{
            background: 'radial-gradient(circle, var(--color-primary) 0%, transparent 70%)',
            filter: 'blur(80px)',
          }}
          animate={{
            x: [0, 100, 50, 0],
            y: [0, 50, 100, 0],
            scale: [1, 1.1, 0.9, 1],
          }}
          transition={{
            duration: 20,
            repeat: Infinity,
            ease: 'linear',
          }}
        />

        {/* Secondary blob */}
        <motion.div
          className="absolute top-1/4 -right-40 w-[500px] h-[500px] rounded-full"
          style={{
            background: 'radial-gradient(circle, var(--color-secondary) 0%, transparent 70%)',
            filter: 'blur(80px)',
          }}
          animate={{
            x: [0, -80, -40, 0],
            y: [0, 80, 40, 0],
            scale: [1, 0.9, 1.1, 1],
          }}
          transition={{
            duration: 25,
            repeat: Infinity,
            ease: 'linear',
          }}
        />

        {/* Accent blob */}
        <motion.div
          className="absolute bottom-0 left-1/3 w-[400px] h-[400px] rounded-full"
          style={{
            background: 'radial-gradient(circle, var(--color-accent) 0%, transparent 70%)',
            filter: 'blur(80px)',
          }}
          animate={{
            x: [0, 60, -30, 0],
            y: [0, -60, -30, 0],
            scale: [1, 1.2, 0.95, 1],
          }}
          transition={{
            duration: 18,
            repeat: Infinity,
            ease: 'linear',
          }}
        />

        {/* Extra ambient blob */}
        <motion.div
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] rounded-full"
          style={{
            background: 'radial-gradient(circle, var(--color-primary) 0%, var(--color-secondary) 50%, transparent 70%)',
            filter: 'blur(120px)',
            opacity: 0.3,
          }}
          animate={{
            scale: [1, 1.05, 0.98, 1],
            rotate: [0, 180, 360],
          }}
          transition={{
            duration: 30,
            repeat: Infinity,
            ease: 'linear',
          }}
        />
      </div>

      {/* Radial gradient overlay for depth */}
      {showRadialGradient && (
        <div 
          className="absolute inset-0 pointer-events-none"
          style={{
            background: 'radial-gradient(ellipse 80% 80% at 50% -20%, transparent 50%, rgba(255,255,255,0.8) 100%)',
          }}
        />
      )}

      {/* Noise texture overlay */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.015] dark:opacity-[0.03]"
        style={{
          backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E")`,
        }}
      />

      {/* Content */}
      <div className="relative z-10">
        {children}
      </div>
    </div>
  );
}

