'use client';

/**
 * Page Transition Component
 * 
 * Provides smooth page transitions with configurable animations.
 * Can be toggled on/off via settings.
 */

import { motion, AnimatePresence } from 'framer-motion';
import { usePathname } from 'next/navigation';
import { ReactNode, useEffect, useState } from 'react';
import { useSettingsStore } from '@/stores/settingsStore';

interface PageTransitionProps {
  children: ReactNode;
}

// Animation variants - Premium transitions
const pageVariants = {
  // Fade transition
  fade: {
    initial: { opacity: 0 },
    animate: { opacity: 1 },
    exit: { opacity: 0 },
  },
  // Slide from right
  slideRight: {
    initial: { opacity: 0, x: 50 },
    animate: { opacity: 1, x: 0 },
    exit: { opacity: 0, x: -30 },
  },
  // Slide from bottom
  slideUp: {
    initial: { opacity: 0, y: 40 },
    animate: { opacity: 1, y: 0 },
    exit: { opacity: 0, y: -30 },
  },
  // Scale and fade
  scale: {
    initial: { opacity: 0, scale: 0.92 },
    animate: { opacity: 1, scale: 1 },
    exit: { opacity: 0, scale: 1.08 },
  },
  // Elegant reveal with blur - Default premium option
  reveal: {
    initial: { opacity: 0, y: 60, filter: 'blur(12px)' },
    animate: { opacity: 1, y: 0, filter: 'blur(0px)' },
    exit: { opacity: 0, y: -40, filter: 'blur(8px)' },
  },
  // Cinematic zoom reveal
  cinematic: {
    initial: { 
      opacity: 0, 
      scale: 1.1, 
      filter: 'blur(20px) saturate(0.5)',
    },
    animate: { 
      opacity: 1, 
      scale: 1, 
      filter: 'blur(0px) saturate(1)',
    },
    exit: { 
      opacity: 0, 
      scale: 0.95, 
      filter: 'blur(10px) saturate(0.8)',
    },
  },
  // Dramatic sweep from side
  sweep: {
    initial: { 
      opacity: 0, 
      x: -100,
      skewX: -5,
    },
    animate: { 
      opacity: 1, 
      x: 0,
      skewX: 0,
    },
    exit: { 
      opacity: 0, 
      x: 100,
      skewX: 5,
    },
  },
  // Luxury fade with scale
  luxury: {
    initial: { 
      opacity: 0, 
      scale: 0.96,
      y: 30,
      filter: 'blur(8px)',
    },
    animate: { 
      opacity: 1, 
      scale: 1,
      y: 0,
      filter: 'blur(0px)',
    },
    exit: { 
      opacity: 0, 
      scale: 1.02,
      y: -20,
      filter: 'blur(6px)',
    },
  },
};

const transitionConfig = {
  duration: 0.5,
  ease: [0.22, 1, 0.36, 1] as const, // Smooth cubic bezier (expo out)
};

export function PageTransition({ children }: PageTransitionProps) {
  const pathname = usePathname();
  const enableTransitions = useSettingsStore((s) => s.enableTransitions);
  const transitionStyle = useSettingsStore((s) => s.transitionStyle);

  // Get the appropriate variant
  const variant = pageVariants[transitionStyle as keyof typeof pageVariants] || pageVariants.fade;

  // If transitions are disabled, just render children
  if (!enableTransitions) {
    return <>{children}</>;
  }

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={pathname}
        initial="initial"
        animate="animate"
        exit="exit"
        variants={variant}
        transition={transitionConfig}
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}

/**
 * Section animation component for staggered content
 */
interface AnimatedSectionProps {
  children: ReactNode;
  delay?: number;
  className?: string;
}

export function AnimatedSection({ children, delay = 0, className = '' }: AnimatedSectionProps) {
  const enableTransitions = useSettingsStore((s) => s.enableTransitions);

  if (!enableTransitions) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div
      className={className}
      initial={{ opacity: 0, y: 40, filter: 'blur(8px)' }}
      whileInView={{ opacity: 1, y: 0, filter: 'blur(0px)' }}
      viewport={{ once: true, margin: '-80px' }}
      transition={{ 
        duration: 0.7, 
        delay, 
        ease: [0.22, 1, 0.36, 1],
      }}
    >
      {children}
    </motion.div>
  );
}

/**
 * Staggered children animation
 */
interface StaggeredContainerProps {
  children: ReactNode;
  className?: string;
  staggerDelay?: number;
}

export function StaggeredContainer({ children, className = '', staggerDelay = 0.1 }: StaggeredContainerProps) {
  const enableTransitions = useSettingsStore((s) => s.enableTransitions);

  if (!enableTransitions) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div
      className={className}
      initial="hidden"
      animate="visible"
      variants={{
        hidden: { opacity: 0 },
        visible: {
          opacity: 1,
          transition: {
            staggerChildren: staggerDelay,
          },
        },
      }}
    >
      {children}
    </motion.div>
  );
}

export function StaggeredItem({ children, className = '' }: { children: ReactNode; className?: string }) {
  return (
    <motion.div
      className={className}
      variants={{
        hidden: { opacity: 0, y: 30, scale: 0.95 },
        visible: { opacity: 1, y: 0, scale: 1 },
      }}
      transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
    >
      {children}
    </motion.div>
  );
}

/**
 * Premium card reveal animation
 * Use for cards that should have a luxury reveal effect
 */
export function LuxuryReveal({ children, className = '', delay = 0 }: { children: ReactNode; className?: string; delay?: number }) {
  const enableTransitions = useSettingsStore((s) => s.enableTransitions);

  if (!enableTransitions) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div
      className={className}
      initial={{ 
        opacity: 0, 
        y: 60, 
        scale: 0.9,
        filter: 'blur(10px)',
      }}
      whileInView={{ 
        opacity: 1, 
        y: 0, 
        scale: 1,
        filter: 'blur(0px)',
      }}
      viewport={{ once: true, margin: '-50px' }}
      transition={{ 
        duration: 0.8, 
        delay,
        ease: [0.22, 1, 0.36, 1],
      }}
    >
      {children}
    </motion.div>
  );
}

/**
 * Horizontal slide reveal
 * Use for content that should slide in from the side
 */
export function SlideReveal({ 
  children, 
  className = '', 
  direction = 'left',
  delay = 0 
}: { 
  children: ReactNode; 
  className?: string; 
  direction?: 'left' | 'right';
  delay?: number;
}) {
  const enableTransitions = useSettingsStore((s) => s.enableTransitions);

  if (!enableTransitions) {
    return <div className={className}>{children}</div>;
  }

  const xOffset = direction === 'left' ? -80 : 80;

  return (
    <motion.div
      className={className}
      initial={{ 
        opacity: 0, 
        x: xOffset,
        filter: 'blur(8px)',
      }}
      whileInView={{ 
        opacity: 1, 
        x: 0,
        filter: 'blur(0px)',
      }}
      viewport={{ once: true, margin: '-50px' }}
      transition={{ 
        duration: 0.7, 
        delay,
        ease: [0.22, 1, 0.36, 1],
      }}
    >
      {children}
    </motion.div>
  );
}

export default PageTransition;

'use client';

import React from 'react';
import { motion, Variants } from 'framer-motion';
import { cn } from '@/lib/utils';

// Gradient animated text
interface GradientTextProps {
  children: string;
  className?: string;
  animate?: boolean;
  from?: string;
  via?: string;
  to?: string;
}

export function GradientText({ 
  children, 
  className, 
  animate = true,
  from,
  via,
  to,
}: GradientTextProps) {
  // Build gradient - use custom colors if provided, otherwise use CSS variables
  const gradientStyle = from && to 
    ? {
        backgroundImage: via 
          ? `linear-gradient(90deg, ${from.replace('from-', '')} 0%, ${via.replace('via-', '')} 50%, ${to.replace('to-', '')} 100%)`
          : `linear-gradient(90deg, ${from.replace('from-', '')} 0%, ${to.replace('to-', '')} 100%)`
      }
    : {
        backgroundImage: 'linear-gradient(90deg, var(--color-primary), var(--color-secondary), var(--color-accent), var(--color-primary))',
      };

  // Convert Tailwind class names to actual colors
  const tailwindToColor = (cls: string): string => {
    const colorMap: Record<string, string> = {
      // Cyan
      'cyan-400': '#22d3ee', 'cyan-500': '#06b6d4', 'cyan-600': '#0891b2',
      // Teal
      'teal-400': '#2dd4bf', 'teal-500': '#14b8a6', 'teal-600': '#0d9488',
      // Emerald/Green
      'emerald-400': '#34d399', 'emerald-500': '#10b981', 'emerald-600': '#059669',
      'green-400': '#4ade80', 'green-500': '#22c55e', 'green-600': '#16a34a',
      // Blue
      'blue-400': '#60a5fa', 'blue-500': '#3b82f6', 'blue-600': '#2563eb',
      // Orange/Amber
      'orange-400': '#fb923c', 'orange-500': '#f97316', 'orange-600': '#ea580c',
      'amber-400': '#fbbf24', 'amber-500': '#f59e0b', 'amber-600': '#d97706',
      // Pink/Rose
      'pink-400': '#f472b6', 'pink-500': '#ec4899', 'pink-600': '#db2777',
      'rose-400': '#fb7185', 'rose-500': '#f43f5e',
      // Slate
      'slate-600': '#475569', 'slate-700': '#334155', 'slate-800': '#1e293b',
    };
    // Strip prefix
    const color = cls.replace(/^(from-|via-|to-)/, '');
    return colorMap[color] || cls;
  };

  const computedStyle = from && to 
    ? {
        backgroundImage: via 
          ? `linear-gradient(90deg, ${tailwindToColor(from)} 0%, ${tailwindToColor(via)} 50%, ${tailwindToColor(to)} 100%)`
          : `linear-gradient(90deg, ${tailwindToColor(from)} 0%, ${tailwindToColor(to)} 100%)`
      }
    : {
        backgroundImage: 'linear-gradient(90deg, var(--color-primary), var(--color-secondary), var(--color-accent), var(--color-primary))',
      };

  return (
    <span
      className={cn(
        'bg-clip-text text-transparent',
        animate && 'animate-gradient bg-[length:400%_100%]',
        className
      )}
      style={computedStyle}
    >
      {children}
    </span>
  );
}

// Text that reveals character by character
interface TypewriterTextProps {
  text: string;
  className?: string;
  delay?: number;
  speed?: number;
}

export function TypewriterText({
  text,
  className,
  delay = 0,
  speed = 0.05,
}: TypewriterTextProps) {
  const characters = text.split('');

  return (
    <span className={className}>
      {characters.map((char, index) => (
        <motion.span
          key={index}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{
            duration: 0.1,
            delay: delay + index * speed,
          }}
        >
          {char}
        </motion.span>
      ))}
    </span>
  );
}

// Staggered text animation word by word
interface StaggerTextProps {
  children: string;
  className?: string;
  wordClassName?: string;
  delay?: number;
  staggerDelay?: number;
  once?: boolean;
}

export function StaggerText({
  children,
  className,
  wordClassName,
  delay = 0,
  staggerDelay = 0.1,
  once = true,
}: StaggerTextProps) {
  const words = children.split(' ');

  const container: Variants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: staggerDelay,
        delayChildren: delay,
      },
    },
  };

  const wordAnimation: Variants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        type: 'spring',
        damping: 12,
        stiffness: 100,
      },
    },
  };

  return (
    <motion.span
      className={cn('inline-flex flex-wrap gap-x-[0.25em]', className)}
      variants={container}
      initial="hidden"
      whileInView="visible"
      viewport={{ once }}
    >
      {words.map((word, index) => (
        <motion.span
          key={index}
          variants={wordAnimation}
          className={cn('inline-block', wordClassName)}
        >
          {word}
        </motion.span>
      ))}
    </motion.span>
  );
}

// Animated heading with line reveal
interface RevealHeadingProps {
  children: React.ReactNode;
  className?: string;
  as?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6';
}

export function RevealHeading({
  children,
  className,
  as: Component = 'h2',
}: RevealHeadingProps) {
  return (
    <div className="overflow-hidden">
      <motion.div
        initial={{ y: '100%' }}
        whileInView={{ y: 0 }}
        viewport={{ once: true }}
        transition={{
          duration: 0.6,
          ease: [0.22, 1, 0.36, 1],
        }}
      >
        <Component className={className}>{children}</Component>
      </motion.div>
    </div>
  );
}

// Blur reveal text
interface BlurRevealProps {
  children: React.ReactNode;
  className?: string;
  delay?: number;
}

export function BlurReveal({ children, className, delay = 0 }: BlurRevealProps) {
  return (
    <motion.div
      className={className}
      initial={{ filter: 'blur(10px)', opacity: 0 }}
      whileInView={{ filter: 'blur(0px)', opacity: 1 }}
      viewport={{ once: true }}
      transition={{
        duration: 0.8,
        delay,
        ease: 'easeOut',
      }}
    >
      {children}
    </motion.div>
  );
}

// Highlighted text with animated underline
interface HighlightTextProps {
  children: string;
  className?: string;
  highlightColor?: string;
}

export function HighlightText({
  children,
  className,
  highlightColor = 'var(--color-accent)',
}: HighlightTextProps) {
  return (
    <span className={cn('relative inline-block', className)}>
      {children}
      <motion.span
        className="absolute bottom-0 left-0 h-[0.15em] w-full"
        style={{ backgroundColor: highlightColor, opacity: 0.4 }}
        initial={{ scaleX: 0, transformOrigin: 'left' }}
        whileInView={{ scaleX: 1 }}
        viewport={{ once: true }}
        transition={{ duration: 0.6, delay: 0.3, ease: 'easeOut' }}
      />
    </span>
  );
}

// Letter by letter hover effect
interface HoverLettersProps {
  children: string;
  className?: string;
}

export function HoverLetters({ children, className }: HoverLettersProps) {
  return (
    <span className={cn('inline-flex', className)}>
      {children.split('').map((char, index) => (
        <motion.span
          key={index}
          className="inline-block"
          whileHover={{
            y: -5,
            color: 'var(--color-primary)',
            transition: { duration: 0.1 },
          }}
        >
          {char === ' ' ? '\u00A0' : char}
        </motion.span>
      ))}
    </span>
  );
}

'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import { useTranslations, useLocale } from 'next-intl';
import { ThemeToggle } from '../ThemeToggle';
import { LanguageSwitcher } from '../LanguageSwitcher';
import { CurrencySwitcher } from '../CurrencySwitcher';
import { UserPreferencesModal } from '../settings/UserPreferencesModal';
import {
  UtensilsCrossed,
  Home,
  Waves,
  Cookie,
  Menu,
  X,
  User,
  ShoppingCart,
  Settings,
  Link as LinkIcon
} from 'lucide-react';
import { useState, useEffect, useMemo } from 'react';
import { useAuth } from '@/lib/auth-context';
import { useCartStore } from '@/stores/cartStore';
import { cn } from '@/lib/cn';
import { useTerminology } from '@/hooks/useTerminology';
import { useSiteSettings } from '@/lib/settings-context';

// ... inside Header component
export default function Header() {
  const { settings, modules } = useSiteSettings();
  const { terms } = useTerminology();
  const locale = useLocale();
  const pathname = usePathname();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [preferencesOpen, setPreferencesOpen] = useState(false);
  const [mounted, setMounted] = useState(false);
  const { user, isAuthenticated } = useAuth();
  const cartCount = useCartStore((s) => s.getCount());

  const t = useTranslations('nav');
  const tCommon = useTranslations('common');

  // Prevent hydration mismatch by only rendering client-specific content after mount
  useEffect(() => {
    setMounted(true);
  }, []);

  // Handle scroll effect
  useEffect(() => {
    const isSticky = settings.navbar?.config?.sticky !== false;
    if (!isSticky) {
      setScrolled(false);
      return;
    }
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [settings.navbar?.config?.sticky]);

  interface ModuleIcon {
    slug: string;
    template_type: string;
  }
  const getIconForModule = (module: ModuleIcon) => {
    // Specific icons for default modules
    if (module.slug === 'restaurant') return UtensilsCrossed;
    if (module.slug === 'snack-bar') return Cookie;
    if (module.slug === 'pool') return Waves;
    if (module.slug === 'chalets') return Home;

    // Generic icons based on type
    switch (module.template_type) {
      case 'menu_service': return UtensilsCrossed;
      case 'multi_day_booking': return Home;
      case 'session_access': return Waves;
      default: return Home;
    }
  };

  const getIconByName = (name: string) => {
    type IconComponent = typeof Home | typeof UtensilsCrossed | typeof Waves | typeof Cookie | typeof LinkIcon | typeof User | typeof ShoppingCart | typeof Settings;
    const icons: Record<string, IconComponent> = {
      Home,
      UtensilsCrossed,
      Waves,
      Cookie,
      Link: LinkIcon,
      User,
      ShoppingCart,
      Settings
    };
    return icons[name] || Home;
  };

  // Get translated name for module - dynamic lookup with fallback
  const getModuleTranslatedName = (slug: string, fallbackName: string) => {
    // Dynamic Terminology Overrides
    if (slug === 'chalets' && terms?.unit_plural) return terms.unit_plural;
    if (slug === 'pool' && terms?.facility_singular) return terms.facility_singular;
    if (slug === 'restaurant' && terms?.dining_singular) return terms.dining_singular;

    // Known translation keys mapping
    const knownKeys: Record<string, string> = {
      'restaurant': 'restaurant',
      'chalets': 'chalets',
      'pool': 'pool',
      'snack-bar': 'snackBar',
      'snackbar': 'snackBar',
      'gym': 'gym',
      'spa': 'spa',
      'cafe': 'cafe',
      'chocolate-box': 'chocolateBox',
      'chocolate box': 'chocolateBox',
      'chocolatebox': 'chocolateBox',
    };

    const translationKey = knownKeys[slug.toLowerCase()];
    if (translationKey) {
      try {
        const translated = t(translationKey as any);
        if (translated && translated !== translationKey) {
          return translated;
        }
      } catch {
        // Ignore translation errors
      }
    }

    // Final fallback: use the module name from database (properly formatted)
    return fallbackName;
  };

  interface NavLink {
    type?: string;
    moduleSlug?: string;
    label: string;
    href: string;
    icon?: string;
  }

  interface NavigationItem {
    name: string;
    href: string;
    icon: React.ComponentType<{ className?: string }>;
  }

  // Build navigation from CMS or Fallback - recalculate when locale changes
  // IMPORTANT: Only show modules that are ACTIVE and have show_in_main enabled
  const navigation = useMemo((): NavigationItem[] => {
    // Get list of active modules that should be shown in customer nav
    const activeModules = modules.filter(m => m.is_active && m.show_in_main);
    
    if (settings.navbar?.links && settings.navbar.links.length > 0) {
      // CMS mode: filter links to only include valid, active modules
      const mappedItems = settings.navbar.links
        .map((link: NavLink): NavigationItem | null => {
          if (link.type === 'module') {
            // Case-insensitive module lookup - ONLY show if module is active AND show_in_main
            const module = activeModules.find(m => m.slug.toLowerCase() === link.moduleSlug?.toLowerCase());
            if (module) {
              return {
                name: getModuleTranslatedName(module.slug, module.name),
                href: `/${module.slug}`,
                icon: getIconForModule(module)
              };
            }
            // Module not found or inactive - SKIP this link entirely
            return null;
          }
          // Non-module links (internal/external) - keep as-is
          return {
            name: link.label,
            href: link.href,
            icon: getIconByName(link.icon || 'Home')
          };
        });
      return mappedItems.filter((item): item is NavigationItem => item !== null);
    }
    
    // Fallback: Auto-generate from active modules
    return [
      { name: t('home'), href: '/', icon: Home },
      ...activeModules
        .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
        .map(m => ({
          name: getModuleTranslatedName(m.slug, m.name),
          href: `/${m.slug}`,
          icon: getIconForModule(m)
        }))
    ];
  }, [settings.navbar?.links, modules, locale, t]);

  // ...existing code...

  // Don't show header on admin or staff pages
  if (pathname?.startsWith('/admin') || pathname?.startsWith('/staff')) {
    return null;
  }

  const navConfig = settings.navbar?.config || {
    showLanguageSwitcher: true,
    showThemeToggle: true,
    showCurrencySwitcher: true,
    showUserPreferences: true,
    showCart: true,
    sticky: true
  };

  return (
    <motion.header
      initial={{ y: -100, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ type: 'spring', stiffness: 300, damping: 30 }}
      className={cn(
        navConfig.sticky ? 'sticky top-0 z-50' : 'relative z-50',
        'transition-all duration-500',
        scrolled
