// Type definitions for menu and session data
interface MenuItem {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  description?: string;
  description_ar?: string;
  description_fr?: string;
  price: number;
  image_url?: string;
  image?: string;
  category_id: string;
  is_available: boolean;
}

interface MenuCategory {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  sort_order: number;
}

interface PoolSession {
  id: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  description?: string;
  description_ar?: string;
  description_fr?: string;
  start_time: string;
  end_time: string;
  capacity: number;
