// Flatten all navigation items for search
export function flattenNavigation(categories: NavCategory[]): Array<{ name: string; href: string; category: string }> {
  const items: Array<{ name: string; href: string; category: string }> = [];
  
  for (const category of categories) {
    for (const item of category.items) {
      items.push({ name: item.name, href: item.href, category: category.name });
      if (item.children) {
        for (const child of item.children) {
          items.push({ name: child.name, href: child.href, category: category.name });
        }
      }
    }
  }
  
  return items;
}

// Filter navigation by user roles
export function filterNavigationByRole(categories: NavCategory[], userRoles: string[]): NavCategory[] {
  return categories.map(category => ({
    ...category,
    items: category.items
      .filter(item => !item.roles || item.roles.some(role => userRoles.includes(role)))
      .map(item => ({
        ...item,
        children: item.children?.filter(child => !child.roles || child.roles.some(role => userRoles.includes(role)))
      }))
  })).filter(category => category.items.length > 0);
}

// Local storage keys for persisting expanded state
export const SIDEBAR_EXPANDED_KEY = 'admin-sidebar-expanded';
export const SIDEBAR_CATEGORIES_KEY = 'admin-sidebar-categories';

// Get initial expanded categories from localStorage
export function getInitialExpandedCategories(): string[] {
  if (typeof window === 'undefined') return ['modules'];
  try {
    const saved = localStorage.getItem(SIDEBAR_CATEGORIES_KEY);
    return saved ? JSON.parse(saved) : ['modules'];
  } catch {
    return ['modules'];
  }
}

// Save expanded categories to localStorage
export function saveExpandedCategories(categories: string[]): void {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(SIDEBAR_CATEGORIES_KEY, JSON.stringify(categories));
  } catch {
    // Ignore storage errors
  }
}

'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import type {
  CustomizableEntityType,
  CustomizationGroupWithOptions,
  CustomizationSelection,
  CustomizationValidationResult,
  ValidatedSelection,
} from '@/components/customization/CustomizationSelector';

// Query keys
export const customizationKeys = {
  all: ['customizations'] as const,
  forEntity: (entityType: CustomizableEntityType, entityId: string) =>
    [...customizationKeys.all, 'entity', entityType, entityId] as const,
  groups: () => [...customizationKeys.all, 'groups'] as const,
  group: (id: string) => [...customizationKeys.groups(), id] as const,
  order: (orderType: string, orderId: string) =>
    [...customizationKeys.all, 'order', orderType, orderId] as const,
};

/**
 * Hook to fetch customizations available for an entity
 */
export function useEntityCustomizations(
  entityType: CustomizableEntityType,
  entityId: string,
  options?: { enabled?: boolean }
) {
  return useQuery({
    queryKey: customizationKeys.forEntity(entityType, entityId),
    queryFn: async () => {
      const response = await api.get<CustomizationGroupWithOptions[]>(
        `/customizations/for-entity/${entityType}/${entityId}`
      );
      return response.data;
    },
    enabled: options?.enabled !== false && !!entityId,
    staleTime: 5 * 60 * 1000, // 5 minutes
  });
}

/**
 * Hook to validate customization selections
 */
export function useValidateCustomizations() {
  return useMutation({
    mutationFn: async (data: {
      entityType: CustomizableEntityType;
      entityId: string;
      selections: CustomizationSelection[];
    }) => {
      const response = await api.post<CustomizationValidationResult>(
        '/customizations/validate',
        data
      );
      return response.data;
    },
  });
}

/**
 * Hook to get customizations for a placed order
 */
export function useOrderCustomizations(
  orderType: string,
  orderId: string,
  orderItemId?: string,
  options?: { enabled?: boolean }
) {
  return useQuery({
    queryKey: [...customizationKeys.order(orderType, orderId), orderItemId],
    queryFn: async () => {
      const params = orderItemId ? `?orderItemId=${orderItemId}` : '';
      const response = await api.get<Array<{
        groupName: string;
        options: Array<{
          name: string;
          type: string;
          quantity: number;
          priceAdjustment: number;
        }>;
      }>>(`/customizations/orders/${orderType}/${orderId}${params}`);
      return response.data;
    },
    enabled: options?.enabled !== false && !!orderId,
  });
}

