'use client';

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useRouter } from 'next/navigation';
import { api, API_BASE_URL } from './api';
import { authLogger } from './logger';

interface User {
  id: string;
  email: string;
  fullName: string;
  phone?: string;
  profileImageUrl?: string;
  preferredLanguage: string;
  roles: string[];
}

interface TwoFactorRequired {
  requiresTwoFactor: true;
  userId: string;
  email: string;
}

interface LoginResult {
  user: User;
  requiresTwoFactor?: false;
}

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, password: string) => Promise<User | TwoFactorRequired>;
  verify2FA: (userId: string, code: string) => Promise<User>;
  logout: () => void;
  refreshUser: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    // Handle OAuth callback - check for tokens in URL
    const handleOAuthCallback = () => {
      if (typeof window === 'undefined') return false;

      const params = new URLSearchParams(window.location.search);
      const oauth = params.get('oauth');
      const accessToken = params.get('accessToken');
      const refreshToken = params.get('refreshToken');

      if (oauth === 'success' && accessToken && refreshToken) {
        // Store tokens from OAuth callback
        localStorage.setItem('accessToken', accessToken);
        localStorage.setItem('refreshToken', refreshToken);

        // Clean URL by removing OAuth params
        const cleanUrl = window.location.pathname;
        window.history.replaceState({}, '', cleanUrl);

        authLogger.info('OAuth tokens received and stored');
        return true;
      }
      return false;
    };

    // Validate stored credentials on mount by checking with the server
    const validateSession = async () => {
      // First check for OAuth callback
      const oauthHandled = handleOAuthCallback();

      const storedUser = localStorage.getItem('user');
      const accessToken = localStorage.getItem('accessToken');

      // If no access token (and OAuth didn't just set one), nothing to validate
      if (!accessToken) {
        setIsLoading(false);
        return;
      }

      try {
        // Validate token with backend using the api instance (which handles token refresh)
        const response = await api.get('/auth/me');

        if (response.data.success && response.data.data) {
          // Use server-validated user data, not localStorage
          const validatedUser: User = {
            id: response.data.data.id,
            email: response.data.data.email,
            fullName: response.data.data.full_name || response.data.data.fullName,
            phone: response.data.data.phone,
            profileImageUrl: response.data.data.profile_image_url || response.data.data.profileImageUrl,
            preferredLanguage: response.data.data.preferred_language || response.data.data.preferredLanguage || 'en',
            roles: response.data.data.roles || []
          };
          setUser(validatedUser);
          // Update localStorage with validated data
          localStorage.setItem('user', JSON.stringify(validatedUser));

          // If this was an OAuth login, log success
          if (oauthHandled) {
            authLogger.info('OAuth login successful for:', validatedUser.email);
          }
        } else {
          throw new Error('Invalid session');
        }
      } catch (e) {
        // Clear invalid session data
        authLogger.warn('Session validation failed, clearing credentials');
        localStorage.removeItem('user');
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
        setUser(null);
      }

      setIsLoading(false);
    };

    validateSession();
  }, []);

  const login = async (email: string, password: string): Promise<User | TwoFactorRequired> => {
    const response = await api.post('/auth/login', { email, password });
    const data = response.data;

    if (!data.success) {
      throw new Error(data.error || 'Login failed');
    }

    // Check if 2FA is required
    if (data.data.requiresTwoFactor) {
      return {
        requiresTwoFactor: true,
        userId: data.data.userId,
        email: data.data.email,
      };
    }

    const { user: userData, tokens } = data.data;

    if (!tokens?.accessToken || !tokens?.refreshToken) {
      throw new Error('Invalid login response - missing tokens');
    }

    localStorage.setItem('accessToken', tokens.accessToken);
    localStorage.setItem('refreshToken', tokens.refreshToken);
    localStorage.setItem('user', JSON.stringify(userData));

    setUser(userData);

    return userData;
  };

  const verify2FA = async (userId: string, code: string): Promise<User> => {
    const response = await api.post('/auth/2fa/verify', { userId, code });
    const data = response.data;

    if (!data.success) {
      throw new Error(data.error || '2FA verification failed');
    }

    const { user: userData, tokens } = data.data;

    if (!tokens?.accessToken || !tokens?.refreshToken) {
      throw new Error('Invalid response - missing tokens');
    }

    localStorage.setItem('accessToken', tokens.accessToken);
    localStorage.setItem('refreshToken', tokens.refreshToken);
    localStorage.setItem('user', JSON.stringify(userData));

    setUser(userData);

    return userData;
  };

  const logout = () => {
    // Invalidate server-side session (fire-and-forget)
    const refreshToken = localStorage.getItem('refreshToken');
    api.post('/auth/logout', { refreshToken }).catch(() => {
      // Best-effort: still clear client state even if API call fails
    });
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('user');
    setUser(null);
    router.push('/');
  };

  const refreshUser = () => {
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isLoading,
        isAuthenticated: !!user,
        login,
        verify2FA,
        logout,
        refreshUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
}

import { useEffect } from 'react';
import { useSettingsStore } from '@/stores/settingsStore';

export function HydrateSettingsFromBackend() {
  useEffect(() => {
    async function hydrate() {
      try {
        const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';
        const res = await fetch(`${apiUrl.replace(/\/api\/?$/, '')}/api/settings`);
        if (!res.ok) return;
        const data = await res.json();
        if (data.success && data.data) {
          if (data.data.theme) {
            useSettingsStore.getState().setResortTheme(data.data.theme);
          }
          if (typeof data.data.animationsEnabled === 'boolean') {
            useSettingsStore.getState().setAnimationsEnabled(data.data.animationsEnabled);
          }
          if (typeof data.data.reducedMotion === 'boolean') {
            useSettingsStore.getState().setReducedMotion(data.data.reducedMotion);
          }
          if (typeof data.data.soundEnabled === 'boolean') {
            useSettingsStore.getState().setSoundEnabled(data.data.soundEnabled);
          }
        }
      } catch (err) {
        // Silent fail, fallback to defaults
      }
    }
    hydrate();
  }, []);
  return null;
}

/**
 * Module Utility Functions
 * 
 * Provides helper functions for working with dynamic modules throughout the application.
 * This enables the system to work with any configured modules, not just hardcoded ones.
 */

import { 
  UtensilsCrossed, 
  Home, 
  Waves, 
  Cookie, 
  Dumbbell, 
  Sparkles, 
  Coffee, 
  Bed, 
  Calendar, 
  Users,
  Music,
  Film,
  Gamepad2,
  PartyPopper,
  ShoppingBag,
  Ticket,
  Trophy,
  Heart,
  Star,
  Gift,
  type LucideIcon
} from 'lucide-react';

export interface Module {
  id: string;
  template_type: 'menu_service' | 'multi_day_booking' | 'session_access';
  name: string;
  slug: string;
  description?: string;
  is_active: boolean;
  show_in_main?: boolean;
  settings?: {
    header_color?: string;
    accent_color?: string;
    show_in_nav?: boolean;
    icon?: string;
    [key: string]: string | number | boolean | undefined;
  };
  sort_order: number;
}

/**
 * Icon mapping for modules based on slug or template type
 */
const ICON_MAP: Record<string, LucideIcon> = {
  // Default modules
  'restaurant': UtensilsCrossed,
  'snack-bar': Cookie,
  'snackbar': Cookie,
  'pool': Waves,
  'chalets': Home,
  
  // Common module types
  'gym': Dumbbell,
  'gym-floor': Dumbbell,
  'fitness': Dumbbell,
  'fitness-classes': Dumbbell,
  'spa': Sparkles,
  'cafe': Coffee,
  'coffee': Coffee,
  'hotel-rooms': Bed,
  'rooms': Bed,
  'room-service': UtensilsCrossed,
  'concierge': Users,
  'membership': Trophy,
  'personal-training': Dumbbell,
  
  // Entertainment
  'bar': Coffee,
  'lounge': Music,
  'cinema': Film,
  'gaming': Gamepad2,
  'events': PartyPopper,
  'shop': ShoppingBag,
  'tickets': Ticket,
  
  // Default by template type
  'menu_service': UtensilsCrossed,
  'multi_day_booking': Home,
  'session_access': Ticket,
};

/**
 * Get the appropriate icon component for a module
 */
export function getModuleIcon(module: Module): LucideIcon {
  // First check if module has a custom icon setting
  if (module.settings?.icon && ICON_MAP[module.settings.icon]) {
    return ICON_MAP[module.settings.icon];
  }
  
  // Then check by slug
  const slugLower = module.slug.toLowerCase();
  if (ICON_MAP[slugLower]) {
    return ICON_MAP[slugLower];
  }
  
  // Finally fallback to template type
  return ICON_MAP[module.template_type] || Home;
}

/**
 * Get a default icon by name string
 */
export function getIconByName(name: string): LucideIcon {
  const normalizedName = name.toLowerCase().replace(/[_\s]/g, '-');
  return ICON_MAP[normalizedName] || Home;
}

/**
 * Get only modules that should be shown on the main page
 */
export function getMainPageModules(modules: Module[]): Module[] {
  return modules
    .filter(m => m.is_active && (m.show_in_main !== false))
    .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
}

/**
 * Get modules that should appear in navigation
 */
export function getNavModules(modules: Module[]): Module[] {
  return modules
    .filter(m => m.is_active && (m.settings?.show_in_nav !== false))
    .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
}

/**
 * Generate a description for a module based on its type
 * This is used when the module doesn't have a custom description
 */
export function getModuleDefaultDescription(module: Module): string {
  switch (module.template_type) {
    case 'menu_service':
      return `Browse our ${module.name.toLowerCase()} menu and place orders`;
    case 'multi_day_booking':
      return `Book your stay at our ${module.name.toLowerCase()}`;
    case 'session_access':
      return `Purchase tickets and passes for ${module.name.toLowerCase()}`;
    default:
      return `Explore our ${module.name.toLowerCase()} services`;
  }
}

/**
 * Generate a stat label for a module
 */
export function getModuleStatLabel(module: Module): string {
  switch (module.template_type) {
    case 'menu_service':
      return 'Menu Items';
    case 'multi_day_booking':
      return 'Units Available';
    case 'session_access':
      return 'Daily Visitors';
    default:
      return 'Available';
  }
}

/**
 * Get a placeholder stat value for a module
 * In production, this should be fetched from the actual module data
 */
export function getModuleStatPlaceholder(module: Module): number {
  switch (module.template_type) {
    case 'menu_service':
      return 50;
    case 'multi_day_booking':
      return 10;
    case 'session_access':
      return 100;
    default:
      return 25;
  }
}

/**
 * Offline Sync Manager
 * 
 * Manages synchronization between IndexedDB and the server:
 * - Background sync when online
 * - Conflict resolution
 * - Cache refresh
 * - Sync status notifications
 */

import {
  syncQueue,
  cacheManager,
  menuItemsStore,
  menuCategoriesStore,
  modifiersStore,
  customersStore,
  ordersStore,
  paymentsStore,
  isOnline,
  onOnline,
  onOffline,
} from './offline-storage';
import api from '@/lib/api';

const API_BASE = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

// Sync configuration
const SYNC_CONFIG = {
  maxRetries: 3,
  retryDelayMs: 5000,
  cacheRefreshIntervalMs: 5 * 60 * 1000, // 5 minutes
  maxCacheAgeMinutes: 60,
};

// Sync status callbacks
type SyncStatusCallback = (status: SyncStatus) => void;
const statusCallbacks: Set<SyncStatusCallback> = new Set();

export interface SyncStatus {
  isOnline: boolean;
  isSyncing: boolean;
  pendingCount: number;
  failedCount: number;
  lastSyncAt: Date | null;
  error: string | null;
}

let currentStatus: SyncStatus = {
  isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
  isSyncing: false,
  pendingCount: 0,
  failedCount: 0,
  lastSyncAt: null,
  error: null,
};

function updateStatus(partial: Partial<SyncStatus>): void {
  currentStatus = { ...currentStatus, ...partial };
  statusCallbacks.forEach((cb) => cb(currentStatus));
}

export function subscribeToSyncStatus(callback: SyncStatusCallback): () => void {
  statusCallbacks.add(callback);
  callback(currentStatus);
  return () => statusCallbacks.delete(callback);
}

export function getSyncStatus(): SyncStatus {
  return { ...currentStatus };
}

/**
 * Initialize offline sync manager
 */
export async function initOfflineSync(): Promise<void> {
  // Update online status
  onOnline(() => {
    updateStatus({ isOnline: true });
    syncAll();
  });

  onOffline(() => {
    updateStatus({ isOnline: false });
  });

  // Initial cache refresh if online
  if (isOnline()) {
    await refreshAllCaches();
  }

  // Update pending count
  const stats = await syncQueue.getStats();
  updateStatus({
    pendingCount: stats.pending,
    failedCount: stats.failed,
  });

  // Start periodic sync
  setInterval(() => {
    if (isOnline() && !currentStatus.isSyncing) {
      syncAll();
    }
  }, SYNC_CONFIG.cacheRefreshIntervalMs);
}

/**
 * Refresh all caches from server
 */
export async function refreshAllCaches(): Promise<void> {
  if (!isOnline()) return;

  try {
    await Promise.all([
      refreshMenuCache(),
      refreshCustomerCache(),
    ]);
    
    updateStatus({ lastSyncAt: new Date(), error: null });
  } catch (error) {
    console.error('Cache refresh failed:', error);
    updateStatus({ error: error instanceof Error ? error.message : 'Cache refresh failed' });
  }
}

/**
 * Refresh menu data cache
 */
export async function refreshMenuCache(): Promise<void> {
  const isStale = await cacheManager.isStale('menu_items', SYNC_CONFIG.maxCacheAgeMinutes);
  if (!isStale && !isOnline()) return;

  try {
    // Fetch menu items
    const menuResponse = await api.get('/restaurant/menu');
    const menuData = menuResponse.data;
    
    // Store menu items
    if (menuData.items) {
      await menuItemsStore.clear();
      await menuItemsStore.putMany(menuData.items);
      await cacheManager.updateMetadata('menu_items', menuData.items.length);
    }
    
    // Store categories
    if (menuData.categories) {
      await menuCategoriesStore.clear();
      await menuCategoriesStore.putMany(menuData.categories);
      await cacheManager.updateMetadata('menu_categories', menuData.categories.length);
    }

    // Fetch modifiers
    const modifiersResponse = await api.get('/restaurant/modifiers');
    const modifiersData = modifiersResponse.data;
    if (modifiersData.modifiers) {
      await modifiersStore.clear();
      await modifiersStore.putMany(modifiersData.modifiers);
      await cacheManager.updateMetadata('modifiers', modifiersData.modifiers.length);
    }
  } catch (error) {
    console.error('Menu cache refresh failed:', error);
    throw error;
  }
}

/**
 * Refresh customer data cache (recent customers only)
 */
export async function refreshCustomerCache(): Promise<void> {
  const isStale = await cacheManager.isStale('customers', SYNC_CONFIG.maxCacheAgeMinutes);
  if (!isStale && !isOnline()) return;

  try {
    const response = await api.get('/users?role=customer&limit=500&sort=last_visit:desc');
    const data = response.data;
    
    if (data.users) {
      // Don't clear - merge with existing data
      for (const customer of data.users) {
        await customersStore.put(customer);
      }
      await cacheManager.updateMetadata('customers', await customersStore.count());
    }
  } catch (error) {
    console.error('Customer cache refresh failed:', error);
    throw error;
  }
}

/**
 * Sync all pending items to server
 */
export async function syncAll(): Promise<{ synced: number; failed: number }> {
  if (!isOnline() || currentStatus.isSyncing) {
    return { synced: 0, failed: 0 };
  }

  updateStatus({ isSyncing: true });
  
  let synced = 0;
  let failed = 0;

  try {
    // Get all pending items
    const pending = await syncQueue.getPending();
    
    for (const item of pending) {
      try {
        await syncItem(item);
        await syncQueue.remove(item.id);
        synced++;
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        
        // Update item status
        if (item.attempts >= SYNC_CONFIG.maxRetries) {
          await syncQueue.updateStatus(item.id, 'failed', errorMessage);
          failed++;
        } else {
          await syncQueue.updateStatus(item.id, 'pending', errorMessage);
        }
      }
    }

    // Update status
    const stats = await syncQueue.getStats();
    updateStatus({
      isSyncing: false,
      pendingCount: stats.pending,
      failedCount: stats.failed,
      lastSyncAt: new Date(),
      error: null,
    });

    // Refresh caches after sync
    await refreshAllCaches();

  } catch (error) {
    updateStatus({
      isSyncing: false,
      error: error instanceof Error ? error.message : 'Sync failed',
    });
  }

  return { synced, failed };
}

/**
 * Sync a single queue item
 */
async function syncItem(item: { entityType: string; entityId: string; operation: string; data: unknown }): Promise<void> {
  const { entityType, entityId, operation, data } = item;
  
  let endpoint: string;
  let method: string;
  
  switch (entityType) {
    case 'order':
      endpoint = operation === 'create' 
        ? `${API_BASE}/api/v1/restaurant/orders`
        : `${API_BASE}/api/v1/restaurant/orders/${entityId}`;
      break;
    case 'payment':
      endpoint = `${API_BASE}/api/v1/payments`;
      break;
    default:
      throw new Error(`Unknown entity type: ${entityType}`);
  }

  switch (operation) {
    case 'create':
      method = 'POST';
      break;
    case 'update':
      method = 'PUT';
      break;
    case 'delete':
      method = 'DELETE';
      break;
    default:
      throw new Error(`Unknown operation: ${operation}`);
  }

  const response = await api({
    url: endpoint.replace(`${API_BASE}/api/v1`, ''),
    method,
    data: operation !== 'delete' ? data : undefined,
  });

  if (response.status >= 400) {
    throw new Error(`HTTP ${response.status}`);
  }

  // If this was an offline order, update local record with server ID
  if (entityType === 'order' && operation === 'create') {
    const result = response.data;
    if (result.id && result.id !== entityId) {
      // Update local order with server ID
      const localOrder = await ordersStore.getById(entityId);
      if (localOrder) {
        await ordersStore.delete(entityId);
        await ordersStore.put({ ...localOrder, id: result.id, synced: true });
      }
    }
  }
}

/**
 * Create an offline order
 */
export async function createOfflineOrder(orderData: {
  tableId?: string;
  items: Array<{
    menuItemId: string;
    quantity: number;
    notes?: string;
    modifiers?: string[];
  }>;
  customerId?: string;
  notes?: string;
}): Promise<string> {
  const offlineId = `offline_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  
  const order = {
    id: offlineId,
    ...orderData,
    status: 'pending',
    created_at: new Date().toISOString(),
    synced: false,
  };

  // Save to local store
  await ordersStore.put(order);

  // Add to sync queue
  await syncQueue.add({
    entityType: 'order',
    entityId: offlineId,
    operation: 'create',
    data: orderData,
  });

  // Update pending count
  const stats = await syncQueue.getStats();
  updateStatus({ pendingCount: stats.pending });

  // Try to sync immediately if online
  if (isOnline()) {
    syncAll();
  }

  return offlineId;
}

/**
 * Get menu items from cache
 */
export async function getOfflineMenuItems(): Promise<unknown[]> {
  return menuItemsStore.getAll();
}

/**
 * Get menu categories from cache
 */
export async function getOfflineCategories(): Promise<unknown[]> {
  return menuCategoriesStore.getAll();
}

/**
 * Get customers from cache
 */
export async function getOfflineCustomers(): Promise<unknown[]> {
  return customersStore.getAll();
}

/**
 * Search customers in cache
 */
export async function searchOfflineCustomers(query: string): Promise<unknown[]> {
  const customers = await customersStore.getAll();
  const lowerQuery = query.toLowerCase();
  
  return customers.filter((c: any) => 
    c.email?.toLowerCase().includes(lowerQuery) ||
    c.first_name?.toLowerCase().includes(lowerQuery) ||
    c.last_name?.toLowerCase().includes(lowerQuery) ||
    c.phone?.includes(query)
  );
}

/**
 * Get unsent orders
 */
export async function getUnsentOrders(): Promise<unknown[]> {
  // Get all orders and filter for unsynced ones
  // (IndexedDB doesn't support boolean index keys directly)
  const allOrders = await ordersStore.getAll();
  return allOrders.filter((order) => !order.synced);
}

/**
 * Force retry failed items
 */
export async function retryFailedItems(): Promise<{ retried: number }> {
  const failed = await syncQueue.getFailed();
  
  for (const item of failed) {
    await syncQueue.updateStatus(item.id, 'pending');
  }

  // Update counts
  const stats = await syncQueue.getStats();
  updateStatus({
    pendingCount: stats.pending,
    failedCount: stats.failed,
  });

  // Trigger sync
  if (isOnline()) {
    syncAll();
  }

  return { retried: failed.length };
}

/**
 * Clear all offline data
 */
export async function clearOfflineData(): Promise<void> {
  await Promise.all([
    menuItemsStore.clear(),
    menuCategoriesStore.clear(),
    modifiersStore.clear(),
    customersStore.clear(),
    ordersStore.clear(),
    paymentsStore.clear(),
    syncQueue.clear(),
  ]);

  updateStatus({
    pendingCount: 0,
    failedCount: 0,
    lastSyncAt: null,
  });
}

/**
 * ESC/POS Receipt Printer Service
 * 
 * Provides printing capabilities for thermal receipt printers:
 * - USB and Network printer support
 * - ESC/POS command generation
 * - Receipt and kitchen ticket templates
 */

// WebUSB types (for browsers that support it)
import api from '@/lib/api';
declare global {
  interface Navigator {
    usb?: {
      requestDevice(options: { filters: Array<{ vendorId?: number; productId?: number }> }): Promise<USBDevice>;
      getDevices(): Promise<USBDevice[]>;
    };
  }
  
  interface USBDevice {
    configuration: USBConfiguration | null;
    open(): Promise<void>;
    close(): Promise<void>;
    selectConfiguration(configurationValue: number): Promise<void>;
    claimInterface(interfaceNumber: number): Promise<void>;
    releaseInterface(interfaceNumber: number): Promise<void>;
    transferOut(endpointNumber: number, data: ArrayBuffer | ArrayBufferView): Promise<USBOutTransferResult>;
  }
  
  interface USBConfiguration {
    configurationValue: number;
    interfaces: USBInterface[];
  }
  
  interface USBInterface {
    interfaceNumber: number;
    alternate: USBAlternateInterface;
  }
  
  interface USBAlternateInterface {
    endpoints: USBEndpoint[];
  }
  
  interface USBEndpoint {
    direction: 'in' | 'out';
    endpointNumber: number;
  }
  
  interface USBOutTransferResult {
    bytesWritten: number;
    status: 'ok' | 'stall' | 'babble';
  }
}

// ESC/POS Commands
const ESC = 0x1b;
const GS = 0x1d;
const LF = 0x0a;

export const ESCPOS = {
  // Text formatting
  INIT: [ESC, 0x40], // Initialize printer
  BOLD_ON: [ESC, 0x45, 0x01],
  BOLD_OFF: [ESC, 0x45, 0x00],
  UNDERLINE_ON: [ESC, 0x2d, 0x01],
  UNDERLINE_OFF: [ESC, 0x2d, 0x00],
  DOUBLE_WIDTH: [GS, 0x21, 0x10],
  DOUBLE_HEIGHT: [GS, 0x21, 0x01],
  NORMAL_SIZE: [GS, 0x21, 0x00],
  
  // Alignment
  ALIGN_LEFT: [ESC, 0x61, 0x00],
  ALIGN_CENTER: [ESC, 0x61, 0x01],
  ALIGN_RIGHT: [ESC, 0x61, 0x02],
  
  // Paper control
  CUT_PAPER: [GS, 0x56, 0x00], // Full cut
  PARTIAL_CUT: [GS, 0x56, 0x01],
  FEED_LINES: (n: number) => [ESC, 0x64, n],
  
  // Cash drawer
  OPEN_DRAWER: [ESC, 0x70, 0x00, 0x19, 0xfa],
  
  // Barcode
  BARCODE_HEIGHT: (n: number) => [GS, 0x68, n],
  BARCODE_WIDTH: (n: number) => [GS, 0x77, n],
  BARCODE_CODE39: (data: string) => [GS, 0x6b, 0x04, ...textToBytes(data), 0x00],
  
  // QR Code
  QR_SIZE: (n: number) => [GS, 0x28, 0x6b, 0x03, 0x00, 0x31, 0x43, n],
  QR_DATA: (data: string) => {
    const bytes = textToBytes(data);
    const len = bytes.length + 3;
    return [GS, 0x28, 0x6b, len & 0xff, (len >> 8) & 0xff, 0x31, 0x50, 0x30, ...bytes];
  },
  QR_PRINT: [GS, 0x28, 0x6b, 0x03, 0x00, 0x31, 0x51, 0x30],
};

function textToBytes(text: string): number[] {
  return Array.from(new TextEncoder().encode(text));
}

// Printer interface
interface PrinterConfig {
  type: 'usb' | 'network' | 'bluetooth';
  address?: string; // IP address for network printer
  port?: number; // Port for network printer (default 9100)
  vendorId?: number; // USB vendor ID
  productId?: number; // USB product ID
  characterSet?: 'cp437' | 'cp850' | 'cp858' | 'utf8';
  width?: 48 | 42 | 32; // Characters per line
}

interface PrintJob {
  id: string;
  data: Uint8Array;
  status: 'pending' | 'printing' | 'completed' | 'failed';
  error?: string;
  createdAt: Date;
}

// Print queue
const printQueue: PrintJob[] = [];
let isProcessing = false;

/**
 * ESC/POS Document Builder
 */
export class ReceiptBuilder {
  private buffer: number[] = [];
  private width: number;

  constructor(width: number = 48) {
    this.width = width;
    this.init();
  }

  init(): this {
    this.buffer.push(...ESCPOS.INIT);
    return this;
  }

  text(content: string): this {
    this.buffer.push(...textToBytes(content));
    return this;
  }

  newLine(): this {
    this.buffer.push(LF);
    return this;
  }

  line(content: string): this {
    return this.text(content).newLine();
  }

  bold(enabled = true): this {
    this.buffer.push(...(enabled ? ESCPOS.BOLD_ON : ESCPOS.BOLD_OFF));
    return this;
  }

  underline(enabled = true): this {
    this.buffer.push(...(enabled ? ESCPOS.UNDERLINE_ON : ESCPOS.UNDERLINE_OFF));
    return this;
  }

  doubleWidth(): this {
    this.buffer.push(...ESCPOS.DOUBLE_WIDTH);
    return this;
  }

  doubleHeight(): this {
    this.buffer.push(...ESCPOS.DOUBLE_HEIGHT);
    return this;
  }

  normalSize(): this {
    this.buffer.push(...ESCPOS.NORMAL_SIZE);
    return this;
  }

  alignLeft(): this {
    this.buffer.push(...ESCPOS.ALIGN_LEFT);
    return this;
  }

  alignCenter(): this {
    this.buffer.push(...ESCPOS.ALIGN_CENTER);
    return this;
  }

  alignRight(): this {
    this.buffer.push(...ESCPOS.ALIGN_RIGHT);
    return this;
  }

  divider(char = '-'): this {
    return this.line(char.repeat(this.width));
  }

  row(left: string, right: string): this {
    const spaces = this.width - left.length - right.length;
    return this.line(left + ' '.repeat(Math.max(1, spaces)) + right);
  }

  feed(lines = 1): this {
    this.buffer.push(...ESCPOS.FEED_LINES(lines));
    return this;
  }

  cut(partial = false): this {
    this.buffer.push(...(partial ? ESCPOS.PARTIAL_CUT : ESCPOS.CUT_PAPER));
    return this;
  }

  openDrawer(): this {
    this.buffer.push(...ESCPOS.OPEN_DRAWER);
    return this;
  }

  qrCode(data: string, size = 6): this {
    this.buffer.push(...ESCPOS.QR_SIZE(size));
    this.buffer.push(...ESCPOS.QR_DATA(data));
    this.buffer.push(...ESCPOS.QR_PRINT);
    return this;
  }

  barcode(data: string, height = 50): this {
    this.buffer.push(...ESCPOS.BARCODE_HEIGHT(height));
    this.buffer.push(...ESCPOS.BARCODE_CODE39(data));
    return this;
  }

  build(): Uint8Array {
    return new Uint8Array(this.buffer);
  }
}

/**
 * Receipt Template - Customer Receipt
 */
export function buildCustomerReceipt(order: {
  orderNumber: string;
  date: Date;
  items: Array<{
    name: string;
    quantity: number;
    price: number;
    modifiers?: string[];
  }>;
  subtotal: number;
  tax: number;
  tip?: number;
  total: number;
  paymentMethod: string;
  serverName?: string;
  tableName?: string;
  businessInfo: {
    name: string;
    address?: string;
    phone?: string;
    website?: string;
  };
}): Uint8Array {
  const builder = new ReceiptBuilder(48);

  // Header
  builder
    .alignCenter()
    .bold()
    .doubleHeight()
    .line(order.businessInfo.name)
    .normalSize()
    .bold(false);

  if (order.businessInfo.address) {
    builder.line(order.businessInfo.address);
  }
  if (order.businessInfo.phone) {
    builder.line(order.businessInfo.phone);
  }

  builder
    .newLine()
    .divider('=')
    .alignLeft()
    .line(`Order: #${order.orderNumber}`)
    .line(`Date: ${order.date.toLocaleDateString()} ${order.date.toLocaleTimeString()}`);

  if (order.tableName) {
    builder.line(`Table: ${order.tableName}`);
  }
  if (order.serverName) {
    builder.line(`Server: ${order.serverName}`);
  }

  builder.divider();

  // Items
  for (const item of order.items) {
    const itemTotal = (item.quantity * item.price).toFixed(2);
    builder.row(`${item.quantity}x ${item.name}`, `$${itemTotal}`);
    
    if (item.modifiers && item.modifiers.length > 0) {
      for (const mod of item.modifiers) {
        builder.line(`   - ${mod}`);
      }
    }
  }

  builder.divider();

  // Totals
  builder
    .row('Subtotal:', `$${order.subtotal.toFixed(2)}`)
    .row('Tax:', `$${order.tax.toFixed(2)}`);

  if (order.tip) {
    builder.row('Tip:', `$${order.tip.toFixed(2)}`);
  }

  builder
    .divider()
    .bold()
    .row('TOTAL:', `$${order.total.toFixed(2)}`)
    .bold(false)
    .newLine()
    .line(`Paid by: ${order.paymentMethod}`);

  // Footer
  builder
    .newLine()
    .alignCenter()
    .line('Thank you for dining with us!')
    .newLine();

  if (order.businessInfo.website) {
    builder.line(order.businessInfo.website);
  }

  builder.feed(3).cut();

  return builder.build();
}

/**
 * Kitchen Ticket Template
 */
export function buildKitchenTicket(order: {
  orderNumber: string;
  date: Date;
  items: Array<{
    name: string;
    quantity: number;
    modifiers?: string[];
    notes?: string;
    station?: string;
  }>;
  tableName?: string;
  serverName?: string;
  notes?: string;
  priority?: 'normal' | 'rush';
}): Uint8Array {
  const builder = new ReceiptBuilder(42);

  // Header with large text
  builder
    .alignCenter()
    .bold()
    .doubleWidth()
    .doubleHeight();

  if (order.priority === 'rush') {
    builder.line('*** RUSH ***');
  }

  builder
    .line(`#${order.orderNumber}`)
    .normalSize()
    .bold(false)
    .newLine();

  // Order info
  builder
    .alignLeft()
    .line(`Time: ${order.date.toLocaleTimeString()}`);

  if (order.tableName) {
    builder.bold().line(`Table: ${order.tableName}`).bold(false);
  }
  if (order.serverName) {
    builder.line(`Server: ${order.serverName}`);
  }

  builder.divider('=');

  // Items
  for (const item of order.items) {
    builder
      .bold()
      .doubleHeight()
      .line(`${item.quantity}x ${item.name}`)
      .normalSize()
      .bold(false);

    if (item.modifiers && item.modifiers.length > 0) {
      for (const mod of item.modifiers) {
        builder.line(`  ** ${mod}`);
      }
    }

    if (item.notes) {
      builder.line(`  NOTE: ${item.notes}`);
    }

    builder.newLine();
  }

  // Order notes
  if (order.notes) {
    builder
      .divider()
      .bold()
      .line('ORDER NOTES:')
      .bold(false)
      .line(order.notes);
  }

  builder.feed(3).cut();

  return builder.build();
}

/**
 * Network Printer Connection
 */
export async function printToNetworkPrinter(
  address: string,
  port: number,
  data: Uint8Array
): Promise<void> {
  // In a real implementation, this would use WebSocket or a backend proxy
  // because browsers can't directly open TCP connections
  const response = await api.post('/pos/print', {
    printerAddress: address,
    printerPort: port,
    data: Array.from(data),
  });

  if (!response.data?.success && response.status >= 400) {
    throw new Error(response.data?.message || 'Print failed');
  }
}

/**
 * USB Printer Connection (WebUSB API)
 */
export async function connectUSBPrinter(): Promise<USBDevice | null> {
  if (!navigator.usb) {
    console.warn('WebUSB not supported');
    return null;
  }

  try {
    const device = await navigator.usb.requestDevice({
      filters: [
        // Common receipt printer vendor IDs
        { vendorId: 0x0416 }, // Winbond (Star printers)
        { vendorId: 0x04b8 }, // Seiko Epson
        { vendorId: 0x0519 }, // Star Micronics
        { vendorId: 0x0dd4 }, // Custom Engineering
      ],
    });

    await device.open();
    
    // Select first configuration
    if (device.configuration === null) {
      await device.selectConfiguration(1);
    }
    
    // Claim first interface
    await device.claimInterface(0);
    
    return device;
  } catch (error) {
    console.error('Failed to connect USB printer:', error);
    return null;
  }
}

export async function printToUSBPrinter(device: USBDevice, data: Uint8Array): Promise<void> {
  // Find the OUT endpoint
  const endpoint = device.configuration?.interfaces[0]?.alternate.endpoints.find(
    (e) => e.direction === 'out'
  );

  if (!endpoint) {
    throw new Error('No OUT endpoint found');
  }

  await device.transferOut(endpoint.endpointNumber, data);
}

/**
 * Open cash drawer
 */
export async function openCashDrawer(printer: {
  type: 'usb' | 'network';
  device?: USBDevice;
  address?: string;
  port?: number;
}): Promise<void> {
  const command = new Uint8Array(ESCPOS.OPEN_DRAWER);

  if (printer.type === 'usb' && printer.device) {
    await printToUSBPrinter(printer.device, command);
  } else if (printer.type === 'network' && printer.address) {
    await printToNetworkPrinter(printer.address, printer.port || 9100, command);
  }
}

/**
 * Stripe Terminal Integration Service
 * 
 * Provides integration with Stripe Terminal for hardware POS:
 * - Reader discovery and connection
 * - Payment collection
 * - Reader status management
 */

import { loadStripeTerminal, Terminal } from '@stripe/terminal-js';
import api from '@/lib/api';

// Types
interface Reader {
  id: string;
  object: 'terminal.reader';
  device_type: string;
  label: string;
  location: string | null;
  serial_number: string;
  status: 'online' | 'offline';
  ip_address?: string;
}

interface PaymentIntent {
  id: string;
  amount: number;
  currency: string;
  status: string;
}

interface TerminalConfig {
  locationId?: string;
  onConnectionStatusChange?: (status: ConnectionStatus) => void;
  onPaymentStatusChange?: (status: PaymentStatus) => void;
  onUnexpectedReaderDisconnect?: (reader: Reader) => void;
}

type ConnectionStatus = 'not_connected' | 'connecting' | 'connected';
type PaymentStatus = 'not_ready' | 'ready' | 'waiting_for_input' | 'processing';

// Singleton terminal instance
let terminal: Terminal | null = null;
let currentReader: Reader | null = null;

const API_BASE = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3005';

/**
 * Initialize Stripe Terminal
 */
export async function initializeTerminal(config: TerminalConfig = {}): Promise<Terminal> {
  if (terminal) {
    return terminal;
  }

  const stripeTerminal = await loadStripeTerminal();
  
  if (!stripeTerminal) {
    throw new Error('Failed to load Stripe Terminal SDK');
  }

  terminal = stripeTerminal.create({
    onFetchConnectionToken: fetchConnectionToken,
    onUnexpectedReaderDisconnect: (event) => {
      console.error('Reader unexpectedly disconnected:', event);
      currentReader = null;
      // The event contains error info, not the reader directly
      config.onUnexpectedReaderDisconnect?.({} as Reader);
    },
    onConnectionStatusChange: (event) => {
      console.log('Connection status:', event.status);
      config.onConnectionStatusChange?.(event.status as ConnectionStatus);
    },
    onPaymentStatusChange: (event) => {
      console.log('Payment status:', event.status);
      config.onPaymentStatusChange?.(event.status as PaymentStatus);
    },
  });

  return terminal;
}

/**
 * Fetch connection token from server
 */
async function fetchConnectionToken(): Promise<string> {
  const response = await api.post('/payments/terminal/connection-token');
  return response.data.secret;
}

/**
 * Discover available readers
 */
export async function discoverReaders(options: {
  simulated?: boolean;
  locationId?: string;
} = {}): Promise<Reader[]> {
  if (!terminal) {
    throw new Error('Terminal not initialized');
  }

  const config: any = {
    simulated: options.simulated || false,
  };

  if (options.locationId) {
    config.location = options.locationId;
  }

  const result = await terminal.discoverReaders(config);

  if ('error' in result) {
    throw new Error(result.error.message);
  }

  return result.discoveredReaders as Reader[];
}

/**
 * Connect to a reader
 */
export async function connectReader(reader: Reader): Promise<Reader> {
  if (!terminal) {
    throw new Error('Terminal not initialized');
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const result = await terminal.connectReader(reader as any);

  if ('error' in result) {
    throw new Error(result.error.message);
  }

  currentReader = result.reader as Reader;
  return currentReader;
}

/**
 * Disconnect from current reader
 */
export async function disconnectReader(): Promise<void> {
  if (!terminal) {
    throw new Error('Terminal not initialized');
  }

  await terminal.disconnectReader();
  currentReader = null;
}

/**
 * Get currently connected reader
 */
export function getConnectedReader(): Reader | null {
  return currentReader;
}

/**
 * Create a payment intent on the server
 */
async function createPaymentIntent(options: {
  amount: number;
  currency?: string;
  orderId?: string;
  metadata?: Record<string, string>;
}): Promise<{ clientSecret: string; paymentIntentId: string }> {
  const response = await api.post('/payments/terminal/payment-intent', {
    amount: options.amount,
    currency: options.currency || 'usd',
    orderId: options.orderId,
    metadata: options.metadata,
  });

  return response.data;
}

/**
 * Collect payment with terminal
 */
export async function collectPayment(options: {
  amount: number;
  currency?: string;
  orderId?: string;
  metadata?: Record<string, string>;
  skipTipping?: boolean;
}): Promise<PaymentIntent> {
  if (!terminal || !currentReader) {
    throw new Error('No reader connected');
  }

  // Create payment intent on server
  const { clientSecret, paymentIntentId } = await createPaymentIntent({
    amount: options.amount,
    currency: options.currency,
    orderId: options.orderId,
    metadata: options.metadata,
  });

  // Collect payment method
  const collectConfig: any = {
    skip_tipping: options.skipTipping ?? false,
  };

  const collectResult = await terminal.collectPaymentMethod(clientSecret, collectConfig);

  if ('error' in collectResult) {
    throw new Error(collectResult.error.message);
  }

  // Process payment
  const processResult = await terminal.processPayment(collectResult.paymentIntent);

  if ('error' in processResult) {
    throw new Error(processResult.error.message);
  }

  // Capture the payment on server
  await capturePayment(paymentIntentId);

  return processResult.paymentIntent as PaymentIntent;
}

/**
 * Capture payment on server
 */
async function capturePayment(paymentIntentId: string): Promise<void> {
  await api.post('/payments/terminal/capture', { paymentIntentId });
}

/**
 * Cancel current payment collection
 */
export async function cancelPayment(): Promise<void> {
  if (!terminal) {
    throw new Error('Terminal not initialized');
  }

  await terminal.cancelCollectPaymentMethod();
}

/**
 * Set reader display message
