}

/**
 * PWA Service Worker Registration and Push Notification Utilities
 */

// Check if service workers are supported
export function isPWASupported(): boolean {
  return 'serviceWorker' in navigator;
}

// Check if push notifications are supported
export function isPushSupported(): boolean {
  return 'PushManager' in window;
}

// Register service worker (disabled in development to prevent stale JS caching)
export async function registerServiceWorker(): Promise<ServiceWorkerRegistration | null> {
  if (!isPWASupported()) {
    console.log('[PWA] Service workers not supported');
    return null;
  }

  // In development, unregister any existing service worker to prevent stale cache
  if (process.env.NODE_ENV === 'development') {
    const registrations = await navigator.serviceWorker.getRegistrations();
    for (const reg of registrations) {
      await reg.unregister();
      console.log('[PWA] Unregistered service worker in dev mode');
    }
    // Also clear all caches
    const cacheNames = await caches.keys();
    for (const name of cacheNames) {
      await caches.delete(name);
    }
    return null;
  }

  try {
    const registration = await navigator.serviceWorker.register('/sw.js', {
      scope: '/',
    });

    console.log('[PWA] Service worker registered:', registration.scope);

    // Check for updates
    registration.addEventListener('updatefound', () => {
      const newWorker = registration.installing;
      if (newWorker) {
        newWorker.addEventListener('statechange', () => {
          if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
            // New content available, prompt user to refresh
            console.log('[PWA] New content available, refresh to update');
            dispatchEvent(new CustomEvent('pwa-update-available'));
          }
        });
      }
    });

    return registration;
  } catch (error) {
    console.error('[PWA] Service worker registration failed:', error);
    return null;
  }
}

// Unregister service worker
export async function unregisterServiceWorker(): Promise<boolean> {
  if (!isPWASupported()) return false;

  try {
    const registration = await navigator.serviceWorker.ready;
    return await registration.unregister();
  } catch (error) {
    console.error('[PWA] Failed to unregister service worker:', error);
    return false;
  }
}

// Request push notification permission
export async function requestNotificationPermission(): Promise<NotificationPermission> {
  if (!('Notification' in window)) {
    console.log('[PWA] Notifications not supported');
    return 'denied';
  }

  if (Notification.permission === 'granted') {
    return 'granted';
  }

  if (Notification.permission !== 'denied') {
    const permission = await Notification.requestPermission();
    return permission;
  }

  return Notification.permission;
}

// Subscribe to push notifications
export async function subscribeToPush(vapidPublicKey: string): Promise<PushSubscription | null> {
  if (!isPushSupported()) {
    console.log('[PWA] Push notifications not supported');
    return null;
  }

  try {
    const registration = await navigator.serviceWorker.ready;
    
    // Check existing subscription
    let subscription = await registration.pushManager.getSubscription();
    
    if (subscription) {
      return subscription;
    }

    // Create new subscription
    subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(vapidPublicKey),
    });

    console.log('[PWA] Push subscription created:', subscription.endpoint);
    return subscription;
  } catch (error) {
    console.error('[PWA] Failed to subscribe to push:', error);
    return null;
  }
}

// Unsubscribe from push notifications
export async function unsubscribeFromPush(): Promise<boolean> {
  if (!isPushSupported()) return false;

  try {
    const registration = await navigator.serviceWorker.ready;
    const subscription = await registration.pushManager.getSubscription();
    
    if (subscription) {
      await subscription.unsubscribe();
      return true;
    }
    
    return false;
  } catch (error) {
    console.error('[PWA] Failed to unsubscribe from push:', error);
    return false;
  }
}

// Get current push subscription
export async function getPushSubscription(): Promise<PushSubscription | null> {
  if (!isPushSupported()) return null;

  try {
    const registration = await navigator.serviceWorker.ready;
    return await registration.pushManager.getSubscription();
  } catch (error) {
    console.error('[PWA] Failed to get push subscription:', error);
    return null;
  }
}

// Helper to convert VAPID key to Uint8Array
function urlBase64ToUint8Array(base64String: string): Uint8Array<ArrayBuffer> {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding)
    .replace(/-/g, '+')
    .replace(/_/g, '/');

  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);

  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  
  return outputArray as Uint8Array<ArrayBuffer>;
}

// Check if app is installed (in standalone mode)
export function isAppInstalled(): boolean {
  // Check if running in standalone mode
  if (window.matchMedia('(display-mode: standalone)').matches) {
    return true;
  }
  
  // iOS Safari check
  if ((navigator as any).standalone === true) {
    return true;
  }
  
  return false;
}

// PWA install prompt handling
let deferredPrompt: any = null;

export function setupInstallPrompt(): void {
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    dispatchEvent(new CustomEvent('pwa-install-available'));
  });

  window.addEventListener('appinstalled', () => {
    deferredPrompt = null;
    console.log('[PWA] App installed');
    dispatchEvent(new CustomEvent('pwa-installed'));
  });
}

export function canInstall(): boolean {
  return deferredPrompt !== null;
}

export async function promptInstall(): Promise<boolean> {
  if (!deferredPrompt) {
    return false;
  }

  deferredPrompt.prompt();
  const { outcome } = await deferredPrompt.userChoice;
  deferredPrompt = null;
  
  return outcome === 'accepted';
}

// Show local notification (for testing or app-triggered notifications)
export async function showNotification(
  title: string,
  options?: NotificationOptions
): Promise<void> {
  if (Notification.permission !== 'granted') {
    console.log('[PWA] Notification permission not granted');
    return;
  }

  const registration = await navigator.serviceWorker.ready;
  await registration.showNotification(title, {
    icon: '/icons/icon-192x192.png',
    badge: '/icons/icon-72x72.png',
    ...options,
  });
}

'use client';

import { useEffect, useState, useRef, useCallback } from 'react';
import { io, Socket } from 'socket.io-client';
import { socketLogger } from './logger';

// Type definitions for socket events
interface OrderStatusUpdate {
  orderId: string;
  status: string;
  previousStatus?: string;
  updatedAt: string;
  updatedBy?: string;
}

interface NewOrderNotification {
  orderId: string;
  moduleId: string;
  customerName?: string;
  totalAmount: number;
  items: number;
  createdAt: string;
}

type OrderUpdateCallback = (data: OrderStatusUpdate) => void;
type NewOrderCallback = (data: NewOrderNotification) => void;

// SOCKET_URL should NOT include /api
const SOCKET_URL = process.env.NEXT_PUBLIC_SOCKET_URL || 'http://localhost:3005';

// Ensure we don't have /api suffix for socket connection
const cleanSocketUrl = SOCKET_URL.replace(/\/api\/?$/, '');

// Singleton socket instance to prevent multiple connections
let globalSocket: Socket | null = null;
let socketRefCount = 0;
let heartbeatInterval: NodeJS.Timeout | null = null;

function getAuthToken(): string | null {
  if (typeof window === 'undefined') return null;
  return localStorage.getItem('accessToken');
}

function createSocket(): Socket {
  const token = getAuthToken();
  
  const socket = io(cleanSocketUrl, {
    transports: ['websocket', 'polling'],
    reconnection: true,
    reconnectionAttempts: Infinity,
    reconnectionDelay: 1000,
    reconnectionDelayMax: 10000,
    timeout: 120000,           // Match server pingTimeout (2 minutes)
    forceNew: false,           // Reuse existing connection
    multiplex: true,           // Allow connection sharing
    autoConnect: true,
    auth: token ? { token } : undefined,
    // Buffer events when disconnected
    retries: 3,
  });

  // Setup heartbeat to keep connection alive
  socket.on('connect', () => {
    // Clear any existing heartbeat
    if (heartbeatInterval) {
      clearInterval(heartbeatInterval);
    }
    // Send heartbeat every 30 seconds
    heartbeatInterval = setInterval(() => {
      if (socket.connected) {
        socket.emit('heartbeat');
      }
    }, 30000);
  });

  socket.on('disconnect', () => {
    if (heartbeatInterval) {
      clearInterval(heartbeatInterval);
      heartbeatInterval = null;
    }
  });

  return socket;
}

interface UseSocketReturn {
  socket: Socket | null;
  isConnected: boolean;
  joinRoom: (room: string) => void;
  leaveRoom: (room: string) => void;
  reconnect: () => void;
}

export function useSocket(): UseSocketReturn {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const mountedRef = useRef(true);

  const reconnect = useCallback(() => {
    if (globalSocket) {
      globalSocket.disconnect();
      globalSocket.connect();
    }
  }, []);

  useEffect(() => {
    mountedRef.current = true;
    
    // Use singleton pattern - create or reuse global socket
    if (!globalSocket || globalSocket.disconnected) {
      globalSocket = createSocket();
    }
    
    socketRefCount++;
    const socketInstance = globalSocket;

    const handleConnect = () => {
      if (mountedRef.current) {
        setIsConnected(true);
        socketLogger.info('Connected', socketInstance.id);
      }
    };

    const handleDisconnect = (reason: string) => {
      if (mountedRef.current) {
        setIsConnected(false);
        socketLogger.info('Disconnected', reason);
      }
      // Handle specific disconnect reasons
      if (reason === 'io server disconnect') {
        // Server forcefully disconnected - reconnect
        setTimeout(() => socketInstance.connect(), 1000);
      } else if (reason === 'transport close' || reason === 'transport error') {
        // Network issue - socket.io will auto-reconnect
        socketLogger.debug('Transport issue, auto-reconnecting...');
      } else if (reason === 'ping timeout') {
        // Ping timeout - try to reconnect
        socketLogger.debug('Ping timeout, reconnecting...');
        setTimeout(() => socketInstance.connect(), 2000);
      }
    };

    const handleConnectError = (error: Error) => {
      socketLogger.warn('Connection error', error.message);
      // If auth error, try reconnecting without token
      if (error.message.includes('auth') || error.message.includes('unauthorized')) {
        socketLogger.debug('Auth error, reconnecting...');
      }
    };

    const handleReconnect = (attemptNumber: number) => {
      socketLogger.info(`Reconnected after ${attemptNumber} attempts`);
      // Re-authenticate on reconnect
      const token = getAuthToken();
      if (token && socketInstance.auth) {
        (socketInstance.auth as { token?: string }).token = token;
      }
    };

    const handleReconnectAttempt = (attemptNumber: number) => {
      socketLogger.debug(`Reconnect attempt: ${attemptNumber}`);
    };

    socketInstance.on('connect', handleConnect);
    socketInstance.on('disconnect', handleDisconnect);
    socketInstance.on('connect_error', handleConnectError);
    socketInstance.io.on('reconnect', handleReconnect);
    socketInstance.io.on('reconnect_attempt', handleReconnectAttempt);

    // Set initial state if already connected
    if (socketInstance.connected) {
      setIsConnected(true);
    }

    setSocket(socketInstance);

    return () => {
      mountedRef.current = false;
      socketRefCount--;
      
      socketInstance.off('connect', handleConnect);
      socketInstance.off('disconnect', handleDisconnect);
      socketInstance.off('connect_error', handleConnectError);
      socketInstance.io.off('reconnect', handleReconnect);
      socketInstance.io.off('reconnect_attempt', handleReconnectAttempt);
      
      // Only disconnect when no components are using the socket
      if (socketRefCount === 0 && globalSocket) {
        if (heartbeatInterval) {
          clearInterval(heartbeatInterval);
          heartbeatInterval = null;
        }
        globalSocket.disconnect();
        globalSocket = null;
      }
    };
  }, []);

  const joinRoom = useCallback((room: string) => {
    socket?.emit('join-room', room, (success: boolean) => {
      if (success) {
        socketLogger.debug(`Joined room: ${room}`);
      }
    });
  }, [socket]);

  const leaveRoom = useCallback((room: string) => {
    socket?.emit('leave-room', room);
