  async sendBetaNewsletter(
    subject: string,
    content: string,
    testers?: string[]
  ): Promise<void> {
    const query = testers
      ? this.supabase
          .from('beta_testers')
          .select('email, name')
          .in('id', testers)
          .eq('status', 'active')
      : this.supabase
          .from('beta_testers')
          .select('email, name')
          .eq('status', 'active');

    const { data: recipients } = await query;

    for (const recipient of recipients || []) {
      // Send personalized email
      const sgMail = require('@sendgrid/mail');
      await sgMail.send({
        to: recipient.email,
        from: process.env.SENDGRID_FROM_EMAIL,
